\title{
Work in Progress:
Middleware-Transparent Callback Enforcement in Commoditized \\Component-Oriented Real-time Systems
}

\author{
  Takahiro Ishikawa-Aso$^{\dagger\ddagger}$,
  Atsushi Yano$^{*\ddagger}$,
  Takuya Azumi$^{*}$,
  Shinpei Kato$^{\dagger}$
  \\
