	Denote $w:=(x,z,y)$, $w_k:=(x_k,z_k,y_k)$, and define
	\begin{align}\label{Grd}
		F_{s_k}(w;x_k,y_k,\rho_k,\delta_k):=	\begin{bmatrix}
			\rho_k(x-x_k)+J^r_{s_k}(x)^Tz-J^c_{s_k}(x)^Ty\\
			r(x)-z\\
			c(x)+\delta_k (y-y_k)
		\end{bmatrix},
	\end{align}
	where $J^r_{s_k}(x)$ and $J^c_{s_k}(x)$ are defined by (\ref{JArd}) and (\ref{JBrd}) with $\gamma_k$.
One can apply Newton-like method to
\begin{align}\label{newton}
	F_{s_k}(w;x_k,y_k,\rho_k,\delta_k)=0
\end{align}
sequentially to find an approximate KKT point.
Let $T_{s_k}$ be an approximation of the Jacobian matrix of $F_{s_k}(w;x_k,y_k,\rho_k,\delta_k)$ at $w_k$.
 Denote $J^r_{s_k}:=J^r_{s_k}(x_k)$, $J^c_{s_k}:=J^c_{s_k}(x_k)$  and $F_{s_k}:=F_{s_k}(w_k;x_k,y_k,\rho_k,\delta_k)$.
	%$r_k:=r(x_k)$, %$c_k:=c(x_k)$
%	\begin{align}\label{Gkrd}
%		F_{s_k}(w_k):=F_{s_k}(w_k;x_k,y_k,\rho_k,\delta_k)=
%		\begin{bmatrix}
%			(J^r_{s_k})^Tz_k-(J^c_{s_k})^Ty_k\\
%			r(x_k)-z_k\\
%			c(x_k)
%		\end{bmatrix}.
%	\end{align}
Then solving the linear system
\begin{align}
T_{s_k} d_w=-F_{s_k}
\end{align}
can give an inexact solution of \eqref{newton}.
In practice, one can adjust $d_y$ to $-d_y$ to make the coefficient matrix of the linear system symmetric so that a symmetric indefinite factorization can be used (cf. \cite{MA57}).
That is, an inexact Newton step $d_{w_k}=(d_{x_k}, d_{	z_k}, d_{y_k} )$ is computed by solving the system
	%$T_k\Delta w_k=-F_{s_k}$
	% which can be written as
	\begin{align} \label{sysrd}
		\begin{bmatrix}
			H_{s_k}+\rho_k I & (J^r_{s_k})^T & (J^c_{s_k})^T \\
			J^r_{s_k} & -I & 0\\
			J^c_{s_k} & 0 & -\delta_k I
		\end{bmatrix}\begin{bmatrix}
			d_{x}  \\
			d_{	z}\\
			-d_{y}
		\end{bmatrix}
		=\begin{bmatrix}
			-(J^r_{s_k})^Tz_k+(J^c_{s_k})^Ty_k \\
			z_k-r(x_k) \\
			-c(x_k)
		\end{bmatrix},
	\end{align}
where $H_{s_k}$ is a symmetric approximation of $H(x,z_k,y_k)$ at $x_k$ with
	\begin{align}\label{Hrd}
		H(x,z,y)=\sum_{i=1}^{p} z_i \nabla^2 r_i(x)
		-\sum_{i=1}^{m} y_i \nabla^2
		c_i(x).
	\end{align}

Define the merit function
\begin{align*}
		\|F_{s_k}\|_*=\|(J^r_{s_k})^T z_k-(J^c_{s_k})^T y_k\|+\|z_k-r(x_k)\|+	\|c(x_k)\|.
\end{align*}
If the trial step $d_{w_k}$	can lead to a sufficient decrease, i.e.,
\begin{align}\label{innerstoprd}
		\|F_{s_{k+1}}\|_* \leq \theta\|F_{s_k}\|_*+\epsilon_k,
\end{align}
where $0<\theta<1$, $0< \epsilon_k\downarrow 0$,
we accept it and  take $w_{k+1}=w_k+d_{w_k}$.
Otherwise we go to inner iterations to minimize the augmented Lagrangian function so that a trial step can be obtained to satisfy \eqref{innerstoprd}. That is, we solve
\begin{align}\label{alrd}
	\min_x\	\phi_k(x;\delta)=\frac{1}{2}\|r(x)\|^2-y_k^Tc(x)+
		\frac{1}{2}\delta^{-1}\|c(x)\|^2,
\end{align}
where $\delta$ may be updated in inner iterations.


Actually, \eqref{alrd} is equivalent to the nonlinear least square problem
	\begin{align}\label{inLS}
		\min_x\ \frac{1}{2}\|\Phi_k(x;\delta)\|^2:=\frac{1}{2}
		\left\|\begin{bmatrix}
			r(x)\\
			\delta^{-1/2}(c(x)-\delta y_k)
		\end{bmatrix}\right\|^2.
	\end{align}
It can be solved by a derivative-free LM method.
Let
\begin{align*}
		J^{\Phi}_s(x;\delta)=\begin{bmatrix}
			J^r_s(x)\\
			\delta^{-1/2}J^c_s(x)
		\end{bmatrix}
	\end{align*}
and
\begin{align}\label{phik}
\nabla\phi_{k,s}(x;\delta)=J^r_{s}(x)^Tr(x)-J^c_{s}(x)^Ty_k +\delta^{-1} J^c_{s}(x)^T c(x)
\end{align}
be the approximate Jacobian matrix of $\Phi_k(x;\delta)$ and approximate gradient of $\phi_k(x;\delta)$ with respect to $x$, respectively.
At the $j$-th inner iteration of the $k$-th outer iteration, we denote
$$
J_{s_{k,j}} := J^{\Phi}_s(x_{k,j};\delta_{k,j}),
\quad \nabla \phi_{s_{k,j}}:= \nabla \phi_{k,s}(x_{k,j};\delta_{k,j})
$$
for brevity, and solve
\begin{align}\label{LMstep}
(J_{s_{k,j}}^TJ_{s_{k,j}}+\lambda_{k,j} \|\nabla \phi_{s_{k,j}}\| I)d_x=- \nabla \phi_{s_{k,j}}
\end{align}
to obtain the step $d_{ x_{k,j}}$, where $\lambda_{k,j}$ is the parameter updated from iteration to iteration.
We may use two-step QR factorization such as that of \cite{Sun2006} to find the solution of \eqref{LMstep},
which can avoid the calculation of $J_{s_{k,j}}^TJ_{s_{k,j}}$.
Define the ratio
\begin{align}\label{LMratio}
\zeta_{k,j}=\frac{\|\Phi_k(x_{k,j};\delta_{k,j})\|^2-\|\Phi_k(x_{k,j}+d_{ x_{k,j}};\delta_{k,j})\|^2}
				{\|\Phi_k(x_{k,j};\delta_{k,j})\|^2-\|\Phi_k(x_{k,j};
					\delta_{k,j})+J_{s_{k,j}}d_{ x_{k,j}}\|^2}.
\end{align}
It plays an important role in deciding whether $d_{ x_{k,j}}$ is acceptable and how to update $\lambda_{k,j}$.
The parameter $\delta_{k,j}$ will be decreased if
the relatively sufficient decrease on $\|\nabla \phi_{k,s}(x ;\delta)\|$ is achieved
but the constraint violation decrease does not meet the requirement.

The derivative-free regularization algorithm for solving \eqref{prob} is presented as follows.




