\section{Global convergence of the algorithm}\label{sec3}
In this section, we study the global convergence of Algorithm \ref{alg1}.	
It is shown that Algorithm \ref{alg1} either finds an approximate KKT point with high probability
or converges to a stationary point of the constraints almost surely.

Note that the Jacobian approximations are built in some random fashion,
which implies the randomness of the iterates, the smoothing parameters, etc.
We use uppercase letters to represent random quantities, such as $X_k$, $J^r_{S_k}(X_k)$,  etc.,
and use lowercase letters to represent their realizations, such as $x_k$,
$J^r_{s_k}(x_k)$ etc.
Denote by $\mathcal{F}_{k}$  the $\sigma$-algebra generated by all randomness in
iteration $k$ and all previous iterations.

We first derive the bounds for the difference between the Jacobian matrix and the expectation of its  approximation and the variance of the approximate Jacobian, respectively.
We make the following assumption.

\begin{assumption}\label{ass1rd}
(i) $J^r(x)$ and $J^c(x)$ are Lipchitz continuous, i.e., there exist $\kappa_{ljr}, \kappa_{ljc}>0 $  such that for all $x,y \in\mathbb{R}^n$,
\begin{align}
			\|J^r(x)-J^r(y)\| &\leq \kappa_{ljr} \|x-y\|,  \label{lipaed}\\
			\|J^c(x)-J^c(y)\| &\leq \kappa_{ljc} \|x-y\|. \label{lipbed}
\end{align}


(ii) $r(x)$ and $c(x)$ are Lipschitz continuous, i.e., there exist $\kappa_{lr}, \kappa_{lc}>0$ such that for all $x,y \in		\mathbb{R}^n$,
\begin{align}\label{liprrd}
			\|r(x)-r(y)\|& \leq \kappa_{lr} \|x-y\|, \\
			\|c(x)-c(y)\|& \leq \kappa_{lc} \|x-y\|.
\end{align}

 \end{assumption}	

	\eqref{lipaed} implies that there exists $\kappa_{lgr}>0 $ such that for all $x,y \in\mathbb{R}^n$, 		\begin{align}\label{lrird}
			\|\nabla r_i(x)- \nabla r_i(y)\| \leq \kappa_{lgr} \|x-y\|, \quad i=1,\ldots,p.
		\end{align}
\eqref{lipbed} implies that there exists 	$\kappa_{lgc}>0 $ such that for all $x,y \in\mathbb{R}^n$,
		\begin{align}\label{lcird}
			\|\nabla c_i(x)- \nabla c_i(y)\| \leq \kappa_{lgc}\|x-y\|,\quad i=1,\ldots,m.
		\end{align}


	%\begin{assumption}\label{ass5}			
	%			\begin{align}\label{phinf}
		%				\inf_j	\phi_k(x_{k,j};\delta_{k,j})>-\infty,
		%				\end{align}
	%\end{assumption}	

	%{\color{red} indexes in  alg2orithm are not changed yet}




	%The following Lemma provide  error bound for the
	%derivative-free estimators (\ref{JArd}) and (\ref{JBrd}).


\begin{lemma}\label{lemAB}
Suppose that Assumption \ref{ass1rd}(i) holds. Then there exists $d>0$ such that
\begin{align}
			\|\mathbb{E}_u [J^r_{S}(x)]-J^r(x)\| &\leq\frac{d\sqrt{p}n	\kappa_{lgr}}{n+1}	\gamma,		\label{lem1A}\\
			\|\mathbb{E}_u [J^c_{S}(x)]-J^c(x)\| &\leq	\frac{d\sqrt{m}n\kappa_{lgc}}{n+1}\gamma,		\label{lem1B}
\end{align}
and
\begin{align}
			&\mathbb{E}_u \left[ \left\|J^r_{S}(x)-\mathbb{E}_u
			[J^r_{S}(x)] 	\right\|^2\right] \leq  \frac{d^2p n\kappa_{lgr}^2}{4}\gamma^2, \label{lem1varA}\\
			& \mathbb{E}_u \left[ \left\|J^c_{S}(x)-\mathbb{E}_u
			[J^c_{S}(x)] 	\right\|^2\right] \leq  \frac{d^2m n\kappa_{lgc}^2}{4}\gamma^2. \label{lem1varB}
\end{align}
\end{lemma}

\begin{proof}
		By the equivalence of matrix norms, there exists  $d>0$ such that
		\begin{align}
			&\|\mathbb{E}_u [J^r_{S}(x)]-J^r(x)\| \leq d \| \mathbb{E}_u[J^r_{S}(x)]-J^r(x)\|_F, \label{normeq} \\
	%		&\|\mathbb{E}_u [J^c_{S}(x)]-J^c(x)\| \leq d \|	\mathbb{E}_u[J^c_{S}(x)]-J^c(x)\|_F, \label{normeq1}
		&	\left\|J^r_{S}(x)-\mathbb{E}_u 	[J^r_{S}(x)] \right\| \leq d \left\|J^r_{S}(x)-\mathbb{E}_u [J^r_{S}(x)] 	\right\|_F. \label{normeq2}
		%&	\left\|J^c_{S}(x)-\mathbb{E}_u 	[J^c_{S}(x)] 	\right\| \leq d \left\|J^c_{S}(x)-\mathbb{E}_u [J^c_{S}(x)] 	\right\|_F.
		\end{align}
		It follows from \cite{wang} that
		\begin{equation*}
			\|\mathbb{E}_u [\nabla r_{S,i}(x)] - \nabla r_i(x)\| \leq
			\frac{n	\kappa_{lgr}}{n+1}\gamma.
			%\|\mathbb{E}_u [\nabla c_{S,i}(x)] - \nabla c_i(x)\| \leq
%			\frac{n	\kappa_{lgc}}{n+1} \gamma.
		\end{equation*}
Hence,
\begin{align*}
\| \mathbb{E}_u[J^r_{S}(x)]-J^r(x)\|_F^2&=\sum_{i=1}^{p}\|\mathbb{E}_u
[\nabla r_{S,i}(x)] - \nabla r_i(x)\|^2 \leq p\left(\frac{n	\kappa_{lgr}}{n+1}\right)^2 \gamma^2.
%\| \mathbb{E}_u[J^c_{S}(x)]-J^c(x)\|_F^2
%&=\sum_{i=1}^{m}\|\mathbb{E}_u	[\nabla c_{S,i}(x)] - \nabla c_i(x)\|^2 \leq m\left(\frac{n	\kappa_{lgc}}{n+1}\right)^2\gamma^2.
		\end{align*}
This, together with (\ref{normeq}), yields (\ref{lem1A}).


		On the other hand, it holds that for $i=1,\ldots,p$,
		\begin{align}\label{Ers}
			\mathbb{E}_u\left[ \left\|\nabla r_{S,i}(x)-\mathbb{E}_u
			[\nabla r_{S,i}(x)] 	\right\|^2\right] =\mathbb{E}_u \left[ \|\nabla r_{S,i}(x)
			\|^2\right] -\|\mathbb{E}_u [\nabla r_{S,i}(x)] \|^2.
		\end{align}
		By the Taylor expansion,
		\begin{align*}
			\frac{r_i(x+\gamma u_j)-r_i(x)}{\gamma} = \nabla
			r_i(x)^T
			u_j+ \frac{1}{2} \gamma u_j^T r''_i(\xi_i)u_j,
		\end{align*}
		where $\xi_i\in [x,x+\gamma u_j]$.
		Denote $\beta_j=u_j^T r''_i(\xi_i) u_j, j=1,\ldots, n$.
By (\ref{lrird}),
		\begin{align}\label{K}
			|\beta_j|\leq \|u_j\|^2\|r''_i(\xi_i) \| \leq \kappa_{lgr}.
		\end{align}
 Since $u_j^Tu_j=1$ and $u_j^Tu_k=0$ for all $j\not=k, j,k=1,\ldots,n$, and
		\begin{equation}\label{uu}
			\mathbb{E}_u [u_j u_j^T]=\frac{1}{n}I,
		\end{equation}
(cf. \cite{wang}),   by (\ref{nabrrd}) and (\ref{K}),
		\begin{align}\label{tem1}
			&\mathbb{E}_u \left[ \| \nabla r_{S,i}(x)	\|^2\right]
			=\mathbb{E}_u \left[\left\| \sum_{j=1}^n \frac{r_i(x+\gamma u_j)-r_i(x)}{\gamma} u_j \right\|^2\right] \nonumber\\
			&= \mathbb{E}_u \left[\left\| \sum_{j=1}^n u_j^T \nabla r_i(x)	u_j+ \frac{\gamma}{2}  \sum_{j=1}^n   \beta_j  u_j
			\right\|^2\right] \nonumber\\
& =\sum_{j=1}^n\mathbb{E}_u \left[ \nabla
			r_i(x)^T u_j u_j^T \nabla r_i(x) \right] + \gamma
			\sum_{j=1}^n  \mathbb{E}_u \left[ \nabla r_i(x)^T u_j \beta_j
			\right]  +
			\frac{\gamma^2}{4}  \sum_{j=1}^n \mathbb{E}_u \left[ \beta_j^2
			\right]
			\nonumber\\
			& \leq \|\nabla	r_i(x)\|^2 +\gamma
			\sum_{j=1}^n  \mathbb{E}_u \left[ \nabla r_i(x)^T u_j \beta_j
			\right]  +\frac{ n \kappa_{lgr}^2}{4}\gamma^2.
		\end{align}	


		Now we consider $\|\mathbb{E}_u [\nabla r_{S,i}(x) ] \|^2$. By	\eqref{uu},
		\begin{align}\label{tem2}
			&	\|\mathbb{E}_u [\nabla r_{S,i}(x) ] \|^2 = \left\|
			\mathbb{E}_u\left[\sum_{j=1}^n\frac{r_i(x+\gamma u_j)-r_i(x)}{\gamma} u_j   \right]	\right\|^2  \nonumber \\
			&=\left\| \mathbb{E}_u \left[ \sum_{j=1}^n	\left(u_j^T	\nabla r_i(x)\right) u_j\right] + \frac{\gamma}{2}
			\sum_{j=1}^n\mathbb{E}_u\left[ \beta_j u_j \right] \right\|^2\nonumber\\
			&=\left\|\sum_{j=1}^n \mathbb{E}_u \left[	u_ju_j^T\nabla r_i(x) \right] \right\|^2 + \gamma \left(
			\sum_{j=1}^n\mathbb{E}_u \left[  u_ju_j^T \nabla r_i(x) \right] \right)^T\left(
			\sum_{j=1}^n\mathbb{E}_u 	\left[ \beta_j u_j \right] \right)\nonumber\\
			& \quad + \frac{ \gamma^2}{4}  \left(\sum_{j=1}^n\mathbb{E}_u 	\left[ \beta_j u_j \right]	\right)^T\left(
			\sum_{j=1}^n\mathbb{E}_u 	\left[ \beta_j u_j \right]	\right)\nonumber\\
			& =  \|\nabla	r_i(x)\|^2 +\gamma\sum_{j=1}^n  \mathbb{E}_u \left[ \nabla r_i(x)^T u_j \beta_j\right] +
			\frac{\gamma^2}{4}  \left(\sum_{j=1}^n\mathbb{E}_u 	\left[ \beta_j u_j \right]\right)^T\left(			\sum_{j=1}^n\mathbb{E}_u 	\left[ \beta_j u_j \right] \right).
		\end{align}
		Combining \eqref{Ers},   (\ref{tem1}) and (\ref{tem2}), we obtain
		\begin{align}\label{varr}
			 \mathbb{E}_u\left[ \left\|\nabla r_{S,i}(x)-\mathbb{E}_u
			[\nabla r_{S,i}(x)] 	
			\right\|^2\right]
			& \leq  \frac{ n \kappa_{lgr}^2}{4}\gamma^2.
		\end{align}
		Thus by (\ref{normeq2}) and (\ref{varr}),
		\begin{align*}
			&\mathbb{E}_u\left[ \left\|J^r_{S}(x)-\mathbb{E}_u
			[J^r_{S}(x)] 	
			\right\|^2\right]
			\leq d^2 \mathbb{E}_u\left[ \left\|J^r_{S}(x)-\mathbb{E}_u
			[J^r_{S}(x)] \right\|_F^2\right] \nonumber\\
			& =d^2 \sum_{i=1}^{p} \mathbb{E}_u\left[ \left\|\nabla
			r_{S,i}(x)-\mathbb{E}_u
			[\nabla r_{S,i}(x)] 	
			\right\|^2\right] \leq \frac{ d^2 pn \kappa_{lgr}^2}{4}\gamma^2,
		\end{align*}
		which gives (\ref{lem1varA}).

	Similarly, \eqref{lem1B} and (\ref{lem1varB}) can be proved.
	\end{proof}


Next we give the bound for the difference between the gradient of the augmented Lagrangian function
and the expectation of its  approximation in inner iterations,
and the bound for the variance of the approximate gradient as well.


\begin{assumption}\label{ass2rd}
(i) The approximate Jacobian matrices  $J^r_{s_k}, J^c_{s_k}, J^r_{s_{k,j}}, J^c_{s_{k,j}}$ are bounded for all $k$ and $j$.

(ii) The function values  $r_k, c_k, r_{k,j}, c_{k,j}$ are bounded for all $k$ and $j$, i.e., there exist 	$\kappa_{br}, \kappa_{bc}>0$ such that
\begin{align}\label{rckbounded}
	\|r(x_k) \|\leq \kappa_{br}, \ \ \|c(x_k)\| \leq \kappa_{bc},\ \
\|r(x_{k,j})  \|\leq \kappa_{br}, \ \  \|c(x_{k,j})\| \leq \kappa_{bc}.
\end{align}

(iii) The multipliers $z_k, y_k$ are bounded, i.e., there exist
$\kappa_{bz}, \kappa_{by}>0$		such that
$$\|z_k\| \leq \kappa_{bz}, \ \
\|y_k\| \leq \kappa_{by}.$$

(iv) $T_{s_k}$ are non-singular for all $k$.

(v) $\epsilon_k\downarrow 0$.

\end{assumption}



Note that the non-singularity of $T_{s_k}$  can be guaranteed by setting appropriate $\rho_k$.	

\begin{lemma}\label{lemphi}
Suppose that Assumptions \ref{ass1rd}(i) and \ref{ass2rd}(ii),(iii)  hold.
Then we have
\begin{align}
&	\| \mathbb{E}_{u}[\nabla\phi_{S_{k,j}}(x_{k,j};\delta )]-\nabla	\phi_{k}(x_{k,j};\delta)\| \nonumber\\
& \leq \left(\frac{d\sqrt{p}n\kappa_{lgr}\kappa_{br}}{n+1}+\frac{d\sqrt{m}n\kappa_{lgc}}{n+1}(\|y_k\|+\delta^{-1} \kappa_{bc})	\right) \gamma_{k,j} := \kappa_{\phi_k,1}\gamma_{k,j},
			\label{phi1bound} \\
&\mathbb{E}_u\left[ \left\|\nabla\phi_{S_{k,j}}(x_{k,j};\delta)-\mathbb{E}_u
			[\nabla	\phi_{S_{k,j}}(x_{k,j};\delta )] 	\right\|^2\right] \nonumber\\
&\leq3\left( \frac{d^2p n\kappa_{lgr}^2\kappa_{br}^2}{4}+
			\frac{d^2m n\kappa_{lgc}^2}{4}(\|y_k\|^2+\delta^{-1}\kappa_{bc}^2)\right) \gamma_{k,j}^2 := \kappa_{\phi_k,2}\gamma_{k,j}^2.
			\label{phi2bound}
\end{align}

\end{lemma}

\begin{proof}
By the definition of $\phi_k(x;\delta)$,
		\begin{align*}
			\nabla\phi_{S_{k,j}}(x_{k,j};\delta)&
			=(J^r_{S_{k,j}})^Tr(x_{k,j})-(J^c_{S_{k,j}})^Ty_k+\delta^{-1}
			(J^c_{S_{k,j}})^Tc(x_{k,j}),\\
			\nabla\phi_{k}(x_{k,j};\delta)&=
			(J^r_{k,j})^Tr(x_{k,j})-(J^c_{k,j})^Ty_k+\delta^{-1}(J^c_{k,j})^T
			c(x_{k,j}).
		\end{align*}
By Assumption \ref{ass2rd}(ii)--(iii)  and Lemma \ref{lemAB},
		\begin{align*}
			&	\| \mathbb{E}_u[\nabla	\phi_{k,S_{k,j}}(x_{k,j};\delta)]-\nabla	\phi_{k}(x_{k,j};\delta)\| \\
			& = \left \|\left(  \mathbb{E}_u [J^r_{S_{k,j}}]-J^r_{k,j}\right)
			^Tr(x_{k,j})-\left(  \mathbb{E}_u [J^c_{S_{k,j}}]-J^c_{k,j}\right)^Ty_k+\delta^{-1}
			\left(  \mathbb{E}_u [J^c_{S_{k,j}}]-J^c_{k,j}\right)^Tc(x_{k,j})\right\|\\
			& \leq \left\| \mathbb{E}_u [J^r_{S_{k,j}}]-J^r_{k,j}\right\|\|r(x_{k,j})\|+
			\left\|\mathbb{E}_u [J^c_{S_{k,j}}]-J^c_{k,j}\right\|\|y_k\|+ \delta^{-1}
			\left\|\mathbb{E}_u [J^c_{S_{k,j}}]-J^c_{k,j}\right\|\|c(x_{k,j})\| \\
			&\leq \left(\frac{d\sqrt{p}n\kappa_{lgr}\kappa_{br}}{n+1}+\frac{d\sqrt{m}n\kappa_{lgc}}{n+1}(\|y_k\|+\delta^{-1} \kappa_{bc})\right)		\gamma_{k,j}.
		\end{align*}
Similarly, we have
		\begin{align*}
			&	\mathbb{E}_u\left[ \left\|\nabla
			\phi_{S_{k,j}}(x_{k,j};\delta)-\mathbb{E}_u
			[\nabla
			\phi_{S_{k,j}}(x_{k,j};\delta)] 	
			\right\|^2\right]\\
			&=\mathbb{E}_u\left[ \left\| 	\left( J^r_{S_{k,j}}-\mathbb{E}_u[
			J^r_{S_{k,j}}] \right) ^Tr(x_{k,j})-\left(
			J^c_{S_{k,j}}-\mathbb{E}_u[J^c_{S_{k,j}}]\right)
			^Ty_k+\delta^{-1}
			\left( J^c_{S_{k,j}}-\mathbb{E}_u[J^c_{S_{k,j}}]\right)^Tc(x_{k,j})
			\right\|^2\right]\\
			&\leq 3\mathbb{E}_u\left[\left\|  J^r_{S_{k,j}}-\mathbb{E}_u[
			J^r_{S_{k,j}}] \right\|^2 \kappa_{br}^2 +\left\|
			J^c_{S_{k,j}}-\mathbb{E}_u[
			J^c_{S_{k,j}}] \right\|^2 \|y_k\|^2+ \delta^{-2}\left\|
			J^c_{S_{k,j}}-\mathbb{E}_u[
			J^c_{S_{k,j}}] \right\|^2 \kappa_{bc}^2  \right]\\
			&\leq 3\left( \frac{d^2p n\kappa_{lgr}^2\kappa_{br}^2}{4}+
			\frac{d^2m n\kappa_{lgc}^2}{4}(\|y_k\|^2+\delta^{-2}\kappa_{bc}^2)\right) \gamma_{k,j}^2.
		\end{align*}	
The proof is completed.	
	\end{proof}

Based on Lemma \ref{lemphi}, we investigate the properties of Algorithm \ref{alg2} if it is called by Algorithm \ref{alg1}.
We discuss two cases: $\Delta_{k,j}$ decrease finitely many times or infinitely many times.
As Algorithm \ref{alg2} is similar to the derivative-free LM algorithm
\cite[Algorithm 1]{cx} for unconstrained nonlinear least squares problems
in the former case, we apply some of its results directly.		

\begin{lemma}\label{lembeforthem}
Suppose that Assumptions \ref{ass1rd} and \ref{ass2rd}(i)-(iii) hold for every realization of  Algorithm \ref{alg2} with fix $k$.
If $\Delta_{k,j}$ decrease finitely many times, then
\begin{align}
				\|F_{S_{k,j+1}}\|_* \leq \theta \|F_{s_k}\|_*+\epsilon_k
\end{align}
		holds for some $j$ with any probability $0<p<1$.
\end{lemma}

\begin{proof}
Denote
$$
\mathcal E_1=\{\Delta_{k,j} \ \text{decrease finitely many times}\}.
$$
If $\mathcal E_1$ happens in  Algorithm \ref{alg2} for some $k$,
then there exists $j_0$ such that $\Delta_{k,j}=\Delta_{k,j_0}$ for all $j \ge
j_0$.
So Algorithm \ref{alg2} is similar to \cite[Algorithm 1]{cx}, except the updating rule of the smoothing parameter.
In this paper, we take $\gamma_{k,j+1}=\min\{\frac{1}{2}\gamma_{k,j}, \|d_{x_{k,j}}\|\}$ for all $j\ge j_0$.
Under  Assumptions \ref{ass1rd} and \ref{ass2rd}(i),
according to the proof of  \cite[Theorem 3.2]{cx} and \cite[Remark 3.4]{cx},
$\{\nabla \phi_{S_{k,j}}(X_{k,j};\Delta_{k,j_0})\}_{j\ge j_0}$ is $\frac{1}{2}$-probabilistically
			first-order 	accurate  as defined in \cite[Definition 3.1]{cx}.
Following \cite[Theorem 4.6]{cx}, we have
\begin{equation}\label{limconverg}
\mathbb P\left( 	\liminf_{j \to \infty}\|\nabla\phi_{k}(X_{k,j};\Delta_{k,j_0})\|=0 \ \Big |\ \mathcal E_1 \right)	=1.
\end{equation}  		
Moreover, it follows from \cite[Lemma 4.3]{cx} that $\lim\limits_{j \to \infty}\lambda_{k,j}=+ \infty$. This, together with $\gamma_{k,j} \leq \|d_{x_{k,j-1}}\|\leq \frac{1}{\lambda_{j-1}}$, implies that
\begin{align}\label{gamma}
\lim_{j \to \infty}\gamma_{k,j}=0
\end{align} for any	realization  of Algorithm \ref{alg2} if $\mathcal E_1$ happens.

On the other hand, by Lemma \ref{lemphi} and multivariate Chebyshev's inequality 		\cite{Chebyshevproof}, for any $s>0$ and $j\ge j_0$,
\begin{align}\label{Chev}
\mathbb{P}\left(\left\|\nabla \phi_{S_{k,j}}(x_{k,j};\delta_{k,j_0})-\mathbb{E}_u
				[\nabla \phi_{S_{k,j}}(x_{k,j};\delta_{k,j_0})] 	
				\right\|\leq s\right)\ge 1- \frac{\kappa_{\phi_k,2}\gamma_{k,j}^2}{s^2}.
\end{align}
For any $0<p<1$, let $s=\sqrt{\frac{ \kappa_{\phi_k,2}}{1-p}}	\gamma_{k,j}$.
Then  by (\ref{phi1bound}) and \eqref{Chev},
\begin{align}\label{pgrad}
&	\mathbb{P}\left[	\left\|\nabla\phi_{S_{k,j}}(X_{k,j};\Delta_{k,j_0})-\nabla
\phi_{k}(X_{k,j};\Delta_{k,j_0})\right\|\leq \left(\kappa_{\phi_k,1}+ \sqrt{\frac{
\kappa_{\phi_k,2}}{1-p}}\right)\Gamma_{k,j} \ \bigg |\   \mathcal{F}_{k,j}, \mathcal E_1 \right] \nonumber\\
&= 	\mathbb{P}\left[	\left\|\nabla	\phi_{S_{k,j}}(x_{k,j};\delta_{k,j_0})-\nabla\phi_{k}(x_{k,j};\delta_{k,j_0})
	\right\|\leq \left(\kappa_{\phi_k,1}+ \sqrt{\frac{	\kappa_{\phi_k,2}}{1-p}}
				\right)\gamma_{k,j}  \right] \nonumber\\
&\geq \mathbb{P}\left(\left\|\nabla \phi_{S_{k,j}}(x_{k,j};\delta_{k,j_0})-\mathbb{E}_u
				[\nabla \phi_{S_{k,j}}(x_{k,j};\delta_{k,j_0})] 	
				\right\|\leq \sqrt{\frac{ \kappa_{\phi_k,2}}{1-p}}	\gamma_{k,j}\right)\nonumber\\
&\ge p
\end{align}
for all $j\ge j_0$.
			%Denote $C_{\phi_k,1}+ \sqrt{\frac{ C_{\phi_k,2}}{1-p}}$


It follows from (\ref{limconverg}) and \eqref{gamma} that  there exists $j_1\ge j_0$  such that
\begin{align}\label{t6}
\|\nabla \phi_{k}(x_{k,j_1+1};\delta_{k,j_0})\|\leq \theta\|\nabla_x L_{s_{k}}
				(x_k,y_k) \|+ \frac{1}{2}\epsilon_k- \left(\kappa_{\phi_k,1}+
				\sqrt{\frac{\kappa_{\phi_k,2}}{1-p}}\right)\gamma_{k,j}.
\end{align}
Thus by \eqref{pgrad} and (\ref{t6}),
\begin{align}\label{t7}
\left\|\nabla\phi_{S_{k,j_1+1}}(x_{k,j_1+1};\delta_{k,j_0})\right\|\leq
				\theta\|\nabla_x L_{s_{k}}		(x_k,y_k) \|+ \frac{1}{2}\epsilon_k
\end{align}
holds with probability at least $p$.

Note that
$$
\nabla\phi_{s_{k,j+1}}(x_{k,j+1};\delta_{k,j})=\nabla_xL_{s_{k,j+1}}
(x_{k,j+1},y_k-\delta_{k,j}^{-1}c(x_{k,j+1}))
$$
and $\delta_{k,j}$ does not decrease for $j\geq j_0$.
By  the line 8 of Algorithm \ref{alg2}, if \eqref{t7} happens, it holds
\begin{align}
\|c(x_{k,j_1+1})\|\leq \theta	\|c(x_{k})\|+\frac{1}{2}\epsilon_k.
\end{align}
Since $z_{k,j_1+1}=r(x_{k,j_1+1})$, $y_{k,j_1+1}= y_k-\delta_{k,j_0}^{-1}c(x_{k,j_1+1})$ due to line 9 of Algorithm \ref{alg2}, by (\ref{t7}),  we have
			\begin{align*}
				\|F_{S_{k,j_1+1}}\|_*&=\left\|\nabla
				\phi_{k,S_{k,j_1+1}}(x_{k,j_1+1};\delta)\right\| +
				\|z_{k,j_1+1}-r(x_{k,j_1+1})\| + \|c(x_{k,j_1+1})\| \\
				&\leq \theta \left( \|\nabla_x 	L_{s_{k}}(x_k,y_k) \| +
				\|z_{k}-r(x_{k})\| + \|c(x_{k})\|   \right)  + \epsilon_k  \\
				&=\theta \|F_{s_k}\|_*+\epsilon_k
			\end{align*}
			holds with   probability at least  $p$.			
		\end{proof}



Now we consider the case that $\Delta_{k,j}$ decrease infinitely many times.
It is shown that Algorithm \ref{alg2} converges to a stationary point of the merit function of the constraints with probability one. It happens in numerical experiments.

\begin{lemma}\label{lemBC}
 Suppose that Assumptions \ref{ass1rd}(i) and \ref{ass2rd}(i)-(iii)  hold for each realization of 	Algorithm \ref{alg2} with fix $k$.
 If $\Delta_{k,j}$ decrease infinitely many	times, then the random sequence $\{X_{k,j}\}$
generated  by Algorithm \ref{alg2} 	satisfies
\begin{align}\label{feasible}
		\liminf_{j\to \infty}\|J^c(X_{k,j})^T c(X_{k,j})\|=0
\end{align}
almost surely.
\end{lemma}

\begin{proof}
Denote
$$
\mathcal E_2=\{\Delta_{k,j}\  \text{decrease infinitely many times}\}.
$$
If $\mathcal E_2 $  happens  for the realization of  Algorithm \ref{alg2} for some $k$,
then the set
$$
\mathcal{J}:= \{ j\in \mathbb{N}: \delta_{k,j}<\delta_{k,j-1} \}
$$
is infinite. Due to line 8 of Algorithm \ref{alg2}, for all $j\in\mathcal{J}$,
\begin{align}\label{tb1}
&\|(J^r_{s_{k,j}})^Tr(x_{k,j})-(J^c_{s_{k,j}})^Ty_k	+\delta_{k,j-1}^{-1}(J^c_{s_{k,j}})^Tc(x_{k,j})\|\nonumber\\
&=\|\nabla_xL_{s_{k,j}}(x_{k,j},y_k-\delta_{k,j-1}^{-1}c(x_{k,j}))  \|\nonumber\\
&\leq \theta	\|\nabla_x L_{s_{k}} (x_k,y_k) \|+	\frac{1}{2}\epsilon_k,
\end{align}
and	$\| c(x_{k,j}) \| > \theta\|c(x_{k})\|	+\frac{1}{2}\epsilon_k>0 $.
It then follows from Assumptions %\ref{ass1rd} and
\ref{ass2rd}(i)-(iii),
\eqref{tb1} and $\delta_{k,j} \ge \frac{1}{10}\delta_{k,j-1}$  that for all
$j\in\mathcal{J}$,
\begin{align*}
\frac{1}{10}\delta_{k,j}^{-1} \|(J^c_{s_{k,j}})^Tc(x_{k,j})\|
&\leq \delta_{k,j-1}^{-1}\|(J^c_{s_{k,j}})^Tc(x_{k,j})\|\nonumber\\
&\leq\|(J^r_{s_{k,j}})^Tr(x_{k,j})-(J^c_{s_{k,j}})^Ty_k\|
				+\theta\|\nabla_x L_{s_{k}} (x_k,y_k) \|+\frac{1}{2}\epsilon_k\nonumber\\
&<+\infty.
\end{align*}
Since $\delta_{k,j} = \delta_{k,j-1}$  for all $j\notin\mathcal{J}$,	we have
 $ \{(J^c_{s_{k,j}})^Tc(x_{k,j})\}_{j\in \mathcal{J}}	\to	0$.

Next we prove $\{\gamma_{k,j}\}_{j\in \mathcal{J}} \to 0$.
Otherwise there exists  $\nu>0$ such that the set $ \mathcal{J}_1=\{j\in \mathcal{J}:\gamma_{k,j}>\nu\}$ is
infinite. Hence the set $ \mathcal{J}_2=\{j\in \mathcal{J}:\gamma_{k,j}>\frac{\nu}{2}\}$ is also infinite.
Define $ \mathcal{J}_3=\{j\in \mathcal{J}_2:\gamma_{k,j+1}>\gamma_{k,j}\}$.
We show $\mathcal{J}_3$ is also infinite.
Otherwise,  there exists $j_0\in \mathcal{J}_2 $ such that $\gamma_{k,j+1}\leq \gamma_{k,j}$ for all $j\ge j_0$ in $\mathcal{J}_2$.
Then there exists $j_1\in\mathcal{J}\setminus \mathcal{J}_2, j_1>j_0$,
such that $\gamma_{k,j_1} \leq \frac{\nu}{2}$ and $\gamma_{k,j+1}\leq \gamma_{k,j}$ for all $j\in [j_0,j_1)\cap \mathcal{J}_2$.
Since $\mathcal{J}_2$ is infinite, by the updating rule	(\ref{gamaupd}), there exists $j_2\in\mathcal{J}_2, j_2>j_1$ such that $\frac{\nu}{2}<\gamma_{k,j_2}\leq \nu$ and $\gamma_{k,j}\leq \frac{\nu}{2}$
for all $j \in [j_1,j_2)\cap \mathcal{J}\setminus \mathcal{J}_2$.
By induction, it can be deduced  that $\gamma_{k,j} \leq \nu$ for all $j\in (j_2,+\infty)\cap \mathcal{J}$, which contradicts the infiniteness of $\mathcal{J}_1$. Thus, $\mathcal{J}_3$ is infinite.
Since $ \{(J^c_{s_{k,j}})^Tc(x_{k,j})\}_{j\in \mathcal{J}} \to 0$, there exists
$j_{\nu}\in\mathcal{J}_3\subset \mathcal{J}_2$, such that
\begin{align*}%\label{tb3}
\|(J^c_{s_{k,j_{\nu}}})^Tc(x_{k,j_{\nu}})\| < \frac{p_3\nu}{2}< p_3 \gamma_{k,j_{\nu}}, \quad					\gamma_{k,j_{\nu}+1}>\gamma_{k,j_{\nu}}.
\end{align*}
This contradicts (\ref{gamaupd}).
Thus, $\{\gamma_{k,j}\}_{j\in \mathcal{J}} \to 0$.
Besides, by Algorithm \ref{alg2}, $\gamma_{k,j+1}\leq\frac{1}{2}\gamma_{k,j}$ for $j\notin \mathcal{J}$,
so we have
\begin{align}\label{gammato}
\{\gamma_{k,j}\}_{j} \to 0.
\end{align}


By Lemma \ref{lemAB} and multivariate Chebyshev's inequality \cite{Chebyshevproof}, for any $s>0$,
\begin{align}\label{temp}
\mathbb{P}\left(	\left\|	J^c_{S_{k,j}}(x_{k,j})-\mathbb{E}_u [J^c_{S_{k,j}}(x_{k,j})] 	
				\right\|\leq s\right)\ge 1- \frac{d^2m n\kappa_{lgc}^2}{4s^2}\gamma_{k,j}^2.
\end{align}
By Assumption \ref{ass2rd}(ii) and (\ref{lem1B}),
\begin{align}\label{temp1}
 &	\left\| J^c_{S_{k,j}}(x_{k,j})^Tc(x_{k,j})-J^c(x_{k,j})^Tc(x_{k,j}) \right\| \leq
			 	\left\| J^c_{S_{k,j}}(x_{k,j})-J^c(x_{k,j})  \right\|\left\|  c(x_{k,j}) \right\|\nonumber\\
			 &\leq \left( \left\|  J^c_{S_{k,j}}(x_{k,j})-\mathbb{E}_u
			 [J^c_{S_{k,j}}(x_{k,j})]\right\|+\left\|\mathbb{E}_u
			 [J^c_{S_{k,j}}(x_{k,j})]- J^c(x_{k,j})\right\|  \right) \left\| c(x_{k,j}) \right\|\nonumber\\
			 & \leq \kappa_{bc}\left( \left\| J^c_{S_{k,j}}(x_{k,j})-\mathbb{E}_u [J^c_{S_{k,j}}(x_{k,j})]\right\|+d\sqrt{m}\kappa_{lgc}\gamma_{k,j} \right) .
\end{align}
Let $s=\sqrt{\frac{d^2m n\kappa_{lgc}^2}{2}} \gamma_{k,j}$ in (\ref{temp}).
Combining (\ref{temp}), (\ref{temp1}) and $\mathbb{E}_{u}[J^c_{S_{k,j}}(x_{k,j})]=			\mathbb{E}[J^c_{S_{k,j}}(X_{k,j})\mid \mathcal{F}_{k,j}]$, we obtain
\begin{align*}
&	\mathbb{P}\left(	\left\|
J^c_{S_{k,j}}(X_{k,j})^Tc(X_{k,j})-J^c(X_{k,j})^Tc(X_{k,j})
\right\|\leq \kappa_{bc}d\sqrt{m}\kappa_{lgc}\left(1+\sqrt{\frac{n}{2}}\right)\Gamma_{k,j}	\mid \mathcal{F}_{k,j} \right)\\
&= 	\mathbb{P}\left(	\left\|	J^c_{S_{k,j}}(x_{k,j})^Tc(x_{k,j})-J^c(x_{k,j})^Tc(x_{k,j})
				\right\|\leq \kappa_{bc}d\sqrt{m}\kappa_{lgc}\left(1+\sqrt{\frac{n}{2}}\right)\gamma_{k,j}	\right)\nonumber\\
&\ge \mathbb{P}\left(	\left\|	J^c_{S_{k,j}}(x_{k,j})-\mathbb{E}_u [J^c_{S_{k,j}}(x_{k,j})] 	
				\right\|\leq \sqrt{\frac{d^2m n\kappa_{lgc}^2}{2}} \gamma_{k,j}\right)\nonumber\\
&\ge \frac{1}{2}.
 \end{align*}

Let $\hat{\kappa}:= \kappa_{bc}d\sqrt{m}\kappa_{lgc}\left(1+\sqrt{\frac{n}{2}}\right)$.
Define the event
$$V_j=\left\lbrace 	\left\|	J^c_{S_{k,j}}(X_{k,j})^Tc(X_{k,j})-J^c(X_{k,j})^Tc(X_{k,j})
		\right\|\leq \hat{\kappa}\Gamma_{k,j}	\right\rbrace.
$$
Then $\mathbb{P}\left( V_j \mid \mathcal{F}_{k,j}\right)\ge \frac{1}{2}$.
Define a random walk
			\begin{align}\label{radwk}
				W^R_l=\sum_{j=0}^{l} (2 \textbf{1}_{V_j}-1).
			\end{align}
Obviously,
			\begin{align*}
				W^R_{l+1}=
				\begin{cases}
					W^R_{l}+1, & \text{if}\ \textbf{1}_{V_{l+1}}=1, \\
					W^R_{l}-1, & \text{if}\ \textbf{1}_{V_{l+1}}=0.
				\end{cases}
			\end{align*}
Let $\mathcal{F}^V_{l-1}$ be the $\sigma$-algebra generated by 		$\textbf{1}_{V_{0}},\ldots,\textbf{1}_{V_{l-1}}$, which is contained in $\mathcal{F}_{k,l}$,
Then
\begin{align*}
\mathbb E\left[ W^R_l \mid 		\mathcal{F}^V_{l-1}\right]&= \mathbb E
				\left[W^R_{l-1}  \mid\mathcal{F}^V_{l-1} \right] +\mathbb  E \left[	2\cdot
				\textbf{1}_{V_l} -1  \mid	\mathcal{F}^V_{l-1}\right] \nonumber\\
				&=  W^R_{l-1} + 2 \mathbb P \left( V_l \mid	\mathcal{F}^V_{l-1}\right) -1 \nonumber\\
				& \ge  W^R_{l-1},
\end{align*}
So $W^R_l$ is a submartingale with $\pm 1$ increments.
Thus, by \cite[Theorem 4.3.1]{DR2010},
			\begin{equation}\label{prow1}
				\mathbb P \left( \limsup_{l\to\infty} W^R_l=+ \infty
				\right) =1.
			\end{equation}

Suppose that \eqref{gammato} is not true.
We discuss the case that
\begin{align}\label{bigthe}
\|J^c(x_{k,j})^Tc(x_{k,j})\|> \varepsilon
\end{align}
happens for some $\varepsilon>0$ and all $j$.
Define the random variable
$$
\Pi_j=\ln_2 (\Gamma_{k,j}),
$$
whose realization is denoted as $\pi_j=\ln_2 (\gamma_{k,j} )$.
Since $\{\gamma_{k,j}\}_{j} \to 0$, there exists $j_0$ such that for all $j \ge j_0$,
\begin{align}\label{tb4}		
				\gamma_{k,j}\leq \min\left\lbrace	
			\frac{\varepsilon}{p_4+\hat{\kappa}},
			\frac{\gamma_{k}}{2} \right\rbrace.
\end{align}
We discuss two	cases for $j\in\mathcal{J}, j\ge j_0$.

If $\textbf{1}_{V_j}=1$, then
\begin{align*}
&\left\|J^c(x_{k,j})^Tc(x_{k,j}) \right\|-\left\|J^c_{s_{k,j}}(x_{k,j})^Tc(x_{k,j})\right\|\\
&\leq	\left\|	J^c_{s_{k,j}}(x_{k,j})^Tc(x_{k,j})-J^c(x_{k,j})^Tc(x_{k,j})	\right\|
\leq \hat{\kappa}\gamma_{k,j},
\end{align*}
which, together with (\ref{bigthe}), implies that
\begin{align*}
	\left\|	J^c_{s_{k,j}}(x_{k,j})^Tc(x_{k,j})\right\|\geq 	\varepsilon- \hat{\kappa}\gamma_{k,j}.
\end{align*}
Thus by (\ref{tb4}) and the updating rule (\ref{gamaupd}), we have $\gamma_{k,j+1}=2\gamma_{k,j} $.
 This gives
\begin{align}\label{tb5}
				\pi_{j+1}-\pi_j=1.
\end{align}

If $\textbf{1}_{V_j}=0$, then $\gamma_{k,j+1}\ge \frac{1}{2}\gamma_{k,j}$ due to (\ref{gamaupd}) and $j\in\mathcal{J}$.
Hence $\pi_{j+1}\ge \pi_j-1$. This  implies
			\begin{align}\label{tb6}
				\pi_{j+1}-\pi_j\ge -1.
			\end{align}

Combining (\ref{tb5}) and (\ref{tb6}), we have
			\begin{equation*}
				\pi_j-\pi_{j_0}\ge w^R_j-w^R_{j_0},
			\end{equation*}
where $w^R_j$ is a realization of $W^R_j$ corresponding to the particular realization $\pi_j$.
Because $\pi_{j_0}$ and $w^R_{j_0}$ is finite, by (\ref{prow1}), we have
	\begin{equation}\label{zproin}
				\mathbb{P} \left( \limsup_{j\to\infty}
				\Pi_j=+	\infty  \mid \mathcal E_2\right) =1.
	\end{equation}
On the other hand, by \eqref{gammato}, we have $\pi_j<0$ for sufficiently large $j$, which contradicts (\ref{zproin}).
Therefore, we have
			\begin{align*}
				\P\left( 	\liminf_{j\to \infty}\|J^c(X_{k,j})^T
				c(X_{k,j})\|=0 \mid \mathcal E_2 \right)  =1.
			\end{align*}
The proof is completed.
	\end{proof}

Combining Lemmas \ref{lembeforthem} and \ref{lemBC}, we obtain the convergence result of Algorithm \ref{alg2} as follows.

\begin{theorem}\label{theminner}
Suppose that Assumptions \ref{ass1rd} and \ref{ass2rd}(i)-(iii) hold for every realization of  Algorithm \ref{alg2} with $k$.
It holds that either
	\begin{itemize}
		\item[(i)] for any $\epsilon>0$ and $0<p<1$, we can find $j$ such that
		\begin{align}\label{akkt}
				\|F_{S_{k,j+1}}\|_* \leq \theta \|F_{s_k}\|_*+\epsilon_k
		\end{align}
with probability at least $p$; or	
		\item[(ii)] the random sequence $\{X_{k,j}\}$ generated  by Algorithm
		\ref{alg2}
		satisfies
		\begin{align*}
			\liminf_{j\to \infty}\|J^c(X_{k,j})^T c(X_{k,j})\|=0
		\end{align*}
		almost surely.
	\end{itemize}
\end{theorem}	


