%to zero if $\Delta_{k,j}$ decrease finitely many times.

Now we show that Algorithm \ref{alg1} converges	to an approximate KKT point
with arbitrary precision with high probability if Algorithm \ref{alg2} always
return to Algorithm
	\ref{alg1} with (\ref{innerstoprd}) being satisfied.

\begin{lemma}\label{Gsto0ther}
Suppose that Assumptions \ref{ass2rd}(v) holds for every realization of  Algorithm  \ref{alg1}, and Algorithm \ref{alg2} always achieves (\ref{innerstoprd}),
then $\{w_k\}$ generated by Algorithm \ref{alg1}
	satisfies
	\begin{align}\label{Gsto0}
		\lim_{k\to\infty}	F_{s_k}= 0.
	\end{align}
\end{lemma}

\begin{proof}
Let $\mathcal{G}:=\limsup\limits_{k\to\infty}\|F_{s_{k}}\|_*$ and $\epsilon_M=\sup_k \epsilon_k$.	
By (\ref{innerstoprd}),
\begin{align*}
\|F_{s_{k+1}}\|_*-\frac{\epsilon_M}{1-\theta}%&\leq \theta \left(			\|F_{s_{k}}\|_*-\frac{\epsilon_M}{1-\theta}	\right) +(\epsilon_k-\epsilon_M) \\
			&\leq \theta \left(\|F_{s_{k}}\|_*-\frac{\epsilon_M}{1-\theta}\right).
\end{align*}
This implies $\mathcal{G} \leq\frac{\epsilon_M}{1-\theta}$ because of $0<\theta<1$.
Taking the limit superior in (\ref{innerstoprd}), we have $\mathcal{G}\leq \theta \mathcal{G}$, which gives $\mathcal{G}=0$.
Hence,
\begin{align*}
0\leq \liminf\limits_{k\to\infty}\|F_{s_{k}}\|_* \leq \mathcal{G}=0,
\end{align*}
thus $\lim\limits_{k\to\infty}\|F_{s_{k}}\|_* =0$. So \eqref{Gsto0} holds true.
\end{proof}


