	Note that \eqref{prob} is equivalent to
\begin{align}\label{prob2}
	\min_{x\in\mathbb{R}^n} \ \frac{1}{2}\|z\|^2,\quad
	\text{s.t.} \quad r(x)=z, \ c(x)=0.
\end{align}
The KKT conditions for \eqref{prob2} are
\begin{align}\label{KKT-prob2}
	F(w)=	\begin{bmatrix}
		J^r(x)^Tz-J^c(x)^Ty\\
		r(x)-z\\
		c(x)
	\end{bmatrix}=0.
\end{align}
where $y$ and $-z$ are the Lagrange multipliers for $c(x)=0$ and
$r(x)-z=0$, respectively.
Based on Lemma \ref{Gsto0ther}, we have:

\begin{theorem}\label{outcon}
Suppose that Assumptions \ref{ass1rd}(i) and \ref{ass2rd}(iii)-(v) hold for every realization of  Algorithm  \ref{alg1}, and Algorithm \ref{alg2} always achieves (\ref{innerstoprd}),
then for any $\epsilon>0$ and $0<p<1$, we can find $k_0$ such that
\begin{align}\label{akkt}
		\|F_{k_0}\|  \leq \epsilon
\end{align}
with probability at least $p$.
\end{theorem}


\begin{proof}
	Denote $J^r_{k}:=J^r(x_k), J^c_{k}:=J^c(x_k), F_{s_k}:=F_{s_k}(w_k;
	x_k,y_k,\rho_k,\delta_k), F_k=F(w_k)$.
  By (\ref{Grd}) and \eqref{KKT-prob2},
	\begin{align*}
		F_{s_k}-F_k=\begin{bmatrix}
			\left(J^r_{s_k}- J^r_{k}\right) ^Tz_k-
			\left(J^c_{s_k}- J^c_{k}\right) ^Ty_k\\
			0\\
			0
		\end{bmatrix}.
	\end{align*}
	Hence,
	\begin{align}\label{tet1}
		\|F_{s_k}-F_k\| \leq \|J^r_{s_k}- J^r_{k}\|\|z_k\|+	\|J^c_{s_k}-
		J^c_{k}\|\|y_k\|.
	\end{align}
By  Lemma \ref{lemAB} and multivariate 	Chebyshev's inequality
	\cite{Chebyshevproof},
	for any $s>0$,
	\begin{align*}
		\mathbb{P}\left[\left\|J^r_{S_k}(x_k)-\mathbb{E}_u[J^r_{S_k}(x_k)]\right\|\leq
		s	\right]\ge 1- \frac{d^2p n\kappa_{lgr}^2}{4 s^2} \gamma_k^2.
	\end{align*}
	For any $0<p<1$, let  $s=d\kappa_{lgr}\sqrt{\frac{p n}{4(1-p)}}\gamma_{k}$.
	By (\ref{lem1A}),
	\begin{align}
		&	\mathbb{P}\left[	\left\|J^r_{S_k}(X_{k})-J^r(X_k)
		\right\|\leq d\sqrt{p}\kappa_{lgr}\left(1+\sqrt{\frac{n}{4(1-p)}}
		\right)\Gamma_{k}\ \bigg |\ \mathcal{F}_{k}				\right]
		\nonumber\\
		&= 	\mathbb{P}\left[	\left\|J^r_{S_k}(x_{k})-J^r(x_k)
		\right\|\leq d\sqrt{p}\kappa_{lgr}\left(1+\sqrt{\frac{n}{4(1-p)}}
		\right)\gamma_{k}\right] \nonumber\\
		&\ge \mathbb{P}	
		\left[\left\|J^r_{S_k}(x_k)-\mathbb{E}_u[J^r_{S_k}(x_k)]\right\|\leq
		d\kappa_{lgr}\sqrt{\frac{pn}{4(1-p)}}\gamma_{k}\right]  \nonumber\\
		&\ge p.
	\end{align}
	Similarly, we have
	\begin{align}
		&	\mathbb{P}\left[	\left\|J^c_{S_k}(X_{k})-J^c(X_k)
		\right\|\leq d\sqrt{m}\kappa_{lgc}\left(1+ \sqrt{\frac{n}{4(1-p)}}
		\right)\Gamma_{k} \ \Big |\ \mathcal{F}_{k}	\right]
		\ge p.
	\end{align}
Let $\kappa_G:=(\kappa_{bz}d\sqrt{p}\kappa_{lgr}+\kappa_{by}
	d\sqrt{m}\kappa_{lgc} ) \left(1+\sqrt{\frac{n}{4(1-p)}}\right)$.
	It then follows from (\ref{tet1}) and Assumptions \ref{ass2rd}(iii) that
	\begin{align}\label{tet2}
		&	\mathbb{P}\left[	\left\|F_{S_k}(W_k)-F_k(W_k)
		\right\|\leq \kappa_G	\Gamma_{k} \mid \mathcal{F}_{k}
		\right]  =  \mathbb{P}\left[	\left\|F_{S_k}(w_k)-F_k
		\right\|\leq \kappa_G		\gamma_{k}
		\right]      \ge p.
	\end{align}
		By Assumption \ref{ass2rd}(iv), Lemma \ref{Gsto0ther} and
		(\ref{sysrd}), we
	have
	$\{d_{w_k}\}_k \to 0$.
	Note that at the $k$-th iteration, $\gamma_{k+1}=\|d_{x_k}\|$ if Algorithm
	\ref{alg2} is not called;
	otherwise we set $\gamma_{k+1}:=\gamma_{k,j_{t}+1}$,
	where $j_t$ is the index given by Algorithm \ref{alg2} such that
	(\ref{innerstoprd}) is satisfied.
	By  the updating rule of $\gamma_{k,j}$, we have $\gamma_{k+1} \leq
	\gamma_{k}$.
	Thus, $\{d_{w_k}\}_k \to 0$ implies $\{\gamma_{k}\}_k \to 0$.
	Hence by  Lemma 	\ref{Gsto0ther},
	for any $\epsilon>0$,
	\begin{align}\label{lst}
		\kappa_G \gamma_k \leq \frac{1}{2}\epsilon, \quad 	\|F_{s_k}\| \leq
		\frac{1}{2}\epsilon
	\end{align}
	holds for sufficiently large $k$ for every realization.
	Since $\|F_k\| \leq \|F_{s_k}\|+ \|F_{s_k}-F_k\| $,  by (\ref{tet2}) and
	(\ref{lst}),  we can find $k_0$ such that
	\begin{align*}
		\|F_{k_0}\|  \leq \epsilon
	\end{align*}
	with probability at least $p$.
\end{proof}



\section{Numerical experiments}\label{sec4}
In this section, we test Algorithm \ref{alg1} (DFRCNLS) and compare it with
two derivative-free algorithms for constrained optimization problems: COBYLA
(cf. \cite{PowellCOBYLA}) using	Matlab interface of PDFO\cite{pdfo}, a direct search optimization method
	that models the objective and constraint functions by linear interpolation,
and DEFT-FUNNEL (cf. \cite{Sampaio2021}), an  global optimization algorithm that belongs to the class of trust-region sequential quadratic optimization algorithms and uses the polynomial interpolation models as surrogates for the black-box functions.

The experiments are implemented on a laptop  with an AMD Core R7-6800H CPU (3.20GHz) and 32GB of RAM, using Matlab R2022b.


\subsection{Implementation details}
We set $\delta_0=1, \rho_0=0, \epsilon_{0}=10^{3}, \gamma_0=1, \theta=0.99$ in Algorithm \ref{alg1},
and $p_0=0.001, p_1=0.25, p_2=0.75, p_3=10^{-10}, p_4=10^{12}, \lambda_{\min}=10^{-8}$ in Algorithm \ref{alg2}, respectively.
We take $\delta_k=\max\left\{10^{-6}, \min\left\{0.1\delta_{k-1},\:\|F_{s_{k}}\|_*\right\}\right\}$ and
$\epsilon_{k+1}=\max\{\min\{10^{3}\delta_{k},0.99\epsilon_{k}\},0.9\epsilon_{k}\}$ (cf. \cite{Orban2020}).
The regularization parameter $\rho_{k}$ is updated as that in \cite[Algorithm 5.1]{Orban2020} so that the coefficient matrices of the system (\ref{sysrd}) are nonsingular.
The initialization multiplier $y_{0}$ is obtained by solving the problem
\begin{align*}	
\min\limits_{y}\:\frac{1}{2}
		\|(J^c_{s_0})^{T}y-(J^r_{s_0})^{T}r(x_{0})\|^{2}.
\end{align*}


Algorithm \ref{alg1} runs up to $K_1$ iterations and stops at iteration $k < K_1$ if
\begin{align}\label{nat}
\max\left\{\dfrac{\|(J^r_{s_{k}})^T	 		r(x_k)-(J^c_{s_{k}})^Ty_k\|_\infty}{\max\left\{100,\:\dfrac{\|y_k\|_1}{m}\right\}\Big /100},
	 	\:\|c(x_k)\|_\infty\right\}\leq 10^{-5}.
\end{align}
Algorithm \ref{alg2} runs up to $K_2$ iterations and stops at iteration $k < K_2$ if 		
 $\|(J^c_{s_{k,j}})^T c(x_{k,j})\|\leq 10^{-6}$, then it returns to Algorithm \ref{alg1}.
 The defaults values of $K_1$ and $K_2$ are 150 and 50, respectively.

In the implementation, the approximate Jacobian matrices are computed by \eqref{nabrrd}--\eqref{JBrd}. 	
We can generate $n$ independent random vectors $w_1,\ldots,w_n$ with identical distribution $\mathcal{N}(0,I)$ at each iteration, then compute the QR decomposition of the matrix  $[w_1,\ldots,w_n]$ to obtain $u_1,\ldots,u_n$; the corresponding algorithm is denoted as DFRCNLS-OSSv1.
We can also generate ten orthogonal direction sets, then choose one of them randomly as directions at each iteration; in this case the algorithm is denoted as DFRCNLS-OSSv2.
If we take $u_j=e_j(j=1,\ldots,n)$, then the Jacobian matrices are approximated by the finite difference, and the corresponding algorithm is denoted as DFRCNLS-FD,

We take the approximate Hessian matrices of $r_i(x)$, denoted by $H^{r_i}_{s}$, as zero matrix.
The approximate Hessian matrices of $c_i(x)$, denoted by $H^{c_i}_{s}$, are updated in the following three ways: by the symmetric rank-one update (SR1)
 \begin{align*}
 (H^{c_i}_{s})^+= \left\{\begin{array}{ll}
 H^{c_i}_{s}+ \dfrac{( y^{c_i}-H^{c_i}_{s}t)( y^{c_i}- H^{c_i}_{s}t)^T}{ ( y^{c_i}-H^{c_i}_{s}t)^Tt},
 & \mbox{if}\ \|( y^{c_i}-H^{c_i}_{s} t)^Tt \|\ge 10^{-7},\\
 H^{c_i}_{s}, & \mbox{otherwise},
 \end{array} \right.
 \end{align*}
 where $t=x^+ -x$, $y^{c_i}=[(J_{s}^{c})^+ ]_i^T-[J^c_{s}]_i^T $
and $[\cdot]_i$ represents the $i$-th row of the matrix,
or by the BFGS update
 \begin{align*}
(H^{c_i}_{s})^+= \left\{\begin{array}{ll}
  H^{c_i}_{s}+\dfrac{y^{c_i}(y^{c_i})^T}{t^Ty^{c_i}}- \dfrac{H^{c_i}_{s} t(H^{c_i}_{s} t)^T}{t^TH^{c_i}_{s} t},
 & \mbox{if}\  \|t^Ty^{c_i}\|\ge 10^{-7},\\
 H^{c_i}_{s}, & \mbox{otherwise},
 \end{array} \right.
 \end{align*}
or $(H^{c_i}_{s})^+=0$.
