\vskip 10pt
% section problem_and_set_up (end)



\section{Preparations for the proof} % (fold)
\label{sec:schwartz_homology}

\subsection{Schwartz analysis and Borel's lemma} % (fold)
\label{sub:toolkits}

As mentioned in the previous section, we work in the setting of almost linear Nash groups.  In the sense of \cite{MR4211018}, an almost linear Nash group is a group with a Nash structure, which admits a homomorphism to some general linear group with a finite kernel. All groups we are working with in this paper (general linear groups and their closed subgroups) belong to this class of groups.

\vskip 5pt

Let $G$ be an almost linear Nash group, we denote by $\Smod\left(G\right)$ the category of smooth Fr\'echet representations of moderate growth of $G$. For a representation $\left(\pi, V\right)$ of $G$, we put
\[
    V_G = V\big/\left\langle \pi\left(g\right)v-v~\big|~g\in G,~v\in V\right\rangle,
\]
equipped with the quotient topology. It might not be Hausdorff. The functor $V\longmapsto V_G$ is a right exact functor from $\Smod\left(G\right)$ to the category of topological vector spaces. The Schwartz homology $\SH_i\left(G,V\right)$ is by definition the $i$-th derived functor of it.

\vskip 5pt

Let $H$ be a Nash subgroup of $G$, and $\left(\pi_H, V\right)$ be a representation of $H$. Then there is a continuous map
\[
    I: \mathcal{S}\left(G,V\right) \longrightarrow C^\infty\left(G,V\right), \quad  f\longmapsto \left(g\mapsto \int_H \pi_H(h)f\left(h^{-1}g\right)\,dh\right)
\]
from the space of Schwartz functions $\mathcal{S}\left(G,V\right)$ to the space of smooth functions $C^\infty\left(G,V\right)$, with image landing in the usual un-normalized induction $\leftindex^u{\Ind}_H^G V$. The image of $I$, equipped with the quotient topology of $\mathcal{S}\left(G,V\right)$, is called the Schwartz induction of $\pi_H$ and will be denoted by $\leftindex^u\ind_H^G V$.

\begin{Rmk}
The following two facts are worth noting:

\begin{itemize}
\item if $H$ is a parabolic subgroup, then, as $H\backslash G$ is compact, the Schwartz induction $\leftindex^u\ind_H^G V$ is the usual un-normalized parabolic induction;
\vskip 5pt

\item the Schwartz induction $\leftindex^u\ind_H^G V$ can be also intepreted as the space of Schwartz sections over the vector bundle
\[
    H\backslash (G\times V) \longrightarrow H\backslash G,
\]
where $H$ acts on $G\times V$ diagonally.%is defined by $h.(g,v):=(h\cdot g,h.v)$.
\end{itemize}
\end{Rmk}

\vskip 5pt

The next proposition is a version of Frobenius reciprocity in the setting of Schwartz analysis. Readers may consult \cite[Prop. 6.6, Thm. 6.8]{MR4211018} for more details.

\begin{Prop}\label{P:Frobenious}
Let $V$ be a representation of $H$. Then
\[
   \left(\left(\leftindex^u\ind_H^G \left( V\cdot \delta_H\right)\right)\cdot\delta_G^{-1}\right)_G \simeq V_H,
\]
where $\delta_H$ and $\delta_G$ are the modulus characters of $H$ and $G$, respectively.
\end{Prop}

\vskip 5pt

In later proofs we also need to do some orbit analysis. We now introduce a version of Borel's lemma, following \cite[Prop. 8.2, 8.3]{MR4211018} and \cite[Prop. 2.5]{xue2020besselShomology}. Let $\mathcal{X}$ be a Nash manifold and $\mathcal{Z}$ a closed Nash submanifold. We put $\mathcal{U} = \mathcal{X} \backslash \mathcal{Z}$. Let $\mathcal{E}$ be a tempered vector bundle over $\mathcal{X}$, then the ``extension by zero'' of Schwartz sections over $\mathcal{U}$ gives us the following exact sequence:
\[
    0 \longrightarrow \Gamma\left(\mathcal{U}, \mathcal{E}\right) \longrightarrow \Gamma\left(\mathcal{X}, \mathcal{E}\right) \longrightarrow \Gamma_{\mathcal{Z}}\left(\mathcal{X}, \mathcal{E}\right) \longrightarrow 0,
\]
where the symbol $\Gamma$ stands for taking Schwartz sections, and
\[
    \Gamma_{\mathcal{Z}}\left(\mathcal{X}, \mathcal{E}\right) := \Gamma\left(\mathcal{X}, \mathcal{E}\right)\big/\Gamma\left(\mathcal{U}, \mathcal{E}\right).
\]
Let $N_{\mathcal{Z}|\mathcal{X}}^\vee$ 
 be the conormal bundle of $\mathcal{Z}$ and $\mathcal{N}_{\mathcal{Z}|\mathcal{X}}^\vee$ the complexification of $N_{\mathcal{Z}|\mathcal{X}}^\vee$.

\begin{Prop}\label{P:BorelLemma}
There is a descending filtration on $\Gamma_{\mathcal{Z}}\left(\mathcal{X}, \mathcal{E}\right)$ indexed by $k\in\mathbb{N}:$
\[
    \Gamma_{\mathcal{Z}}\left(\mathcal{X}, \mathcal{E}\right)=\Gamma_{\mathcal{Z}}\left(\mathcal{X}, \mathcal{E}\right)_0 \supset \Gamma_{\mathcal{Z}}\left(\mathcal{X}, \mathcal{E}\right)_1 \supset \Gamma_{\mathcal{Z}}\left(\mathcal{X}, \mathcal{E}\right)_2 \supset \cdots,
\]
such that
\[
    \Gamma_{\mathcal{Z}}\left(\mathcal{X}, \mathcal{E}\right) = \lim_{\longleftarrow} \Gamma_{\mathcal{Z}}\left(\mathcal{X}, \mathcal{E}\right)\big/\Gamma_{\mathcal{Z}}\left(\mathcal{X}, \mathcal{E}\right)_k,
\]
with each graded piece isomorphic to
\[
    \Gamma\left(\mathcal{Z}, \Sym^k\mathcal{N}_{\mathcal{Z}|\mathcal{X}}^\vee\otimes\mathcal{E}\big|_\mathcal{Z}\right), \quad k\in\mathbb{N}.
\]
Moreover, if $\mathcal{X}$ is a $G$-Nash manifold, $\mathcal{Z}$ is stable under the $G$-action, and $\mathcal{E}$ is a tempered $G$-bundle, then this filtration is stable under the $G$-action.

\end{Prop}

\vskip 5pt

\iffalse
Now we state Casselman's comparison theorem in this setting. Let $G$ be a reductive Nash group, and $P=MN$ be a parabolic subgroup, with Levi component $M$ and unipotent radical $N$. Put $\mathfrak{n}= {\rm Lie}\left(N\right)_\C$.

\begin{Conj}\label{C:CasselmanComparison}
Let $V$ be a Casselman--Wallach representation of $G$. Then the Schwartz homology $\SH_i\left(N,V\right)$ is the Casselman--Wallach globalization of the corresponding Lie algebra homology $\SH_i\left(\mathfrak{n}, V^{HC}\right)$, where $V^{HC}$ is the Harish-Chandra module associated to $V$.    
\end{Conj} 

\vskip 5pt

This conjecture has been proved when $P$ is a minimal parabolic subgroup of $G$, see \cite{MR4346020}. For the general case, it seems to us that this conjecture is still open.

\vskip 5pt\fi

% subsection toolkits (end)

\subsection{Infinitesimal character argument and a vanishing lemma} % (fold)
\label{sub:two_vanishing_lemmas}

%\CR{Add "infinitesimal character argument"}

Finally, we introduce two lemmas, which will help us to conclude certain Hom spaces or Schwartz homologies are zero. Recall that for any irreducible representation $\pi$ of $G_n$, there exists a parabolic induction
\[
    \tau_1|{\det}_{d_1}|^{s_1}\times\tau_2|{\det}_{d_2}|^{s_2}\times\cdots\times\tau_r|{\det}_{d_r}|^{s_r},
\]
where $\tau_i$ are unitary discrete series of $G_{d_i}$, and 
\[
    s_1\geq s_2\geq\cdots\geq s_r
\] 
are real numbers, such that $\pi$ is the unique quotient of this parabolic induction, called the ``\textit{Langlands quotient}''. We denote it by $\pi = LQ\left(\tau_1|{\det}_{d_1}|^{s_1}\times\tau_2|{\det}_{d_2}|^{s_2}\times\cdots\times\tau_r|{\det}_{d_r}|^{s_r}\right)$. It is known that $\pi$ occurs in this parabolic induction with multiplicity one. We first prove a result for Schwartz homologies of certain parabolic induced representations, which is based on a standard infinitesimal character argument.

\begin{Lem}\label{L:inftesimalArguement}
Let $\pi$
be a finite length representation of $G_n$. Let $\chi_1,\chi_2,\cdots,\chi_k$ be characters of $G_1$, $F$ a finite dimensional representation of $G_k$, and $\pi_0$ a representation of $G_{n-d}$ (not necessarily of finite length). Then there exists a Zariski closed proper subset ${\rm Ex}$ of $\C^n$, such that for all $\left(s_1, s_2, \cdots, s_{k}\right) \in \C^n\,\backslash\, {\rm Ex}$, we have
\[
    \SH_i\left(G_n, \pi^\vee\otimes \left(I_{\underline{\chi}}\left(s_1,s_2,\cdots,s_{k}\right)\otimes F\right)\times\pi_0\right) = 0
\]
for all $i\geq 0$. Here $I_{\underline{\chi}}\left(s_1,s_2,\cdots,s_{k}\right)\coloneqq\chi_1|\cdot|^{s_1}\times\chi_2|\cdot|^{s_2}\times\cdots\times\chi_k|\cdot|^{s_{k}}$.
\end{Lem}

\vskip 5pt

\begin{proof}
This lemma can be proved in the same way as \cite[Lem. 4.2]{xue2020besselShomology}. The idea is to construct an element $z$ in the center of the universal enveloping algebra of $\gothg_n = {\rm Lie}\left(G_n\right)_\C$ explicitly, such that $z$ annihilates $\left(I_{\underline{\chi}}\left(s_1,s_2,\cdots,s_{k}\right)\otimes F\right)\times\pi_0$ but does not annihilate $\pi$.

\end{proof}

\vskip 5pt

Next, we prove a vanishing lemma that concerns Hom spaces.

\begin{Lem}\label{L:vanishingLem1}
Let
\[
    \pi = LQ\left(\tau_1|{\det}_{d_1}|^{s_1}\times\tau_2|{\det}_{d_2}|^{s_2}\times\cdots\times\tau_r|{\det}_{d_r}|^{s_r}\right)
\]
be an irreducible representation of $G_n$. Let $s$ be a real number, $\tau$ a unitary discrete series of $G_d$, and $\pi_0$ a representation of $G_{n-d}$ (not necessarily of finite length). Suppose there either 

\begin{itemize}
    \item $s > s_1$; or

    \vskip 5pt

    \item $s+\frac{1}{2}>s_1\geq\cdots \geq s_k \geq s > s_{k+1}$, and $\tau|{\det}_d|^s\not\simeq \tau_i|{\det}_{d_i}|^{s_i}$ for $i=1,\cdots,k$.
\end{itemize}
\vskip 5pt
Then we have
\[
    \Hom_{G_n}\left(\tau|\det|^s\times\pi_0, \pi\right) = 0.
\]
%In particular, when $s>s_1$, the condition of the lemma is satisfied.
\end{Lem}

\vskip 5pt

\begin{proof}
This lemma can be proved in the same manner as \cite[Thm. A.1.1]{chen2023multiplicity} following the idea of \cite{moeglin2012conjecture}. For the sake of completeness, we provide a sketch of the proof below.

\vskip 5pt

We shall prove by contradiction. Suppose on the contrary that there is a real number $s$, a unitary discrete series $\tau$ of $G_d$ and a representation $\pi_0$ of $G_{n-d}$, satisfying the conditions in the lemma, but
\[
\Hom_{G_n}(\tau|\det|^s\times\pi_0,\pi) \neq 0.
\]
Let $\gothg_n$ be the complexified Lie algebra of $G_n$, and $K_n$ a maximal compact subgroup of $G_n$. Since for any representation in $\Smod\left(G_n\right)$, its subspace of $K_n$-finite vectors is dense, we know that the Hom space between the $\left(\gothg_n, K_n\right)$-module of $\tau|\det|^s\times\pi_0$ and the $\left(\gothg_n, K_n\right)$-module of $\pi$ is also non-zero.
Then we can appeal to the second adjointness. In \cite[Sect. 5]{MR4344027}, Y. Din defined various functors. In particular, the composition ${\rm cofib}_I\circ\mathcal{C}_I$ of the functors ${\rm cofib}_I$ and $\mathcal{C}_I$ there, provides a right adjoint functor of the parabolic induction functor ${\rm pind}_I$. This functor ${\rm cofib}_I\circ\mathcal{C}_I$ also preserves admissibility and the property of finite length. 
By using this functor, we can further assume that $\pi_0$ is an irreducible representation.

\vskip 5pt

Next we use the Langlands classification to deduce a contradiction. Suppose that
\[
    \pi_0 = LQ\left(\rho_1|\det|^{b_1}\times\rho_2|\det|^{b_2}\times\cdots\times\rho_m|\det|^{b_m}\right),
\]
where $\rho_i$ are unitary discrete series of $G_{\alpha_i}$, and $b_1\geq\cdots\geq b_m$ are real numbers. Substituting this into the Hom space, we have
\[
    \Hom_{G_n}\left(\tau|\det|^s\times\rho_1|\det|^{b_1}\times\rho_2|\det|^{b_2}\times\cdots\times\rho_m|\det|^{b_m},\pi\right) \neq 0.
\]
If $s\geq b_1$, then $\tau|\det|^s\times\rho_1|\det|^{b_1}\times\cdots\times\rho_m|\det|^{b_m}$ is a standard module of $G_n$. It then follows that
\[
    \pi = LQ\left(\tau|\det|^s\times\rho_1|\det|^{b_1}\times\rho_2|\det|^{b_2}\times\cdots\times\rho_m|\det|^{b_m}\right),
\]
which contradicts our assumption on $\pi$. So we must have $s< b_1$. By induction in stages, one can see that there is an irreducible subquotient $T$ of $\tau|\det|^s\times \rho_1|\det|^{b_1}$, such that
\[
    \Hom_{G_n}\left(T\times\rho_2|\det|^{b_2}\times\cdots\times\rho_m|\det|^{b_m},\pi\right) \neq 0.
\]
Again, we write $T$ as a Langlands quotient
\[
    T=LQ\left(\rho'_0|\det|^{b'_0}\times\cdots\times \rho'_t|\det|^{b'_t}\right).
\]
If $\tau|\det|^s\times \rho_1|\det|^{b_1}$ is irreducible, then $T \simeq \rho_1|\det|^{b_1}\times\tau|\det|^s$. If $\tau|\det|^s\times \rho_1|\det|^{b_1}$ is reducible, then by the irreducibility criterion for principal series \cite[Thm. 6.2]{MR401654} \cite[Thm. 10b]{MR1476497}, we can conclude that $b'_0\geq s+1/2$.
Replacing $T$ in the Hom space by its standard module $\rho'_0|\det|^{b'_0}\times\cdots\times \rho'_t|\det|^{b'_t}$ and repeating this procedure. After finitely many steps, we will find that
\[
\Hom_{G_n}\left(\rho''_0|\det|^{c_0}\times\rho''_1|\det|^{c_1}\times\cdots\times\rho''_u|\det|^{c_u},\pi\right) \neq 0,
\]
where $\rho''_0|\det|^{c_0}\times\rho''_1|\det|^{c_1}\times\cdots\times\rho''_u|\det|^{c_u}$ is a standard module, such that either $c_0\geq s+1/2$, or $\tau|\det|^s\simeq \rho''_i|\det|^{c_i}$ for some $1\leq i \leq u$. This again contradicts our assumption on $\pi$. Therefore, the lemma holds.

