\section{Orbit analysis and higher corank models} % (fold)
\label{sec:orbit_analysis_and_higher_corank_models}

\subsection{Orbit analysis on Grassmannian} % (fold)
\label{sub:orbit_analysis_on_grassmannian_rank_1_case}

We first investigate how a parabolic induced representation $\rho\times\tau$ of $G_{n+1}$ decomposes when restricted to the mirabolic subgroup $M_{n+1}$ using Borel's lemma (Proposition \ref{P:BorelLemma}), where $\rho$ is an essential discrete series representation of $G_k$. Let $P_{k,n+1-k}$ be the standard parabolic subgroup of $G_{n+1}$ with Levi component $G_k\times G_{n+1-k}$. Then we need to do the orbit analysis on the Grassmannian
\[
    P_{k,n+1-k}\backslash G_{n+1} = \Gr\left(k,n+1\right).
\]
Let $\calE_{\rho,\tau}$ be the tempered vector bundle over $\calX = \Gr\left(k,n+1\right)$ corresponding to $\rho\times\tau$. There are exactly two orbits of $M_{n+1}$ on $\calX$.

\vskip 5pt

$\bullet$ The closed orbit $\calZ = \Gr\left(k,n\right)$ consisting of $k$-dimensional subspaces of $F^n$. The action of $M_{n+1}$ on this orbit descends to $G_n$; the stabilizer in $G_n$ of a representative in this orbit is $P_{k,n-k}$. By some elementary computations we know that the conormal bundle of $\calZ$ in $\calX$ is
    \[
        N_{\calZ|\calX}^\vee \simeq G_n\times_{P_{k,n-k}}\std_k,
    \]
    where as a vector space $\std_k = F^k$, the action of $P_{k,n-k}$ on $F^k$ factors through the Levi component $G_k\times G_{n-k}$, $G_k$ acts on $F^k$ by the standard representation, and $G_{n-k}$ acts trivially. Applying Borel's lemma, the contribution of the closed orbit (and derivatives) $\Gamma_{\calZ}\left(\calX, \calE_{\rho,\tau}\right)$ has a filtration, with each graded piece
    \[
        \left(\Sym^j\std_{k,\C}\otimes\rho\right)|{\det}_k|^{\frac{1}{2}}\times\left(\tau~\big|_{G_{n-k}}\right)
    \]
    as representations of $G_n$, where $j=0,1,2,\cdots$.

    \vskip 5pt

$\bullet$ The open orbit $\calX\backslash\calZ$ consisting of $k$-dimensional subspaces not contained in $F^n$. Let $S_k$ be the stabilizer in $M_{n+1}$ of a representative in this orbit. It fits into an exact sequence
    \[
        1 \lra N_{k-1,n+1-k} \lra S_k \lra M_k\times G_{n+1-k} \lra 1,
    \]
    where $N_{k-1,n+1-k}$ is the unipotent radical of $P_{k-1,n+1-k}$. The contribution of the open orbit (as a representation of $M_{n+1}$) is
    \[
        \leftindex^u\ind_{S_k}^{M_{n+1}}\left(\rho|{\det}_k|^{\frac{n+1-k}{2}}~\big|_{M_k}\boxtimes\tau|{\det}_{n+1-k}|^{-\frac{k}{2}}\right),
    \]
    where $\rho|{\det}_k|^{\frac{n+1-k}{2}}~\big|_{M_k}\boxtimes\tau|{\det}_{n+1-k}|^{-\frac{k}{2}}$ is a representation of $M_k\times G_{n+1-k}$, and we regard it as a representation of $S_k$ by inflation.  

\vskip 5pt

We give two useful applications of discussions in this section. The first application concerns the so-called \textit{Fourier--Jacobi models}, namely, the Hom space
\[
    \Hom_{G_n}\left(\pi\otimes \omega_n,\sigma\right)
\]
for two representations $\pi$ and $\sigma$ of $G_n$.

\begin{Lem}\label{L:FJToBessel}
Let $\pi$ and $\sigma$ be finite length representations of $G_n$. Then for all but at most countably many $s\in \sqrt{-1}\cdot\R$, there is a natural isomorphism 
\[
    \Hom_{G_n}\left(|\cdot|^s\times\pi,\sigma\right) \simeq \Hom_{G_n}\left(\pi\otimes \omega_n,\sigma\right).
\]   
\end{Lem}

\vskip 5pt

\begin{proof}
Apply the discussion above to $|\cdot|^s\times\pi$. By Lemma \ref{L:inftesimalArguement}, we know that for all but at most countably many $s\in \sqrt{-1}\cdot\R$, we have
\[
    \SH_i\left(G_n, \left(\Sym^j\std_{1,\C}\otimes|\cdot|^{s+\frac{1}{2}}\times\left(\pi~\big|_{G_{n-1}}\right)\right)\otimes\sigma^\vee\right) = 0
\]
for all $i,j = 0,1,2,\cdots$. This implies that for all but at most countably many $s\in\sqrt{-1}\cdot\R$, we have
\[
    \Hom_{G_n}\left(|\cdot|^s\times\pi,\sigma\right) \simeq \Hom_{G_n}\left(\leftindex^u\ind_{G_n}^{M_{n+1}}\pi|{\det}_{n}|^{-\frac{1}{2}}~\big|_{G_n},\sigma\right).
\]  
Note that $\leftindex^u\ind_{G_n}^{M_{n+1}}\pi|{\det}_{n}|^{-\frac{1}{2}}~\big|_{G_n}\simeq \pi\otimes\omega_n$, hence we are done.

\end{proof}

\vskip 5pt



To give the second application, we specialize to the case that $F=\R$ and $n=k=1$. Let $\delta$ be an irreducible unitary discrete series representation of $G_2$. We would like to investigate how $\delta$ decomposes when restricted to $M_2$. It is well-known that discrete series of $G_2$ can be constructed as the quotient of a principal series by a finite-dimensional subrepresentation. To be more precise, there exists a unitary character $\chi$ of $G_1$ and a positive integer $m\in\Z_{>0}$, such that $\delta$ fits into an exact sequence
\begin{equation}\label{E:dsExactSeq}
    0 \lra \Pi_f \lra \chi\,{\rm sgn}^{m-1}|\cdot|^{-\frac{m}{2}}\times\chi|\cdot|^{\frac{m}{2}} \lra \delta \lra 0,
\end{equation}
where $\Pi_f=\chi\,{\rm sgn}^{m-1}|\cdot|^{\frac{1-m}{2}}{\rm Sym}^{m-1}\C^2$ is an $m$-dimensional representation of $G_2$. Applying the discussion in this section to $\chi\,{\rm sgn}^{m-1}|\cdot|^{-\frac{m}{2}}\times\chi|\cdot|^{\frac{m}{2}}$, one knows that:

\begin{itemize}
    \item as a representation of $M_2$, $\chi\,{\rm sgn}^{m-1}|\cdot|^{-\frac{m}{2}}\times\chi|\cdot|^{\frac{m}{2}}$ has a subrepresentation
    \[
        \Gamma_{op} \simeq \leftindex^u\ind_{G_1}^{M_2}\chi|\cdot|^{\frac{m-1}{2}};
    \]

    \vskip 5pt

    \item the quotient of $\chi\,{\rm sgn}^{m-1}|\cdot|^{-\frac{m}{2}}\times\chi|\cdot|^{\frac{m}{2}}$ by $\Gamma_{op}$ has a descending filtration, with each graded pieces isomorphism to the inflation of
    \[
        \chi\,{\rm sgn}^{j+m-1}|\cdot|^{j+\frac{1-m}{2}}
    \]
    to $M_2$, where $j=0,1,2,\cdots$.
\end{itemize}
\vskip 5pt
On the other hand, easy to see that the restriction of $\Pi_f$ to $M_2$ has a filtration, with each graded piece isomorphic to the inflation of
\[
        \chi\,{\rm sgn}^{j+m-1}|\cdot|^{j+\frac{1-m}{2}}
\]
to $M_2$, where $j=0,1,2,\cdots,m-1$. We can conclude that:

\begin{Lem}\label{L:Res.d.s.To.Mirabolic}
In the context of the above discussion (i.e. $F=\R$ and $n=k=1$), let $\delta$ be the discrete series representation of $G_2$ which fits into the exact sequence (\ref{E:dsExactSeq}). Then there is an exact sequence of $M_2$-representations
\[
    0 \lra \Gamma_{op} \lra \delta~\big|_{M_2} \lra \Gamma_\delta \lra 0,
\] 
where $\Gamma_{op}$ is defined as above, and $\Gamma_\delta$ has a descending filtration, with each graded piece isomorphic to the inflation of
    \[
        \chi\,{\rm sgn}^{j}|\cdot|^{j+\frac{m-1}{2}}
    \]
    to $M_2$, where $j=1,2,\cdots$.
\end{Lem}

\vskip 5pt

\begin{proof}
By our discussions, to show this lemma it suffices to show that $\Gamma_{op}\cap \Pi_f = 0$. This can be proved as in \cite[Prop. 5.2.4]{chen2021local}. 

\end{proof}


