\subsection{Rankin--Selberg models of higher corank} % (fold)
\label{sub:rankin_selberg_models_of_higher_corank}

Now back to the general case. In the proof of our main result, some more general models will be involved. Let $m\leq n$ be two non-negative integers. We set $Q_{m,n}$ to be the standard parabolic subgroup of $G_{n+1}$ with Levi component
\[
    G_{m+1}\times\underbrace{G_1\times\cdots\times G_1}_{n-m\textit{-times}},
\]
and denote its unipotent radical by $U_{m,n}$. As before, we regard $G_m$ as a subgroup of $G_{m+1}$. The corank $n+1-m$ \textit{Rankin--Selberg subgroup} of $G_{n+1}$ is defined to be
\[
    RS_{m,n} = G_m\cdot U_{m,n}.
\]
Fix a non-trivial additive character $\psi_F$ of $F$; we can define a generic character
\[
    \psi_{m,n}: U_{m,n} \lra \C, \quad u \longmapsto \psi_F\left(\sum_{i=1}^{n-m}u_{m+i,m+i+1}\right),
\]
where $u_{a,b}$ is the $\left(a,b\right)$-entry of $u\in U_{m,n}$. We are interested in determining the space
\[
    \Hom_{RS_{m,n}}\left(\pi,\sigma\boxtimes \psi_{m,n}\right)
\]
for irreducible representations $\pi$ of $G_{n+1}$ and $\sigma$ of $G_m$. These models also enjoy the multiplicity one property \cite{MR3384460}. It is worth noting that: 

\begin{itemize}
    \item when $m=n$, by definition $RS_{m,n}=G_n$, this recovers the corank $1$ model considered at the beginning of this paper;

    \vskip 5pt

    \item when $m=0$, by definition $RS_{m,n}$ is the unipotent radical of the Borel subgroup, this recovers the usual Whittaker model.
\end{itemize}

\vskip 5pt

Next we follow \cite[Sect. 6]{MR3384460} to relate these general models to the corank $1$ case. 

\begin{Prop}\label{P:ReductionToCorank1}
Let $\pi$ be a finite length representation of $G_{n+1}$, and $\sigma$ a finite length representation of $G_m$. Then there exists an exceptional subset ${\rm Ex}\subset\C^{n+1-m}$, which is a union of countably many Zariski closed proper subsets of $\C^{n+1-m}$, such that for all $\left(s_1, s_2, \cdots, s_{n+1-m}\right) \in \C^{n+1-m}\,\backslash\, {\rm Ex}$, there is a natural isomorphism
\[
    \Hom_{G_{n+1}}\left(\sigma^\vee\times I\left(s_1,s_2,\cdots,s_{n+1-m}\right)\otimes\omega_{n+1}, \pi^\vee\right) \simeq \Hom_{RS_{m,n}}\left(\pi,\sigma\boxtimes \psi_{m,n}\right).
\]
Here $I\left(s_1,s_2,\cdots,s_{n+1-m}\right)\coloneqq|\cdot|^{s_1}\times|\cdot|^{s_2}\times\cdots\times|\cdot|^{s_{n+1-m}}$.
\end{Prop}

\vskip 5pt

\begin{proof}
A similar statement in the non-Archimedean setting has been established in \cite[Sect. 6]{MR3384460}; the argument there works for the Archimedean case with some mild modifications. For the convenience of readers, we briefly sketch the proof here.

\vskip 5pt

Recall that $\omega_{n+1}$ is realized on the space of Schwartz functions on $F^{n+1}$. Consider the subspace $\omega_{n+1}^0$ of $\omega_{n+1}$ consisting of Schwartz functions supported on $F^{n+1}\backslash\left\{0\right\}$, it induces a filtration of the Weil representation
\[
    0 \lra \omega_{n+1}^0 \lra \omega_{n+1} \lra \omega_{n+1}/\omega_{n+1}^0 \lra 0.
\] 
According to Borel's lemma (Proposition \ref{P:BorelLemma}), $\omega_{n+1}/\omega_{n+1}^0$ has a filtration, with each graded piece
\[
    \left(\Sym^j\std_{n+1,\C}\right)\otimes |{\det}_{n+1}|^{-\frac{1}{2}},
\]
where $j=0,1,\cdots$. By Lemma \ref{L:inftesimalArguement}, one knows that there exists an exceptional subset ${\rm Ex}_\alpha\subset\C^{n+1-m}$, which is a union of countably many Zariski closed proper subsets, such that for all $\left(s_1, s_2, \cdots, s_{n-m+1}\right) \in \C^{n+1-m}\,\backslash\, {\rm Ex}_\alpha$, one has
\[
    \SH_i\left({G_{n+1}},\left(\sigma^\vee\times I\left(s_1,s_2,\cdots\right)\otimes\left(\Sym^j\std_{n+1,\C}\right)\otimes |{\det}_{n+1}|^{-\frac{1}{2}}\right)\otimes\pi\right) = 0
\]
for all $i,j= 0,1,2,\cdots$. This implies that
\[
    \Hom_{G_{n+1}}\left(\sigma^\vee\times I\left(s_1,s_2,\cdots\right)\otimes\omega_{n+1},\pi^\vee\right) 
    \simeq \Hom_{G_{n+1}}\left(\sigma^\vee\times I\left(s_1,s_2\cdots\right)\otimes\omega_{n+1}^0, \pi^\vee\right).
\]
\vskip 5pt

Now note that 
\[
    \omega_{n+1}^0 \simeq \left(\leftindex^u\ind_{M_{n+1}^t}^{G_{n+1}} \C\right)\otimes |{\det}_{n+1}|^{-\frac{1}{2}},
\]
where $M_{n+1}^t$ is the transpose of the mirabolic subgroup $M_{n+1}$, or equivalently, the subgroup of $G_{n+1}$ stabilizing
\[
    e_{n+1} \coloneqq \left(0,\cdots,0,1\right)^t\in F^{n+1}
\]
under the standard action. Hence we have
\[
    \sigma^\vee\times I\left(s_1,s_2,\cdots\right)\otimes\omega_{n+1}^0 \simeq |{\det}_{n+1}|^{-\frac{1}{2}}\otimes\leftindex^u\ind_{M_{n+1}^t}^{G_{n+1}} \left(\sigma^\vee\times I\left(s_1,s_2,\cdots\right)~\big|_{M_{n+1}^t}\right).
\]
To describe the representation on the right hand side of above, once again we appeal to the Mackey theory. Let $P_{m,n+1-m}$ be the standard parabolic subgroup of $G_{n+1}$ with Levi component $G_m\times G_{n+1-m}$, and $\calE_{\sigma,\underline{s}}$ the tempered vector bundle over the Grassmannian $\calX = P_{m,n+1-m}\backslash G_{n+1}$ corresponding to $\sigma^\vee\times I\left(s_1,s_2,\cdots\right)$. Similar to discussions in Section \ref{sub:orbit_analysis_on_grassmannian_rank_1_case}, there are exactly two orbits of $M_{n+1}^t$ on the $\calX$.

\vskip 5pt

$\bullet$ The closed orbit $\calZ$ consisting of $m$-dimensional subspaces $X\subset F^{n+1}$ with the property that $e_{n+1}\in X$. 
    Let $T_m$ be the stabilizer in $M_{n+1}^t$ of a representative in this orbit. It fits into an exact sequence
    \[
        1 \lra N_{m,n+1-m} \lra T_m \lra M_m^t\times G_{n+1-m} \lra 1,
    \]
    where $N_{m,n+1-m}$ is the unipotent radical of $P_{m,n+1-m}$. By some elementary computations, we know that the conormal bundle of $\calZ$ in $\calX$ is
    \[
        N_{\calZ|\calX}^\vee \simeq M_{n+1}^t\times_{T_m}\std_{n+1-m}^\vee,
    \]
    where the action of $T_m$ on $\std_{n+1-m}^\vee$ descends to $M_m^t\times G_{n+1-m}$, $G_{n+1-m}$ acts as $\std_{n+1-m}^\vee$, and $M_m^t$ acts trivially. Applying Borel's lemma, the contribution of the closed orbit (and derivatives) $\Gamma_\calZ\left(\calX,\calE_{\sigma,\underline{s}}\right)$ has a filtration, with each graded piece  
    \[
        \leftindex^u\ind_{T_m}^{M^t_{n+1}}\left(\sigma^\vee|{\det}|^{\frac{n+1-m}{2}}~\big|_{M_m^t}\boxtimes\,\Sym^j\std_{n+1-m,\C}^\vee\otimes I\left(s_1,s_2,\cdots\right)|{\det}|^{-\frac{m}{2}}\right),
    \]
    where $\sigma^\vee|{\det}|^{\frac{n+1-m}{2}}~\big|_{M_m^t}\boxtimes\,\Sym^j\std^\vee\otimes I\left(s_1,\cdots\right)|{\det}|^{-\frac{m}{2}}$ is a representation of $M_m^t\times G_{n+1-m}$, we regard it as a representation of $T_m$ by inflation; and $j=0,1,2,\cdots$. After applying the functor $|{\det}_{n+1}|^{-\frac{1}{2}}\otimes\leftindex^u\ind_{M_{n+1}^t}^{G_{n+1}}$, each graded piece becomes to
    \[
        |{\det}_{n+1}|^{-\frac{1}{2}}\otimes\leftindex^u\ind_{T_m}^{G_{n+1}}\left(\sigma^\vee|{\det}|^{\frac{n+1-m}{2}}~\big|_{M_m^t}\boxtimes\,\Sym^j\std_{n+1-m,\C}^\vee\otimes I\left(s_1,\cdots\right)|{\det}|^{-\frac{m}{2}}\right)
    \]
    \[
        \simeq \left(\sigma^\vee\otimes\omega_m\right)\times \left(\Sym^j\std_{n+1-m,\C}^\vee\otimes I\left(s_1,\cdots\right)|{\det}|^{-\frac{1}{2}}\right),
    \]
    where $j=0,1,2,\cdots$. 

    \vskip 5pt

$\bullet$ The open orbit $\calX\backslash\calZ$ consisting of $m$-dimensional subspaces $X\subset F^{n+1}$ with the property that $e_{n+1}\notin X$. Let $S_m$ be the stabilizer in $M_{n+1}^t$ of a representative in this orbit. It fits into an exact sequence
    \[
        1 \lra N^0_{m,n+1-m} \lra S_m \lra G_m\times \leftindex^wM^t_{n+1-m} \lra 1,
    \]
    where $N_{m,n+1-m}$ is the unipotent radical of $P_{m,n+1-m}$, $N^0_{m,n+1-m}$ is the subgroup of $N_{m,n+1-m}$ consisting of elements of the form 
\[
        \left(\begin{array}{ccc}
                            I_m & 0 & X\\
                            ~ & 1 & ~\\
                            ~ & ~ & I_{n-m}
                    \end{array}\right), \qquad X\in {\rm Mat}_{m,n-m}\left(F\right);
\]
and $\leftindex^wM^t_{n+1-m}$ is the subgroup of $G_{n+1-m}$ consisting of elements of the form
\[
    \left(\begin{array}{cc}
                            1 & v\\
                            ~ & g
                    \end{array}\right), \qquad g\in G_{n-m}, v\in F^{n-m}.
\]
One can easily check that $\leftindex^wM^t_{n+1-m}$ is a conjugation of $M^t_{n+1-m}$. The contribution of the open orbit $\Gamma\left(\calX\backslash\calZ,\calE_{\sigma,\underline{s}}\right)$ is
    \[
        \leftindex^u\ind_{S_m}^{M^t_{n+1}}\left(\sigma^\vee|{\det}|^{\frac{n+1-m}{2}}\boxtimes \,I\left(s_1,s_2,\cdots\right)|{\det}|^{-\frac{m}{2}}~\big|_{\leftindex^wM^t_{n+1-m}}\right),
    \]
    where $\sigma^\vee|{\det}|^{\frac{n+1-m}{2}}\boxtimes \,I\left(s_1,s_2,\cdots\right)|{\det}|^{-\frac{m}{2}}~\big|_{\leftindex^wM^t_{n+1-m}}$ is a representation of $G_m\times \leftindex^wM^t_{n+1-m}$, and we regard it as a representation of $S_m$ by inflation. After applying the functor $|{\det}_{n+1}|^{-\frac{1}{2}}\otimes\leftindex^u\ind_{M_{n+1}^t}^{G_{n+1}}$, it becomes to
    \[
        |{\det}_{n+1}|^{-\frac{1}{2}}\otimes\leftindex^u\ind_{S_m}^{G_{n+1}}\left(\sigma^\vee|{\det}|^{\frac{n+1-m}{2}}\boxtimes \,I\left(s_1,s_2,\cdots\right)|{\det}|^{-\frac{m}{2}}~\big|_{\leftindex^wM^t_{n+1-m}}\right).
    \]

\vskip 5pt

Similarly, by using the infinitesimal character argument (Lemma \ref{L:inftesimalArguement}), there exists an exceptional subset ${\rm Ex}_\beta\subset \C^{n+1-m}$, which is a union of countably many Zariski closed proper subsets, such that for all $\left(s_1, \cdots, s_{n-m+1}\right) \in \C^{n+1-m}\,\backslash\, {\rm Ex}_\beta$, one has
\[
    \SH_i\left(G_{n+1}, \left(\sigma^\vee\otimes\omega_m\right)\times \left(\Sym^j\std_{n+1-m,\C}^\vee\otimes I\left(s_1,\cdots\right)|{\det}|^{-\frac{1}{2}}\right)\otimes\pi\right) = 0
\]
for all $i,j= 0,1,2,\cdots$. This implies that
\[
    \Hom_{G_{n+1}}\left(\sigma^\vee\times I\left(s_1,s_2,\cdots\right)\otimes\omega_{n+1}^0, \pi^\vee\right) 
\]
\[
    \simeq \Hom_{G_{n+1}}\left(|{\det}_{n+1}|^{-\frac{1}{2}}\otimes\leftindex^u\ind_{S_m}^{G_{n+1}}\left(\sigma^\vee|{\det}|^{\frac{n+1-m}{2}}\boxtimes \,I\left(s_1,s_2,\cdots\right)|{\det}|^{-\frac{m}{2}}~\big|_{\leftindex^wM^t_{n+1-m}}\right), \pi^\vee\right).
\]

\vskip 5pt

Finally, we need to describe the restriction of $I\left(s_1,s_2,\cdots\right)$ to the subgroup $\leftindex^wM^t_{n+1-m}$. The restriction of a principal series representation to a mirabolic subgroup has been studied by Xue \cite[Prop. 5.1]{xue2020besselShomology} when $F=\C$, and by the first author \cite[Prop. 5.2.5]{chen2021local} when $F=\R$ using Borel's lemma. 
Consider the \textit{MVW-involution}
\[
    c: G_{n+1-m} \lra G_{n+1-m}, \quad g \longmapsto w\cdot\leftindex^{t}g^{-1}\cdot w^{-1},
\]
where $w\in G_{n+1-m}$ is a suitably chosen element. Note that the MVW-involution of $G_{n+1-m}$ takes principal series representations to principal series representations, and takes the mirabolic subgroup $M_{n+1-m}$ to $\leftindex^wM^t_{n+1-m}$. Hence we can combine \cite[Prop. 5.1]{xue2020besselShomology}, \cite[Prop. 5.2.5]{chen2021local} with the MVW-involution to describe $I\left(s_1,s_2,\cdots\right)~\big|_{\leftindex^wM^t_{n+1-m}}$. We summarize the result as follows.

\vskip 5pt

$\bullet$ The representation $I\left(s_1,s_2,\cdots\right)~\big|_{\leftindex^wM^t_{n+1-m}}$ has a subrepresentation isomorphic to
    \[
        \leftindex^u\ind_{~U_{n+1-m}}^{\leftindex^wM^t_{n+1-m}}\psi_{n+1-m}^{-1},
    \]
    where $U_{n+1-m}$ is the subgroup of $\leftindex^wM^t_{n+1-m}$ consisting of upper triangular unipotent matrices, and $\psi_{n+1-m}$ is a generic character of $U_{n+1-m}$.

\vskip 5pt

$\bullet$ The quotient 
\[
    I\left(s_1,s_2,\cdots\right)~\big|_{\leftindex^wM^t_{n+1-m}} \big/ \leftindex^u\ind_{~U_{n+1-m}}^{\leftindex^wM^t_{n+1-m}}\psi_{n+1-m}^{-1}
\]
admits a $\leftindex^wM^t_{n+1-m}$-stable filtration whose graded pieces are of the form
\[
    \leftindex^u\ind_{~Q_{a,b,c}}^{\leftindex^wM^t_{n+1-m}} \tau_a\boxtimes\tau_b\boxtimes\tau_c,
\]
where:

\begin{itemize}
    \item[-] $Q_{a,b,c}$ is the intersection of $P_{a,b,c}$ with $\leftindex^wM^t_{n+1-m}$, where $a,b,c$ are non-negative integers such that $a+b+c= n+1-m$ and $b+c>0$, $P_{a,b,c}$ is the standard parabolic subgroup of $G_{n+1-m}$with Levi component $G_a\times G_b\times G_c$; 

    \vskip 5pt

    \item[-] the group $Q_{a,b,c}$ fits into an exact sequence
    \[
     1 \lra N_{a,b,c} \lra Q_{a,b,c} \lra \leftindex^wM^t_{a}\times G_b\times G_c \lra 1,
    \]
    where $N_{a,b,c}$ is the unipotent radical of $P_{a,b,c}$;

    \vskip 5pt

    \item[-] $\tau_a$ is a representation of $\leftindex^wM^t_{a}$, and is isomorphic to $\leftindex^u\ind_{~U_{a}}^{\leftindex^wM^t_{a}}\psi_{a}^{-1}$;

    \vskip 5pt

    \item[-] $\tau_b$ is a representation of $G_b$ which is of the form $\tau'_b\otimes \rho$, where $\tau'_b$ is a principal series representation of the same form as $\tau_c$ described below, and $\rho$ is a finite dimensional representation of $G_b$;

    \vskip 5pt

    \item[-] $\tau_c$ is a principal series representation of $G_c$ which is of the form
    \[
        \chi_1|\cdot|^{s_{i_1}+k_1}\times\chi_2|\cdot|^{s_{i_2}+k_2}\times\cdots\times\chi_c|\cdot|^{s_{i_c}+k_c},
    \]
    where $1\leq i_1,i_2,\cdots,i_c\leq n+1-m$, $\chi_1,\chi_2,\cdots,\chi_c$ are (conjugate) self-dual characters of $F^\times$, and $k_1,k_2,\cdots,k_c\in \Z$;

    \vskip 5pt

    \item[-] $\tau_a\boxtimes\tau_b\boxtimes \tau_c$ is a representation of $\leftindex^wM^t_{a}\times G_b\times G_c$, regarded as a representation of $Q_{a,b,c}$ by inflation. 
\end{itemize}
\vskip 5pt

Easy to check that
\[
    |{\det}_{n+1}|^{-\frac{1}{2}}\otimes\leftindex^u\ind_{S_m}^{G_{n+1}}\left(\sigma^\vee|{\det}|^{\frac{n+1-m}{2}}\boxtimes \,\left(\leftindex^u\ind_{~Q_{a,b,c}}^{\leftindex^wM^t_{n+1-m}} \tau_a\boxtimes\tau_b\boxtimes\tau_c\right)|{\det}_{n+1-m}|^{-\frac{m}{2}}\right)
\]
\[
    \simeq \leftindex^u\ind_{RS_{m,m+a-1}}^{G_{m+a}} \left(\sigma^\vee|\det|^{\frac{a-1}{2}}\boxtimes\psi^{-1}_{m,m+a-1}\right)\times \tau_b|\det|^{\ell_b}\times\tau_c|\det|^{\ell_c}
\]
for some half integer $\ell_b,\ell_c\in\frac{1}{2}\Z$. Once again, by using the infinitesimal characters argument (Lemma \ref{L:inftesimalArguement}), one can show that there exists an exceptional subset ${\rm Ex}_\gamma\subset\C^{n+1-m}$, which is a union of countably many Zariski closed proper subsets, such that for all $\left(s_1, s_2, \cdots, s_{n-m+1}\right) \in \C^{n+1-m}\,\backslash\, {\rm Ex}_\gamma$, one has
\[
    \SH_i\left(G_{n+1}, \left(\leftindex^u\ind_{RS_{m,m+a-1}}^{G_{m+a}} \left(\sigma^\vee|\det|^{\frac{a-1}{2}}\boxtimes\psi^{-1}_{m,m+a-1}\right)\times \tau_b|\det|^{\ell_b}\times\tau_c|\det|^{\ell_c}\right)\otimes \pi\right) = 0
\]
for all $i=0,1,2,\cdots$ and all $\leftindex^u\ind_{~Q_{a,b,c}}^{\leftindex^wM^t_{n+1-m}} \tau_a\boxtimes\tau_b\boxtimes\tau_c$. This implies that
\[
    \Hom_{G_{n+1}}\left(|{\det}_{n+1}|^{-\frac{1}{2}}\otimes\leftindex^u\ind_{S_m}^{G_{n+1}}\left(\sigma^\vee|{\det}|^{\frac{n+1-m}{2}}\boxtimes \,I\left(s_1,s_2,\cdots\right)|{\det}|^{-\frac{m}{2}}~\big|_{\leftindex^wM^t_{n+1-m}}\right), \pi^\vee\right)
\]
\[
    \simeq \Hom_{G_{n+1}}\left(\leftindex^u\ind_{RS_{m,n}}^{G_{n+1}} \left(\sigma^\vee|\det|^{\frac{n-m}{2}}\boxtimes\psi_{m,n}^{-1}\right),\pi^\vee\right).
\]
Let ${\rm Ex} = {\rm Ex}_\alpha\cup{\rm Ex}_\beta\cup{\rm Ex}_\gamma$ and combine all these isomorphisms, we eventually get
\[
    \Hom_{G_{n+1}}\left(\sigma^\vee\times I\left(s_1,s_2,\cdots\right)\otimes\omega_{n+1},\pi^\vee\right)
    \simeq \Hom_{RS_{m,n}}\left(\pi,\sigma\boxtimes \psi_{m,n}\right)
\]
for all $\left(s_1, s_2, \cdots, s_{n+1-m}\right) \in \C^{n+1-m}\,\backslash\, {\rm Ex}$ as desired. This completes the proof.

\end{proof}

\vskip 5pt

Combine Lemma \ref{L:FJToBessel} and Proposition \ref{P:ReductionToCorank1}, we obtain the following consequence.  
\begin{Cor}\label{C:ExchangeVariables}
Let $\pi$ be a finite length representation of $G_{n+1}$, and $\sigma$ a finite length representation of $G_n$. Then there exists a (at most) countable subset ${\rm Ex}\subset\sqrt{-1}\cdot\R$, such that for all $s_1, s_2\in \sqrt{-1}\cdot\R\,\backslash\, {\rm Ex}$, there is a natural isomorphism
\[
    \Hom_{G_n}\left(\pi,\sigma\right) \simeq \Hom_{G_{n+1}}\left(|\cdot|^{s_1}\times\sigma^\vee\times|\cdot|^{s_2},\pi^\vee\right).
\]   
\end{Cor}


