\section{Type II theta correspondence} % (fold)
\label{sec:type_ii_theta_correspondence}

\subsection{Results on theta correspondence} % (fold)
\label{sub:results_on_theta_correspondence}

In this section we give a quick review of type II theta correspondence and recall a result on irreducibility of the big theta lifting, which will be used later. 

\vskip 5pt

Let $M_{n,m}$ be the space of $n\times m$ matrices over $F$, and $\calS\left(M_{n,m}\right)$ the space of Schwartz functions over $M_{n,m}$, equipped with the group action of $G_n\times G_m$ given by
\begin{equation}\label{E:DefWeilRep}
    \left(\omega_{n,m}\left(g,h\right)\varphi\right)\left(X\right) = |\det g|^{-\frac{m}{2}}|\det h|^{\frac{n}{2}}\varphi\left(g^{-1}Xh\right),
\end{equation}
where $\left(g,h\right)\in G_n\times G_m$, $\varphi\in \calS\left(M_{n,m}\right)$ and $X\in M_{n,m}$. This is the so-called \textit{Weil representation} associated to $G_n\times G_m$. The twist $|\det g|^{-\frac{m}{2}}|\det h|^{\frac{n}{2}}$ here is to make this representation \textit{unitary} under the inner product of $L^2$-functions. %We shall always assume that $n\leq m$ unless otherwise stated. 
Given any irreducible smooth representation $\pi$ of $G_n$, one can consider the maximal $\pi$-isotypic quotient of $\omega_{n,m}$, the so-called ``\textit{big theta lift}''
\[
   \Theta_{n,m}\left(\pi\right) = \left(\omega_{n,m}\otimes\pi^\vee\right)_{G_n},
\]
as a representation of $G_m$. It is known that $\Theta_{n,m}\left(\pi\right)$ is of finite length. We have the celebrated \textit{Howe duality}, see \cite[Sect. III.9]{MR1005856} for the Archimedean case, and M\'inguez \cite[Thm. 1]{MR2504432} for the non-Archimedean case.

\begin{Thm}[Howe duality]\label{T:HoweDuality}
Suppose that $n\leq m$.  

\begin{enumerate}
    \item For any irreducible representation $\pi$ of $G_n$, the big theta lift $\Theta_{n,m}\left(\pi\right)$ has a unique irreducible quotient $\sigma$, such that
    \[
        \Hom_{G_n\times G_m}\left(\omega_{n,m},\pi\boxtimes\sigma\right) \neq 0,
    \]
    and the dimension of this Hom space is $1$.

    \vskip 5pt

    \item This representation $\sigma$ is an irreducible constituent of the parabolic induced representation $\pi^\vee\times\mathbbm{1}_{m-n}$, where $\mathbbm{1}_{m-n}$ is the trivial representation of $G_{m-n}$.
\end{enumerate}
\end{Thm} 

\vskip 5pt

We have the following criterion for the irreducibility of the big theta lift $\Theta_{n,m}\left(\pi\right)$.

\begin{Prop}\label{P:IrredBigTheta}
Suppose that $n\leq m$. Let $\pi$ be an irreducible unitary representation of $G_n$, such that its Godement--Jacquet L-function $L\left(s,\pi\right)$ is holomorphic at $s=\frac{1+m-n}{2}$. Then the big theta lift of $\pi$
\[
    \Theta_{n,m}\left(\pi\right) \simeq \pi^\vee\times\mathbbm{1}_{m-n}
\]   
is irreducible.
\end{Prop}

\vskip 5pt

This proposition was first proved by Fang--Sun--Xue \cite[Cor. 1.5]{MR3803804} in the case $n=m$, and then generalized by the second author and his collaborators in the non-Archimedean case. For the sake of completeness, we shall provide a proof in Appendix \ref{App:IrredBigTheta}.

