\subsection{Bessel versus Fourier--Jacobi} % (fold)
\label{sub:bessel_versus_fourier_jacobi}

Next we appeal to a well-known seesaw diagram to connect Bessel models with Fourier--Jacobi models. This connection between the two models indicates a ``symmetry'' inside Bessel models, which is one of the ingredients we need in our later proof.

\vskip 5pt

\begin{Lem}\label{L:BesselToFJ}
Let $\pi$ be an irreducible unitary representation of $G_{n+1}$, and $\sigma$ an irreducible unitary representation of $G_n$. Then there exist (infinitely many) unitary characters $\xi$ of $G_1$, such that there is an isomorphism 
\[
    \Hom_{G_n}\left(\pi,\sigma\right) \simeq \Hom_{G_{n+1}}\left(\left(\sigma^\vee\times\xi\right)\otimes \omega_{n+1},\pi^\vee\right).
\]   
\end{Lem}

\vskip 5pt

\begin{proof}
Let $\xi = |\cdot|^s$ be a unitary character of $G_1$, where $s\in \sqrt{-1}\cdot\R$ is purely imaginary, such that $L\left(s,\pi^\vee\xi^{-1}\right)$ is holomorphic at $s=\frac{1}{2}$, and $L\left(s,\sigma\xi\right)$ is holomorphic at $s=1$. Obviously we have
\[
    \Hom_{G_n}\left(\pi,\sigma\right) \simeq \Hom_{G_n}\left(\pi\xi,\sigma\xi\right).
\]
Consider the seesaw diagram:
\[
\begindc{\commdiag}[6]
\obj(60,40)[aa]{$G_{n+1}\times G_{n+1}$}
\obj(57,38)[a]{$~$}
