\section{Setting the Stage: Context and Preliminaries}\label{chap: preliminary}


\subsection{Admissible signatures}\label{sec: admissible signature}

In this section, we introduce the notion of a signature $\sigma$, which can be viewed as an ordering of vectors and covectors.
Let $a, b, n, d\in \Z$ be non-negative integers such that $n = a+b \ge 3$ and $d \ge 3$. We denote by $[i, j]$ the set of all integers $k\in \Z$ satisfying $i\le k \le j$. 

\begin{defn}\label{defn: signature}
	A  \emph{(size $n$) signature of type $(a, b)$} is a map:
	\begin{equation}
		\sigma: \Z \rightarrow \{-1, 1\}
	\end{equation}
	such that 
	\begin{enumerate}[label = {\textbf{(\alph*)}}, wide, labelwidth=!, labelindent=0pt]
		\item $\sigma(j + n ) = \sigma(j)$ for $j\in \Z$ (periodicity),
		\item $\#\{\sigma^{-1}(1)\cap [1, n]\} = a$ and $\#\{\sigma^{-1}(-1)\cap [1, n]\} = b$.
	\end{enumerate}
	%Note that $n = a+b$. 
	For an index $j\in \Z$, we say $j$ (or $j \bmod d$) is a \emph{black vertex} (resp., \emph{white vertex}) if $\sigma(j) = 1$ (resp., $\sigma(j) = -1$).
\end{defn}

\begin{remk}\label{remk: interpretation of a signature}
	A signature $\sigma$ of type $(a, b)$ equivalently defines a cyclic word of length $n$ over $\{\bullet, \circ\}$ with $a$ black vertices $\bullet$ and $b$ white vertices $\circ$. We denote this as $\sigma = [\sigma_1\, \sigma_2\, \cdots\, \sigma_n]$, where $\sigma(j) = \sigma_j$ for $j \in [1, n]$.
\end{remk}


\begin{example}
	Figure~\ref{fig: example of a signature} shows the signature $\sigma = [\bullet\, \bullet\, \circ\, \bullet\, \circ\, \bullet]$ of type $(4, 2)$, where $\sigma(1) = \sigma(2) = \sigma(4) = \sigma(6) = 1$ and $\sigma(3) = \sigma(5) = -1$.
\end{example}

