		\centering
		\begin{tikzcd}
			&1 & 2 \arrow[d] \arrow[l]  & \boxed{3}   \arrow[l]   \\
			&	{7} \arrow[u] \arrow[d] \arrow[ur]  & {8} \arrow[d]&  \\
			4 \arrow[r] & 5 \arrow[r] & 6 \arrow[ul] & 	
		\end{tikzcd}
		\caption{The quiver of the amalgamated seed.}
		\label{fig: example of gluing two seeds}
	\end{figure}

\end{example}


\begin{remk}\label{remk: properties of amalgamation}
	Amalgamation has the following important properties.
	\begin{itemize}[wide, labelwidth=!, labelindent=0pt]
		\item \textbf{Commutation with mutations}. With the same notation as in Definition~\ref{defn: amalgamating two seeds}, let $z\in \zz_1$ be a cluster variable. Then 
		\[
		\glueseeds{\mu_z(\seed_1)}{\seed_2}{\zz_0} = \mu_z(\glueseeds{\seed_1}{\seed_2}{\zz_0}).
		\]
		\item \textbf{Associativity}. Let $\seed_i = (Q_i, \zz_i)$, $i = 1, 2, 3$, be three seeds in $\msf$. Suppose  that $\seed_1$ and $\seed_2$ can be amalgamated along $\zz_0:= \zz_1\cap \zz_2$; $\seed_2$ and $\seed_3$ can be amalgamated along  $\zz'_0 := \zz_2\cap \zz_3$. Furthermore, suppose that $\zz'_0\cap \zz_0 = \emptyset$. Then 
		\[
		\glueseeds{(\glueseeds{\seed_1}{\seed_2}{\zz_0})}{\seed_3}{\zz'_0} = \glueseeds{\seed_1}{(\glueseeds{\seed_2}{\seed_3}{\zz'_0})}{\zz_0}.
		\]
	\end{itemize}	
\end{remk}

















\subsection{Combinatorics of (Demazure) weaves}\label{sec: combinatorics of weaves}

The diagrammatic planar calculus of weaves, introduced by Casals and Zaslow \cite{CasalsZaslow} and further developed in \cite{CasalsWeng,CasalsLeSBWeng,CGGS,CGGLSS}, provides tools to construct cluster structures in algebraic varieties. We begin with foundational definitions.

\begin{defn}[{\cite[Definition 2.25]{CasalsLeSBWeng}}] For $d\in\Z_{>0}$, a \emph{$d$-weave}  $\ww$ is a particular kind of a planar graph properly embedded in a topological 2-disk, with edges labeled by elements in $[1, d-1]$. Vertices on the disk boundary are \emph{boundary vertices}; others are \emph{internal}. Each internal vertex must conform to one of the types in Figure~\ref{fig:allowable vertices}. Boundary vertex have degree $1$. Edges of $\ww$ are also referred to as \emph{weave lines}. Certain boundary vertices are designated as \emph{marked boundary vertices}. Weave lines incident to boundary vertices are \emph{external weave lines}. See Figure~\ref{fig: example of a 4-weave} for an example of a $4$-weave.\\

	\noindent Elements of $[1,d-1]$ are referred to as the \emph{colors} of the edges of a $d$-weave. We often refer to $d$-weaves simply as \emph{weaves} if $d$ is clear from the context.
	\begin{figure}[H]
		\centering
		\includegraphics[trim = 18.5cm 22cm 20cm 20cm, clip = true, scale = 0.55]{allowable_vertices.pdf}
		\caption{Allowable vertex types in a weave. For a 3-valent vertex, all labels must be of the same color. For a 4-valent vertex, the labels must alternate between two non-adjacent different colors. For a 6-valent vertex, the labels must alternate between two adjacent colors.}
		\label{fig:allowable vertices}
	\end{figure}
\end{defn}

\begin{example}
	A $2$-weave corresponds to a trivalent graph embedded in the $2$-disk (with marked boundary vertices). Figure~\ref{fig: example of a 4-weave} is an example of a $4$-weave.
