To allow local analysis of Demazure weaves, we introduce the notion of \emph{row words} and \emph{partial weaves}. 

\begin{defn}\label{defn: scanning process and row words}
	Let $\ww$ be a Demazure weave. By toggling the vertices, we may assume that they are at different heights. Now consider a horizontal scanning line that connects the left and right boundaries of $\ww$. If a scanning line does not pass through any vertices, we can form a word by recording the color of weave lines that intersect with the scanning line, from left to right. Such a word is called a \emph{row word of $\ww$}. 

	Let $\ww_\text{top}$ (resp. $\ww_\text{bottom}$) be the row word when the scanning line is at the top (resp. bottom) boundary of $\ww$. We will usually write $\ww: \ww_\text{top} \rarrow \ww_\text{bottom}.$
	We will also use similar notation to describe a portion of a weave between two horizontal lines.

	As the scanning line moves from top to bottom, the row words are transformed as follows:
	\begin{itemize}[wide, labelwidth=!, labelindent=0pt]
	\item when the scanning line does not move through a vertex, the row word remains unchanged; 
	\item when the scanning line moves through a trivalent vertex, cf.\ Figure~\ref{fig:local transformations when passing through a vertex}, the row word is transformed as follows: $\cdots i  i \cdots \rarrow \cdots i \cdots$;
	\item when the scanning line moves through 4-valent vertex, cf.\ Figure~\ref{fig:local transformations when passing through a vertex}, the row word is transformed as follows: $\cdots i  j \cdots \rarrow \cdots j  i  \cdots$;
	\item when the scanning line moves through 6-valent vertex, cf.\ Figure~\ref{fig:local transformations when passing through a vertex}, the row word is transformed as follows: $\cdots i  j  i \cdots \rarrow \cdots j  i j \cdots$.
	\end{itemize}


	\begin{figure}[H]
		\centering
		\includegraphics[trim = 11.5cm 12cm 0cm 12cm, clip = true, scale = 0.47]{local_transformations_when_passing_through_a_vertex.pdf}
		\caption{Row word transformations via vertex crossings. Dashed lines: scanning lines.}
		\label{fig:local transformations when passing through a vertex}
	\end{figure}
	The last two transformations are called \emph{braid moves}. Let $\beta, \beta'$ be two words. We say that they are \emph{braid equivalent}, denoted by $\beta\sim \beta'$, if they are related by a sequence of braid moves. Notice that for a Demazure weave $\ww: \beta\rarrow \beta'$, we have $\beta \sim \beta'$ if and only if $\ww$ contains only 4-valent and 6-valent vertices.
\end{defn}

\begin{defn}	
	Let $\ww: \beta\rarrow \beta'$ be a Demazure weave. Let $\beta_1, \beta_2$ be two row words for $\ww$, with $\beta_1$ above $\beta_2$. The portion of the weave that is between $\beta_1$ and $\beta_2$ is called \emph{a partial weave of $\ww$}, denoted by $\beta_1\stackrel{\ww}{\rarrow} \beta_2$ (or simply $\beta_1\rarrow \beta_2$ when $\ww$ is clear from the context). 

	A Demazure weave $\ww: \beta\rarrow \beta'$ can be interpreted as a concatenation of partial weaves of $\ww$ along the row words. We express this as
	\[
	\ww: \beta = \beta_0 \rarrow \beta_1 \rarrow \beta_2 \rarrow \cdots \rarrow \beta_{s-1} \rarrow \beta_s = \beta'
	\]
	where $\beta_i$ are row words for $\ww$, $0\le i \le s$.
\end{defn}


\begin{remk}
We will view a partial weave of $\ww$ with $\ww_{\text{top}}$ as the top word as a Demazure weave with the same set of marked boundary vertices (as $\ww$). However, a partial weave $\beta_1\rarrow \beta_2$ with $\beta_1 \neq \ww_{\text{top}}$ will not be viewed as a Demazure weave in general; as the information concerning the marking is lost in general. 
\end{remk}

\begin{example}
	let $\ww$ be the Demazure 4-weave shown in Figure~\ref{fig: example of a demazure 4-weave}. Toggle the trivalent vertex $v$ to be above the trivalent vertex $w$. Then $\ww$ can be decomposed as
	\[
	\ww: \ww_{\text{top}} = 321122 \rarrow  32122 \rarrow  3212 \rarrow  3121 \rarrow 1321 = \ww_{\text{bottom}}.
	\]
\end{example}

To construct a cluster algebra, we associate a quiver $Q(\ww)$ to a Demazure weave~$\ww$, cf.\ \cite[Section~4.4]{CGGLSS}. The vertices of $Q(\ww)$ correspond to \emph{Lusztig cycles} of $\ww$ (Definition~\ref{defn:Lusztig cycles}), while its arrows derive from the  intersection pairings between the corresponding Lusztig cycles (Definition~\ref{defn:local intersection pairing}).


\begin{defn}[{\cite[Definition 2.33]{CasalsLeSBWeng}}]\label{defn:Lusztig cycles} Let $\ww$ be a Demazure weave. Let $v$ be either a marked boundary vertex or a trivalent vertex in $\ww$. The \emph{(Lusztig) cycle} $\gamma = \gamma_v$ associated with $v$ is a function on the edges of $\ww$, constructed by scanning $\ww$ from top to bottom, as follows.
	\begin{itemize}[wide, labelwidth=!, labelindent=0pt]
		\item For any weave line $e$ that begins above $v$, we have $\gamma(e)=0$.
		\item For the unique weave line $e$ that begins at $v$, we have $\gamma(e)=1$.
		\item For any trivalent vertex $w$ below $v$, we have (cf.\ Figure~\ref{fig: trivalent 4-valent and 6-valent label}):
		\[\gamma(b)=\min\{\gamma(a), \gamma(c)\},
		\]
		where $b$ is the weave line that begins at $w$, and $a, c$ are weave lines end at $w$.
		\item For any 4-valent vertex $w$, we have (cf.\ Figure~\ref{fig: trivalent 4-valent and 6-valent label}):
		\[
		\gamma(c)=\gamma(a), \quad \gamma(b)=\gamma(d),
		\]where $a,b,c,d$ are weave lines incident to $w$ listed in a cyclic order.
		\item For any 6-valent vertex $w$, we have (cf.\ Figure~\ref{fig: trivalent 4-valent and 6-valent label}):
		\begin{align*}
		\gamma(b)&=\gamma(f)+\gamma(e)-\min\{\gamma(a),\gamma(e)\},\\
		 \gamma(c)&=\min\{\gamma(a),\gamma(e)\},\\ 
		 \gamma(d)&=\gamma(a)+\gamma(f)-\min\{\gamma(a),\gamma(e)\},
		\end{align*}
		where $a,b,c,d,e,f$ are weave lines incident to $w$ in a cyclic order, with $a,f,e$ above $w$ and $b,c,d$ below $w$.
	\end{itemize}
\end{defn}

	\begin{figure}[H]
		\centering
		\includegraphics[trim= 12.5cm 18cm 20cm 18.7cm, clip = true, scale = 0.58]{trivalent_4-valent_and_6-valent_label.pdf}
		\caption{Edge labelings around trivalent, 4-valent and 6-valent vertices.}
		\label{fig: trivalent 4-valent and 6-valent label}
	\end{figure}


	Such a (Lusztig) cycle $\gamma$ can be interpreted as an oriented weighted subgraph ~$G_\gamma$ of ~$\ww$. An edge $e$ in $\ww$ belongs to $G_\gamma$ if $\gamma(e) \neq 0$; its weight is equal to $\gamma(e)$. Graphically cycles follow the rules shown in Figure~\ref{fig: local cycle types}.	


