	\includegraphics[trim= 0cm 9cm 4cm 4.5cm, clip = true, scale = 0.27]{local_cycle_types.pdf}
	\caption{Local rules for a cycle. A thickened edge indicates that the value of the cycle on that edge is $1$; otherwise the value is $0$.}
	\label{fig: local cycle types}
\end{figure}

\begin{defn}\label{defn: mutable and frozen cycles}
	A cycle is \emph{frozen} if it meets with a boundary vertex. Otherwise it is \emph{mutable}. Notice that there are two types of frozen cycles: one that originating from the marked boundary vertices; the other that originating from a trivalent vertex, but ending at the bottom boundary of the weave. 
\end{defn}

