The number of arrows between two vertices of the quiver associated with a Demazure weave is the \emph{intersection pairing} between the corresponding cycles. 


\begin{defn}[{\cite[Definition 2.28]{CasalsLeSBWeng}}]\label{defn:local intersection pairing} Let $V_\ww$ denote the set of internal vertices in a weave $\ww$. For any two cycles $\gamma, \gamma'$, their \emph{intersection pairing} is defined by
	\begin{equation}
		\inprod{\gamma}{\gamma'}:=\sum_{v\in V_\ww}\inprod{\gamma}{\gamma'}_v,
	\end{equation}
	where we use the notation
	\[
	\inprod{\gamma}{\gamma'}_v:=\left\{\begin{array}{ll}\vspace{1cm}  \begin{vmatrix}
			1 & 1 & 1 \\
			\gamma(a) & \gamma(b) & \gamma(c)\\
			\gamma'(a) & \gamma'(b) & \gamma'(c)
		\end{vmatrix} & \text{if } v \text{ is trivalent},\\
		\vspace{1cm}
		\frac{1}{2}\left(\begin{vmatrix} 1 & 1 & 1\\
			\gamma(a) & \gamma(c) & \gamma(e) \\
			\gamma'(a) & \gamma'(c) & \gamma'(e)
		\end{vmatrix} +\begin{vmatrix} 1 & 1 & 1\\
			\gamma(b) & \gamma(d) & \gamma(f) \\ 
			\gamma'(b) & \gamma'(d) & \gamma'(f)
		\end{vmatrix}\right) & \text{if } v \text{ is } 6\text{-valent}, \\
		0 & \text{otherwise,}
	\end{array}\right.
	\]
	and the edges labels are as shown in Figure~\ref{fig: trivalent and 6-valent labeled}.
	\end{defn}
