We next describe equivalence and mutation equivalence between Demazure weaves and show that the quiver associated with Demazure weaves are well-behaved under equivalence and mutation equivalence. 


\begin{defn}[{\cite[Section 4.2]{CGGLSS}}]\label{defn: weave equivalence moves}
	Two Demazure weaves with the same marked boundary vertices are \emph{equivalent} if they are related by a sequence of \emph{(local) equivalence moves}, defined as follows:
	\begin{enumerate}[wide, labelwidth=!, labelindent=0pt]
		\item[(i)] Let $\ww,\ww':\beta\rarrow\beta'$ contain only  4-valent and 6-valent vertices (equivalently $\beta\sim \beta'$). Then $\ww$ and $\ww'$ are equivalent. For example, the partial weaves $ij \rarrow ji \rarrow ij$ and $ij \rarrow ij$ (cf.\ left of Figure~\ref{fig: 4-valent and 6-valent only equivalent move}) are equivalent, where $|i-j|>1$; the partial weaves $iji\rarrow jij \rarrow iji$ and $iji \rarrow iji$ (cf.\ right of Figure~\ref{fig: 4-valent and 6-valent only equivalent move}) are equivalent, where $|i-j| = 1$.
		 \begin{figure}[H]
		 	\centering
		 	{\includegraphics[trim= 2cm 9cm 10cm 12cm, clip = true, scale = 0.3]{4-valent_and_6-valent_only_equivalent_move.pdf}}
		 	\caption{Equivalence moves with only 4-valent and 6-valent vertices.}
		 	\label{fig: 4-valent and 6-valent only equivalent move}
		 \end{figure}
		\item[(ii)] [\textbf{Pushthrough from below.}] Suppose that $|i-j| = 1$. Then the partial weaves $ijij\rarrow jijj\rarrow jij$ and $ijij\rarrow iiji\rarrow iji\rarrow jij$ (cf.\ Figure~\ref{fig: equivalence pushthrough from below}) are equivalent. The mirror image version of this equivalence is defined in a similar way.
		\begin{figure}[H]
			\centering
			{\includegraphics[trim= 8cm 9.1cm 10cm 14.5cm, clip = true, scale = 0.45]{equivalence_pushthrough_from_below.pdf}}
			\caption{Pushthrough from below, $|i-j| = 1$.}
			\label{fig: equivalence pushthrough from below}
		\end{figure}
		\item[(ii$'$)] [\textbf{Pushthrough from above.}] Suppose that $|i-j| = 1$. Then the partial weaves $ijii\rarrow iji \rarrow jij$ and $ijii\rarrow jiji\rarrow jjij\rarrow jij$ (cf.\ Figure~\ref{fig: equivalence pushthrough from above}) are equivalent. The mirror image version of this equivalence is defined in a similar way.
		\begin{figure}[H]
			\centering
			\includegraphics[trim= 7cm 6.1cm 5cm 15.1cm, clip = true, scale = 0.41]{equivalence_pushthrough_from_top.pdf}
			\caption{Pushthrough from above, $|i-j| = 1$.}
			\label{fig: equivalence pushthrough from above}
		\end{figure}
		\item[(iii)] Suppose that $|i-j| > 1$. Then the partial weaves $iji\rarrow iij\rarrow ij\rarrow ji$ and $iji\rarrow jii\rarrow ji$ (cf.\ Figure~\ref{fig: Equivalence Passthrough}) are equivalent. In other words, one can move a $j$-colored strand through an $i$-colored trivalent vertex.
	\end{enumerate}	
