		\caption{Passthrough a trivalent vertex, $|i-j|>1$.}
		\label{fig: Equivalence Passthrough}
	\end{figure}
\end{defn}


\begin{defn}
	The move depicted in Figure~\ref{fig: local mutation move} is called a \emph{weave mutation move}. Two Demazure weaves are called \emph{mutation equivalent} if they are related by a sequence of mutation moves and equivalence moves. 
	\begin{figure}[H]
		\centering
		{\includegraphics[trim= 7cm 8cm 14.5cm 15.8cm, clip = true, scale = 0.41]{local_mutation_move2.pdf}}
		\caption{Local mutation move.}
		\label{fig: local mutation move}
	\end{figure}
\end{defn}

\begin{remk}\label{remk: correspondence of cycles under mutation equivalence}
	For each local equivalence move and mutation move, there is a distinguished 1-1 correspondence between the trivalent vertices before and after the move.  For the local equivalence moves, there is at most one trivalent vertex, so the choice of correspondence is unique. For the local mutation move, $v$ and $w$ correspond to $v'$ and $w'$ respectively, cf.\ Figure~\ref{fig: local mutation move}. This 1-1 correspondence induces a 1-1 correspondence between the cycles of two mutation equivalent Demazure weaves. 
\end{remk}

We say an edge of a Demazure weave a \emph{bottom edge} if it is incident to the bottom boundary of the weave. 

\begin{lemma}\label{lemma: cycles end behavior remain unchanged under mutation}
	Mutation equivalent weaves preserve cycle weights on bottom edges. 
\end{lemma}
\begin{proof}
	Let $\ww, \ww': \beta\rarrow \beta'$ be two mutation equivalent Demazure weaves. Fix a sequence of local equivalence moves and local mutation moves that transform $\ww$ to $\ww'$. Let $\gamma$ be a cycle in $\ww$ and $\gamma'$ be the corresponding cycle in $\ww'$ (see Remark~ \ref{remk: correspondence of cycles under mutation equivalence}). We need to show that $\gamma(e) = \gamma'(e)$ for any bottom edge $e$. 

	As $\ww$ and $\ww'$ are related by a sequence of local equivalence moves and local mutation moves, we only need to prove the result if $\ww$ and $\ww'$ are related by a single equivalence move or a single mutation move. Here we demonstrate the proof for one move, the proof for other moves is similar. 

	Consider the local equivalence move (ii): Pushthrough from below, cf.\ Figure~\ref{fig: equivalence pushthrough from below same cycles}. Assume that $\gamma \neq \gamma_v$ (hence $\gamma' \neq \gamma_{v'}$). We have $\gamma = \gamma'$ on $a, b, c, d$, and we need to show that $\gamma = \gamma'$ on $l, h, n$. 
	\begin{figure}[H]
		\centering
		\includegraphics[trim = 3.5cm 12.5cm 0cm 13cm, clip = true, scale = 0.44]{equivalence_pushthrough_from_below_same_cycles.pdf}
		\caption{Two Demazure weaves related by a Pushthrough from below.}
		\label{fig: equivalence pushthrough from below same cycles}
	\end{figure}
	Using the definition of (Lusztig) cycles (cf.\ \ref{defn:Lusztig cycles}), we have
	\begin{equation*}
		\begin{split}
			\gamma'(h) &=\min\{\gamma'(g), \gamma'(f)\}\\
			&= \min\{\min\{\gamma'(a), \gamma'(e)\}, \gamma'(c)+\gamma'(b) - \min\{\gamma'(b), \gamma'(d)\}\}\\
			&= \min\{\gamma(a), \gamma'(e),\gamma(c)+\gamma(b) - \min\{\gamma(b), \gamma(d)\} \}\\
			&= \min\{\gamma(a), \gamma(c)+\gamma(d) - \min\{\gamma(b), \gamma(d)\},\gamma(c)+\gamma(b) - \min\{\gamma(b), \gamma(d)\} \}\\
			&= \min\{\gamma(a), \min\{\gamma(c)+\gamma(d) - \min\{\gamma(b), \gamma(d)\},\gamma(c)+\gamma(b) - \min\{\gamma(b), \gamma(d)\}\} \}\\
			& = \min\{\gamma(a), \gamma(c) - \min\{\gamma(b), \gamma(d)\} + \min\{\gamma(d)\},\gamma(b) \}\}\\
			& = \min\{\gamma(a), \gamma(c)\} = \gamma(h).
		\end{split}			
	\end{equation*}
	Now notice that $\gamma(h) + \gamma(l) = \gamma(b) + \gamma(c)$ and $\gamma'(h) + \gamma'(l) = \gamma'(k) + \gamma'(f) = \gamma'(b) + \gamma'(c)$, we get $\gamma(l) = \gamma'(l)$. Lastly, we have 
	\[
	\gamma(n) = \min\{\gamma(m), \gamma(d)\} = \min\{\gamma(a) + \gamma(b) - \min\{\gamma(a), \gamma(c)\}, \gamma(d)\}.
	\]
	and 
	\begin{equation*}
		\begin{split}
	\gamma'(n) &= \gamma'(g) + \gamma'(k) - \gamma(h)\\
	& = \min\{\gamma(a), \gamma'(e)\} + \min\{\gamma(b), \gamma(d)\} - \min\{\gamma(a), \gamma(c)\}\\
	& = \min\{\gamma(a), \gamma(c) + \gamma(d) - \min\{\gamma(b), \gamma(d)\}\} + \min\{\gamma(b), \gamma(d)\} - \min\{\gamma(a), \gamma(c)\}\\
	& = \min\{\gamma(a)+ \min\{\gamma(b), \gamma(d)\}, \gamma(c) + \gamma(d)\}  - \min\{\gamma(a), \gamma(c)\}\\
	& =  \min\{\gamma(a) + \gamma(b) - \min\{\gamma(a), \gamma(c)\}, \gamma(d)\}.
	\end{split}			
	\end{equation*}
The last identity is obtained by troplicalizing the identity
\[
\frac{t^{\gamma(a)}(t^{\gamma(b)}+t^{\gamma(d)}) + t^{\gamma(c)}t^{\gamma(d)}}{t^{\gamma(a)} + t^{\gamma(c)}} = \frac{t^{\gamma(a)}t^{\gamma(b)}}{t^{\gamma(a)} + t^{\gamma(c)}} + t^{\gamma(d)}.
\]
Hence $\gamma'(n) = \gamma(n)$. 

Finally, notice that $\gamma_v(l) = \gamma_v(h) = \gamma_{v'}(l) = \gamma_{v'}(h) = 0$ and $\gamma_v(n) = \gamma_{v'}(n) = 1$. This completes the proof.
\end{proof}

The next Proposition justifies the notion of mutation equivalence of Demazure weaves. 
\begin{prop}\label{prop: mutation equivalent weaves yield mutation equivalent quivers}
	Let $\ww, \ww': \beta\rarrow \beta'$ be two equivalent (resp. mutation equivalent) Demazure weaves. Then the quivers associated with $\ww, \ww'$ are the same (resp., mutation equivalent), i.e., $Q(\ww) = Q(\ww')$ (resp., $Q(\ww) \sim Q(\ww')$). 
\end{prop}

\begin{proof}
	Let us first assume that $\ww$ and $\ww'$ are equivalent Demazure weaves. By definition, they are related by a sequence of local equivalence moves. So we only need to show that $Q(\ww) = Q(\ww')$ if $\ww$ and $\ww'$ are related by a single local equivalence move. Here we will demonstrate the proof for one move, the proof for other moves is similar. 

	Consider the local equivalence move (ii): Pushthrough from below, cf.\ Figure~\ref{fig: equivalence pushthrough from below same cycles}. Let $\gamma_1, \gamma_2$ be two different cycles in $\ww$, the corresponding cycles in $\ww'$ are denoted by $\gamma'_1, \gamma'_2$ respectively. We need to show that $\langle \gamma_1, \gamma_2 \rangle_{\ww} = \langle \gamma'_1, \gamma'_2\rangle_{\ww'}$. Note that for any vertex $z$ that $\ww$ and $\ww'$ have in common, we have $\langle \gamma_1, \gamma_2 \rangle_{z} = \langle \gamma'_1, \gamma'_2\rangle_{z}$. So we only need to prove the following identity: 
	\[
	\langle \gamma_1, \gamma_{2} \rangle_{u} +\langle \gamma_1, \gamma_{2} \rangle_{v}= \langle \gamma_1', \gamma_{2}'\rangle_{w}+\langle \gamma'_1, \gamma'_{2}\rangle_{v'}+\langle \gamma'_1, \gamma'_{2}\rangle_{x}.
	\]
	We refer reader to \cite[Lemma 4.30]{CGGLSS} for a proof for the identity above.
	\begin{figure}
		\centering
		\includegraphics[trim =1cm 7.8cm 0cm 11.5cm, clip = true, scale = 0.4]{local_mutation_move_seeds_version.pdf}
		\caption{A local mutation move.}
		\label{fig: local mutation move seeds version 1}
	\end{figure}
	Now let us assume that $\ww$ and $\ww'$ are related by a local mutation move, cf.\ Figure~\ref{fig: local mutation move seeds version 1}. We will show that $Q(\ww)$ and $Q(\ww')$ are related by a single quiver mutation. More precisely, we will show that $Q(\ww') = \mu_{\gamma_v}(Q(\ww))$. 

	Let $\gamma_1, \gamma_2$ be two (different) cycles other than $\gamma_v$ in $\ww$, the corresponding cycles in $\ww'$ are denoted by $\gamma'_1, \gamma'_2$ respectively. We need to prove the following two identities:
	\[
	\langle \gamma'_1, \gamma_{v'} \rangle_{\ww'} = - \langle \gamma_1 , \gamma_{v} \rangle_{\ww};
	\]
	and
	\[
	\langle \gamma'_1, \gamma'_2\rangle_{\ww'} = \langle \gamma_1, \gamma_2 \rangle_{\ww} + [\langle \gamma_1, \gamma_v \rangle_{\ww}]_+[\langle \gamma_v, \gamma_2\rangle_\ww]_+ - [\langle \gamma_1, \gamma_v \rangle_\ww]_-[\langle \gamma_v, \gamma_2\rangle_\ww]_-.
	\]
	Here $[x]_+ := \max\{x, 0\}$ and $[x]_{-}:= \min\{x, 0\}$. Similarly we refer reader to \cite[Lemma 4.33]{CGGLSS} for a proof for these identities. \qedhere
\end{proof}


We close this section by discussing \emph{reduced Demazure weaves} and the \emph{classification theorem} for reduced Demazure weaves. 


\begin{defn}
	Let $d \in \Z_{>0}$. The \emph{$0$-Hecke monoid} $H^d_0$ has generators $\tau_i$, $i\in [1, d-1]$ and relations
	\begin{equation}
		\begin{split}
			\tau_i^2 &= \tau;\\
			\tau_i \tau_j &= \tau_j\tau_i, \ |i-j|>1;\\
			\tau_i\tau_{i+1}\tau_i & = \tau_{i+1}\tau_i\tau_{i+1}.
		\end{split}
	\end{equation}
	A \emph{reduced word} for an element $\delta\in H^d_0$ is defined to be the shortest sequence of generators that multiply to $\delta$ in $H^d_0$. Notice that they are the same as reduced words in the symmetric group. 

	For a word $\beta$ in the alphabet $\{\tau_1, \cdots, \tau_{d-1}\}$, the \emph{Demazure product} $\delta(\beta)\in H_0^d$ of $\beta$ is defined to be the product in $H^d_0$. 
	%We will interchangeably use $\tau_i$ and $s_i$, as well as $H_0^d$ and $S_d$?
\end{defn}


We will use $\tau_i$ and $i$ interchangeably when representing a word. 
\begin{lemma}
	Let $\ww: \beta \rarrow \beta'$ be a Demazure weave with $\beta = \ww_{\text{top}}$ and $\beta' = \ww_{\text{bottom}}$. Then for any row word $\tilde{\beta}$, we have $\delta(\tilde{\beta}) = \delta(\beta)$. In particular, we have $\delta(\beta) = \delta(\beta')$. 
\end{lemma}
\begin{proof}
	By Definition~\ref{defn: scanning process and row words}, $\beta$ and $\tilde{\beta}$ are related by a sequence of transformations: $ii \rarrow i$,  $ij \rarrow ji$ (with $|i-j|>1$) and $iji \rarrow jij$ (with $|i-j| = 1$), and these transformations preserve products in $H_0^d$, hence resulting in the same Demazure product. 
\end{proof}
\begin{defn}
	A Demazure weave $\ww: \beta \rarrow \beta'$ is \emph{reduced} if $\beta'$ is a reduced word for $\delta(\beta)$. %And $\ww$ is called \emph{complete} if $\beta'$ is a reduced word for the element of the longest element $w_0$ in the corresponding symmetric group.
\end{defn}

\begin{remk}
	Different choices of a reduce word for $\delta(\beta)$ are braid equivalent. This follows from the well-known results for reduce words in the symmetric group $S_d$. 
\end{remk}
\begin{example}
	the Demazure weave  $\ww: 321122 \rarrow 1321$ in Figure~\ref{fig: example of a demazure 4-weave} is reduced, since $1321$ is a reduced word. %However $\ww$ is not complete, since $1321 \nsim 323123$. 
\end{example}

One of the most important results about Demazure weaves is the following classification theorem. It ensures that cluster structures are independent of weave presentation.

\begin{theorem}[{\cite[Theorems 4.12]{CGGS}}]
	\label{thm: demazure classification}
	Let $\ww,\ww':\beta\rarrow\beta'$ be reduced Demazure weaves with the same marked boundary vertices. Then $\ww$ and $\ww'$ are mutation equivalent. Consequently, we have $Q(\ww) \sim Q(\ww')$ by Proposition~\ref{prop: mutation equivalent weaves yield mutation equivalent quivers}. 
\end{theorem}

\begin{remk}
	The assumption that $\ww, \ww'$ are reduced (i.e., $\beta'$ is reduced) is important. Indeed, the two Demazure weaves $(ii)i \rarrow ii$ and $i(ii) \rarrow ii$ are neither equivalent or mutation equivalent. 
\end{remk}






\subsection{Mixed exterior algebra}\label{sec: mixed exterior algebra}

This section reviews foundational concepts of \emph{exterior algebras} over $V$ and $V^*$
following~\cite[Chapters 5 and 6]{Greub}, emphasizing their duality. We then introduce the \emph{mixed wedge} operator $\mixwed$, a key tool for streamlining notation in cluster variable computations and exchange relations.

Let $V$ be a $d$-dimensional vector space over $\C$ and let \[
\bigwedge V = \bigoplus_{k = 0}^{d} {\bigwedge}^k V 
\]
denote the \emph{exterior algebra} over $V$, here $\bigwedge^0 V = \C$. Elements in $\bigwedge^k V$ are called \emph{$k$-extensors}. The exterior product is denoted by $\wedge$ as usual. %Fix a \emph{volume form} $e\in \bigwedge^d V$. 
For $u\in \bigwedge V$, we call $u$ \emph{decomposable in $\bigwedge V$} if either $u\in \C$ or there exist $v_1, \cdots, v_r \in V$ such that $u = v_1 \wedge \cdots \wedge v_r$. 



The dual space $V^*$ similarly admits an exterior algebra  $\bigwedge V^*$ with (dual) exterior product $\wedge^*$ and {decomposable} elements. The following pairing bridges these structures:


\begin{defn}\label{defn: pairing of vectors and covectors, determinant}
The pairing
\begin{equation}\label{pairing}
	\langle \ , \  \rangle: \bigwedge V \times \bigwedge V^* \rightarrow \C
\end{equation}
is defined by 
\begin{equation}\label{formula: pairing formula}
	\begin{split}
		\langle \lambda, \mu\rangle &= \lambda\mu,  \text{ for } \lambda, \mu \in \C; \\
		\langle v_1\wedge \cdots \wedge v_k, w^*_1\wedge^* \cdots \wedge^* w^*_k \rangle &= \det(w^*_i(v_j)), \text{ for } v_1, \cdots, v_k \in v, w_1^*, \cdots, w_k^*\in V^*;\\
		\langle v_1\wedge \cdots \wedge v_p, w^*_1\wedge^* \cdots \wedge^* w^*_q \rangle &= 0, \text{ for } v_1, \cdots, v_p \in v, w_1^*, \cdots, w_q^*\in V^* \text{ and } p \neq q.
	\end{split}
\end{equation}
Fix a \emph{volume form} $e\in \bigwedge^d V$ and a \emph{dual volume form} $e^*\in \bigwedge^d V^*$ such that $\langle e, e^* \rangle  = 1$. For a top form $c\in \bigwedge^d V$, the \emph{determinant} of $c$ is defined by $\det(c) := \langle c, e^* \rangle \in \C$. For $c = v_1\wedge \cdots \wedge v_n$, we will write $\det(c) = \det(v_1, \cdots, v_n)$. Similarly, the determinant of $c^*\in \bigwedge^d V^*$ is defined by $\det(c^*): = \langle e, c^* \rangle$. 
\end{defn}
For simplicity, we identify $\bigwedge^d V$ with $\bigwedge^0 V = \C$ under the map $\langle \cdot, e^* \rangle $. In other words, we identify a top form $c$ with its determinant $\det(c)$. We identify $\bigwedge^d V^*$ with $\bigwedge^0 V^* = \C$ in a similar way.


The pairing in Definition~\ref{defn: pairing of vectors and covectors, determinant} naturally induces identifications of  $(\bigwedge^{d-k} V^*)^*$ with $\bigwedge^{d-k} V$, for $0\le k \le d$, leading to:


\begin{defn}\label{defn: identification map from V to V^*}
 The exterior product map
\begin{equation}
	{\bigwedge}^k V^* \times {\bigwedge}^{d-k} V^* \stackrel{\wedge^*}{\longrightarrow} {\bigwedge}^d V^* = \C
\end{equation}
	induces isomorphisms
\begin{equation}
	\psi_k: {\bigwedge}^k V^* \longrightarrow ({\bigwedge}^{d-k} V^*)^* = {\bigwedge}^{d-k} V
\end{equation}
via the pairing, yielding a vector space isomorphism:
\[
\psi: = \oplus \psi_k : \bigwedge V^* \rightarrow \bigwedge V.
\]
The \emph{identification map} $\psi$ intertwines two exterior algebra $\bigwedge V$ and $\bigwedge V^*$.
\end{defn}


With this identification, we define a product structure on the exterior algebra $\bigwedge V$ mirroring the (dual) wedge product on the dual exterior algebra $\bigwedge V^*$:



\begin{defn}\label{defn: intersection product}
The \emph{intersection product} $\cap$ on $\bigwedge V$ is the pullback of $\wedge^*$ on $\bigwedge V^*$ via the identification map $\psi$:
\begin{equation}
	u \cap v := \psi(\psi^{-1}(u)\wedge^* \psi^{-1}(v)), \text{ for } u, v \in \bigwedge V.
\end{equation}
In other words, the diagram
\[
\begin{tikzcd}[column sep=large, row sep=large]
	\bigwedge V^* \times \bigwedge V^* \arrow[r, "\psi \times \psi"] \arrow[d, "\wedge^*"] & \bigwedge V\times \bigwedge V \arrow[d, "\cap"]\\
	\bigwedge V^* \arrow[r, "\psi"] & \bigwedge V
\end{tikzcd}
\]
commutes.
The exterior algebra $\bigwedge V$ endowed with the two operators $\wedge, \cap$ is usually called \emph{the Grassmann-Cayley algebra}, cf.\ \cite[Section 3.3]{SturmfelsBernd}. The operators $\wedge, \cap$ are then called the meet and join, respectively; we will not use this terminology. 
\end{defn}

\begin{remk}
	We can similarly define $\cap^*$ in $\bigwedge V^*$. Under the identification map $\psi$, applying $\wedge^*$ in $\bigwedge V^*$ is the same as applying $\cap$ in $\bigwedge V$; and applying $\cap^*$ in $\bigwedge V^*$ is the same as applying $\wedge$ in $\bigwedge V$. We will interchangeably use $\wedge$ with $\cap^*$ (and $\wedge^*$ with  $\cap$) depending on the context. 
\end{remk}


The intersection product’s explicit form reveals its combinatorial and geometric nature as an intersection:

\begin{prop}\label{prop: intersection production expansion formula}
If $u = u_1 \wedge \cdots \wedge u_p\in \bigwedge^p V$ and $v = v_1 \wedge \cdots \wedge v_q\in \bigwedge^q V$ with $p+q\ge d$. Then $u\cap v\in \bigwedge^{p+q-d} V$. Specifically:
\begin{equation}
	u\cap v = \sum_{\sigma} \sgn(\sigma)\det(u_{\sigma(1)}, \cdots, u_{\sigma(d-q)}, v_1, \cdots, v_q) u_{\sigma(d-q+1)}\wedge \cdots \wedge u_{\sigma(p)}
\end{equation}
where the sum is taken over all permutations $\sigma$ of $\{1, 2, \cdots, p\}$ such that $\sigma(1)<\cdots<\sigma(d-q)$ and $\sigma(d-q+1)<\cdots<\sigma(p)$. 

In particular, if $p+q = d$,  then 
\begin{equation}
	u\cap v = \det(u\wedge v).
\end{equation}
Since we identify $u\wedge v$ with $\det(u\wedge v)$, we get, in this case, the equality $u\wedge v = u\cap v$.
Also we have
\begin{equation}\label{equation: intersection is anti-commutative}
	u\cap v = (-1)^{(d-p)(d-q)} v\cap u.
\end{equation}

\end{prop}
\begin{proof}
	See \cite[Section 6.12]{Greub} and \cite[Section 3.3]{SturmfelsBernd}.
\end{proof}

The identification $\psi$ preserves decomposability:
\begin{lemma}\label{lemma: decomposable well-defined under psi}
	An extensor $v\in \bigwedge V$ is decomposable in $\bigwedge V$ if and only if $w^* = \psi^{-1}(v)$ is decomposable in $\bigwedge V^*$. 
\end{lemma}
\begin{proof}
	Let $v\in \bigwedge^{d-k} V$ be a $(d-k)$-extensor, $k\in [0, d]$. For $k = 0, 1, d-1, d$, we know $v$ is always decomposable in $\bigwedge V$ and $w^* = \psi^{-1}(v) \in \bigwedge^{k} V^*$ is always decomposable in $\bigwedge V^*$. Now let us assume that $k\in [2, d-2]$. Assume that $w^*$ is decomposable in $\bigwedge V^*$, i.e., we have $w^* = w^*_1\wedge^* w^*_2 \wedge^* \dots \wedge^* w^*_k$ for some $w^*_i \in V^*$, $1\le i \le k$. Let $v_i:= \psi(w^*_i) \in \bigwedge^{d-1} V$, $1\le i \le k$, then by Definition~\ref{defn: intersection product}, we have
	\begin{align*}
	v = \psi(w^*) =& \psi(w^*_1\wedge^* w^*_2\wedge^* \dots \wedge^* w^*_k) \\
	=& \psi(\psi^{-1}(v_1)\wedge^* \psi^{-1}(v_2)\wedge^* \dots \wedge^* \psi^{-1}(v_k))
	= v_1\cap v_2 \cap \dots \cap v_k.
	\end{align*}
	We claim that the  intersecting a $(d-1)$-extensor $v_1$ with a decomposable (in $\bigwedge V$)~$j$-extensor $u$ is again decomposable (in $\bigwedge V$), $1\le j \le d-1$. 

	We prove the claim by an induction on $j$. If $j = 1$, then $v_1\cap u \in \bigwedge^d V = \C$ is decomposable. Assume that $v_1 \cap u'$ is decomposable for any decomposable $(j-1)$-extensor $u'$. Let $u$ be a decomposable $j$-extensor. Then we can write $u = u_1\wedge u_2\wedge \dots \wedge u_j$ with $u_i\in V$, $1\le i \le j$. Now by Proposition~\ref{prop: intersection production expansion formula}, if $u_i\wedge v_1 = 0$ for all $i\in [1, j]$, then $u\cap v_1 = 0$ and we are done. Otherwise, without loss of generality, we assume that $u_{j-1}\wedge v_1 \neq 0$. Then again by Proposition~\ref{prop: intersection production expansion formula}, we have
	\[
	u \cap v_1 = (u_1\wedge u_2\wedge \dots \wedge u_j)\cap v_1 = (u_j\wedge v_1)\cdot(u_1\wedge u_2\wedge \dots \wedge u_{j-1}) - \left((u_1\wedge \dots \wedge u_{j-1})\cap v_1 \right) \wedge u_j.
	\]
	Notice that
	\[
	(u_j\wedge v_1)\cdot(u_1\wedge u_2\wedge \dots \wedge u_{j-1}) = \frac{u_j\wedge v_1}{u_{j-1}\wedge v_1}\left( \left((u_1\wedge \dots \wedge u_{j-1})\cap v_1\right)\wedge u_{j-1}\right).
	\]
	Therefore
	\[
	u\cap v_1 = \left((u_1\wedge \dots \wedge u_{j-1})\cap v_1 \right) \left(\frac{u_j\wedge v_1}{u_{j-1}\wedge v_1}u_{j-1} - u_j\right). 
	\]
	is a wedge of two decomposable extensors, hence is decomposable. 

	Now by the claim, it is clear that $v$ is decomposable (by an induction on $k$). This completes the proof that $w^*$ is decomposable in $\bigwedge V^*$ implies $v$ is decomposable in $\bigwedge V$. The reverse implication follows symmetrically.
\end{proof}

%From now on, as we have identified $\bigwedge V$ with $\bigwedge V^*$ under the identification map $\psi$, we will simply say an extensor $v\in \bigwedge V$ is decomposable if $v$ is decomposable in $\bigwedge V$. 



Combining $\wedge$ and $\cap$ into a unified operator:
\begin{defn}
	The \emph{mixed wedge operator} $\mixwed$ is the bilinear map
	\begin{equation}
		\mixwed: \bigwedge V \times \bigwedge V \rightarrow \bigwedge V
	\end{equation}
	such that for $u\in \bigwedge^p V$ and $v\in \bigwedge^q V$, $p, q \in [0, d]$, we have 
	\begin{equation}
		u\mixwed v := \begin{cases}
			u\wedge v, & \text{if }\  p+q \le d,\\
			u\cap v, & \text{if }\  p+q\ge d.
		\end{cases}
	\end{equation}
The mixed wedge operator $\mixwed$ extends naturally to the \emph{mixed exterior algebra},  where we identify $\bigwedge V$ and $\bigwedge V^*$ under $\psi$. %We should view $u\mixwed v^*$ as $u\mixwed \psi(v^*)$, $w^* \mixwed u$ as $\psi(w^*)\mixwed u$ and $v^*\mixwed w^*$ as $\psi(v^*)\mixwed \psi(w^*)$, for $u\in \bigwedge V$ and $v^*, w^*\in \bigwedge V^*$. 
\end{defn}





Note that $\mixwed$ is commutative up to sign, i.e., we have 
\begin{equation}
	u\mixwed v := \begin{cases}
		(-1)^{pq}v\mixwed u, & \text{if }\  p+q \le d,\\
		(-1)^{(d-p)(d-q)}v\mixwed u, & \text{if }\ d\le p+q\le 2d.
	\end{cases}
\end{equation}
for $u\in \bigwedge^p V$ and $v\in \bigwedge^q V$, $0\le p, q\le d$; cf.\ Equation (\ref{equation: intersection is anti-commutative}).

\begin{remk}
The product $\mixwed$ is not always associative. Let $u\in \bigwedge^p V, v\in \bigwedge^q V, w\in \bigwedge^r V$.  If $p+q+r\le d$ or $p+q+r \ge 2d $, then the mixed wedge is associative:
\[
(u \mixwed v)\mixwed w = u \mixwed (v \mixwed w),
\]
because we are either applying $\wedge$ twice, or applying $\cap$ twice. On the other hand, if $d< p+q+r< 2d$, then in general 
\[
(u \mixwed v)\mixwed w \neq u \mixwed (v \mixwed w),
\]
because we are mixing $\wedge$ and $\cap$, making the product non-associative. 
\end{remk}

Due to the non-associativity of $\mixwed$, we resolve ambiguity by adopting the \textbf{right-to-left} evaluation convention when parentheses are omitted. For example, $u\mixwed v\mixwed w := u \mixwed (v \mixwed w)$.

\begin{example}
	Let $u\in \bigwedge^k V$ and $u^*\in \bigwedge^k V^*$. Then 
	\[
	u \mixwed u^* = u\wedge u^* = \langle u, u^* \rangle
	\]
	and 
	\[
	u^* \mixwed u = u^* \wedge u =   (-1)^{k(d-k)} u\wedge u^* = (-1)^{k(d-k)}\langle u, u^* \rangle.
	\]
\end{example}

\begin{example}
	Let $v_1, \cdots, v_p \in V$ and $v \in \bigwedge^q V$ with $p+q\le d$. Then
	\[
	v_1\mixwed \cdots \mixwed v_p \mixwed v = (v_1\wedge \cdots \wedge v_p) \wedge v.
	\]
\end{example}
\begin{lemma}\label{lemma: mixwed wedge of decomposable is decomposable}
	The mixed wedge of two decomposable extensors is decomposable. 
\end{lemma}
\begin{proof}
	This follows from Lemma~\ref{lemma: decomposable well-defined under psi}. Notice that the mixed wedge operator is either $\wedge$ in $\bigwedge V$ or $\cap = \wedge^*$ in $\bigwedge V^*$; in either case, the wedge (resp., dual wedge) of two decomposable extensors (in their corresponding space) is again decomposable. 
\end{proof}


The lemma below plays a pivotal role in simplifying mixed wedge products, particularly in the analysis of cluster variables and their exchange relations.

\begin{lemma}\label{lemma: derivative formula for mixwed wedge}
	Let $v\in V$,  $u^*_1 \in \bigwedge^p V^*$ and $u^*_2\in \bigwedge^q V^*$ with $p, q \ge 1, p+q \le d$.  Then 
	\begin{equation}\label{formula: derivative formula for mixed wedge}
		v\mixwed (u^*_1\mixwed u^*_2) = (-1)^{q}(v\mixwed u^*_1)\mixwed u^*_2 +  u^*_1 \mixwed (v\mixwed u^*_2).
	\end{equation}
	Similarly, if $v_1 \in \bigwedge^p V$, $v_2\in \bigwedge^q V$ and $u^*\in V^*$ with $p, q\ge 1, p+q \le d$, then
	\begin{equation}\label{formulat: derivative formula for mixed wedge, dual}
		u^*\mixwed(v_1\mixwed v_2) = (-1)^q(u^*\mixwed v_1)\mixwed v_2 + v_1 \mixwed (u^*\mixwed v_2).
	\end{equation}
\end{lemma}
\begin{proof}
	See \cite[Proposition 5.14.1]{Greub}.
\end{proof}

The following computation illustrates mechanics:

\begin{example}
	Let $d = 3$, $v_1, v_2, v_3 \in V$ and $u^*_1, u^*_2, u^*_3\in V^*$, then we have 
	\begin{equation}
		v_1\mixwed v_2\mixwed v_3 = \det(v_1, v_2, v_3), \quad u^*_1\mixwed u^*_2\mixwed u^*_3 = \det(u^*_1, u^*_2, u^*_3).
	\end{equation}
	Let us compute
	\begin{equation}
		I = v_1\mixwed v_2 \mixwed u^*_1 \mixwed v_3 \mixwed u^*_2 \mixwed u^*_3
	\end{equation}
	as a polynomial in the Weyl generators (cf.\ Definition \ref{defn: Weyl generators}). 
	Recall that we apply $\mixwed$ from right to left. We first calculate 
	\begin{align*}
	v_3 \mixwed (u^*_2 \mixwed  u^*_3) \stackrel{(\ref{formula: derivative formula for mixed wedge})}{=\joinrel=} -u^*_2(v_3)u^*_3 + u^*_3(v_3)u^*_2,
	\end{align*}
	then we compute
	\begin{align*}
	u^*_1 \mixwed (-u^*_2(v_3)u^*_3 + u^*_3(v_3)u^*_2) = - u^*_2(v_3)u^*_1 \wed u^*_3 + u^*_3(v_3)u^*_1\wed u^*_2,
	\end{align*}
	and
	\begin{align*}
	& v_2 \mixwed (- u^*_2(v_3)u^*_1 \wed u^*_3 + u^*_3(v_3)u^*_1\wed u^*_2) \\
	=&- u^*_2(v_3) (v_2 \mixwed (u^*_1 \mixwed  u^*_3)) + u^*_3(v_3) (v_2 \mixwed (u^*_1\wedge^*u^*_2))\\
	 =&  u^*_1(v_2)u^*_2(v_3)u^*_3 - u^*_2(v_3)u^*_3(v_2)u^*_1 - u^*_1(v_2)u^*_3(v_3)u^*_2 + u^*_2(v_2)u^*_3(v_3)u^*_1\quad (\text{by (\ref{formula: derivative formula for mixed wedge})}).
	\end{align*}
	Finally, we compute
	\begin{align*}
	 I = &v_1 \mixwed (u^*_1(v_2)u^*_2(v_3)u^*_3 - u^*_2(v_3)u^*_3(v_2)u^*_1 - u^*_1(v_2)u^*_3(v_3)u^*_2 + u^*_2(v_2)u^*_3(v_3)u^*_1)\\
	  =& u^*_1(v_2)u^*_2(v_3)u^*_3(v_1) - u^*_1(v_1)u^*_2(v_3)u^*_3(v_2) - u^*_1(v_2)u^*_2(v_1) u^*_3(v_3)+ u^*_1(v_1)u^*_2(v_2)u^*_3(v_3),
	\end{align*}
	and we are done. Note that the last two steps can be combined into a single step if we group $v_1\wedge v_2$ first:
	\begin{align*}
		I &= v_1\mixwed v_2 \mixwed u^*_1 \mixwed v_3 \mixwed u^*_2 \mixwed u^*_3 \\
		& = (v_1\mixwed v_2) \mixwed u^*_1 \mixwed v_3 \mixwed (u^*_2 \mixwed u^*_3)\\
		& = (v_1\mixwed v_2) \mixwed (-u^*_2(v_3)u^*_1\mixwed u^*_3 + u^*_3(v_3)u^*_1\mixwed  u^*_2)\\
		& = -u^*_2(v_3)\langle v_1\wedge v_2, u^*_1\wedge^*  u^*_3\rangle + u^*_3(v_3)\langle v_1\wed v_2, u^*_1\wedge^* u^*_2 \rangle \\
		& = u^*_1(v_2)u^*_2(v_3)u^*_3(v_1) - u^*_1(v_1)u^*_2(v_3)u^*_3(v_2) - u^*_1(v_2)u^*_2(v_1)u^*_3(v_3) + u^*_1(v_1)u^*_2(v_2)u^*_3(v_3).
	\end{align*}	
	Alternatively, we can use formula (\ref{formula: derivative formula for mixed wedge}) in a slightly different way:
	\begin{align*}
		I = & v_1\mixwed v_2 \mixwed u^*_1 \mixwed v_3 \mixwed u^*_2 \mixwed u^*_3\\
		 =& v_1\mixwed v_2 \mixwed (u^*_1 \mixwed (v_3 \mixwed (u^*_2 \mixwed u^*_3)))\\
		=& v_1\mixwed v_2 \mixwed (v_3 \mixwed (u^*_1 \mixwed (u^*_2 \mixwed u^*_3))) -v_1\mixwed v_2 \mixwed (u^*_1(v_3)( u^*_2 \mixwed u^*_3) )\\
		=& \det(v_1, v_2 , v_3)\det(u^*_1, u^*_2,  u^*_3) - u^*_1(v_3) \langle v_1 \wedge v_2, u^*_2 \wedge^* u^*_3\rangle \\
		=&\det(v_1, v_2 , v_3)\det(u^*_1, u^*_2,  u^*_3) - u^*_1(v_3)u_2^*(v_1)u_3^*(v_2) + u^*_1(v_3)u_2^*(v_2)u_3^*(v_1).
	\end{align*}	
	Notice that we get a different representation of $I$ as a polynomial in the Weyl generators. 
\end{example}
The following example shows that a mixed wedge product can factor or vanish due to 
repeated terms.
\begin{example}
	Let $d = 3$, $v_1, v_2, v_3 \in V$ and $u^* \in V^*$. Then we have 
	\[v_3 \mixwed v_2\mixwed u^* \mixwed v_1 \mixwed v_2 =  u^*(v_2)\cdot\det(v_3, v_2,  v_1)
	\]
	and 
	\[
	v_1 \mixwed v_2 \mixwed u^* \mixwed v_1 \mixwed v_2 = 0.
	\]
\end{example}

