\section{Cluster Structures in Mixed Grassmannians}\label{chap: cluster structures on mixed grassmannians}

\subsection{Decorated flags}\label{sec: decorated flags}

In this section, we introduce the notion of \emph{decorated flags} (see, e.g., \cite{CasalsLeSBWeng, CasalsWeng, Weng}),
which encode nested subspaces of $V$ with additional data. These structures arise naturally in the study of cluster algebras via the quotient $\text{SL}(V)/N$, the \emph{decorated flag variety}, where $N$ is the upper triangular unipotent subgroup of $\slv = \text{SL}(n, \C)$. We interpret decorated flags combinatorially as tuples of nested (decomposable) extensors, laying groundwork for their role as ``coordinates" in subsequent cluster variable constructions.


\begin{defn}{\label{flag}}
	A (complete) \emph{decorated flag} is an element of the \emph{decorated flag variety} $\slv/N$. Equivalently, a \emph{decorated flag} over $V$ is a tuple
	\begin{equation}
		\mcf= (\mcf^1, \mcf^2, \dots, \mcf^{d-1})
	\end{equation}
	such that
	\begin{enumerate}[wide, labelwidth=!, labelindent=0pt]
		\item[\textbf{(a)}] for each $1\le k \le d-1$, we have $\mcf^k \in \bigwedge^k V - \{0\}$;
		\item[\textbf{(b)}] for each $1\le k <d-1$, there exists $v\in V$ such that $\mcf^{k+1} = \mcf^k \wedge v$.		
	\end{enumerate}
\end{defn}

\begin{remk}
	The group $\slv$ acts on decorated flags via its natural action on $\bigwedge V$, preserving the nested condition in Definition \ref{flag}\textbf{(b)}. 
\end{remk}

The duality between decorated flags in $V$ and $V^*$ emerges via the identification map $\psi$.  Applying $\psi^{-1}$ reverses flag gradings while preserving nesting. %The nested condition is preserved if we view these extensors as in $V^*$ via the identification map $\psi^{-1}$. 

\begin{lemma}\label{lemma: k+1 = k wedge v equivalent k = k+1 wedge v star}
	Let $1\le k \le d-1$, and let $\mcf^k\in \bigwedge^k V$ and $\mcf^{k+1} \in \bigwedge^{k+1}$ be nonzero decomposable extensors. Then $\mcf^{k+1} = \mcf^k \wedge v$ for some $v\in V$ if and only if $\mcf^k = \mcf^{k+1}\mixwed v^*$ for some $v^*\in V^*$. 
\end{lemma}
\begin{proof}
	Assume that $\mcf^{k+1} = \mcf^k \wedge v$ and write $\mcf^k = v_1\wedge \cdots \wedge v_k$ with $v_i \in V$. Now take $v^*\in V^*$ such that $v^*(v_i) = 0$ for $1\le i \le k$ and $v^*(v) = (-1)^{k}$, then we have
	\begin{equation}
		\mcf^{k+1} \mixwed v^* =(-1)^{d-k-1}v^* \mixwed \mcf^{k+1} =(-1)^{d-k-1}(\mcf^k \mixwed (v^*\mixwed v)) = \mcf^k
	\end{equation}
	by lemma~\ref{lemma: derivative formula for mixwed wedge}. The converse is similar. 
\end{proof}



\begin{remk}\label{remk: pull back of flags over V are flags over V dual}
	Let $\mcf$ be a decorated flag over $V$. It's dual in $V^*$
	\[
	\mcf^*: = \psi^{-1}(\mcf) := (\psi^{-1}(\mcf^{d-1}), \dots, \psi^{-1}(\mcf^2), \psi^{-1}(\mcf^1))
	\]
	is a decorated flag in $V^*$, where $\psi$ is the identification map, cf.\ Definition~\ref{defn: identification map from V to V^*}. Indeed, by Lemma~\ref{lemma: k+1 = k wedge v equivalent k = k+1 wedge v star}, we have
	\begin{equation*}
		({\mcf^*})^{k+1} = \psi^{-1}(\mcf^{d-k-1}) = \psi^{-1}(\mcf^{d-k} \mixwed v^*) = \psi^{-1}(\mcf^{d-k}) \wedge^* v^*= (\mcf^*)^{k}\wedge^* v^*
	\end{equation*}
	for some $v^*\in V^*$.
\end{remk}



The following result is foundational to our framework: the vanishing and commutativity properties of mixed wedges in decorated flags ensure algebraic consistency, which is critical for explicit computations of cluster variables and their exchange relations.


\begin{prop}\label{prop: wedge of any two within a flag is zero}
	Let $\mcf$ be a decorated flag. Let $1\le k, k'\le d-1$. Then
	\begin{equation}\label{equation: wedges in the same flag is zero}
		\mcf^k\mixwed \mcf^{k'} = 0. 
	\end{equation}
Moreover, for any $v \in \bigwedge V$ we have 
\begin{equation}\label{equation: wedges in the same flag commutes}
	\mcf^k\mixwed (\mcf^{k'} \mixwed v) = \mcf^{k'}\mixwed (\mcf^k  \mixwed v).
\end{equation}
\end{prop}
\begin{proof}
	As $\mixwed$ is anti-commutative, we may assume that $k\le k'$. Suppose that $k+k'\le d$, we have $\mcf^{k'} = \mcf^k \wedge u$ with $u\in \bigwedge^{k'-k}V$, hence 
	\[
	\mcf^k\mixwed \mcf^{k'} = \mcf^k\wedge  \mcf^{k'} = \mcf^k\wedge \mcf^{k} \wedge u= 0.
	\]
	Suppose that $k+k'> d$, then $(d-k) + (d-k') < d$, and by duality (cf.\ Remark~\ref{remk: pull back of flags over V are flags over V dual}), it reduces to the previous case. This completes the proof of (\ref{equation: wedges in the same flag is zero}).

	Now let us prove (\ref{equation: wedges in the same flag commutes}). By linearity we may assume that $v\in \bigwedge^i V$. By symmetry we may assume that $k\le k'$. Write $\mcf^{k'} = \mcf^k \wedge u$ with $u\in  \bigwedge^{k'-k} V$. If $i+k+k'\le d$ or $i+k+k' \ge 2d$, then the mixed wedge operator is associative, and both sides vanish by (\ref{equation: wedges in the same flag is zero}). Hence we may assume that $d< i + k + k' < 2d$. 

	Suppose that $i < d-k'$. Then $i+k \le i+k' < d$. By the shuffling formula for the intersection product, cf.\ Proposition~\ref{prop: intersection production expansion formula}, we can conclude that
	\[
	\mcf^k\mixwed (\mcf^{k'} \mixwed v)  = \mcf^k \cap (\mcf^k\wedge u \wedge v) = 0
	\]
	and 
	\[
	 \mcf^{k'}\mixwed (\mcf^k  \mixwed v) = (\mcf^k \wedge u)\cap (\mcf^k \wedge v) = 0.
	\]
	By duality, the result follows in the case when $i > d-k$. 

	We next assume that $d-k' \le i \le d-k$. This is the case when both sides do not vanish. We have
	\[
	\mcf^k\mixwed (\mcf^{k'} \mixwed v) = \mcf^k \wedge \big((\mcf^k\wedge u)\cap v\big) = \mcf^k \wedge \big( u \cap (\mcf^k\wedge v)\big) 
	\]
	where the last equality follows from the shuffling formula for the intersection product. Similarly we have
	\[
	\mcf^{k'}\mixwed (\mcf^k  \mixwed v) = (\mcf^k\wedge u) \cap (\mcf^k \wedge v) = \mcf^k \wedge \big( u \cap (\mcf^k\wedge v)\big).
	\]
	This completes the proof of (\ref{equation: wedges in the same flag commutes}).
	%Alternatively, (\ref{equation: wedges in the same flag commutes}) can be proved by an induction on $k$ with Lemma~ \ref{lemma: derivative formula for mixwed wedge}.
\end{proof}


\begin{remk}
	When $d-k' \le i \le d-k$, identity (\ref{equation: wedges in the same flag commutes}) is a generalized version of the following identity for vector spaces. Let $U, V, W$ be vector subspaces of $\C^n$ with $U\subseteq V$, then 
	\[
		U + (V\cap W) = V\cap(U+W).
		\]
\end{remk}



We now associate a tuple of $n$ cyclically ordered decorated flags to a chosen signature, crucial for cluster coordinates.


\begin{defn}\label{defn: element of Vsigma}
Let $\sigma$ be a size $n$ signature of type $(a, b)$, cf.\ Definition~\ref{defn: signature}. Recall from Definition~\ref{defn: V sigma and rsigma} that the configuration space $V^\sigma$ is the rearrangement of the direct product  $V^a\times(V^*)^b$ where the $j$-th factor is $V$ (resp., $V^*$) if $\sigma(j) = 1$ (resp., $\sigma(j) = -1$), for $1\le j \le n$. Accordingly we will usually write an element $\uu\in V^\sigma$ as a tuple
\[
\uu = (u_1, u_2, \dots, u_n),
\]
where $u_j \in V$ if $\sigma(j) = 1$ and $u_j \in V^*$ if $\sigma(j) = -1$, $1\le j \le n$. We will extend the notation $u_j$ to all $j\in \Z$ by periodicity, i.e., $u_{j+n} = u_{j}$ for $j\in \Z$. Sometimes we will write $u^*_j$ instead of $u_j$ when $\sigma(j) = -1$ in order to indicate that $u_j$ is a covector.
\end{defn}

\begin{example}
	Let $\sigma = [\bullet\, \bullet\, \circ\, \circ\, \bullet]$. Recall that $\bullet$ stands for $1$ and $\circ$ stands for $-1$. Then $V^\sigma = V\times V\times V^*\times V^*\times V$, and $\uu = (u_1, u_2, u_3^*, u_4^*, u_5)\in V^\sigma$.
\end{example}

\begin{defn}\label{defn: generic point}
	Let $\uu\in V^\sigma$ and $j\in \Z$. For $j\in [1, n]$, define 
	\[
	f_j(\uu) := u_j \mixwed u_{j+1} \mixwed \cdots \mixwed u_{j'-1}\mixwed u_{j'} \in \C
	\] 
	where $j' \ge j$ is the smallest integer such that
	\begin{equation*}
		\sum_{i = j}^{j'} \sigma(i) \equiv 0 \bmod d.
	\end{equation*}
	Recall that by convention we take $\mixwed$ from right to left, i.e., the mixed wedge above should be viewed as $u_j \wed (u_{j+1}\wed \cdots \wed (u_{j'-1}\wed u_{j'}))$. 

	These $f_j$'s will be the frozen variables for the cluster algebra. 
	Let 
	\[
	f(\uu) = \prod_{j = 1}^n f_j(\uu).
	\]
	We say $\uu$ is \emph{generic} if $f(\uu) \neq 0$. Genericity ensures non-degenerate flag constructions.
\end{defn}


\begin{defn}\label{defn: tuple of flags mcf associated with sigma and u}
	Let $\sigma$ be a $d$-admissible signature (cf.\ Definition~\ref{defn: admissible signature}) and let $\uu\in V^\sigma$ such that $f(\uu) \neq 0$. The tuple of decorated flags
	\begin{equation}
		\vec{\mcf} = \vec{\mcf}(\uu) = (\mcf_1, \mcf_2, \dots, \mcf_{n}, \mcf_{n+1}= \mcf_1)
	\end{equation}
	is defined as follows.

	For every $j\in [1, n]$ and $k\in [1, d-1]$, take the smallest integer $j'\ge j$ such that 
	\begin{equation}
		\sum_{i = j}^{j'} \sigma(i) \equiv k \mod d.
	\end{equation}
	Then set
	\begin{equation}
		\mcf_j^k := u_j \mixwed u_{j+1} \mixwed \cdots \mixwed u_{j'-1}\mixwed u_{j'} \in {\bigwedge}^k V,
	\end{equation}
	Let
	\begin{equation}
		\mcf_j := (\mcf_j^1,\mcf_j^2, \dots, \mcf_j^{d-1}).
	\end{equation}
	%We call $j' -j +1$ the \emph{length of $(\mcf_j^\sigma)^k$}, denoted by $\ell((\mcf_j^\sigma)^k)$, which is the same as $\ell(\sigma,j,k)$.
We will extend $\mcf_j$ to all $j\in \Z$ by periodicity, i.e., $\mcf_{j+n}= \mcf_{j}$ for $j\in \Z$. 

To be precise, we cannot call $\mcf_j$ a decorated flag yet as we haven't check that the conditions for a decorated flag are satisfied for $\mcf_j$. This is done in the next Proposition. 
\end{defn}

\begin{prop}\label{prop: mcf is a decorated flag}
	Let $j\in \Z$. Then $\mcf_j$ is a decorated flag over $V$ for generic $\uu\in V^\sigma$. 
\end{prop}

The proof of Proposition \ref{prop: mcf is a decorated flag} will rely on two lemmas, but first let us work an example. 


\begin{example}
	Let $\sigma = [\bullet\, \bullet\, \bullet\, \bullet\, \circ]$ with $n = 5, d = 4$. Then 
	\begin{align*}
		\mcf_1 &= (u_1, u_1\mixwed u_2, u_1 \mixwed u_2\mixwed u_3),  &f_1 &= \det(u_1, u_2, u_3, u_4);\\
		\mcf_2 & = (u_2, u_2\mixwed u_3, u_2\mixwed u_3\mixwed u_4),  &f_2 &= u_2\mixwed u_3 \mixwed u_4 \mixwed u_5^*\mixwed u_1 \mixwed u_2;\\
		\mcf_3 & = (u_3, u_3 \mixwed u_4, u_3\mixwed u_4\mixwed u^*_5\mixwed u_1\mixwed u_2), &f_3 &= u_3 \mixwed u_4 \mixwed u_5^* \mixwed u_1 \mixwed u_2 \mixwed u_3;\\
		\mcf_4 & = (u_4, u_4\mixwed u^*_5\mixwed u_1\mixwed u_2, u_4\mixwed u^*_5\mixwed u_1\mixwed u_2\mixwed u_3), &f_4 &= u_4 \mixwed u_5^* = u^*_5(u_4);\\
		\mcf_5 & = (u^*_5\mixwed u_1\mixwed u_2, u^*_5\mixwed u_1\mixwed u_2\mixwed u_3, u^*_5), &f_5 &= u_5^* \mixwed u_1 = -u_5^*(u_1).
	\end{align*}
	The condition that $f_j \neq 0$ for all $j\in [1, 5]$ ensures that $\mcf_j$ are all non-degenerate. The nested condition is quite subtle. Take $\mcf_5$ as an example, notice that 
	\[
	u_5^* \mixwed u_1 \mixwed u_2 \mixwed u_3 = u_5^* \mixwed (u_1 \mixwed u_2 \mixwed u_3)  \neq (u_5^*\mixwed u_1 \mixwed u_2) \mixwed u_3.
	\]
	Instead, we have
	\[
	u_5^* \mixwed u_1 \mixwed u_2 \mixwed u_3 = (u_5^*\mixwed u_1 \mixwed u_2) \mixwed (-u_3 + \frac{u_5^*(u_3)}{u_5^*(u_1)}u_1).
	\]
\end{example}








\begin{lemma}\label{lemma: iterated mixed wedges are decomposable}
	For $j\in \Z$ and $k\in [1, d-1]$, the $k$-extensor $\mcf_j^k$ is decomposable. 
\end{lemma}
\begin{proof}
	This follows from Lemma~\ref{lemma: mixwed wedge of decomposable is decomposable}, as $\mcf_j^k$ is defined to the mixed wedges of vectors and covectors. 
\end{proof}

Let $u$ (resp., $v$) be either a vector or a covector. We say $u$ and $v$ are \emph{of the same type} if they are both vectors or both covectors.

\begin{lemma}\label{lemma: we can change the order of wedge by adjusting the last vectors}
	Let $r\ge 2$ and $w = w_1 \mixwed w_2 \mixwed \cdots \mixwed w_{r-1} \mixwed w_{r} \neq 0$ where $w_j \in V$ or $w_j\in V^*$, $1\le j\le r$. Suppose that $w_j \mixwed w_{j+1} \mixwed \cdots \mixwed w_r \notin \bigwedge^0 V$ (and $\bigwedge^d V$), for all $2\le j\le r$.  Then there exists $w'_r$ of the same type as $w_r$ such that $w = (w_1 \mixwed w_2 \mixwed \cdots \mixwed w_{r-1}) \mixwed w'_{r}$.
\end{lemma}
\begin{proof}
	We prove the statement by induction on $r$. When $r = 2$, we take $w'_2 = w_2$. 
	Now assume that the statement  is true for $r$, consider $w = w_1 \mixwed w_2 \mixwed \cdots \mixwed w_{r} \mixwed w_{r+1}$.  Without loss of generality, we may assume that $w_{r+1}\in V$. We have 
	\[
	w = w_1 \mixwed w_2 \mixwed \cdots \mixwed w_{r} \mixwed w_{r+1} = w_1 \mixwed (w_2 \mixwed \cdots \mixwed w_{r} \mixwed w_{r+1}) = w_1 \mixwed w'
	\]
	with $w' = w_2 \mixwed \cdots \mixwed w_{r} \mixwed w_{r+1}$. Apply induction hypothesis to $w'$, there exists $w_{r+1}'\in V$ such that $w' = (w_2 \mixwed \cdots \mixwed w_{r}) \mixwed w'_{r+1}$. Therefore
	\[
	w = w_1 \mixwed w_2 \mixwed \cdots \mixwed w_{r} \mixwed w_{r+1} =  w_1 \mixwed w' = w_1 \mixwed ((w_2 \mixwed \cdots \mixwed w_{r}) \mixwed w'_{r+1}) = w_1 \mixwed w'' \mixwed w'_{r+1}
	\]
	where $w'' = w_2 \mixwed \cdots \mixwed w_{r}$.  

	Now by Lemma~\ref{lemma: iterated mixed wedges are decomposable}, $w''$ is decomposable. Suppose that $w_1\in V$. Then we have
	\[
	w = w_1 \wedge w'' \wedge w'_{r+1} = (w_1 \wedge w'') \wedge w'_{r+1} = (w_1 \mixwed w_2 \mixwed \cdots \mixwed w_{r}) \mixwed w'_{r+1}.
	\]
	and we are done. Suppose that $w_1\in V^*$. Similar to the proof of Lemma~\ref{lemma: decomposable well-defined under psi}, there exists $w''_{r+1} \in V$ such that 
	\begin{align*}
	w &= w_1 \mixwed w'' \mixwed w'_{r+1} = w_1 \cap (w'' \wedge w'_{r+1}) =(w_1 \cap w'') \wedge w''_{r+1} \\
	&= (w_1 \mixwed w'') \mixwed w''_{r+1} =(w_1 \mixwed w_2 \mixwed \cdots \mixwed w_{r}) \mixwed w''_{r+1}. \qedhere
	\end{align*}
\end{proof}


\begin{proof}[Proof of Proposition~\ref{prop: mcf is a decorated flag}]
	Let $j\in [1, n]$ and $k\in [1, d-1]$. We first show that $\mcf_j^k \neq 0$. 
	As in Definition~\ref{defn: tuple of flags mcf associated with sigma and u}, let $j'(k) \ge j$ be the smallest integer such that 
	\[
	\sum_{i = j}^{j'(k)} \sigma(i) \equiv k \bmod d.
	\]
	Then $\mcf_j^k = u_j \mixwed u_{j+1} \mixwed \cdots \mixwed u_{j'(k)-1}\mixwed u_{j'(k)}$.
	Now let $j_0 < j'(k)$ be the largest integer such that 
	\[
	\sum_{i = j_0}^{j'(k)} \sigma(i) \equiv 0 \bmod d.
	\]
	Notice that $j_0 < j$ and 
	\[
	f_{j_0} = u_{j_0}\mixwed u_{j_0+1} \mixwed \cdots \mixwed u_{j'(k)-1}\mixwed u_{j'(k)} = u_{j_0}\mixwed u_{j_0+1} \mixwed \cdots \mixwed u_{j-1} \mixwed \mcf_j^k.
	\]
	Since $f_{j_0}\neq 0$, we conclude that $\mcf_j^k\neq 0$. 


	We next show that the nested condition for decorated flags is satisfied for $\mcf_j$. Similarly we denote by $j'(k+1) \ge j$ the smallest integer such that 
	\[
	\sum_{i = j}^{j'(k)} \sigma(i) \equiv k+1 \bmod d.
	\]
Then $\mcf_j^{k+1} = u_j \mixwed u_{j+1} \mixwed \cdots \mixwed u_{j'(k+1)-1}\mixwed u_{j'(k+1)}$. 
	By duality, we may assume that $j'(k) < j'(k+1)$. Then we have 
	\begin{align*}
		\mcf_j^{k+1} &= u_j \mixwed u_{j+1} \mixwed \cdots \mixwed u_{j'(k+1)-1}\mixwed u_{j'(k+1)}\\
		&= u_j \mixwed u_{j+1} \mixwed \cdots \mixwed u_{j'(k)} \mixwed (u_{j'(k)+1} \mixwed \cdots \mixwed u_{j'(k+1)-1}\mixwed u_{j'(k+1)})\\
		& = u_j \mixwed u_{j+1} \mixwed \cdots \mixwed u_{j'(k)} \mixwed w
	\end{align*}
	where $w = u_{j'(k)+1} \mixwed \cdots \mixwed u_{j'(k+1)-1}\mixwed u_{j'(k+1)}\in \bigwedge^1 V = V$. Notice that the condition of Lemma~\ref{lemma: we can change the order of wedge by adjusting the last vectors} is satisfied for $\mcf_j^{k+1}$ by the definition of $j'(k+1)$. Hence by Lemma~\ref{lemma: we can change the order of wedge by adjusting the last vectors}, there exists $v\in V$ such that $\mcf_j^{k+1} =(u_j \mixwed u_{j+1} \mixwed \cdots \mixwed u_{j'(k)}) \mixwed v = \mcf_j^k \wedge v$. 
\end{proof}




The tuple $\vec{\mcf}(\uu)$ exhibits a recursive structure where each decorated flag $\mcf_j$ can be uniquely reconstructed from its successor and either its first component (when $\sigma(j) = 1$) or its last component (when $\sigma(j) = -1$). This recursive dependency is universal: any cyclic tuple of decorated flags satisfying these conditions must be of the form $\vec{\mcf}(\uu)$ for some generic $\uu \in V^\sigma$. 


\begin{prop}\label{prop: recursive relation between flags associated with a signature}
		Let $\sigma$ be a $d$-admissible signature. Let $\uu\in V^\sigma$ with $f(\uu) \neq 0$. Then the tuple of decorated flags
	\begin{equation}
		\vec{\mcf}(\uu) = (\mcf_1, \mcf_2, \dots, \mcf_{n}, \mcf_{n+1}= \mcf_1)
	\end{equation}
	satisfies the following recursive relations. Let $j\in [1, n]$.
	\begin{itemize}[wide, labelwidth=!, labelindent=0pt]
		\item Suppose that $\sigma(j) = 1$. Then $\mcf_j$ is uniquely determined by $\mcf_{j+1}$ and $\mcf_j^1$ via
		\begin{equation}\label{equation: wedge iteration condition black}
			\mcf_j^k = \begin{cases}
				\mcf_j^1, &\quad \text{if} \quad  k=1;\\
				\mcf_j^1 \mixwed \mcf_{j+1}^{k-1}, &\quad \text{if} \quad 1< k \le d-1.	
			\end{cases}
		\end{equation}
	\item Suppose that $\sigma(j) = -1$. Then $\mcf_j$ is uniquely determined by $\mcf_{j+1}$ and $\mcf_j^{d-1}$ via
	\begin{equation}\label{equation: wedge iteration condition white}
		\mcf_j^k = \begin{cases}
			\mcf_j^{d-1}, &\quad \text{if} \quad k = d-1; \\
			\mcf_j^{d-1} \mixwed \mcf_{j+1}^{k+1}, &\quad \text{if} \quad 1\le k < d-1.
		\end{cases}
	\end{equation}
	\end{itemize}
	Conversely, let $\vec{\mcg} = (\mcg_1, \mcg_2, \cdots, \mcg_n, \mcg_{n+1} = \mcg_1)$ be a tuple of decorated flags satisfying the recursive relations (\ref{equation: wedge iteration condition black}) and (\ref{equation: wedge iteration condition white}). Then $\vec{\mcg} = \vec{\mcf}(\uu)$ for some $\uu\in V^\sigma$. 
\end{prop}
\begin{proof}
	Let $j\in [1,n]$. If $\sigma(j) = 1$, then $\mcf_j^1 = u_j$. For $1< k \le d-1$, let $j'\ge j$ be the smallest integer such that 
	\begin{equation}
		\sum_{\ell = j}^{j'} \sigma(\ell) \equiv k \mod d.
	\end{equation}
	Since $\sigma(j) = 1$, we notice that $j' \ge j+1$ is also the smallest integer such that 
		\begin{equation}
		\sum_{\ell = j+1}^{j'} \sigma(\ell) \equiv k-1 \mod d.
	\end{equation}
	Hence $\mcf_{j+1}^{k-1} = u_{j+1} \mixwed \cdots \mixwed u_{j'-1}\mixwed u_{j'}$,
	and therefore 
	\begin{equation}
		\mcf_{j}^k = u_j\mixwed u_{j+1} \mixwed \cdots \mixwed u_{j'-1}\mixwed u_{j'} =  u_j \mixwed \mcf_{j+1}^{k-1}=\mcf_j^1 \mixwed \mcf_{j+1}^{k-1}.
	\end{equation}
	Similarly if $\sigma(j) = -1$, we have $\mcf_j^{d-1} = u^*_j$ and 
	\begin{equation}
		\mcf_{j}^k = u^*_j \mixwed \mcf_{j+1}^{k+1} =\mcf_j^{d-1} \mixwed \mcf_{j+1}^{k+1}
	\end{equation}
	for $1\le k < d-1$.

	Conversely, let $j\in [1, n]$, define $u_j := \mcg_j^1 \in V$ (resp. $u^*_j := \mcg_j^{d-1}\in V^*$) if $\sigma(j) = 1$ (resp. $\sigma(j) = -1$). Let $\uu = (u_1, u_2, \cdots, u_n) \in V^\sigma$. Then it is easy to check that $\vec{\mcg} = \vec{\mcf}(\uu)$. 
\end{proof}


In the next section, we will show that the universality in Proposition \ref{prop: recursive relation between flags associated with a signature} induces an isomorphism between:
\begin{enumerate}[wide, labelwidth=!, labelindent=0pt]
	\item the \emph{generic configuration space} $V^\sigma \setminus \{f = 0\}$, and 
	\item the moduli space of cyclic decorated flag tuples satisfying the recursive relations.
\end{enumerate}

This isomorphism, formalized in Theorem~\ref{thm: bijection between configuration spaces of signature and decorated flag moduli spaces}, achieves our goal of providing explicit coordinates for cluster variables via decorated flags.





\subsection{Decorated flag moduli space}\label{sec: decorated flag moduli space}

In this section, we introduce the notion of decorated flag moduli space. These flag moduli spaces were originally considered in the context of the microlocal theory of sheaves, cf.\ \cite[Section 2.8]{CasalsWeng} and references therein. 
While our construction of decorated flag moduli spaces shares similarities with \cite[Section 6.2]{CasalsLeSBWeng}, we employ distinct conventions that better suit our framework.



\begin{defn}[{\cite[Section 4.6.2]{CasalsWeng}}]\label{defn: wedge with common subspace quotient out}
	Let $u \in \bigwedge^p V, v \in \bigwedge^q V$. Let  $w\in \bigwedge^r V$ with $p+q - d \le r\le \min\{p, q\}$, such that $u = u_1\wedge w$ and $v = w\wedge v_1$ for some $u_1\in \bigwedge^{p-r} V, v_1\in \bigwedge^{q-r} V$. Then \emph{the wedge of $u$ and $v$ over $w$} is defined to be
	\begin{equation}
		\qwed u v w := u_1\wedge w\wedge v_1 \in {\bigwedge}^{p+q-r} V.
	\end{equation}
	Notice that $\qwed u v w = u_1\wedge w \wedge v_1 = u\wedge v_1 = u_1\wedge v$, it follows that the definition of $\qwed uvw$ does not depend on the choice of $u_1$ and $v_1$. Also note that the operation is anti-commutative in $u$ and $v$, i.e., $\qwed u v w = (-1)^{(p-r)(q-r)} \qwed v u w$.
\end{defn}

To understand the algebraic behavior of this wedge product, we establish fundamental cancellation laws:

\begin{lemma}\label{lemma: cancellation law for quotient wedge}
	Under the same assumption as in the Definition~\ref{defn: wedge with common subspace quotient out}, and assume that $v = \qwed w x y $ for some $x\in \bigwedge^s V, y\in \bigwedge^t V$. Then we have
	\begin{equation}\label{equation: cancellation law for quotient wedge}
		\qwed{u}{(\qwed w x y)}{w} = \qwed u x y.
	\end{equation}
	Symmetrically, if $u = \qwed{x'}{w}{y'}$ for some $x'\in \bigwedge^s V, y\in \bigwedge^t V$, then 
	\begin{equation}
		\qwed{(\qwed{x'}{w}{y'})}{v}{w} = \qwed{x'}{v}{y'}.
	\end{equation}
\end{lemma}
\begin{proof}
	If we write $x =  y \wedge x_1$ for some $x_1\in \bigwedge^{s-t}$, then we have
	\[
	\qwed{u}{(\qwed w x y)}{w} = \qwed u {(w\wedge x_1)} w= u \wedge x_1 =  \qwed u x y. 
	\]
	The symmetric case follows analogously.
\end{proof}

\begin{lemma}\label{lemma: cancellation law for quotient wedge, version2}
	Let $u, w, x, y$ be four extensors such that $u = w'\wedge w$ and $y = x \wedge x'$ for some extensors $w', x'$. Then we have
	\[
	\qwed{(u\wedge x)}{(w\wedge y)}{w\wedge x} = u\wedge y.
	\]
\end{lemma}
\begin{proof}
	We have 
	\[
	\qwed{(u\wedge x)}{(w\wedge y)}{w\wedge x} = \qwed{(w'\wedge w\wedge x)}{(w\wedge y)}{w\wedge x} = w'\wedge w\wedge y = u \wedge y. \qedhere
	\]
\end{proof}



Having established these algebraic tools, we now analyze geometric relationships between decorated flags:



\begin{defn}\label{defn: relative position}
	Let $\mcg, \mch$ be two decorated flags and $k\in [1, d-1]$. We say $\mcg$ and $\mch$ are \emph{in relative position} $s_k$, denoted by $\mcg \rel{k} \mch$, if $\mcg_i = \mch_i$ for $i\neq k$ and $\mcg_k \neq \lambda \mch_k$ for any $\lambda \in \C$.
\end{defn}

\begin{remk}
	Our relative position definition differs from \cite[Definition 6.8]{CasalsLeSBWeng} by omitting their uniform \emph{crossing value} (cf.\ Definition~\ref{defn: crossing values}) normalization. This modification preserves greater geometric flexibility.
\end{remk}


\begin{defn}
	Let $u, v \in \bigwedge^k V$ and $\mu \in \C$ such that $u = \mu v$. Then we define
	\[
	\frac u v := \mu\in \C.
	\]
\end{defn}

\begin{lemma}\label{lemma: crossing values of flags well-defined}
	Let $\mcg, \mch$ be two decorated flags that are in relative position $s_k$ for some $k\in [1, d-1]$. Then 
	\[
	\frac{\qwed{\mcg^k}{\mch^k}{\mcg^{k-1}}}{\mcg^{k+1}} = \mu \in \C - \{0\}.
	\]
	Here we adopt the convention that $\mcg^0 = \mcg^{d} = 1$.
\end{lemma}
\begin{proof}
	Let $u, v, w\in V$ such that $\mcg^{k} = \mcg^{k-1}\wedge u$, $\mcg^{k+1} = \mcg^{k-1}\wedge u \wedge v$ and $\mch^{k} = \mcg^{k-1}\wedge w$.  Since $\mch^{k+1} = \mcg^{k+1} = \mcg^{k-1}\wedge u \wedge v$, there exists $\lambda, \mu \in \C$ such that $\mch^{k} = \mcg^{k-1}\wedge (\lambda u + \mu v)$. Hence
	\[
	\qwed{\mcg^k}{\mch^k}{\mcg^{k-1}} = (\mcg^{k-1}\wedge u)\wedge (\lambda u + \mu v) = \mu\cdot (\mcg^{k-1}\wedge u \wedge v) = \mu \mcg^{k+1}.
	\]
	Notice that $\mch^k \neq \lambda \mcg^k$, hence $\mu \neq 0$.
\end{proof}



\begin{defn}[{\cite[Section 4.6.2]{CasalsWeng}}] \label{defn: crossing values}
	Following Lemma~\ref{lemma: crossing values of flags well-defined}, the \emph{crossing value} of $\mcg$ and $\mch$, denoted by $\cv \mcg \mch k$, is defined to be the constant $\mu$:
	\begin{equation}
		\cv \mcg \mch k := \frac{\qwed{\mcg^k}{\mch^k}{\mcg^{k-1}}}{\mcg^{k+1}} \in \C.
	\end{equation}
	Notice that $\cv \mcg \mch k = - \cv \mch \mcg k$. 
\end{defn}


\begin{example}
	Let $d = 3$, $\mcg = (u_2, u_1\wedge u_2)$ and $\mch = (u_2, u_2\wedge u_3)$. Then 
	\[
	\cv \mcg \mch 2= \frac{\qwed{(u_1\wedge u_2)}{(u_2\wedge u_3)}{u_2}}{1} = u_1\wedge u_2 \wedge u_3 = \det(u_1, u_2, u_3).
	\]
\end{example}

\begin{remk}\label{remk: duality of crossing values}
	Similarly, we can define the \emph{dual crossing values} $\dcv \mcg \mch k$ by viewing $\mcg, \mch$ as flags in $V^*$. To be precise,  
	let $u^* \in \bigwedge^p V^*, v^* \in \bigwedge^q V^*$. Let  $w^*\in \bigwedge^r V^*$ with $p+q - d \le r\le \min\{p, q\}$ such that $u^* = u^*_1\wedge^* w^*$ and $v^* = w^*\wedge v^*_1$ for some $u^*_1\in \bigwedge^{p-r} V^*, v^*_1\in \bigwedge^{q-r} V^*$, then the \emph{dual wedge of $u^*$ and $v^*$ over $w^*$} is defined as
	\begin{equation}
		\qwedd {u^*} {v^*} {w^*} := u^*_1\wedge^* w^*\wedge^* v^*_1 \in {\bigwedge}^{p+q-r} V^*.
	\end{equation}
	The \emph{dual crossing value of $\mcg$ and $\mch$}, denoted by $\dcv \mcg \mch k$, is defined as
	\begin{equation}
		\dcv \mcg \mch k:= \frac{\qwedd{\mcg^k}{\mch^k}{\mcg^{k+1}}}{\mcg^{k-1}} \in \C.
	\end{equation}
\end{remk}


Without any surprise, the duality implies that $\cv \mcg \mch k = \dcv \mcg \mch k$.
\begin{lemma}
	Let $\mcg, \mch$ be two decorated flags that are in relative position $s_k$ for some $k\in [1, d-1]$. Then $\cv \mcg \mch k = \dcv \mcg \mch k$.
\end{lemma}
\begin{proof}
	As in the proof of Lemma~\ref{lemma: crossing values of flags well-defined}, we can write $\mcg^{k} = \mcg^{k-1}\wedge u$, $\mcg^{k+1} = \mcg^{k-1}\wedge u \wedge v$ and $\mch^{k} = \mcg^{k-1}\wedge (\lambda u + \mu v)$ with $u, v\in V$, $\lambda, \mu\in \C$ and 
	$\cv \mcg \mch k = \mu$. 

	Now let $w^* \in V^*$ such that $w^*\mixwed \mcg^{k-1} = 0, w^*(u) = (-1)^{k-1}\mu$ and $w^*(v) = (-1)^k\lambda$. Then $\mch^k = \mcg^{k+1} \mixwed w^*$. Indeed, by Lemma~\ref{lemma: derivative formula for mixwed wedge} we have
	\begin{equation*}
		\begin{split}
			\mcg^{k+1} \mixwed w^* &= (\mcg^{k-1}\wedge u\wedge v) \mixwed w^*\\
			&=(\mcg^{k-1}\mixwed w^*)\mixwed (u\wedge v) + (-1)^{k-1} \mcg^{k-1}\mixwed (u\wedge v)\mixwed w^*\\
			&= (-1)^{k-1}\mcg^{k-1}\mixwed ((u\mixwed w^*)\mixwed v - (u\mixwed (v\mixwed w^*)))\\
			&= \mcg^{k-1}\wedge (\lambda u + \mu v) = \mch^k.
		\end{split}
	\end{equation*}
	Hence by Lemma~\ref{lemma: derivative formula for mixwed wedge} again, we have
	\[
	\qwedd{\mcg^k}{\mch^k}{\mcg^{k+1}} = \mcg^k \mixwed  w^* = (\mcg^{k-1}\wedge u) \mixwed w^* =( \mcg^{k-1}\mixwed w^*)\mixwed u + (-1)^{k-1} \mcg^{k-1}\mixwed (u\mixwed w^*) = \mu \mcg^{k-1}.
	\]
	Therefore $\dcv \mcg \mch k = \mu = \cv \mcg \mch k$.
\end{proof}



We now synthesize these concepts into our main geometric objects: \emph{the decorated flag moduli spaces}. 

\begin{defn}\label{defn: decoration of word}
	Let $\beta = \beta_1\beta_2\cdots\beta_s$ be a word with $\beta_k \in [1, d-1]$, $1\le k \le s$. A \emph{decoration for $\beta$} is a tuple of decorated flags $\dec_{\beta} = (\mcg_1, \mcg_2, \cdots, \mcg_{s+1})$ such that $\mcg_{k} \rel{{\beta_{k}}}\mcg_{k+1}$ (cf.\ Definition~\ref{defn: relative position}), $1\le k \le s$. We accordingly write
	\[
	\mcg_1 \rel{\beta_1} \mcg_2 \rel{\beta_2} \cdots \rel{\beta_{s-1}} \mcg_s \rel{\beta_s} \mcg_{s+1}.
	\]
	We also say that $\beta$ is decorated ``from $\mcg_1$ to $\mcg_{s+1}$". A decoration is called \emph{cyclic} if $\mcg_1 = \mcg_{s+1}$. A word with a decoration is called a \emph{decorated word}. 
\end{defn}

\begin{defn}\label{defn: marked word}
	A \emph{marked word} is a word with certain characters marked. We usually use overline above a character to indicate that it is marked. For example, in the marked word $13\overline{2}4\overline{3}1$, the third and fifth characters are marked. 

	Let $\ww$ be a Demazure weave, then the top word $\beta = \ww_{\text{top}}$ of $\ww$ will be treated as a marked word; a character in $\beta$ is marked if the corresponding weave line is connected to a marked boundary vertex. 
\end{defn}


\begin{defn}\label{defn: decoration of marked word}
	Let $\beta = \beta_1\beta_2\cdots\beta_s$ be a marked word. A \emph{normalized (resp., normalized cyclic) decoration for a marked word $\beta$} is a decoration (resp., cyclic decoration) $\dec_\beta = (\mcg_1, \mcg_2, \cdots, \mcg_{s+1})$ for $\beta$ such that all unmarked crossing values are equal to ~$1$, i.e., if $\beta_k$ is unmarked, then $\cv{\mcg_{k}}{\mcg_{k+1}}{\beta_k} = 1$. 
\end{defn}


\begin{defn}\label{defn: decorated flag moduli space}
	Let $\beta$ be a marked word. \emph{The decorated flag moduli space} $\mfmo(\beta)$ is the configuration space
	\begin{equation}
		\mfmo(\beta):= \{\text{Normalized decorations $\dec_\beta$ for }\beta \}.
	\end{equation}
	\emph{The cyclic decorated flag moduli space} $\mfm(\beta)$ is the configuration space
	\begin{equation}
		\mfm(\beta):= \{\text{Normalized cyclic decorations $\dec_\beta$ for }\beta \}.
	\end{equation}
\end{defn}
\begin{remk}
	The crossing value is $\slv$-invariant, i.e., for any $g\in \slv$, we have $\cv{g\mcg}{g\mch}{k} = \cv \mcg \mch k$. As a consequence, $\slv$ acts naturally on (cyclic) decorated flag moduli spaces. 
\end{remk}



\begin{remk}\label{remk: restriction of decorations to a subword}
	Let $\beta'$ be a contiguous marked subword of a marked word $\beta$. Then a normalized cyclic decoration for $\beta$ restricts to a normalized decoration for $\beta'$, i.e.,  we have a \emph{restriction map}
	\[
	\mfm(\beta) \rightarrow \mfmo(\beta').
	\]
\end{remk}

We next define the (cyclic) decorated flag moduli space associated with a signature. 
Let $\sigma$ be a size $n$ $d$-admissible signature of type $(a, b)$, cf.\ Definition~\ref{defn: admissible signature}. 
\begin{defn}\label{defn: configuration space of a signature, and defn of beta sigma}
	Let $\rho = 12\cdots \overline{(d-1)}$ and $\rho^* = {(d-1)}\cdots 2\overline{1}$ be marked words (with the last character marked).  The \emph{marked word associated with a signature $\sigma$} is the marked word 
	\[
	\beta_\sigma = \prod_{j = 1}^n \rho_{j}, \quad \rho_j \in \{\rho, \rho^*\}
	\]
	where $\rho_j = \rho$ (resp. $\rho_j =  \rho^*$) if $\sigma(j) = 1$ (resp. $\sigma(j) = -1$). In other words, $\beta_\sigma$ is a concatenation of $n$ copys of $\rho$ or $\rho^*$ such that the $j$-th subword is $\rho$ (resp. $\rho^*$) if $\sigma(j) = 1$ (resp. $\sigma(j) = -1$), $1\le j \le n$.
\end{defn}

\begin{defn}
	The \emph{(cyclic) decorated flag moduli space $\mfm(\beta_\sigma)$ associated with a $d$-admissible signature $\sigma$} is the cyclic decorated flag moduli space for the word $\beta_\sigma$. 
\end{defn}


Recall from Definition~\ref{defn: element of Vsigma} that the configuration space
$V^\sigma$ is the rearrangement of the direct product  $V^a\times(V^*)^b$ with respect to $\sigma$. A point $\uu\in V^\sigma$ is generic if $f(\uu) \neq 0$ (cf.\ Definition~\ref{defn: generic point}). The \emph{generic configuration space} $V^\sigma \setminus \{f = 0\}$ associated with $\sigma$ is the space of generic points in $V^\sigma$. 

The cyclic decorated flag moduli space $\mfm(\beta_\sigma)$ admits a geometric invariant theory interpretation as the generic configuration space associated with $\sigma$ (cf.\ Theorem \ref{thm: bijection between configuration spaces of signature and decorated flag moduli spaces}).


\begin{defn}\label{defn: interval words}
	An \emph{interval word} for an interval $[i, j]$ is either 
	\[
	I_i^j : = i (i+1) \cdots (j-1){j}\quad  \text{ or } \quad I_j^i:= {j}{(j-1)}\cdots {(i+1)}i,
	\] 
	where $1\le i \le j \le d-1$. We call $I_i^j$ (resp. $I_j^i$) \emph{increasing} (resp. \emph{decreasing}). The notion of interval words will be used again in later sections. 
\end{defn}

\begin{lemma}\label{lemma: decoration for interval word}
	Let $\beta$ be a marked interval word. Let $(\mcg_1, \mcg_2, \cdots, \mcg_{s+1})$ be a normalized decoration of $\beta$. Then the decorated flags $\mcg_{k}$ for $k\in[1, s+1]$ are uniquely determined by $\mcg_1$ and $\mcg_{s+1}$. In other words, a decoration for an interval word can be represented by a tuple $(\mcg_1, \mcg_{s+1})$, and we usually write $\mcg_1 \rel{\beta} \mcg_{s+1}$.
\end{lemma}
\begin{proof}
	Without loss of generality, we assume that $\beta = I_i^j$ with $1\le i\le j \le d-1$. Then 
	\[
		\mcg_k = (\mcg_{1}^1, \dots, \mcg_1^{i-1}, \mcg_{s+1}^i, \dots, \mcg_{s+1}^{k+i-2}, \mcg_1^{k+i-1}, \cdots, \mcg_1^{d-1}), \quad k \in [1, s+1]. 
		\]	
		is uniquely determined by $\mcg_1$ and $\mcg_{s+1}$. 
\end{proof}


\begin{lemma}\label{lem: pre-assignment of top boundary flags}
	For generic $\uu\in V^\sigma$ (cf.\ Definition \ref{defn: generic point}), let 
	\[
	\vec{\mcf}(\uu) =  (\mcf_1, \mcf_2, \dots, \mcf_n, \mcf_{n+1} = \mcf_1)
	\]
	be the tuple defined in Definition~\ref{defn: tuple of flags mcf associated with sigma and u}. Let $\{\mcf_{j,k}\}_{j\in \Z, 1\le k \le d-1}$ be a set of decorated flags defined as follows:
	\begin{itemize}[wide, labelwidth=!, labelindent=0pt]
		\item $\mcf_{j+n, k} = \mcf_{j, k}$;
		\item $\mcf_{j,1} = \mcf_j$, $1\le j \le n+1$;
		\item If $\sigma(j) = 1$, define $\mcf_{j, k}^i = \mcf_{j}^i$ for $i \ge  k$ and $\mcf_{j, k}^i = \mcf_{j+1}^i$ for $i< k$;
		\item If $\sigma(j) = -1$, define $\mcf_{j, k}^i = \mcf_{j}^i$ for $i \le d-k$ and $\mcf_{j, k}^i = \mcf_{j+1}^i$ for $i > d-k$.
	\end{itemize}
	Then 
	\[
	\dec = (\mcf_{1, 1}, \mcf_{1, 2}, \dots, \mcf_{1, d-1}, \mcf_{2, 1}, \dots, \mcf_{2, d-1}, \dots, \mcf_{n, 1}, \dots, \mcf_{n, d-1}, \mcf_{n+1,1} = \mcf_{1, 1})
	\] 
	is a normalized cyclic decoration for $\beta_\sigma$.  
\end{lemma}


\begin{proof}
	First we check that $\mcf_{j, k}$ is decorated flag, for $j\in \Z$ and $k\in [1, d-1]$. All these extensors are nonzero as $f(\uu) \neq 0$. Without loss of generality, we assume that $\sigma(j) = 1$. By Proposition~ \ref{prop: recursive relation between flags associated with a signature}, we have
	\[
	\mcf_{j, k}^{k} = \mcf_{j}^{k} = \mcf_j^1 \wedge \mcf_{j+1}^{k-1} = \mcf_j^1 \wedge \mcf_{j, k}^{k-1}.
	\]
	Hence the nested condition is satisfied and $\mcf_{j, k}$ is a decorated flag. 

	For $j\in \Z$ and $k \in [1, d-2]$. Notice that $\mcf_{j,k}$ and $\mcf_{j,k+1}$ are in relative position $s_k$ (resp. $s_{d-k}$) if $\sigma(j) = 1$ (resp. $\sigma(j) = -1$); and the crossing value (cf.\ Definition~\ref{defn: crossing values}) is equal to $1$. Indeed, without loss of generality, we assume that $\sigma(j) = 1$, then
	\[
	\cv{\mcf_{j, k}}  {\mcf_{j, k+1}}{k} = \frac{\qwed{\mcf_j^k}{\mcf_{j+1}^k}{\mcf_{j+1}^{k-1}}}{\mcf_{j}^{k+1}} = \frac{\qwed{({\mcf_j^1 \wedge \mcf_{j+1}^{k-1}})}{\mcf_{j+1}^k}{\mcf_{j+1}^{k-1}}}{\mcf_j^1\wedge \mcf_{j+1}^{k}}=1. 
	\]
	Here the last equality follows from Lemma~\ref{lemma: cancellation law for quotient wedge}. Notice that $\mcf_{j, d-1}$ and $\mcf_{j+1, 1}$ are in relative position $s_{d-1}$ (resp. $s_1$) if $\sigma(j) = 1$ (resp. $\sigma(j) = -1$); and the crossing value 
	is equal to $f_j \neq 0$ (cf.\ Definition \ref{defn: generic point}). Indeed, without loss of generality, we assume that $\sigma(j) = 1$, then
	\[
	\cv{\mcf_{j, d-1}}  {\mcf_{j+1,1}}{d-1} = \frac{\qwed{\mcf_j^{d-1}}{\mcf_{j+1}^{d-1}}{\mcf_{j+1}^{d-2}}}{1} = \qwed{({\mcf_j^1 \wedge \mcf_{j+1}^{d-2}})}{\mcf_{j+1}^{d-1}}{\mcf_{j+1}^{d-2}}=\mcf_j^1\wedge \mcf_{j+1}^{d-1} = f_j. 
	\]
	This completes that proof that  $\dec$ is a normalized cyclic decoration for $\beta_\sigma$. 
\end{proof}


\begin{theorem}\label{thm: bijection between configuration spaces of signature and decorated flag moduli spaces}
	There is a $\emph{\text{SL}}(V)$-equivariant isomorphism
	\begin{equation}
	\Phi: \mfm(\beta_\sigma) \stackrel{\sim}{\longrightarrow} V^\sigma\setminus \{f = 0\}.
	\end{equation}
	%where the image is the non-vanishing locus of $f$ on $V^\sigma$ (cf.\ Definition \ref{defn: generic point}).
\end{theorem}
\begin{proof}
	Let 
	\[
	 \dec_{\beta_\sigma} = (\mcg_{1, 1}, \mcg_{1, 2}, \cdots, \mcg_{1, d-1}, \mcg_{2, 1}, \cdots, \mcg_{2, d-1}, \cdots, \mcg_{n, 1}, \cdots, \mcg_{n, d-1}, \mcg_{n+1, 1} = \mcg_{1, 1})
	\]
	be a normalized cyclic decoration for $\beta_\sigma$. Let $\mcg_j:= \mcg_{j, 1}$, $j\in [1, n+1]$. We define 
	\[
	\Phi(\dec_{\beta_\sigma}) = (\mcg_1^{\sigma(1)}, \mcg_2^{\sigma(2)}, \dots, \mcg_n^{\sigma(n)}) \in V^\sigma.
	\]
	Here we adopt the convention that $\mcg^{-1} := \mcg^{d-1}$.  Notice that the crossing value between $\mcg_{j, d-1}$ and $\mcg_{j+1, 1}$ is equal to $f_j(\Phi(\dec_{\beta_\sigma}))\neq 0$, for $j\in \Z$. Hence $f(\Phi(\dec_{\beta_\sigma})) \neq 0$ and therefore $\Phi(\dec_{\beta_\sigma}) \in V^\sigma \setminus \{f = 0\}$.


	The inverse of $\Phi$ is given in Lemma~\ref{lem: pre-assignment of top boundary flags}. Let us verify that they are indeed inverse to each other. 
	Consider the tuple
	\[
	\vec{\mcg} = (\mcg_1, \mcg_2, \dots, \mcg_n, \mcg_{n+1} = \mcg_1).
	\]
	Notice that by Lemma~\ref{lemma: decoration for interval word}, the flags $\mcg_{j, k}$ can be uniquely recovered from $\mcg_{j, 1} =\mcg_j$. So we only need to show that $\vec{\mcg} = \vec{\mcf}(\Phi(\dec_{\beta_\sigma}))$ (cf.\ Definition~\ref{defn: tuple of flags mcf associated with sigma and u}). 

	Let  $j\in [1, n]$. Suppose that $\sigma(j) = 1$. The normalized condition on the crossing values translate into the following identities:  for $k\in [1, d-2]$, we have $\cv{\mcg_{j, k}}{\mcg_{j, k+1}}{k} = 1$. Equivalently, 
	\begin{equation}\label{equ: crossing = 1}
	\mcg_{j, k}^{k+1} = \qwed{\mcg_{j, k}^k}{\mcg_{j, k+1}^k}{\mcg_{j, k}^{k-1}}, \quad k\in[1, d-2].
	\end{equation}
	Notice that $\mcg_{j, k}^{k} = \mcg_{j}^k, \mcg_{j, k+1}^k = \mcg_{j+1}^k, \mcg_{j,k}^{k-1} = \mcg_{j+1}^{k-1}$ and $\mcg_{j, k}^{k+1} = \mcg_{j}^{k+1}$. Then Equations ~(\ref{equ: crossing = 1}) are equivalent to
	\begin{equation}\label{equ: inductive formula}
	\mcg_j^{k+1} = \qwed{\mcg_j^k}{\mcg_{j+1}^k}{\mcg_{j+1}^{k-1}}, \quad k\in [1, d-2].
	\end{equation}
	Then by an induction on $k$, we can show that Equations (\ref{equ: inductive formula}) are equivalent to 
	\begin{equation}\label{equ: recursive formula for flags, black}
	\mcg_j^{k+1} = \mcg_j^1 \wedge \mcg_{j+1}^k, \quad k\in [1, d-2].
	\end{equation}
	Suppose that $\sigma(j) = -1$.  Similarly we have
	\begin{equation}\label{equ: recursive formula for flags, white}
	\mcg_{j}^{k} = \mcg_j^{d-1} \mixwed \mcg_{j+1}^{k+1}, \quad k \in [1, d-2].
	\end{equation}

	To sum up, the tuple $\vec{\mcg}$
	satisfies the recursive relations (\ref{equ: recursive formula for flags, black}) and (\ref{equ: recursive formula for flags, white}). Hence by Proposition~\ref{prop: recursive relation between flags associated with a signature}, $\vec{\mcg} = \vec{\mcf}(\Phi(\dec_{\beta_\sigma}))$.  
\end{proof}





Recall from Definition~\ref{defn: V sigma and rsigma} that the mixed Pl\"ucker ring
\[R_\sigma(V) = \C[V^\sigma]^{\slv},
\]
%the coordinate ring of the mixed Grassmannian,
is the ring of $\slv$-invariant polynomial functions on $V^\sigma$. The fraction field of $R_\sigma(V)$ is denoted by $\K$. It is well-known that $\K$ is equal to the field of $\slv$-invariant rational functions on $V^\sigma$ (cf.\ \cite[Theorem 3.3]{VinbergPopov}):
\[
K_\sigma(V) = \C(V^\sigma)^{\slv}.
\]



