\begin{remk}
	The product $f = \prod_{j = 1}^n f_j$ corresponds to frozen variables in the cluster algebra associated to $\sigma$. While inverting $f$ would align with geometric perspective of cluster algebras, we deliberately maintain $f$ as a geometric constraint rather than a formal inversion. This preserves the algebro-geometric interpretation of $\mfm(\beta_\sigma)$ as an open subvariety of $V^\sigma$, where non-vanishing of $f$ encodes the stability condition for flag configurations. The cluster structure nevertheless persists through the identification of $f_j$'s as generalized Plücker coordinates.
\end{remk}






\subsection{Cluster algebras from Demazure weaves}\label{sec: cluster alg associated with weaves}




Let $\ww$ be a Demazure weave with marked top word $\beta$.
We now construct its associated cluster algebra through the following geometric framework:
\begin{enumerate}[wide, labelwidth=!, labelindent=0pt]
	\item \textbf{Quiver Foundations}: Recall from Definition~\ref{defn: quiver associated with Demazure weaves} that $\ww$ determines a quiver $Q(\ww)$ encoding its combinatorial structure.
	\item \textbf{Geometric realization}: Cluster variables will be realized as rational functions on the decorated flag moduli space $\mfm(\beta)$ (Definition~\ref{defn: seed from weave}).
\end{enumerate}

%In this section, we are going to define the cluster algebra associated with $\ww$. We already know how to define the quiver $Q(\ww)$ associated with $\ww$ (see Definition~\ref{defn: quiver associated with Demazure weaves}), so we only need to assign rational functions (cluster/frozen variables) to the cycles in $\ww$. These rational functions will be defined on a suitable decorated flag moduli space. 

The results in this section are parallel to the results in \cite[Section 5]{CGGLSS}, but with different notations and conventions. 

\begin{defn}\label{defn: decorated demazure weave}
	A Demazure weave $\ww$ divides the ambient rectangle $R$ into faces. A \emph{decoration $\dec$ for $\ww$} is a set of decorated flags indexed by faces of $\ww$, satisfying the following condition:	
		 there exists $\Delta_\gamma\in \C$, one for each (Lusztig) cycle $\gamma$, such that the \emph{edge-crossing relation} is satisfied for every
		  weave line $e$:  suppose that $e$ is of color~$k$ and separates faces $U$ (left) and $V$ (right), then $\mcf_U\rel{k} \mcf_V$ and furthermore, the crossing value (cf.\ Definition~\ref{defn: crossing values}) is given by
		\begin{equation}\label{equation: edge value is equal to the product of cycles passing through}
			\Delta_e:= 	\cv {\mcf_U}{\mcf_V} k= \prod_{\gamma} \Delta_\gamma^{\gamma(e)}.
		\end{equation}


	A \emph{decorated Demazure weave} is a pair $(\ww, \dec)$ consisting of a Demazure weave $\ww$ and a decoration $\dec$ for $\ww$. We simply write $\ww$ if $\dec$ is clear from the context. 
\end{defn}

\begin{example}
	See Example~\ref{example: describing a seed from a decorated weave} for an explicit decorated Demazure weave with computed crossing values. 
\end{example}

\begin{remk}\label{remk: decoration of weave is the same as deco of the top word}
	Let $\beta$ be a marked word. We can view $\beta$ as a trivial Demazure weave $\ww_{\beta}: \beta \rarrow \beta$. 
	A decoration for the weave $\ww_{\beta}$ corresponds precisely to a {normalized decoration for $\beta$} (cf.\ Definition~\ref{defn: decoration of marked word}). Indeed, if a weave line $e$ (say of color $k$) in $\ww_\beta$ is incident to a unmarked boundary vertex, then no cycles passes through edge $e$, i.e., $\gamma(e) = 0$ for all $\gamma$; hence the crossing value $\Delta_e = \cv {\mcf_U}{\mcf_V} k = 1$. 

	Let $\ww$ be a Demazure weave with marked top word $\beta$. Then a decoration $\dec$ for $\ww$ restricts to a normalized decoration for $\beta$. Theorem~\ref{thm: unique extension of decorations for a weave} implies that the converse is also true: a normalized decoration for $\beta$ extends (uniquely) to a decoration for $\ww$. This bridges local flag configurations with global cycle invariants.
\end{remk}



\begin{theorem}\label{thm: unique extension of decorations for a weave}
	Let $\ww$ be a Demazure weave with marked top word $\beta = \ww_{\text{top}}$. Then a generic normalized decoration $\dec_{\beta}$ for $\beta$ extends uniquely to a decoration $\dec$ for $\ww$. Moreover, the numbers $\Delta_\gamma$ (cf.\ Definition~\ref{defn: decorated demazure weave}) are uniquely determined by $\dec_\beta$ (equivalently, by $\dec$). 
\end{theorem}

\begin{proof}
	We scan the Demazure weave $\ww$ from top to bottom, and extend the decoration as we meet new faces. In the meantime, we will define $\Delta_\gamma$ for new cycles $\gamma$, such that (\ref{equation: edge value is equal to the product of cycles passing through}) hold for new edges. To start with, since $\dec_\beta$ is normalized, we do have a valid decoration for the top of $\ww$, cf.\ Remark~\ref{remk: decoration of weave is the same as deco of the top word}. 

	Now as we scan downwards, there is nothing to be done until we will meet a new vertex $v$. 
	\begin{itemize}[wide, labelwidth=!, labelindent=0pt]
	\item If $v$ is trivalent, let $e$ be the edge below $v$. There is no new face, so we don't need to extend our decoration. However, we do have a new cycle $\gamma_v$, originated at $v$ with $\gamma_v(e) = 1$. We define 
	\[
	\Delta_{\gamma_v}: = {\Delta_e}\big/{\prod_{\gamma \in Y_v} \Delta_{\gamma}^{\gamma(e)}},
	\]
	where $Y_v$ is the set of all cycles originating above $v$. Notice that if a cycle $\gamma$ originates below $v$, then $\gamma(e) = 0$. Hence
	\[
		\Delta_e = \Delta_{\gamma_v} \prod_{\gamma \in  Y_v} \Delta_{\gamma}^{\gamma(e)} = \prod_{\gamma} \Delta_\gamma^{\gamma(e)}.
	\]

	\item If $v$ is $4$-valent, as in Figure~\ref{fig: 4-valent and 6-valent configuration}, let $U, V, W, X$ be the faces to the left, right, top, bottom of $v$; let $e$ of color $i$ (resp. $f$ of color $j$) be the edge separating $V$ (resp. $U$) and $W$, $|i-j|>1$; and $e'$ (resp. $f'$) be the edge separating $U$ (resp. $V$) and $X$. We have a new face $X$, so we extend our decoration by defining $\mcf_X$ as follows. Let $(\mcf_X)^k = (\mcf_{U})^k$ for $k\neq i$ and $(\mcf_X)^k = (\mcf_{V})^k$ for $k\neq j$. This is well-defined as $(\mcf_U)^k = (\mcf_{V})^k$ for $k\neq i, j$, and is clearly a decorated flag. There is no new cycle, and we need to verify (\ref{equation: edge value is equal to the product of cycles passing through}) for new edges $e'$ and $f'$. 

	Notice that $\Delta_{e'} = \cv{\mcf_U}{\mcf_X}{i} = \cv{\mcf_W} {\mcf_V}{i} = \Delta_{e}$; and $\gamma(e) = \gamma(e')$ for any cycle $\gamma$. Therefore $\Delta_{e'} = \Delta_e= \prod_{\gamma} \Delta_\gamma^{\gamma(e)} = \prod_{\gamma} \Delta_\gamma^{\gamma(e')}$. Similarly, we have $\Delta_{f'} = \prod_{\gamma} \Delta_\gamma^{\gamma(f')}$.
	\begin{figure}[H]
		\centering
		\includegraphics[trim =8cm 13cm 8cm 11cm, clip = true, scale = 0.45]{4-valent_and_6-valent_configuration.pdf}
		\caption{Decoration around a $4$-valent vertex (left) and at a $6$-valent vertex (right).}
		\label{fig: 4-valent and 6-valent configuration}
	\end{figure}
	\item If $v$ is $6$-valent. By duality (cf.\ Remark~ \ref{remk: duality of crossing values}), we may assume that it is the case of $i (i+1) i \rarrow (i+1) i (i+1)$, cf.\ Figure~\ref{fig: 4-valent and 6-valent configuration}. We have two new faces $T, S$, we extend the decoration by defining $\mcf_T$ and $\mcf_S$ as follows: $(\mcf_T)^k  := (\mcf_S)^k := (\mcf_U)^k$ for $k \neq i, i+1$, $(\mcf_T)^i := (\mcf_U)^i$, $(\mcf_S)^i := (\mcf_V)^i$, and 
	\[
	(\mcf_T)^{i+1} := (\mcf_S)^{i+1} := (\prod_{\gamma \in Y_v} \Delta_{\gamma}^{\gamma(c)})^{-1}\cdot(\qwed{\mcf_U^i}{\mcf_V^i}{\mcf_U^{i-1}}).
	\]
	There is no new cycle, and we need to verify (\ref{equation: edge value is equal to the product of cycles passing through}) for new edges $b, c$ and $d$. By definition, we have
	\[
	\Delta_c =\cv  {\mcf_T}  {\mcf_S}{i} = \frac{\qwed{\mcf_T^i}{\mcf_S^i}{\mcf_{T}^{i-1}}}{(\mcf_T)_{i+1}}= \frac{\qwed{\mcf_U^i}{\mcf_V^i}{\mcf_U^{i-1}}}{(\mcf_T)_{i+1}} = \prod_{\gamma\in Y_v} \Delta_{\gamma}^{\gamma(c)}=\prod_{\gamma} \Delta_{\gamma}^{\gamma(c)},
	\]
	where the last equality follows from the fact that if $\gamma$ is originated below $v$, then $\gamma(c) = 0$. Similarly, we have
	\[
	\Delta_b = \cv {\mcf_U}  {\mcf_T}{i+1} = \frac{\qwed{\mcf_U^{i+1}}{\mcf_T^{i+1}}{\mcf_U^i}}{(\mcf_U)_{i+2}} = \frac{\qwed{\mcf_U^{i+1}}{\big(\Delta_c^{-1}\cdot(\qwed{\mcf_U^i}{\mcf_V^i}{\mcf_U^{i-1}}) \big)}{\mcf_U^i}}{(\mcf_U)_{i+2}}\\
	= \frac{\qwed{\mcf_U^{i+1}}{\mcf_V^{i}}{\mcf_U^{i-1}}}{\Delta_c\cdot (\mcf_U)_{i+2}};
	\]
	where the last equality follows from Lemma~\ref{lemma: cancellation law for quotient wedge}. Similarly we have
	\[
	\Delta_e\Delta_f= \frac{\qwed{\mcf_H^i}{\mcf_V^i}{\mcf_U^{i-1}}}{\mcf_V^{i+1}}\cdot \frac{\qwed{\mcf_U^{i+1}}{\mcf_V^{i+1}}{\mcf_H^i}}{\mcf_U^{i+2}} = \frac{\qwed{\mcf_U^{i+1}}{(\qwed{\mcf_H^i}{\mcf_V^i}{\mcf_U^{i-1}})}{\mcf_H^i}}{\mcf_U^{i+2}}=\frac{\qwed{\mcf_U^{i+1}}{\mcf_V^{i}}{\mcf_U^{i-1}}}{(\mcf_U)_{i+2}}.
	\]
	Hence $\Delta_e\Delta_f = \Delta_b\Delta_c$. Now notice that $\gamma(b) + \gamma(c) = \gamma(e) + \gamma(f)$ for any cycle $\gamma$, so
	\[
	\Delta_b = \frac{\Delta_e\Delta_f}{\Delta_c} = \prod_{\gamma} \Delta_\gamma^{\gamma(e) + \gamma(f) - \gamma(c)} = \prod_{\gamma} \Delta_\gamma^{\gamma(b)}.
	\]
	Similarly 
	\[
	\Delta_d = \frac{\Delta_a\Delta_f}{\Delta_c} =  \prod_{\gamma} \Delta_\gamma^{\gamma(d)}.
	\]
	\end{itemize}	

	By continuing the scanning, we can extend the decoration to $\ww$; and for each cycle $\gamma$, we have defined $\Delta_\gamma$ such that $\Delta_e = \prod_{\gamma} \Delta_\gamma^{\gamma(e)}$ hold for all weave lines $e$. Therefore, we can extend a normalized decoration of $\beta$ to a decoration for $\ww$. The uniqueness of the extension is clear by the construction.

	Finally, notice that $\Delta_{\gamma_v}$ is uniquely determined by $\Delta_e$ and $\{\Delta_{\gamma}\}_{\gamma\in Y_v}$, where $e$ is the edge below $v$. So recursively, $\Delta_{\gamma_v}$ is uniquely determined by $\{\Delta_e\}_{e\in \ww}$, %and $\{\Delta_\gamma\}_{\gamma\in Y_{\text{top}}}$ where ${Y}_{\text{top}}$ is the set of cycles originated from the marked boundary vertices; 
	which are uniquely determined by $\dec_{\beta}$.
\end{proof}

\begin{remk}
	Let $\ww$ be a Demazure weave with marked top word $\beta$. Let $\gamma$ be a cycle in $\ww$. By Theorem~\ref{thm: unique extension of decorations for a weave}, $\Delta_\gamma$ can be viewed as a rational function on the space of normalized decorations for $\beta$. Notice that $\Delta_e$ is invariant under $\slv$ actions, so $\Delta_\gamma$ is a $\slv$-invariant rational function on $\mfmo(\beta)$, i.e., $\Delta_\gamma \in \C(\mfmo(\beta))^{\slv}$.
\end{remk}

\begin{remk}\label{remk: cycles are in Ksigma}
	Throughout this manuscript, every marked top word $\beta$ for a Demazure weave $\ww$ that we consider will be a contiguous subword of $\beta_\sigma$ for some signature $\sigma$, cf.\ Definition~\ref{defn: configuration space of a signature, and defn of beta sigma}. Therefore a normalized cyclic decoration for $\beta_\sigma$ induces a normalized decoration for $\beta$, i.e., we have a natural map 
	\[
	 \mfm(\beta_\sigma) \rightarrow \mfmo(\beta).
	\]
	This induces an inclusion of the corresponding fields of $\text{SL}(V)$-invariant rational functions:
	\[
	\C(\mfmo(\beta))^{{\text{SL}}(V)} \hookrightarrow \C(\mfm(\beta_\sigma))^{{\text{SL}}(V)} \cong  \K.
	\]
	The isomorphism $\C(\mfm(\beta_\sigma))^{{\text{SL}}(V)} \cong \K$ follows from Corollary~\ref{cor: decorated flag moduli space and the mixed grassmannian} (recall that $\K$ is the fraction field of $\rsigma$).  Hence for any cycle $\gamma$ in $\ww$, we can view $\Delta_\gamma$ as an element of $\K$. 
\end{remk}





\begin{defn} \label{defn: seed from weave}
	Let $\beta$ be a marked contiguous subword of $\beta_\sigma$ for a signature $\sigma$. Let $\ww$ be a Demazure weave with marked top word $\beta$. 
	We define \emph{the seed} 
	\[
	\seed(\ww) = (Q(\ww), \zz(\ww))
	\]
	\emph{associated with a Demazure weave $\ww$}, as a seed in $\K$ given as follows. 

	The quiver $Q(\ww)$ is defined as in Definition~\ref{defn: quiver associated with Demazure weaves}. 
	Recall that the set of vertices of $Q(\ww)$ is indexed by the set of cycles in $\ww$. A vertex of $Q(\ww)$ is designated frozen (resp., mutable) if the corresponding cycle is frozen (resp., mutable). The number of arrows between two vertices is the intersection pairing of the corresponding cycles, cf.\ Definition~\ref{defn:local intersection pairing}.

	We define the cluster $\zz(\ww)$ by setting
	the cluster (or frozen) variable associated with a vertex in $Q(\ww)$ to be $\Delta_\gamma \in \K$, where $\gamma$ is the cycle corresponding to that vertex. 

	\emph{The cluster algebra $\mca(\ww)$ associated with a  Demazure weave $\ww$} is the cluster algebra associated with the seed $\seed(\ww)$. 
\end{defn}

\begin{remk}
	Strictly speaking we cannot  call $\seed(\ww)$ a seed since we don't yet know if the  cluster/frozen variables $\Delta_\gamma$ are algebraically independent. We will prove that the choices described in later sections guarantee that $\seed(\ww)$ is a seed, cf.\ Lemma~\ref{lemma: alg indep of the cluster}. Nevertheless, we would like to point out that the results for the seed mutations associated with Demazure weaves in the next few sections do not rely on Lemma~\ref{lemma: alg indep of the cluster}. To be precise, when we say two seeds $\seed_1 = (Q_1, \zz_1)$ and $\seed_2 = (Q_2, \zz_2)$ are mutation equivalent, what we mean is that $Q_1$ and $Q_2$ are related by a sequence of mutations, and applying the corresponding exchange transformations to the collection $\zz_1$ produce the collection $\zz_2$. 
\end{remk}



\begin{example}
For an explicit illustration of the seed construction in Definition~\ref{defn: seed from weave}, including the assignment of cluster variables to cycles, computation of crossing values, and quiver mutation dynamics, see Example~\ref{example: describing a seed from a decorated weave}. This step-by-step walkthrough demonstrates how a decorated Demazure weave explicitly determines a cluster seed, bridging the combinatorial topology of weaves with the algebraic structure of cluster algebras.
\end{example}



In the remainder of this section, we establish that mutation-equivalent Demazure weaves produce mutation-equivalent seeds, thereby demonstrating the invariance of their associated cluster algebras under weave mutations.



\begin{defn}
	Two decorated Demazure weaves are \emph{equivalent} (resp., \emph{mutation equivalent}) if the underlying weaves are equivalent (resp., mutation equivalent) and their decorations for the marked top word are the same. 
\end{defn}
\begin{lemma} \label{lemma: mutation equivalent weave same bottom flags}
	Let $\ww, \ww': \beta \rarrow \beta'$ be two mutation equivalent decorated Demazure weaves. Then they have the same decoration for the bottom word. 
\end{lemma}
\begin{proof}
	We only need to show that under a single local equivalence/mutation move, the decorated bottom words remain the same. Here we demonstrate the proof for one move, the proof for other moves is similar. 

	Consider the local equivalence move Pushthrough from below, cf.\ Figure~\ref{fig: equivalent pushthrough from below bottom flag unchanged}. Without loss of generality, we assume that $j = i+1$. We need to show that $\mch = \mch'$ and $\mck = \mck'$. 

	Notice that $\mch^k = \mcg_k = (\mch')^k$ and $\mck^k = \mathcal{I}^k = (\mck')^k$ for $k \neq i+1$, so we only need to show that $\mch^{i+1} = (\mch')^{i+1}$ and $\mck^{i+1} = (\mck')^{i+1}$. 
	\begin{figure}
		\centering
		\includegraphics[trim = 3cm 10cm 0cm 11cm, clip = true, scale = 0.4]{equivalent_pushthrough_from_below_bottom_flag_unchanged.pdf}
		\caption{Two decorated Demazure weaves related by a single local move Pushthrough from below.}
		\label{fig: equivalent pushthrough from below bottom flag unchanged}
	\end{figure}
	By Lemma~\ref{lemma: cycles end behavior remain unchanged under mutation}, we have $\gamma(h) = \gamma'(h)$ for any cycle $\gamma$ in $\ww$ and the corresponding cycle $\gamma'\in \ww'$. Let $Y_v$ (resp. $Y'_{v'}$) be the cycles in $\ww$ (resp. $\ww'$) that originates above $v$ (resp. $v'$); there is a 1-1 correspondence between $Y_v$ and $Y'_{v'}$. Notice that if $\gamma \notin Y_v$ (and $\gamma'\notin Y'_{v'}$), then $\gamma(h) = 0$ and $\gamma'(h) =  0$.
	Hence
	\[
		\Delta_h(\ww) =\prod_{\gamma\in Y_v}\Delta_{\gamma}^{\gamma(h)} =  \prod_{\gamma'\in Y'_{v'}}\Delta_{\gamma'}^{\gamma'(h)} = \Delta_{h}(\ww').
	\]
	Then by Definition~\ref{defn: crossing values}, we have
	\[
	\Delta_h(\ww) = \cv{\mch}{\mathcal{K}}{i} = \frac{\qwed{\mch^i}{\mck^i}{\mch^{i-1}}}{\mch^{i+1}} = \frac{\qwed{\mcg^i}{\mathcal{I}^i}{\mcg^{i-1}}}{\mch^{i+1}}; \]
	and
	\[ 
	\Delta_{h}(\ww') =\cv {\mch'}  {\mathcal{K'}}{i} = \frac{\qwed{{\mch'}^i}{{\mck'}^i}{{\mch'}^{i-1}}}{{\mch'}^{i+1}} = \frac{\qwed{\mcg^i}{\mathcal{I}^i}{\mcg^{i-1}}}{{\mch'}^{i+1}}.
	\]
	Hence $\Delta_h(\ww) = \Delta_{h}(\ww')$ implies $\mch^{i+1} = {\mch'}^{i+1}$. Similarly we have $\mck^{i+1} = {\mck'}^{i+1}$.\qedhere
\end{proof}


\begin{theorem}\label{thm: mutation equivalence demazure weaves yield mutation equivalent seeds}
	The seeds associated with equivalent (resp., mutation equivalent) Demazure weaves are the same (resp., mutation equivalent). Consequently, the cluster algebra associated with mutation equivalent Demazure weaves are the same. 
\end{theorem}


\begin{proof}
	Let us first show that the seeds associated with equivalent Demazure weaves are the same. Similar to the proof of Lemma~\ref{lemma: mutation equivalent weave same bottom flags}, we only demonstrate the proof for one move, cf.\ Figure~\ref{fig: equivalent pushthrough from below bottom flag unchanged}.  By Proposition~\ref{prop: mutation equivalent weaves yield mutation equivalent quivers}, $Q(\ww) = Q(\ww')$. 

	Let $Y_v$ (resp. $Y'_{v'}$) be the cycles in $\ww$ (resp. $\ww'$) that originates above $v$ (resp. $v'$). If $\gamma \in Y_v$, and let $\gamma' \in Y'_{v'}$ be the corresponding cycle in $\ww'$, then $\Delta_\gamma = \Delta_{\gamma'}$ as $\ww$ and $\ww'$ are the same above the local picture. Now let us show that $\Delta_{\gamma_v} = \Delta_{\gamma_{v'}}$.

	By Lemma~\ref{lemma: mutation equivalent weave same bottom flags}, $\mathcal{K} = \mathcal{K'}$, hence 
	\[\Delta_n(\ww)= \cv{\mathcal{K}}{\mathcal{I}}{j} = \cv{\mck}{\mathcal{I}}{j} = \Delta_{n}(\ww').\]
	Notice that
	\[
	\Delta_n(\ww) = \Delta_{\gamma_v}^{\gamma_v(n)}\prod_{\gamma \neq \gamma_v}\Delta_{\gamma}^{\gamma(n)} \quad \text{and} \quad   \Delta_{n}(\ww')= \Delta_{\gamma_{v'}}^{\gamma_{v'}(n)}\prod_{\gamma' \neq \gamma_{v'}} \Delta_{\gamma'}^{\gamma'(n)}.
	\]
	By Lemma~\ref{lemma: cycles end behavior remain unchanged under mutation}, we have $\gamma(n) = \gamma'(n)$ for any cycle $\gamma$ in $\ww$ and it is corresponding cycle $\gamma'$ in $\ww'$. Notice that if $\gamma \notin Y_v$ and $\gamma \neq \gamma_v$, then $\gamma(n) = 0$ and $\gamma'(n) = 0$. 
	Also notice that $\gamma_v(n) = \gamma_{v'}(n) = 1$. So we can conclude that $\Delta_{\gamma_v} = \Delta_{\gamma_{v'}}$.

	Finally if $\gamma \notin Y_v$ and $\gamma \neq \gamma_v$, then $\gamma$ and $\gamma'$ originate below $v$ and $v'$, respectively. Now as we have shown that $\Delta_{\gamma_v} = \Delta_{\gamma_{v'}}$, we conclude that $\Delta_\gamma = \Delta_{\gamma'}$ as they are both defined recursively. 
	This completes the proof that the seeds associated with equivalent Demazure weaves are the same.

	\begin{figure}[H]
		\centering
		\includegraphics[trim = 0.5cm 7.5cm 0cm 13cm, clip = true, scale = 0.38]{local_mutation_move_seeds_version.pdf}
		\caption{A local mutation move.}
		\label{fig: local mutation move seeds version}
	\end{figure}
	Now we need to show that the seeds associated with mutation equivalent Demazure weaves are mutation equivalent. Since equivalence move does not change seeds, we only need to show that under a single mutation move (cf.\ Figure~\ref{fig: local mutation move seeds version}), the seeds associated with the corresponding Demazure weaves are mutation equivalent. To be precise, we are going to show that $\seed(\ww') = \mu_{\gamma_{v}}(\seed(\ww))$. 

	By Proposition~\ref{prop: mutation equivalent weaves yield mutation equivalent quivers}, we know that $Q(\ww') = \mu_{\gamma_v}(Q(\ww))$. Now we show that the cluster variables other than $\Delta_{\gamma_v}$ (resp., $\Delta_{\gamma_{v'}}$) coincide, and $\Delta_{\gamma_v}$ and $\Delta_{\gamma_{v'}}$ satisfy the exchange relation. 

	Let $\gamma$ be a cycle in $\ww$ that originates above $v$ and $\gamma'$ be the corresponding cycle in $\ww'$. Then $\Delta_\gamma = \Delta_{\gamma'}$ as they are recursively defined by the cycles above, and $\ww$ and $\ww'$ are the same above the local picture. 

	Let $\gamma$ be a cycle in $\ww$ that originates below $v$. Then $\Delta_\gamma$ is recursively defined by all the cycles above it other than $\gamma_v$. This is because $\gamma_v$ ends at $w$, it will not enter the edge where $\gamma$ originates. Similarly, the corresponding cycle $\Delta_{\gamma'}$ in $\ww'$ is recursively (under the same formula) defined by all cycles above it other than $\gamma_{v'}$. Therefore, $\Delta_\gamma = \Delta_{\gamma'}$. 

	Let $Y$ (resp. $Y'$) be the set of cycles $\gamma \neq \gamma_v$ (resp. $\gamma'\neq \gamma_{v'}$) in $\ww$ (resp. $\ww'$). Then the discussion above shows that $\Delta_{\gamma} = \Delta_{\gamma'}$ for $\gamma\in Y$ and $\gamma'\in Y'$.

	Finally let us show that $\Delta_{\gamma_v}$ and $\Delta_{\gamma_{v'}}$ satisfy the exchange relation:
	\[
	\Delta_{\gamma_v}\Delta_{\gamma_{v'}}= \prod_{\gamma\in Y}\Delta_{\gamma}^{[\langle \gamma, \gamma_v \rangle]_+} + \prod_{\gamma\in Y}\Delta_{\gamma}^{-[\langle \gamma, \gamma_v \rangle]_-}.
	\]
	By $3$-term Pl\"ucker relations, we have
	\begin{equation}
		\Delta_{e}\Delta_{e'} = \Delta_{a}\Delta_{c} + \Delta_b\Delta_d.
	\end{equation}
	Furthermore, we have 
	\[
	\Delta_e = \Delta_{\gamma_v}\prod_{\gamma\in Y}\Delta_{\gamma}^{\gamma(e)} \quad \text{and}\quad \Delta_{e'} = \Delta_{\gamma_{v'}}\prod_{\gamma'\in Y'} \Delta_{\gamma'}^{\gamma'(e')};
	\]
	and let $\ell \in \{a, b, c, d\}$, notice that $\gamma_v(\ell) = 0$. Hence
	\[
	\Delta_\ell = \Delta_{\gamma_v}^{\gamma_v(\ell)}\prod_{\gamma\in Y}\Delta_{\gamma}^{\gamma(\ell)} =\prod_{\gamma\in Y}\Delta_{\gamma}^{\gamma(\ell)}.
	\]
	Therefore we have
	\[
	\Delta_{\gamma_v}\Delta_{\gamma_{v'}}\prod_{\gamma\in Y} \Delta_{\gamma}^{\gamma(e)+\gamma'(e')} = \prod_{\gamma\in Y}\Delta_{\gamma}^{\gamma(a) + \gamma(c)} + \prod_{\gamma\in Y}\Delta_{\gamma}^{\gamma(b) + \gamma(d)},
	\]
	where on the left the identity, we are using the fact that $\Delta_\gamma = \Delta_{\gamma'}$. 
	Hence
	\[
	\Delta_{\gamma_v}\Delta_{\gamma_{v'}}= \prod_{\gamma\in Y}\Delta_{\gamma}^{\gamma(a) + \gamma(c) - (\gamma(e)+\gamma'(e'))} + \prod_{\gamma\in Y}\Delta_{\gamma}^{\gamma(b) + \gamma(d)-(\gamma(e)+\gamma'(e'))}.
	\]
	Notice that
	\[
	\gamma(a) + \gamma(c) - (\gamma(e)+\gamma'(e')) = \gamma(a) + \gamma(c)  - \min\{\gamma(b), \gamma(c)\} - \min\{\gamma(a), \gamma(b)\};
	\]
	\begin{multline*}
	\gamma(b) + \gamma(d)-(\gamma(e)+\gamma'(e')) \\= \gamma(b) + \min\{\gamma(a), \gamma(b),\gamma(c)\}- \min\{\gamma(b), \gamma(c)\} - \min\{\gamma(a), \gamma(b)\};
	\end{multline*}
	and
	\[
	\langle \gamma, \gamma_v \rangle = \gamma(a) - \gamma(b) + \gamma(c) - \min\{\gamma(a), \gamma(b), \gamma(c)\}.
	\]
	Hence by Lemma~\ref{lemma: min equality}, we have
	\[
	\gamma(a) + \gamma(c) - (\gamma(e)+\gamma'(e')) = [\langle \gamma, \gamma_v \rangle]_+;
	\]
	\[
	\gamma(b) + \gamma(d)-(\gamma(e)+\gamma'(e')) = -[\langle \gamma, \gamma_v \rangle]_-;
	\]
	and therefore we have
	\[
	\Delta_{\gamma_v}\Delta_{\gamma_{v'}}= \prod_{\gamma\in Y}\Delta_{\gamma}^{[\langle \gamma, \gamma_v \rangle]_+} + \prod_{\gamma\in Y}\Delta_{\gamma}^{-[\langle \gamma, \gamma_v \rangle]_-}.
	\]
	This completes the proof that $\seed(\ww') = \mu_{\gamma_{v}}(\seed(\ww))$.
\end{proof}







\begin{lemma}\label{lemma: min equality}
	Let $a, b, c \in \Z$, then we have the following identities.
	\begin{enumerate}
		\item $[a-b+c-\min\{a, b, c\}]_+ =  a + c - \min\{b, c\} - \min\{a, b\}$.
		\item $-[a-b+c-\min\{a, b, c\}]_- = b - \min\{b, c\} - \min\{a, b\} + \min\{a, b, c\}$.
	\end{enumerate}
	Here $[x]_+ := \max\{x, 0\}$ and $[x]_- := \min\{x, 0\}$.
\end{lemma}
\begin{proof}
	By tropicalizing the identity
	\[
	\frac{(t^a+t^b+t^c)t^b}{t^{a+c}} + t^0  = \frac{(t^b+t^c)(t^a+t^b)}{t^{a+c}},
	\]
	we get 
	\[\min\{\min\{a, b, c\} + b - a - c, 0\} = \min\{b, c\} + \min\{a, b\} - a - c,\]
	hence the first identity holds since $[x]_+ = -[-x]_-$.
	The second identity holds since $[x]_+ + [x]_- = x$.
\end{proof}



\begin{theorem}\label{thm: demazure weaves same top/bottom yield mutation equivalent seeds}
	Let $\ww, \ww': \beta \rarrow \beta'$ be two reduced Demazure weaves. Then the seeds $\seed(\ww)$ and $\seed(\ww')$ are mutation equivalent. Consequently, $\mca(\ww) = \mca(\ww')$.
\end{theorem}
\begin{proof}
	This follows from Theorem~\ref{thm: demazure classification} and Theorem~\ref{thm: mutation equivalence demazure weaves yield mutation equivalent seeds}.
\end{proof}











\subsection{Cluster structures in mixed Grassmannians}\label{sec: cluster structure on mixed Grassmannians}

In this section, we formulate (and illustrate) our main results concerning the existence of cluster structures on mixed Plücker rings. 



Let $\sigma$ be a size $n$ $d$-admissible signature of type $(a, b)$, cf.\ Definition~\ref{defn: admissible signature}. 
\textbf{Critical constraints are}:
\begin{itemize}
	\item odd dimension: $d$ is odd;
	\item size condition: $n > d^2$.
\end{itemize}
%\textbf{From now on, we assume that $d$ is odd and $n>d^2$.} 
These constraints will be assumed as always unless stated otherwise. The necessity of these constraints is explained in Remark~\ref{remk: d odd and n>d squared explained}.




We first define a cluster algebra $\mcas$ (Definition~\ref{defn: cluster algebra A sigma}) for the chosen signature and then state that the mixed Pl\"ucker ring $R_\sigma$ is equal to the cluster algebra $\mcas$ (Theorem~\ref{thm: mixed grassmannian is a cluster algebra}). 






\begin{defn}
	Let $p, q\in [1, n]$. \emph{The $n$-cyclic distance between $p$ and $q$}, denoted by $\|p-q\|_n$, is defined as
	\[
	\|p-q\|_n := \min\{|p-q|, n - |p-q|\}.
	\]
	We usually write $\|p-q\|$ if $n$ is clear from the context. 
\end{defn}

\begin{defn}\label{defn: valid cut in general}
	Let $1\le p\le q \le n$. We say that a pair $(p, q)$ is a \emph{valid cut of $\sigma$} if $\|p - q\| \ge d+1$. 
\end{defn}


\begin{defn}\label{defn: reversed word}
	Let $\beta$ be a word. We use $\rev \beta$ to denote the reversed word of $\beta$. For example, if $\beta = 123121$, then $\rev \beta = 121321$. If $\beta$ is marked, then we require the same marking on $\rev \beta$ as on $\beta$. As an example, if $\beta = \overline{1}23\overline{1}2\overline{1}$, then $\rev \beta = \overline{1} 2 \overline{1} 32 \overline{1}$. 
\end{defn}


Recall from Definition~\ref{defn: configuration space of a signature, and defn of beta sigma} that the marked words $\rho = 12\cdots \overline{(d-1)}$ and $\rho^* = {(d-1)}\cdots 2\overline{1}$ (with the last character marked).  The word associated with $\sigma$ is
\[
\beta_\sigma = \prod_{j = 1}^n \rho_{j}, \quad \rho_j \in \{\rho, \rho^*\}
\]
where $\rho_j = \rho$ (resp. $\rho_j = \rho^*$) if $\sigma(j) = 1$ (resp. $\sigma(j) = -1$). 
%In other words, $\beta_\sigma$ is a concatenation of $n$ copys of $\rho$ or $\rho^*$ such that the $j$-th subword is $\rho$ (resp. $\rho^*$) if $\sigma(j) = 1$ (resp. $\sigma(j) = -1$), $1\le j \le n$.

We first defined two reduced Demazure weaves associated with $\sigma$ with respect to a valid cut $(p, q)$. 

\begin{defn}\label{defn: cutting along the disk to get two weaves}
%By the cyclic natural of $\sigma$, we should view $\beta_\sigma$ as a cyclic word, i.e., $\beta_\sigma = \prod_{j = k}^{n+k-1} \rho_j$ for any $k\in \Z$. 
Consider a valid cut $(p, q)$ of $\sigma$. It will break $\beta_\sigma$ into two marked subwords
\[
\beta_1 = \beta_\sigma(p, q) =  \prod_{j = p}^{q-1} \rho_j\quad \text{and} \quad \beta_2 = \beta_\sigma(q, p+n) =  \prod_{j = q}^{p+n-1} \rho_j,
\]
where $\rho_j = \rho$ (resp., $ \rho_j = {\rho^*}$) if $\sigma(j) = 1$ (resp., $\sigma(j) = -1$). 
%Notice that $\beta_\sigma = \beta_1\beta_2$ as cyclic words. 
Let $\ww_1, \ww_2$ be  two reduced Demazure weaves 
\[
\ww_1 = \ww_\sigma(p, q): \beta_1 \rarrow \beta_1', \quad \ww_2 = \ww_\sigma(q, p+n) : \beta_2 \rarrow \beta_2',
\] 
where $\beta_1'$ and $\beta_2'$ are reduced words such that $\beta_1' = \rev{\beta_2'}$ (this is possible as they are both braid equivalent to $w_0$, by Lemma~\ref{lemma: bottom word is w0}).
\end{defn}


Now we define the cluster algebra associated with $\sigma$ with respect to a valid cut $(p, q)$.
\begin{defn}\label{defn: cluster algebra cutting at p, q}
Let $\seed_1 = \seed(\ww_1)$ be the seed associated with $\ww_1 = \ww_\sigma(p, q)$ and $\seed_2 = \seed(\ww_2)$ be the seed associated with $\ww_2 = \ww_\sigma(q, p+n)$, cf.\ Definition~\ref{defn: seed from weave}. Then by Lemma~\ref{lemma: amalgamation condition is satisfied}, $\seed_1$ and $\seed_2$ can be amalgamated along
\[
\zz_0 = \{\mcf_p^1\wedge \mcf_q^{d-1}, \mcf_p^2\wedge \mcf_q^{d-2}, \dots, \mcf_p^{d-1}\wedge \mcf_q^1\}.
\]
Let 
$\seed_\sigma(p, q):= \glueseeds{\seed_1}{\seed_2}{\zz_0}
$
be the amalgamated seed, cf.\ Definition~\ref{defn: amalgamating two seeds}; and let $\mca_\sigma(p, q)$ be the cluster algebra associated with $\seed_\sigma(p, q)$. 
\end{defn}

\begin{remk}
	Notice that $\seed_\sigma(p, q)$ does not depend on the choice of the (reduced) bottom words for $\ww_1$ and $\ww_2$ (we do require them to be reverse to each other), as changing the bottom word will only change the intersection pairings between the frozen variables in $\zz_0$, and these intersection pairings in $\ww_1$ will cancel out with those in $\ww_2$ when we amalgamate them. Also notice that $\mca_\sigma(p, q)$ does not depend on the choice of $\ww_1$ and $\ww_2$, since different choices of reduced Demazure weaves will result in mutation equivalent seeds by Theorem~\ref{thm: mutation equivalence demazure weaves yield mutation equivalent seeds}. 
\end{remk}


\begin{remk}\label{remk: d odd and n>d squared explained}
	Let us first explain why we require $d$ to be odd. By Proposition~\ref{prop: decoration flags of the initial weave}, the frozen variables in $\ww_1$ associated with the cycles ending at the bottom boundary of $\ww_1$ are 
	\[
	\{\mcf_p^1\wedge \mcf_q^{d-1}, \mcf_p^2\wedge \mcf_q^{d-2}, \dots, \mcf_p^{d-1}\wedge \mcf_q^1\};
	\]
	while the corresponding frozen variables in $\ww_2$ are
	\[
	\{\mcf_q^{d-1}\wedge \mcf_p^{1}, \mcf_q^{d-2}\wedge \mcf_p^{2}, \dots, \mcf_q^{1}\wedge \mcf_p^{d-1}\}.
	\]
	Notice a sign difference between these two sets:
	\[
	\mcf_p^k\wedge \mcf_q^{d-k} = (-1)^{k(d-k)} \mcf_q^{d-k}\wedge \mcf_p^k\  \text{ for }  k\in [1, d-1].
	\]
	Requiring $d$ to be odd resolves the sign difference.


	Why would such a sign issue arise? The key observation is that the mixed Grassmannian only have cyclic symmetry up to a sign. Detailed discussion on the sign issue and one potential solution to the even dimension case can be found in Section \ref{sec: intro main results}.  %This can already be seen in the case of the Grassmannian $\text{Gr}_{2, 4}$: the set of Pl\"ucker variables $P_{ij}$ is not invariant under cyclic shifts of indices. 
	%Requiring $d$ to be odd resolves the problem, since in that case, the set of Pl\"ucker variables is invariant under cyclic shifts. 

	%One potential solution in the case when $d$ is even relies on breaking the cyclic symmetry by toggling the signs. Similar problem arose in the study of cluster structures for the positroid varieties by Casals, Le, Sherman-Bennett and Weng \cite{CasalsLeSBWeng}; they resolved the issue by introducing  \emph{sign curves}, cf.\ \cite[Appendix A2]{CasalsLeSBWeng}. We expect a similar method to be applicable to our case. Due to time constraints, we were unable to complete the required verification. 


	As explained in Section \ref{sec: intro main results}, the condition $n>d^2$ is not essential for the construction of cluster structures in mixed Grassmannians, but is needed  for the proof of the main theorem. When the signature is ``nice", the condition $n>d^2$ can be relaxed significantly (e.g., cf.\ Theorem~\ref{thm: mixed grassmannian is a cluster algebra in the case of separated signatures}).  
	 %Example~\ref{example: describing a seed from a decorated weave} is an example that things work out just fine even if $n\le d^2$. 
\end{remk}

The subscript $\sigma$ will be dropped in $\beta_\sigma(p,q), \ww_\sigma(p,q), \seed_\sigma(p, q), \mca_\sigma(p, q)$, etc., when $\sigma$ is clear from the context.  



The following two lemmas are needed for Definition~\ref{defn: cutting along the disk to get two weaves} and Definition~\ref{defn: cluster algebra cutting at p, q}, and will be proved later in Section~\ref{sec: initial weave} and~\ref{section: weyl generators} respectively. 
\begin{lemma}\label{lemma: bottom word is w0}
	In Definition~\ref{defn: cutting along the disk to get two weaves}, $\beta'_1$ and $\beta'_2$ are reduced words for $w_0\in S_d$.
\end{lemma}

\begin{lemma}\label{lemma: amalgamation condition is satisfied}
	In Definition~\ref{defn: cluster algebra cutting at p, q}, the two seeds $\seed_1$ and $\seed_2$ can be amalgamated along the subset $\zz_0 = \{\mcf_p^1\wedge \mcf_q^{d-1}, \mcf_p^2\wedge \mcf_q^{d-2}, \dots, \mcf_p^{d-1}\wedge \mcf_q^1\}$.
\end{lemma}








Let us work out an example in detail, describing the cluster algebra $\mcas(1, 5)$. 

