\subsection{The cluster algebra $\mcas$ is well defined}\label{sec: ca does not depend of the choice of the cut}

The section proves Proposition~\ref{prop: cluster algebra does not depend on the cut}, which establishes that the cluster structure on a  mixed Grassmannian remain invariant under different choices of the cut $(p, q)$.

Recall from Definition~\ref{defn: interval words} that an interval word for an interval $[i, j]$ is a word either of the form $I_i^j = i (i+1)\cdots j$ or  of the form $I_j^i = j (j-1)\cdots i$, for $1\le i \le j \le d-1$.

\begin{defn}\label{defn: nested words and complete nested words}
	A word $T$ is called \emph{nested} if it has the form
	\[
	T = T_sT_{s+1}\cdots T_{d-1}, \quad \text{for some } s\in [1, d-1]
	\]
	where $T_s, \dots, T_{d-1}$ are interval words such that
	\begin{itemize}[wide, labelwidth=!, labelindent=0pt]
		\item $T_{d-1}$ is an interval word for $[1,d-1]$;
		\item for $k\in [s, d-1]$, $T_k$ is an interval word for $[i, j]$, $1\le i \le j \le d-1$; 
		\item for $k\ge s+1$, if $T_k = I_i^j$, then $T_{k-1}$ is an interval word for $[i+1, j]$; if $T_k = I_j^i$, then $T_{k-1}$ is an interval word for $[i, j-1]$. 
	\end{itemize}
	We call a nested word $T$ \emph{complete} if $s = 1$. For $k\in [s, d-1]$, $T_k$ is said to be an interval word for $T$. 
\end{defn}


\begin{example}
	$T^+ := I_{d-1}^{d-1}I_{d-2}^{d-1}\cdots I_1^{d-1}$ is a complete nested word with all $T_k$ increasing; and $T^-:= I_{1}^{1}I_{2}^{1}\cdots I_{d-1}^1$ is a complete nested word with all $T_k$ decreasing. 
\end{example}







\begin{remk}
	Let $T$ be a nested word as in Definition~\ref{defn: nested words and complete nested words}. For $k\in [1, d-1]$, let $x$ (resp. $y$) be the number of increasing (resp. decreasing) words $T_i$ with $i>k$. Then $T_k$ is an interval word for $[i, j]$ with $i =  x +1$ and $j = d- 1 - y$.
\end{remk}

\begin{defn}
	A \emph{marked complete nested word} is a complete nested word $T = T_1T_2\cdots T_{d-1}$ in which the last character of each interval word $T_k$ is marked.  As an example, $T = \bar{4}3\bar423\bar 4 123 \bar 4$ is a marked complete nested word. This is the only marking we will  be considering for a complete nested word.
\end{defn}


It's well-known that all complete nested words are braid equivalent to the longest reduced word $w_0$ in $S_d$. Moreover, the marking is preserved under the equivalence in the sense as described in the next lemma.

We say that an edge of a Demazure weave is a \emph{bottom edge} (resp., \emph{top edge}) if it is incident to the bottom boundary (resp., top boundary) of the weave. 

\begin{lemma}\label{lemma: complete nested words are all related by braid moves}
	Let $T$ be a marked complete nested word. Then any Demazure weave $\ww: T\rarrow T^+$ has the property that a bottom edge has a cycle passing through it if and only if the edge corresponds to a marked character in $T^+$. 
\end{lemma}
\begin{proof}
	First we notice that we only need to prove the statement for a specific Demazure weave by Theorem~\ref{thm: demazure classification} and Lemma~\ref{lemma: cycles end behavior remain unchanged under mutation}.

	Let us start with $T = T^{-} = I_1^1 \cdots I_{d-2}^1 I_{d-1}^1$. 
	Notice that we have partial weaves $I_k^1 I_{d-1}^1 \rarrow I_{d-1}^1I_{k+1}^2$ for any $1\le k \le d-2$. Indeed, when $k = d-2$, it is of the form in Figure~\ref{fig: T- to T+ boundary case} with $i = 1$; and when $k< d-2$, it is of the form in Figure~\ref{fig: T- to T+ generic case}.
	\begin{figure}[H]
		\centering
		\includegraphics[trim= 0cm 5cm 5.5cm 2cm, clip = true, scale = 0.38]{T-toT+boundary_case.pdf}
		\caption{A (local) weave $\ww: I_{d-2}^i I_{d-1}^i \rarrow I_{d-1}^i I_{d-1}^{i+1}$, $1\le i \le d-2$.}
		\label{fig: T- to T+ boundary case}
	\end{figure}
	\begin{figure}[H]
		\centering
		\includegraphics[trim= 0cm 9cm 22cm 2cm, clip = true, scale = 0.38]{T-toT+generic_case.pdf}
		\caption{A (local) weave $\ww: I_{k}^i I_{d-1}^i \rarrow I_{d-1}^iI_{k+1}^{i+1}$, $1\le i\le k <d-2$.}
		\label{fig: T- to T+ generic case}
	\end{figure}

	Now for $k = d-2, d-3, \dots, 1$, by concatenating these $d-2$ partial weaves $I_k^1 I_{d-1}^1 \rarrow  I_{d-1}^1I_{k+1}^2$, we  obtain a Demazure weave
	\begin{multline*}
	T^- = I_{1}^{1}\cdots I_{d-2}^1 I_{d-1}^1 \rarrow  I_1^1  \cdots I_{d-3}^1 I_{d-1}^1 I_{d-1}^2\\ \rarrow
	  I_1^1 \cdots I_{d-4}^1 I_{d-1}^1 I_{d-2}^2 I_{d-1}^2 \rarrow \cdots \rarrow  I_{d-1}^1 I_{2}^2 I_{3}^2 \cdots I_{d-2}^2 I_{d-1}^2.
	\end{multline*}
	Let us also record the information of the cycles originated from the top marked boundary vertices. The first $d-2$ cycles end at the last character of the second to last interval words of the bottom word, and the last cycle ends at the first character of the first interval word $I_{d-1}^1$.

	We now extend this methodology to the subsequent interval using an analogous sequence of partial weaves. For example, we have partial weaves $I_k^2 I_{d-1}^2 \rarrow I_{d-1}^2I_{k+1}^3$ for $k \in [2, d-2]$ (cf.\ Figures~\ref{fig: T- to T+ boundary case} and~\ref{fig: T- to T+ generic case}). By concatenating these partial weaves for $k = d-2, d-3, \dots, 2$, we get
	\[
	T^-  \rarrow I_{d-1}^1 I_{2}^2 I_{3}^2 \cdots I_{d-2}^2I_{d-1}^2 \rarrow  I_{d-1}^1 I_{d-1}^2 I_3^3\cdots I_{d-2}^3 I_{d-1}^{3}.
	\]

	Iteratively applying the partial weave transformations described above, we recursively construct the full Demazure weave through successive concatenation of local braid moves:
	\[
		T^-  \rarrow I_{d-1}^1 I_{2}^2 I_{3}^2 \cdots I_{d-2}^2I_{d-1}^2 \rarrow  I_{d-1}^1 I_{d-1}^2 I_3^3\cdots I_{d-2}^3 I_{d-1}^{3} \rarrow\\
		\cdots \rarrow I_{d-1}^1 I_{d-1}^2 \cdots I_{d-1}^{d-1}.
	\]
	The cycles originated from the top boundary vertices will end at the first character of each interval word for the bottom word. 

	Finally we notice that by swapping (non-adjacent) weave lines, we have partial weaves 
	\[I_{d-k}^1I_{d-k+1}^2\cdots I_{d-1}^k \rarrow I_{d-k}^{d-1} I_{d-k-1}^1I_{d-k}^2 \cdots I_{d-1}^{k+1}, \text{ for } 1\le k \le d-1.
	\]
	Concatenate these partial weave for $k = 1, 2,\dots, d-1$, we can transform $I_{d-1}^1 I_{d-1}^2 \cdots I_{d-1}^{d-1}$ into $T^+$ as follows: 
	\begin{multline*}
			T^-  \rarrow  I_{d-1}^1 I_{d-1}^2 \cdots I_{d-1}^{d-1} = I_{d-1}^{d-1} I_{d-2}^1 I_{d-1}^2 I_{d-1}^3 \cdots I_{d-1}^{d-1}\\
			\rarrow  I_{d-1}^{d-1} I_{d-2}^{d-1}I_{d-3}^1I_{d-2}^2I_{d-1}^3 I_{d-1}^4\cdots I_{d-1}^{d-1}
			 \rarrow \cdots
			\rarrow  I_{d-1}^{d-1}I_{d-2}^{d-1}\cdots I_1^{d-1} = T^+.
	\end{multline*}


	We notice that the cycles originated from the top boundary vertices will end at the last character of each interval word for the bottom word $T^+$. This completes the proof of the statement for $T = T^-$. 





	Let $T = T_1T_2\cdots T_{d-1}$ be a marked complete nested word.  If $T = T^+$ or $T= T^-$, then we are done. Otherwise let $T_{k-1}, T_{k}$ be two adjacent interval words such that one of them is increasing and the other is decreasing; without loss of generality, we assume that $T_{k-1}$ is increasing and $T_{k}$ is decreasing, i.e., $T_{k-1} = I_i^{j-1}$ and $T_{k} = I_j^i$. Let 
	\[
	T' = T_1T_2\cdots T_{k-2}T'_{k-1}T'_{k}T_{k+1}\cdots T_{d-1}
	\]
	such that $T'_{k-1} = I_j^{i+1}$ and $T'_{k} = I_i^j$. Then we have a Demazure weave 
	\[
	T = T_1T_2 \cdots T_{k-1}T_k \cdots T_{d-1} \rarrow T_1T_2\cdots T_{k-1}'T_{k}' \cdots T_{d-1} = T'
	\]
	with the part $T_{k-1}T_k \rarrow T'_{k-1}T'_k$ shown in Figure~\ref{fig: braid X-patch-bw with cycles}. Now notice that $T'$ is complete nested: $T'_{k} = I_i^j$ and $T'_{k-1}$ is an interval word for $[i+1, j]$. Also notice that the cycles originated from the top boundary vertices will end at the marked characters in $T'$.
	\begin{figure}
		\centering
		{\includegraphics[trim= 11cm 10cm 5cm 8cm, clip = true, scale = 0.4]{braid_X-patch-bw_with_cycles.pdf}}
		\caption{A (local) weave $\ww: I_i^{j-1}I_j^i \rarrow I_j^{i+1}I_i^j$. }
		\label{fig: braid X-patch-bw with cycles}
	\end{figure}
	\noindent Repeat this process (and concatenate the Demazure weaves we obtained in the process) until no such pair exists. The (final) Demazure has bottom word $\tilde{T} = \tilde{T}_1\tilde{T}_2\cdots \tilde{T}_{d-1}$ such that $\tilde{T}_i$ is decreasing for $i\le k$ and increasing for $i>k$, for some $k\in [1, d-2]$, i.e., the (final) Demazure weave is of the form
	\[
	T \rarrow   I_{d-k}^{d-k} I_{d-k+1}^{d-k}\cdots I_{d-1}^{d-k} I_{d-k-1}^{d-1}I_{d-k-2}^{d-1} \cdots I_{1}^{d-1} = \tilde{T}.
	\]
	Notice that $I_{d-k}^{d-k} I_{d-k+1}^{d-k}\cdots I_{d-1}^{d-k}$ is a $T^{-}$ in $k$ characters $(d-k, d-k+1, \dots, d-1)$, so we can make a Demazure weave from it to the $T^+ (= I_{d-1}^{d-1}I_{d-2}^{d-1}\cdots I_{d-k}^{d-1})$ in the same characters by braid moves. Combining with the rest of the interval words, we get a Demazure weave
	\begin{multline*}
	T \rarrow I_{d-k}^{d-k} I_{d-k+1}^{d-k}\cdots I_{d-1}^{d-k} I_{d-k-1}^{d-1}I_{d-k-2}^{d-1} \cdots I_{1}^{d-1} \\
	\rarrow I_{d-1}^{d-1}I_{d-2}^{d-1}\cdots I_{d-k}^{d-1} I_{d-k-1}^{d-1}I_{d-k-2}^{d-1} \cdots I_{1}^{d-1} = T^+.
	\end{multline*}
	Lastly we simply notice that the cycles will end exactly at the last character of each interval word for $T^+$. 
\end{proof}




\begin{defn}\label{defn: left/right/double push by flags}
	Let $\mcg, \mch$ be decorated flags. For $0\le i \le d-1$, define $\lpush{\mcg}{i}{\mch}$ 
to be the decorated flag 
\[
\lpush{\mcg}{i}{\mch} = \big(\mcg^1, \cdots, \mcg^i, \mcg^i \wed \mch^1, \cdots, \mcg^i \wed \mch^{d-1-i}\big).
\]
By convention we have $\lpush{\mcg}{0}{\mch} = \mch$ and $\lpush{\mcg}{d-1}{\mch} = \mcg$. 
We can  interpret $\mcg^i\wed \mch$ as follows: first we shift $\mch$ to the right by $i$ steps, then we fill in the first $i$ spots with the first $i$ components of $\mcg$, and finally wedge the rest with $\mcg^i$. 

Similarly, we define $\rpush{\mch}{\mcg}{j}$ to be the decorated flag
\[
\rpush{\mch}{\mcg}{j} = \big(\mcg^{j}\wed\mch^{d-j+1} , \cdots, \mcg^{j}\wed\mch^{d-1} , \mcg^{j}, \cdots, \mcg^{d-1}\big)
\]
when $1\le j \le d$. By convention we have $\rpush{\mch}{\mcg}{d} = \mch$ and $\rpush{\mch}{\mcg}{1} = \mcg$. 

Also we define $\lrpush{\mcg}{i}{\mch}{j}$ (with $i<j$) to be the decorated flag 
\begin{align*}
\lrpush{\mcg}{i}{\mch}{j}=&\big(\mcg^1, \cdots, \mcg^i, \mcg^{j}\wed\mcg^i \wed \mch^{d-j+1}, \cdots, \mcg^{j}\wed\mcg^i \wed \mch^{d-i-1}, \mcg^{j}, \cdots, \mcg^{d-1}\big)\\
=&\big(\mcg^1, \cdots, \mcg^i, \mcg^{i}\wed\mcg^j \wed \mch^{d-j+1}, \cdots, \mcg^{i}\wed\mcg^j \wed \mch^{d-i-1}, \mcg^{j}, \cdots, \mcg^{d-1}\big).
\end{align*}
Here we used the fact that $\mcg^{j}\wed\big(\mcg^i \wed \mch^{k}\big) = \mcg^i \wed \big(\mcg^{j} \wed \mch^{k}\big)$ by Proposition~\ref{prop: wedge of any two within a flag is zero}. By convention we have $\lrpush{\mcg}{0}{\mch}{j} = \rpush{\mch}{\mcg}{j}$ and $\lrpush{\mcg}{i}{\mch}{d} = \lpush{\mcg}{i}{\mch}$. 

