Recall from Lemma~\ref{lemma: decoration for interval word}, a decoration for an interval word is uniquely determined by the first and last decorated flags. And  recall from Definition~\ref{defn: decoration of marked word} that a normalized decoration for a marked word is a decoration such that the non-marked crossing values are equal to $1$.

\begin{lemma}\label{lemma: decoration for complete nested word is unique}
	Let $\mcg, \mch$ be two decorated flags and $T = T_1T_2\cdots T_{d-1}$ be a marked complete nested word. Then the word $T$ has a unique normalized decoration $\dec_{T}(\mcg, \mch)$ from $\mcg$ to $\mch$. This decoration is determined as follows. 
	Let $i, j \in [1, d-1]$ such that $T_k$ is an interval word for $[i, j]$; and let $\mck_{k+1} = \lrpush{\mcg}{i-1}{\mch}{j+1}$, for $k\in [1, d-1]$. 
	Then $\dec_T(\mcg, \mch) = (\mck_1, \mck_2, \cdots, \mck_d)$, denoted by
	\[
	\mcg = \mck_1 \rel{T_1} \mck_2 \rel{T_2} \cdots \rel{T_{k-1}} \mck_{k} \rel{T_k} \mck_{k+1} \rel{T_{k+1}} \cdots \rel{T_{d-1}} \mck_{d} = \mch.
	\]
\end{lemma}

\begin{proof}
	The proof is by induction on $k$. For $k = d-1$, we have $\mck_d = \mch$; recall from the definition of a complete nested word (cf.\ Definition~\ref{defn: nested words and complete nested words}), $T_{d-1}$ is an interval word for $[1, d-1]$, and we have $\lrpush{\mcg}{0}{\mch}{d} = \mch = \mck_d$. 

	Now assume that $T_k$ is an interval word for $[i,j]$ and $\mck_{k+1} = \lrpush{\mcg}{i-1}{\mch}{j+1}$. Without loss of generality, we assume that $T_k = I_i^j$. Then $T_{k-1}$ is an interval word for $[i+1, j]$,  let us show that $\mck_{k} = \lrpush{\mcg}{i}{\mch}{j+1}$. 

	We have $\mck_k \rel{T_k} \mck_{k+1}$. Recall that $T_k = I_i^j$ is marked only for the last character, namely $j$, so for any $r\in [i, j-1]$, the crossing value at $r$ is equal to $1$, i.e., 
	\[
	\frac{\qwed{\mck_k^r}{\mck_{k+1}^r}{\mck_{k+1}^{r-1}}}{\mck_k^{r+1}} = 1, \quad r\in [i, j-1];
	\]
	equivalently
	\[
	\mck_k^{r+1} = \qwed{\mck_k^r}{\mck_{k+1}^r}{\mck_{k+1}^{r-1}}, \quad r\in [i,j-1].
	\]
	Notice that for $t \le i$ or $t\ge j+1$, we have $\mck^t_k = \mck^t_{k-1}= \dots = \mck_1^t= \mcg^t$. Now let us prove $\mck^t_{k} = \mcg^i \mixwed\mcg^{j+1} \mixwed\mch^{d+t-i-j-1}$ for $t \in [i+1, j]$ by an induction on $t$. When $t = i+1$, notice that $\mck_{k+1}^{i-1} = \mcg^{i-1}$ and $\mck_{k+1}^{i} = \mcg^{i-1}\mixwed \mcg^{j+1}\mixwed\mch^{d-j}$, then we have
	\begin{align*}
		\mck_k^{i+1} &= \qwed{\mck_k^i}{\mck_{k+1}^i}{\mck_{k+1}^{i-1}} \\
		&=\qwed{\mcg^i}{\big(\mcg^{i-1}\mixwed \mcg^{j+1}\mixwed\mch^{d-j}\big)}{\mcg^{i-1}}\\
		&= \mcg^{i}\mixwed \mcg^{j+1}\mixwed\mch^{d-j},
	\end{align*}
	where the last equality follows from Lemma~\ref{lemma: cancellation law for quotient wedge}. Now assume that $\mck^t_{k} = \mcg^i \mixwed\mcg^{j+1} \mixwed\mch^{d+t-i-j-1}$. Notice that $\mck_{k+1}^{t-1} = \mcg^{i-1}\mixwed \mcg^{j+1}\mixwed\mch^{d+t-i-j-1} $ and $\mck_{k+1}^t = \mcg^{i-1}\mixwed \mcg^{j+1}\mixwed\mch^{d+t-i-j}$, then
	\begin{align*}
	\mck_k^{t+1} &= \qwed{\mck_k^t}{\mck_{k+1}^t}{\mck_{k+1}^{t-1}} \\
	&=\qwed{\big(\mcg^i \mixwed\mcg^{j+1} \mixwed\mch^{d+t-i-j-1}\big)}{\big(\mcg^{i-1}\mixwed \mcg^{j+1}\mixwed\mch^{d+t-i-j}\big)}{\mcg^{i-1}\mixwed \mcg^{j+1}\mixwed\mch^{d+t-i-j-1}}\\
	&= \mcg^i \mixwed\mcg^{j+1} \mixwed\mch^{d+t-i-j}
	\end{align*}
	where the last equality follows from Lemma~\ref{lemma: cancellation law for quotient wedge, version2}. This completes the proof that $\mck_{k} = \lrpush{\mcg}{i}{\mch}{j+1}$.
\end{proof}









\begin{lemma}\label{lemma: changing from T to T^+ does not affact the seed}
	Let $\mcg, \mch$ be two decorated flags and $T = T_1T_2\cdots T_{d-1}$ be a marked complete nested word. Let $\ww: T \rarrow T^+ := I_{d-1}^{d-1}I_{d-2}^{d-1}\cdots I_1^{d-1}$ be a decorated Demazure weave with the top word $T$ decorated by $\dec_T(\mcg, \mch)$. Then the cycles of $\ww$ can be described as follows. For $k\in [1, d-1]$, let $T_k$ be the $k$-th interval word for $T$. 
	\begin{itemize}[wide, labelwidth=!, labelindent=0pt]
		\item If $T_k = I_i^j$, then the cycle $\gamma_k$ start at the last character of $T_k$, of color $j$, and end at the last character of $I_i^{d-1}$, of color $d-1$; furthermore,  $\Delta_{\gamma_k} = \mcg^i \wedge \mch^{d-i}$.
		\item If $T_k = I_j^i$, then the cycle $\gamma_k$ start at the last character of $T_k$, of color  $i$, and end at the last character of $I_j^{d-1}$, of color $d-1$; furthermore,  $\Delta_{\gamma_k} = \mcg^j \wedge \mch^{d-j}$. 
	\end{itemize}
	 Consequently, the decoration for the bottom word $T^+$ is the normalized decoration $\dec_{T^+}(\mcg, \mch)$.
\end{lemma}
\begin{proof}
	By Lemma~\ref{lemma: mutation equivalent weave same bottom flags} and Theorem~\ref{thm: mutation equivalence demazure weaves yield mutation equivalent seeds}, we only need to prove the lemma for a specific Demazure weave.  The statement involving where cycles end follows from Lemma~\ref{lemma: complete nested words are all related by braid moves} and its proof (where a specific Demazure weave is described). The frozen variables associated with the cycles can be calculated using the decoration for the top word. We will show the case when $T_k = I_i^j$; the other case follows in a similar way.  Let $\dec_T(\mcg, \mch) = (\mck_1, \mck_2, \cdots, \mck_d)$. Then
	\begin{align*}
	\Delta_{\gamma_k} &= \frac{\qwed{\mck_k^j}{\mck_{k+1}^j}{\mck_{k+1}^{j-1}}}{\mck_{k}^{j+1}}=  \frac{\qwed{\big(\mcg^i\mixwed \mcg^{j+1}\mixwed \mch^{d-i-1}\big)}{\big(\mcg^{i-1}\mixwed \mcg^{j+1}\mixwed \mch^{d-i}\big)}{\mcg^{i-1}\mixwed\mcg^{j+1}\mixwed \mch^{d-i-1}}}{\mcg^{j+1}}\\
	&= \frac{{\mcg^{i}\mixwed \mcg^{j+1}\mixwed \mch^{d-i}}}{\mcg^{j+1}}= \frac{{\mcg^{j+1}\mixwed \mcg^{i}\mixwed \mch^{d-i}}}{\mcg^{j+1}} = \mcg^i \wedge \mch^{d-i}.
	\end{align*}
	Here the third equality follows from Lemma~\ref{lemma: cancellation law for quotient wedge, version2} and the fourth equality follows from Proposition~\ref{prop: wedge of any two within a flag is zero}. 

	Finally, the statement that the decoration for the bottom word is normalized follows from the description for the cycles. A bottom edge has a cycle passing through it if and only if the edge corresponds to the last character of an interval word for $T^+$; hence other than the last character of an interval word for $T^+$, the crossing values are equal to $1$, i.e., the decoration is normalized. 
\end{proof}


\begin{lemma} \label{lemma: w0 rho to w0 equals rho w0 w0}
	Let $\mcg, \mch, \mck$ be decorated flags such that $\mch = \lpush{\mch}{1}{\mck}$. Recall that $\rho = 12\cdots\overline{d-1}$. We have the following statements. 
