The following lemma is needed for Lemma~\ref{lemma: the cluster algebra does not depend on the choice of the cut}, and will be proved in Section~\ref{sec: initial weave}.

\begin{lemma}\label{lemma: bottom cycle description of ww(p, q) and bottom decoration is normalized}
	Let $(p, q)$ be a valid cut of $\sigma$ (cf.\ Definition~\ref{defn: valid cut in general}). Let $\ww(p, q): \beta(p, q) \rarrow T^+$ be a Demazure weave as in Definition~\ref{defn: cutting along the disk to get two weaves}. Then a bottom edge has a cycle passing through it if and only if the edge corresponds to the last character of an interval word for $T^+$. These frozen cycles correspond to the frozen variables 
	\[
	\zz_0 = \{\mcf_p^1\wedge \mcf_q^{d-1}, \mcf_p^2\wedge \mcf_q^{d-2}, \dots, \mcf_p^{d-1}\wedge \mcf_q^1\}
	\]
	in $\seed(\ww(p, q))$. Consequently, the decoration for the bottom word is the normalized decoration $\dec_{T^+}(\mcf_p, \mcf_q)$.
\end{lemma}



\begin{lemma}\label{lemma: the cluster algebra does not depend on the choice of the cut}
	Assume that both $(p, q)$ and $(p, q+1)$ are valid cuts of $\sigma$. Then $\seed(p, q)$ and $\seed(p, q+1)$ are mutation equivalent. Therefore $\mca(p, q) = \mca(p, q+1)$.
\end{lemma}



\begin{proof}
	Without loss of generality, we assume that $\sigma(q) = 1$. Let $\mcg = \mcf_p, \mch = \mcf_q, \mck = \mcf_{q+1}$. Then we have $\mch = \lpush{\mch}{1}{\mck}$, cf.\ Proposition~\ref{prop: recursive relation between flags associated with a signature}. Let $\ww(p, q, q+1)$ (resp., $\ww(q, q+1, p+n)$ be a decorated Demazure $\ww: T^+\rho \rarrow T^+$ (resp., $\ww': \rho \rev{T^+} \rarrow \rev{T^+}$) as in Lemma~\ref{lemma: w0 rho to w0 equals rho w0 w0}. 

	We claim that $\seed(\ww(p, q+1))$ is mutation equivalent to the amalgamation of $\seed(\ww(p, q))$ and $\seed(p, q, q+1)$ along the frozen variables 
	\[
	\zz_0 = \{\mcf_p^1\wedge \mcf_q^{d-1}, \mcf_p^2\wedge \mcf_q^{d-2}, \dots, \mcf_p^{d-1}\wedge \mcf_q^1\}, 
	\]
	i.e., we have 
\begin{equation}\label{equation: (p, q+1) = (p,q) + (p,q, q+1)}
	\seed(\ww(p, q+1)) \sim \glueseeds{\seed(\ww(p, q))}{\seed(p, q, q+1)}{\zz_0}.
\end{equation}
	Here $\seed(\ww(p, q))$ (resp. $\seed(\ww(p, q+1))$) is the seed associated with the Demazure weave $\ww(p,q): \beta(p, q) \rarrow T^+$ (resp. $\ww(p, q+1) : \beta(p, q+1) \rarrow T^+$) as in Definition~\ref{defn: cutting along the disk to get two weaves}; and $\seed(p, q, q+1)$ is the seed associated with $\ww(p, q, q+1)$. 

	\begin{proof}[Proof of the claim]
		Consider the decorated Demazure weave $\ww: \beta(p, q+1) \rarrow T^+$ constructed as follows. First notice that $\beta(p, q+1) = \beta(p, q) \rho$, we make a Demazure weave $\ww^*: \beta(p, q) \rho \rarrow T^+ \rho$, which is $\ww(p, q)$ accompanying with $d-1$ vertical strands representing $\rho$, see the top portion of Figure~\ref{fig: glue m(p, q) with m(p, q, q+1)}. Then we concatenate the bottom of the weave $\ww^*$ with the top of $\ww(p, q, q+1): T^+ \rho \rarrow T^+$. We have a valid concatenation: by Lemma~\ref{lemma: bottom cycle description of ww(p, q) and bottom decoration is normalized}, the decoration for the bottom word of the weave $\ww^*$ matches with the decoration for the top word of the weave $\ww(p, q, q+1)$; furthermore, the cycles ending at the bottom boundary of the weave $\ww^*$ concatenate exactly at the marked boundary vertices for the weave $\ww(p, q, q+1)$.
	\begin{figure}
	\centering
	\includegraphics[trim= 0.5cm 3.2cm 7cm 4.2cm, clip = true, scale = 0.33]{glue_m_p_q_with_m_p_q_q+1.pdf}
	\caption{Concatenating $\ww(p, q)$ with $\ww(p, q, q+1)$.}
	\label{fig: glue m(p, q) with m(p, q, q+1)} 
\end{figure}

		Now notice that by construction, the seed associated with $\ww$ is the amalgamation of $\seed(\ww(p, q))$ and $\seed(p, q, q+1)$ along the frozen variables $
		\zz_0$:
		\[
		\seed(\ww) = \glueseeds{\seed(\ww(p, q))}{\seed(p, q, q+1)}{\zz_0}.
		\](the amalgamation conditions are satisfied by Lemma~\ref{lemma: amalgamation condition is satisfied}).
		Finally we notice that $\ww$ is a Demazure weave $\beta(p, q+1) \rarrow T^+$, we have that $\seed(\ww)\sim \seed(\ww(p, q+1))$ by Theorem~\ref{thm: mutation equivalence demazure weaves yield mutation equivalent seeds}. Hence we have 
		\[
		\seed(\ww(p, q+1)) \sim \seed(\ww) = \glueseeds{\seed(\ww(p, q))}{\seed(p, q, q+1)}{\zz_0}.
		\]
		This completes the proof of the claim. \qedhere 
\end{proof}

	Similarly we can show that 
\begin{equation}\label{equation: (q, p+n) = (q, q+1, p+n) + (q+1, p+n)}
	\seed(\ww(q, p+n)) \sim \glueseeds{\seed(\ww(q+1, p+n))}{\seed(q, q+1, p+n)}{\zz'_0},
\end{equation}
	where
	\[
	\zz'_0 = \{\mcf_p^1\wedge \mcf_{q+1}^{d-1}, \mcf_p^2\wedge \mcf_{q+1}^{d-2}, \dots, \mcf_p^{d-1}\wedge \mcf_{q+1}^1\}.
	\]


	Now by Definition~\ref{defn: cluster algebra cutting at p, q}, $\seed(p, q)$ is the seed obtained by amalgamating $\seed(\ww(p, q))$ and $\seed(\ww(q, p+n))$ along the frozen variables $\zz_0$, i.e., 
	\[
	\seed(p, q) = \glueseeds{\seed(\ww(p, q))}{\seed(\ww(q, p+n))}{\zz_0}.
	\]
	Then by Remark~\ref{remk: properties of amalgamation}, we have
	\begin{align*}
		\seed(p, q) =& \glueseeds{\seed(\ww(p, q))}{\seed(\ww(q, p+n))}{\zz_0}\\
		{\sim} &\glueseeds{\seed(\ww(p, q))}{\big(\glueseeds{\seed(\ww(q+1, p+n))}{\seed(q, q+1, p+n)}{\zz'_0}\big)}{\zz_0} \text{ by  } (\ref{equation: (q, p+n) = (q, q+1, p+n) + (q+1, p+n)})\\
		 =&\glueseeds{\big(\glueseeds{\seed(\ww(p, q))}{\seed(q, q+1, p+n)}{\zz_0}\big)}{\seed(\ww(q+1, p+n))}{\zz'_0}\\
		 {=}&\glueseeds{\big(\glueseeds{\seed(\ww(p, q))}{\seed(p, q, q+1)}{\zz_0}\big)}{\seed(\ww(q+1, p+n))}{\zz'_0}\text{ by Lemma } \ref{lemma: w0 rho to w0 equals rho w0 w0}\\
		{\sim}&\glueseeds{\seed(\ww(p, q+1))}{\seed(\ww(q+1, p+n))}{\zz'_0} \text{ by } (\ref{equation: (p, q+1) = (p,q) + (p,q, q+1)})\\
	= 	&\seed(p, q+1). \qedhere
	\end{align*}
\end{proof}
	\begin{figure}
		\centering
		\includegraphics[trim= 5cm 6cm 7cm 3.5cm, clip = true, scale = 0.23]{p_q_q+1_equivalent.pdf}
		\caption{Amalgamating three decorated Demazure weaves in two different ways. They result in the same seeds.}
		\label{fig: Amalgamating three decorated Demazure weaves in two different ways, result in the same seeds}
	\end{figure}

Now Proposition~\ref{prop: cluster algebra does not depend on the cut} follows by repeatedly applying Lemma~\ref{lemma: the cluster algebra does not depend on the choice of the cut}.

\begin{proof}[Proof of Proposition~\ref{prop: cluster algebra does not depend on the cut}]
	We first show that 
	\[
	\mca(p, q) = \mca(p+1, q+1),
	\]
	where $1\le p \le q \le n$ and $||p-q||\ge d+1$. Since $n\ge 2(d+1) + 1$, we may assume that $\|q+1 - p\| \ge d+1$ (or else $\|p+1 - q\| \ge d+1$), then $\mca(p, q) = \mca(p, q+1)$ by Lemma~\ref{lemma: the cluster algebra does not depend on the choice of the cut}. Similarly, as $\|p+1 - (q+1)\| = \|p - q\| \ge d+1$,  we get $\mca(p, q+1) = \mca(p+1, q+1)$ by Lemma~\ref{lemma: the cluster algebra does not depend on the choice of the cut} again. Hence $\mca(p, q) = \mca(p+1, q+1)$. 

	We then show that 
	\[
	\mca(p, q) = \mca(p, q'),
	\]
	where $1\le p \le q \le q' \le n$, $\|p-q\| \ge d+1$ and $\|p - q'\| \ge d+1$. Notice that for any $r \in [q, q']$, we have $\|p-r\| \ge d+1$, hence by Lemma~\ref{lemma: the cluster algebra does not depend on the choice of the cut}, we have $\mca(p, q) = \mca(p, q+1) = \cdots = \mca(p, q')$. 

	Finally, notice that $\mca(p, q) = \mca(p+1, q+1)$ and $\mca(p, q) = \mca(p, q')$ implies that $\mca(p, q)$ does not depend on the choice of the cut $(p, q)$. 
\end{proof}




\subsection{An initial weave for $\mca_\sigma$}\label{sec: initial weave}
In this section, we will construct and study an \emph{initial weave} for the cluster algebra ~$\mca_\sigma$. %We start with the construction of the weave. 
We begin by defining local components of weaves called \emph{patches}, which will serve as modular units for larger constructions.


\begin{defn}\label{defn: patches}
	Let $1\le i \le j \le d-1$. A \emph{patch} is a particular kind of a partial weave of the form $\cdots TT' \cdots \rarrow \cdots \tilde{T}T \cdots$ where $T$ and $T'$ are two interval words for the same interval. Specifically:
	\begin{itemize}[wide, labelwidth=!, labelindent=0pt]
		\item An \emph{$X$-patch} is a  partial weave, either of the form $\cdots I_i^jI_j^i \cdots  \rarrow \cdots I_{j}^{i+1} I_{i}^j \cdots$ or of the form $\cdots I_j^i I_i^j \cdots \rarrow \cdots I_{i}^{j-1} I_{j}^i\cdots$, as shown in Figure~ \ref{fig: X patch small}.	
		\item An \emph{$H$-patch} is a  partial weave, either of the form $\cdots I_i^jI_i^j \cdots  \rarrow \cdots I_{i+1}^j I_{i}^j \cdots$ or of the form $\cdots I_j^i I_j^i \cdots \rarrow \cdots I_{j-1}^i I_{j}^i\cdots$, as shown in Figure~\ref{fig: H patch and Y patch small} (left) and Figure~\ref{fig: H patch and Y patch small dual} (left).
		\item A \emph{$Y$-patch} is a partial weave, either of the form $\cdots I_i^jI_j^i \cdots  \rarrow \cdots I_{i}^{j-1} I_{j}^i \cdots$ or of the form $\cdots I_j^i I_i^j \cdots \rarrow \cdots I_{j}^{i-1} I_{i}^j\cdots$, as shown in Figure~\ref{fig: H patch and Y patch small} (right) and Figure~\ref{fig: H patch and Y patch small dual} (right).
	\end{itemize}
	We say that a patch is of type $X$ (resp., $H$, $Y$) if it is an $X$-patch (resp., $H$-patch, $Y$-patch). %We say apply an $X$-patch (resp., $H$-patch, $Y$-patch) to two interval words $TT'$, we mean to create a patch $\cdots TT' \cdots \rarrow \cdots \tilde{T}T \cdots$ of the corresponding type. 
\end{defn}	


