\begin{defn}\label{defn: weakly nested words}
	Let $m \ge d-1$. A word $T$ is called \emph{weakly nested (of rank $m$) at $s$} for some $s\in [1, m]$ if it has the form
	\[
	T = T_1T_2\cdots T_sT_{s+1}\cdots T_{m},
	\]
	where $T_1, \dots, T_m$ are interval words such that
	\begin{itemize}[wide, labelwidth=!, labelindent=0pt]
		\item $T_{1}, T_2, \dots, T_s$ are  interval words for the same interval;
		\item $T_{s}T_{s+1}\cdots T_{m}$ is a nested word (cf. Definition~\ref{defn: nested words and complete nested words}).
	\end{itemize}
	We note that the nested word $T_{s}T_{s+1}\cdots T_{m}$ is not necessarily complete (cf.\ Definition~\ref{defn: nested words and complete nested words}). 
\end{defn}


	\begin{defn}[\textbf{Construction of $\str{\beta}$}]   \label{defn: strips}
		Let $\beta = T_1T_2\cdots T_sT_{s+1}\cdots T_{m}$ be a weakly nested word at $s$.
		We denote by $\str{\beta}$ a partial weave, with $\beta$ as the top word, that constructed by concatenating patches as follows.


		Without loss of generality, we assume that $T_1 = I_i^j$ with $1\le i < j\le d-1$. 

		If $T_1\neq T_2$ and $T_2 = T_3$, then we apply a $Y$-patch to $T_1T_2$:
		\[
		T_1T_2\cdots T_sT_{s+1}\cdots T_{m} \rarrow T'_1T_2T_3\cdots T_sT_{s+1}\cdots T_m,
		\]
		where $T'_1 = I_{i}^{j-1}$. We then apply an $H$-patch (resp., $X$-patch) to $T_2T_3$, provided $T_2 = T_3$ (resp., $T_2 \neq T_3$):
		\[
		T'_1T_2T_3T_4\cdots T_sT_{s+1}\cdots T_m \rarrow T'_1 T'_3 T_2 T_4\cdots T_sT_{s+1}\cdots T_m,
		\]
		with $T'_3 = I_{j-1}^i$ (resp., $T'_3 = I_{i}^{j-1}$). Recursively applying patches to $T_2T_k$, $3\le k \le s$, we end up getting a Demazure weave
		\[
		\str{\beta}: \beta = T_1T_2\cdots T_sT_{s+1}\cdots T_{m} \rarrow \cdots \rarrow \beta' = T'_1T'_3\cdots T'_s T_2 T_{s+1}T_{s+2}\cdots T_m.
		\]
		Notice that the bottom word for $\str{\beta}$, $\beta' = T'_1T'_3\cdots T'_s T_2 T_{s+1}T_{s+2}\cdots T_m$, is weakly nested at $s-1$: the first $s-1$ interval words are on the same interval, and the rest $T'_s T_2 T_{s+1}T_{s+2}\cdots T_m$ forms a nested word. 


		Otherwise we apply a $H$-patch (resp., $X$-patch) to $T_1T_2$ if $T_1 = T_2$ (resp., $T_1 \neq T_2$):
		\[
		T_1T_2\cdots T_sT_{s+1}\cdots T_{m} \rarrow T'_2T_1T_3\cdots T_sT_{s+1}\cdots T_m,
		\]
		where $T'_2 = I_{i-1}^{j}$ (resp., $T'_2 = I_j^{i-1}$). Recursively applying patches to $T_1T_k$, $2\le k \le s$, we end up getting a Demazure weave
		\[
		\str{\beta}: \beta = T_1T_2\cdots T_sT_{s+1}\cdots T_{m} \rarrow \cdots \rarrow \beta' = T'_2T'_3\cdots T'_s T_1 T_{s+1}T_{s+2}\cdots T_m.
		\]
		Similarly the bottom word for $\str{\beta}$, $\beta' = T'_2T'_3\cdots T'_s T_1 T_{s+1}T_{s+2}\cdots T_m$, is weakly nested at $s-1$: the first $s-1$ interval words are all on the same interval, and $T'_s T_1 T_{s+1}T_{s+2}\cdots T_m$ forms a nested word. 

		The \emph{type} of $\str{\beta}$ is defined to be the type of the first patch we used in the construction of the strip. 

		If $i = j$, then $T_1 = T_2 = \cdots = T_s = i$, and $\str\beta$ is formed by merging these weave lines (all of color $i$) from left to right. The bottom word is a complete nested word $iT_{s+1}\cdots T_m$. In this case, we say $\str \beta$ is of \emph{degenerate type}.
	\end{defn}


	\begin{remk}\label{remk: nested part unchanged}
		The \emph{nested part} $T_{s+1}\cdots T_m$ of $\beta$ remains unchanged during the transformation process from $\beta$ to $\beta'$.
	\end{remk}
	Following the convention in Definition~\ref{defn: cutting along the disk to get two weaves}, we next construct two specific Demazure weaves $\ww_1 = \ww(p, q)$ and $\ww_2 = \ww(q, p+n)$, called \emph{the initial weaves}, as a concatenation of strips. 

\begin{defn}[\textbf{Construction of the initial weaves}]\label{defn: construction of the initial weaves as concatenations of strips}
	Let $m_1 = q-p$ and $m_2 = p+n-q$. For $i = 1, 2$, the Demazure weave $\ww_i$ is constructed by the following recursive procedure, with $\beta_i$ as the input.

	\begin{itemize}[wide, labelwidth = 0pt, labelindent=0pt]
		\item[\textbf{Step 0:}] Set $\beta = \beta_i$. Set $\ww_i: \beta \rarrow \beta$ to be the trivial Demazure weave. 

		\item[\textbf{Step 1:}] If $\beta$ is a complete nested word, output $\ww_i$ and end the algorithm. Otherwise, let $\str{\beta}: \beta \rarrow \beta'$ be the strip defined in Definition~\ref{defn: strips}; notice that this can be done since $\beta$ is weakly nested of rank $m_i$ at $s$ for some $s\in [1, m_i]$.

		\item[\textbf{Step 2:}] Concatenate the bottom of $\ww_i$ with the top of $\str{\beta}$. Assign the new Demazure weave to $\ww_i$. Set $\beta := \beta'$. Return to Step 1.
	\end{itemize}

	Notice that Steps 1 \& 2 of the algorithm above will run exactly $d-1$ times. To be precise, Step 1 will be executed $d$ times, while during the last time, we simply output the weave and end the algorithm.
\end{defn}



\begin{example}
	Consider the weave $\ww_1$ in Figure~ \ref{fig: example of beta1} of Example~\ref{example: describing a seed from a decorated weave}. It's obtained by a concatenation of two strips. The portion between any two consecutive dashed lines is a single patch. The concatenation of the first three patches forms the first strip. The concatenation of the fourth and fifth patches forms the second strip.
\end{example}


We next describe the cycles and the decorations for the initial weaves $\ww_1$ and $\ww_2$. For this purpose, we focus on $\ww_1$; the result for $\ww_2$ is obtained in a similar way. Let us fix some notations. 

Recall from Definition~\ref{defn: cutting along the disk to get two weaves} that $\beta_1 = \beta(p, q) = \prod_{j = p}^{q-1} \rho_j$, where $\rho_j$ is either $\rho$ or $\rho^*$ depending on the signature $\sigma(j)$, is the top word for $\ww_1$. By Theorem~\ref{thm: bijection between configuration spaces of signature and decorated flag moduli spaces} and Remark~\ref{remk: restriction of decorations to a subword}, the normalized cyclic decoration $\dec_{\beta_\sigma} = \big(\mcf_1, \mcf_2, \dots, \mcf_n, \mcf_{n+1}=\mcf_1\big)$ for $\beta_\sigma$ restricts to a normalized decoration $\dec_{\beta_1} = \big(\mcf_p, \mcf_{p+1}, \dots, \mcf_{q}\big)$ for $\beta_1$:
\[
\mcf_p \rel{\rho_p} \mcf_{p+1}\rel{\rho_{p+1}} \dots \rel{\rho_{q-1}} \mcf_q.
\]
Let $(\ww_1, \dec)$ be the decorated Demazure weave with $\dec_{\beta_1}$ as the top decoration, cf.\ Definition~\ref{defn: decorated demazure weave} and Theorem~\ref{thm: unique extension of decorations for a weave}. We will simply refer to $(\ww_1, \dec)$ as $\ww_1$, since $\dec$ is fixed throughout this section. 

Now recall that $\ww_1$ is constructed via concatenations of strips, cf.\ Definition~\ref{defn: construction of the initial weaves as concatenations of strips}. There will be $d-1$ strips in total; let us label them so that the $r$-th strip is labeled as $\str{r}: \beta(r-1) \rarrow \beta(r)$, for $r\in [1, d-1]$. Hence $\beta(0)$ is the top word $\beta(p, q)$ and $\beta(d-1)$ is the bottom word for $\ww_1$. Notice that $\beta(d-1)$ is a complete nested word; in particular, it is braid equivalent to the longest word $w_0\in S_d$.

\begin{proof}[Proof of Lemma~\ref{lemma: bottom word is w0}]
	By the discussion above, the bottom word for a specific Demazure weave $\ww_1$ is a complete nested word; hence it is braid equivalent to $w_0$. As different choices of a reduced bottom word for a Demazure weave are  braid equivalent, we conclude that $\beta_1'$ is braid equivalent to $w_0$. Similarly $\beta_2'$ is braid equivalent to $w_0$. 
\end{proof}


