Once we have the local pictures of quivers around the cycles $\gamma(r, i)$ appearing in Proposition~\ref{prop: description of local pictures, i not 1}, we can write down the exchange relations for these cycles. Then using the exchange relations, we can calculate the once-mutated cluster variables. 

\begin{prop}\label{prop: exchange relations, generic case}
	Let $r\in [1, d-1]$ and $i\in [2, m_1-r-1]$. Then 
	\[
	\Delta_{\gamma(r, i)} = \mcf_p^k\wedge \mcf_{t}^{d-k}
	\]
	where $t = p+r+i$ and $k\in [1, d-1]$ (cf.\ Proposition~\ref{prop: decoration flags of the initial weave}). Without loss of generality, we assume that $\str r$ is of $BW$-type $B$. %Then the exchange relation for $\gamma(r, i)$ is one of the following forms.
	\begin{enumerate}[wide, labelwidth=!, labelindent=0pt]
		\item[(HX)] Suppose that $\sigma(t-1) = -\sigma(t) =1$. Then the exchange relation for $\gamma(r, i)$ is
		\begin{equation}\label{equation: degree 4 exchange relations HX}
		\Delta_{\gamma(r, i)}\Delta'_{\gamma(r, i)} = \big(\mcf_p^k\wedge \mcf_{t-1}^{d-k}\big)\big(\mcf_p^{k-1}\wedge \mcf_{t+1}^{d-(k-1)}\big) + \big(\mcf_p^k\wedge \mcf_{t+1}^{d-k}\big)\big(\mcf_p^{k-1}\wedge \mcf_{t-1}^{d-(k-1)}\big),
		\end{equation}
		where $\Delta'_{\gamma(r, i)}=
			\mcf_p^{k-1}\mixwed \mcf_{t-1}^{1}\mixwed \mcf_{t+1}^{d-k}.$
		\item[(XH)] Suppose that $\sigma(t-1) = -\sigma(t) =-1$. Then the exchange relation for $\gamma(r, i)$ is
		\begin{equation}\label{equation: degree 4 exchange relations XH}
			\Delta_{\gamma(r, i)}\Delta'_{\gamma(r, i)} = \big(\mcf_p^k\wedge \mcf_{t-1}^{d-k}\big)\big(\mcf_p^{k+1}\wedge \mcf_{t+1}^{d-(k+1)}\big) + \big(\mcf_p^k\wedge \mcf_{t+1}^{d-k}\big)\big(\mcf_p^{k+1}\wedge \mcf_{t-1}^{d-(k+1)}\big),
		\end{equation}
		where $\Delta'_{\gamma(r, i)}=
			\mcf_p^{k+1}\mixwed \mcf_{t-1}^{d-1}\mixwed \mcf_{t+1}^{d-k}.$
	\item[(XX)] Suppose that $\sigma(t-1) = \sigma(t) =-1$ ($XX$). %If $\str r$ is of type $H$ or $i\ge 3$.  
	Then the exchange relation for $\gamma(r, i)$ is 
	\begin{multline}\label{equation: degree 6 exchange relations XX}
		\Delta_{\gamma(r, i)}\Delta'_{\gamma(r, i)} = \big(\mcf_p^{k}\wedge \mcf_{t-1}^{d-k}\big)\big(\mcf_p^{k+1}\wedge \mcf_t^{d-(k+1)}\big) \big(\mcf_p^{k-1}\wedge \mcf_{t+1}^{d-(k-1)}\big) \\
		+\big(\mcf_p^{k}\wedge \mcf_{t+1}^{d-k}\big)\big(\mcf_p^{k+1}\wedge \mcf_{t-1}^{d-(k+1)}\big) \big(\mcf_p^{k-1}\wedge \mcf_{t}^{d-(k-1)}\big),
	\end{multline}
	where $\Delta'_{\gamma(r, i)} =
	\mcf_p^{k+1} \mixwed \mcf_{t-1}^{d-k} \mixwed \mcf_{t+1}^{d-k} \mixwed\mcf_p^{k-1}$.
	\item[(HH)] Suppose that $\sigma(t-1) = \sigma(t)=1$. If $\str r$ is of type $H$ or $i\ge 3$, then the exchange relation for $\gamma(r, i)$ is 
	\begin{multline}\label{equation: degree 6 exchange relations HH}
		\Delta_{\gamma(r, i)}\Delta'_{\gamma(r, i)} = \big(\mcf_p^{k}\wedge \mcf_{t-1}^{d-k}\big)\big(\mcf_p^{k-1}\wedge \mcf_t^{d-(k-1)}\big) \big(\mcf_p^{k+1}\wedge \mcf_{t+1}^{d-(k+1)}\big) \\
		+\big(\mcf_p^{k}\wedge \mcf_{t+1}^{d-k}\big)\big(\mcf_p^{k-1}\wedge \mcf_{t-1}^{d-(k-1)}\big) \big(\mcf_p^{k+1}\wedge \mcf_{t}^{d-(k+1)}\big),
	\end{multline}
	where $\Delta'_{\gamma(r, i)} =
	\mcf_p^{k-1} \mixwed \mcf_{t-1}^{d-k} \mixwed \mcf_{t+1}^{d-k} \mixwed\mcf_p^{k+1}$.
	\item[(XHH)] Suppose that $i = 2$, $\sigma(t-1) = \sigma(t)$ and $\str r$ is of type $X$.  Then $k = x$ and the exchange relation for $\gamma(r, i)$ is 
		\begin{multline}\label{equation: degree 6 exchange relations, second cycle XB}
			\Delta_{\gamma(r, 2)}\Delta'_{\gamma(r, 2)} = \big(\mcw{p}{d-(y+1)}\wedge \mcf_{t-1}^{y+1}\big)\big(\mcf_p^{x-1}\wedge \mcf_t^{d-(x-1)}\big) \big(\mcf_p^{x+1}\wedge \mcf_{t+1}^{d-(x+1)}\big) \\
			+\big(\mcf_p^{x}\wedge \mcf_{t+1}^{d-x}\big)\big(\mcf_p^{x-1}\wedge \mcf_{t-1}^{d-(x-1)}\big) \big(\mcw{p}{d-(y+1)}\wedge \mcf_t^{y+1}\big),
		\end{multline}
		where 
		\begin{align}
		\Delta'_{\gamma(r, 2)} &=
		\frac{\mcf_p^{x-1} \mixwed \mcf_{t-1}^{d-x} \mixwed  \mcf_{t+1}^{d-x}\mixwed \mcf_p^{x+1}}{\mcb{p}{x}\wedge \mcf_{t-1}^{d-x}}
		\\ 
		&= 
		\begin{cases}
			\mcw{p}{d-(y+1)}\mixwed \mcf_{t-1}^y \mixwed  \mcf_{t+1}^{d-x}\mixwed\mcf_p^{x+1} &  \text{if } \, \mcb{p}{x-1} \neq \mcf_p^{x-1};\\
			\mcw{p}{d-(y+1)}\mixwed \mcf_{t-1}^{y+2} \mixwed\mcf_{t+1}^{d-x} \mixwed \mcb{p}{x-1} &  \text{if } \, \mcb{p}{x-1} = \mcf_p^{x-1}.\\
		\end{cases}
		\end{align}
		\item[(YHH)] Suppose that $i = 2$, $\sigma(t-1) = \sigma(t)$ and $\str r$ is of type $Y$.  Then $k = x+1$ and the exchange relation for $\gamma(r, i)$ is 
		\begin{multline}\label{equation: degree 6 exchange relations, second cycle YB}
			\Delta_{\gamma(r, 2)}\Delta'_{\gamma(r, 2)} = \big(\mcw{p}{d-y}\wedge \mcf_{t-1}^y\big)\big(\mcf_p^{x}\wedge \mcf_t^{d-x}\big) \big(\mcf_p^{x+2}\wedge \mcf_{t+1}^{d-(x+2)}\big) \\
			+\big(\mcf_p^{x+1}\wedge \mcf_{t+1}^{d-(x+1)}\big)\big(\mcf_p^{x}\wedge \mcf_{t-1}^{d-x}\big) \big(\mcw{p}{d-y}\wedge \mcf_{t}^y\big),
		\end{multline}
		where 
		\begin{align}
		\Delta'_{\gamma(r, 2)} &=
		\frac{\mcf_p^{x} \mixwed \mcf_{t-1}^{d-(x+1)} \mixwed\mcf_{t+1}^{d-(x+1)} \mixwed \mcf_p^{x+2} }{\mcb{p}{x+1}\wedge \mcf_{t-1}^{d-(x+1)}}\\
		&= 
		\begin{cases}
			\mcw{p}{d-y}\mixwed \mcf_{t-1}^{y-1} \mixwed \mcf_{t+1}^{d-(x+1)}\mixwed\mcf_p^{x+2} &  \text{if } \, \mcb{p}{x} \neq \mcf_p^{x};\\
			\mcw{p}{d-y}\mixwed \mcf_{t-1}^{y+1} \mixwed\mcf_{t+1}^{d-(x+1)} \mixwed \mcb{p}{x} &  \text{if } \, \mcb{p}{x} = \mcf_p^{x}.\\
		\end{cases}
		\end{align}
	\end{enumerate} 
\end{prop}

\begin{remk}
When $k = 1$ or $k = d-1$, certain degeneracies arise in \crefrange{equation: degree 4 exchange relations HX}{equation: degree 6 exchange relations XX}. These cases occur when either $\str r$ is the first strip of its $BW$-type, or $\str r$ is the last strip. To address these degeneracies, the exchange relations must be adjusted according to the quiver structure described in Proposition \ref{prop: description of local pictures, i not 1}. 

For example, when $k = 1$, $\sigma(t-1) = -\sigma(t) = 1$, equation (\ref{equation: degree 4 exchange relations HX}) simplifies to:
\[
\big(\mcf_p^1\wedge \mcf_t^{d-1}\big)\big(\mcf_{t-1}^1\wedge \mcf_{t+1}^{d-1}\big) = \mcf_p^1\wedge \mcf_{t-1}^{d-1} + \big(\mcf_p^1\wedge \mcf_{t+1}^{d-1}\big)\big(\mcf_{t-1}^{1}\wedge \mcf_{t}^{d-1}\big).
\]

This adjustment reflects near-boundary behavior in the quiver structure.
Consequently, \crefrange{equation: degree 4 exchange relations HX}{equation: degree 6 exchange relations XX} are called the \emph{generic exchange relations} for $\gamma(r, i)$, as they hold uniformly outside these degenerate boundary scenarios.
\end{remk}

\begin{proof}[Proof of Proposition~\ref{prop: exchange relations, generic case}]
	The exchange relations arise directly from the combinatorial structure of the local pictures (cf.\ Proposition~\ref{prop: description of local pictures, i not 1}) together with Proposition~\ref{prop: decoration flags of the initial weave}. The expressions for the once mutated cluster variables are obtained by a direct calculation. Here we present the calculation for the expression of $\Delta'_{\gamma(r, i)}$ for equation~(\ref{equation: degree 6 exchange relations HH}); other cases are obtained in a similar way. 

	Assume that $\sigma(t-1) = \sigma(t) = 1$. With the same notation as in Proposition \ref{prop: decoration flags of the initial weave}, we have $k = x+1$. %We will be using Lemma \ref{lemma: derivative formula for mixwed wedge} and Proposition \ref{prop: wedge of any two within a flag is zero}. 

	We first simplify the first term on the right-hand side of the equation (\ref{equation: degree 6 exchange relations HH}):
	\[
	\big(\mcf_p^{x+1}\wedge \mcf_{t-1}^{d-x-1}\big)\big(\mcf_p^{x}\wedge \mcf_t^{d-x}\big) \big(\mcf_p^{x+2}\wedge \mcf_{t+1}^{d-x-2}\big).
	\]
	Rearranging terms within the wedge product, we get:
	\begin{align*}
		\big(\mcf_p^{x+1}\wedge \mcf_{t-1}^{d-x-1}\big)\big(\mcf_p^{x+2}\wedge \mcf_{t+1}^{d-x-2}\big) &= \mcf_{t-1}^{d-x-1}\wed \big( \mcf_p^{x+1}\wed \big(\mcf_p^{x+2} \wed \mcf_{t+1}^{d-x-2}\big)\big) \\
		&= \mcf_{t-1}^{d-x-1}\wed \big( \mcf_p^{x+2}\wed \big(\mcf_p^{x+1} \wed \mcf_{t+1}^{d-x-2}\big)\big)\\
		&= \big(\mcf_{t-1}^{d-x-1}\wed  \mcf_p^{x+2} \big) \wed \big(\mcf_p^{x+1} \wed \mcf_{t+1}^{d-x-2}\big)\\
		&= \mcf_{t-1}^2 \wed\big(\mcf_p^{x+2} \wed  \mcf_{t+1}^{d-x-3} \big) \wed \big(\mcf_p^{x+1} \wed \mcf_{t+1}^{d-x-2}\big)\\
		&= -\big(\mcf_{t-1}^2 \wed \big(\mcf_p^{x+1} \wed \mcf_{t+1}^{d-x-2}\big) \big) \wed \big(\mcf_p^{x+2} \wed  \mcf_{t+1}^{d-x-3} \big)
	\end{align*}
	where the second equality follows from Proposition~\ref{prop: wedge of any two within a flag is zero}, and the fourth equality follows from Proposition~\ref{prop: intersection production expansion formula} (by expanding out the intersection, all but two terms are left, and they can be combined into a single term). Hence the first term simplifies to
	\begin{multline*}
		\big(\mcf_p^{x+1}\wedge \mcf_{t-1}^{d-x-1}\big)\big(\mcf_p^{x}\wedge \mcf_t^{d-x}\big) \big(\mcf_p^{x+2}\wedge \mcf_{t+1}^{d-x-2}\big) = \\
		-\big(\mcf_{t-1}^2 \wed \big(\mcf_p^{x+1} \wed \mcf_{t+1}^{d-x-2}\big) \big)\wed \big(\big(\mcf_p^{x}\wedge \mcf_t^{d-x}\big)\cdot \big(\mcf_p^{x+2} \wed  \mcf_{t+1}^{d-x-3} \big)\big).
	\end{multline*}
	Similarly, the second term simplifies to
	\begin{multline*}
		\big(\mcf_p^{x+1}\wedge \mcf_{t+1}^{d-x-1}\big)\big(\mcf_p^{x}\wedge \mcf_{t-1}^{d-x}\big) \big(\mcf_p^{x+2}\wedge \mcf_{t}^{d-x-2}\big) = \\
		\big(\mcf_{t-1}^2 \wed \big(\mcf_p^{x+1} \wed \mcf_{t+1}^{d-x-2}\big) \big)\wed \big(\big(\mcf_p^{x+2}\wedge \mcf_t^{d-x-2}\big)\cdot \big(\mcf_p^{x} \wed  \mcf_{t+1}^{d-x-1} \big)\big).
	\end{multline*}
	Combining these two simplified terms, we get
	\begin{multline*}
		\big(\mcf_p^{x+1}\wedge \mcf_{t}^{d-(x+1)}\big)\Delta'_{\gamma(r, i)} = 
		\big(\mcf_{t-1}^2 \wed \big(\mcf_p^{x+1} \wed \mcf_{t+1}^{d-x-2}\big) \big) \\ 
		\wed \Big(\big(\mcf_p^{x+2}\wedge \mcf_t^{d-x-2}\big)\cdot \big(\mcf_p^{x} \wed  \mcf_{t+1}^{d-x-1} \big) - \big(\mcf_p^{x}\wedge \mcf_t^{d-x}\big)\cdot \big(\mcf_p^{x+2} \wed  \mcf_{t+1}^{d-x-3} \big) \Big).
	\end{multline*}
	Now we notice that 
	\begin{align*}
	&\mcf_{t-1}^2 \wed \big(\mcf_p^{x+1} \wed \mcf_{t+1}^{d-x-2}\big)\\
	=&\big( \mcf_{t-1}^1 \wed \mcf_p^{x+1} \wed \mcf_{t+1}^{d-x-2}\big)\cdot \mcf_t^1 - \big( \mcf_{t}^1 \wed \mcf_p^{x+1} \wed \mcf_{t+1}^{d-x-2}\big)\cdot \mcf_{t-1}^1\\
	=&\big( \mcf_{t-1}^1 \wed \mcf_p^{x+1} \wed \mcf_{t+1}^{d-x-2}\big)\cdot \mcf_t^1 + (-1)^x \big( \mcf_p^{x+1} \wed \mcf_{t}^{d-x-1}\big)\cdot \mcf_{t-1}^1
	\end{align*}
and
\begin{align*}
	&\mcf_t^1 \wedge \Big(\big(\mcf_p^{x+2}\wedge \mcf_t^{d-x-2}\big)\cdot \big(\mcf_p^{x} \wed  \mcf_{t+1}^{d-x-1} \big) - \big(\mcf_p^{x}\wedge \mcf_t^{d-x}\big)\cdot \big(\mcf_p^{x+2} \wed  \mcf_{t+1}^{d-x-3} \big) \Big) \\
	=& (-1)^x \big(\mcf_p^{x+2}\wedge \mcf_t^{d-x-2}\big)\cdot \big(\mcf_p^{x} \wed  \mcf_{t}^{d-x} \big) - (-1)^x\big(\mcf_p^{x}\wedge \mcf_t^{d-x}\big)\cdot \big(\mcf_p^{x+2} \wed  \mcf_{t}^{d-x-2} \big)\\
	=& 0.
\end{align*}
Therefore we conclude that 
\[
\Delta'_{\gamma(r, i)} = 
(-1)^x \mcf_{t-1}^1
\wed \Big(\big(\mcf_p^{x+2}\wedge \mcf_t^{d-x-2}\big)\cdot \big(\mcf_p^{x} \wed  \mcf_{t+1}^{d-x-1} \big) - \big(\mcf_p^{x}\wedge \mcf_t^{d-x}\big)\cdot \big(\mcf_p^{x+2} \wed  \mcf_{t+1}^{d-x-3} \big) \Big).
\]
Finally by Lemma~\ref{lemma: derivative formula for mixwed wedge} and  Propositions~\ref{prop: wedge of any two within a flag is zero} and \ref{prop: intersection production expansion formula}, we have
\begin{align*}
	&\big(\mcf_p^x \wed \mcf_{t+1}^{d-x-1}\big) \big(\mcf_p^{x+2}\wed \mcf_t^{d-x-2}\big)  \\
	=& \big(\mcf_p^{x+2} \mixwed \mcf_p^x \mixwed \mcf_{t+1}^{d-x-1}\big) \mixwed \mcf_t^{d-x-2} + \big(\mcf_p^{x+2}\wed \big(\mcf_p^x\wed \mcf_{t+1}^{d-x-1}\big)\wed \mcf_t^{d-x-2}\big)\\
	=& \big(\mcf_p^{x} \mixwed \mcf_p^{x+2} \mixwed \mcf_{t+1}^{d-x-1}\big) \mixwed \mcf_t^{d-x-2} + \big(\mcf_p^{x+2}\wed \big(\mcf_p^x\wed \mcf_{t}^{d-x}\big)\wed \mcf_{t+1}^{d-x-3}\big)\\
	=& \big(\mcf_p^{x} \mixwed \mcf_p^{x+2} \mixwed \mcf_{t+1}^{d-x-1}\big) \mixwed \mcf_t^{d-x-2} + \big(\mcf_p^{x}\wedge \mcf_t^{d-x}\big)\cdot \big(\mcf_p^{x+2} \wed  \mcf_{t+1}^{d-x-3} \big).
\end{align*}
Therefore 
\begin{align*}
	\Delta'_{\gamma(r, i)} &= (-1)^x \mcf_{t-1}^1 \mixwed \Big(\big(\mcf_p^{x} \mixwed \mcf_p^{x+2} \mixwed \mcf_{t+1}^{d-x-1}\big) \mixwed \mcf_t^{d-x-2} \Big)\\
	&=\mcf_p^{x} \mixwed \mcf_{t-1}^{d-(x+1)} \mixwed \mcf_{t+1}^{d-(x+1)}\mixwed \mcf_p^{x+2}.
\end{align*}
The derived expression for $\Delta'_{\gamma(r, i)}$ matches the proposed formula, confirming that the exchange relation holds under the given assumptions.
\end{proof}


For the case  $r = d-1$ and $i\in [2, m_1-r-1]$, the local pictures are constructed analogously. Specifically, the cycle $\gamma(r, i)$ connects to vertices in two strips above, $\str{r'}$ and $\str{r''}$, where $\str{r'}$ (resp., $\str{r''}$) is the closest strip above such that its $i' = (i+r-r')$-th (resp., $i'' = (i+r-r'')$-th) patch is of type $X$ (resp. $H$). To fully characterize the quiver structure, we analyze four distinct configurations depending on the types of the subsequent patches $i'+1$ in $\str{r'}$ and $i''+1$ in $\str{r''}$. These cases follow patterns analogous to those in Propositions~\ref{prop: description of local pictures, i not 1} and~\ref{prop: exchange relations, generic case}, and we omit their explicit examination here.




