\begin{prop}\label{prop: exchange relations, i = 1}
	Let $r\in [1, d-1]$ and $i = 1$. Then the exchange relation for $\gamma(r, 1)$ is described as follows, depending the type of $\str r$. 
	\begin{enumerate}[wide, labelwidth=!, labelindent=0pt]
		\item[(Y)]
		Suppose that $\str r$ is of type $Y$. Without loss of generality, we assume that $\str r$ is of $BW$-type $B$. 
		%Then $\sigma(t-1) = \sigma(t) = 1$.
		With notation as in Case 2(b) of Proposition~ \ref{prop: decoration flags of the initial weave}, we have 
		\[
		\Delta_{\gamma(r, 1)} = \mcw{p}{d-y}\wedge \mcf_{t}^y, \quad \text{with }\, t = p+r+1.
		\]
		The exchange relation for $\gamma(r, 1)$ is given by
		\begin{multline}\label{equation: degree 4 exchange relations for the first cycle Y-strip}
			\Delta_{\gamma(r, 1)}\Delta'_{\gamma(r, 1)} = \big(\mcf_p^x\wedge \mcf_{t}^{d-x}\big)\big(\mcf_p^{d-(y-1)}\wedge \mcf_{t+1}^{y-1}\big)\\ + \big(\mcf_p^{x+1}\wedge \mcf_{t+1}^{d-(x+1)}\big)\big(\mcf_p^{d-(y-1)}\wedge \mcf_{t}^{y-1}\big),
		\end{multline}
		where $\Delta'_{\gamma(r, 1)} = 
		\mcb{p}{x+1}\mixwed \mcf_{t}^{y-1}\mixwed\mcf_{t+1}^{d-(x+1)}\mixwed 	\mcf_p^{d-(y-1)}$.
		In the case when $\mcf_p^x = \mcb{p}{x}$, we need to adjust  equation (\ref{equation: degree 4 exchange relations for the first cycle Y-strip}) by inserting an extra factor $\mcf_{p+x}^{d-1}\wedge \mcf_{p+x+1}^1$ into the first term of the right-hand side. 

		\item[(X)]
		Suppose that $\str r$ is of type $X$. Without loss of generality, assume that $\str r$ is of $BW$-type $W$. 
		%Then $\sigma(t-1) = -\sigma(t) = -1$.
		Let $r'\in [r+1, d-1]$ be such that $\str{r'}$ is the next $X$-strip. With notation (for $\str{r'}$) as in Case 2(b) of Proposition~\ref{prop: decoration flags of the initial weave}, we have 
		\[
		\Delta_{\gamma(r, 1)} = \mcw{p}{d-(y+1)}\wedge \mcf_{t}^{y+1}, \quad \text{with }\, t = p+r'+1.
		\]
		The exchange relation for $\gamma(r, 1)$ is given by
		\begin{multline}\label{equation: degree 4 exchange relations for the first cycle X strip}
			\Delta_{\gamma(r, 1)}\Delta'_{\gamma(r, 1)} = \big(\mcf_p^{x-1}\wedge \mcf_{t}^{d-{(x-1)}}\big)\big(\mcf_p^{d-y}\wedge \mcf_{t+1}^{y}\big)\\
			 + \big(\mcf_p^{x}\wedge \mcf_{t+1}^{d-x}\big)\big(\mcf_p^{d-y}\wedge \mcf_{t}^{y}\big),
		\end{multline}
		where $\Delta'_{\gamma(r, 1)} = 
		\mcb{p}{x}\mixwed \mcf_{t}^{y}\mixwed\mcf_{t+1}^{d-x}	\mixwed \mcf_p^{d-y}$.
		In the case when $\mcf_p^{x-1} = \mcb{p}{x-1}$ (and $x>1$), we need to adjust  equation (\ref{equation: degree 4 exchange relations for the first cycle X strip}) by inserting an extra factor $\mcf_{p+x-1}^{d-1}\wedge \mcf_{p+x}^1$ into the first term of the right-hand side. In the case when $\str{r}$ is the first strip of its $BW$-type, we need to adjust  equation (\ref{equation: degree 4 exchange relations for the first cycle X strip}) by inserting an extra factor $\mcf_{p+r+1}^{d-1}\wedge \mcf_{p+r+2}^1$ into the first term of the right-hand side.

		\item[(HH)] Suppose that $\str r$ is of type $H$ and the second patch of $\str r$ is of type $H$. Without loss of generality, assume that $\str r$ is of $BW$-type $B$. 
		%Then $\sigma(t-1) = \sigma(t) = 1$.
