		\[
		\Delta_{\gamma(r, 1)} = \mcf_p^r \wedge \mcf_t^{d-r}, \quad \text{with } \, t = p+r+1.
		\]
		The exchange relation for $\gamma(r, 1)$ is given by 
		\begin{multline}\label{equation: degree 4 exchange relations for the first cycle HH}
			\Delta_{\gamma(r, 1)}\Delta'_{\gamma(r, 1)} = \big(\mcf_p^{r-1}\wedge \mcf_{t}^{d-(r-1)}\big)\big(\mcf_p^{r+1}\wedge \mcf_{t+1}^{d-(r+1)}\big)\\ + \big(\mcf_p^{r-1}\wedge \mcf_{t-1}^{d-(r-1)}\big)\big(\mcf_p^{r}\wedge \mcf_{t+1}^{d-r}\big),
