\begin{prop}\label{prop: exchange relations for defrosted variables}
	The exchange relations for the defrosted cluster variables are 
	\begin{multline}
		\big(\mcf_p^{d-k}\wedge \mcf_q^{k}\big)\big(\mcf_{p-1}^{d-k}\wedge \mcf_{q-1}^k\big) = \big(\mcf_p^{d-k}\wedge \mcf_{q-1}^k \big)\big(\mcf_{p-1}^{d-k}\wedge \mcf_{q}^k\big)\\
		 + \big(\mcf_{p}^{d-(k+1)}\wedge \mcf_{q-1}^{k+1}\big)\big(\mcf_{p-1}^{d-(k-1)}\wedge \mcf_q^{k-1}\big),
	\end{multline}
	for $k\in [1, d-1]$. When $k = 1$ or $k = d-1$, the degenerated expressions should be adjusted following Proposition \ref{prop: local picture around the defrosted vertices}. 
\end{prop}

