\begin{cor}\label{cor: once mutated c.v. are in Rsigma}
	Let $(p, q)$ be a valid cut of $\sigma$ with $\sigma(p-1) = \sigma(q-1)$. Consider the initial seed $\seed_\sigma(p, q)$. Then all the once mutated cluster variables lie in the ring  $R_\sigma$. 
\end{cor}
\begin{proof}
	Combining the exchange relations from Propositions~\ref{prop: exchange relations, generic case},~\ref{prop: exchange relations, i = 1} and~\ref{prop: exchange relations for defrosted variables}, we observe that all once-mutated cluster variables are expressible as mixed wedges of~$u_i$'s. Hence all of them lie in $R_\sigma$, by the same argument as in the proof of Corollary~\ref{cor: seed lies in R sigma}.
\end{proof}



\subsection{$\mca_\sigma$ contains the Weyl generators}\label{section: weyl generators}

In this section, we will show that all Weyl generators for $R_\sigma$ (cf. Definition~\ref{defn: Weyl generators}) belong to $\mca_\sigma$. This result will have two consequences. First, it will imply that our ``seeds" $\seed_\sigma(p, q)$ for $\mca_\sigma$ are indeed seeds, i.e., the elements of a extended cluster are algebraically independent. Second, it will imply that  $R_\sigma$ is a subalgebra of $\mca_\sigma$, by the First Fundamental Theorem of Invariant Theory, cf.\ Theorem~\ref{thm: the first fundamental theorem of invariant theory}.


Let $1\le i \le j \le n$ be such that $\sigma(i) = -\sigma(j) = 1$. We begin by showing that  $\langle u_i , u_j^* \rangle = u_i\mixwed u^*_j = \mcf_i^1\wedge \mcf_j^{d-1}\in \mca_\sigma$. 

\begin{lemma}\label{lemma: pairings are in A sigma}
	Any pairing $\langle u_i , u_j^* \rangle$ lies in the extended cluster for the initial seed $\seed_\sigma(p, q)$, for some $1\le p \le q \le n$ with $\|p-q\| \ge d+1$.
\end{lemma}
\begin{proof}
If $\| i - j\| \ge d+1$, then we take $p = i, q = j$. Then $\langle u_i , u_j^* \rangle = \mcf_p^1\wedge \mcf_q^{d-1}$ is a cluster variable for $\seed_\sigma(p, q)$, cf. Proposition~\ref{prop: decoration flags of the initial weave}. 

Otherwise, without loss of generality, we assume that $|j - i| \le d$.  Let $p = i$ and $q>j$ such that $\|p - q\| \ge d+1$. 

Consider the initial weave $\ww_1 = \ww(p, q)$. If $j = i+1$, then $\mcf_p^1\wedge \mcf_j^{d-1}$ is the frozen variable associated with the  cycle originating from the first marked boundary vertex. Thus, from now on we assume that $j>i+1$. 

If $\sigma(p+1) = \sigma(p+2) = \cdots = \sigma(j) = -1$, then $\mcf_p^1\wedge \mcf_j^{d-1}$ is the first cluster or frozen variable in the $(j-i-1)$-th strip.  Otherwise, $\mcf_p^1\wedge \mcf_j^{d-1}$ is the $(j-i-1)$-th cluster or frozen variable in the first strip. Both of the statements  follow directly from Proposition~\ref{prop: decoration flags of the initial weave}.
\end{proof}

Now let $p= i_1<i_2<\cdots <i_d\le q$ be such that all $i_j$'s are of the same color. We are going to show that $\det(u_{i_1}, u_{i_2}, \dots, u_{i_d})\in \mca_\sigma$.

\begin{defn}\label{defn: generalized patches and strips}
	A \emph{generalized $X$-patch} is a partial weave, either of the form \newline $\cdots I_i^j I_j^k\cdots \rarrow \cdots I_{j+1}^k I_i^j \cdots$ with $k\le i$ or of the form $\cdots I_j^i I_i^k \cdots \rarrow \cdots I_{i+1}^k I_j^i\cdots$ with $k\le j$. Similarly a \emph{generalized $H$-patch} is a partial weave, either of the form $\cdots I_i^j I_k^j\cdots \rarrow \cdots I_{k+1}^j I_i^j \cdots$ with $k\le i$ or of the form $\cdots I_j^i I_k^i \cdots \rarrow \cdots I_{k+1}^i I_j^i\cdots$ with $k\le j$. We say that a generalized patch is \emph{of type} $H$ (resp., $X$) if it is a $H$-patch (resp., $X$-patch). The ``degenerated" patch $\cdots i i \cdots \rarrow \cdots i \cdots$ is called a \emph{degenerate patch}. 

	A \emph{generalized strip} is a partial weave formed by concatenations of generalized patches. The type of a generalized strip is defined to be the type of its first patch. 
\end{defn}


\begin{prop}\label{prop: determinants are in A sigma}
	The determinant $\det(u_{i_1}, u_{i_2}, \cdots, u_{i_d})$ lies in the extended cluster for a seed $\seed_\sigma(p, q)$.
\end{prop}
\begin{proof}
Without loss of generality, we assume that all vertices $i_j$ are black.
Consider the decorated Demazure weave $\ww: \beta(p, q) \rarrow \beta'$ constructed as follows. 

Let $\beta(p, q) = T_1T_2\cdots T_m$ where $m = q-p$. The weave lines on and after the interval word $T_{i_d}$ will remain unchanged in the construction. Start with the word $T_{i_{d-1}}T_{i_{d-1}+1}\cdots T_{i_{d}-1}$. Construct an $H$-strip (resp., $X$-strip) if the first two interval words are the same (resp., different), cf.\ Definition~\ref{defn: strips}. Denote the bottom word by $T(d-1)T_{i_{d-1}}$. Then by Proposition~\ref{prop: decoration flags of the initial weave}, the decoration for the bottom word is of the form
\[
\mcf_{i_{d-1}} \rel{T(d-1)} \lpush{\mcf_{i_{d-1}}}{1}{\mcf_{i_d}} \rel{T_{i_{d-1}}} \mcf_{i_d}.
\]

Then consider the word $T_{i_{d-2}}T_{i_{d-2}+1}\cdots T_{i_{d-1}-1} T(d-1)T_{i_{d-1}}$. Construct a generalized $H$-strip (resp., $X$-strip) if the first two interval words are the same (resp., different), following a similar procedure as in Definition~\ref{defn: strips}; denote the bottom word by $T(d-2)T'(d-1)T_{i_{d-2}}T_{i_{d-1}}$. Following the proof of Proposition~\ref{prop: decoration flags of the initial weave}, we conclude that the decoration for the bottom word is of the form
\[
\mcf_{i_{d-2}} \rel{T(d-2)} \lpush{\mcf_{i_{d-2}}}{1}{\mcf_{i_{d-1}}} \rel{T'(d-1)} \lpush{\mcf_{i_{d-1}}}{1}{(\lpush{\mcf_{i_{d-2}}}{1}{\mcf_{i_d}})} \stackrel{T_{i_{d-2}}T_{i_{d-1}}}{\leftarrow \joinrel \xrightarrow{\hspace*{1cm}}}\mcf_{i_d}.
\]
Repeat this construction until we have made $d-1$ strips. Consider the last strip, denote the bottom word by $ \tilde{T}(1)\tilde{T}(2)\cdots \tilde{T}(d-2)T_{i_1}T_{i_2}\cdots T_{i_{d-1}}$. The decoration for the bottom word is 
\begin{multline*}
	\mcf_{i_{1}} \rel{\tilde{T}(1)} \lpush{\mcf_{i_{1}}}{1}{\mcf_{i_{2}}} \rel{\tilde{T}(2)} \cdots \rel{\tilde{T}(d-2)} \lpush{\mcf_{i_1}}{1}{\bigg(\lpush{\mcf_{i_2}}{1}{\big(\cdots(\lpush{\mcf_{i_{d-2}}}{1}{\mcf_{i_{d-1}}})\big)}\bigg)}\\
	\rel{T_{i_1}} \lpush{\mcf_{i_2}}{1}{\bigg(\lpush{\mcf_{i_3}}{1}{\big(\cdots(\lpush{\mcf_{i_{d-1}}}{1}{\mcf_{i_{d}}})\big)}\bigg)}  \stackrel{T_{i_2}T_{i_3}\cdots T_{i_{d-1}}}{\leftarrow \joinrel \xrightarrow{\hspace*{1.7cm}}}  \mcf_{i_d}.
\end{multline*}

Now we simply notice that for the last patch (degenerated) of the last generalized strip, the cycle $\gamma$ associated with that patch originates at the last character of $T_{i_1}$. As a result, the cluster or frozen variable associated with that cycle is 
\begin{align*}
\Delta_\gamma &= \qwed{\mcf_{i_1}\wedge \mcf_{i_2}\wedge \cdots \wedge \mcf_{i_{d-1}}}{\mcf_{i_2}\wedge \mcf_{i_3} \wedge \cdots \wedge  \mcf_{i_d}}{\mcf_{i_2}\wedge \mcf_{i_3}\wedge \cdots \wedge \mcf_{i_{d-1}}}\\
& = \mcf_{i_1}\wedge \mcf_{i_2}\wedge \cdots \wedge \mcf_{i_{d}} \\
&= \det(u_{i_1}, u_{i_2}, \cdots, u_{i_d}).
\end{align*}

Although $\beta' = \tilde{T}(1)\tilde{T}(2)\cdots \tilde{T}(d-2)T_{i_1}T_{i_2}\cdots T_{i_{d-1}} T_{i_{d}}T_{i_{d}+1}\cdots T_m$ is not reduced, we simply make any partial weave $\ww': \beta' \rarrow \beta''$ such that $\beta''$ is reduced, then concatenate $\ww: \beta(p, q) \rarrow \beta'$ with $\ww'$. The resulting Demazure weave is denoted by $\ww_1$.  We have shown that  $\det(u_{i_1}, u_{i_2}, \cdots, u_{i_d})$ is a cluster or frozen variable for the seed $\seed(\ww_1)$. This implies that $\det(u_{i_1}, u_{i_2}, \cdots, u_{i_d})$ lies in the extended cluster for the amalgamated seed $\seed_\sigma(p, q)$.
\end{proof}


\begin{cor}\label{cor: weyl generators are in A sigma}
	Assume that $n > d^2$ and let $I\in R_\sigma$ be a Weyl generator. Then there exist $1\le p\le q\le n$ with $\|p-q\| \ge d+1$ such that $I$ lies in the extended cluster for the seed $\seed_\sigma(p, q)$. 
\end{cor}
\begin{proof}
	The condition $n>d^2$ guarantees that there exists a cut $(p, q)$ satisfying $\|p-q\|>d$ such that all the vertices used for the Weyl generator $I$ lie on one side of the cut. The result then follows from Lemma~\ref{lemma: pairings are in A sigma} and Proposition~\ref{prop: determinants are in A sigma}. 
\end{proof}

\begin{remk}
	The condition $n>d^2$ seems to be stronger than necessary. We conjecture that it can be relaxed to $n \ge 2d$. 
\end{remk}


\begin{lemma}\label{lemma: alg indep of the cluster}
	Assume that $n > d^2$. Let $1\le p\le q\le n$ with $\| p - q\| \ge d+1$. Then the elements in the extended cluster for a seed $\seed_\sigma(p, q)$ are algebraically independent. 
\end{lemma}
\begin{proof}
	By Proposition~\ref{prop: cluster algebra does not depend on the cut}, any two seeds $\seed_\sigma(p, q)$ and $\seed_\sigma(p', q')$ are mutation equivalent. As a consequence, the corresponding extended seeds are birationally related to each other, i.e., any cluster variable in $\seed_\sigma(p', q')$ can be written as a rational function in the extended cluster for $\seed_\sigma(p, q)$. By Corollary~\ref{cor: weyl generators are in A sigma}, these extended clusters will collectively generate the fraction field $K_\sigma$ of $R_\sigma$. 

	By Corollary~\ref{cor: dimension for mca sigma}, the size of an extended cluster is $d(n-d)+1$, which coincides with the (Krull) dimension of $R_\sigma$. The transcendent degree of $K_\sigma$ over $\C$ is equal to the (Krull) dimension of $R_\sigma$, cf.\ \cite[Theorem 5.9]{Kemper}. It follows that the elements in an extended cluster for a seed $\seed_\sigma(p, q)$ are algebraically independent. 
\end{proof}

\begin{proof}[Proof of Lemma~\ref{lemma: amalgamation condition is satisfied}]
	By Proposition~\ref{prop: decoration flags of the initial weave}, the two seeds $\seed_1 = \seed(\ww(p, q))$ and $\seed_2 = \seed(\ww(q, p+n))$ have common frozen variables \[\zz_0 = \{\mcf_p^1\wedge \mcf_q^{d-1}, \mcf_p^2\wedge \mcf_q^{d-2}, \dots, \mcf_p^{d-1}\wedge \mcf_q^1\}.\]
	By Lemma~\ref{lemma: alg indep of the cluster}, we know that the elements in the union of the extended clusters for $\seed_1$ and $\seed_2$ are algebraically independent. Therefore, these two seeds can be amalgamated along $\zz_0$ (cf.\ Definition~\ref{defn: amalgamating two seeds}). 
\end{proof}


\begin{prop}\label{prop: rsigma is in mcasigma}
	Assume that $n>d^2$. Then $R_\sigma$ is a subalgebra of $\mca_\sigma$, i.e., we have the inclusions
	\[
	R_\sigma \subseteq \mca_\sigma \subseteq \K.
	\]
\end{prop}
\begin{proof}
	This follows from Corollary~\ref{cor: weyl generators are in A sigma} and Theorem~\ref{thm: the first fundamental theorem of invariant theory}.
\end{proof}






\subsection{Proof of the main theorem}\label{sec: proof of the main theorem}

In this section, we present two different proofs for Theorem~\ref{thm: mixed grassmannian is a cluster algebra}, both relying on the results in \cite{GLS}. 

Assume that $d$ is odd and $n>d^2$. Recall that by Proposition~\ref{prop: rsigma is in mcasigma}, we have $R_\sigma \subseteq \mcas$. So we only need to show the other inclusion. 

The first proof uses \cite[Theorem 1.4]{GLS}. By finding two disjoint seeds lying in $R_\sigma\subseteq \mcas$, we deduce that $R_\sigma = \mcas$.

The second proof uses \cite[Theorem 1.3]{GLS} to show that all cluster and frozen variables in $\mca_\sigma$ that lies in $R_\sigma$ are irreducible in $R_\sigma$; and then uses Proposition~\ref{prop:cluster-criterion} to conclude that $R_\sigma = \mcas$ by showing that the cluster and frozen variables for the initial seed and it is neighbors are all in $R_\sigma$. 


We start by presenting the first proof. The key result we will need is \cite[Theorem~ 1.4]{GLS}, restated as Theorem~\ref{thm: disjoint clustes lies in a subalgebra ufd implies equality} below.  


\begin{defn}
	Let $\mca$ be a cluster algebra of rank $r$ and dimension $s$. Denote the set of frozen variables of $\mca$ by $\{z_{r+1}, \cdots, z_{s}\}$.  Two clusters $\xx = (x_1, \dots, x_r)$ and $\yy = (y_1, \dots, y_r)$ of a cluster algebra $\mca$ are \emph{disjoint} if $\{x_1, \cdots, x_r\} \cap \{y_1, \dots, y_r\} = \emptyset$. 
\end{defn}


\begin{theorem}[{\cite[Theorem 1.4]{GLS}}]\label{thm: disjoint clustes lies in a subalgebra ufd implies equality}
	Let $\xx$ and $\yy$ be disjoint clusters of $\mca$. Let $R\subseteq \mca$ be a factorial subalgebra of $\mca$ such that 
	\[
	\{x_1, \cdots, x_r, y_1, \cdots, y_r, z_{r+1}, \cdots, z_{s}\} \subseteq R \subseteq \mca. 
	\]
	Then $R = \mca$.
\end{theorem}

Our goal is to identify two disjoint seeds for $\mca_\sigma$. They will both be initial seeds for some cuts $(p, q)$. 

\begin{lemma}\label{lemma: a tuple for disjoint seeds} Assume that $n\ge 4d-2$.
	Then there exists a tuple $(p, p', q, q')$ with $1\le p < p' < q < q' \le n$ (up to a cyclic shift) that satisfies the following conditions:
	\begin{enumerate}[wide, labelwidth=!, labelindent=0pt]
		\item there exists $\tilde{p}$ with $q'\le \tilde{p} < p+n$ such that $\sum_{i = \tilde{p}}^{p-1} \sigma(i) \equiv 0 \mod d$;
		\item there exists $\tilde{q}$ with $p'\le  \tilde{q} < q$ such that $\sum_{i = \tilde{q}}^{q-1} \sigma(i) \equiv 0 \mod d$;
		\item $p'-p\ge d-1$ and $q'-q\ge d-1$;
		\item $\| p-q\|\ge d+1$ and $\|p'-q'\| \ge d+1$. 
	\end{enumerate}
\end{lemma}
\begin{proof}
	If $\sigma$ is monochromatic, then we pick $p = 1, p' = d, q= 2d, q' = 3d-1$; it is easy to check that all conditions are satisfied. 

	Now assume that $\sigma$ is not monochromatic. Up to a cyclic shift, we may assume that $p = 1$ and $\sigma(n) = -\sigma(n-1)$. Let $p' = d$ and $q' = n-2$. Now consider the restriction of $\sigma$ to $[d, n-d-2]$. 
	\begin{itemize}[wide, labelwidth=!, labelindent=0pt]
		\item If $\sigma$ is monochromatic on $[d, n-d-2]$, then we take $q= n-d-1$. Let us check that all conditions are satisfied. 
		\begin{itemize}
			\item Take $\tilde{p} = n-2$, then $\sigma(n-2) + \sigma(n-1) = 0$;
			\item take $\tilde{q} = n-2d-1$, notice that $\tilde{q}= n-2d-1\ge 4d-2 - 2d -1 = 2d - 3 \ge d = p'$, and $\sum_{i = n-2d-1}^{n-d-2} \sigma(i) = d \equiv 0\mod d$;
			\item we have $p'-p = d-1$ and $q' - q = n-2 - (n-d-1) = d-1$;
			\item $\| p-q \| = \min\{n-d-2, d+2\} \ge d+1$ and $\|p' -q'\| = \min\{n-2-d, d+2\} \ge d+1$. 
		\end{itemize}
		\item Otherwise, let $j\in [d, n-d-3]$ such that $\sigma(j) = -\sigma(j+1)$, we take $q = j+1$. Similarly we can check that all conditions are satisfied.  \qedhere
	\end{itemize}
\end{proof}

\begin{defn}
	Recall from Definition~\ref{defn: tuple of flags mcf associated with sigma and u} that $\mcf_j^k = u_j\mixwed u_{j+1}\mixwed \cdots \mixwed u_{j'}$ where $j' \ge j$  is the smallest integer such that $\sum_{i = j}^{j'}\sigma(i) \equiv k \mod d$. Let $j\le \bar j < j+n$ such that $\bar j \equiv j' \mod n$; and let $h_j^k = \frac{j' - \bar j}{n} \in \Z$. We say the extensor $\mcf_j^k$ \emph{starts at $j$, ends at $\bar{j}$, and has $h_j^k$ revolutions}. 

	Recall from Definition~\ref{defn: multidegree} that for an invariant $f\in R_\sigma$, the multidegree of $f$ is defined to be 
	\[
	\multideg(f) = (d_1, \cdots, d_n)
	\]
	where $d_i= \deg_i(f)$ is the homogeneous degree of $f$ in $u_i$, for $i\in [1, n]$. We extend $d_i$ to all $i\in  \Z$ by periodicity, i.e., $d_{i+n} = d_i$ for $i\in \Z$. This notion can be naturally adapted to an extensor $\mcf_j^k$. To be precise, we define the  \emph{multidegree} of $\mcf_j^k$ to be
	\[
	\multideg(\mcf_j^k) = (\dots, d_1, \dots, d_n, \dots)
	\]
	such that $d_{i+n} = d_i$ for all $i\in \Z$ and 
	\[
	d_i = \deg_i(\mcf_j^k) = \begin{cases}
		h_j^k, & \text{if }\, \bar j < i <j+n;\\
		h_j^k + 1, & \text{if }\, j\le i \le \bar j.
	\end{cases}
	\]
\end{defn}


\begin{lemma}\label{lemma: necessary conditions for two wedge product to be the same}
	Let $1\le j_1 < j_2 \le n$, $1\le j_1'< j_2'\le n$, $k, k'\in [1, d-1]$ such that $j_1 \neq j_1'$, $j_1\neq j_2'$, $j_2\neq j'_1$. Then we have $\mcf_{j_1}^k\wedge \mcf_{j_2}^{d-k} \neq  \mcf_{j_1'}^{k'}\wedge \mcf_{j_2'}^{d-k'}$ provided one of the following is true. 
	\begin{enumerate}[wide, labelwidth=!, labelindent=0pt]
		\item Both $\mcf_{j_1}^k$ and $\mcf_{j_2}^{d-k}$ do not end at $j_1-1$.
		\item $\mcf_{j_1}^k$ does not end at $j_1-1$ or $j_2-1$; $\mcf_{j_1'}^{k'}$ does not end at $j_1'-1$ or $j_2'-1$;  $\mcf_{j_1}^k$ and $\mcf_{j'_1}^{k'}$ do not end at the same vertex. 
	\end{enumerate}
\end{lemma}
\begin{proof}
	Assume that $\mcf_{j_1}^k\wedge \mcf_{j_2}^{d-k} = \mcf_{j_1'}^{k'}\wedge \mcf_{j_2'}^{d-k'}$, then
	\[
	\multideg(\mcf_{j_1}^k)+\multideg(\mcf_{j_2}^{d-k}) = \multideg(\mcf_{j'_1}^{k'})+\multideg(\mcf_{j'_2}^{d-k'}).
	\]
	Then the lemma follows from a case by case analysis, depending on where $\mcf_{j_1}^k$, $\mcf_{j_2}^{d-k}$, $\mcf_{j'_1}^{k'}$, $ \mcf_{j'_2}^{d-k'}$ ends. %Here we present the contradiction for the case when $j_2 = j'_2$, and both $\mcf_{j_1}^k$ and $\mcf_{j_2}^{d-k}$ do not end at $j_1-1$.%We would like to point out that these are only necessary conditions, as they only guarantee the multidegree matches, the wedge product might still be different. 
\end{proof}



\begin{lemma}\label{lemma: a disjoint pair of seeds}
	Let $(p, p', q, q')$ be a tuple satisfying the conditions in Lemma~\ref{lemma: a tuple for disjoint seeds}. The the clusters for the initial seeds $\seed_\sigma(p, q)$ and $\seed_\sigma(p', q')$ are disjoint. 
\end{lemma}
\begin{proof}
	By Proposition~\ref{prop: decoration flags of the initial weave}, cluster variables in $\seed_\sigma(p, q)$ are of the form
	\[
	\mcf_p^x\wedge \mcf_{p_1}^{d-x}, \quad \mcb{p}{x} \wedge \mcf_{p_1}^{d-x}, \quad \mcw{p}{x}\wedge \mcf_{p_1}^{d-x}, \quad \mcf_q^x\wedge \mcf_{q_1}^{d-x}, \quad \mcb{q}{x} \wedge \mcf_{q_1}^{d-x}, \quad \mcw{q}{x}\wedge \mcf_{q_1}^{d-x},
	\] 
	where $p+2\le p_1\le q$, $q+2\le q_1\le p+n$ and $x\in [1, d-1]$; and cluster variables in $\seed_\sigma(p', q')$ are of the form
	\[
	\mcf_{p'}^{x'}\wedge \mcf_{p'_1}^{d-x'}, \quad \mcb{p'}{x'} \wedge \mcf_{p'_1}^{d-x'}, \quad \mcw{p'}{x'}\wedge \mcf_{p'_1}^{d-x'}, \quad \mcf_{q'}^{x'}\wedge \mcf_{q'_1}^{d-x'}, \quad \mcb{q'}{x'} \wedge \mcf_{q'_1}^{d-x'}, \quad \mcw{q'}{x'}\wedge \mcf_{q'_1}^{d-x'},
	\] 
	where $p'+2\le p'_1\le q'$, $q'+2\le q'_1\le p'+n$ and $x'\in [1, d-1]$. 

	First let us consider the cluster variable $\mcf_p^x\wedge \mcf_{p_1}^{d-x}$. Let us show that it is not a cluster variable in $\seed_\sigma(p', q')$. If $\mcf_p^x\wedge \mcf_{p_1}^{d-x} = \mcf_{p'}^{x'}\wedge \mcf_{p'_1}^{d-x'}$, then by Lemma~\ref{lemma: a tuple for disjoint seeds} (1), we know that both $\mcf_p^x$ and $\mcf_{p_1}^{d-x}$ cannot end at $p-1$, hence by Lemma~\ref{lemma: necessary conditions for two wedge product to be the same} (1), we get a contradiction. Similarly we can show $\mcf_p^x\wedge \mcf_{p_1}^{d-x}\neq \mcf_{q'}^{x'}\wedge \mcf_{q'_1}^{d-x'}$. It's also clear that $\mcf_p^x\wedge \mcf_{p_1}^{d-x}$ is not equal to any of $\mcb{p'}{x'} \wedge \mcf_{p'_1}^{d-x'}$, $ \mcw{p'}{x'}\wedge \mcf_{p'_1}^{d-x'}$, $\mcb{q'}{x'} \wedge \mcf_{q'_1}^{d-x'}$,  $\mcw{q'}{x'}\wedge \mcf_{q'_1}^{d-x'}$ by an similar argument involving multidegree. 

	Now consider the cluster variable $\mcb{p}{x} \wedge \mcf_{p_1}^{d-x}$. If $\mcb{p}{x} \wedge \mcf_{p_1}^{d-x} = \mcb{p'}{x'} \wedge \mcf_{p'_1}^{d-x'}$, then by Lemma~\ref{lemma: a tuple for disjoint seeds} (3), we know that $\mcb{p}{x}$ only uses the black vertices in $[p, p'-1]$ and $\mcb{p'}{x'}$ only uses black vertices in $[p', q']$. If either $\mcb{p}{x}$ or $\mcb{p'}{x'}$ is not consecutive wedges of black vertices, then it is clear that the multidegree will not match. Now we assume that they are both consecutive wedges of black vertices, hence $\mcb{p}{x} =\mcf_{\bar{p}}^x$ and $\mcb{p'}{x'} = \mcf_{\bar{p'}}^x$ for some $\bar p \in [p, p']$ and $\bar{p'}\in [p', q']$. Notice that $\mcf_{\bar{p}}^x$ can not end at $\bar p-1$; if $\mcf_{\bar{p}}^x$ end  at $p_1-1$, then $\mcf_{\bar{p}}^x\wedge \mcf_{p_1}^{d-x}$ is a frozen variable, a contradiction. Similarly we can show that $\mcf_{\bar{p'}}^x$ can not end at $\bar{p'}-1$ or $p_1'-1$. Finally notice that $\mcf_{\bar{p}}^x$ and $\mcf_{\bar{p'}}^x$ can not end at the same vertex. Therefore, by Lemma~\ref{lemma: necessary conditions for two wedge product to be the same} (2), we get a contradiction. Similarly we can show that $\mcb{p}{x} \wedge \mcf_{p_1}^{d-x}$ is not equal to any of the cluster variables in $\seed_\sigma(p', q')$.

	Similar arguments can be applied to the other types of cluster variables in $\seed_\sigma(p, q)$, and we conclude that the two clusters for $\seed_\sigma(p, q)$ and $\seed_\sigma(p, q)$ are disjoint. 
\end{proof}



Now Theorem~\ref{thm: mixed grassmannian is a cluster algebra} follows. 



\begin{proof}[The first proof of Theorem~\ref{thm: mixed grassmannian is a cluster algebra}]
	By Proposition~\ref{prop: rsigma is in mcasigma}, we have $R_\sigma \subseteq \mca_\sigma$. By Lemma \ref{lemma: R(V) is a UFD}, $R_\sigma$ is factorial. Then by Lemmas~\ref{lemma: a tuple for disjoint seeds} and~\ref{lemma: a disjoint pair of seeds}, there exists a pair of disjoint clusters such that all their cluster variables are in $R_\sigma$ (cf.\ Corollary~\ref{cor: seed lies in R sigma}). The frozen variables are clearly in $R_\sigma$. Therefore $R_\sigma = \mcas$ by Theorem~\ref{thm: disjoint clustes lies in a subalgebra ufd implies equality}. 
\end{proof}

Now let us present the second proof. The key result needed from \cite{GLS} is restated as Theorem~\ref{thm: units of a cluster algebra are trivial and cluster varibles are irreducible} below. 

\begin{defn}
	Let $R$ be an integral domain and $R^\times$ be the set of invertible elements in $R$.  A nonzero element $f\in R$ is \emph{irreducible} if it cannot be written as a product $f = gh$ with non-invertible $g, h\in R$.
\end{defn}

\begin{theorem}[{\cite[Theorem 1.3]{GLS}}]\label{thm: units of a cluster algebra are trivial and cluster varibles are irreducible}
	Let $\mca$ be a cluster algebra. Then $\mca^\times = \C$ and any cluster or frozen variable in $\mca$ is irreducible. 
\end{theorem}

We remind the reader that frozen variables are not invertible by our convention. 

\begin{cor}\label{cor: cluster variables irreducible in Rsigma}
	A cluster or frozen variable in $\mcas$ that lies in $R_\sigma$ is irreducible in ~$R_\sigma$.
\end{cor}
\begin{proof}
	Let $x\in R_\sigma \subseteq \mca_\sigma$ be a cluster or frozen variable. Then $x$ is irreducible in $\mca_\sigma$ by Theorem~\ref{thm: units of a cluster algebra are trivial and cluster varibles are irreducible}. Now assume that $x$ is not irreducible in $R_\sigma$, then $x = gh$ with $g,h\in R_\sigma$ non-invertible in $R_\sigma$. Notice that $R_\sigma^\times = \mcas^\times = \C$, this implies $x = gh$ with $g, h\in \mcas$ and $g, h$ non-invertible in $\mcas$. Hence $x$ is not irreducible in $\mca_\sigma$, a contradiction.
\end{proof}


\begin{lemma}\label{lemma: requirements for starfish lemma}
	There exists a seed $\seed = (Q, \zz)$ for $\mcas$ satisfying the following conditions:
	\begin{enumerate}[wide, labelwidth=!, labelindent=0pt]
		\item all elements of $\zz$ belong to $R_\sigma$;
		\item the cluster variables are all irreducible;
		\item for each cluster variable $z\in \zz$, the seed mutation $\mu_z$ replace $z$ with an element $z'$ that lies in $R_\sigma$ and is irreducible in $R_\sigma$. 
	\end{enumerate}
\end{lemma}
\begin{proof}
	Let $(p, q)$ be a valid cut with $\sigma(p-1) = \sigma(q-1)$ and consider the initial seed $\seed_\sigma(p, q) = (Q, \zz)$. By Corollary~\ref{cor: seed lies in R sigma}, all elements of $\zz$ belong to $R_\sigma$. By Corollary~\ref{cor: once mutated c.v. are in Rsigma}, the once mutated cluster variables are also in $R_\sigma$. The lemma then follows from Corollary~\ref{cor: cluster variables irreducible in Rsigma}. 
\end{proof}









\begin{proof}[The second proof of Theorem~\ref{thm: mixed grassmannian is a cluster algebra}]
	By Proposition~\ref{prop: rsigma is in mcasigma}, we have $R_\sigma \subseteq \mcas$. Now we show the other inclusion. By Lemma~\ref{lemma: requirements for starfish lemma}, we can find a seed $\seed = (Q, \zz)$ such that all the frozen variables, cluster variables, and once mutated cluster variables are irreducible in $R_\sigma$. Notice that two elements in $\zz$ cannot differ by a scalar as they are algebraically independent; similarly $z$ and $z'$ cannot differ by a scalar since otherwise the exchange relation will give a non-trivial algebraic relation for elements in $\zz'$. We conclude that $\mcas \subseteq R_\sigma$ by Proposition~\ref{prop:cluster-criterion}, as desired. 
\end{proof}










