\section{Beyond the Main Theorem}\label{chap: properties and generalizations}

\subsection{Separated signatures}\label{sec: separated signatures}

In this section, we consider the case of separated signatures. Recall from Definition \ref{defn: separated signature} that a signature of type $(a, b)$ is {separated} if it contains $a$ consecutive black vertices followed by $b$ consecutive white vertices.  

%Theorem \ref{thm: mixed grassmannian is a cluster algebra in the case of separated signatures} states that for a separated signature $\sigma$ with $d$ odd, $a, b \ge d-1$ and $n \ge 2d$, we have $R_\sigma = \mcas$. Now let us prove it. 


\begin{defn}\label{defn: monochormatic and separated restrictions}
	Let $i \le j$. We say that  the restriction of $\sigma$ to $[i, j]$ is \emph{monochromatic} if $\sigma$ is constant on $[i, j]$. We say that the restriction of $\sigma$ to $[i, j]$ is \emph{separated} if there exists $k\in [i, j-1]$ such that the restrictions of $\sigma$ to $[i,k]$ and $[k+1, j]$ are both monochromatic. We say that $\sigma$ is \emph{monochromatic} if its restriction on $[1, n]$ is monochromatic. Note that $\sigma$ is {separated} if and only if there exists $j\in \Z$ such that the restriction of $\sigma$ to $[j, j+n-1]$ is separated. 
\end{defn}

\begin{example}
	The signature $\sigma = [\bullet\, \bullet \, \bullet\, \circ\, \circ\, \bullet\, \bullet\ \bullet]$ is separated. Its restriction on $[3, 7]$ is not separated. 
\end{example}


\begin{defn}\label{defn: valid cut for separated signatures}
	Let $\sigma$ be a separated signature. Let $1\le p \le q \le n$. The pair $(p, q)$ is called a \emph{feasible cut} for $\sigma$ (or $\beta_\sigma$) if one of the following conditions is satisfied:
	\begin{itemize}[wide, labelwidth=!, labelindent=0pt]	
		\item $n = 2d$, $q - p = d$, and each of the restrictions of $\sigma$ to $[p, q-1]$ and $[q, p+n-1]$ is separated;
		\item $n \ge 2d + 1$, $q - p = d$, and the restriction of $\sigma$ to $[p, q-1]$ is separated; 
		\item $n \ge 2d + 1$,  $p+n - q = d$, and the restriction of $\sigma$ to $[q, p+n-1]$ is separated;
		\item $\| p - q\| \ge d+1$.
	\end{itemize}
\end{defn}

\begin{defn}
	Let $(p, q)$ be a feasible cut for a separated signature $\sigma$ (note that $(p, q)$ is not necessarily a valid cut, cf.\ Definition \ref{defn: valid cut in general}). The cluster algebra $\mcas(p, q)$ is then defined in exactly the same way as in Definitions~\ref{defn: cutting along the disk to get two weaves} and~\ref{defn: cluster algebra cutting at p, q}. Notice that with the conditions for a feasible cut, we either have $m_1 = q-p \ge d+1$, or $\ww(p, q)$ does not contain an $X$-strip; in either case, Corollary~\ref{cor: description of the frozen cycles to the bottom for the initial weave} works, hence so does the amalgamation process, cf.\ Remark~\ref{remk: separated case no X strips so relaxed condition on n}. 
\end{defn}

\begin{prop}\label{prop: cluster algebra does not depend on the cut separated case}
	The cluster algebra $\mcas(p, q)$ does not depend on the choice of a feasible cut $(p, q)$.
\end{prop}
\begin{proof}
	This follows similarly to the proof of Proposition~\ref{prop: cluster algebra does not depend on the cut}.
\end{proof}

\begin{defn}
	In view of Proposition~\ref{prop: cluster algebra does not depend on the cut separated case}, we can defined the cluster algebra $\mcas$ associated with a separated signature $\sigma$ as the cluster algebra $\mcas(p, q)$, for any feasible cut $(p, q)$. 
\end{defn}

We are now prepared to state and prove a more precise version of Theorem \ref{thm: mixed grassmannian is a cluster algebra in the case of separated signatures}:

\begin{theorem}\label{thm: cluster structure for separated signatures}
	Assume that $d$ is odd and $n \ge 2d$. Let $\sigma$ be a separated signature with $a, b \ge d-1$. Then the cluster algebra $\mcas$ coincides (as a $\C$-algebra) with the mixed Pl\"ucker ring $R_\sigma$.
\end{theorem}
\begin{proof}%[Proof of Theorem \ref{thm: mixed grassmannian is a cluster algebra in the case of separated signatures}]
	%Let us start with the construction of $\mcas(p, q)$. Recall that for a general (admissible) signature, we require $(p, q)$ to be a valid cut, i.e., $1\le p \le q \le n$ and $\|p-q\| \ge d+1$ (cf.\ \ref{defn: valid cut in general}). In the case of a separated signature, this condition can be relaxed, as described in Definition~\ref{defn: valid cut for separated signatures}; 

	%Now similarly to the proof of , we can show that $\mcas(p, q)$ does not depend on the choice of the valid cut $(p, q)$.  
	The fact that all Weyl generators for $R_\sigma$ are cluster or frozen variables in $\mcas$ follows from Lemma~\ref{lemma: pairings are in A sigma} and Proposition \ref{prop: determinants are in A sigma}, together with the existence of a valid cut such that all the black (resp., white) vertices lie on one side of the cut (notice that $a, b\ge d-1$). 

	The result then follows from the second proof of the main theorem. %Notice that we will not be able to use the first proof of the main theorem, as Lemma \ref{lemma: a tuple for disjoint seeds} requires that $n \ge 4d-2$. 
\end{proof}




We next show that when $\sigma$ is separated (and $d$ is odd), the cluster structure  constructed above coincides with the one given by Carde in \cite{Carde}.
\begin{theorem}\label{thm: separated coincide with carde}
	Assume that $d$ is odd and $\sigma$ is a separated signature with $a, b \ge d$. Then the cluster algebra structure on $R_\sigma$ described in Theorem \ref{thm: cluster structure for separated signatures} coincides with the one described in \cite[Theorem 4.7]{Carde}.
\end{theorem}
\begin{proof}
	Without loss of generality, we may assume that $\sigma$ is black on $[1, a]$ and white on $[a+1, n]$. Take the cut $(1, a+1)$. 
	We will now define the ``zig-zag" Demazure weave $\ww_1 = \ww(1, a+1): \beta(1, a+1) \rarrow T(1, a+1)$ (here we use $T(i, i')$ to represent any nested word) using   the following recursive procedure (illustrated in the top half of the Figure \ref{fig: The zig zag weave}).



	\begin{enumerate}[wide, labelwidth=!, labelindent=0pt]	
		\item The ``zig-zag" Demazure weave $\ww(j, j+2): \beta(j, j+2) \rarrow T(j, j+2)$, where $j = \lfloor \frac{a}{2} \rfloor$. It is formed by an $H$-patch.

		For $1\le k \le \lfloor \frac{a}{2} \rfloor - 1$, we define the ``zig-zag" Demazure weave 
			\[
		\ww(k, a+1-k): \beta(k, a+1-k)\rarrow T(k, a+1-k)
		\]
		and 
		\[\ww(k+1, a+1-k): \beta(k+1, a+1-k) \rarrow T(k+1, a+1-k)
		\]
		via the following joint recursion. 

		\item To define the ``zig-zag" Demazure weave 
		\[
		\ww(k, a+1-k): \beta(k, a+1-k)\rarrow T(k, a+1-k),
		\]
		we take the
		``zig-zag" Demazure weave (see step (3))
		\[\ww(k+1, a+1-k): \beta(k+1, a+1-k) \rarrow T(k+1, a+1-k).
		\]
		We then prefix it with the word $\rho$ to get the weave
		\[\rho\ww(k+1, a+1-k): \rho \beta(k+1, a+1-k) \rarrow \rho T(k+1, a+1-k).
		\]
		Concatenating it  with any reduced Demazure weave $\rho T(k+1, a+1-k) \rarrow T(k, a+1-k)$, we obtain the Demazure weave $\ww(k, a+1-k)$. 
		(Here we used  that $\beta(k, a+1-k) = \rho \beta(k+1, a+1-k)$.)%, so the concatenation indeed gives a Demazure weave on $\beta(k+1, a+1-k)$. %Also notice that any two reduced Demazure weaves $\rho T(k+1, a+1-k) \rarrow T(k, a+1-k)$ are equivalent.
		\item To define the ``zig-zag" Demazure weave 
		\[\ww(k+1, a+1-k): \beta(k+1, a+1-k) \rarrow T(k+1, a+1-k),
		\]
		we start with the 
		``zig-zag" Demazure weave 
		\[
		\ww(k+1, a-k): \beta(k+1, a-k)\rarrow T(k+1, a-k).
		\]
		(if $k < \lfloor \frac{a}{2}\rfloor - 1$, execute step (2), with $k: = k + 1$; otherwise execute step (1)).
		We then append the word $\rho$ on the right to get the weave
		\[
		\ww(k+1, a-k)\rho: \beta(k+1, a-k)\rho \rarrow T(k+1, a-k)\rho.
		\]
		Finally, we concatenate $\ww(k+1, a-k) \rho$ with any reduced Demazure weave $T(k+1, a-k) \rho \rarrow T(k+1, a+1-k)$ to obtain the  Demazure weave  $\ww(k+1, a+1-k)$. (Here we used that $\beta(k+1, a+1-k) = \beta(k+1, a-k) \rho$.)%, so the concatenation indeed gives a Demazure weave on $\beta(k+1, a+1-k)$. %Also notice that any two reduced Demazure weaves $T(k+1, a-k) \rho\rarrow T(k+1, a+1-k)$ are equivalent.
	\end{enumerate}

	We next define the ``dual zig-zag" Demazure weave 
	\[
	\ww_2 = \ww(a+1, n+1): \beta(a+1, n+1) \rarrow T(a+1, n+1)
	\]
	as follows. We start with the ``zig-zag" Demazure weave 
	\[
	\ww(a+2, n+1): \beta(a+2, n+1) \rarrow T(a+2, n+1)
	\]
	similarly defined to the recursive procedure as above. We then prefix the word $\rho^*$ to get the weave 
	\[
	\rho^*\ww(a+2, n+1): \rho^* \beta(a+2, n+1) \rarrow \rho^*T(a+2, n+1).
	\]
	Finally, we concatenate $\rho^*\ww(a+2, n+1)$ with any reduced Demazure weave  $\rho^* T(a+2, n+1) \rarrow \rev{T(1, a+1)}$ to get the Demazure weave $\ww_2 = \ww(a+1, n+1)$. 

	It is straightforward to check that the seed obtained by amalgamating the seeds $\seed(\ww(1, a+1))$ and $\seed(\ww(a+1, n+1))$ coincides with the initial seed described in \cite{Carde}, up to a relabeling of the coordinates. In order to match their labelings, we need to label $a$ vectors and $b$ covectors (cyclically) as $a, a-1, \dots, 2, 1, b, b-1, \dots, 2, 1$, see Figure \ref{fig: The zig zag weave}.
\end{proof}	

