\subsection{Properties of cluster algebra $\mcas$}\label{sec: properties and further results}

This section establishes the ``naturality" of the cluster structures on mixed Grassmannians constructed in Section~\ref{chap: cluster structures on mixed grassmannians}. Specifically, we show that 
\begin{itemize}[wide, labelwidth=!, labelindent=0pt]
	\item all generators of $\mcas$ (the cluster and frozen variables) are multi-homogeneous elements of $\rab$;
	\item the set of these generators contains all Weyl generators;
	\item the construction recovers 
	\begin{itemize}
		\item the standard cluster structure on Grassmannians (cf.\ \cite{Scott}) when $b = 0$;
		\item cluster structures built from tensor diagrams for $d = 3$, cf.\ \cite{FominPylyavskyy};
		\item cluster structures built from mixed plabic graphs of separated signature with $a, b \ge d$, cf.\ \cite{Carde}.
	\end{itemize} 
	%\item the construction does not depend on arbitrary choices; in particular, it is invariant under the symmetries of a signature.
\end{itemize}






We have already established the last claim (for separated signatures) in Section~\ref{sec: separated signatures}. Let us tend to the case where $\sigma$ is monochromatic. In that case,  $R_\sigma = \C[\text{Gr}_{d, n}]$, the homogeneous coordinate ring of the Grassmannian $\text{Gr}_{d,n}$. The cluster structure for $ \C[\text{Gr}_{d, n}]$ was first described by Scott \cite{Scott} (cf.\ also  \cite{GSV}) and extensively studied thereafter.

\begin{theorem}\label{thm: monochromatic case}
	Assume that $\sigma$ is monochromatic. The condition $n>d^2$ in Theorem~\ref{thm: mixed grassmannian is a cluster algebra} can be relaxed to $n\ge 2d$.  The cluster structure in the cluster algebra $\mcas$ coincides with the standard cluster structure in the Pl\"ucker ring $R_\sigma$.
\end{theorem}
\begin{proof}
	The fact that $\mcas$ is well-defined follows via the same arguments as in the separated case. The main difference is that we are not able to prove that $\mcas$ contains all the Weyl generators for $R_\sigma$ simply by choosing different cuts or different Demazure weaves for $\ww_1$ and $\ww_2$. However, we will show that we can find a seed that is the same as the rectangle seed (cf.\ \cite[Section 6.7]{FominWilliams6}); as a result, we will conclude that $\mcas = R_\sigma$. 

	Let $(p, q )$ with $q = n$ be any valid cut. Let $\ww_2 = \ww(n, p+n): \beta(n, p+n)\rarrow T^+$ be the usual initial weave. Construct the Demazure weave $\tilde{\ww}_1 = \ww(p, n): \beta(p, n) \rarrow \rev{T^+}$ via the the algorithm used in Definition \ref{defn: construction of the initial weaves as concatenations of strips} for constructing $\ww_1$, modified by replacing $\str{\beta}$ by $\rev{\str{\rev{\beta}}}$. That is,  we reverse the weakly nested word, apply the Strip construction, then reverse the resulting weave (mirror image). Notice that we can get $T^{-}$ as the bottom word after this algorithm, so we need to concatenate the resulting weave with a Demazure weave $T^{-} \rarrow \rev{T^+}$ (cf.\ Lemma~\ref{lemma: complete nested words are all related by braid moves}). It is routine to verify that the seed obtained by amalgamating the seeds $\seed(\tilde{\ww}_1)$ and $\seed(\ww_2)$ matches the rectangle seed described in \cite[Section~6.7]{FominWilliams6}.
\end{proof}

We next discuss the case $d= 3$. The fact that $R_\sigma$ is a cluster algebra is proved in \cite[Theorem 8.1]{FominPylyavskyy}. We claim that the cluster structures constructed in \cite{FominPylyavskyy} coincide with ours:


\begin{theorem}
	Assume that $d = 3$, $n\ge 6$ and $\sigma$ is non-alternating. Then the cluster algebra structure on $R_\sigma$ described in Theorem \ref{thm: mixed grassmannian is a cluster algebra in the case of separated signatures} coincides with the one described in \cite[Theorem 8.1]{FominPylyavskyy}.
\end{theorem}

\begin{proof}
	Let us explicitly establish the correspondence between our framework and the ``special invariants" construction in \cite{FominPylyavskyy}. The trees $\Lambda_p$ and $\Lambda^p$ correspond to the extensors $\mcf_p^1$ and $\mcf_p^2$, respectively. The special invariants $J_p^q$, $J_{pqr}$, $J^{pqr}$ are given by $J_p^q = \mcf_p^1 \wedge \mcf_q^{2}$, $J_{pqr} = \mcf_p^1\wedge \mcf_q^1\wedge \mcf_r^1$, and $J^{pqr} = \mcf_p^2 \mixwed \mcf_q^2\mixwed \mcf_r^2$. 

	For any valid cut $(p, q)$, the initial seed $\seed_\sigma(p, q)$ coincide with the  seed in \cite[Theorem 8.1]{FominPylyavskyy} arising from the triangulation $T$ with the diagonals $(p, k)$ for $k\in [p+2, q]$ and $(q, k')$ for $k'\in [q+2, p+n-1]$. 
	This equivalence is verified using the exchange relations in Section~\ref{sec: quivers and mutations}. Notably, each of $\ww_1$ and $\ww_2$ contains only two strips. This leads to significant simplifications in the mutation dynamics, mirroring the tensor diagram model's combinatorial rules.

	We note that under the assumptions of the theorem, the condition $n > d^2 = 9$
	in Theorem~\ref{thm: mixed grassmannian is a cluster algebra} can be relaxed to $n \ge 2d = 6$. %This follows by demonstrating that our initial seed aligns with the structure in \cite{FominPylyavskyy}, as shown below.
	%This can be verified using the exchange relations in Section \ref{sec: quivers and mutations}; notice that for each of $\ww_1$ and $\ww_2$, there are only $2$ strips, so things are simplified significantly.  
\end{proof}

We next show that all generators of $\mcas$ are multi-homogeneous, cf.\ Definition~\ref{defn: multidegree}.



\begin{prop}
	All  cluster and frozen variables in $\mcas$ are multi-homogeneous. 
\end{prop}
\begin{proof}
As in Section \ref{sec: quivers and mutations}, consider the initial seed $\seed_\sigma(p, q)$ for a valid cut $(p, q)$ with $\sigma(p-1) =\sigma(q-1)$. In Proposition~\ref{prop: decoration flags of the initial weave}, we calculated all cluster and frozen variables; they are all multi-homogeneous.  In Section \ref{sec: quivers and mutations}, we derived all exchange relations for the cluster variables in $\seed_\sigma(p, q)$. Critically, both terms on the right-hand side of every exchange relation have the same multidegree. By \cite[Proposition 6.2]{FominZelevinsky4}, this ensures that mutations preserve multi-homogeneity.
\end{proof}



While our construction of $\mcas$ initially depends on the choice of a valid cut $(p, q)$, Proposition~\ref{prop: cluster algebra does not depend on the cut} demonstrates that $\mcas$ is independent of this choice. Furthermore, our construction ensures that the cluster structure is preserved under cyclic shifts of the signature. It would be interesting to explore whether the cluster structure in $\mcas$ is invariant under the reversal of $\sigma$ and/or under the duality involution $\bullet \leftrightarrow \circ$.







\subsection{Generalizations and conjectures}\label{sec: generalizations and conjectures}


We note that vectors can be viewed as $1$-extensors and covectors as $(d-1)$-extensors. It is natural to generalize the configuration space of vectors and covectors to more general configuration space of extensors of arbitrary level. 

Let $n, d\ge 3$ be integers. Let $V$ be a $d$-dimensional vector space. 

\begin{defn}
	A \emph{generalized signature} (of size $n$ and dimension $d$) is a map:
	\begin{equation}
		\sigma: \Z \rightarrow \{1, 2, \dots, d-1\}
	\end{equation}
such that $\sigma(j+n) = \sigma(j)$ for all $j\in \Z$. 
\end{defn}



\begin{defn}
	Let $\sigma$ be a generalized signature. 
	The \emph{configuration space of $\sigma$-tuples of extensors over $V$} is the ordered product
	\[
	V^\sigma = \prod_{j = 1}^n {\bigwedge}^{\sigma(j)} V.
	\]
	The invariant ring $R_\sigma$ is defined as the ring of $\slv$-invariant polynomial functions on~$V^\sigma$:
	\[
	R_\sigma = R_\sigma(V) = \C[V^\sigma]^{\slv}.
	\]
\end{defn}








The  ring $R_\sigma$ can be embedded into the Pl\"ucker ring as a subring. Explicitly, there is an inclusion:
\begin{equation}
	\iota: R_\sigma \hookrightarrow \C[\text{Gr}_{d, m}] = \C[V^m]^{\slv},
\end{equation}
where $m = \sum_{j = 1}^n \sigma(j)$.



\begin{theorem}[{\cite[Theorem 3.17]{VinbergPopov}}]
	The invariant ring $R_\sigma$ is factorial. 
\end{theorem}

By \cite[Theorem 3.5]{VinbergPopov}, the invariant ring $R_\sigma$ is finitely generated. We conjecture that the generators are of the following form:
\begin{conj}
	The invariant ring $R_\sigma$ is generated by the invariants of the form
	\[
	u_{j_1}\mixwed u_{j_2}\mixwed \cdots \mixwed u_{j_k}
	\]
	where $j_1, j_2, \dots, j_k$ are distinct elements in $[1, n]$ with $\sum_{i = 1}^k \sigma(j_i) \equiv 0 \bmod d$, and $u_{j_i}\in \bigwedge^{\sigma(j_i)}$ are coordinates. 
	%Moreover, the relations among these generators are generated by the Pl\"ucker relations. 
\end{conj} 
%One need to refine the set of generators to make it manageable. 

The notion of {$d$-admissibility} extends to  generalized signatures. 
\begin{defn}
	Let $\sigma$ be a generalized signature. We say that $\sigma$ is \emph{$d$-admissible} if there exists $j\in \Z$ such that for each $k\in [0, d-1]$, there exists $j'\ge j$ such that $\sum_{i = j}^{j'} \sigma(i) \equiv k \mod d$. 
\end{defn}





\begin{defn}
For $k\in [1, d-1]$, define the marked word
\[
\rho_k = I_k^1I_{k+1}^2\cdots I_{d-1}^{d-k}
\]
with the last character marked. 
Similarly we can define 
\[
\rho'_k = I_{k}^{d-1}I_{k-1}^{d-2}\cdots I_{1}^{d-k}
\]
with the last character marked. 
The (cyclic) marked word associated with a generalized signature $\sigma$ is 
\[
\beta_\sigma: = \prod_{j = 1}^n \rho_{\sigma(j)}.
\]
\end{defn}

\begin{defn}
	Let $\sigma$ be a generalized signature. The \emph{cyclic decorated flag moduli space} associated with $\sigma$ is defined to be the moduli space $\mfm(\beta_\sigma)$. 
\end{defn}

Analogously, define the distinguished invariant $f\in R_\sigma$
as in Definition~\ref{defn: generic point}.




\begin{conj}
	Assume that a generalized signature $\sigma$ is admissible. Then there is a $\emph{\text{SL}}(V)$-equivariant isomorphism of varieties:
	\begin{equation}
		\mfm(\beta_\sigma) \cong  V^\sigma \setminus \{f = 0\}.
	\end{equation}
	Consequently, we have 
	\begin{equation}
		\C[\mfm(\beta_\sigma)]^{\emph{\text{SL}}(V)} \cong R_\sigma[\frac{1}{f}].
	\end{equation}
\end{conj}

