\section{Combinatorics of Signatures}\label{appendix: signature}
\subsection{Signatures and affine permutations}\label{sec: signatures and affine permutations}

Let $n, d\in \Z$ be positive integers such that $n = a + b \ge d \ge 3$. 





\begin{defn}\label{defn: biased affine permutation and bounded affine permutation}
	A \emph{biased affine permutation of size $n$} is a bijection
	\begin{equation}
		\pi: \Z \rightarrow \Z
	\end{equation}
	such that $\pi(j) \ge j$ and $\pi(j + n) = \pi(j) + n$ for all $j\in \Z$. 
	The \emph{bias} of $\pi$, denoted by $\bb(\pi)$, is defined by
	\begin{equation}
		\bb(\pi) = \frac{1}{n}\sum_{j = 1}^n (\pi(j) - j).
	\end{equation}
	Notice that $\bb(\pi)\in \Z$ for any such $\pi$. 
	A biased affine permutation $\pi$ is called a \emph{bounded affine permutation} if  $\pi(j) \le j + n$ for all $j\in \Z$.
\end{defn}

\begin{remk}
	In \cite[\S2.1]{GalashinLam}, an \emph{affine permutation} is defined as a bijection $\pi: \Z\rightarrow \Z$ such that $\pi(j+n) = \pi(j) + n$ for all $j\in \Z$. A \emph{bounded affine permutation} further requires that $j \le \pi(j) \le j+n$ for all $j\in \Z$.   In contrast, \cite[Definition 1]{MadrasNeal} imposes the additional condition $\sum_{j=1}^n(\pi(j) - j) = 0$, or equivalently $\bb(\pi) = 0$m which is neither we nor \cite{GalashinLam} assume. 
\end{remk}



\begin{defn}\label{defn: biased affine permutation associated with a signature}
	Let $\sigma$ be a signature (cf.\ Definition~\ref{defn: signature}). For every $j\in \Z$, we have $\ell(\sigma, j, 0, d) < \infty$, cf.\ Definition~\ref{defn: admissible signature} and Remark~\ref{remk: ell(sigma, j, 0) < infty}. Define
	\begin{equation}
		\pi_{\sigma, d}: \Z \rightarrow \Z, \quad j \mapsto j + \ell(\sigma, j, 0, d).
	\end{equation}
	Then $\pi_{\sigma, d}$ is a biased affine permutation of size $n$. In what follows, we refer to $\pi_{\sigma, d}$ as \emph{the biased affine permutation associated with $\sigma$}. An affine permutation $\pi$ is called \emph{$d$-representable} if there exists a signature $\sigma$ such that $\pi = \pi_{\sigma, d}$. 
	Define the \emph{$d$-length of $\sigma$} to be the bias of $\pi_{\sigma, d}$:
	\begin{equation}
		\ell_d(\sigma) := \bb(\pi_{\sigma, d}) = \frac{1}{n}\sum_{j = 1}^n (\pi_{\sigma, d}(j) - j) = \frac{1}{n} \sum_{j = 1}^n \ell(\sigma, j , 0, d) \in \Z.
	\end{equation}
	The index $d$ will be dropped for $\pi_{\sigma, d}$, $\ell_d(\sigma)$, etc., if $d$ is clear from the context. 
\end{defn}




\begin{lemma}\label{lemma same pi implies same signature up to sign}
	Let $\sigma_1, \sigma_2$ be two signatures of the same size. Then $\pi_{\sigma_{1},d} = \pi_{\sigma_{2}, d}$ if and only if $\sigma_1 = \pm \sigma_2$. 
\end{lemma}

\begin{proof}	
	If $\sigma_1 = \pm \sigma_2$, then it is clear that $\pi_{\sigma_1, d} = \pi_{\sigma_2, d}$. 

	Conversely, assume that $\pi_{\sigma_{1}, d} = \pi_{\sigma_{2}, d} = \pi$. For any $j\in \Z$, we have $\pi(j) \ge j+2$ as $d \ge 2$. If $\pi(j) = j+2$, then $j$ and $j+1$ must be of different color in both $\sigma_1$ and $\sigma_2$. Otherwise $\pi(j) > j+2$, which implies that $j$ and $j+1$ are of the same color in both $\sigma_1$ and $\sigma_2$. The claim follows. 
\end{proof}


Recall from Definition~\ref{defn: admissible signature} that a signature $\sigma$ is \emph{$d$-admissible} if $\ell(\sigma, j, k, d) < \infty$  for all $j\in \Z$ and all $k\in [0, d-1]$. Equivalently, by Lemma~\ref{lemma: admissible equivalent def}, 
$\sigma$ is $d$-admissible if and only if $\ell(\sigma, j_0,k, d) < \infty$ for some $j_0\in \Z$ and all $k \in [0, d-1]$.


%Equivalently $\sigma$ is $d$-admissible if for every $j\in \Z$, $0\le k \le d-1$, we have a finite index $j'$ such that $m^j_{j'} \equiv k \mod d$; equivalently $\sigma$ is $d$-admissible if for all $j\in \Z$, $\{m_t^j\mod d\}_{t \ge j} $ forms a complete residue system mod $d$. 	


By Definition~\ref{defn: biased affine permutation associated with a signature} and Lemma~\ref{lemma same pi implies same signature up to sign}, we have an injective map
\begin{align*}
	\varphi_d:	\{\text{Signatures}\}/\{\pm 1\} &\longrightarrow \{\text{Biased affine permutations}\} \\
	\sigma & \longmapsto \pi_{\sigma, d}.
\end{align*}
We next show that the image of $\varphi_d$ consists of all $d$-representable biased affine permutations with bias $\le d$. Furthermore, the image of $d$-admissible signatures under $\varphi_d$ consists of  all $d$-representable biased affine permutation with bias~$d$ (cf.\ Theorem~\ref{thm: length and admissibility theorem} and Remark~\ref{remk: correspondence between signatures and affine permutations}).





\begin{defn}\label{defn: shifting of a signature}
	Let $\sigma$ be a signature. For $m\in \Z$, let $\tau_m(\sigma)$ be the signature (of the same type as $\sigma$) obtained from $\sigma$ by \emph{shifting to the left by $m$}, i.e., 
	\begin{equation}
		\tau_m(\sigma)(j) := \sigma(j+m), \quad j\in \Z.
	\end{equation}
	It's clear that 
	\begin{equation}
		\ell(\tau_m(\sigma), j, k, d) = \ell(\sigma, j+m, k, d).
	\end{equation}
	In particular, shifting a signature does not affect its admissibility. 
\end{defn}

\begin{defn}\label{defn: reversing of a signature}
	Let $\sigma$ be a signature. The \emph{reversal of $\sigma$}, denoted by $\rev{\sigma}$, is defined by
	\begin{equation}
		\rev{\sigma}(j) := \sigma(-j), \quad j\in \Z.
	\end{equation}
\end{defn}




\begin{lemma}\label{admissibility of reversing}
	$\sigma$ is $d$-admissible if and only if $\rev{\sigma}$ is $d$-admissible. 
\end{lemma}

\begin{proof}
	Note that $\rev{\rev{\sigma}} = \sigma$, so we only need to show that if $\sigma$ is $d$-admissible, then $\rev{\sigma}$ is $d$-admissible. Furthermore, we may assume that $\sigma$ is of type $(a, a)$ by Lemma~\ref{admissibility for signature of type a, b}.

	Assume that $\sigma$ is $d$-admissible. For $j\in \Z$ and $1\le k \le d-1$, there exists $j' \in \Z$ with $j'\ge -j + 1$ such that 
	\[
	\sum_{i = -j + 1}^{j'} \sigma(i) \equiv d - k \mod d.
	\]
	Now as $\sigma$ is of type $(a, a)$, we have 
	\[
	\sum_{i = -j+1}^{-j+tn} \sigma(i) = 0
	\]
	for any $t\in \Z$; take $t$ such that $-j + tn > j'$, then
	\[
	\sum_{i  = j' + 1 }^{-j + tn} \sigma(i) \equiv k \mod d.
	\]
	Therefore
	\[
	\sum_{i = j}^{-j'-1+tn} \rev{\sigma}(i) = \sum_{i = j - tn}^{-j'-1} \rev{\sigma}(i) = \sum_{i = j' + 1}^{-j + tn}\sigma(i) \equiv k \mod d.
	\]
	Note that $-j'-1+tn \ge j$, implying that $\rev{\sigma}$ is $d$-admissible. 
\end{proof}

\begin{lemma}\label{shifting/reversing preseves length}
	Let $\sigma$ be a signature. Then 
	\[
	\pi_{\rev{\sigma}}(j) = -\pi^{-1}_{\sigma}(-j) \quad \text{and} \quad \pi_{\tau_m(\sigma)}(j) = \pi_\sigma(j+m) - m
	\]
	for $j\in \Z$. As a consequence, $\ell_d(\sigma) = \ell_d({\rev{\sigma}})$ and $\ell_d(\sigma) = \ell_d({\tau_m(\sigma)})$ for all $m\in \Z$. In other words, shifts and reversals preserve the length of a signature. 
\end{lemma}

\begin{proof}
	For $1\le j\le n$, let $g_j = \pi_\sigma(j)$. Then 
	\[
	\pi_{\rev{\sigma}}(-g_j) = -g_j + \ell({\rev{\sigma}},{-g_j},0, d) = -g_j + (g_j - j) = -j.
	\]
	In other words, we have 
	\begin{equation}\label{pi of sigma and sigma reverse}
		\pi_{\rev{\sigma}}(j) = -\pi^{-1}_{\sigma}(-j), \quad j\in \Z.
	\end{equation}
	So 
	\[
	\ell_d({\rev{\sigma}}) = \frac{1}{n}\sum_{j=1}^n \left(\pi_{\rev{\sigma}}(-g_j) - (-g_j)\right) = \frac{1}{n}\sum_{j  = 1}^n (g_j - j) = \frac{1}{n}\sum_{j= 1}^n (\pi_\sigma(j) - j) = \ell_d(\sigma).
	\]
	For shifting, we have, for $j\in \Z$:
	\begin{equation}\label{pi of sigma and sigma shifts}
		\pi_{\tau_m(\sigma)}(j)  = j + \ell(\tau_m(\sigma),j,0, d) = j + \ell(\sigma,{j+m},0, d) = \pi_\sigma(j+m) - m.
	\end{equation}
	Hence 
	\[
	\ell_d({\tau_m(\sigma)}) = \frac{1}{n}\sum_{j=1}^n (\pi_{\tau_m(\sigma)}(j) - j) = \frac{1}{n}\sum_{j=1}^n (\pi_\sigma(j+m) - (j+m)) = \ell_d(\sigma).\qedhere
	\]

\end{proof}




\begin{defn}
	Let $\sigma$ be a signature. Then $j\in \Z$ is called a \emph{$d$-fixed point of $\sigma$} (or a \emph{fixed point of $\pi_{\sigma, d}$})  if 
	\begin{equation}
		\pi_{\sigma, d}(j) \equiv j \mod n.
	\end{equation}
	We use $\fix(\sigma, d)$ (or $\fix(\pi_{\sigma, d}))$ to denote the number of $d$-fixed points of $\sigma$ (or the number of fixed points of $\pi_{\sigma, d}$) in $\Z/n\Z$. 
\end{defn}


\begin{example}
	Let $n = 5, a = 4, b = 1, \sigma = [\bullet\, \bullet\, \bullet\, \bullet\, \circ]$ and $d = 6$. Then we have $(\pi_\sigma(j) - j)_{1\le j\le 5} = (8, 8, 10, 2, 2)$. Hence $\fix(\sigma) = 1$ and $j = 3$ is a fixed point of $\sigma$. Note that $\pi_\sigma(3) = 3 + 2n$.
\end{example}



\begin{lemma}\label{lemma: fixed points change color equivalent to a = b and must of length n}
	Let $\sigma$ be a signature of type $(a, b)$ and $j\in \Z$ a fixed point of $\pi_{\sigma}$. Then $\sigma(j-1)\neq \sigma(j)$ if and only if $a = b$. Moreover, if these conditions hold, then $\pi_\sigma(j) = j + n$.
\end{lemma}

\begin{proof}
	As $j$ is a fixed point of $\sigma$, we may assume that $\pi_\sigma(j) = j + sn$ for some $s\in \Z$ and $s\ge 1$. Without loss of generality, assume that $j$ is black. 

	Consider the sequence
	\[
	m_t = \sum_{i = j}^t \sigma(i), \text{ for } t \ge j.
	\]
	We have $m_j = 1$, $m_{j+n-1} = a - b$, note that $0< m_t < d$ for $j \le t < j + sn -1$ as $j + sn -1$ is the first time we have  $m_t \equiv 0 \mod d$. 

	Now if $\sigma(j-1) \neq \sigma(j)$, then $j-1$ is white, so $\sigma(j-sn-1) = \sigma(j-1) = -1$, hence $m_{j+sn-1} = m_{j+sn-2} + \sigma(j+sn-1) = m_{j+sn-2} - 1$, therefore $0\le m_{j+sn-1} <d-1$, as we know $m_{j+sn-1} \equiv 0 \mod d$, we must have $m_{j+sn-1} = 0$. Therefore $m_{j+sn-1} = s(a-b) = 0$, hence $a = b$. Moreover, as we have $m_{j+n-1} = a-b = 0$, we conclude that $s = 1$ and $\pi_\sigma(j) = j+n$.

	Conversely, if $a = b$, then we have $m_{j+n-1} = a -b = 0$. So $s =1$ and $\pi_\sigma(j) = j+n$. Then $m_{j+n-1} = 0$ implies $m_{j+n-2} = 1$, hence $\sigma(j-1) = -1$.\qedhere
\end{proof}


\begin{prop}
	For any signature $\sigma$ and any $m\in \Z$, we have $\fix(\sigma) = \fix(\tau_m(\sigma)) = \fix(\overline{\sigma})$.
\end{prop}

\begin{proof}
	We have 
	\[
	\pi_{\tau_m(\sigma)}(j)  =  \pi_\sigma(j+m) - m \quad \text{and} \quad \pi_{\overline{\sigma}}(j) = -\pi^{-1}_{\sigma}(-j), \text{ for } j\in \Z.
	\]
	So $j$ is a fixed point of $\sigma$ if and only if $j -m$ is a fixed points of $\tau_m(\sigma)$ if and only if $-j +1$ is a fixed point of $\overline{\sigma}$. Hence $\fix(\sigma) = \fix(\tau_m(\sigma)) = \fix(\overline{\sigma})$.
\end{proof}



\begin{prop}\label{the number of fixed points is at most 2 for type (a, a)}
	Let $\sigma$ be a signature of type $(a, a)$. Then any two fixed points of $\sigma$ must be of different colors. In particular,  $\fix(\sigma) \le 2$. 
\end{prop}
\begin{proof}
	Let $i < j$ be two fixed points of $\sigma$ such that $\sigma(i) = \sigma(j)$.  We may assume that $|j - i| < n$ by periodicity of $\sigma$.


	Without loss of generality, we may assume that $\sigma(i) = \sigma(j) = 1$. Then $\sigma(i-1) = -1$ and $\sigma(j-1) = -1$ by Lemma~\ref{lemma: fixed points change color equivalent to a = b and must of length n}. Let $x_1$ (resp. $y_1$) denote the number of blacks (resp. white) between $i$ and $j-1$, and let $x_2$ (resp., $y_2$) be the number of black (resp., white) vertices between $j$ and $i-1 + n$. 
	Consider the following sequence 
	\[
	m_t = \sum_{c = i}^{t} \sigma(c), \text{ for } t\ge i.
	\]
	We have $m_i = 1$, so $m_{j-1} > 0$, which implies $x_1 - y_1 > 0$. Similarly, $x_2 - y_2 >0$. However, as $\sigma$ is of type $(a, a)$, we must have $x_1 + x_2 = y_1 + y_2$, a contradiction.
\end{proof}


\begin{example}
	Let $\sigma_1 = [\bullet\, \bullet\, \circ\, \circ\, \bullet\, \bullet\, \circ\, \circ]$, $\sigma_2 = [\bullet\, \bullet\, \circ\, \bullet\, \circ\, \bullet\, \circ\, \circ]$ and $\sigma_3 = [\bullet, \bullet, \circ, \circ]$. Each of these signatures is $3$-admissible but not $4$-admissible. Furthermore,  $\fix(\sigma_1, 3) = \fix(\sigma_1, 4) = 0, \fix(\sigma_2, 3) =\fix(\sigma_2, 4) = 1, \fix(\sigma_3, 3)= \fix(\sigma_3, 4) = 2$.  
\end{example}



\begin{example}
	%We call $\sigma$ \emph{monochromatic} if $\sigma$ is a signature of type $(n, 0)$ or $(0, n)$. 
	If $\sigma$ is monochromatic, then
	\begin{equation}
		\fix(\sigma, d) = \begin{cases}
			n, & \text{if} \  n \mid d\\
			0, & \text{if}\   n \nmid d
		\end{cases}
	\end{equation}
	If $\sigma$ is a signature of type $(n-1, 1)$ or $(1, n-1)$, then
	\begin{equation}
		\fix(\sigma, d) = \begin{cases}
			n, & \text{if} \ d = 0\\
			n - 4, & \text{if} \  d \ge 1, n \ge 4 \text{ and } n-2 \mid d\\
			0, & \text{otherwise}.
		\end{cases}
	\end{equation}
\end{example}







\begin{prop}\label{admissibility for switching an adjacent pair of different colors}
	Let $\sigma$ be a non-monochromatic $d$-admissible signature.  Let ${(i, i+1)}$ be such that $\sigma(i)\sigma(i+1) = -1$. Let $\sigma'$ be a signature obtained from $\sigma$ by switching the colors of $i$ and $i+1$, i.e., $\sigma'(i) = \sigma(i+1)$, $\sigma'(i+1) = \sigma(i)$ and $\sigma'(j) = \sigma(j)$ for $j\not\equiv i, i+1 \mod n$. Then the following are equivalent:
	\begin{enumerate}[wide, labelwidth=!, labelindent=0pt]
		\item[\rm\textbf{(a)}] $\sigma'$ is $d$-admissible;
		\item[\rm\textbf{(b)}] $i+1$ is not a fixed point of $\pi_{\sigma, d}$;
		\item[\rm\textbf{(c)}] $\ell_d({\sigma}) = \ell_d({\sigma'})$.
	\end{enumerate}
\end{prop}

\begin{proof}
	Without loss of generality, we may assume that $\sigma(i) = 1$ and $\sigma(i+1) = -1$. Let $j\in \Z$ such that $\pi_\sigma(j) = i + 1 $ and $j'\in \Z$ such that $\pi_{\sigma'}(j') = i + 1$. Then we have $\pi_{\sigma}(m) = \pi_{\sigma'}(m)$ for all $m\in \Z$ such that $m\notin \{i+1, j, j'\} \mod n$. 
	\begin{itemize}[wide, labelwidth=!, labelindent=0pt]
	\item[\textbf{(a)} $\Rightarrow$ \textbf{(b)}:]
	Assume that $\sigma'$ is $d$-admissible. If $i+1$ is a fixed point of $\pi_{\sigma}$, then $\sigma$ is of type $(a, a)$ and $\pi_\sigma(i+1) = i+1 + n$ by Lemma~\ref{lemma: fixed points change color equivalent to a = b and must of length n}. Consider the sequence 	
	\[
	m_t = \sum_{k = i+2}^{t} \sigma'(k), \ t\ge i+2.
	\]
	We claim that $m_{t} \not\equiv 1 \bmod n$ for $i+2 \le t < i+n -1$.  Otherwise, assume that $m_t \equiv 1 \bmod n$ for some $i+2 \le t < i+n-1$. Then $\pi_{\sigma}(i+1) = t + 1< i + 1 +n$, a contradiction. Notice that $m_{i+n-1} = m_{i+n+1} = 0$ and $m_{i+n} = -1$. We conclude that $m_t \not\equiv 1 \mod n$ for all $t\ge i + 2$ (as $\sigma$ is of type $(a, a)$). This implies that $\ell({\sigma'},{i+2},1, d) = \infty$, contradicting the admissibility of  $\sigma'$. Therefore $i+1$ is not a fixed point of $\pi_{\sigma}$. 

	\item[\textbf{(b)} $\Rightarrow$ \textbf{(c)}:]
	Assume that $i+1$ is not a fixed point of $\pi_{\sigma}$. Since $\sigma$ is admissible, the same argument as above implies that $i+1$ is not a fixed point of $\pi_{\sigma'}$, thus $j \not\equiv i+1\mod n$ and $j' \not\equiv i+1 \mod n$. Therefore
	\begin{equation*}
		\begin{split}
			n(\ell({\sigma}) - \ell({\sigma'})) &= (\pi_{\sigma}(i+1) - \pi_{\sigma'}(i+1)) +(\pi_{\sigma}(j) - \pi_{\sigma'}(j)) +(\pi_{\sigma}(j') - \pi_{\sigma'}(j'))\\
			&= \left(\left(1+\ell(\sigma,{i+2},{1}, d)\right) -\left(1+\ell(\sigma,{i+2},{d-1}, d)\right)\right) \\
			&\quad + \left(-\ell(\sigma,{i+2},{1}, d) - 1\right) + \left(\ell(\sigma,{i+2},{d-1}, d) + 1\right) =0.
		\end{split}
	\end{equation*}

	\item[\textbf{(c)} $\Rightarrow$ \textbf{(a)}:]
	Assume that $\ell(\sigma) = \ell({\sigma'})$. Suppose that $\sigma'$ is not admissible. Then there exist some $r\in \Z$ and $1\le k \le d-1$ such that $\ell({\sigma'},r,k, d) = \infty$. Consider $x = r + \ell(\sigma,r,k, d)-1$. Suppose that $x \not\equiv i \mod n$, then $\ell({\sigma'},r,k, d) \le \ell(\sigma,r,k, d) < \infty$, a contradiction. Hence $x \equiv i \mod n$. We claim that $i+1$ is a fixed point of $\pi_{\sigma}$. Otherwise, we will have $\ell({\sigma'},{i+2},1, d) < \infty$. As a result,  $\ell({\sigma'},r,k, d) \le \ell(\sigma,r,k, d) -1 + 2 + \ell({\sigma'},{i+2},1, d) < \infty$, a contradiction. 

	Now as $i+1$ is a fixed point of $\pi_{\sigma}$ and is not a fixed point of $\pi_{\sigma'}$, we conclude that $j\equiv i+1$ and $j' \not\equiv i+1$. Therefore 
	\begin{equation*}
		\begin{split}
			n(\ell({\sigma}) - \ell({\sigma'})) &= (\pi_{\sigma}(i+1) - \pi_{\sigma'}(i+1)) +(\pi_{\sigma}(j') - \pi_{\sigma'}(j'))\\
			&= \left(\left(1+\ell(\sigma,{i+2},{1}, d)\right) -\left(1+\ell(\sigma,{i+2},{d-1}, d)\right)\right) \\
			&+ \left(\ell(\sigma,{i+2},{d-1}, d) + 1\right)= 1 + \ell(\sigma,{i+2},1,d) =n.
		\end{split}
	\end{equation*}
	So $\ell({\sigma}) = \ell({\sigma'}) + 1$, a contradiction. \qedhere
\end{itemize}
\end{proof}


