\begin{prop}\label{length and admissibility of signature of type a b}
	Let $\sigma$ be a signature of type $(a, b)$ with $a \neq b$. Then $\sigma$ is $d$-admissible and $\ell_d({\sigma}) = d$. 
\end{prop}
\begin{proof}		
	The first claim was established in Lemma~\ref{admissibility for signature of type a, b}. Note that any two of such ($d$-admissible) signatures are related to each other by a sequence of switches of adjacent pairs. Hence $\ell_d(\sigma)$ is constant (for any signature $\sigma$ of type $(a, b)$ with $a \neq b$) by Proposition~\ref{admissibility for switching an adjacent pair of different colors}. Consider the separated signature $\sigma$ with $\sigma(1) = 1$ and $\sigma(n) = -1$ (cf.\ Definition~\ref{defn: separated signature}). Let us calculate $\ell(\sigma)$. 

	Without loss of generality, we may assume that $a> b$. Then 
	\begin{equation}
		\pi_{\sigma}(j) - j= \begin{cases}
			\left(\left[ \frac{d-a-2+j}{a-b} \right] + 1\right)(n-a+b) + d, &\text{if}\ 1\le j \le a - b;\\
			2(a + 1 - j), & \text{if}\  a-b + 1 \le j \le a;\\
			2(a + b + 1 -j), & \text{if} \ a+1 \le j \le a+b = n.
		\end{cases} 
	\end{equation}
	Hence
	\begin{equation*}
		\begin{split}
			\ell(\sigma) &= \frac{1}{n}\sum_{j = 1}^n (\pi_{\sigma}(j) - j) \\
			&= \frac{1}{n}\left(\sum_{j = 1}^{a-b}\left[ \frac{d-a-2+j}{a-b} \right] (n-a+b) + (n-a+b+d)(a-b) + \sum_{j = 1}^b 4j\right).
		\end{split}
	\end{equation*}
	Note that if we write $d-a-2 = u(a-b) + v$ with $0 \le v < a-b$, then 
	\[
	\left[ \frac{d-a-2+j}{a-b} \right] = \left[ \frac{u(a-b)+v+j}{a-b} \right] = u + \left[ \frac{v+j}{a-b} \right].
	\]
	Therefore
	\begin{equation}
		\begin{split}
			\ell(\sigma) &= \frac{1}{n}\sum_{j = 1}^n (\pi_{\sigma}(j) - j)\\
			& = \frac{1}{n}\left(\sum_{j = 1}^{a-b}\left[ \frac{d-a-2+j}{a-b} \right] (n-a+b) + (n-a+b+d)(a-b) + \sum_{j = 1}^b 4j\right)\\
			&= \frac{1}{n}\left(\sum_{j = 1}^{a-b}(u + \left[ \frac{v+j}{a-b} \right]) (n-a+b) + (n-a+b+d)(a-b) + 2b(b+1)\right)\\
			&= \frac{1}{n}\left((u(a-b) +v+1) (n-a+b) + (n-a+b+d)(a-b) + 2b(b+1)\right)\\
			& = \frac{1}{n}\left((d - a-1)(2b) + (2b+d)(a-b) + 2b(b+1)\right)= \frac{(a+b)d}{n} = d.\qedhere
		\end{split}
	\end{equation}
\end{proof}


%Recall from Definition~\ref{defn: separated signature} that a signature $\sigma$ is separated if it contains $a$ consecutive black vertices followed by $b$ consecutive white vertices. 
\begin{comment}
\begin{defn}\label{def: separated signature}
	We call $\sigma$ \emph{separated (at $m$)} if there exists $m\in \Z$ such that $\sigma(j+m) = 1$ for $1\le j\le a$ and $\sigma(j+m) = -1$ for $a+1 \le j \le a + b = n$. Equivalently, $\sigma$ is separated if there are only two pairs of adjacent opposite colors mod $n$. 
\end{defn}
\end{comment}


\begin{remk}\label{remk: admissiblility for separated sigma}
	Let $\sigma$ be a separated signature of type $(a, b)$. Then $\sigma$ is $d$-admissible if and only if $a \neq b$ or $ a = b \ge d- 1$. 
\end{remk}



\begin{prop}\label{length and admissibility of type (a, a)}
	Let $\sigma$ be a signature of type $(a, a)$. Then $\ell_d({\sigma}) \le d$. Moreover, $\sigma$ is $d$-admissible if and only if $\ell_d({\sigma}) = d$.
\end{prop}
\begin{proof}
	We prove the statement by induction on $a$. Recall that we require $n\ge d \ge 3$, hence $a\ge 2$. When $a = 2$, then either $\sigma = \sigma_1  =  [\bullet\, \bullet\, \circ\ \circ]$ or $\sigma = \sigma_2=  [\bullet\, \circ\, \bullet\ \circ]$; and $\ell_d({\sigma_1}) = 3, \ell_d(\sigma_2) = 2$ for any $d\ge 3$. Notice that $\sigma_2$ is not $d$-admissible for any $d\ge 3$ and $\sigma_1$ is $d$-admissible only if $d = 3$. 

	Now let $\sigma$ be a signature of type $(a, a)$ and assume that the statement is true for signatures of type $(a-1,a-1)$.  
	Consider pairs $(i, i+1)$ with $\sigma(i) = -\sigma(i+1)$. If there are only two such pairs mod $n$, then $\sigma$ is separated. As shifting preserves admissibility and length by Lemma~\ref{shifting/reversing preseves length}, we may assume that $\sigma$ is separated. Note that $\sigma$ is admissible if and only if $a \ge d- 1$ (cf.\ Remark~\ref{remk: admissiblility for separated sigma}). Now let us calculate $\ell(\sigma)$. Suppose that $a < d -1$, then
	\[
	\ell(\sigma) = \frac{1}{n}\sum_{j=1}^a 4j = \frac{2a(a+1)}{n} = a+1 < d.
	\]
	Suppose that $a \ge d - 1$, then
	\[
	\ell(\sigma) = \frac{1}{n}\left(2d(a-d+1) + \sum_{j=1}^{d-1} 4j\right) = \frac{1}{n}\left(2ad - 2d^2 + 2d + 2d(d-1)\right) = d.
	\]
	Therefore we always have $\ell(\sigma) \le d$. Moreover,  $\ell(\sigma) = d$ if and only if $a \ge d - 1$ if and only if $\sigma$ is admissible.

	Now let us assume that there are at least three pairs of $(i, i+1)$ (mod $n$) with $\sigma(i) = -\sigma(i+1)$. Then there exists one such pair such that $i+1$ is not a fixed point as we can have at most two fixed points by Proposition~\ref{the number of fixed points is at most 2 for type (a, a)}. 

	First we show that if $\sigma$ is admissible, then $\ell(\sigma) = d$. As shifting preserves admissibility and length by Lemma~\ref{shifting/reversing preseves length}, we may assume that $i = 2a - 1$. Without loss of generality, we also assume that $\sigma(i) = 1$ and $\sigma(i+1) = -1$. Now consider the signature $\hat{\sigma}$ of type $(a-1, a-1)$ define by $\hat{\sigma}(j) = \sigma(j)$ for $1\le j \le 2a-2$. In other words, $\hat{\sigma}$ is obtained from $\sigma$ by removing $i$ and $i+1$. Let us show that $\hat{\sigma}$ is admissible. 
	Similar to the proof of Proposition~\ref{admissibility for switching an adjacent pair of different colors}, (c) $\Rightarrow$ (a), if $\hat{\sigma}$ is not admissible, then $i+1$ will be a fixed point of $\sigma$, a contradiction. Now $\hat{\sigma}$ is admissible implies $\ell({\hat{\sigma}}) = d$ by induction hypotheses. 

	As $\sigma$ is admissible, so is $\rev{\sigma}$ by Lemma~\ref{admissibility of reversing}. For $0\le k \le d-1$, let $j_k =2a - \ell(\rev{\sigma},1,k, d)$. Then $j_1 = 2a -1 = i$ since $\sigma(i) = 1$;  and $i+1$ is not a fixed point of $\sigma$ implies that $i$ is not a fixed point of $\rev{\sigma}$. Hence $\ell(\rev{\sigma},1,0, d) < 2a$, and therefore $1\le j_k \le 2a -2$ for $k\neq 1$. Now let $1\le j \le 2a-2$ such that $j \neq j_k$ for any $0\le k \le d-1$. Then we must have $\pi_{\hat{\sigma}}(j) = \pi_\sigma(j)$. Notice that $\pi_{\hat{\sigma}}(j_k) = \pi_\sigma(j_k) - 2$ for $1< k \le d -1$, $\pi_\sigma(j_1) - j_1 = \pi_\sigma(i) - i = 2$, and $\pi_\sigma(j_0) - \pi_{\hat{\sigma}}(j_0) = 1 - \ell(\sigma,{1},1, d) $. Lastly, we have $\pi_{\sigma}(i+1) - (i+1) = 1 + \ell(\sigma,{1},1, d)$. Put all these together, we get
	\begin{equation*}
		\begin{split}
			2a\ell(\sigma) - 2(a-1)\ell({\hat{\sigma}}) & = \sum_{0\le k \le d-1, \ k \neq 1} \bigg( \left( \pi_\sigma(j_k) - \pi_{\hat{\sigma}}(j_k)\right) \\
			&\quad\quad \quad \quad \quad\quad+ (\pi_\sigma(i) - i) + (\pi_\sigma(i+1) - (i+1))\bigg)\\
			& = 2(d-2) + (1- \ell(\sigma,1,1, d)) + 2 + (1 + \ell(\sigma,1,1, d)) = 2d.
		\end{split}
	\end{equation*}
	Since $\ell({\hat{\sigma}}) = d$, we conclude that 
	\[
	\ell(\sigma) = \frac{2(a-1)\ell({\hat{\sigma}})  + 2d}{2a} = \frac{2(a-1)d + 2d}{2a} = d,
	\]
	which completes the proof that if $\sigma$ is admissible, then $\ell(\sigma) = d$. 

	Now we show that if $\sigma$ is not admissible, then $\ell(\sigma) < d$. We follow the  same procedure as above,  it is clear that $\hat{\sigma}$ is not admissible, so $\ell({\hat{\sigma}}) < d$. As $\sigma'$ is not admissible, some of the $j_k$'s might not be defined (as $\ell(\rev{\sigma}, 1, k, d)$ can be $\infty$), and whenever that happens, the term $\left( \pi_\sigma(j_k) - \pi_{\hat{\sigma}}(j_k)\right)$ will not appear in $2a\ell(\sigma) - 2(a-1)\ell({\hat{\sigma}})$, as a result, we have an inequality:
	\begin{equation*}
		\begin{split}
			2a\ell(\sigma) - 2(a-1)\ell({\hat{\sigma}}) & \le \sum_{0\le k \le d-1, \ k \neq 1} \bigg(\left( \pi_\sigma(j_k) - \pi_{\hat{\sigma}}(j_k)\right) \\
			&\quad \quad \quad\quad\quad \quad\quad+ (\pi_\sigma(i) - i) + (\pi_\sigma(i+1) - (i+1))\bigg)= 2d.
		\end{split}
	\end{equation*}
	Therefore
	\[
	\ell(\sigma) \le \frac{2(a-1)\ell({\hat{\sigma}})  + 2d}{2a} < \frac{2(a-1)d + 2d}{2a} = d.
	\]
	This completes the proof that if $\sigma$ is not admissible, then $\ell(\sigma) < d$. 	
\end{proof}




\begin{theorem}\label{thm: length and admissibility theorem}
	For any signature $\sigma$, we have $\ell_d(\sigma) \le d$.  Moreover, $\sigma$ is $d$-admissible if and only if $\ell_d({\sigma}) = d$.
\end{theorem}

\begin{proof}
	This follows from Proposition~\ref{length and admissibility of signature of type a b} and Proposition~\ref{length and admissibility of type (a, a)}.
\end{proof}


\begin{cor}\label{remk: correspondence between signatures and affine permutations}
	%Let $\pi$ be a biased affine permutation. We call it \emph{$d$-representable} if there exists a signature $\sigma$ such that $\pi = \pi_{\sigma, d}$. 
	The map $\sigma \mapsto \pi_{\sigma, d}$ gives a bijection
\[
		\{\text{signatures}\}/\{\pm 1\} \longleftrightarrow \{\text{$d$-representable biased affine permutations of bias} \le d\}.
\]
	This bijection restricts to a bijection 
	\[
	\{\text{$d$-admissible signatures}\}/\{\pm 1\} \longleftrightarrow \{\text{$d$-representable affine permutations of bias } d\}.
	\]
\end{cor}
\begin{proof}
	Combine Theorem~\ref{thm: length and admissibility theorem} and Lemma~\ref{lemma same pi implies same signature up to sign}.
\end{proof}

In Section~\ref{subsec: adundant signatures}, we will provide a counterpart of Corollary \ref{remk: correspondence between signatures and affine permutations} for bounded affine permutations.




\begin{cor}\label{Not admissible when d > a + 1}
	Let $\sigma$ be a signature of type $(a, a)$ with  $a < d-1$. Then $\sigma$ is not $d$-admissible.
\end{cor}
\begin{proof}
	Let $1 \le j \le n = 2a$, define $g(j) = \pi_{\sigma}(j)$, if $j$ is not a fixed point, then 
	\[
	\sum_{i = g(j)}^{j-1 +n} \sigma(i) = - \sum_{i = j}^{g(j) -1}\sigma(i) = 0,
	\]
	hence
	\[
	(\pi_\sigma(j) - j ) + (\pi_\sigma(g(j))-g(j)) = \pi_\sigma(g(j)) - j \le n.
	\]
	If $j$ is a fixed point, then $g(j) = j + n$ by Lemma~\ref{lemma: fixed points change color equivalent to a = b and must of length n}, hence
	\[
	(\pi_\sigma(j) - j ) + (\pi_\sigma(g(j))-g(j)) = 2n.
	\]
	Note that if $j \neq j'$, then $g(j) \not\equiv g(j') \mod n$, so we have 
	\begin{align*}
		2\ell(\sigma) &= \frac{1}{n}\sum_{j=1}^n (\pi_\sigma(j) - j ) + (\pi_\sigma(g(j))-g(j)) \\
		&\le  \frac{1}{n}\left(2n\fix(\sigma) + n(n-\fix(\sigma))\right) = n + \fix(\sigma).
	\end{align*} 
	Hence if $a < d- 1$, then $n + 2 = 2a + 2 < 2d$, so
	\begin{equation}
		\ell(\sigma) \le \frac{n + \fix(\sigma)}{2} \le \frac{n + 2}{2} < d,
	\end{equation}
	here we used the fact that $\fix(\sigma) \le 2$ by Proposition~\ref{the number of fixed points is at most 2 for type (a, a)}. Finally by Theorem~\ref{thm: length and admissibility theorem} we conclude that $\sigma$ is not $d$-admissible as $\ell(\sigma) < d$.
\end{proof}




\begin{cor}\label{cor: admissible = separated when d = a+ 1}
	Let $\sigma$ be a signature of type $(a, a)$ with $a = d - 1$. Then $\sigma$ is $d$-admissible if and only if $\sigma$ is separated. 
\end{cor}
\begin{proof}
	Assume that $\sigma$ is separated. Then $\sigma$ is $d$-admissible by Remark~\ref{remk: admissiblility for separated sigma}.

	Assume that $\sigma$ is $d$-admissible. If there exists a pair $(i, i+1)$ of opposite colors such that $i+1$ is not a fixed point of $\sigma$, then the signature $\hat{\sigma}$ constructed as in the proof of Proposition~\ref{length and admissibility of type (a, a)} (by removing $i$ and $i+1$) is also $d$-admissible. Notice that $\hat{\sigma}$ is of type $(a-1, a-1)$ and $a - 1  = d - 2 < d - 1$. Hence $\hat{\sigma}$  is not $d$-admissible by Corollary~\ref{Not admissible when d > a + 1}, a contradiction. This implies that if $i$ and $i+1$ are of different colors, then $i+1$ is a fixed point of $\sigma$. By Proposition~\ref{the number of fixed points is at most 2 for type (a, a)}, there are at most $2$ fixed points of $\sigma$ (mod $n$). Therefore, there are at most two pairs of adjacent opposite colors (mod $n$), which implies that $\sigma$ is separated. 
\end{proof}



\subsection{Abundant signatures}\label{subsec: adundant signatures}

In this section, we study the counterparts of bounded affine permutations under the correspondence described in Remark~\ref{remk: correspondence between signatures and affine permutations}. %namely, {$d$-bounded signatures} (cf.\ Definition~\ref{definition of abundant }) and {$d$-abundant signatures} (cf.\ Definition~\ref{def: abundant}).

\begin{defn}\label{definition of abundant }
	A signature $\sigma$  of size $n$ is called \emph{$d$-bounded} if $\ell(\sigma,j,0, d) \le n$ for all $j\in \Z$. Equivalently, $\sigma$ is $d$-bounded if $\pi_{\sigma, d}$ is a bounded affine permutation, cf.\ Definition \ref{defn: biased affine permutation and bounded affine permutation}.
\end{defn}


\begin{prop}\label{shifting/reversing preseves boundness}
	Let $\sigma$ be a signature. The following are equivalent:
	\begin{itemize}[wide, labelwidth=!, labelindent=0pt]
		\item $\sigma$ is $d$-bounded;
		\item $\rev{\sigma}$ is $d$-bounded;
		\item $\tau_m(\sigma)$ is  $d$-bounded for some $m\in \Z$;
		\item $\tau_m(\sigma)$ is  $d$-bounded for every $m\in \Z$.
	\end{itemize}
\end{prop}
\begin{proof}
	For any $m\in \Z$, we have
	\[
	\pi_{\tau_m(\sigma)}(j) - j  =  \pi_\sigma(j+m) - (j+m),  \text{ for } j\in \Z.
	\]
	Hence $\sigma$ is bounded if and only if ${\tau_m(\sigma)}$ is $d$-bounded.

	Similarly, we have 
	\[
	\pi_{\rev{\sigma}}(j) = -\pi^{-1}_{\sigma}(-j), \text{ for } j\in \Z.
	\]
	Assume that $\sigma$ is $d$-bounded. Then for any $j\in \Z$, we have
	\[
	-j = \pi_{\sigma}(\pi^{-1}_{\sigma}(-j)) \le \pi^{-1}_{\sigma}(-j) + n.
	\]
	Hence for all $j\in \Z$, we have
	\[
	\pi_{\rev{\sigma}}(j) = -\pi^{-1}_{\sigma}(-j) \le j + n.
	\]
	Therefore ${\rev{\sigma}}$ is $d$-bounded. The converse follows from the fact that $\rev{\rev{\sigma}} = \sigma$. 
\end{proof}


\begin{lemma}\label{lemma: type (a,a) is bounded}
	Any signature $\sigma$ of type $(a, a)$ is $d$-bounded. 
\end{lemma}
\begin{proof}
	For any $j\in \Z$, we have 
	\begin{equation}
		\sum_{i = j}^{j+n-1} \sigma(i) = a - a = 0.
	\end{equation}
	Hence $\ell(\sigma,j,0,d) \le n$, so $\sigma$ is bounded. 
\end{proof}


\begin{defn}\label{def: abundant}
	A signature $\sigma$ is called \emph{$d$-abundant} if $\ell(\sigma,j,k, d) \le n$ for all $j\in \Z$ and $0\le k \le d-1$. 
\end{defn}

Note that if $\sigma$ is $d$-abundant, then it is both $d$-admissible and $d$-bounded. The converse is also true:


\begin{prop}\label{proposition abundant  = bounded + admissible}
	A signature $\sigma$ is $d$-abundant  if and only if $\sigma$ is $d$-bounded and $d$-admissible. 
\end{prop}

In other words, $\ell(\sigma, j, 0, d) \le n$ and $\ell(\sigma, j, k, d) < \infty$ for all $j\in \Z$ and $1\le k \le d -1$ forces $\ell(\sigma, j, k, d) \le n$ for $j\in \Z$, $0\le k \le d-1$. 

\begin{proof}
	As mentioned above, if $\sigma$ is abundant, then it is bounded and admissible by definition. 

	Now assume that $\sigma$ is bounded and admissible. Then $\ell(\sigma,j,k, d) < \infty$ and $\ell(\sigma,j,0, d) \le n$ for all $j\in \Z$ and $1\le k \le d-1$.
	Consider the set \[
	S = \{\ell(\sigma,{j},k, d)\}_{1\le j \le n, \, 0\le k \le d-1}.
	\]
	It is a finite set of integers, so $\max{S}$ exists. Take $j\in \Z,\  0\le k \le d-1$ such that $\ell(\sigma,{j},k, d) = \max{S}$. 

	Suppose that $\sigma$ is not abundant. Then $\ell(\sigma,{j},k, d) = \max{S} > n$. Since $\ell(\sigma,j,0, d) \le n$ by assumption, we must have $k \neq 0$. Without loss of generality, we may assume that $\sigma(j) = 1$. If $\sigma(j-1) = 1$, then
	\[
	\ell(\sigma,{j-1},{k+1}, d) =	\ell(\sigma,{j},k, d) + 1 > \max{S},
	\]
	a contradiction. If $\sigma(j-1) = -1$, then 
	\[
	\ell(\sigma,{j-1},{k-1}, d) =	\ell(\sigma,{j},k, d) +1 > \max{S},
	\]
	a contradiction. 
\end{proof}


\begin{cor}\label{cor: abundant = admissible for type (a, a)}
	Let $\sigma$ be a signature of type $(a, a)$. Then $\sigma$ is $d$-abundant if and only if $\sigma$ is $d$-admissible. 
\end{cor}
\begin{proof}
	This follows from Lemma~\ref{lemma: type (a,a) is bounded} and Proposition~\ref{proposition abundant  = bounded + admissible}.
\end{proof}




\begin{theorem}\label{abundant  = bounded affine permutation theorem}
	A signature $\sigma$ is $d$-abundant  if and only if $\pi_{\sigma, d}$ is a bounded affine permutation of bias $d$.
\end{theorem}

\begin{proof}
	Suppose that $\sigma$ is $d$-abundant. Then $\sigma$ is $d$-bounded, so $\pi_{\sigma, d}$ is a bounded affine permutation. By Theorem~\ref{thm: length and admissibility theorem}, we have $\bb(\pi_{\sigma, d}) = \ell_d(\sigma) = d$ as $\sigma$ is $d$-admissible. 

	Conversely, assume that $\pi_{\sigma, d}$ is a bounded affine permutation of bias $d$. Then $\sigma$ is $d$-bounded and $\ell_d({\sigma}) = d$. By Theorem~\ref{thm: length and admissibility theorem}, $\ell_d({\sigma}) = d$ implies that $\sigma$ is $d$-admissible. So $\sigma$ is $d$-bounded and $d$-admissible, hence $d$-abundant  by Proposition~\ref{proposition abundant  = bounded + admissible}.
\end{proof}


\begin{remk}
	Following Corollary~\ref{remk: correspondence between signatures and affine permutations},  the bijection
	\begin{align*}
		\{\text{signatures}\}/\{\pm 1\} &\longrightarrow \{\text{$d$-representable biased affine permutations of bias} \le d\}, \\
		\sigma & \longmapsto \pi_{\sigma, d}
	\end{align*}
	restricts to bijections
	\begin{equation*}
		\begin{split}
			\{\text{$d$-admissible signatures}\} &\leftrightarrow \{\text{$d$-representable affine permutations of bias} = d\},\\
			\{\text{$d$-bounded signatures}\} &\leftrightarrow \{\text{$d$-representable bounded affine permutations of bias} \le d\},\\
			\{\text{$d$-abundant  signatures}\} &\leftrightarrow \{\text{$d$-representable bounded affine permutations of bias} = d\}.
		\end{split}
	\end{equation*}
\end{remk}


\begin{cor}\label{shifting/reversing preserves strongly admissibility corollary}
	For a signature $\sigma$, the following are equivalent:
	\begin{itemize}[wide, labelwidth=!, labelindent=0pt]
		\item $\sigma$ is $d$-abundant;
		\item $\rev{\sigma}$ is $d$-abundant;
		\item $\tau_m(\sigma)$ is  $d$-abundant for some $m\in \Z$;
		\item $\tau_m(\sigma)$ is  $d$-abundant for every $m\in \Z$.
	\end{itemize}
\end{cor}

\begin{proof}
	This follows from Proposition~\ref{shifting/reversing preseves boundness}, Proposition~\ref{shifting/reversing preseves length} and Theorem~\ref{abundant  = bounded affine permutation theorem}. 
\end{proof}

\begin{prop}\label{separated signature abundant  condition}
	Let $\sigma$ be a separated signature of type $(a, b)$. Then $\sigma$ is $d$-abundant  if and only if 
	\begin{equation}
		d \le \max\{\min\{a, b\} + 1,  |a - b|\}.
	\end{equation}
\end{prop}

\begin{proof}
	Suppose that $a = b$. Then $\sigma$ is $d$-abundant  if and only if $\sigma$ is $d$-admissible if and only if $d \le a + 1$ by Corollary~\ref{cor: abundant = admissible for type (a, a)}  and Proposition~\ref{length and admissibility of signature of type a b}. 

	Suppose that $a\neq b$. Without loss of generality, we may assume that $a>b$,  $\sigma(1) = 1$ and $\sigma(n) = -1$. By Theorem~\ref{abundant  = bounded affine permutation theorem}, $\sigma$ is $d$-abundant  if and only if 
	\[\max_{j\in \Z}\{\pi_\sigma(j) - j\} \le n.\] As in the proof of Proposition~\ref{length and admissibility of signature of type a b}, we have 
	\begin{equation}
		\pi_{\sigma}(j) - j= \begin{cases}
			\left(\left[ \frac{d-a-2+j}{a-b} \right] + 1\right)(n-a+b) + d, &\text{if}\ 1\le j \le a - b;\\
			2(a + 1 - j), & \text{if}\  a-b + 1 \le j \le a;\\
			2(a + b + 1 -j), & \text{if} \ a+1 \le j \le a+b = n.
		\end{cases} 
	\end{equation}
	So the maximum of $\pi_{\sigma}(j) - j$ can only happen at $j = a-b$, $j = a-b + 1$ or $j = a + 1$. Hence
	\begin{align*}
		\max_{j\in \Z}\{\pi_\sigma(j) - j\} &= \max\{\left(\left[ \frac{d-a-2+a-b}{a-b} \right] + 1\right)(n-a+b) + d, 2b\} \\
		&= \max\{2b\left(\left[ \frac{d-b-2}{a-b} \right] + 1\right) + d, 2b\}.
	\end{align*}
	Notice that $2b < a + b = n$, so $\sigma$ is $d$-abundant  if and only if 
	\[2b\left(\left[ \frac{d-b-2}{a-b} \right] + 1\right) + d \le n.\]
	This is equivalent to $d \le \max\{b + 1, a -b\}$. \qedhere
\end{proof}



