\section{Methods}    
    \subsection{Variational Monte Carlo}

        \par As explained in the main text, Variational Monte Carlo aims at minimizing the expectation value of the hamiltonian under a variational state $\ket{\psi_\theta}$: 
        \begin{equation*}
            E_\theta =  \frac{\bra{\psi_\theta} H \ket{\psi_\theta}}{\bra{\psi_\theta} \ket{\psi_\theta}}.
        \end{equation*}
        \par By inserting the sum of projector along each element of the orthogonal basis $\{\ket{x}\}$, namely $\mathbb{I} = \sum_x \ket{x}\bra{x}$ one can rewrite the previous expression as an expectation value under the Born amplitude $p(x) = \frac{|\psi_\theta(x)|^2}{\bra{\psi_\theta}\ket{\psi_\theta}}$:

        \begin{equation*}
            E_\theta = \E_{p}\left[ H_{loc}(x)\right],
        \end{equation*}

        where: \begin{equation*}
            H_{loc}(x) = \frac{1}{\psi_\theta(x)} \sum_{y, H_{xy} \neq 0} H_{xy} \psi_\theta(y)
        \end{equation*}
        is called the local energy. This quantity is indeed local as it can be evaluated with the knowledge of the NQS $\psi_\theta(\cdot)$ and $\ket{x}$.

\subsection{Infidelity optimization}
\label{appendix:infid}

    The fidelity between two pure quantum states is defined as:
    \begin{equation*}
        \mathcal{F}(\ket{\psi}, \ket{\phi}) = 
        \frac{\bra{\psi} \ket{\phi}\bra{\phi} \ket{\psi}}{
        \braket{\psi} \braket{\phi}}, 
    \end{equation*}
    where $\ket{\psi}$ will be identified to the variational state, and $\ket{\phi}$ to the target state.
    The goal will be to minimize the infidelity $\mathcal{I} = 1 - \mathcal{F}$.
    Following \cite{gravina_neural_2024}, we write $\mathcal{F}$ as an expectation value marginalized over the target state

    \begin{equation*}
        \mathcal{F}(\ket{\psi}, \ket{\phi}) = \E_{|\psi|^2}[\underbrace{\E_{y \sim |\phi|^2}[F(x,y) \mid x]}_{f(x)}].
    \end{equation*}
    In this form, a Monte Carlo estimator of the fidelity suffers from a vanishing SNR when $\psi$ approaches $\phi$.
    It is convenient to use the control-variate-enhanced estimator to get rid of this problem:
    \begin{align*}
        f(x) &= \E_{y \sim |\phi|^2}[F(x, y) \mid x] \\ \notag
         &= \Re\{A_x(x)\E_{y \sim|\phi|^2}[A_y(y)]\} \;+ \\ \notag &c \left( \left| A_x(x) \right|^2 \mathbb{E}_{y \sim \pi_\phi} \left[ \left| A_y(y) \right|^2 \right] - 1 \right),
    \end{align*}
    with $A_x(x) = \phi(x)/\psi(x)$ and $A_y(y) = \psi(y)/\phi(y)$.
    This expression leverages the fact that $\E_{x,y\sim |\psi(x)|^2|\phi(y)|^2}[|A_x(x)A_y(y)|^2] = 1$ to reduce the variance.
    Importance sampling is then applied by independently sampling and reweighting by $|\psi(x)|^\alpha$ and $|\phi(y)|^\alpha$.
    We use the same $\alpha$ for both expectation values as $\ket{\psi}$ is expected to resemble $\ket{\phi}$ near convergence.

    \par It is worth noting that projected quantum dynamics already employed importance sampling to bypass the fact that evaluating $\mathcal{F}(\hat{V}\ket{\psi}, \hat{U}\ket{\phi})$ introduces an expensive sampling procedure from $|\bra{x}\hat{V}\ket{\psi}|^2$ and $|\bra{y}\hat{U}\ket{\phi}|^2$ and that our approach builds on top of this reweighting: instead of reweighting with $|\psi(x)|^2$ (resp. $|\phi(y)|^2$), we reweight with $|\psi(x)|^\alpha$ (resp. $|\phi(y)|^\alpha$).

\subsection{The self-normalized Importance Sampling estimator}
    \label{appendix:snis}
     In this section, we review the mathematical aspects of the self-normalized Importance Sampling estimator (SNIS). We start by defining the SNIS estimator, then computes its variance and bias. Afterwards, we derive the derivative of the variance of the SNIS estimator for a variational sampling distribution.


\subsubsection{Definition}
    The definition of the Self-normalized importance sampling estimator is given by \cref{eqn:estimator_2} below. 
    To define it, and discuss its properties we start by introducing some notation. 
    \begin{itemize}
        \item $P(x) = p(x)/Z_p$ is the original (or target) Born distribution we want moments under. 
        \item $Q(x) = q(x)/Z_q$ is the proposal distribution from which we actually intend to sample. 
        \item $x_i \sim Q$ for $i=1,\ldots,n$ are the samples. 
        \item $X$ and $Y$ are arbitrary functions of interest and $X_i = X(x_i)$ and $Y_i=Y(x_i)$. 
        \item $w_i= w(x_i) = p(x_i)/q(x_i)$ are the raw importance weights and $W_1 = \sum_i w_i$, $W_2 = \sum_i w_i^2$ are the first and second weight–moments. 
        \item $\tilde w_i = w_i/W_1$ are the self‑normalized weights. 
    \end{itemize}
    We note for future reference that since 
    \begin{equation}
        \E_{Q}[w(x)] = \sum_{x} \frac{q(x)}{Z_q} \frac{p(x)}{q(x)} = \frac{\sum_x p(x)}{Z_q} = \frac{Z_p}{Z_q},
    \end{equation}
    the expectation value under $P$ of some local quantity f can be written as a ratio,
    \begin{align*}
        \E_{P}[f(x)] 
        &= \sum_x \frac{p(x)}{Z_p} f(x) 
        = \sum_x \frac{p(x)}{Z_p} \frac{q(x)/Z_q}{q(x)/Z_q} f(x) \\
        &= \frac{\sum_x \frac{q(x)}{Z_q} w(x) f(x)}{Z_p/Z_q}
        = \frac{\E_Q[w(x)f(x)]}{\E_Q[w(x)]}.
    \end{align*}

    We now define the self-normalized importance sampling estimator as the plug-in estimator of the above ratio, that is 
    \begin{align}
    \label{eqn:estimator_2}
        \E_P[f(x)] 
        &= \notag \frac{\E_Q[w(x)f(x)]}{\E_Q[w(x)]} 
        \approx \frac{\frac{1}{n}\sum_{i=1}^nw_if(x_i)}{\frac{1}{n}\sum_{i=1}^nw_i} \\
        &= \frac{\sum_{i=1}^nw_if(x_i)}{W_1} 
        = \sum_{i=1}^n \tilde w_if(x_i).
    \end{align}


    Let $X$ and $Y$ bet two random variables. Lets introduce some auxiliary notation. Let $\mu_X=\E_P[X]$, $\mu_Y=\E_P[Y]$, $\mu_{XY}=\E_P[XY]$, and $C_{XY}=\cov_P(X,Y) = \E_P[\underbrace{(X-\mu_X)(Y-\mu_Y)}_{C(X.Y)}]$.  Equation~\eqref{eqn:estimator_2} can be applied to the means of $X(x)$ and $Y(x)$ for which we have that
    \begin{equation*}
        \mu_X = \E_P[X] \approx\widehat\mu_X  = \sum_{i=1}^{n}\tilde w_i X_i,
    \end{equation*}
    and similarly for $\mu_Y$. For the expression of the covariance of $X$ and $Y$, we have an analogous replacement:
    \begin{align*}
        C_{XY} 
        &= \E_{P}\bigl[(X(x)-\mu_X)\,(Y(x)-\mu_Y)\bigr]  \\
        &= \frac{\E_{Q}\bigl[w(x)\,(X(x)-\mu_X)\,(Y(x)-\mu_Y)\bigr]}{\E_Q[w(x)]},
    \end{align*}
    with the plug-in estimator being 
    \begin{equation}
    \label{eqn:is_simple_cov}
        \widehat{C}_{XY}^{\rm{\,simple}} =\sum_{i=1}^{n}\tilde w_i
            (X_i-\widehat\mu_X)(Y_i-\widehat\mu_Y)
          =\sum_{i=1}^{n}\tilde w_i X_i Y_i
            -\widehat\mu_X\widehat\mu_Y .
    \end{equation}
    Recall that now $x_i$ are sampled from $Q$, not from $P$.
    We now want to estimate the variance of this estimator. A finite‑sample closed form is algebraically complicated because of the normalizing denominator. Following the overwhelming majority of the literature, we rely on the first-order multi-variate delta method \cite{oehlert_delta_1992} to obtain the asymptotic variance of both estimators.

    \subsubsection{Variance of the SNIS sample covariance}

    In this appendix we will prove that the variance of the covariance estimator (\cref{eqn:is_simple_cov}) of the Self Normalized Importance Sampling (SNIS) is
    \begin{equation}
        \label{eq:varformula}
        \V(\hat{F_i^q}) = \frac{1}{N_S}\frac{\E_q\left[w^2(x)|f_i(x) -F_i|^2 \right]}{(\E_q\left[w(x)\right])^2}.
    \end{equation}

    The proof follows.
    We define the random vectors
    \begin{equation*}
    %\label{eqn:delta_method_vector}
        \bm V_i=
        \frac{Z_q}{Z_p}
        \begin{pmatrix}
          w_i\\
          w_i X_i\\
          w_i Y_i\\
          w_i X_i Y_i
         \end{pmatrix},
    \qquad
    \bm \Sigma_n=\frac{1}{n}\sum_{i=1}^{n} \bm V_i
        =\begin{pmatrix}
          A\\ B \\ C \\ D\\
          \end{pmatrix}
    \end{equation*}
    with 
    \begin{align*}
        A &= \notag \frac1n\sum_iw_i,\quad\quad &&B= \frac1n\sum_iw_i X_i,\\ C&=\frac1n\sum_iw_i Y_i,\quad\quad &&D=\frac1n\sum_iw_i X_i Y_i.
    \end{align*}
    Note that the factor $Z_q/Z_p$ in the definition of $\bm V_i$ is deterministic and only serves the purpose of normalizing the expectation values.
    Indeed, the expectations under $Q$ are
    \begin{equation}
    \label{eqn:averages}
    \begin{aligned}
        \bm m \equiv \E_Q[\bm V] = \bigl(1,\;\mu_X,\;\mu_Y,\;\mu_{XY}\bigr)^{T} = \E_Q[\bm \Sigma_n]
    \end{aligned}
    \end{equation}
    where $\bm V$ is a representative of the sample statistics $\bm V_i$. 

    Replacing into Eq.~\eqref{eqn:is_simple_cov} we obtain
    \begin{equation*}
        \widehat{C}_{XY}^{\rm{\,simple}} = g(\bm \Sigma_n) = g(A,B,C,D) = \frac{D}{A}-\frac{BC}{A^{2}}.
    \end{equation*}
    To apply the delta method \cite{oehlert_delta_1992} we need to compute the gradient of $g(\bm \Sigma_n)$ and evaluate it at $\bm m$:
    \begin{equation*}
        \begin{aligned}
    \frac{\partial g}{\partial A}
       & =-\frac{D}{A^{2}}+\frac{2BC}{A^{3}}
         \;\;\xrightarrow[]{\eqref{eqn:averages}}\;\;
         -C_{XY} + \mu_X\mu_Y,
         \\[4pt]
    \frac{\partial g}{\partial B}
       & =-\frac{C}{A^{2}}
         \;\;\xrightarrow[]{\eqref{eqn:averages}}\;\;
         -\mu_Y\\[4pt]
    \frac{\partial g}{\partial C}
       & =-\frac{B}{A^{2}}
         \;\;\xrightarrow[]{\eqref{eqn:averages}}\;\;
         -\mu_X\\[4pt]
    \frac{\partial g}{\partial D}
       & =\frac1A
         \;\;\xrightarrow[]{\eqref{eqn:averages}}\;\;
         1,
    \end{aligned}
    \end{equation*}
    so that 
    \begin{equation*}
        \grad g(A,B,C,D)\,\bigl|_{\bm m}= 
    \bigl(
    -C_{XY} + \mu_X\mu_Y,\;
    -\mu_Y,\;
    -\mu_X,\;
    1
    \bigr)^T.
    \end{equation*}
    To conclude, we need the covariance matrix of one draw, that is
    \begin{align*}
        \bm \Sigma &=\cov_q[\bm V] = \E_q[\bm V \bm V^T] - \bm m\bm m^T
    \end{align*}

    From the delta method \cite{oehlert_delta_1992}, we have that to leading order in $n$
    \begin{equation}
    \label{eqn:variance_is_simple}
        \V\bigl[\widehat{C}_{XY}^{\rm{\,simple}}\bigr]
          \approx \frac{1}{n}\grad g(\bm m)^{T}\bm\Sigma\,\grad g(\bm m) + o(n^{-1}).
    \end{equation}
    From here on out we will neglect the terms vanishing faster than $1/n$. 
    Computing the leading term by explicitly carrying out the contraction is straightforward but can be quite tedious. Instead we realize that 
    \begin{align*}
        \grad g(\bm m)^{T}\bm\Sigma\,\grad g(\bm m)
        &= \grad g(\bm m)^{T}\cov_Q[\bm V]\,\grad g(\bm m)\\ &= 
        \V_Q[\grad g(\bm m)^T\,\bm V],
    \end{align*}
    where we used that $\grad g(\bm m)^T\,\bm V$ is a scalar quantity to replace the covariance with the variance. Since $\grad g(\bm m)^T$ is deterministic, we have that $\E_Q(\grad g(\bm m)^T\,\bm V) = \bm m$. 
    Now

    \begin{flalign*}
        &\grad g(\bm m)^T(\bm V - \bm m) = 
        \notag \frac{Z_q}{Z_p}\cdot\underbrace{\,w\bigl(XY - \mu_YX - \mu_XY - C_{XY}\bigr)\,}_{=\,(X-\mu_X)(Y-\mu_Y) - C_{XY} = C(X,Y) - C_{XY}} \, \\ &+ \, \underbrace{\,C_{XY} - \mu_X\mu_Y + 2\mu_X\mu_Y - \mu_{XY}\,}_{=\;0}\\
        &=  \frac{Z_q}{Z_p} w \bigl( C(X,Y) - C_{XY} \bigr) 
         \equiv \frac{Z_q}{Z_p} w\,H(X,Y), 
    \end{flalign*}
    where 
    \begin{equation*}
        H(X,Y) \equiv C(X,Y) - C_{XY} \equiv (X-\mu_X)(Y-\mu_Y) - C_{XY}.
    \end{equation*}
    Note that $H(X,Y)$ is a functional and should be seen as $H(X,Y)(x) = H(X(x),Y(x))$.
    Finally we have that 
    \begin{equation*}
    \label{eqn:variance_covariance}
    \begin{aligned}
        &\V\bigl[\widehat{C}_{XY}^{\rm{\,simple}}\bigr]
          = \frac{1}{n}\grad g(\bm m)^{T}\bm\Sigma\,\grad g(\bm m) \\
          &= \frac{1}{n} \V_Q\qty[\frac{Z_q}{Z_p}w\,H(X,Y)] 
          = \frac{1}{n} \frac{\V_Q[w\,H(X,Y)]}{(Z_p/Z_q)^2} \\
          &= \frac{1}{n} \frac{\E_Q[w^2\,H^2(X,Y)]}{(\E_Q[w])^2},
    \end{aligned}
    \end{equation*}
    where in the last equality we used that $wH$ is centered in $Q$.
    The plug-in estimator of this quantity is 
    \begin{equation*}
    \begin{aligned}
        &\widehat\V\bigl[\widehat{C}_{XY}^{\rm{\,simple}}\bigr]
        =  \frac{1}{n} \frac{\frac{1}{n}\sum_i w_i^2\,H^2(X_i,Y_i)}{\qty(\frac{1}{n}\sum_i w_i)^2} \\
        &= \sum_i \qty(\frac{w_i}{\sum_i w_i})^2\,H^2(X_i,Y_i) 
        = \sum_i \tilde w_i^2\,H^2(X_i,Y_i) \\[0.1cm]
        &= \sum_i \tilde w_i^2 \bigl[(X_i - \widehat\mu_X)(Y_i - \widehat\mu_Y) - \widehat C_{XY}^{\,\rm{simple}}  \bigr]^2
    \end{aligned}
    \end{equation*}

    Going back to the notation of the paper, we see that we get \cref{eq:varformula}.

\subsubsection{Bias}
    In this appendix we prove that the bias of the SNIS estimator is

    \begin{equation}
        \mu_X \left[\frac{1}{n}\left(\underbrace{\frac{\E_Q[w^2(\mu_X - X)]}{\mu_X \E_Q[w]^2}}_{\rho_0}\right)\right].
    \end{equation} 
    The proof follows.
    To simplify the calculation, we will make an approximation by neglecting the covariance structure of the estimator, and only the consider the bias related to the ratio structure. 
    This approximation is motivated by the fact that the covariance will contribute higher order terms which we assume are not dominant here (we also remark that without this approximation it would be very hard to get interpretable analytical results).

    We recall that the SNIS estimator is denoted as $F = \frac{1}{n}\sum_{i=1}^n \tilde{w}_i X_i$. 
    Similarly to the previous section, we will use the delta method to compute the bias. In that case, we need to go to second order as $\E_Q(\frac{Z_q}{Z_p}(w X) - \mu_X) = \E_Q[\frac{Z_q}{Z_p}w - 1] = 0$. 

    Defining:
    \begin{equation*}
    \label{eqn:delta_method_vector_bias}
        \bm V_i=  \frac{Z_q}{Z_p}    
        \begin{pmatrix}
          w_i\\
          w_i X_i\\
         \end{pmatrix},
    \qquad
    \bm \Sigma_n=\frac{1}{n}\sum_{i=1}^{n} \bm V_i
        =\begin{pmatrix}
          A\\ B 
          \end{pmatrix},
    \end{equation*}
    one observes that given $g(A,B) = \frac{B}{A}$ and $\bm m = (\mu_X, 1)^T$, we have:
    \begin{equation*}
        \notag
        \bm \nabla^2 g(\bm m) = 
        \begin{pmatrix}
            \;2\mu_X
            & \;-1\; 
             \\[6pt]
            \cdot 
            & \;0\; 
    \end{pmatrix}.
    \end{equation*}
    Let $r = \frac{Z_p}{Z_q}$. One can thus write:
    \begin{equation*}
           \begin{aligned}
            &\E(F) \approx \mu_X + \frac12\left[ 2\mu_X \frac{1}{n}\V_Q(\frac{w}{r}) - \frac{2}{n}\mathrm{Cov}_Q(\frac{w}{r},\frac{wX}{r})\right] \\
            &= \mu_X \left[1 + \frac{1}{n}\left(\underbrace{\frac{\E_Q[w^2(\mu_X - X)]}{\mu_X r^2}}_{\rho_0}\right)\right],
        \end{aligned} 
    \end{equation*}

    where we denoted as $\rho_0$ the shrinking factor, independent from the sample size $n$.
    One has especially:
    \begin{align*}
        \frac{\V_Q(w)}{r^2} &= \frac{1}{\rm ESS} - 1,
    \end{align*}
    where the effective sample size (ESS), defined as $\frac{\E_Q\left[w(x)\right]^2}{\E_Q\left[w(x)^2\right]}$, is a common metric to measure the similarity between two probability distributions.

    It is often employed in the usual context of importance sampling where one tries to approximate an intractable distribution as a mean to sample from it.
    It varies from 0 for distributions with disjoint support, to 1 for identical distributions.

    As a consequence, one can infer that the more dissimilar $q$ and $p$ are, the greater the bias will be.

    In \cref{fig:snr-bias} we plot the signal-to-noise ratio as well as the shrinkage factor $\rho_0$ defined above for a variational state taken at the end of the ground state search for the nitrogen, as described in \cref{sec:results-snr}. One sees that in that case, $\rho_0 \sim O(10^1)$ which is negligible compared to the $\frac{1}{n}$ prefactor as $n$ is usually taken in the range $10^3-10^4$. However, $\rho_0$ quickly increases as $\alpha$ approaches 0, which suggests that using a distribution that is too different from the original sampling distribution may lead to problems, except if one find a way to mitigate this bias by employing a refined estimator.

    \begin{figure}
        \center
        \includegraphics[]{snr_bias.pdf}
        \caption{Effective sample size and SNR curves over $\alpha$ computed at the end of a ground state search of the $N_2$ molecule, one of the cases where the optimal $\alpha$ drops to almost $0.5$. The shrinkage factor is relatively small compared to the usually used sample sizes of $N_S \sim O(10^3-10^4)$}
        \label{fig:snr-bias}
    \end{figure}
\subsubsection{Gradient of the SNR}
    \label{appendix:autotuning}
    \par Let $(q_\alpha)_{\alpha \in \mathbb{R}^m}$  be a variational family in $ \mathcal{F}(\{0,1\}^N, \mathbb{R}^+)$.
    Let  $Q_\alpha(x) = \frac{q_\alpha(x)}{Z_\alpha}$ the associated normalized probability distribution.
    Differentiating $Q_\alpha$ with respect to $\alpha$ gives:
    \begin{equation*}
        \forall i \in \{1...m\},
        \frac{\partial_{\alpha_i} q_\alpha(x)}{Z_\alpha} - \sum_y \partial_{\alpha_i} q_\alpha(y) \frac{Q_\alpha(x)}{Z_\alpha},
    \end{equation*}
    which can in general be simplified as: 
    \begin{align*}
        \partial_{\alpha_i} Q_\alpha(x) &= Q_\alpha(x)(\partial_\alpha \log q_\alpha(x) - \E_{q_\alpha}[\partial_{\alpha_i} \log q_\alpha(x)]) \notag \\ &= q_\alpha(x) \Delta_{q_\alpha} \partial_\alpha \log q_\alpha(x),
    \end{align*}
    where 
    \begin{equation*}
        \Delta_{q_\alpha} \partial_\alpha \log q_\alpha(x) = \partial_\alpha \log q_\alpha(x) - \E_{q_\alpha}[\partial_\alpha \log q_\alpha(x)].
    \end{equation*}
    Thus one can write, taking the notations of the main text:
    \begin{align*}
        \partial_{\alpha_i} \V[\hat{F_i}] &= \partial_{\alpha_i} \left( \sum_x \frac{P(x)^2}{Q_\alpha(x)}|f_i(x) - F_i|^2 \right) \notag \\ \notag &=  - \sum_x Q_\alpha(x) \Delta_q\partial_{\alpha_i}\log q_\alpha(x) g_i^2(x)  \\ &= - \E_{q_\alpha}[\Delta_{q_\alpha}\partial_{\alpha_i}\log q_\alpha(x) g_i^2(x)],
    \end{align*}
    where $g_i(x) = W(x)|f_i(x) - F_i|$.
    The gradient of $\mathcal{L}_{IS}$ with respect to $\alpha$ can thus be obtained through the chain rule.

    \subsection{Alternative definitions of the objective function}
        \label{appendix:kl}
        \par As mentioned in the main text, one knows analytically that the distribution minimizing the variance of each gradient component is:
        \begin{equation*}
            q_{opt}^i(x) \propto |\psi(x)|^2(x)|f_i(x) - F_i|.
        \end{equation*}
        We will denote $q_{opt}^{SNIS}(x) = \frac{1}{N_p}\sum_{i=1}^{N_p} q_{opt}^i(x)$ the average of the above distributions, and $q_\alpha$ a variational family of distribution. One can choose a measure of divergence between probability distribution as the objective function, like the Kullback-Leibler divergence \cite{li_variance_2018}:
        \begin{equation*}
            \mathrm{D_{KL}}(q_\alpha |q_{opt}^{SNIS}) = \E_{q_\alpha}\left[\log\left(\frac{q_\alpha(x)}{q_{opt}^{SNIS}(x)}\right)\right].
        \end{equation*}
        One could also consider the following distribution, which is the average of the optimal distributions for standard importance sampling:
        \begin{equation*}
            q_{opt}^{IS}(x) \propto \sum_{i=1}^{N_p}|\psi(x)|^2(x)|f_i(x)|.
        \end{equation*}

        In \cref{fig:snr-kl}, we show that the minimums of KL divergences almost coincides with the maximum SNR for $q_{opt}^{IS}$ but not  $q_{opt}^{SNIS}$. Indeed, averaging all probability distribution may break optimality in a more dramatic way for $q_{opt}^{SNIS}$.
       \begin{figure}[ht]
            \center
            \includegraphics[width=\linewidth]{snr_kl.pdf}
            \caption{Comparison of several objective for the adaptive tuning. We compare Signal-to-noise ratio (grey) with Kullback Leibler divergence with respect to near optimal distributions for importance sampling (orange and blue). The comparison is carried on the state obtained at the end of the ground state search for the nitrogen molecule.}
            \label{fig:snr-kl}
        \end{figure}


    \begin{figure}
            \center
            \includegraphics[width=\linewidth]{spring_comp.pdf}
            \caption{Comparison of SPRING with $\mu=0.9$ vs SGD SR using two different sample sizes. SPRING improves the optimization at low sample sizes.}
            \label{fig:springcomp}
    \end{figure}

        \section{Experimental details}
            \subsection{$J_1$-$J_2$ results}
                \subsubsection{ViT architecture}
                \label{appendix:vit}
                The Vision Transformer, as introduced in \cite{viteritti_transformer_2023}, is a deep neural network architecture originally applied to Computer Vision problems. First, one patches the input by grouping together nearby sites on the lattice. It is particularly interesting in the case of the square $J_1$-$J_2$ model as using patches of lateral size 2 corresponds to the unit cell of the model. Then, a linear embedding layer transforms these patches into $h$ vectors of dimension $d_{model}/h$, where $h$ denotes the number of heads and $d_{model}$ the total number of features. We will denote this matrix $X_i^\mu$, where the upper index runs on the number of heads. These vectors are then passed through a series of multi-head factored attention layers, whose central part is the following operation:
                \begin{equation*}
                    \alpha_i^\mu = \sum_{j=1}^{N} A_{i,j}^\mu X_j^\mu,
                    \label{facatt}
                \end{equation*}
                where $N$ denotes the number of patches, and $A_{i,j}^\mu$ is a tensor of variational parameters.

                Eq. \ref{facatt} essentially mixes the patches' embeddings, allowing the model to capture long-range correlations between them. The full ViT is a stack of these factored attentions combined with a patchwise Multi-Layer Perceptron to process the information aggregated by the factored attention in each patch vector. This architecture makes the ViT translational invariant on patch level. To impose full translational invariance, we just have to apply it at the level of the patch, by averaging the model over one-site translations. 

                This same architecture is also used for the SNR analysis on the 4x4 lattice, the only difference being that we employed a patch size of 1, which greatly improved the results for this lattice size.

                \subsubsection{Hyperparameters}
                \label{appendix:hparams}
                For training the ViT on the J1-J2 model, we used a fixed budget of 6000 iterations using Stochastic Reconfiguration, in which all simulations converged. To regularize the Quantum Geometric Tensor (QGT), we add a diagonal shift, initialized at $10^{-2}$ and decreased to $10^{-4}$ during the first 1000 steps using a cosine decay schedule. The learning rate is annealed in a similar manner, from $O(10^{-3})$ to $O(10^{-4})$. To remove bias, every variational energy is computed as an expectation values under $|\psi|^2$.

    \subsection{Ab-initio quantum chemistry}

        \subsubsection{Neural network backflow}
            We use an NQS with the same architecture as the one used in Ref.~\cite{luo_backflow_2019} and Ref.~\cite{liu_efficient_2025}. 
            For results on $\rm Li_2O$, we use 2 hidden layers, and 256 hidden units. 
            For $\rm N_2$, the number of hidden units is reduced to 16. 
            To improve the results, we also enforce spin flip symmetry.

            \subsubsection{Optimization}

            The Hamiltonians of $\rm N_2$ and $\rm Li_2O$ are expressed in the STO-3G basis and canonical HF molecular orbitals. 
            We observed that with MCMC, using natural orbitals from CCSD makes the optimization slightly more difficult.

            We employ SR or MinSR as an optimization technique depending on the number of variational parameters.
            We also found that SPRING with a momentum of 0.9 improves the training stability, as shown in figure \cref{fig:springcomp}.

            For lithium oxide, we train for 4000 iterations the learning is decayed linearly from $0.1$ to $0.001$ in the first 1000 iterations while the diagonal shift is also decreased linearly from $10^{-3}$ to $10^{-4}$ in 500 steps.
            These parameters are very conservative for many simulations, but could give the overall best results, especially for vanilla VMC using $|\psi(x)|^2$.


        \subsection{Infidelity minimization}
            We employ the same hyperparameters as appendix F of Ref.~\cite{gravina_neural_2024}. As an ansatz, we use a convolutional neural network with 4 layers, a fixed kernel size of 3, and 10 channels in each layer. The diagonal shift is set automatically with the PI controller developed in the same paper.

    \subsection{Equation summary (implementation aid)}
    \label{app:eq-summary-impl-aid}
    In this section we give all the necessary equations for the reader to implement the method presented in this paper. 
    For details about the notation and derivation, please refer to the main text and later appendices.

    \subsubsection{VMC}
    We aim at minimizing: 
    \begin{equation}
        \mathcal{L}(\theta) = \E_{p}[\ell(x)]
    \end{equation}
    for some local objective $\ell(x)$. To estimate the gradient $\bm F = \grad_{\theta} \mathcal{L}(\theta)$, we resort to:
    \begin{equation*}
         F_i = \E_{p}[\underbrace{2\,\Delta\partial_{\theta_i}\!\log \psi_\theta(x)\,\,\Delta \ell(x)}_{f_i(x)}],
    \end{equation*}
    where $\Delta A(x) \equiv A(x) - \E_{p}[A]$. 

    The self normalized importance sampling estimator of the gradient is:
    \begin{equation*}
        F_i = \E_{q}[\underbrace{W(x) f_i(x)}_{f_i^q(x)}],
    \end{equation*}
    where we define $W(x) = w(x)/\E_{q}[w(x)]$ and $w(x) = p(x)/q(x) = |\psi(x)|^2/q(x)$.
    In a similar manner, we estimate the Quantum Geometric Tensor (QGT) as:
    \begin{equation*}
         S_{ij} 
            % &= \E_{p}\!\left[\Delta\partial_{\theta_i}\!\log \psi_\theta(x)^*\,\,\Delta\partial_{\theta_j}\!\log \psi_\theta(x)\right]\\
            = \Re{\E_{q}\!\left[W(x) \, \Delta\partial_{\theta_i}\!\log \psi_\theta(x)^*\,\,\Delta\partial_{\theta_j}\!\log \psi_\theta(x)\right]},
    \end{equation*}

    \subsubsection{Adaptive tuning}
    The variance of the gradient estimator can be estimated as:
    \begin{equation*}
        \V_q[f_i^q(x)] = \E_{q}\left[W^2(x)|f_i(x) - F_i|^2\right].
        \label{varis}
    \end{equation*}

    We aim at maximizing the following objective function:
    \begin{equation*}
        \mathcal{L}_{\rm IS}(q) = \frac{1}{N_p}\sum_{i=1}^{N_p} \sqrt{\frac{|\E_q[f_i^q(x)]|^2}{\V_q[f_i^q(x)]}} =  \frac{1}{N_p}\sum_{i=1}^{N_p} \mathrm{SNR}(f_i^q),
    \end{equation*}
    over the family of overdispersed sampling distributions:
    \begin{equation*}
            \qty{q_\alpha(x) = \frac{|\psi_\theta(x)|^\alpha}{Z_\alpha},\quad \alpha\geq 0}.
    \end{equation*}
    We use:
    \begin{equation*}
        \mathbf{\alpha}' = \mathbf{\alpha} + \eta \partial_\alpha\mathcal{L}_{\rm IS}(q_{\alpha}).
    \end{equation*}
    The gradient of the variance with respect to the variational parameters can be expressed as:
     \begin{multline*}
         \partial_{\alpha} \V_{q_\alpha}[f_i^{q_\alpha}(x)] = -\E_{q_\alpha}[\\\Delta_{q_\alpha}\partial_{\alpha_i}\log f_\alpha(x) W^2(x)|f_i(x) - F_i|^2],
    \end{multline*}
     where
     \begin{equation*}
         \Delta_{q_\alpha} \partial_\alpha \log f_\alpha(x) = \partial_\alpha \log f_\alpha(x) - \E_{q_\alpha}[\partial_\alpha \log f_\alpha(x)].
     \end{equation*}
     This leads to :
     \begin{equation*}
        \partial_{\alpha} \mathrm{SNR}(f_i^{q_\alpha}(x)) = \frac{1}{2} \partial_{\alpha} \V_{q_\alpha}[f_i^{q_\alpha}(x)] \frac{|\E_{q_\alpha}[f_i^{q_\alpha}(x)]|}{\V_{q_\alpha}[f_i^{q_\alpha}(x)]^{3/2}},
    \end{equation*}
    from which we build an estimator of $\partial_\alpha\mathcal{L}_{\rm IS}(q_{\alpha})$.

