\begin{lemma}\label{containment}
If $(X,T)\preceq(X',T')$, then $U_{X,T}\subset U_{X',T'}$.
\end{lemma}

\begin{proof}
Suppose that $(X,T)\preceq(X',T')$.  This implies that, for all $e$ such that $X'_e=0$, we have $X_e=0$ and $T_e=T'_e$.
The result follows.
\end{proof}
