Given an element $z\in\cZ(\cA,\cK)$ represented by a pair $(v,T)\in\cK\times\cT$, let $X\in\cL$ be the unique covector such that $v\in F_X$,
and let $\cK_z := \cK_{X,T}$.  Lemma \ref{Kz} tells us that this is well defined.  

\begin{lemma}\label{confusing}
Let $(X,T)$ and $(Y,S)$ be elements of $\Sal(\cA,\cK)$.  Fix an element $v\in F_Y$, and let $z\in\cZ(\cA,\cK)$ be the element represented
by the pair $(v,S)\in\cK\times\cT$.  The following are equivalent:
\begin{enumerate}
\item[{\em (1)}] $T = X\circ Y$ and $S = Y\circ X$
\item[{\em (2)}] $T = X\circ Y$ and $F_X\cap \cK\subset\cK_z$
\item[{\em (3)}] $F_Y$ and $F_T$ lie on the same side of every hyperplane containing
$F_X$, and $F_X$ and $F_S$ lie on the same side of every hyperplane containing $F_Y$
\item[{\em (4)}] $z\in U_{X,T}$.
\end{enumerate}
\end{lemma}

\begin{proof}
The equivalence of (1), (2), and (3) is immediate from the definitions.  The equivalence of the fourth condition to the other three is slightly trickier.
% All four conditions imply that there are no hyperplanes that contain both $F_X$ and $F_Y$, or equivalently that there is no $e$ such that $X_e=0=Y_e$.
% Thus we will assume this condition throughout.

The statement that $z\in U_{X,T}$ is equivalent to the statement that $v\in \cK_{X,T}$ and $(v,S)\sim(v,T)$.
We have $v\in \cK_{X,T}$ if and only if $F_Y$ and $F_T$ lie on the same side of every hyperplane containing $F_X$,
which in particular implies that there is no hyperplane containing both $F_X$ and $F_Y$.
We have $(v,S)\sim(v,T)$ if and only if $F_S$ and $F_T$ lie on the same side of every hyperplane containing $F_Y$.
Given the statement that there is no hyperplane containing both $F_X$ and $F_Y$, along with the fact that $F_X$ lies on the boundary of $F_T$,
this is equivalent to the condition that $F_S$ and $F_X$ lie on the same side of every hyperplane containing $F_Y$.
This establishes the equivalence of (3) and (4).
\end{proof}

\vspace{-\baselineskip}
\begin{proposition}\label{whe}
The Salvetti complex $|\Sal(\cA,\cK)|$ is weakly homotopy equivalent to $\cZ(\cA,\cK)$.
\end{proposition}

\begin{proof}
Consider the map that associates to any element $(X,T)\in\Sal(\cA,\cK)$
the open subset $U_{X,T}\subset\cZ(\cA,\cK)$.  By Lemma \ref{containment}, this is a map of posets. 
For any $z\in \cZ(\cA,\cK)$, consider the poset $$\Sal(\cA,\cK)_{z} = \{(X,T)\in\Sal(\cA,\cK)\mid z\in U_{X,T}\}.$$
Let $Y$ be the unique covector such that $\pi(z)\in F_Y$.
By the equivalence of (2) and (4) in Lemma \ref{confusing}, we have
$$\Sal(\cA,\cK)_{z} = \{(X,X\circ Y)\mid F_X\cap \cK\subset\cK_z\}.$$
In particular, there is a bijection from $\cL(\cA,\cK_z)$ to $\Sal(\cA,\cK)_{z}$ given by the map $X\mapsto (X,X\circ Y)$.
We claim that this bijection is in fact an isomorphism of posets.  Indeed, if
$X\leq X'\in \cL(\cA,\cK_z)$, then $X'\circ X = X'$, which implies that 
$(X,X\circ Y)\preceq(X',X'\circ Y)\in\Sal(\cA,\cK)_{z}$.

Since we have a poset isomorphism $\cL(\cA,\cK_z) \cong \Sal(\cA,\cK)_{z}$, 
Proposition \ref{face poset} implies that the order complex $|\Sal(\cA,\cK)_{z}|$ is contractible.
Then Corollary \ref{Dan's got a lot of nerve} implies that $|\Sal(\cA,\cK)|$ is weakly homotopy equivalent to $\cZ(\cA,\cK)$.
\end{proof}

\begin{proof-z-pair}
Theorem \ref{stronger} and Proposition \ref{whe} together imply that $\cM(\cA,\cK)$ and $|\Sal(\cA,\cK)|$ have the same weak homotopy type.
Since $\cM(\cA,\cK)$ and $|\Sal(\cA,\cK)|$ are both homotopy equivalent to CW-complexes, they must be homotopy equivalent.
This well-known fact that can be proved by combining Whitehead's theorem \cite[Proposition 4.5]{hatcher} with the existence and
uniqueness of CW-approximations \cite[Proposition 4.13 and Corollary 4.19]{hatcher}.
\end{proof-z-pair}

