%
%
\subsubsection{Fine-grained KMS relation for energy eigenstates whose $s_\alpha, m = O \left( N^\zeta  \right)$, wherein $\zeta \in (0, 1]$, and $s_\alpha - m = O(1)$}
\label{app_KMS_s_Large_m_Large}

In the above-named parameter regime, we estimate the Clebsch–Gordan product $\mathcal{C}$. Then, we estimate the $\partial_s \tilde{S}_\th$ in the log-ratio~\eqref{eq_Logratio_app_help2}.

Let us estimate the Clebsch–Gordan product $\mathcal{C}$ in the log-ratio~\eqref{eq_Logratio_app_help2}. We leverage the following claim, labeled as Eqs.~(B11)--(B12) in~\cite{24_Lasek_Numerical}: 
   \begin{align}
      \label{eq_CG_prop_24a}  &
      \text{If} \; \tilde{s}, \tilde{m} = O \left(  N^\zeta  \right), 
      \;  \text{wherein}  \;   \zeta \in (0, 1],  \;  \text{and}  \;
      \;  \tilde{\nu}, \tilde{k}, \tilde{q}, \tilde{s} - \tilde{m} = O(1),
      \; \text{then} \\ &
      % % %
      \label{eq_CG_prop_24b}
      \braket{ \tilde{s} + \tilde{\nu} , \tilde{m} + \tilde{q} }{
                   \tilde{s}, \tilde{m} ; \tilde{k} , \tilde{q}  }
      =  c \left( \tilde{\nu} , \tilde{k} , \tilde{q}, \tilde{s} - \tilde{m}  \right)  \,
      (\tilde{s})^{- | \tilde{\nu} - \tilde{q} | / 2}  \,
      \left[ 1 + O \left( \tilde{s}^{-1} \right)  \right] ,
      \; \text{wherein} \\ &
      % % %
      \label{eq_CG_prop_24c}
      c \left( \tilde{\nu} , \tilde{k} , \tilde{q}, \tilde{s} - \tilde{m}  \right)
      =  \delta_{ \tilde{\nu} \tilde{q} }  
          +  \left( 1 - \delta_{ \tilde{\nu}  \tilde{q} }  \right)  \,  O(1) .
   \end{align}
   Our parameters satisfy the conditions~\eqref{eq_CG_prop_24a}.\footnote{
   % < f >
   Equations~\eqref{eq_Bound_nu} bound $\Delta s = s_{\alpha'} - s_\alpha$ in terms of $k$ and $k'$, which are $O(1)$.}
   % < /f >
   We can therefore apply Eqs.~\eqref{eq_CG_prop_24b} and~\eqref{eq_CG_prop_24c}, with the $\mathcal{C}$ definition~\eqref{eq_CG_prod_app}, to the Clebsch–Gordan product in Eq.~\eqref{eq_Logratio_app_help2}:
   \begin{align}
      \label{eq_KMS_thermo_case1_help1}
      \mathcal{C} ( \Delta s | s_\alpha, m , k , k' , q ) 
      % % %
      & = \left\{  \delta_{ (\Delta s) \, q }
      + O \left( \left[ 1 - \delta_{ (\Delta s) \, q}  \right]  \,
                     s_\alpha^{- | \Delta s - q | }  \right)  \right\}
      \left[ 1 + O \left( s_\alpha^{-1}  \right)  \right]  \\
      % % %
      & =  \delta_{ (\Delta s)  q}  \,
            \left[ 1 + O \left( s_\alpha^{-1}  \right)  \right]
            +  \left( 1 - \delta_{ (\Delta s) q }  \right)  \,
                O  \left(  s_\alpha^{- O(1)}  \right) .
   \end{align}
This function remains invariant under the transformation~\eqref{eq_Trans_compare}. Hence the two Clebsch–Gordan products in~\eqref{eq_Logratio_app_help2} cancel. Yet consider substituting for the $\mathcal{C}$s in Eqs.~\eqref{eq_S_w_dynamic_app_3} and~\eqref{eq_C_Trans_Help1}. Each $\mathcal{C}$'s leading-order term is proportional to $\delta_{(\Delta s) q} \, ,$ which multiplies a $\delta_{(\Delta m) q} \, .$ The following consequence will affect our result:
\begin{align}
   \label{eq_Delta_s_m}
   \Delta s = \Delta m .
\end{align}

Now, we can apply the $\rho_\NATS$ property~\eqref{eq_Big_params_thermo_1} to energy eigenstates $\ket{\alpha, m}$. This application is justified only if $s_\alpha$, $m$, and $E_\alpha$ satisfy Eqs.~\eqref{eq_NATS_eigen_correspondence}. $s_\alpha$ and $m$ do by assumption [by the title of this subsubsection and by the boldface text above Eq.~\eqref{eq_Big_params_thermo_1}] and by Eq.~\eqref{eq_Sz_bm_large}.
Hence
\begin{align}
   \label{eq_partial_s_help1}
   \partial_s \tilde{S}_\th (E, s) \lvert_{E_\alpha, \, s_\alpha}
   =  - \beta (\mu + \gamma )  +  O( s_\alpha^{-1} ) .
\end{align}

Let us substitute from Eqs.~\eqref{eq_KMS_thermo_case1_help1},~\eqref{eq_Delta_s_m},~\eqref{eq_partial_s_help1}, and~\eqref{eq_Estimate_Exp_Correxn} into the log-ratio~\eqref{eq_Logratio_app_help2}:
\begin{align}
   \label{eq_Logratio_app_help3}
    \tilde{\mathcal{{L}}}_{AB} (\Omega, q, \Delta s;  \alpha,m)
    % % %
    & = \beta ( \Omega  -  \mu \, \Delta m  -  \gamma \,  \Delta s )  
    + O \left( s_\alpha^{-O(1)}  \right)
   + O \left( E_\alpha^{-1}  \right)
   \nonumber \\ & \quad \; 
   + O \left( N E_\alpha^{-2}  \right)
   + O  \left( N s_\alpha^{-2}  \right)
   + O \left( N E_\alpha^{-1}  s_\alpha^{-1}  \right) .
\end{align}
We have proved the fine-grained KMS relation.


%
%
%
\subsubsection{Fine-grained KMS relation for energy eigenstates whose 
$s_\alpha = O(N^\zeta)$, wherein $\zeta \in (0, 1]$, and $m = 0$}
\label{app_KMS_s_Large_m_0}

Again, we approximate the $\mathcal{C}$ in the log-ratio~\eqref{eq_Logratio_app_help2}. Then, we approximate the $\tilde{S}_\th$ derivative.

Equation~\eqref{eq_CG_prod_app} defines $\mathcal{C}$ in terms of two Clebsch--Gordan coefficients, approximated as follows in App.~\ref{app_CG_property}:
   \begin{align}
      \text{If} \; 
      \tilde{s} = O \left( N^\zeta \right) , \;
      \zeta \in (0, 1 ] ,
      \; \text{and} \;
      \tilde{k}, \tilde{q}, \tilde{m}  =  O(1) ,
      \; \text{then}  \;
      \braket{ \tilde{s} + \tilde{\nu} , \tilde{m} + \tilde{q} }{  
                   \tilde{s} , \tilde{m} ; \tilde{k} , \tilde{q} }
      =  \bar{c} \left(  \tilde{\nu} ; \tilde{k} , \tilde{q}  \right)  \,
      \left[ 1 + O \left( \tilde{s}^{-1}  \right)  \right] .
   \end{align} 
   Appendix~\ref{app_CG_property} specifies the form of 
   $\bar{c}  (  \tilde{\nu} ; \tilde{k} , \tilde{q}  )$.
   Therefore, the Clebsch--Gordan product in Eq.~\eqref{eq_S_w_dynamic_app_2} approximates to
   \begin{align}
      \mathcal{C} ( \Delta s | s_\alpha , m , k , k' , q )
      % % % 
      & = \bar{c} ( -\Delta s ; k' , -q )  \,
      \bar{c} ( \Delta s; k, q )  \,
      \left[ 1 + O \left( s_\alpha^{-1}  \right)  \right] 
      % % %
      \label{eq_C_case2_help1}
      =  \mathcal{C} ( - \Delta s | s_\alpha, m, k', k, -q)
      \left[ 1 + O \left( s_\alpha^{-1}  \right)  \right] .
   \end{align}

Now, we estimate the $\tilde{S}_\th$ derivative in the log-ratio~\eqref{eq_Logratio_app_help2}.
Since $m = 0$ by assumption, $\mu = 0$. Therefore, by the similarity between $\rho_\NATS$ and $\ket{\alpha, m}$, Eq.~\eqref{eq_S_bm0} implies
% DO NOT DELETE: See folder "KMS_relation_JaeDong" --> Notes --> 25_07_Match_NATS_with_|alpha,m>
   $\partial_s  \tilde{S}_\th (E, s) |_{ E_\alpha, \, s_\alpha}  \approx  - \beta \gamma$.
%   The text above Eq.~\eqref{eq_Approx_ratio2} explains the $\approx$ symbol.

Let us substitute from the foregoing equation, Eq.~\eqref{eq_C_case2_help1}, and Eq.~\eqref{eq_Estimate_Exp_Correxn} into Eq.~\eqref{eq_Logratio_app_help2}:
\begin{align}
   \label{eq_L_case2_app}
   \tilde{\mathcal{{L}}}_{AB} (\Omega, q, \Delta s;  \alpha, m {=} 0)
    % % %
    = \beta ( \Omega  -  \gamma \,  \Delta s )  
    + O \left( s_\alpha^{-1}  \right)
   + O \left( E_\alpha^{-1}  \right)
   + O \left( N E_\alpha^{-2}  \right)
   + O  \left( N s_\alpha^{-2}  \right)
   + O \left( N E_\alpha^{-1}  s_\alpha^{-1}  \right) .
\end{align}
Again, we have proved the fine-grained KMS relation.



