\section{Transformation property of fine-grained correlator evaluated in energy eigenstate}
\label{app_Sym_for_num}

This appendix introduces the transformation property invoked in the numerical analysis (Sec.~\ref{sec_Num}). By invoking the property, one can easily deduce general results from the examples analyzed. The property stems from the Wigner–Eckart theorem as follows. In Sec.~\ref{sec_Num}, we analyze correlators of spherical tensor operators $A^{(k')}_{-q}$ and $B^{(k)}_q \, .$ The correlators depend on elements of the matrices that represent the operators relative to the energy eigenbasis, $\{ \ket{\alpha, m} \}$. By the Wigner–Eckart theorem, Clebsch–Gordan coefficients encapsulate all the matrix elements' $m$- and $q$-dependences. For example, 
\begin{align}
    \langle \alpha',m+q|B^{(k)}_q | \alpha,m\rangle &= 
    \langle s_{\alpha'},m+q|s_\alpha,m;k,q\rangle \langle \alpha' \| B^{(k)}
    \| \alpha \rangle   
    % % %
    =  \frac{\langle s_\alpha', m+q|s_\alpha,m;k,q\rangle}{\langle s_\alpha',0|s_\alpha,0;k,0\rangle}   
    \langle \alpha',0 | B^{(k)}_0 | \alpha,0\rangle  \\ &
    % % %
    \equiv  
    %\frac{\langle s_{\alpha'},m+q|s_\alpha,m;k,q\rangle}
    %         {\langle s_{\alpha'},0|s_\alpha,0;k,0\rangle}
             \mathsf{M}_1 (s_\alpha, s_{\alpha'}, m, k, q) 
             \langle \alpha',0 | B^{(k)}_0 | \alpha,0\rangle 
             \label{eq:element_symmetry}
\end{align}
We have defined the Clebsch–Gordan ratio 
\begin{equation}
    \mathsf{M}_1(s, s', m, k, q) 
    \coloneqq \frac{\langle s', m+q|s,m;k,q\rangle}
    {\langle s',0|s,0;k,0\rangle} .
    \label{eq:M1coefficient}
\end{equation}
In Eq.~\eqref{eq:element_symmetry}, the prefactor depends on $\alpha$ and $\alpha'$ only through $s_\alpha$ and $s_{\alpha'}$. This property allows us to transform one fine-grained correlator into another easily.

The matrix-element symmetry~\eqref{eq:element_symmetry} extends to the fine-grained dynamical correlator, 
$\hat{\bar{C}}^{\rm dyn}_{A^{(k')}_{-q},  B^{(k)}_q}
(\Omega, \Delta m{=}q; \Delta s; \alpha, m)$ [Eq.~\eqref{eq_Corr_help1}]. If 
\begin{align}
    & \mathsf{M}_2(s, \Delta s, m, k, k', q) \coloneqq 
        \mathsf{M}_1(s+ \Delta s, s, m+q, k', -q)
        \mathsf{M}_1(s, s+ \Delta s, m, k, q) ,
        \label{eq:M2coefficient}
        \quad \text{then} \\ &
        % % %
    \hat{\bar{C}}^{\rm dyn}_{A^{(k')}_{-q},B^{(k)}_q}
    (\Omega, \Delta m{=}q, \Delta s; 
    \alpha, m) = 
    \mathsf{M}_2(s_\alpha, \Delta s, m, k, k', q)  \,
    \hat{\bar{C}}^{\rm dyn}_{A^{(k')}_{0},B^{(k)}_0}
    (\Omega, \Delta m{=}0, \Delta s;
    \alpha,0) .
    \label{eq:Stransform}
\end{align}
Therefore, we can deduce about general dynamical fine-grained correlators upon evaluating a correlator between spherical tensor operators' $q{=}0$ components on $\ket{\alpha, m{=}0}$.

To test the fine-grained KMS relation, we define the logarithmic ratio
\begin{equation}
    \tilde{\mathcal{{L}}}_{A^{(k')}_{-q} B^{(k)}_q} (\Omega, q, \Delta s;  \alpha,m)
    \coloneqq \ln  \left(  \frac{ 
    \hat{\bar{C}}^{\rm dyn}_{A^{(k')}_{-q} B^{(k)}_q}
                (\Omega, \Delta m{=}q, \Delta s;
\alpha, m)}
{ \hat{\bar{C}}^{\rm dyn}_{B^{(k)}_{q} A^{(k')}_{-q}}
               (-\Omega, \Delta m{=}{-q}, -\Delta s;
\alpha, m)}  \right) .
\label{eq:LogRatioFunc2}
\end{equation}
By the transformation rule~\eqref{eq:Stransform}, the log-ratio transforms as
\begin{equation}
   \tilde{\mathcal{L}}_{A^{(k')}_{-q} B^{(k)}_q} (\Omega, q, \Delta s;  \alpha,m) 
   = \mathsf{M}_3(s_\alpha, \Delta s, m; k, k', q)  
   +  \tilde{\mathcal{L}}_{A^{(k')}_{0}  B^{(k)}_0} (\Omega, 0, \Delta s;  \alpha,0) .
   \label{eq:Ltransform}
\end{equation}
We have defined the function
\begin{equation}
    \mathsf{M}_3(s, \Delta s, m; k, k', q) = \ln  \left( \frac{
    \mathsf{M}_2(s, \Delta s, m, k, k', q)}{
    \mathsf{M}_2(s, -\Delta s, m, k', k, -q)}   \right)
\end{equation}
of 8 Clebsch–Gordan coefficients.


