You will be given the following information:

<protein_sequences>
{{PROTEIN_SEQUENCES}}
</protein_sequences>

<biological_features>
{{BIOLOGICAL_FEATURES}}
</biological_features>

<activation_values>
{{ACTIVATION_VALUES}}
</activation_values>

