\subsubsection{Ridgeless Estimators}\label{RRE}

 When we consider the sub case of RRE with $p<n-1$, we set wpa1 $\bar{r} <p$, $\bar{\Psi}=0$, and $\bar{\eta} \ge c$, where $ c $ is a positive constant in Theorem \ref{thm1} result above. Let the $j$ th row of estimator of the precision matrix  be $\hat{\Theta}_{RRE,j}'$. To obtain Corollary \ref{cl5}, we use Corollary OA.2 and Corollary \ref{cl2} with $r_{w1},r_{w2}$ in Theorem \ref{thm1}  replaced with $r_{RRE-l}$ rate after Corollary OA.1 in Online Appendix. 

\begin{corollary}\label{cl5}


Set $p/n = a_{2n} \to 0$, and under Assumptions \ref{as1}-\ref{as5}, and $r_n /\delta_n \to 1$
\begin{eqnarray*}
\max_{1 \le j \le p} \| \hat{\Theta}_{RRE,j}' - \Theta_{j}' \|_2 &=& O_p \left(\max (K \sqrt{a_{2n} logp},1) \max (  \frac{\sqrt{log n + p}}{\sqrt{n }}, \frac{\sqrt{K}}{\sqrt{\bar{\xi}}})\right)\nonumber \\
&+& O_p \left( d_{2n} \max ( \frac{\sqrt{log n + p}}{\sqrt{n }}	, \frac{\sqrt{K}}{\sqrt{\bar{\xi}}})\right)\\
& + & O_p \left( \max(\frac{K^{3/2}}{n^{1/2}}, K \frac{\sqrt{logn}}{n^{1/2}})\right) = o_p (1).
\end{eqnarray*}
\end{corollary}

\begin{remark} \label{rem8}
