\begin{corollary}\label{cl6}

Under Assumptions \ref{as1}-\ref{as2}, Assumption $3^{*}(i)$ Assumptions \ref{as3}(ii)-\ref{as4}-\ref{as5}(ii),  with signal-to-noise condition $ \sqrt{K} d_{2n}/\sqrt{\bar{\xi}} \to 0$,
and $\min_{ 1 \le j \le p} re (\Sigma_{U_{-j}}) > C n$ and $\tilde{U}_{-j}$ matrix with independent entries,  
\begin{eqnarray*}
\max_{1 \le j \le p} \| \hat{\Theta}_{INT,j}' - \Theta_{INT,j}'\|_2 &= &O_p \left( \max (\frac{\sqrt{log n + n}}{\sqrt{n \delta_n}}, \frac{\sqrt{K} d_{2n}}{\sqrt{\bar{\xi}}})\right)\\
&+&O_p \left( \max(\frac{K^{3/2}}{n^{1/2}}, K \frac{\sqrt{logp)}}{n^{1/2}})\right) = o_p (1).
\end{eqnarray*}






\end{corollary}


\begin{remark}

\begin{itemize}

\item 
First of all we still get consistency with $p-1>n$,
as long as signal-to-noise ratio dominates number of factors multiplied by $d_{2n}$. This can be seen easily by $K \sqrt{logp/n} \to 0$,
