In this appendix, we only cover the proof of Theorem 2, the rest of the proofs are relegated to Online Appendix.	
Before the following proof, we proceed with three inequalities that are used for rectangular matrices. Take a generic rectangular matrix $M$ and a vector $x$.

\begin{equation}
\| M x \|_2 \le \| M \|_2 \| x\|_2,\label{i1}
\end{equation}
 by (11.4.4) of \cite{bern2018}. Then by (11.3.15) of \cite{bern2018} where for two generic rectangular matrices $M,L$ 
 \begin{equation}
 \| M L \|_2 \le \| M\|_2 \| L\|_2,\label{i2}
 \end{equation}
We form the following matrix norm inequality for a generic rectangular matrix $M: m_1 \times m_2$
\begin{eqnarray}
\| M \|_2 \le \| M \|_F &= &[\sum_{i=1}^{m_1} \sum_{j=1}^{m_2} | M_{ij} |^2 ]^{1/2} \nonumber \\
& \le & \sqrt{m_1 m_2} \max_{1 \le i \le m_1} \max_{1 \le j \le m_2} | M_{ij} |= \sqrt{m_1 m_2} \| M \|_{\infty}.\label{61}
\end{eqnarray}
where $\|.\|_F $ is the Frobenius norm and we get the first inequality by (4.4) of \cite{v2019}. 





{\bf Proof of Theorem \ref{thma}}. 

First note that $E y_{jt}= \mu_j = a_j' E f_t$, and $E Y_{-jt} = \mu_{-j} = A_{-j} E f_t$. Also see that 
\begin{equation}
y_{jt} - \mu_j= a_j' (f_t - E f_t) + u_{jt},\label{eq1}
\end{equation}
and 
\begin{equation}
Y_{-jt} - \mu_{-j}= A_{-j}  (f_t - E f_t) + U_{-jt},\label{eq2}
\end{equation}

(i). Note that we need to estimate the $j$ th main diagonal term for the precision matrix of asset returns. In that sense the key element is the reciprocal of that term which is defined in (\ref{14a}), and the population version in (OB.11). We use triangle inequality
to consider the estimation error by (\ref{14a})(OB.11)
\begin{equation}
| \tilde{\tau}_j^2 - \tau_j^2| \le | \frac{1}{n} \sum_{t=1}^n [y_{jt}^2 - E (y_{jt} - \mu_j)^2] | +
\left| [n^{-1} \sum_{t=1}^n y_{jt} Y_{-jt}'] \tilde{\alpha}_j - E (y_{jt}- \mu_j)( Y_{-jt} - \mu_{-j})'\alpha_{j}^*
\right|.\label{47}
\end{equation}
Next add and subtract to the second right side term $E [(y_{jt} - \mu_j)( Y_{-jt} - \mu_{-j})' ]\tilde{\alpha}_j$, by iid nature of data,
\begin{eqnarray}
| \tilde{\tau}_j^2 - \tau_j^2| &\le &| \frac{1}{n} \sum_{t=1}^n [y_{jt}^2 - E (y_{jt} -\mu_j)^2] |  
+ \left| n^{-1} \sum_{t=1}^n [y_{jt} Y_{-jt}' - E (y_{jt} -\mu_j) ( Y_{-jt}- \mu_{-j})' \tilde{\alpha}_j 
\right| \nonumber \\ &+& \left|E [(y_{jt} - \mu_j )(  Y_{-jt} - \mu_{-j})'] (\tilde{\alpha}_j - \alpha_{j}^*) 
\right|.\label{48}
\end{eqnarray}
Take uniform bounds over $j=1,\cdots,p$ and use Cauchy-Schwartz inequality for the second and third right side terms on (\ref{48})
\begin{eqnarray}
\max_{1 \le j \le p} | \tilde{\tau}_j^2 - \tau_j^2| &\le &
\max_{1 \le j \le p} | \frac{1}{n} \sum_{t=1}^n [y_{jt}^2 - E (y_{jt} - \mu_j) ^2] |  \nonumber \\
& + & \max_{1 \le j \le p} \| n^{-1} \sum_{t=1}^n [ y_{jt} Y_{-jt}' - E (y_{jt} - \mu_j) ( Y_{-jt} - \mu_{-j})']\|_2  \max_{1 \le j \le p} \|\tilde{\alpha}_j\|_2 \nonumber \\
& + & \max_{1 \le j \le p} \| E [(y_{jt} - \mu_j )(Y_{-jt} - \mu_{-j})'] \|_2 
\max_{1 \le j \le p} \| \tilde{\alpha}_j - \alpha_{j}^*\|_2.\label{49}
\end{eqnarray}

Each right side term in (\ref{49}) will be analyzed as a step in the proof.

{\bf Step 1.} Start with the first right side term on (\ref{49}), and by (\ref{1})
\[ y_{jt}^2 = a_j' f_t f_t' a_j + 2 a_j' f_t u_{jt} + u_{jt}^2,\]
and by Assumption \ref{as1}(iv), and using  (\ref{eq1})
\[ E (y_{jt} -\mu_j)^2 = a_j' \Sigma_f a_j + E	 (u_{jt}^2).\]
Use triangle inequality by the last two equalities, and noting $\Sigma_f:= E (f_t - E f_t )( f_t - E f_t)'$
\begin{eqnarray}
\max_{1 \le j \le p} | \frac{1}{n} \sum_{t=1}^n [y_{jt}^2 - E (y_{jt} -\mu_j)^2]|
& \le & \max_{1 \le j \le p} | a_j' [\frac{1}{n} \sum_{t=1}^n (f_t f_t'-  \Sigma_f)]a_j | \nonumber \\
& +&  \max_{1 \le j \le p} | \frac{1}{n} \sum_{t=1}^n [u_{jt}^2 - E (u_{jt}^2)]| \nonumber \\
&+& \max_{1 \le j \le p} 2 | a_j' [n^{-1}\sum_{t=1}^n f_t u_{jt} ]|.\label{50}
\end{eqnarray}
Take the first right side term in (\ref{50}) above, and use  Cauchy-Schwarz inequality first and then (\ref{i1}) 
\begin{equation}
\max_{1 \le j \le p} | a_j' [\frac{1}{n} \sum_{t=1}^n (f_t f_t'-  \Sigma_f)]a_j | \le 
\left[ \max_{1 \le j \le p} \| a_j \|_2^2 \right] \| \frac{1}{n} \sum_{t=1}^n [f_t f_t' - \Sigma_f] \|_{2}.\label{51}
\end{equation}
We consider the second term on the right side of (\ref{51}), with $F: n \times K$ matrix, 
and $ \| \Sigma_f \|_2 \le C < \infty$ by Assumption \ref{as3}(ii)
\begin{equation}
\| \frac{F'F}{n} - \Sigma_f \|_2 \le C [ \sqrt{\frac{K}{n}} + \sqrt{\frac{log n}{n}}] \| \Sigma_f \|_2,\label{pla2-1}
\end{equation}
by Lemma 23 of \cite{bbsmw21} since rows of $F$ are independent subgaussian vectors, with probability at least $1-2/n^c$ via Assumption \ref{as1}(iii), Assumption \ref{as4}(ii), and note that $K < n$. By Assumption \ref{as4}(iii)
\begin{equation}
\max_{1 \le j \le p} \| a_j \|_2^2 \le C K.\label{53} 
\end{equation}
Use (\ref{pla2-1})-(\ref{53}) in (\ref{51}) and Assumption \ref{as3}  to have
\begin{equation}
\max_{1 \le j \le p} | a_j' (\frac{1}{n} \sum_{t=1}^n [f_t f_t' - \Sigma_f ] a_j | = O_p \left(\max(\frac{K^{3/2}}{n^{1/2}}, K \sqrt{\frac{logn}{n}})\right).\label{54}
\end{equation}
Then in (\ref{50}) consider the second right side term
\begin{equation}
\max_{1 \le j \le p} | \frac{1}{n} \sum_{t=1}^n [u_{jt}^2 - E (u_{jt}^2)]|= O_p (\sqrt{\frac{log p}{n}}).\label{55}
\end{equation}
We now show how we obtain (\ref{55}).
Note that by Corollary 2.8.3 of \cite{v2019}, for $t_1>0$, and the union bound 
\[ P \left[ \max_{1 \le j_1 \le p } \max_{1 \le j_2 \le p} | \frac{1}{n} \sum_{t=1}^n [u_{j_1,t} u_{j_2,t} - E (u_{j_1,t} u_{j_2,t})]|>t_1
\right]
\le p^2 exp \left(-c min(\frac{t_1^2}{C_{\psi}^2}, \frac{t_1}{C_{\psi}})n\right),\]
 where we use $u_{j_1,t}$ and $u_{j_2,t}$ are both subgaussian random variables, so $u_{j_1,t} u_{j_2,t}$ are subexponential random variable (independent across $t=1,\cdots,n$) by Lemma 2.7.7 of \cite{v2019} and exercise 2.7.10 of \cite{v2019} shows centered subexponential are also subexponential random variables, and  we have 
 \[ \max_{1 \le j_1 \le p} \max_{1 \le j_2 \le p}  \| u_{j_1,t} u_{j_2,t} \|_{\psi} \le C_{\psi} < \infty\]
  where 
$C_{\psi}$ are the upper bound constant  for the subexponential norm in Definition 2.7.5 of \cite{v2019}. Next
$
2 p^2 exp \left(-c min(\frac{t_1}{C_{\psi}^2}, \frac{t_1}{C_{\psi}}) n \right)  =  exp \left(log (2 p^2) - c \frac{t_1^2 n}{C_{\psi}^2}\right)$,
with $t_1:= C \frac{\sqrt{log p}}{\sqrt{n}}$ and with sufficiently large $n$ (i.e.$ \sqrt{n} \ge \frac{C}{C_{\psi}} (log p)^{1/2}$). Set 
$ c_{\psi}:= c \frac{C^2}{C_{\psi}^2} - 2 > 0$
 to have 
$ exp [ log 2 + 2 log p - c \frac{C^2}{C_{\psi}^2} log p ] = \frac{2}{p^{c_{\psi}}}.$
Then
\[ P \left(\max_{1 \le j_1 \le p } \max_{ 1 \le j_2 \le p} | \frac{1}{n} \sum_{t=1}^n u_{j_1,t} u_{j_2,t} - E u_{j_1,t} u_{j_2,t}| > C \frac{\sqrt{log p}}{\sqrt{n}}
\right) \le \frac{2}{p^{c_{\psi}}}.\]
The asymptotics in (\ref{55}) are obtained after taking $n \to \infty, p \to \infty$. Consider the third right side term in (\ref{50}). Lemma 2.7.7  and Corollary 2.8.3 of \cite{v2019} together with Assumptions \ref{as1}, \ref{as4}, and   Holder's inequality give
\begin{eqnarray}
\max_{1 \le j \le p} | a_j' (\frac{1}{n}\sum_{t=1}^n f_t u_{jt} )| & \le & \max_{1 \le j \le p} \| a_j \|_1 \max_{1 \le j \le p} \| \frac{1}{n} \sum_{t=1}^n f_t u_{jt} \|_{\infty} \nonumber \\
& = & O_p ( K \sqrt{\frac{log (Kp)}{n}}) = O_p ( \frac{K \sqrt{log p}}{\sqrt{n}}),\label{55a} 
\end{eqnarray}
where the last equality uses $p-1>K$. By (\ref{54})-(\ref{55a}) we have the first right side term in (\ref{49})
\begin{equation}
\max_{1 \le j \le p} | \frac{1}{n} \sum_{t=1}^n [y_{jt}^2 - E (y_{jt} - \mu_j)^2] | = O_p \left( \max( \frac{K^{3/2}}{n^{1/2}}, K \sqrt{\frac{\max(logp, log n)}{n}}) \right).\label{55ab}
\end{equation}



{\bf Step 2.}  We consider the second right side term in (\ref{49}). By (\ref{1})(\ref{2}) and Assumption \ref{as1}(iv)
\[ y_{jt} Y_{-jt}' = a_j' f_t f_t' A_{-j}' + a_j' f_t U_{-jt}' + u_{jt} f_t' A_{-j}' + u_{jt} U_{-jt}',\]
and by (\ref{eq1}) (\ref{eq2})
\[  E (y_{jt} - \mu_j)( Y_{-jt} - \mu_{-j})'= a_j' \Sigma_f  A_{-j}'.\]
Use these last two equations 
\begin{eqnarray}
& & \max_{1 \le j \le p} \| \frac{1}{n} \sum_{t=1}^n [y_{jt} Y_{-jt}' - E (y_{jt} - \mu_j)( Y_{-jt} - \mu_{-j})'] \|_2 \le  
\max_{1 \le j \le p} \| a_j'\left( \frac{1}{n} \sum_{t=1}^n [ f_t f_t' - \Sigma_f ] \right)A_{-j}' \|_2 \nonumber \\
& +& \max_{1 \le j \le p} \|( \frac{1}{n} \sum_{t=1}^n u_{jt} f_t') A_{-j}' \|_2 
+ \max_{1 \le j \le p} \| a_j' ( \frac{1}{n} \sum_{t=1}^n f_t U_{-jt}' ) \|_2 
 +  \max_{ 1 \le j \le p} \| \frac{1}{n} \sum_{t=1}^n u_{jt} U_{-jt}' \|_2.\label{58} 
\end{eqnarray}
Consider the first term on the right side of (\ref{58}) by (\ref{i1})(\ref{i2})
 \begin{eqnarray}
 & & \max_{1 \le j \le p} \| a_j' ( \frac{1}{n} \sum_{t=1}^n [f_t f_t' - \Sigma_f ] A_{-j}' \|_2 
\le \max_{1 \le j \le p} \| a_j \|_2   
 \max_{1 \le j \le p} 
\left\| \left(\frac{1}{n} \sum_{t=1}^n [ f_t f_t' - \Sigma_f ]\right)
A_{-j}' \right\|_2 \nonumber \\
& \le &  ( \max_{1 \le j \le p} \| a_j \|_2 )\| \frac{1}{n} \sum_{t=1}^n [ f_t f_t' - \Sigma_f]\|_2 
 \times  (\max_{1 \le j \le p} \| A_{-j} ' \|_2) \nonumber \\
& = & O (K^{1/2}) O_p ( \max (\frac{K^{1/2}}{n^{1/2}}, \frac{\sqrt{log n}}{n^{1/2}})) O (d_{1n}) 
 =  O_p ( max (\frac{K d_{1n}}{n^{1/2}}, \frac{ d_{1n} \sqrt{K log n}}{n^{1/2}})),\label{58a}
\end{eqnarray}
and the rates are by (\ref{pla2-1})(\ref{53}) and Assumption \ref{as3}. Then consider the second term on the right side of (\ref{58})


\begin{eqnarray}
\max_{1 \le j \le p} \|( \frac{1}{n} \sum_{t=1}^n u_{jt} f_t') A_{-j}' \|_2 & \le & \max_{1 \le j \le p} \| ( \frac{1}{n} \sum_{t=1}^n u_{jt} f_t')\|_2 \max_{1 \le j \le p} \| A_{-j}' \|_2 \nonumber \\
& \le & \sqrt{K} \max_{1 \le j \le p} \| ( \frac{1}{n} \sum_{t=1}^n u_{jt} f_t')\|_{\infty}  \max_{1 \le j \le p} \| A_{-j}' \|_2 \nonumber \\
& = & O_p (\sqrt{K} \frac{\sqrt{log p}}{\sqrt{n}}) O (d_{1n}),\label{60} 
\end{eqnarray}
where we use (\ref{i1}) for the first inequality since $u_{jt} f_t': 1 \times K$ vector and $A_{-j}': K \times p-1$ matrix, and the second inequality is by simple vector norm inequality tying $l_2, l_{\infty}$ vector norms, and the rates are by Assumption \ref{as3}(iii) $\max_{1 \le j \le p} \| A_{-j} ' \|_2 = O (d_{1n})$ and Lemma 2.7.7 and Corollary 2.8.3. of \cite{v2019} which provides $\| n^{-1} \sum_{t=1}^n u_{jt} f_t' \|_{\infty} = O_p (\sqrt{logp/n})$.
 Now third term on the right side of (\ref{58})



