{\bf  Proof of Theorem 1}:

 	Using (4) and (11) we get 
	\[ \tilde{\alpha}_j - \alpha_{j}^* = \hat{B} (Y_{-j} \hat{B})^+ F a_j + \hat{B} (Y_{-j} \hat{B})^+ u_j - \alpha_{j}^*.\]

	Then we have the following inequality
	\begin{equation}
	\| \tilde{\alpha}_j - \alpha_{j}^* \|_2^2   \le  3 \| \hat{B} (Y_{-j} \hat{B})^+ u_j \|_2^2 + 
	3 \| \hat{B} (Y_{-j} \hat{B})^+ F a_j \|_2^2 
	 +  3 \| \alpha_{j}^* \|_2^2.\label{pl1-gl1}	
	\end{equation}

	The proof  contains a detailed transformation of results that can be obtained in linear regression framework to precision matrix
estimation needed here (to make connection with linear regression clearer and overall exposition easier to follow, we often refer to Lemma 17 and related results of \cite{bbsmw21}. Since we ultimately aim to use our results for high dimensional outcomes, we need them to hold uniformly over $j = 1, \dots, p,$. It is important to note that this is in striking contrast with pointwise results (as are those from, e.g., \cite{bbsmw21} that would be applicable to only one outcome.    Each of the right side terms  in (\ref{pl1-gl1}) will be analyzed in each of Steps 1-3.


	{\bf Step 1.} Start with the first right side term in (\ref{pl1-gl1})
	\begin{equation}
	\| \hat{B} (Y_{-j} \hat{B})^+ u_j \|_2^2 = u_j' M_j u_j,\label{pl1-gl2}
	\end{equation}
	with $M_j: n \times  n$ matrix defined as 
	\begin{equation}
	M_j:= (Y_{-j } \hat{B})^{+'} \hat{B}' \hat{B} (Y_{-j } \hat{B})^+.\label{pl1-gl2a}
	\end{equation}




%%%%%%%%%%%%proof is changed after this
To simplify the proof, 
, we consider  the following trace term: 
		$ tr (M_j)= tr [ (Y_{-j} \hat{B})^{+'} \hat{B}' \hat{B} (Y_{-j} \hat{B})^+].$
		First of all 
		\begin{eqnarray}
		tr [ M_j] & \le & rank (M_j) \| M_j \|_2 = rank (Y_{-j} \hat{B})^+  \| M_j \|_2 \nonumber \\
		& = & rank (Y_{-j } \hat{B}) \| M_j \|_2  =  rank (Y_{-j} P_{\hat{B}}) \| M_j \|_2, = \hat{r}_j \| M_j \|_2 \label{pl1-gl5}
		\end{eqnarray}
		where the first inequality is due to $M_j$ being positive semidefinite, and $n \times n$ matrix and Exercise 7.49 of \cite{abamag2005}, and the first equality is by Exercise 8.27a and 4.24a of \cite{abamag2005}, and the second equality is by Exercise 10.28 of \cite{abamag2005}, and the third equality is again by Exercises 4.13d, 4.15b, 4.25b, and 10.28 of \cite{abamag2005} with $P_{\hat{B}} = \hat{B} \hat{B}^+$  in p.8 of \cite{bbsmw21}, and the last equality is just the definition of the complexity $\hat{r}_j$. Now we consider, as proved in (44) of \cite{bbsmw21} 
		\begin{equation}
		\| M_j \|_2 \le (n \hat{\eta}_j)^{-1},\label{pl1-gl6}
				\end{equation}
		where $\hat{\eta}_j:= \hat{\sigma}_{\hat{r}_j}^2 (Y_{-j} P_{\hat{B}})/n$ which is the $\hat{r}_j$ th largest singular value, squared, of the matrix $Y_{-j} P_{\hat{B}}$, and divided by $n$.






Define $C_p>0$ a positive constant.
Then  by (\ref{pl1-gl5})(\ref{pl1-gl6}) and $\bar{\eta}$, $\bar{r}$ definitions
\begin{equation}
\gamma_e^2 \sigma_{j}^2 [ 2 C_p\| M_j \|_2 log n + tr (M_j)]
\le \gamma_e^2 \sigma^2 [ \frac{2 C_p log n }{n \bar{\eta}} + \frac{\bar{r}}{n \bar{\eta}}]  .\label{pt1-s1}  
\end{equation}
Next, define the following events 
\begin{equation}
    E_{1j}:=\{u_j' M u_j \le 2 \gamma_e^2 \sigma_{j}^2 [ 2 C_p \| M_j \|_2 log n + tr (M_j) ]\},\label{pl1-gl3}\end{equation}
    and 
    \begin{equation}
        \bar{E}_{1j}:=\{u_j' M u_j \le 2 \gamma_e^2 \sigma^2 [ \frac{2 C_p logn }{n \bar{\eta}}+ \frac{\bar{r}}{n \bar{\eta}}]\}.\label{pt1-s1a}
        \end{equation} with 
        \begin{equation}
        \bar{E}_1:= \{\max_{1\le j \le p} u_j' M u_j \le 2 \gamma_e^2 \sigma^2 [ \frac{2 C_p logn }{n \bar{\eta}}+ \frac{\bar{r}}{n \bar{\eta}}]\}.\label{pt1-s2}
        \end{equation}
        By (\ref{pt1-s1})
        \begin{equation}
        E_{1j} \subseteq \bar{E}_{1j}.\label{pt1-s1b}
            \end{equation}
        Clearly, since the upper bounds of the events $ \bar{E}_{1j}, \bar{E}_1$ are the same 
        \begin{equation}
            \cap_{j=1}^p \bar{E}_{1j} = \bar{E}_1.\label{pt1-s1c}
        \end{equation}
        By (\ref{pt1-s1b})(\ref{pt1-s1c})
        \begin{equation}
            \cap_{j=1}^p E_{1j}  \subseteq \bar{E_1}.\label{pt1-s1d}
        \end{equation}
        See  that  by $E_{1j}^c$ as the complement of $E_{1j}$
        \begin{equation}
            P (\cap_{j=1}^p  E_{1j} ) + P (\cup_{j=1}^p  E_{1j}^c) =1.\label{pt1-s2a}
        \end{equation}
        Note that  we have, by (\ref{pt1-s1d}) 
        \begin{equation}
          P (\bar{E}_1) \ge P (\cap_{j=1}^p  E_{1j} )\label{pt1-s1e}
          \end{equation}
so by (\ref{pt1-s2a})(\ref{pt1-s1e}) and 
\begin{eqnarray}
     P (\bar{E}_1) &\ge& 1 - P (\cup_{j=1}^p E_{1j}^c)\nonumber \\
     & \ge & 1 - \sum_{j=1}^p P (E_{1j}^c).\label{pt1-s1f}
     \end{eqnarray}
  Now we calculate the sum of the upper bound probability of $E_{1j}^c$, across $j$.
Note that $u_j$ is a   subgaussian vector, and independent of $Y_{-j}$, and $\hat{B}$ by Assumption 1 and the definition of $\hat{B}$,  with $M_j$ being a symmetric positive semi-definite matrix. 
So $M_j$ is independent of $u_j$.
Then 
Lemma \ref{lb1} (with $t=C_p log n $, $H=M_j, \zeta=u_j$, conditional on $M_j$) allows us to write
\begin{equation}
    P (E_{1j}^c| M_j) = 
    P\left( u_j' M u_j > 2 \gamma_e^2 \sigma_{j}^2 [ 2 C_p \| M_j \|_2 log n + tr (M_j) ] | M_j\right) \le \frac{1}{n^{C_p}}.\label{pt1-s5}
    \end{equation}

Next, use the union bound and by Assumption 3, using $log p \le  (\frac{C_p}{2}) log n$
\begin{eqnarray}
\sum_{j=1}^p P (E_{1j}^c) & = & \sum_{j=1}^p P (E_{1j}^c | M_j) P (M_j) 
\le \sum_{j=1}^p P (E_{1j}^c | M_j) \nonumber \\
&\le & 
exp (logp - C_p logn) \le exp (-\frac{C_p}{2} log n)
= \frac{1}{n^{C_p/2}}
.\label{pt1-s6}        
\end{eqnarray}
Use (\ref{pt1-s1f})(\ref{pt1-s6}) in (\ref{pl1-gl2})(\ref{pt1-s2})
\begin{equation}
    P \left( \max_{1 \le j \le p} \| \hat{B} (Y_{-j} \hat{B})^+ u_j \|_2^2 \le 2 
     \gamma_e^2 \sigma^2 [ \frac{2 C_p logn }{n \bar{\eta}}+ \frac{\bar{r}}{n \bar{\eta}}]    \right) \ge  1 - \frac{1}{n^{C_p/2}}.\label{pt1-s7}
\end{equation}




		{\bf Step 2.} Now consider the second term on the right side of (\ref{pl1-gl1}). Keeping in mind that,   $A_{-j}' (A_{-j}^{+})' = I_K$ and recalling on (5), while setting 
        $M_{\hat{B}}:=I_{p-1}- P_{\hat{B}}$, we further have		
        \begin{eqnarray*}
		&&\hat{B} (Y_{-j} \hat{B})^+ F  =  \hat{B} (Y_{-j} \hat{B})^+ F A_{-j}' A_{-j}^{+'} = \hat{B} (Y_{-j} \hat{B})^+ (Y_{-j} - U_{-j}) A_{-j}^{+'} \\
		& = & \hat{B} (Y_{-j} \hat{B})^+ Y_{-j} P_{\hat{B}} A_{-j}^{+'} + 	\hat{B} (Y_{-j} \hat{B})^+ Y_{-j} M_{\hat{B}} A_{-j}^{+'} 
		 -  	\hat{B} (Y_{-j} \hat{B})^+  U_{-j}	A_{j}^{+'}
			\end{eqnarray*}
			Use  simple inequality $(a+b+c)^2 \le 3a^2 + 3b^2 + 3c^2$, 
			\begin{eqnarray}
& & \| \hat{B} (Y_{-j} \hat{B})^+ F a_j \|_2^2 \le  3 \| \hat{B} (Y_{-j} \hat{B})^+ Y_{-j} P_{\hat{B}} A_{-j}^{+'} a_j \|_2^2 \nonumber \\
& + & 3 \| \hat{B} (Y_{-j} \hat{B})^+ Y_{-j} (I_{p-1} - P_{\hat{B}}) A_{-j}^{+'} a_j \|_2^2 
+ 3 \| \hat{B} (Y_{-j} \hat{B})^+  U_{-j}	A_{j}^{+'} a_j \|_2^2.\label{pl1-gl7a}
\end{eqnarray}

In Steps 2a, 2b, and 2c below, we separetely analyze each of the three terms on the right side of (\ref{pl1-gl7a}).

{\bf Step 2a.} So  
\begin{equation}
\| \hat{B} (Y_{-j} \hat{B})^+ Y_{-j} P_{\hat{B}} A_{-j}^{+'} a_j \|_2^2 		\le \| \hat{B} (Y_{-j} \hat{B})^+ Y_{-j} P_{\hat{B}}\|_2^2 \| A_{-j}^{+'} a_j \|_2^2.\label{pl1-gl8}		
		\end{equation}
		Note that we can write the first term on the right side of (\ref{pl1-gl8}) as 
		\begin{equation}
		\| \hat{B} (Y_{-j} \hat{B})^+ Y_{-j} P_{\hat{B}}\|_2		= \| \hat{B} (\hat{B}' Y_{-j}' Y_{-j} \hat{B})^+ \hat{B}' Y_{-j}' Y_{-j} P_{\hat{B}} \|_2, \label{pl1-gl9}
		\end{equation}
		where we use Moore-Penrose inverse rule (134) in \cite{bsmw22} which is for a rectangular matrix $S$, we have  $(S'S)^+ S' = S^+$, which we input 
		$S= Y_{-j} \hat{B}$ in our case above.
		To simplify the expressions see that by the proof of Lemma 15 of \cite{bbsmw21} $P_{\hat{B}}= V_1 V_1',$ where $\hat{B}= V_1 D V_2'$ is a singular value decomposition.   
		$V_1,V_2$ are orthonormal matrices and with dimensions of $p-1 \times r_0, q \times r_0$ respectively,  and  $D$ is a  $r_0$ dimensional diagonal matrix, and the  rank of $(\hat{B}) = r_0$.
		Rewrite right side of (\ref{pl1-gl9}) as 
		\begin{equation}
		\| \hat{B} (Y_{-j} \hat{B})^+ Y_{-j} P_{\hat{B}}\|_2 = \| V_1 D V_2' (V_2 D V_1' Y_{-j}' Y_{-j} V_1 D V_2')^+ V_2D V_1' Y_{-j}' Y_{-j} V_1 V_1' \|_2.\label{pl1-gl10}				\end{equation}
		Then in (\ref{pl1-gl10}) right side see that 
		\begin{equation}
		(V_2 D V_1' Y_{-j}' Y_{-j} V_1 D V_2')^+	= V_2 D^{-1} (V_1' Y_{-j}' Y_{-j} V_1)^+ D^{-1} V_2',\label{pl1-gl11}
		\end{equation}
	which is shown in the proof of Lemma 15 of \cite{bbsmw21}.	 Then use (\ref{pl1-gl11}) in (\ref{pl1-gl10}), $V_2'V_2=I_{r_0}$
		\begin{eqnarray*}
		V_1 D V_2' (V_2 D V_1' Y_{-j}' Y_{-j} V_1 D V_2')^+ V_2 D V_1' & = & V_1 D V_2' V_2 D^{-1} [V_1' Y_{-j}' Y_{-j} V_1]^+ D^{-1} V_2' V_2 D V_1' \\
		& = & V_1 [ V_1' Y_{-j}' Y_{-j} V_1]^+ V_1'		
		\end{eqnarray*}
		Use the last expression in (\ref{pl1-gl10}) right side 
		\[ 
		\| V_1 D V_2' (V_2 D V_1' Y_{-j}' Y_{-j} V_1 D V_2')^+ V_2DV_1' Y_{-j}' Y_{-j} V_1 V_1' \|_2	= \| V_1 [V_1' Y_{-j}' Y_{-j} V_1]^+ V_1' Y_{-j} Y_{-j}' V_1 V_1' \|_2.\]	
		Then clearly since $V_1: p-1 \times r_0$ matrix, and Exercise 10.26 of \cite{abamag2005} shows $[V_1' Y_{-j}' Y_{-j} V_1]^+ V_1' Y_{-j}' Y_{-j} V_1	$ is a symmetric idempotent matrix and all idempotent matrices eigenvalues are either 0 or 1, and since $V_1' V_1 =I_{r_0}$ 
			\[ \| V_1 [V_1' Y_{-j}' Y_{-j} V_1]^+ V_1' Y_{-j}' Y_{-j} V_1 V_1' \|_2 \le \| V_1\|_2 \| [V_1' Y_{-j}' Y_{-j} V_1]^+ V_1' Y_{-j}' Y_{-j} V_1	\|_2 \| V_1' \|_2 \le 1.\]	
			So use this last inequality in (\ref{pl1-gl10})	
			\begin{equation}
		\| \hat{B} (Y_{-j} \hat{B})^+ Y_{-j} P_{\hat{B}}\|_2 \le 1,\label{pl1-gl12}
		\end{equation}	
		Next part of the proof simplifies certain expressions in Lemma 17  of \cite{bbsmw21} and ties that to signal-to-noise ratio.
		Now consider the following term which is common in almost all terms on upper bounds of our estimator, and will link to signal to noise ratio, which is the second term on the right side of (\ref{pl1-gl8}),
		$ \| A_{-j}^{+'} a_j \|_2^2 = a_j' A_{-j}^+ A_{-j}^{+'} a_j = a_j' (A_{-j}' A_{-j})^{-1} a_j,$
		since $A_{-j}^{+}= (A_{-j}' A_{-j})^{-1} A_{-j}^{'}$ with $p-1 > K$. Next 
		 \begin{eqnarray}
		 a_j' A_{-j}^+ (A_{-j}^+)' a_j & = & a_j' \Sigma_f^{1/2} (\Sigma_f^{1/2} A_{-j}' A_{-j} \Sigma_f^{1/2})^{-1} \Sigma_f^{1/2} a_j \nonumber \\
		 & \le & \frac{a_j' \Sigma_f a_j}{\lambda_K (A_{-j} \Sigma_f A_{-j}')},\label{31a}
\end{eqnarray}
where we use first Rayleigh inequality on p.182 of \cite{abamag2005} and then Theorem 2.6.3b of \cite{hj2013}, where $\lambda_K(.)$ is the $K$ th largest eigenvalue for the matrix 
$A_{-j} \Sigma_f A_{-j}': p-1 \times p-1$.  By (6)(7), we try to rewrite (\ref{31a}) right-side. 
\begin{eqnarray}
\lambda_K (A_{-j}' \Sigma_f A_{-j}) & = &\left[ \frac{\lambda_K (A_{-j}' \Sigma_f A_{-j})}{\| \Sigma_{U,-j} \|_2}\right] \| \Sigma_{U,-j} \|_2 \nonumber \\
& = & \xi_j \| \Sigma_{U,-j} \|_2 \ge \bar{\xi} \| \Sigma_{U,-j} \|_2 \nonumber \\
& \ge & \bar{\xi} \delta_n,\label{45a}
\end{eqnarray}
where we use $\delta_n:= \min_{1 \le j \le p} \| \Sigma_{U,-j} \|_2  \ge  c >0$ by Assumption 2(ii), where $\delta_n$ is non-decreasing in $n$.
Then by $\max_{ 1 \le j \le p} \max_{1 \le k \le K} | a_{jk} | \le C < \infty$, with $a_{jk}$ as the $k$ th element of row $a_j$ in $A$,  which is Assumption 4(iii)
\begin{equation}
a_j' \Sigma_f a_j \le \| a_j \|_2^2 Eigmax (\Sigma_f) \le C K,\label{46ab}
\end{equation}
by $Eigmax (\Sigma_f) \le C < \infty$ Assumption 3. So the first term on the right side of (\ref{31a}) can be bounded as  as 
\begin{equation}
\max_{1 \le j \le p} \| A_{-j}^{+'} a_j \|_2^2 =\max_{1 \le j \le p}  \left[\frac{ (a_j' \Sigma_f a_j)}{\lambda_K (A_{-j} \Sigma_f A_{-j}')} \right]\le \frac{ C K}{\bar{\xi} \delta_n}.\label{pl1-gl13}
\end{equation}	
Clearly by (\ref{pl1-gl12})(\ref{pl1-gl13}) in (\ref{pl1-gl8})
	\begin{equation}
\max_{1 \le j \le p} \| \hat{B} (Y_{-j} \hat{B})^+ Y_{-j} P_{\hat{B}} A_{-j}^{+'} a_j \|_2^2 		\le 	\frac{ C K}{\bar{\xi} \delta_n}.\label{pl1-gl13a}
\end{equation}					


{\bf Step 2b.}	Take the second term on the right side of (\ref{pl1-gl7a})

\begin{equation}
\| \hat{B} (Y_{-j} \hat{B})^+ Y_{-j} (I_{p-1} - P_{\hat{B}}) A_{-j}^{+'} a_j \|_2^2 \le \| \hat{B} (Y_{-j} \hat{B})^+ \|_2^2 
\| Y_{-j} (I_{p-1} - P_{\hat{B}}) A_{-j}^{+'} a_j \|_2^2.\label{pl1-gl14}
\end{equation}
See that the first term on the right side in (\ref{pl1-gl14})  by $\| S_b \|_2^2 = \| S_b'S_b \|_2$ for a rectangular matrix $S_b:=\hat{B} (Y_{-j} \hat{B})^+$ and $M_j$ definition in (\ref{pl1-gl2a})
\begin{equation}
\| \hat{B} (Y_{-j} \hat{B})^+ \|_2^2  = \| M_j \|_2 \le \frac{1}{n \hat{\eta}_j},\label{pl1-gl15}
\end{equation}
where the last inequality is by (\ref{pl1-gl6}). Then by definition of $\hat{\Psi}_j$ in (17)
\begin{equation}
\| Y_{-j} (I_{p-1} - P_{\hat{B}}) \|_2^2 = \sigma_1^2 [(Y_{-j} (I_{p-1} - P_{\hat{B}})] = n \hat{\Psi}_j.\label{pl1-gl16}
\end{equation}
Now consider (\ref{pl1-gl13})(\ref{pl1-gl15})(\ref{pl1-gl16}) on the second term-right side of (\ref{pl1-gl7a}), with 
\[ \bar{\Psi}:= \max_{1 \le j \le p} \hat{\Psi}_j, \bar{\eta}:=\min_{1 \le j \le p} \hat{\eta}_j,\]
 with $\hat{\eta}_j$ defined in (16)
\begin{equation}
\max_{1 \le j \le p}
\| \hat{B} (Y_{-j} \hat{B})^+ Y_{-j} (I_{p-1} - P_{\hat{B}}) A_{-j}^{+'} a_j \|_2^2 \le C \left(\frac{\bar{\Psi}}{\bar{\eta}}\right) \left( \frac{K}{\bar{\xi} \delta_n}
\right).\label{pl1-gl17}
\end{equation}



{\bf Step 2c.} Consider the third term on the right side of (\ref{pl1-gl7a})

\begin{equation}
\| \hat{B} (Y_{-j} \hat{B})^+  U_{-j}	A_{j}^{+'} a_j \|_2^2 \le \| \hat{B} (Y_{-j} \hat{B})^+ \|_2^2  \| U_{-j}	A_{j}^{+'} a_j \|_2^2,\label{pl1-gl18}	
\end{equation}
where we analyze the following on the right side of (\ref{pl1-gl18}): $
 \| U_{-j}	A_{j}^{+'} a_j \|_2^2 = a_j' A_{-j}^+ U_{-j} U_{-j}' A_{-j}^{+'} a_j.$ Define $\gamma_{e,j}^2 = \gamma_w^2 a_j' A_{j}^+ \Sigma_{U,-j} A_{j}^{+'} a_j$. Now we simplify $\gamma_{e,j}^2$ term. See that, uniformly over $j$, by Assumption 2 and (\ref{pl1-gl13}) 
  \begin{eqnarray}
\max_{1 \le j \le p}  \gamma_w^2 a_j' A_{j}^+ \Sigma_{U,-j} A_{j}^{+'} a_j & \le & [max_{1 \le j \le p} Eigmax (\Sigma_{U,-j})] [\max_{1 \le j \le p}
\gamma_w^2 a_j' A_{j}^{+} A_{j}^{+'} a_j] \nonumber \\
& \le & \frac{\gamma_w^2 C r_n K }{\bar{\xi} \delta_n}.\label{pl1-gl20}
\end{eqnarray}

Then define the events
\begin{equation}
E_{2j}:= \{ \|U_{-j} A_{-j}^{+'} a_j \|_2^2 \le (n + 2 C_p logn + 2 \sqrt{ C_p n log n} )\gamma_{e,j}^2 \}\label{pt1-s20}
\end{equation}
and 
\begin{equation}
    \bar{E}_{2j}:= \{ \|U_{-j} A_{-j}^{+'} a_j \|_2^2 \le (n+ 2 C_p log n + 
    2 \sqrt{ C_p n logn }) \frac{C \gamma_w^2 r_n K }{\bar{\xi} \delta_n} \}.\label{pt1-s21}
    \end{equation}
    By (\ref{pl1-gl20}) and the explanations above that equation, with (\ref{pt1-s20})(\ref{pt1-s21})
    \begin{equation}
        E_{2j} \subseteq \bar{E}_{2j}.\label{pt2c-1}
    \end{equation}
Next, define 
\begin{equation}
    \bar{E}_2:= \{ \max_{1 \le j \le p} \|U_{-j} A_{-j}^{+'} a_j \|_2^2 \le (n+ 2 C_p log n + 
    2 \sqrt{ C_p n logn }) \frac{C \gamma_w^2 r_n K }{\bar{\xi} \delta_n} \}.\label{pt2c-2}
    \end{equation}
    See that by definitions in (\ref{pt1-s21})(\ref{pt2c-2})
    \begin{equation}
        \cap_{j=1}^p \bar{E}_{2j} = \bar{E}_2.\label{pt2c-3}
    \end{equation}
    Then by (\ref{pt2c-1})(\ref{pt2c-3})
    \begin{equation}
        \cap_{j=1}^p E_{2j} \subseteq \bar{E}_2.\label{pt2c-4}
    \end{equation}
Then by (\ref{pt2c-4})
    \begin{equation}
 P (\bar{E}_2)  \ge  
 P ( \cap_{j=1}^p E_{2j}) 
 =  1 - P ( \cup E_{2j}^c) 
 \ge  1 - \sum_{j=1}^p P (E_{2j}^c).\label{pt1-s22}
    \end{equation}


 Since $U_{-j} A_{-j}^{+'} a_j$ is  $\gamma_w \sqrt{a_j' A_{-j}^+ \Sigma_{U,-j} A_{-j}^{+'} a_j}$ subgaussian vector for each $j=1,\cdots,p$ via Assumption 4, apply Lemma \ref{lb1}
 with $\epsilon_j:= U_{-j} A_{j}^{+'} a_j$ and $H:=I_n$ and $\gamma_{e,j}^2 = \gamma_w^2 a_j' A_{j}^+ \Sigma_{U,-j} A_{j}^{+'} a_j$ with $t=C_p logn $
 \begin{equation}
 P [ \| U_{-j} A_{-j}^{+'} a_j \|_2^2 > (n + 2 C_p logn + 2 \sqrt{C_p n log n} )\gamma_{e,j}^2] \le 1/n^{C_p}.\label{pl1-gl19}
 \end{equation}
 Then take the union bound and with Assumption 3,  $log p \le  \frac{C_p}{2} logn$
 \begin{equation}
     \sum_{j=1}^p P (E_{2j}^c) \le exp (log p - C_p log n) 
     \le exp ( \frac{-C_p}{2} log n) = \frac{1}{n^{C_p/2}}.\label{pt1-s23}
 \end{equation}
 Next use  (\ref{pt1-s22})(\ref{pt1-s23})(\ref{pt2c-2})
 \begin{equation}
 P ( \max_{1 \le j \le p} \| U_{-j} A_{-j}^{+'} a_j \|_2^2 \le 
(n+ 2 C_p log n + 
