	In this part, we provide a precision matrix formula.  Different versions with time series, and for second moments of the regressor matrix can also be found in \cite{caner2019}, \cite{canerkock2018}. Its relation to a hidden factor model context is established here for the first time in the literature and in detail. We follow matrix algebra and establish a formula for each row of the precision matrix.  This relation will be essential to build up our estimator. Define all assets in the portfolio  as  $y_t=(y_{jt}, Y_{-jt}')': p \times 1$. In case of $j=3$, this represents $y_{3t}$ in the third cell in the vector $y_t$ and $Y_{-3t}$ represents elements $1,2, 4,\cdots,p$ in $y_t$.   

	{\bf Proof of Lemma 1}.
	 We will provide formula for $j$ th row and then stack all rows to get an expression. Before that define $\Sigma_{j,j}:= E [(y_{jt}-\mu_j)^2]$ and $\Sigma_{j,-j}:=E [(y_{jt} -\mu_j) (Y_{-jt}- \mu_{-j})']: 1 \times p-1$ and represents $j$ th row of $\Sigma$ with $j$ th element missing, and 
	by symmetricity of $\Sigma$, $\Sigma_{j,-j}=(\Sigma_{-j,j})'$. Specifically,  define $\Sigma_{-j,j}:=E [ (Y_{-jt} - \mu_{-j}) ( y_{jt} - \mu_j) ]: p-1 \times 1$, as the $j$ th column of $\Sigma$ where $j$ th element is missing. In the same way we define $\Sigma_{-j,-j}:= E [ (Y_{-jt} - \mu_{-j})  (Y_{-jt} - \mu_{-j})']: p-1 \times p-1$ where this matrix is $j$ the row and column deleted from $\Sigma$. By Section 2.1 of \cite{yuan2010},  the main diagonal elements are given by  the scalar
	\begin{equation}
	\Theta_{j,j}:= ( \Sigma_{j,j}- \Sigma_{j,-j} \Sigma_{-j, -j}^{-1} \Sigma_{-j,j})^{-1}.\label{5}
	\end{equation}
	and the $j$ th row without the $j$ th element is:
	\begin{equation}
	\Theta_{j,-j}:=- \Theta_{j,j} \Sigma_{j,-j} \Sigma_{-j,-j}^{-1}.\label{6}
	\end{equation}
		Now we relate these quantities to a linear regression context. Define the following  minimizer
	$ \alpha_{j}^*:= argmin_{\alpha_{j} \in R^{p-1}} E [ (y_{jt} - \mu_j)  - (Y_{-jt} - \mu_{-j})' \alpha_{j}]^2,$
	with given zero mean $(y_{jt}-\mu_j ), (Y_{-jt} - \mu_{-j})$ and finite second moments for $y_{jt}, Y_{-jt}$, Lemma 27 in \cite{bsmw22} shows that 
	\begin{equation}
	\alpha_{j}^* = \Sigma_{-j,-j}^+ \Sigma_{-j,j},\label{7}
	\end{equation}
	where $\Sigma_{-j,-j}^+$ is the Moore-Penrose inverse of $\Sigma_{-j,-j}$. We will simplify that expression.  First, 
	\begin{equation}
     \Sigma_{-j,-j}= E [ (Y_{-jt} - \mu_{-j}) ( Y_{-jt} - \mu_{-j})']= A_{-j} \Sigma_f A_{-j}' + \Sigma_{U,-j},\label{b3a}
     \end{equation}
	by (3) and Assumption 1(iv). Then 
	\begin{eqnarray*}
	\min_{ 1 \le j \le p} Eigmin( \Sigma_{-j,-j})& =& \min_{1 \le j \le p} Eigmin (A_{-j} \Sigma_f A_{-j}' + \Sigma_{U,-j}) \\
	&\ge& min_{1 \le j \le p} Eigmin (\Sigma_{U,-j}) \ge c >0,
	\end{eqnarray*}
	by Assumption 2-3. So (\ref{7}) simplifies to
	\begin{equation}
	\alpha_{j}^*= \Sigma_{-j,-j}^{-1} \Sigma_{-j,j}.\label{8}
	\end{equation}
	Define $\eta_{jt}:= (y_{jt} - \mu_j) - (Y_{-jt} - \mu_{-j})' \alpha_{j}^*$ for $j=1,\cdots, p$. Now consider
	\begin{eqnarray}
	E [ (Y_{-jt} - \mu_{-j})  \eta_{jt}] & = & E [ (Y_{-jt} - \mu_{-j}) ( y_{jt} - \mu_j) ] - E [ (Y_{-jt} - \mu_{-j}) ( Y_{-jt} - \mu_{-j})'] \alpha_{j}^* \nonumber \\
	& = & \Sigma_{-j,j} - \Sigma_{-j,-j} \alpha_{j}^* 
	=  \Sigma_{-j,j} - \Sigma_{-j,-j} \Sigma_{-j,-j}^{-1} \Sigma_{-j,j} =0,\label{9}
		\end{eqnarray}
		where the first equality uses $\eta_{jt}$ definition, and the second equality uses definitions of moment matrices, and the third one uses (\ref{8}). Given (\ref{9}) we can write the following infeasible linear regression model,
		\begin{equation}
		y_{jt}-\mu_j = (Y_{-jt} - \mu_{-j}) ' \alpha_{j}^* + \eta_{jt}.\label{10}
		\end{equation}
		Now we relate (\ref{6}) using (\ref{8}). Then 
		\begin{equation}
		\Theta_{j,-j}= - \Theta_{j,j} (\alpha_{j}^*)',\label{11}
		\end{equation}
	and then define $\tau_j^2:= E \eta_{jt}^2$. See that by (\ref{9})(\ref{10})
	\[ E [y_{jt}- \mu_j] ^2 = (\alpha_{j}^*)'  E [(Y_{-jt} - \mu_{-j})  (Y_{-jt} - \mu_{-j})'] \alpha_{j}^* + E [\eta_{jt}^2],\]
	which implies by definitions $\Sigma_{j,j}:= E [ y_{jt}- \mu_j ]^2, \Sigma_{-j,-j}:= E [ (Y_{-jt} - \mu_{-j})  (Y_{-jt} - \mu_{-j})']$ 
	\begin{eqnarray}
	\tau_j^2 & = & \Sigma_{j,j} - (\alpha_{j}^*)' \Sigma_{-j,-j} \alpha_{j}^* 
	=  \Sigma_{j,j}- \Sigma_{j,-j} \Sigma_{-j,-j}^{-1} \Sigma_{-j,j} \label{12a} \\
	& = & 1/\Theta_{j,j},\label{12}
	\end{eqnarray}
	where we use (\ref{8}) for the second equality and (\ref{5}) for the third one. Clearly, also by (\ref{8})(\ref{12a})
	\begin{equation}
	\tau_j^2 = \Sigma_{j,j} - \Sigma_{j,-j} \alpha_{j}^*.\label{13}
	\end{equation}
	 We can form the $j$ th row of precision matrix by using $j$ the main diagonal term, via (\ref{12})(\ref{13})
	\begin{equation}
	\Theta_{j,j} = \frac{1}{\Sigma_{j,j} - \Sigma_{j,-j} \alpha_{j}^*},\label{14}
	\end{equation}
	and the rest of that row, via (\ref{11})(\ref{12})
	\begin{equation}
	\Theta_{j,-j} = \frac{-(\alpha_{j}^*)'}{\tau_j^2}.\label{15}
	\end{equation}
	 We start simplifying $\alpha_{j}^*$ formula in case of hidden factors as in (2)(3). The proof for (i) here  is also a detailed version of the proof of Lemma 7 and (57) of \cite{bsmw22}. This is repeated to show that our scenario fits into their framework. Note that $\Sigma_f:= E (f_t - E f_t) (f_t - E f_t)'$.	 In that respect in (\ref{8}), by(2)-(3)
	 \begin{eqnarray}
	 \Sigma_{-j,j} &= &E [ (Y_{-jt} - \mu_{-j}) (y_{jt} - \mu_j) ] = E \{[ A_{-j} (f_t - E f_t ) + U_{-jt}][(f_t - E f_t)' a_j + u_{jt}]\} \nonumber \\
	 & = & A_{-j} \Sigma_f  a_j + A_{-j} E[ (f_t - E f_t)  u_{jt}] + E [U_{-jt} (f_t- E f_t)'] a_j + E [U_{-jt} u_{jt}] \nonumber \\
	 & = & A_{-j} \Sigma_f a_j = \bar{A}_{-j} \bar{a}_j,\label{20}
	 \end{eqnarray}
	 by Assumption 1(iv). Then the same analysis in (\ref{20}) provides with $\bar{A}_{-j}:= A_{-j} \Sigma_f^{1/2}$,
	 	 \begin{equation}
	 \Sigma_{-j,-j}= E [ (Y_{-jt} - \mu_{-j})  (Y_{-jt} - \mu_{-j})'] = A_{-j} \Sigma_f A_{-j}' + \Sigma_{U,-j} = \bar{A}_{-j} \bar{A}_{-j}^{'} + \Sigma_{U,-j}.\label{21}
	 \end{equation}
	 Using Sherman-Morrison-Woodbury formula in p.19 of \cite{hj2013}
	 \begin{eqnarray}
	 \Sigma_{-j,-j}^{-1} & = & (A_{-j} \Sigma_f  A_{-j}' + \Sigma_{U,-j})^{-1} \nonumber \\
	 & = &  \Sigma_{U,-j}^{-1} - \Sigma_{U,-j}^{-1} A_{-j} (\Sigma_f^{-1} + A_{-j}' \Sigma_{U,-j}^{-1} A_{-j})^{-1} A_{-j}' \Sigma_{U,-j}^{-1} \nonumber \\
	 & = & \Sigma_{U,-j}^{-1} - \Sigma_{U,-j}^{-1} \bar{A}_{-j} ( I_K + \bar{A}_{-j}' \Sigma_{U,-j}^{-1} \bar{A}_{-j})^{-1} \bar{A}_{-j}' \Sigma_{U,-j}^{-1},\label{22}
	 \end{eqnarray}
	  where we use Assumption 3, $\Sigma_f$ is positive definite. Note also that 
	 \begin{equation}
	 \bar{A}_{-j}^+ \bar{A}_{-j} = \bar{A}_{-j}' (\bar{A}_{-j}^+)' = I_K,\label{23}
	 \end{equation}
	 since $A_{-j}, \Sigma_f$ has full rank K by Assumption 3,  so (135) of \cite{bsmw22} provides the last result (\ref{23}). Define $\bar{a}_j:= \Sigma_f^{1/2} a_j$ and (\ref{8})(\ref{20})
	 \begin{eqnarray}
	 \alpha_{j}^* &=& \Sigma_{-j,-j}^{-1} \bar{A}_{-j} \bar{a}_j 
	  =  \Sigma_{-j,-j}^{-1} [ \bar{A}_{-j} \{ \bar{A}_{-j}' (\bar{A}_{-j}^+)'\} \bar{a}_j] \nonumber \\
	 & = & \Sigma_{-j,-j}^{-1} [ \Sigma_{-j,-j} - \Sigma_{U,-j}] (\bar{A}_{-j}^+)' \bar{a}_j 
	  =  [ I_{p-1} - \Sigma_{-j,-j}^{-1} \Sigma_{U,-j}] (\bar{A}_{-j}^+)' \bar{a}_j,\label{24}	
	 \end{eqnarray}
	 where we use (\ref{23}) for the second equality and for the third equality (\ref{21}) and $\bar{A}_{-j}$ definition. By using $\bar{G}_j$ definition before Lemma 1
	 	 and using (\ref{22}) on right side of  (\ref{24}) for $\Sigma_{-j,-j}^{-1}$
	 \begin{eqnarray}
	 I_{p-1} - \Sigma_{-j,-j}^{-1} \Sigma_{U,-j} & = & I_{p-1} - [ \Sigma_{U,-j}^{-1} - \Sigma_{U,-j}^{-1} \bar{A}_{-j} \bar{G}_j^{-1} \bar{A}_{-j}' \Sigma_{U,-j}^{-1}] \Sigma_{U,-j} \nonumber \\
	 & = & \Sigma_{U,-j}^{-1} \bar{A}_{-j} \bar{G}_j^{-1} \bar{A}_{-j}'\label{25}
	 \end{eqnarray}
	 Use (\ref{25}) in (\ref{24}) 
	 \begin{equation}
	 \alpha_{j}^* = \Sigma_{U,-j}^{-1} \bar{A}_{-j} \bar{G}_j^{-1} \bar{A}_{-j}' (\bar{A}_{-j}^+)' \bar{a}_j 
	  =  \Sigma_{U,-j}^{-1} \bar{A}_{-j} \bar{G}_j^{-1} \bar{a}_j,\label{26}
	 \end{equation}
	 by (\ref{23}) for the second equality. One of the other elements in the precision matrix is the reciprocal of the main diagonal term, $\tau_j^2$ in (\ref{13}). We provide a formula for that in terms of hidden factor regression model, which will be new. In that respect, by (2)(3), Assumption 1
	\begin{equation}
	\Sigma_{j,j}:=E (y_{jt} - \mu_j)^2= a_j' \Sigma_f a_j + \sigma_j^2= \bar{a}_j' \bar{a}_j + \sigma_j^2.\label{27}
		\end{equation}
		Similarly, using (2)(3), Assumption 1
		\begin{equation}
		\Sigma_{j,-j}:= E (y_{jt} - \mu_j)(Y_{-jt} - \mu_{-j})' = \bar{a}_j' \bar{A}_{-j}'.\label{28}
		\end{equation}
	Then combine (\ref{26})(\ref{27})(\ref{28}) in (\ref{13})
    \begin{equation}
        \tau_j^2 = (\bar{a}_j' \bar{a}_j + \sigma_j^2) - \bar{a}_j' \bar{A}_{-j}' \Sigma_{U,-j}^{-1} \bar{A}_{-j}
        \bar{G}_{j}^{-1} \bar{a}_j.\label{28a}
    \end{equation}

   (i)-(ii). By (\ref{26}) and (\ref{28a}), and using them in (\ref{12})(\ref{15})  we have the desired result.
	{\bf Q.E.D.}



    Here we first provide a tail inequality for quadratic form of a mean-zero subgaussian random vector. This is Lemma 21 in \cite{bbsmw21}. 
\begin{lemma}\label{lb1}
    Let $\zeta$ be a zero mean  $d$ dimensional $\gamma_e$ sub-Gaussian random vector. For all symmetric positive-semi definite matrices $H$, and all $t \ge 0$,
    \[ P \left( \zeta' H \zeta >  \gamma_e^2 (\sqrt{tr (H)} + \sqrt{2 \| H \|_2 t }
)^2    \right) \le exp(-t),\]
 \end{lemma}
where $tr(H)$ represents trace of $H$, and $\gamma_e$ subgaussian random vector is defined in Assumption 4. Now, we provide a lemma for a lower bound inequality for singular value of a specific random matrix that we use in our proofs for RRE when $p-1>n$. In that way we extend the zero factor mean in Proposition 14 of \cite{bsmw22} to a nonzero mean case below.
\begin{lemma}\label{lb2}
 Under Assumptions $3^{*}(i)$, Assumption 3(ii), Assumption 4, with some $C>0$ large enough, 
 $re (\Sigma_{U,-j}) > C n $, for each $j=1,\cdots,p$, and $\tilde{U}_{-j}$ has independent entries, in the case of $p-1>n$
 \[ P \left( \sigma_n^2 (Y_{-j}) \ge C tr (\Sigma_{U,-j})\right) \ge 1 - 4 exp (-C_p n) .\]
 \end{lemma}
 {\bf Proof of Lemma \ref{lb2}}.
	So  first we use (89) in \cite{bsmw22} and then equation below that on 
p.42 of  proof of Proposition 14 of \cite{bsmw22} but we replace Theorem 4.6.1 of \cite{v2019} in that proof  with Theorem 5.3.9 of \cite{v2012}, (set $t=\sqrt{n}$) to take into account nonzero mean of factors.
The rest carries over from the proof of Proposition 14 of \cite{bsmw22}.{\bf Q.E.D.}	\\		


