Recall that $H$ is feasible if and only if $d_{H}^{\ell}(u,v) \leq \demand(u,v)$, for all $(u,v) \in K$.%

\begin{lemma}\label{lem:lambdaCutEquivalence}
    Let $H=(V,E') \subseteq G$ with $\maxDemand$-extension $\extension{H}$ and any $(u,v) \in K$. Then %
    $$ \textsf{\emph{\textbf{(1)\ }}} d_{H}^{\ell}(u,v) \leq \demand(u,v) \Leftrightarrow \textsf{\emph{\textbf{(2)\ }}} \text{\emph{every $u_0v_{\demand(u,v)}$-cut in $\extension{H}$ is satisfied.}} $$
\end{lemma}
\begin{proof}
    Assume (1) %
    and let $P \subseteq E'$ be a shortest $uv$-path in $H=(V,E')$.
    Then $\ell(P) \leq \demand(u,v)$.
    We can construct a $u_0 v_{\demand(u,v)}$-path $\extension{P} \subseteq \extension{E'}$ in $\extension{H}$ using the arcs corresponding to edges in $P$ (and self-arcs), and (2) holds.
    Conversely, if (2), there is a path $\extension{Q}$ from $u_0$ to $v_{\demand(u,v)}$ in $\extension{H}$. $\extension{Q}$ induces a $uv$-path of length at most $\demand(u,v)$ in $H$ (removing self-arcs). %
\end{proof}

We argue that only a certain kind of cuts may ever be non-satisfied in $\extension{H}$.







\begin{definition}[Ascending $u_0v_{\demand(u,v)}$-cut]\label{def:ascendingCut}
    Let $H=(V,E')$ with $\maxDemand$-extension $\extension{H}$ and $u,v \in V$.
    A $u_0v_{\demand(u,v)}$-cut $(A{:}B)$ in $\extension{H}$ is \emph{ascending} if it is \emph{induced} by a node labeling $\myLabeling \colon V \rightarrow \{0,1,\dots, \demand(u,v)+1\}$, 
    i.e., for every $q \in V$ we have that $q_i \in B$ for all $0 \leq i < \myLabeling(q)$, and $q_i \in A$ for all $\myLabeling(q) \leq i \leq \demand(u,v)+1$.
\end{definition}

Necessarily, $\myLabeling(u) = 0$ and $\myLabeling(v) = \demand(u,v) +1$.
Observe that \Cref{fig:myAscendingCutExample} indeed shows an ascending cut.
A $u_0v_{\demand(u,v)}$-cut $(A{:}B)$ is non-ascending if and only if there is a $q \in V$  %
with $q_i \in A$ and $q_{i+1} \in B$, for some $0 \leq i \leq \demand(u,v)$. Such a cut is trivially satisfied by self-arc $(q_i, q_{i+1})$.
Hence, we only have to consider ascending cuts.
For $(u,v) \in K$, let $\mathcal{C}_{uv}$ denote the set of all ascending $u_0v_{\demand(u,v)}$-cuts in~$\extension{H}$.
By construction via the node labeling $\myLabeling$, we get $|\mathcal{C}_{uv}| = (\demand(u,v)+2)^{n-2}$.
Define $\maxNumCuts \coloneqq \max_{(u,v) \in K} |\mathcal{C}_{uv}| \leq (\maxDemand + 2)^{n-2}$ as the maximum number of ascending $u_0v_{\demand(u,v)}$-cuts for any $(u,v) \in K$.
Next, we bound the probability that an ascending cut is non-satisfied in the $\maxDemand$-extension of our rounded subgraph.


\begin{observation}\label{lem:probability}
        Let $X_1, \dots, X_k$ be independent, binary, random variables with $\Prob(X_i) = \min\{1, p_i\}$ and $\sum_{i=1}^{k} p_i\geq S$. Then $\Prob[\bigwedge_{i=1}^{k} (X_i=0)] = \prod_{i=1}^{k}(1-p_i) \leq e^{-( \sum_{i=1}^{k}p_i)} \leq e^{-S}$. 
\end{observation}

\begin{lemma}\label{lem:cutSatisfyProbability}
    For $(u,v) \in K$, a given ascending $u_0v_{\demand(u,v)}$-cut $(A{:}B)$ is non-satisfied in $\extension{H}$ with probability at most $e^{-\gamma}$.
\end{lemma}
\begin{proof}
    Let $\extension{E'}_c\subseteq \extension{E'}$ be the set of arcs %
    that go from $A$ to $B$ in $\extension{H}$. %
    Let $E'_c \subseteq E'$ be their corresponding edges in $H$.
    Since one unit of flow must cross from $A$ to $B$ in $\extension{H}$, we get
    $1 \leq \sum_{a \in \extension{E'}_c} {f^{uv}_a}^* \leq \sum_{e \in E'_c} x_e^* $, where ${f^{uv}_a}^*$ are the optimal solution values for $f^{uv}_a$, respectively.
    Each $e \in E'_c$ is chosen with probability $\min\{1, \gamma x_e^*\}$ and $\sum_{e \in E_c} \gamma x_e^* \geq \gamma$. 
    Thus, by 
    \Cref{lem:probability},
    we get $\Prob[(A{:}B)\text{ is not satisfied}] =\Prob[E_c \cap E' = \emptyset]\leq e^{-\gamma}$.
\end{proof}

We are now ready to define $\gamma \coloneqq \ln(n\maxNumCuts|K|)$ and get $e^{-\gamma} = \frac{1}{n\maxNumCuts|K|}$.
By \Cref{lem:lambdaCutEquivalence}, $H$ is infeasible if and only if, for any $(u,v) \in K$, there is an ascending $u_0v_{\demand(u,v)}$-cut that is not satisfied.
By union bound, we can estimate this probability as
\begin{equation}%
\label{eq:probFeas}
    \sum_{(u,v) \in K} \sum_{(A{:}B) \in \mathcal{C}_{uv}} e^{-\gamma} \leq  \maxNumCuts |K| \cdot  e^{-\gamma} = \frac{\maxNumCuts |K|}{\myRRratio} = \frac{1}{n}. 
\end{equation}
Hence, our rounded solution $H=(V,E')$ forms a feasible spanner with probability at least $1-\frac{1}{n}$.
The total running time of \Cref{alg:randomizedRounding} is in $\mathcal{O}(\myLP)$; in particular, it is polynomial in $n$ if $\maxDemand \in \mathcal{O}(\poly(n))$.
Using $\maxDemand \leq n L$ and $n \leq m$ yields an upper bound of $\mathcal{O}(\myLPUB)$.
Thus

\begin{theorem}\label{thm:RandomizedRounding}
    For (un)directed \generic \freeform\ spanner problems with integer lengths and polynomially bounded distance demands, \Cref{alg:randomizedRounding} returns a feasible spanner w.h.p., with expected approximation ratio $\gamma = \ln(n \maxNumCuts|K| ) \leq \ln(n^3 (\maxDemand + 2)^{n-2}) \in \mathcal{O}(n \log \maxDemand)\subseteq \mathcal{O}(n \log n)$.
\end{theorem}

If the instance is undirected, we construct the $\maxDemand$-extension of its bi-directed counterpart but only have undirected edge variables in \eqref{lp:ours:arcVars}; constraints \eqref{lp:ours:edgeCons} are constructed twice, once per possible direction of $e$.
The remaining constructions and proofs then work identically. %


\subparagraph{Comparison to Grigorescu et al.~\cite{grigorescu2023approximation}.}
It is worthwhile to compare our algorithm to the currently theoretically strongest known approach~\cite{grigorescu2023approximation} for this setting. Amongst other steps, the latter requires the computation of up to $\GrigNumTrees$ minimum-weight distance-preserving junction trees. Each such tree requires solving an LP with orders of magnitude more variables and constraints; namely, each such computation requires $\Omega(\GrigLP)$ time.
Clearly, these computations alone, even disregarding all other necessary subroutines (solving Path-LPs, etc.), drastically exceed our time guarantee.
Also, neglecting all additional (expected) weight for covering the remaining terminal pairs, the weight introduced by their constrained shortest path trees is lower bounded by $12 \cdot n^{4/5} \ln n \cdot \opt$. 
Compare this to our expected ratio of $\gamma = \ln(n \maxNumCuts |K|) \leq \ln(n^3 (\maxDemand + 2)^{n-2})$.
For, e.g., instances with 
$\maxDemand \leq n$, $\sqrt{n}$, $\log n$, or $10$, our algorithm expects a superior approximation ratio for all $n \leq 248\, 000$, $10^6$, $10^{9}$, and $10^{10}$, respectively. %
Clearly, this encompasses many practically relevant instances.

\subparagraph{Constant-bounded instances.}
Consider any instance in the scenario of~\Cref{thm:RandomizedRounding}; we say it is \emph{constant-bounded} if the maximum distance demand $\maxDemand$ is bounded by some constant.
\begin{corollary}\label{cor:RandomizedRoundingConstantDelta}
    \Cref{alg:randomizedRounding} is an $\mathcal{O}(n)$-approximation for constant-bounded instances.
\end{corollary}





Currently, among constant-bounded spanner problems,
only undirected unit-length multiplicative $2$-spanners (where thus $\delta(u,v)=2$ for all $\{u,v\}\in K=E$) are known to allow approximation ratios in $\mathcal{O}(\log n)$~\cite{kortsarz1994, kortsarz2001}.
We extend this result to all constant-bounded \generic \freeform spanner problems with constant maximum (out)degree $\maxDeg$, even on directed graphs.
Recall that under these restriction, even the undirected basic multiplicative $\alpha$-spanner problem is \textbf{NP}-hard~\cite{gomez2023}. Further, without restricting the (out)degrees, there cannot be a polylogarithmic approximation ratio unless \textbf{NP}$\subseteq$\textbf{BPTIME}$(n^{\text{polylog}(n)})$~\cite{dinitz2015}.

For $(u,v) \in K$ and $G=(V,E)$, let subgraph $\myRestriction{G}=(\myRestriction{V}, \myRestriction{E})$, with $\myRestriction{V}\subseteq V$ and $\myRestriction{E}\subseteq E$, be induced by all $uv$-paths $P$ in $G$ with $\ell(P) \leq \demand(u,v)$.
Then $\myRestriction{G}$ contains all nodes and edges that affect whether terminal pair $(u,v)$ satisfies its distance demand.

\begin{lemma}\label{lem:restrictedGCuts}
    Every ascending $u_0v_{\demand(u,v)}$-cut in $\mathcal{C}_{uv}$ in $\extension{H}$ is satisfied if and only if every ascending $u_0v_{\demand(u,v)}$-cut in $\mathcal{C}_{uv}'$ in $\extension{\myRestriction{H}}$ is satisfied.
\end{lemma}
\begin{proof}
    $\mathcal{C}_{uv} \subseteq \mathcal{C}_{uv}'$ gives necessity.
    For sufficiency, note that no satisfied cut in $\mathcal{C}_{uv}'$ induced by a labeling $\myLabeling$ of nodes $\myRestriction{V}$ can be dissatisfied by expanding $\myLabeling$ to label further nodes. %
\end{proof}

By \Cref{lem:restrictedGCuts}, we only have to choose $\gamma$ such that all ascending $u_0v_{\demand(u,v)}$-cuts in $\extension{\myRestriction{H}}$ are satisfied w.h.p.
Note that $n_{uv} \coloneqq |\myRestriction{V}| \leq \maxDeg^{\demand(u,v)}$, for every $(u,v) \in K$.
Hence, the number of relevant ascending cuts $|\mathcal{C}_{uv}'|$ in $\extension{\myRestriction{H}}$ is bounded by $|\mathcal{C}_{uv}'| \leq (\demand(u,v)+2)^{n_{uv}-2}$.
Let $\maxNumCuts' \coloneqq \max_{(u,v) \in K} |\mathcal{C}_{uv}'|$ the maximum number of relevant cuts for any $(u,v) \in K$.
Then, $\gamma = \ln(n \maxNumCuts' |K|) \in \mathcal{O}(\log n + \maxDeg^{\maxDemand} \log \maxDemand)$ suffices to guarantee 
feasible solutions w.h.p. 
Hence, the expected approximation ratio improves with decreasing $\maxDeg^{\maxDemand}$ and, 
e.g., beats the best known ratio for unit-length multiplicative $3$-spanners of $\widetilde{\mathcal{O}}(n^{1/2})$~\cite{dinitz2011directed} if $\Delta \in o(n^{1/6})$.
Crucially, for constant $\maxDemand$ and constant $\maxDeg$, choosing $\gamma = \ln(n \maxNumCuts'|K|) \in \mathcal{O}(\log(n |K|)) \subseteq \mathcal{O}(\log n)$ suffices.


\begin{corollary}\label{cor:RandomizedRoundingConstDR}
     \Cref{alg:randomizedRounding} is an $\mathcal{O}(\log n)$-approximation for constant-bounded instances with constant maximum (out)degree.
\end{corollary}

Choosing $\gamma = \ln(2 \maxNumCuts' |K|)$ still yields feasible solutions with probability at least 
$1- \frac{1}{2} = \frac{1}{2}$ (see \eqref{eq:probFeas}), but no longer w.h.p.
Then, for constant-bounded instances with constant maximum (out)degree, if the number of terminal pairs $|K|$ is sublinear in $n$ or constant, the so-modified \Cref{alg:randomizedRounding} achieves expected weight ratios in $o(\log n)$ or $\mathcal{O}(1)$, respectively.








\section{Conclusion}
We provided two simple approximations for \generic \freeform spanner problems (cf.~\Cref{tab:myResults,tab:AGResults}). %
Our \AG yields the first unconditional $m$-approximation for this problem.
At the same time, it retains all weight and size guarantees \GR is appreciated for. %
For integer lengths and polynomially bounded distance demands, our \RR has ratio $\mathcal{O}(n \log n)$, closely matching the best known ratio under these conditions~\cite{grigorescu2023approximation}. %
In contrast to the latter very complex %
approach, we simply round a solution of a standard multicommodity flow LP in a graph extension.
On bounded-degree graphs, this furthermore provides the first $\mathcal{O}(\log n)$-ratio for (undirected or directed) spanner problems with constant-bounded distance demands (beyond undirected unit-length $2$-spanners).

Future work could include practical studies.
Such evaluations would have to focus on algorithms tuned for simplicity and implementability, as
our proposed algorithms.
Also, comparisons against the \enquote{defacto state-of-the-art} of forcing \generic instances into a \uniform format would be interesting.
Implementations of algorithms like~\cite{grigorescu2023approximation} seem unrealistic, due to their high complexity and reliance on never implemented subroutines.


