\subsection{Complete graphs}

The following lemma can be viewed as a special case of the later Theorem \ref{thm:outdegree_upper_bound}(a) in Section \ref{sec:genresults}. For the reader's convenience, we also present a proof in the simpler case of this lemma.

\begin{lemma} \label{lem:upbdxdy} Let $G=(V,E)$ be a graph and $T \subset V$ be a subgraph which is a forest. Then we have
\begin{equation} \label{eq:nuisoperi} 
\nu(G) \le \frac{|\partial T|}{|T|}, 
\end{equation}
where $\partial T \subset E$ is the set of edges connecting vertices of $T$ with vertices of $V \setminus T$. In particular, we have
\begin{equation} 
\label{eq:nuGmindxdy}
\nu(G) \le \min_{x \sim y} \frac{d_x+d_y}{2}-1. 
\end{equation}
\end{lemma}

\begin{remark} Inequality \eqref{eq:nuisoperi} in  Lemma \ref{lem:upbdxdy} can also be viewed as the inequality
$$ \nu(G) \le h_{\rm{forest}}(G), $$
where $h_{\rm{forest}}$ is a Cheeger-type constant, which takes the infimum of isoperimetric ratios only for subgraphs which are forests. 
\end{remark}

\begin{proof} We first present the proof in the special case when $T$ is a tree. Let $\sigma: E^{or} \to S^1$ be an arbitrary magnetic potential and $x_0 \in T$. Choose
$f: V \to \C$ as follows: We set $f(x_0) =1$ For any vertex $x \in T \setminus \{x_0\}$, choose the unique path $x_0 \sim x_1 \sim \cdot \sim x_l = x$ in $T$ and define
$$ f(x) = \sigma(x_0,x_1)^{-1} \sigma(x_1,x_2)^{-1} \cdots \sigma(x_{l-1},x_l)^{-1}. $$
For any vertex $x \in V \setminus T$, define
$$ f(x) = 0. $$
Then we have 
$$
\lambda_1^\sigma(G) \le \RR^\sigma(f) = \frac{\displaystyle{\sum_{x \sim y \atop x\in T, y \in V\setminus T}} |f(x)-\sigma(x,y)f(y)|^2}{\sum_{x \in T} |f(x)|^2}
= \frac{|\partial T|}{|T|}.
$$
In the case that $T$ is a forest, we choose in every connected component of $T$ a base point $x_0$ to define the test function $f$ and argue accordingly.

For the second part of the proposition, choose $T=\{x,y\}$ for any pair $x \sim y$.
\end{proof}

