\begin{example}[The complete graph $K_d$] \label{ex:completegraph} For the complete graph $K_d$, we will show that
$$
\nu(K_d) = d-2.
$$
We have
$$ \lambda^{\overline{\sigma}}(K_d) = d-2 $$
for the anti-balanced magnetic potential $\overline{\sigma}\equiv -1$, since 
$$ \Delta^{ \overline{\sigma}} \equiv (d-2) {\rm{Id}}_{d} + J_d, $$
with the all-$1$ square matrix $J_d$ of size $d$, and all non-zero vectors perpendicular to the all-$1$ vector of size $d$ are eigenvectors to the eigenvalue $d-2$, whereas the all-$1$ vector of size $d$ is an eigenvector to the eigenvalue $2(d-1) > d-2$. 
Since $K_d$ is $(d-1)$-regular, it follows from Lemma \ref{lem:upbdxdy} that
$$ \nu(K_d) \le \min_{x \sim y} \frac{d_x+d_y}{2} - 1 = (d-1)-1 = d-2. $$
Since $\lambda^{\overline{\sigma}}(K_d) = d-2$, we have equality $\nu(G) = d-2$, assumed by the anti-balanced magnetic potential $\overline{\sigma}$. For this potential, the multiplicity of $\lambda_1^{\overline{\sigma}}$ has multiplicity $d-2$.
\end{example}

To derive particular rigidity results for complete graphs (Corollary \ref{cor:complrigid} and Proposition \ref{prop:completerigid} below), we start with the following general fact.

\begin{proposition} \label{prop:nudxdy}
Let $G=(V,E)$ be a graph and $\{x,y\} \in E$ be an edge. If
$$ \nu(G) = \frac{d_x+d_y}{2}-1, $$
then we have
$$ S_1(x) \setminus \{y\} = S_1(y) \setminus \{x\}. $$
In particular, we have $d_x=d_y$.
\end{proposition}

\begin{proof}
    Let $\hat \sigma: E^{or}(G) \to S^1$ be a maximal magnetic potential, that is,
    $$ \nu(G) = \lambda_1^{\hat \sigma}(G). $$
    Let $f: V \to \C$ be the following function
    $$ f(z) = \begin{cases} 1 & \text{if $z=x$,} \\
\hat \sigma(x,y)^{-1} & \text{if $z=y$,} \\ 0 & \text{otherwise.} \end{cases}$$
    Then we have
    $$ \frac{d_x+d_y}{2}-1 = \nu(G) = \lambda_1^{\hat \sigma}(G) \le \RR^{\hat \sigma}(f) = \frac{d_x+d_y}{2}-1. $$
    Therefore, $f$ is an eigenfunction of $\Delta^{\hat \sigma}$ to the eigenvalue $\frac{d_x+d_y}{2}-1$. Let us denote the neighbours of $x$ by $y=y_1,y_2,\dots,y_{d_x}$. Assume $y_j$, $j \in \{2,\dots,d_x\}$ is not a neighbour of $y=y_1$. Then we have
    $$ \Delta^{\hat \sigma}f(y_j) = \sum_{z \sim y_j} f(y_j)-\hat \sigma(y_j,z)f(z) = -\hat \sigma(y_j,x)f(x) = 0, $$
    which is a contradiction. This shows that all neighbours of $x$, different from $y$, are also neighbours of $y$. Interchanging the role of $x$ and $y$ implies that we have $d_x=d_y.$
\end{proof}

Now we can prove the following rigidity result.

\begin{corollary} \label{cor:complrigid}
Any connected graph $G=(V,E)$ satisfying
$$ \nu(G) = \max_{x \sim y} \frac{d_x+d_y}{2}-1 $$
is already a complete graph. In particular, any connected graph $G$ with
$$ \nu(G) = d_{\max}-1, $$
where $d_{\max}$ is the maximal vertex degree of $G$, 
is a complete graph $K_{d_{\max}+1}$.
\end{corollary}

\begin{proof}
    It follows from Lemma \ref{lem:upbdxdy} that we have
    $$ \min_{x \sim y} \frac{d_x+d_y}{2} - 1 \ge \nu(G) = \max_{x \sim y} \frac{d_x+d_y}{2}-1,$$
    which implies $d_x+d_y$ is constant for any edge $\{x,y\} \in E$. It follows from Proposition \ref{prop:nudxdy} that any connected component of $G$ is regular and complete. Since $G$ is assumed to be connected, the first statement of the corollary follows. 

    Since 
    $$\max_{x \sim y} \frac{d_x+d_y}{2} \le d_{\max}, $$
    the condition $\nu(G) = d_{\max}-1$ implies that we have $d_x=d_y=d_{\max}$ for all adjacent vertices. Since $G$ is connected, $G$ is regular and Proposition \ref{prop:nudxdy} implies again that $G$ is a complete graph.
\end{proof}

We also have the following rigidity result.

\begin{proposition} \label{prop:completerigid}
Let $\hat \sigma: E^{or}(K_d) \to S^1$ be a maximal magnetic potential of the complete graph $K_d$. Then $\hat \sigma$ is automatically gauge equivalent to the anti-balanced signature $\overline{\sigma} \equiv -1$.
\end{proposition}

\begin{proof}
Let $\hat \sigma$ be a maximal magnetic potential on $K_d$. For $k,l \in \{1,\dots,d\}$, we introduce the function
$$ f_{k,l}(x_m) = \begin{cases} 1 & \text{if $m=k$,} \\
\hat \sigma(x_k,x_l)^{-1} & \text{if $m=l$,} \\ 0 & \text{otherwise.} \end{cases} $$
Then we have
$$ \lambda_1^{\hat \sigma}(K_d) = d-2 = \RR^{\hat \sigma}(f_{k,l}), $$
and $f_{k,l}$ is therefore an eigenfunction of $\Delta^{\hat \sigma}$ to the eigenvalue $d-1$. The eigenfunction equation yields for $m \not\in\{k,l\}$,
$$ \Delta^{\hat \sigma} f_{k,l}(x_m) = \underbrace{\sum_{j \neq m} f_{k,l}(x_m) - \hat \sigma(x_m,x_j) f_{k,l}(x_j)}_{\hat \sigma(x_m,x_k)- \hat \sigma(x_m,x_l)\hat \sigma(x_k,x_l)^{-1}} = (d-1)f_{k,l}(x_m) = 0, $$
which implies 
$$ \hat \sigma(x_m,x_k) \hat \sigma(x_k,x_l) \hat \sigma(x_l,x_m) = -1. $$
Choosing the gauge function $\tau: V \to S^1$,
$$ \tau(z) = \begin{cases} -1, & \text{if $z=x_1$,} \\
\hat \sigma(x_1,x_j)^{-1}, & \text{if $z=x_j$, $j \ge 2$,} \end{cases} $$
we obtain
$$ \hat \sigma^\tau(x_1,x_j) = \tau(x_1)^{-1} \hat \sigma(x_i,x_j)\tau(x_j) = -1 \quad \text{for all $j \ge 2$.} $$
Since, for $k,l \ge 2$, $k\neq l$,
$$\hat \sigma^\tau(x_k,x_l) = \hat \sigma^\tau(x_1,x_k) \hat \sigma^\tau(x_k,x_l) \hat \sigma^\tau(x_l,x_1) = \hat \sigma(x_1,x_k) \hat \sigma(x_k,x_l) \hat \sigma(x_l,x_1) = -1,$$
$\hat \sigma^\tau$ is the anti-balanced signature.
\end{proof}

