\subsection{Wheel graphs}
\begin{example}[Suspension of a tree] \label{ex:treesuspension}
Let $T$ be a tree and $\tilde T$ be its suspension, that is, we add a vertex $x$ to $T$ and connect it to all vertices in $T$. Then we have
$$ \nu(\tilde T) \le 1. $$
This follows directly from \eqref{eq:nuisoperi} in Lemma \ref{lem:upbdxdy}. In fact, we will see later (see Theorem \ref{thm:suspgraph}) that we have $\nu(\tilde T) = 1$ for all trees. %Note that the previous example is a special case of this example, as it is the suspension of a path of length $2$.
\end{example}

Next we consider suspensions of cycles. The suspension of a cycle $C_d$ ($d \ge 3$) is the wheel graph $W_d$. In the next example we compute an explicit lower bound for $\nu(
W_d)$. In contrast to the suspension of trees, we will see that $\nu(W_d) > 1$.  

\begin{example}[The wheel graphs $W_d$] \label{ex:wheel} Let $d \ge 3$ and $x_0,\dots,x_{d-1}$ be the vertices of $W_d$ in the cycle $C_d \subset W_d$ and $x \in W_d$ be the suspension vertex. Let $\sigma_1: E^{or}(W_d) \to \{-1,1\}$ be given by  
$$ \sigma_1(x_j,x_{j+1}) = \begin{cases} 1 & \text{for $j=0,1,\dots,d-2$,} \\
-1 & \text{for (j,j+1)=(d-1,0),}\end{cases}$$ 
and
$$ \sigma_1(x,x_j) = \begin{cases} -\left(e^{-i \frac{2k+1}{d}\pi}\right)^j & \text{for $j=0,1,\dots,d-2$,} \\
- e^{i \frac{2k+1}{d} \pi} & \text{for $j=d-1$.}\end{cases} $$ 
We will show that the eigenvalues of $\Delta^{\sigma_1}$ on $W_d$ (with multiplicities) are given by the values 
$$ 3 - 2 \cos\left( \frac{\pi+2\pi j}{d} \right) \quad \text{with $j =0,1,\dots,d-1$, $j \neq k$}, $$
all counted once,
and the roots of
$$ \lambda^2-\left(d+3-2\cos\left(\frac{2k+1}{d}\pi \right)\right)\lambda+\left( 2-2 \cos \left( \frac{2k+1}{d} \pi \right)\right)d = 0, $$
(with $d=2k$ for even $d$ and $d=2k+1$ for odd $d$) which are also counted once.
Note that this equation simplifies in the case $d=2k+1$ to
$$ \lambda^2-(d+5)\lambda + 4d = 0. $$
Using Lemma \ref{lem:destimates} below, this implies that
$$ \nu(W_d) \ge \lambda_1^{\sigma_1}(W_d) = 3-2 \cos\left( \frac{\pi}{d} \right) = 1 + \nu(C_d). $$

Note that the restriction of $\sigma_1$ to $C_d$, denoted again by $\sigma_1$, for simplicity, is a maximal magnetic potential of $C_d$.
The eigenfunctions of $\Delta^{\sigma_1}_{C_d}$ 
are given by (cf. Figure \ref{fig:Cdeigfunc} with $t=\pi$)
$$f_j=\begin{pmatrix}
    1 \\
    e^{\frac{i\pi}{d}}\xi_{d}^j \\
    (e^{\frac{i\pi}{d}}\xi_{d}^j)^2 \\
    \vdots \\
    (e^{\frac{i\pi}{d}}\xi_{d}^j)^{d-2} \\
    e^{-\frac{i\pi}{d}}(\xi_{d}^j)^{-1}
\end{pmatrix},\quad \text{ $j=0,1,\cdots, d-1$.}$$
Note that we have 
$$ \overline{f_k}=\begin{pmatrix}
    -\sigma_1(x,x_0) \\
    -\sigma_1(x,x_1) \\
    -\sigma_1(x,x_2) \\
    \vdots \\
    -\sigma_1(x,x_{d-2}) \\
    -\sigma_1(x,x_{d-1})
\end{pmatrix}, $$
and, therefore, we have
$$\Delta^{\sigma_1}_{W_d}\cong\begin{pmatrix}\begin{array}{c|ccc}
d &  & \overline{f_{k}}^{\top}  &  \\
\hline
   &    &     &    \\
f_k &   & \Delta^{\sigma_1}_{C_d}+\mathrm{Id} &  \\
    &   &    &
\end{array}    
\end{pmatrix}.$$
The orthogonality relation \eqref{eq:orthogonality} implies that $\Delta^{\sigma_1}_{W_d}$ has the following set of $(d-1)$ eigenfunctions: 
$$\left\{\begin{pmatrix}
    0 \\
    f_j
\end{pmatrix},\,\,\,j=0,1,\cdots,k-1,k+1,\cdots,d-1\right\},$$
corresponding to the eigenvalues $\mu_j(\pi)+1$, $j \neq k$, with the eigenvalues $\mu_j(\pi)$ of $\Delta_{C_d}^{\sigma_1}$ given in \eqref{eq:mujt}.
The remaining $2$-dimensional vector space orthogonal to $span\{f_0,f_1,\cdots,f_{k-1},f_{k+1},\cdots,f_{d-1}\}$ can be written as 
$$\left\{\begin{pmatrix}
    a \\
    bf_k
\end{pmatrix},\,\,\,a,b\in \mathbb{C}\right\}.$$
Solving the eigenfunction equation
$$\begin{pmatrix}
    d  & \overline{f_k}^{\top} \\
    f_k & \Delta^{\hat \sigma}_{C_d}+\mathrm{Id}
\end{pmatrix}
\begin{pmatrix}
    a \\
    bf_{k}
\end{pmatrix}
=\lambda
\begin{pmatrix}
   a \\
   bf_k
\end{pmatrix}$$
leads to
$$\begin{cases}
    (\lambda-d)a=db,\quad &\text{(A)}\\
    a=(\lambda-\mu_k(\pi)-1)b, &\text{(B)}
\end{cases}$$
with
$$ \mu_k(\pi) = 2-2\cos\left( \frac{2k+1}{d} \pi\right). $$
Replacing $a$ with $(B)$ in $(A)$ yields
$$(\lambda-d)(\lambda-\mu_k(\pi)-1)b=db. $$
Since $b=0$ implies $\begin{pmatrix}
    a \\
    bf_k
\end{pmatrix}= 0$, in contradiction to an eigenfunction,  we can divide by $b \neq 0$ and obtain the quadratic equation
$$\lambda^2-(d+\mu_k(\pi)+1)\lambda+\mu_k(\pi)d=0,$$
which gives the remaining two eigenvalues of $\Delta^{\sigma_1}_{W_d}$.
\end{example}

\begin{lemma}\label{lem:destimates}
\begin{itemize}
    \item[(a)] Let $d \ge 3$ be odd. Then we have
    $$ \frac{d+5 - \sqrt{(d+5)^2-16d}}{2} \ge 3-2\cos(\pi/d). $$
    \item[(b)] Let $d \ge 4$ be even. Then we have
    $$ \frac{d+3+2\cos(\pi/d) - \sqrt{(d+3+2\cos(\pi/d))^2-4d(2+2\cos(\pi/d))}}{2} \ge 3-2\cos(\pi/d). $$
\end{itemize}
\end{lemma}
\begin{proof}
The inequality in (a) is an equality in the case $d=3$.
It is also easy to verify (b) for $d=4$.  So we can restrict to the case $d \ge 5$.

Both (a) and (b) are direct consequences of the following two facts:
\begin{itemize}
\item[(i)] We have
$$ d+3+2c-\sqrt{(d+3+2c)^2-4d(2+2c)} \ge 6-4c $$
for $d \ge 5$ and $c= \cos(\pi/d)$.
\item[(ii)] The map
$$ [0,1] \ni c \mapsto d+3+2c-\sqrt{(d+3+2c)^2-4d(2+2c)} $$
is monotone increasing for all $d \ge 5$. 
\end{itemize}
(i) is equivalent to
$$ (4c-1)d + 8c^2 - 12 c \ge 0 $$
for $d \ge 5$ and $c=\cos(\pi/d)$. Since $d \ge 5$, we have
$$ c=\cos(\pi/d) \ge \cos(\pi/4) = \frac{\sqrt{2}}{2}. $$
So it suffices to show
$$ (4c-1)d+8c^2-12c \ge 0$$
for $d \ge 5$ and $c \in [\sqrt{2}/2,1]$. Since $4c-1 > 0$, the left hand side is increasing in $d$, 
and it suffices to show the inequality for $d=5$. This reduces the problem to show that $8c^2+8c-5$ is non-negative for $c \in [\sqrt{2}/2,1]$, which is obviously true. This finishes the proof of (i).

To prove (ii), we set $\alpha=3+2c$ and need to verify, for all $d \ge 5$, that
$$ \alpha \mapsto d+\alpha- \sqrt{(d+\alpha)^2-4d(\alpha-1)} =
d+\alpha - \sqrt{(d-\alpha)^2+4d} $$
is monotone increasing for  $\alpha \in [3,5]$. This is obviously the case, which completes the proof of the lemma.
\end{proof}

