\subsection{Upper bounds in terms of subgraphs}

In this section, we present the following relations between $\nu(G)$ and properties of  subgraphs $G_0$. 

\begin{theorem}\label{thm:outdegree_upper_bound}
Let $G=(V,E)$ be a graph and $G_0=(V_0,E_0)$ be a non-empty subgraph of $G$. Let $d_x^{out}:=|\{y\in V \setminus V_0:y\sim x \}|$ be the \emph{out-degree} of $x\in V_0$. Then $\nu(G)$ has the following upper bounds.
\begin{itemize}
\item[(a)] We have    \begin{align}\label{eq:outdegree_upper_bound}
    \nu(G)\leq\frac{4b_1(G_0)}{|V_0|}+\frac{1}{|V_0|}\sum_{x\in V_0}d_{x}^{out}.
    \end{align}
\item[(b)] We have 
\begin{equation} \label{eq:nuGnuG0weak} 
\nu(G) \leq \nu(G_0) + \max_{x \in V_0} d_x^{out}.
\end{equation}
\end{itemize}
Moreover, if there exists an eigenfunction $f \in C(V_0,\C)$ of the smallest eigenvalue of a maximal magnetic potential of $G_0$ with constant modulus $|f|$, then we have
\begin{equation} \label{eq:nuGnuG0} 
\nu(G) \leq \nu(G_0) + \frac{1}{|V_0|}\sum_{x\in V_0}d_{x}^{out}. \end{equation}
\end{theorem}

Note that the upper bound \eqref{eq:nuGnuG0} is generally stronger than both \eqref{eq:outdegree_upper_bound} and \eqref{eq:nuGnuG0weak}, since $\frac{4b_1(G_0)}{|V_0|} \ge \nu(G_0)$ and $\max_{x \in V_0} d_x^{out} \ge \frac{1}{|V_0|}\sum_{x \in V_0}d_x^{out}$. Moreover, the upper bound \eqref{eq:nuGnuG0} holds whenever we choose $G_0$ to be a tree or a cycle in $G$. In the special case that $G_0$ runs through all edges, we recover the upper bound \eqref{eq:nuGmindxdy} in Lemma \ref{lem:upbdxdy}.

\begin{proof}
    In the two statements (a) and (b) of the theorem, we choose different functions and calculate the corresponding Reighley quotients, respectively.
    \begin{itemize}
        \item [(a)] We first consider the case that $G_0$ is connected. Assume $T\subset G_0$ is a spanning tree of $G_0=(V_0,E_0)$. We choose $x_0$ as a base point of $T$. Let $\hat \sigma:E^{or}(G) \to S^1$ be a maximal magnetic potential of $G$. Then we choose the test function $f$ as follows: 
    $$f(z)=\begin{cases}
       1, & \text{if $z=x_0$,} \\\hat \sigma(x_0,x_1)^{-1}\hat \sigma(x_1,x_2)^{-1}\cdots\hat \sigma(x_{n-1},z)^{-1}, & \text{if $z\in V_0$,}\\
       0, & \text{if $z\notin V_0$.}
    \end{cases},$$
    where, in the second case, $x_0\sim x_1\sim \cdots x_{n-1}\sim z$ is the unique path from $x_0$ to $z$ on the spanning tree $T$. Then we have
    \begin{align*}\nu(G)=\lambda^{\hat \sigma}_1(G)\leq\RR^{\hat \sigma}(f)&=\frac{\sum_{\{x,y\}\in E}|f(x)-\hat\sigma(x,y)f(y)|^2}{\sum_{x\in V}|f(x)|^2}\\
    &=\frac{4(|E_0|-|V_0|+1)+\sum_{x\in v_0}d_x^{out}}{|V_0|}=\frac{4b_1(G_0)}{|G_0|}+\frac{1}{|V_0|}\sum_{x\in V_0}d_x^{out}.
    \end{align*}
    In the case that $G_0$ has more than one connected component, we choose base points in each of its components and argue accordingly.
    \item [(b)] Assume $\hat \sigma$ is a maximal magnetic potential on $G$. Denote the restriction of $\hat \sigma$ to the subgraph $G_0$ by $\hat \sigma_0$. Let $f$ be an eigenfunction on $G_0$ corresponding to the smallest eigenvalue $\lambda^{\hat \sigma_0}_1(G_0)$ and denote its trivial extension to $G$ by $\tilde{f}$. Then the Reighley quotient of $\tilde{f}$ is given as follows:
    \begin{align}
        \nu(G)&=\lambda_1^{\hat \sigma}(G) \leq \RR^{\hat \sigma}(\tilde{f}) \\ &=\frac{\sum_{\{x,y\}\in E}|\tilde{f}(x)-\hat \sigma(x,y)\tilde{f}(y)|^2}{\sum_{x\in V}|\tilde{f}(x)|^2}\notag\\
        &=\frac{\sum_{\{x,y\}\in E_0}|f(x)-\hat \sigma_0(x,y)f(y)|^2}{\sum_{x\in V_0}|f(x)|^2}+\frac{\sum_{x\in V_0}\sum_{y\notin V_0,x\sim y}|f(x)|^2}{\sum_{x\in V_0}|f(x)|^2}\label{eq:reighley_quotient_eigenfunction}\\
        &\leq\lambda^{\hat \sigma_0}_1(G_0)+\max_{x\in V_0}d^{out}_x\leq \nu(G_0)+\max_{x\in V_0}d_x^{out}.\notag
    \end{align}

 Moreover, in the special case where the norm $|f|$ is constant on $G_0$, the second term in \eqref{eq:reighley_quotient_eigenfunction} becomes the average out-degree, and we obtain the upper bound given in \eqref{eq:nuGnuG0}.
    % \begin{align*}
   %     \lambda^{\sigma}_1(G)\leq \RR^{\sigma}(\tilde{f})=&\frac{\sum_{\{x,y\}\in E}|\tilde{f}(x)-\sigma(x,y)\tilde{f}(y)|^2}{\sum_{x\in W}|\tilde{f}(x)|^2}\\
        %=&\frac{\sum_{\{x,y\}\in E_0}|f(x)-\sigma(x,y)f(y)|^2}{\sum_{x\in W}|f(x)|^2}+\frac{\sum_{\{x,y\}\in \partial W}|f(x)-\sigma(x,y)f(y)|^2}{\sum_{x\in W}|f(x)|^2}\\
    %    =&\lambda^{\sigma_W}_1(W)+\frac{1}{|W|}\sum_{x\in W}d_x^{out}.
 %   \end{align*}
    \end{itemize}
\end{proof}

