\begin{corollary}[Suspension of a graph] \label{cor:suspension}
    Let $G=(V,E)$ be a graph and $\tilde{G}=(\tilde{V},\tilde{E})$ be its suspension, that is, we add a new vertex $x$ to $G$ and connect it to all vertices in $G$. Then, we have
    $$\nu(\tilde{G})\leq \nu(G)+1.$$
    Moreover, in the special case that $G$ is a tree, this is Example \ref{ex:treesuspension}. 
\end{corollary}
\begin{proof}
    We choose $G$ as the subgraph of $\tilde{G}$. For each vertex $x\in G$, we have $d_x^{out}=1$, and the above inequality follows from Theorem \ref{thm:outdegree_upper_bound}(b).
\end{proof}


\subsection{Upper and lower Ramanujan type bounds}
\label{subsec:ramanujan}

A connected $d$-regular graph $G=(V,E)$ is called Ramanujan, if all of its eigenvalues $\lambda \not\in \{0,2d\}$ lie within the (Ramanujan) interval $[d-2\sqrt{d-1},d+2\sqrt{d-1}]$. This interval is the (continuous) $L^2$-Laplace spectrum of the $d$-regular tree. The following upper bound is derived in the spirit of the proof of the Alon-Boppana Theorem (see \cite{N91}). Recall that the girth of a graph is the length of a shortest cycle in the graph.



\begin{proposition} \label{prop:alonbopp} Let $G=(V,E)$ be a connected graph with $d_{\max} \ge 2$ and $\rm{girth}(G) \ge 2k+1$. Then we have
$$ \nu(G) \le d_{\max} - 2\sqrt{d_{\max}-1} + \frac{2 \sqrt{d_{\max}-1}-1}{k}. 
$$
\end{proposition}

\begin{proof}
Let $x_0 \in V$ be a fixed vertex. Then the girth condition implies that the subgraph induced by the vertices of the ball $B_k(x_0)$ of radius $k$ about $x_0$ is a tree. For simplicity, we denote the sphere $S_i(x_0)$ of radius $i$ about $x_0$ henceforth by $S_i$. Let $f: V \to \R$ be defined as follows: $f(x) = F_i$ for all $x \in S_i(x_0)$ for $i \le k$, where
$$ F_0 = F_1 = 1, \quad F_i = \frac{1}{(\sqrt{d-1})^{i-1}}, $$
and $f(x) = 0$, otherwise. Let $\sigma: E^{or}(G) \to S^1$ be an arbitrary magnetic potential. Since this potential can be gauged to become trivial on all edges of $B_k(x_0)$, we can assume, without loss of generality, that $\sigma$ is trivial on these edges, and the Rayleigh quotient of $f$ is given as follows
$$ \RR(f) = \frac{\sum_{i=1}^{k-1} |E(S_i,S_{i+1})| \cdot (F_{i+1}-F_i)^2 + |E(S_k,S_{k+1})| \cdot F_k^2}{\sum_{i=0}^k |S_i| \cdot F_i^2}. $$
The denominator of $\RR(f)$ is bounded below by
\begin{equation} \label{eq:crucial0} 
\sum_{i=1}^k |S_i| \cdot F_i^2 = \sum_{i=1}^k \frac{|S_i|}{(d_{\max}-1)^{i-1}}. 
\end{equation}
The first term of the numerator can be estimated from above as follows:
\begin{align}
   \sum_{i=1}^{k-1} |E(S_i,S_{i+1})| \cdot (F_{i+1}-F_i)^2 &\le \sum_{i=1}^{k-1} |S_i| (d_{\max}-1) \left( \frac{1}{(\sqrt{d_{\max}-1})^i} - \frac{1}{(\sqrt{d_{\max}-1})^{i-1}}\right)^2 \nonumber \\
   &= (d_{\max}-2\sqrt{d_{\max}-1}) \sum_{i=1}^{k-1} \frac{|S_i|}{(d_{\max}-1)^{i-1}} \label{eq:crucial1}
\end{align}
The second term of the numerator can be estimated from above as follows:
\begin{align}
|E(S_k,S_{k+1})| \cdot F_k^2 &\le  |S_k| (d_{\max}-1) \cdot \frac{1}{(d_{\max}-1)^{k-1}} \nonumber\\
&= \frac{(d_{\max}-2\sqrt{d_{\max}-1})\cdot|S_k|}{(d_{\max}-1)^{k-1}}
+ \frac{(2\sqrt{d_{\max}-1}-1)\cdot|S_k|}{(d_{\max}-1)^{k-1}} \nonumber\\
&\le \frac{(d_{\max}-2\sqrt{d_{\max}-1})\cdot|S_k|}{(d_{\max}-1)^{k-1}}
+ (2\sqrt{d_{\max}-1}-1) \cdot \frac{1}{k} \sum_{i=1}^k \frac{|S_i|}{(d_{\max}-1)^{i-1}} \label{eq:crucial2}.
\end{align}
In the derivation of \eqref{eq:crucial2}, we applied the inequality
$$ |S_{i+1}| \le (d_{\max}-1)|S_i|$$ 
recursively and applied averaging.

The total numerator, that is, the sum of \eqref{eq:crucial1} and \eqref{eq:crucial2}, amounts to
$$ \left( d_{\max} - 2 \sqrt{d_{\max}-1} + \frac{2\sqrt{d_{\max}-1}-1}{k}\right) \sum_{i=1}^k \frac{|S_i|}{(d_{\max}-1)^{i-1}}. $$
Combining this with the denominator estimate \eqref{eq:crucial0} above, we end up with the estimate
$$ \RR^\sigma(f) \le d_{\max} - 2 \sqrt{d_{\max}-1} + \frac{2\sqrt{d_{\max}-1}-1}{k}. $$
\end{proof}

% A connected $d$-regular graph $G=(V,E)$ is called Ramanujan, if all of its eigenvalues $\lambda \not\in \{0,2d\}$ lies within the interval $[d-2\sqrt{d-1},d+2\sqrt{d-1}]$.

It follows from Proposition \ref{prop:alonbopp} that we have for any sequence $G_n$ of connected $d$-regular graphs ($d \ge 3$) with ${\rm{girth}}(G_n) \to \infty$:
$$ \limsup_{n \to \infty} \nu(G_n) \le d - 2\sqrt{d-1}. $$

Next we present a lower Ramanujan bound of the magneto-spectral height for regular graphs. 

\begin{proposition} \label{prop:MSS}
Let $G=(V,E)$ be a $d$-regular graph with $d \ge 3$. Then we have
$$ d - 2\sqrt{d-1} \le \nu(G) \le d-1. $$
The upper bound is assumed for the complete graph $K_{d+1}$.
\end{proposition}

\begin{proof} Let $G=(V,E)$ be a $d$-regular graph with $d \ge 3$. By Theorem 5.5 in \cite{MSS15}, there exists
a signature $\sigma: E^{or} \to \{-1,1\}$ such that
$$ \lambda_1^\sigma(G) \ge d - 2\sqrt{d-1}, $$
which implies the lower bound. The upper bound follows
straightforwardly from \eqref{eq:nuGmindxdy} in Lemma \ref{lem:upbdxdy}.
\end{proof}

The previous two propositions imply, in particular, that we have for any infinite family $G_n$ of connected, increasing $d$-graphs, $d \ge 3$ with increasing girth, that the sequence $\nu(G_n)$ is convergent with 
$$ \lim_{n \to \infty} \nu(G_n) = d-2\sqrt{d-1}, $$
which is the lower end of the Ramanujan interval.

\begin{question} From this result it is natural to ask whether every graph with minimal vertex degree $d_{\min} \ge 3$ satisfies $\nu(G) \ge d_{\min} - 2\sqrt{d_{\min}-1}$.

A weaker question is whether for every pair $3 \le d_{\min} \le d_{\max}$ there exists $\epsilon >0$, only depending on $d_{\min}$ and $d_{\max}$, such that all graphs with 
$$ d_{\min} \le d_x \le d_{\max} $$ 
satisfy 
$$ \nu(G) > \epsilon. $$
This is false for $d_{\min}=2$, since $\nu(C_n) \to 0$, and true for $d_{\min}=d_{\max} \ge 3$, by Proposition \ref{prop:MSS}.
\end{question}

