The lower diameter bounds in this subsection and their proofs are inspired by \cite[Theorem 4.2]{ChL24} and \cite[Theorem 1.1]{ChL24}, respectively. 

\begin{proposition} \label{prop:nudiamvol}
  Let $G=(V,E)$ be a connected graph. Then we have
  $$ 
  \nu(G) \ge \inf_{\sigma: E^{or}(G) \to \{\pm 1\} \atop \text{unbalanced}} \lambda_1^\sigma(G) \ge \frac{1}{({\rm{diam}(G)+1})|V|}.
  $$
\end{proposition}

Note that the order of this inequality is sharp, since we have for cycles $\nu(C_d) \sim \frac{1}{d^2}$ and ${\rm{diam}}(C_d) \sim d$ and $|C_d| = d$.

\begin{proof}
  Let $\sigma: E^{or}(G) \to \{\pm 1\}$ be an unbalanced magnetic potential and $f: V \to \R$ be an eigenfunction to the eigenvalue $\lambda_1^\sigma(G)$. Let $x_0 \in V$ be a vertex satisfying
  $$ |f(x_0)| \ge f(x) \quad \text{for all $x\in V$. } $$
  Without loss of generality, we can assume that $f(x_0)=1$, by rescaling. This implies that
  $$ \sum_{x \in V} |f(x)|^2 \le |V|. $$
  For any path $x_0 \sim x_1 \sim \cdots \sim x_t$, we have, by Cauchy-Schwarz,
  \begin{multline*}
  \sum_{j=0}^{t-1} |f(x_j) - \sigma(x_j,x_{j+1}) f(x_{j+1})|^2 = |f(x_0)-\sigma(x_0,x_1)f(x_1)|^2 \\ + |\sigma(x_0,x_1)f(x_1)-\sigma(x_0,x_1)\sigma(x_1,x_2)f(x_2)|^2 + \cdots \\ + |\sigma(x_0,x_1)\cdots\sigma(x_{t-2},x_{t-1})f(x_{t-1}) - \sigma(x_0,x_1)\cdots\sigma(x_{t-1},x_t)f(x_t)|^2 \ge \\
  \frac{1}{t} | f(x_0) - \sigma(x_0,x_1)\cdots\sigma(x_{t-1},x_t)f(x_t)|^2. 
  \end{multline*}

  {\bf{Claim:}} There exists a path $x_0 \sim x_1 \sim \cdots \sim x_s$ of length $s \le {\rm{diam}}(G)+1$, such that 
  $$ \sum_{j=0}^{s-1} |f(x_j) - \sigma(x_j,x_{j+1}) f(x_{j+1})|^2 \ge \frac{1}{{\rm{diam}}(G)+1}. $$

  The claim is proved as follows: In the case that there exists $x \in V$ with $f(x)=0$, then we choose a path of length $t \le {\rm{diam}}(G)$ from $x_0$ to $x=x_t$, and this inequality yields
$$ \sum_{j=0}^{t-1} |f(x_j)-\sigma(x_j,x_{j+1})f(x_{j+1})|^2 \ge \frac{1}{t} |f(x_0)|^2 \ge  \frac{1}{{\rm{diam}}(G)}. $$
Now we consider the case when $f(x) \neq 0$ for all $x \in V$. Since $\sigma$ is unbalanced, there must exist an edge $x \sim y$ with
$$ f(x)\sigma(x,y)f(y) < 0 $$
for, otherwise, $\tau(x):=f(x)/|f(x)|$ would be a switching function such that $\sigma^\tau$ is the trivial magnetic potential. Now we choose a path of length $t \le {\rm{diam}}(G)$ from $x_0$ to one of $x,y$, which does not contain the other vertex. Without loss of generality the end point of this path, denoted by $x_t$, is $x$. If 
$$ \sigma(x_0,x_1)\cdots\sigma(x_{t-1},x_t)f(x_t) \le 0, $$
then we obtain 
$$ \sum_{j=0}^{t-1} |f(x_j)-\sigma(x_j,x_{j+1})f(x_{j+1})|^2 \ge \frac{1}{t} |f(x_0)|^2 \ge \frac{1}{{\rm{diam}}(G)}. $$
Otherwise, we conclude that
$$ \sigma(x_0,x_1)\cdots\sigma(x_{t-1},x_t)\sigma(x_{t},y)f(y) \le 0, $$
and we obtain, by applying the above inequality again for the extended path from $x_0$ to $y=x_{t+1}$ via $x=x_t$,
$$ \sum_{j=0}^t |f(x_j)-\sigma(x_j,x_{j+1})f(x_{j+1})|^2 \ge \frac{1}{t+1} |f(x_0)|^2 \ge \frac{1}{{\rm{diam}}(G)+1}.$$
This finishes the proof of the claim.

The claim implies that 
$$ \lambda_1^\sigma(G) = \RR(f) \ge \frac{1}{{\rm{diam}}(G)+1} \cdot \frac{1}{\sum_{x \in V} |f(x)|^2} \ge \frac{1}{({\rm{diam}(G)+1})|V|}. $$
\end{proof}

The next result holds for graphs with non-negative Bakry-\'Emery curvature. Before we state it, let us briefly introduce this curvature notion. For $f,g: V \to \C$ and $\sigma: E^{or}(G) \to S^1$, we consider the following bilinear forms:
\begin{align*}
    2 \Gamma^\sigma(f,g)(x) &= - \Delta(f\bar g)(x) + f(x) \cdot \overline{\Delta^\sigma g(x)} + \Delta^\sigma f(x) \cdot \overline{ g(x)} \\
    &= \sum_{y: y \sim x} \left( f(x)-\sigma(x,y)f(y) \right) \overline{\left(g(x)-\sigma(x,y)g(y) \right)}, \\
    2 \Gamma_2^\sigma(f,g)(x) &= \Delta \Gamma^\sigma(f,g)(x) - \Gamma^\sigma(f,\Delta^\sigma g)(x) - \Gamma^\sigma(\Delta^\sigma f,g)(x).
\end{align*}
We say that a graph $G$ satisfies the \emph{curvature-dimension inequality $CD^\sigma(K,n)$} at a vertex $x \in V$, if we have for all functions $f: V \to \C$,
$$ \Gamma_2^\sigma(f,f)(x) \ge \frac{1}{n} (\Delta^\sigma f(x))^2 + K \Gamma^\sigma(f,f)(x). $$
We say that $G$ satisfies $CD^\sigma(K,n)$ globally, if it satisfies $CD^\sigma(K,n)$ at all vertices. In the special case of the trivial signature $\sigma_0$, we use the simplified notation that $G$ satisfies $CD(K,n)$ instead of $CD^{\sigma_0}(K,n)$. This curvature notion was originally introduced in \cite{B85,BE85}. The modification for magnetic potentials was given in \cite{LMP19}. 

The $CD^\sigma$-condition at a vertex $x \in V$ is a local condition, and it is completely determined by the combinatorial structure and the magnetic potential on the incomplete $2$-ball of $x$. The incomplete $2$-ball $\mathring{B}_2(x)$ is the induced subgraph of the $2$-ball $B_2(x)$ with all spherical edges within the $2$-sphere $S_2(x)$ removed.

% The proof of the next proposition follows the arguments given in the proof of Theorem 1.1 in Section 3.2 of \cite{ChL24}.

\begin{proposition} \label{prop:nudiam} Let $G=(V,E)$ be a connected, non-bipartite, triangle-free graph satisfying $CD(0,\infty)$. Then we have
$$ \nu(G) \ge \frac{C}{{\rm{diam}}^2(G)} $$
with a universal constant $C$.
\end{proposition}

\begin{proof}
{\bf{Step 1:}} In this step, we prove the following: If $G=(V,E)$ is a connected graph satisfying $CD^\sigma(0,\infty)$ for an unbalanced signature $\sigma: E^{or}(G) \to \{-1,1\}$, then
$$ \lambda_1^\sigma(G) \ge \frac{C}{{\rm{diam}}^2(G)} $$
for a universal constant $C$.
Since $\sigma$ is unbalanced, we know that $\lambda_1^\sigma=\lambda_1^\sigma(G) > 0$.  Let $f: V \to \R$ be an eigenfunction of $\Delta^\sigma$ to the eigenvalue $\lambda_1^\sigma$. Let
$$ g(x) = 2 \Gamma^\sigma f(x) + \alpha \lambda_1^\sigma f^2(x) $$
% where
% \begin{align*}
% 2 \Gamma^\sigma(F,G)(x) &= -\Delta (FG)(x) + F(x) \Delta^\sigma G(x) + G \Delta^\sigma F(x) \\
% &= \sum_{y \sim x} (F(x)-\sigma(x,y)F(y))(G(x)-\sigma(x,y)G(y)).
% \end{align*}
and $v \in V$ be such that
$$ g(v) = \max_{x \in V} g(x). $$
Then we have 
\begin{align*} 
0 \le \Delta g(v) &= 2\Delta \Gamma^\sigma f(v) + \alpha \lambda_1^\sigma \Delta f^2(v) \\
% &= 2\Delta \Gamma^\sigma f(v) + \alpha \lambda_1^\sigma (-2 \Gamma^\sigma f(v) + 2 f(v) \Delta^\sigma f(v)) \\
&= 2\Delta \Gamma^\sigma f(v) + 2 \alpha \lambda_1^\sigma ( f(v) \Delta^\sigma f(v)-\Gamma^\sigma f(v)).
\end{align*}
On the other hand, we conclude from the $CD^\sigma(0,\infty)$-condition
$$ 4 \Gamma_2^\sigma(f)(v) = - (2\Delta \Gamma^\sigma f)(v) + 4 \Gamma^\sigma(f,\Delta^\sigma f)(v) \ge 0. $$
Combining both results yields
\begin{align*} 
0 &\le 4 \Gamma^\sigma(f,\Delta^\sigma f)(v) + 2 \alpha \lambda_1^\sigma ( f(v) \Delta^\sigma f(v)-\Gamma^\sigma f(v))  \\
&= 2 \left( 2\lambda_1^\sigma \Gamma^\sigma(f)(v) + \alpha (\lambda_1^\sigma)^2f^2(v) - \alpha \lambda_1^\sigma \Gamma^\sigma f(v) \right) \\
&= 2 \left( \alpha (\lambda_1^\sigma)^2 f^2(v) + (2-\alpha)\lambda_1^\sigma \Gamma^\sigma(f)(v) \right). 
\end{align*}
Assuming $\alpha >2$, this implies
$$ \Gamma^\sigma f(v) \le \frac{\alpha}{\alpha-2} \lambda_1^\sigma f^2(v). $$
Using this, we obtain for any $x \in V$:
\begin{align*}
g(x) \le g(v) &= 2 \Gamma^\sigma f(v) + \alpha \lambda_1^\sigma f^2(v) \\
& \le \frac{2\alpha}{\alpha-2} \lambda_1^\sigma f^2(v) + \alpha \lambda_1^\sigma f^2(v) \\
&\le \frac{\alpha^2}{\alpha-2} \lambda_1^\sigma \max_{z \in V}f^2(z).
\end{align*}
This implies that we have for all $x \in V$,
$$ \sum_{y \sim x} |f(x) - \sigma(x,y)f(y)|^2 = 2 \Gamma^2f(x) \le g(x) \le \frac{\alpha^2}{\alpha-2} \lambda_1^\sigma \max_{z \in V } f^2(z).  $$
Without loss of generality, we can scale $f$ in such a way that
$$ f(x_0) = \max_{z \in V} f(z) = 1 $$
and
$$ f(x) \ge -1 \quad \text{for all $x \in V$.} $$
The claim in the proof of Proposition \ref{prop:nudiamvol} guarantees the existence of a path $x_0 \sim x_1 \sim \cdots \sim x_s$ of length $s \le {\rm{diam}}(G)+1$, satisfying
$$ \sum_{j=0}^{s-1} |f(x_j) - \sigma(x_j,x_{j+1}) f(x_{j+1})|^2 \ge \frac{1}{{\rm{diam}}(G)+1}. $$
Using the above estimate, we conclude that
$$ \frac{1}{{\rm{diam}}(G)+1} \le \sum_{j=0}^{s-1} \frac{\alpha^2}{\alpha-2} \lambda_1^\sigma \max_{z \in V} f^2(z) \le \frac{\alpha^2}{\alpha-2}({\rm{diam}}+1)\lambda_1^\sigma. $$
This finishes the proof of step 1.

\medskip

{\bf Step 2:} Assume that $G=(V,E)$ is a connected, non-bipartite triangle-free graph satisfying $CD(0,\infty)$. Let $\overline{\sigma}: E^{or}(G) \to S^1$ be the anti-balanced magnetic potential. Since $G$ is not bipartite, $\overline{\sigma}$ is an unbalanced magnetic potential. 

Triangle-freeness guarantees that, at every vertex $x \in V$, the magnetic potential on the incomplete $2$-ball $\mathring{B}_2(x)$ can be gauged to be trivial. 
Since the $CD^\sigma(K,n)$ condition at a vertex $x \in V$ is determined by the incomplete $2$-ball $\mathring{B}_2(x)$ and does not change under gauge transforms, we conclude that $G$ satisfies also the $CD^\sigma(0,\infty)$-condition at all vertices. Then the statement of the proposition follows from Step 1.
\end{proof}

\section{Graph constructions} \label{sec:graphconstructions}

In this section, we discuss the behaviour of our magneto-spectral invariant under various graph constructions.

\subsection{Connecting two non-adjacent vertices}

\begin{lemma} \label{lem:addedge}
    Let $G=(V,E)$ be a graph and $\tilde G=(V,\tilde E)$ be obtained from $G$ by adding an edge between two distinct vertices of $G$. Then we have
    $$ \nu(\tilde G) \ge \nu(G). $$
\end{lemma}

This is a straightforward consequence of the Rayleigh quotient, since this graph manipulation adds an additional non-negative term in the numerator of the Rayleight quotient. An immediate consequence of the lemma and the results in Example \ref{ex:cycle} is the following

\begin{corollary} Assume that a graph $G=(V,E)$ with $N$ vertices admits a Hamiltonian cycle. Then we have
$$ \nu(G) \ge \nu(C_N) = 2-2\cos(\pi/N). $$
\end{corollary}

\subsection{Adding a bridge between two graphs}

It is obvious that we have for two disjoint graphs $G$ and $H$:
\begin{equation} \label{eq:GHnu} 
\nu(G \cup H) = \min(\nu(G),\nu(H)). 
\end{equation}

\begin{lemma} \label{lem:GHbridge}
  Let $G=(V,E)$ and $H=(V',E')$ be two disjoint graphs and $\tilde G = (\tilde V, \tilde E)$ be obtained by connecting $G$ and $H$ by an edge (bridge). Then we have
  \begin{equation} \label{eq:minmaxsqueeze} 
  \min(\nu(G),\nu(H)) \le \nu(\tilde G) \le \max(\nu(G),\nu(H)). 
  \end{equation}
\end{lemma}

\begin{proof} The lower bound of \eqref{eq:minmaxsqueeze} follows directly from \eqref{eq:GHnu} and Lemma \ref{lem:addedge}. 

For the upper bound, we choose $\hat \sigma: E^{or}(\tilde G) \to S^1$ to satisfy
$$ \nu(\tilde G) = \lambda_1^{\tilde \sigma}(\tilde G). $$
Let $x_0 \in V$ and $z_0 \in V'$ be the bridge in $\tilde G$. Then we have for any nonzero function $f: \tilde V \to \C$,
\begin{multline*} 
\RR^{\hat \sigma}(f) = \\ \frac{{\displaystyle{\sum_{\{x,y\} \in E}}} |f(x)-\hat \sigma(x,y)f(y)|^2 + {\displaystyle{\sum_{\{z,w\} \in E'}}} |f(z)-\hat \sigma(z,w)f(w)|^2 + |f(x_0) - \hat \sigma(x_0,z_0) f(z_0)|^2}{\sum_{x \in V} |f(x)|^2 + \sum_{z \in V'} |f(z)|^2}. 
\end{multline*}
Let $\sigma_1$ and $\sigma_2$ be the restrictions of $\hat \sigma$ to the graphs $G$ and $H$, respectively. Let $f_1: V \to \C$ and $f_2: V' \to \C$ be non-zero functions satisfying 
$$ \RR^{\sigma_1}(f_1) = \lambda_1^{\sigma_1}(G) \quad \text{and} \quad \RR^{\sigma_2}(f_2) = \lambda_1^{\sigma_2}(H). $$
In the case that $f_1(x_0)$ and $f_2(z_0)$ are either both zero or both non-zero, we can assume, after rescaling, that $|f_1(x_0)-\hat \sigma(x_0,z_0)f_2(z_0)| = 0$, and that
$$ f(v) = \begin{cases} f_1(v) & \text{if $v \in V$,} \\ f_2(v) & \text{if $v \in V'$,} \end{cases} $$
is non-zero, too. Then we have
$$ \RR^{\hat \sigma}(f) = \frac{\sum_{\{x,y\}\in E} |f(x)-\hat \sigma(x,y)f(y)|^2 + \sum_{\{z,w\} \in E'} |f(z)-\hat \sigma(z,w)f(w)|^2}{\sum_{x \in V} |f(x)|^2 + \sum_{z \in V'} |f(z)|^2}, $$
and applying
$$ \frac{a+b}{c+d} \le \max\left\{\frac{a}{c},\frac{b}{d}\right\} $$
for $a,b,c,d > 0$, we conclude that
\begin{align*} 
\nu(\tilde G) &= \lambda_1^{\hat \sigma}(\tilde G) \le \RR^{\hat \sigma}(f) \\ &\le \max\left\{\frac{\sum_{\{x,y\} \in E} |f_1(x)-\sigma_1(x,y)f_1(y)|^2}{\sum_{x \in V} |f_1(x)|^2}, \frac{\sum_{\{z,w\} \in E'} |f_2(z)-\sigma_2(z,w)f_2(w)|^2}{\sum_{z \in V'} |f_2(z)|^2} \right\}\\
&= \max\left\{\RR^{\sigma_1}(f_1),\RR^{\sigma_2}(f_2)\right\} = \max\{\lambda_1^{\sigma_1}(G)\,\lambda_1^{\sigma_2}(H)\} \le \max\{\nu(G),\nu(H)\}.
\end{align*}
It remains to consider the case when precisely one of $f_1(x_0), f_2(z_0)$ is zero. Assume, without loss of generality, that $f_1(x_0) = 0$ and $f_2(z_0) \neq 0$.
We set
$$ f(v) = \begin{cases} f_1(v) & \text{if $v \in V$,} \\ 0 & \text{if $v \in V'$.} \end{cases}$$
Note that $f$ is non-zero, and we obtain
\begin{align*} 
\nu(\tilde G) &= \lambda_1^{\hat \sigma}(\tilde G) \le \RR^{\hat \sigma}(f) \\ &\le \frac{\sum_{\{x,y\}\in E} |f_1(x)-\sigma_1(x,y)f_1(y)|^2}{\sum_{x \in V} |f_1(x)|^2}\\
&= \RR^{\sigma_1}(f_1) = \lambda_1^{\sigma_1}(G) \le \nu(G).
\end{align*}
\end{proof}

A special case of the above lemma is the following, by choosing $H$ to be a single vertex:

\begin{corollary} Let $G$ be a graph and $\tilde G$ be obtained by adding a dangling edge to $G$. Then we have
$$ \nu(\tilde G) \le \nu(G). $$
\end{corollary}

\subsection{Splitting vertices and edges}

We first discuss a graph manipulation involving the splitting of a vertex.

\begin{lemma}\label{lem:splitvertex}
    Let $G=(V,E)$ be a graph and $x \in V$ be a vertex of degree $d=d_1+d_2$. Let $\tilde G=(\tilde V,\tilde E)$ be the graph obtained by splitting $x$ into two non-adjacent vertices $x_1,x_2$, where $x_1$ is adjacent to $d_1$ neighbours of $x$ and $x_2$ adjacent to the other $d_2$ neighbours of $x$. Then we have
    $$ \nu(G) \ge \nu(\tilde G). $$
\end{lemma}

\begin{proof}
Note that under this operation, the set of edges is unchanged (with the minor modification that an edge incident to $x$ is now incident to either $x_1$ or $x_2$). Let $\sigma: E^{or}(G) \to S^1$ be a magnetic potential and $f: V \to \C$ be an arbitrary non-zero function. Let $\tilde \sigma: E^{or}(\tilde G) \to S^1$ be the corresponding magnetic potential inheriting the directed edge values of $\sigma$ and $\tilde f: \tilde V \to \C$ be the following function:
$$ \tilde f(z) = \begin{cases} f(z) & \text{if $z \in V \setminus \{x\}$,} \\ f(x) & \text{if $z\in \{x_1,x_2\}$.} \end{cases} $$
If numerator and denominator of $\RR^\sigma_G(f)$ is denoted by $A$ and $B$, then we have
$$ \RR^{\tilde \sigma}_{\tilde G}(\tilde f) = \frac{A}{B - |f(x)|^2 + |\tilde f(x_1)|^2 + |\tilde f(x_2)|^2} = \frac{A}{B + |f(x)|^2} \le \frac{A}{B} = \RR^\sigma_G(f). $$
This finishes the proof.
\end{proof}

\begin{corollary}
Let $G=(V,E)$ be a graph whose vertices have even degrees. Then we have
$$ \nu(G) \ge 2 - 2 \cos\left( \frac{\pi}{|E|} \right). $$
Moreover, if this inequality holds with equality, then $G$ is the cycle $C_{|E|}$.
\end{corollary}

\begin{proof} Applying the above graph manipulation iteratively, we end up with a new graph $\tilde G$ with the same number of edges and which is $2$-regular. Any $2$-regular graph is a disjoint union of cycles. Assume $C_d$ ($d \le |E|$) is the largest cycle in this disjoint union. Using \eqref{eq:GHnu} and \eqref{eq:nucycle}, we conclude that
$$ \nu(G) \ge \nu(\tilde G) \ge \nu(C_d) = 2-2\cos\left(\frac{\pi}{d}\right) \ge 2-2\cos\left(\frac{\pi}{|E|}\right). $$
This shows
$$ \nu(G) \ge 2 - 2 \cos\left( \frac{\pi}{|E|} \right). $$
If $G$ is not the cycle $C_{|E|}$, then we apply these graph manipulations only until we end up with a graph $\tilde G$ with all but one vertices of degree $2$ and the remaining vertex $x$ of degree $4$. The connected component of $\tilde G$ containing $x$ must be the union of two disjoint cycles glued at the vertex $x$. In the last step, we split $x$ and disconnect this connected component into two disjoint cycles $C_j$ and $C_k$ with $j,k < |E|$. Using \eqref{eq:GHnu}, we conclude that
$$ \nu(G) \ge \nu(\tilde G) \ge \nu(C_k) = 2-2\cos\left(\frac{\pi}{k}\right) > 2-2\cos\left(\frac{\pi}{|E|}\right), $$
proving the rigidity statement.
\end{proof}

\begin{remark} In view of the above construction, we observe the following: If it is true that there exists a universal $\epsilon >0$ such that all graphs $G$ with minimal vertex degree $\ge 3$ satisfy $\nu(G) > \epsilon$, then it is sufficient to prove this statement for all graphs $G$ with minimal vertex degree $3$ and maximal vertex degree $5$.
\end{remark}

The next result is concerned with the splitting of an edge.

\begin{lemma} \label{lem:splitedge}
Let $G=(V,E)$ be a graph and $\tilde G=(\tilde V,\tilde E)$ be obtained by splitting an edge in $G$. Then we have
$$ \nu(\tilde G) \le \nu(G). $$
More generally, if $\tilde G$ is a subdivision of $G$, then we have
$$ \nu(\tilde G) \le \nu(G). $$
\end{lemma}

\begin{proof}
    Let $\{x,y\} \in E$ be the edge which is split with an additional vertex $z$, that is, $\tilde V = V \cup \{z\}$ and 
    $$ \tilde E = \left( E \setminus \{ \{x,y\} \} \right) \cup \{ \{x,z\},\{z,y\}\}. 
    $$
    Let $\hat \sigma$ be a maximal magnetic potential of $\tilde G$, that is,
    $$ \nu(\tilde G) = \lambda_1^{\hat \sigma}(\tilde G). $$
    Let $\sigma_1$ be the magnetic potential on $G$ which agrees with $\hat \sigma$ on the edges $E\setminus\{\{x,y\}\}$ and which satisfies
    $$ \sigma_1(x,y) = \hat \sigma(x,z) \hat \sigma(z,y). $$
    Let $f: V \to \C$ be a non-zero function satisfying
    $$ \lambda_1^{\sigma_1}(G) = \RR^{\sigma_1}(f). $$
    Let $\tilde f: \tilde V \to \C$ be the function which agrees with $f$ on the vertices in $V$ and which satisfies 
    $$ \tilde f(z) = \hat \sigma(x,z)^{-1}f(x). $$
    Then we have
    \begin{align*} 
    \nu(\tilde G) &\le \RR^{\hat\sigma}(\tilde f) \\
    &= \frac{|\tilde f(x)-\hat \sigma(x,z)\tilde f(z)|^2 + |\tilde f(z)-\hat \sigma(z,y)\tilde f(y)|^2 + \displaystyle{\sum_{\{v,w\}\in E\setminus \{\{x,y\}\}}} |\tilde f(v)-\hat \sigma(v,w)\tilde f(w)|^2}{|\tilde f(z)|^2 + \sum_{w \in V} |\tilde f(w)|^2} \\
    &\le \frac{ |f(x)-\hat \sigma(x,z) \hat \sigma(z,y) f(y)|^2 + \displaystyle{\sum_{\{v,w\}\in E\setminus \{\{x,y\}\}}} |f(v)-\sigma_1(v,w)f(w)|^2}{\sum_{w \in V} |f(w)|^2} \\
    &= \RR^{\sigma_1}(f) = \lambda_1^{\sigma_1}(G) \le \nu(G).
\end{align*}
\end{proof}

\subsection{Cartesian products}

\begin{lemma} \label{lem:cartprod} Let $G$ and $H$ be two graphs. Then we have
$$ \nu(G \times H) \ge \nu(G) + \nu(H). $$
\end{lemma}

\begin{proof}
    We use the following fact for magnetic potentials $\sigma_1$ and $\sigma_2$ on $G$ and $H$, respectively, and their Cartesian product magnetic potential $ \sigma$:
    $$ {\rm{spec}}^{\sigma}(G \times H) = \left\{ \lambda + \mu: \lambda \in {\rm{spec}}^{\sigma_1}(G), \mu \in {\rm{spec}}^{\sigma_2}(H) \right\}, $$
    where ${\rm{spec}}^\sigma$ is the multiset of eigenvalues of the magnetic Laplacian $\Delta^\sigma$. Here $\sigma: E^{or}(G \times H) \to S^1$ is defined as follows:
    $$ \sigma(\{(x,z),(y,z)\}) = \sigma_1(x,y) \quad\text{for all $x \sim_G y$ and $z \in H$} $$
    and
    $$ \sigma(\{(x,z),(x,w)\}) = \sigma_2(z,w) \quad \text{for all $x \in G$ and $z \sim_H w$.} $$
    This implies that
    $$ \lambda_1^{\sigma}(G \times H) = \lambda_1^{\sigma_1}(G) + \lambda_1^{\sigma_2}(H). $$
    Therefore, we have
    \begin{align*} 
    \nu(G \times H) &= \sup_\sigma \lambda_1^\sigma(G \times H) \\ &\ge \sup_{\sigma_1,\sigma_2} \left(\lambda_1^{\sigma_1}(G) + \lambda_1^{\sigma_2}(H) \right) \\ &= \sup_{\sigma_1} \lambda_1^{\sigma_1}(G) + \sup_{\sigma_2 }\lambda_1^{\sigma_2}(H) = \nu(G) + \nu(H). 
    \end{align*}
\end{proof}

\subsection{Suspensions}

Regarding suspensions, we have the following result.

\begin{theorem} \label{thm:suspgraph}
Let $G$ be an arbitrary connected graph and $\tilde G$ be its suspension. Then we have
\begin{equation} \label{eq:nutildeGnuG} 
1 \le \nu(\tilde G) \le \nu(G)+1. 
\end{equation}
In particular, we have 
\begin{equation} \label{eq:nutildeT} 
\nu(\tilde T) = 1 
\end{equation}
for the suspension $\tilde T$ of any tree $T$.
\end{theorem}

\begin{proof} The upper bound of $\nu(\tilde G)$ follows directly from Corollary \ref{cor:suspension}. Regarding the lower bound for $\nu(\tilde G)$, it is sufficient to prove it for trees due to Lemma \ref{lem:addedge}. The result \eqref{eq:nutildeT} for the suspension of trees $T$ follows then immediately from \eqref{eq:nutildeGnuG} and $\nu(T)=0$.

Let us now provide the proof of the lower bound in \eqref{eq:nutildeGnuG} for a tree $T=(V,E)$ with $V = \{x_1,\dots,x_t\}$. Let $x$ be the suspension vertex of $\tilde T$. Any $\sigma: E^{or}(\tilde T) \to S^1$ can be switched to a magnetic potential which is trivial on the edges of the tree and assumes the values $a_j = -e^{i \alpha_j}$ on the directed edge 
$(x,x_j) \in E^{or}(\tilde T)$. The corresponding Laplacian is represented by the following matrix:
$$ \Delta^\sigma \cong \begin{pmatrix} \begin{array}{c|ccccc}t & a_1 & a_2 & \cdots & a_{t-1} & a_t \\
\hline
\bar a_1 & & & & & \\
\bar a_2 & & & & & \\
\vdots & & & \Delta_T + {\rm{Id}} & & \\
\bar a_{t-1} & & & & & \\
\bar a_t & & & & &
\end{array}
\end{pmatrix},
$$
where $\Delta_T$ is the non-normalized standard Laplacian
of the tree $T$. Under the assumption that the values $a_1,\dots,a_t \in S^1$ satisfy
\begin{equation} \label{eq:sumaj}
\sum_{j=1}^t a_j = 0,
\end{equation}
the vector $(0,1,\dots,1)^\top$ is an eigenvector of $\Delta^\sigma$ to the eigenvalue $1$ since any constant vector is an eigenvector of $\Delta_T$ to the eigenvalue $0$. It remains to prove that $1$ is the smallest eigenvalue of $\Delta^\sigma$ for a suitable choice of $a_1,\dots,a_t \in S^1$ satisfying \eqref{eq:sumaj}, since we already know from Example \ref{ex:treesuspension} that $\nu(\tilde T) \le 1$. We prove this by showing that we can choose $a_1,\dots,a_t \in S^1$ such that 
$$ \Delta^\sigma - {\rm{Id}} \cong \begin{pmatrix} \begin{array}{c|ccccc}t-1 & a_1 & a_2 & \cdots & a_{t-1} & a_t \\
\hline
\bar a_1 & & & & & \\
\bar a_2 & & & & & \\
\vdots & & & \Delta_T & & \\
\bar a_{t-1} & & & & & \\
\bar a_t & & & & &
\end{array}
\end{pmatrix} $$
is positive semidefinite. The corresponding quadratic form for the complex variables $z,z_1,\dots,z_t \in \C$ is given by
\begin{equation} \label{eq:Q}
Q=(t-1) |z|^2 + \sum_{j=1}^t (a_j z \bar z_j + \bar a_j \bar z z_j) + \sum_{j=1}^t d_{x_j} |z_j|^2 - \sum_{\{x_j,x_k\} \in E} (z_j \bar z_k + \bar z_j z_k).
\end{equation}
We consider $T$ to be a rooted tree with a leaf root $x_1$ and assume the other vertices $x_2,\dots,x_t$ to be ordered with respect to the distance to the root. Note that every vertex in $T$ has at most one parent and potentially several children. Let $I$ be the set of index pairs $(k,l)$ corresponding to oriented edges $x_k \sim x_l$ in $T$ with $x_k$ the parent of $x_l$. Let 
$$ S_6 = \{\pm 1, \pm \omega, \pm \omega^2\} $$
be the set of all $6$-th roots of unity with $\omega = e^{2\pi i/3}$. The following claim allows us to find a suitable choice of $a_1,\dots,a_t \in S^1$ with the required properties.

\medskip

{\bf{Claim:}} There exist a family of values $\{ b_{jk} \}_{(j,k) \in I}$ in $S_6$ which satisfies the following: For any vertex $x_j \in T$ we have  
\begin{equation} \label{eq:tildeaj} 
a_j := \left( \sum_{k: (j,k) \in I} b_{jk}\right) - b_{j_0j} \in S_6, 
\end{equation}
where $x_{j_0} \in T$ is the parent of $x_j$.
Here we use the convention that, for vertices without parents or without children, the corresponding term is chosen to be zero.

\medskip

