	\section{Alternative definition of the discontinuity calculus}
	\label{appx:def-dgen}


	Define the operator $\dgen\equiv1-\disc$. The four properties (\ref{eq:disc-rule-1}--\ref{eq:disc-rule-4}) satisfied by the discontinuity operator $\disc$ introduced in Sec.~\ref{sec:def-disc} can be equivalently expressed as the following four properties satisfied by the operator $\dgen$:
	%

	\noindent (1) Preservation of holomorphy:
	\begin{equation}
		\dgen h(z)=h(z).\tag{R1$'$}
	\end{equation}
	%
	(2) Linearity:
	%
	\begin{equation}
		\dgen\left[\alpha_1 f_1(z)+\alpha_2 f_2(z)\right]=\alpha_1\dgen f_1(z)+\alpha_2\dgen f_2(z).\tag{R2$'$}
	\end{equation}
	%
	(3) Associative homomorphism:  
	\begin{equation}
		\dgen \left[f_1(z)f_2(z)\right]=\dgen f_1(z) \dgen f_2(z).\tag{R3$'$}
	\end{equation}
	%
	(4) Chain rule:
	\begin{equation}
		\dgen F\left[f(z)\right]=\dgen F\left[\omega\right]\big|_{\omega=\dgen f(z)}.\tag{R4$'$}
	\end{equation}


	\section{Direct calculation of discontinuities in the two-point Green's function}
	\label{appx:disc-2PGfunc-def}

	The two-point Green's function $G(s)$ is defined by Eq.~\eqref{eq:def-2PGreenfunction}, which can be rewritten as:
	\begin{equation}
		G(s)=\int_{\mathbb{R}^4} \frac{i d^4 q}{(2 \pi)^4} \frac{1}{D_1^+ D_2^- D_3^- D_4^+},
        \label{eq:def-G-mod}
	\end{equation}
	where 
	\begin{align}
		& D_1^\pm\equiv q^0+E / 2-\omega_1\pm i \epsilon,\notag\\
		& D_2^\pm\equiv q^0+E / 2+\omega_1\pm i \epsilon, \notag\\
		& D_3^\pm\equiv q^0-E / 2+\omega_2\pm i \epsilon, \notag\\
		& D_4^\pm\equiv q^0-E / 2-\omega_2\pm i \epsilon. \notag
	\end{align}
	The calculation is performed in the center-of-mass frame by setting $p=(E,\mathbf{0})$, where $\omega_i=\sqrt{|\mathbf{q}|^2+m_i^2}~(i=1,2)$ denotes the on-shell energy of particle-$i$, and $E=\sqrt{s}$ represents the total energy.

	We now consider the discontinuity of $G(s)$ with respect to $E$:
	\begin{equation}
		\disc_{E} G(s)=\int_{\mathbb{R}^4} \frac{i d^4 q}{(2 \pi)^4} \disc_{E}\left(\frac{1}{D_1^+ D_2^- D_3^- D_4^+}\right).
		\label{eq:disc-G-def}
	\end{equation}
	%
	According to Eq.~\eqref{eq:disc-rule-3}, we need to compute the discontinuities of all four terms in the integrand. By convention, the physical region corresponds to the upper edge of the real axis in the complex $E$-plane. Using Eq.~\eqref{eq:disc-1/x}, we obtain:
	\begin{align}
		& \disc_{E}\left(\frac{1}{D_1^\pm}\right)=-2 \pi i ~\delta\!\left(q^0+E / 2-\omega_1\right) \equiv-2 \pi i~ \delta_1, \notag\\
		& \disc_{E}\left(\frac{1}{D_2^\pm}\right)=-2 \pi i ~\delta\!\left(q^0+E / 2+\omega_1\right) \equiv-2 \pi i~ \delta_2, \notag\\
		& \disc_{E}\left(\frac{1}{D_3^\pm}\right)=+2 \pi i ~\delta\!\left(q^0-E / 2+\omega_2\right) \equiv +2 \pi i~ \delta_3, \notag\\
		& \disc_{E}\left(\frac{1}{D_4^\pm}\right)=+2 \pi i ~\delta\!\left(q^0-E / 2-\omega_2\right) \equiv +2 \pi i~ \delta_4.\notag
	\end{align}
	Since the small imaginary component $\pm i\epsilon$ in the argument of the Dirac delta function does not affect subsequent analyses, we have omitted it in the results above for simplicity. Substituting the above results into Eq.~\eqref{eq:disc-G-def} yields:
\begin{widetext}
		\begin{align}
		\disc_{E}G(s)=\int_{\mathbb{R}^4} \frac{i d^4 q}{(2 \pi)^4} & \left[~~2 \pi i\left(-\frac{\delta_1}{D_2^- D_3^- D_4^+}-\frac{\delta_2}{D_1^+ D_3^- D_4^+}+\frac{\delta_3}{D_1^+ D_2^- D_4^+}+\frac{\delta_4}{D_1^+ D_2^- D_3^-}\right)-\right. \notag\\
		& \quad\, (2 \pi i)^2\left(\frac{\delta_1 \delta_2}{D_3^- D_4^+}-\frac{\delta_1 \delta_3}{D_2^- D_4^+}-\frac{\delta_1 \delta_4}{D_2^- D_3^-}-\frac{\delta_2 \delta_3}{D_1^+ D_4^+}-\frac{\delta_2 \delta_4}{D_1^+ D_3^-}+\frac{\delta_3 \delta_4}{D_1^+ D_2^-}\right)+ \notag\\
		& \quad\left.(2 \pi i)^3\left(\frac{\delta_1 \delta_2 \delta_3}{D_4^+}+\frac{\delta_1 \delta_2 \delta_4}{D_3^-}-\frac{\delta_1 \delta_3 \delta_4}{D_2^-}-\frac{\delta_2 \delta_3 \delta_4}{D_1^+}\right)-(2 \pi i)^4 \delta_1 \delta_2 \delta_3 \delta_4~~\right].
		\label{eq:disc-G-expand}
	\end{align}
% \end{widetext}
	%

	In this work, we restrict our analysis to scenarios with non-zero masses $m_1,m_2>0$, ensuring that the on-shell energies $\omega_1,\omega_2>0$. This mass condition leads to the vanishing products $\delta_1\delta_2=\delta_3\delta_4=0$. Substituting this condition into Eq.~\eqref{eq:disc-G-expand}, we obtain:
	% \begin{widetext}
		\begin{align}
			\disc_{E}G(s)=\int_{\mathbb{R}^4} \frac{id^4 q}{(2 \pi)^4}&\left[~~2 \pi i\left(-\frac{\delta_1}{D_2^- D_3^- D_4^+}-\frac{\delta_2}{D_1^+ D_3^- D_4^+}+\frac{\delta_3}{D_1^+ D_2^- D_4^+}+\frac{\delta_4}{D_1^+ D_2^- D_3^-}\right)+\right.\notag\\
			&\quad\left.(2 \pi i)^2\left(\frac{\delta_1 \delta_3}{D_2^- D_4^+}+\frac{\delta_1 \delta_4}{D_2^- D_3^-}+\frac{\delta_2 \delta_3}{D_1^+ D_4^+}+\frac{\delta_2 \delta_4}{D_1^+ D_3^-}\right)~~\right].\notag
		\end{align}
	\end{widetext}
	%
	The first line on the right-hand side contains terms with a single Dirac-$\delta$ function, referred to as single-pole terms, while the second line comprises terms with two Dirac-$\delta$ functions, referred to as double-pole terms.
	%

    \begin{figure*}
