			%
		(c) By deforming the contour in panel (b), the two poles can be relocated to the same side (e.g., by moving the blue pole from the upper to the lower half-plane). To preserve the continuity of the integral, an additional integration over a closed contour with winding number $+1$ encircling the blue pole is introduced. Even in this configuration, pole coalescence continues to pinch the contour, thereby generating singularities.
			%
		(d) When the poles approach each other while being enclosed by sub-contours with identical winding numbers (e.g., both with winding number $+1$), no pinching occurs, and the integral remains free of singularities.}
		\label{fig:5}
	\end{figure*}

	We first analyze the single-pole terms. For these terms, branch points that contribute to the discontinuity can emerge in the integral only when the pole positions coincide with the endpoints of the complex $q^0$-plane integration contour. In our case, however, the integration path spans the entire real axis, which can be equivalently viewed as a closed contour that closes at infinity, and thus inherently lacks endpoints. Consequently, the single-pole terms do not contribute to the discontinuity.

	Next, we investigate the contributions from double-pole terms. For clarity, we henceforth denote the relevant poles directly as $\delta_i(i=1,2,3,4)$. Consider first a generalized integral of the following form:
	\begin{equation}
		I(s,\bm{n})\equiv\int_{\mathcal{C}(\bm{n})\times\mathbb{R}^3}\frac{i d^4 q}{(2 \pi)^4}\frac{1}{D_1^+ D_2^+ D_3^+ D_4^+},\notag
	\end{equation}
	%
	where $\mathcal{C}(\bm{n})$ represents the integration contour in the complex $q^0$-plane, with the vector $\bm{n}=(n_1,n_2,n_3,n_4)\in\mathbb{Z}^4$ labeling the homotopy equivalence classes of closed contours. Specifically, for $\bm{n}=\mathbf{0}$, the contour $\mathcal{C}(\mathbf{0})$ coincides with the entire real axis. For $\bm{n}\neq\mathbf{0}$, the contour $\mathcal{C}(\bm{n})$ comprises not only the real axis but also closed loops encircling each pole $\delta_i$ with winding number $n_i$, where $n_i>0$ indicates counterclockwise encirclements and $n_i<0$ indicates clockwise ones.

	From the analysis above, we conclude that only the double-pole terms contribute to the discontinuity of the integral $I(s,\bm{n})$. For a specific double-pole term, its contribution depends on whether the integration contour is pinched between the two corresponding poles. In general, we have:
	\begin{widetext}
		\begin{align}
			\disc_E I(s,\bm{n})=&\int_{\mathcal{C}(\bm{n})\times\mathbb{R}^3}\frac{i d^4 q}{(2 \pi)^4}\left[(2 \pi i)^2\left(\frac{\delta_1 \delta_3}{D_2^+ D_4^+}+\frac{\delta_1 \delta_4}{D_2^+ D_3^+}+\frac{\delta_2 \delta_3}{D_1^+ D_4^+}+\frac{\delta_2 \delta_4}{D_1^+ D_3^+}\right)\right] \notag\\
            =&\int_{\mathbb{R}^4}\frac{i d^4 q}{(2 \pi)^4}\left\{\left(2\pi i\right)^2\left[c_{13}(\bm{n})\frac{\delta_1\delta_3}{D_2^+D_4^+}+c_{14}(\bm{n})\frac{\delta_1\delta_4}{D_2^+D_3^+}+c_{23}(\bm{n})\frac{\delta_2\delta_3}{D_1^+D_4^+}+c_{24}(\bm{n})\frac{\delta_2\delta_4}{D_1^+D_3^+}\right]\right\},
			\label{eq:disc-I}
		\end{align}
	% \end{widetext}
	where $c_{ij}(\bm{n})~(ij\in\{13,14,23,24\})$ are integer-valued functions of the homotopy class $\bm{n}$, explicitly given by $c_{ij}(\bm{n})=n_i-n_j$. 
    %
    For an intuitive explanation of this result, we refer to Fig.~\ref{fig:5}.

	Crucially, the two-point Green's function $G(s)$ in Eq.~\eqref{eq:def-G-mod} specifies that two of the four poles ($\delta_2$ and $\delta_3$) are located on the upper edge of the complex $q^0$-plane integration contour. By deforming the contour to relocate all poles to the lower edge of the integration contour, we acquire an additional integration over closed loops encircling $\delta_2$ and $\delta_3$ with winding number $+1$. Thus, by setting $\bm{n}_G=(0,1,1,0)$, we identify $G(s)=I(s,\bm{n}_G)$. Substitution into Eq.~\eqref{eq:disc-I} yields:
	% \begin{widetext}
		\begin{align}
			\disc_E G(s) =\disc_E I(s,\bm{n}_G)=& \int_{\mathbb{R}^4}\frac{i d^4 q}{(2 \pi)^4}\left[\left(2\pi i\right)^2\left(-\frac{\delta_1\delta_3}{D_2^+D_4^+}+\frac{\delta_2\delta_4}{D_1^+D_3^+}\right)\right]\notag\\
			= & \int_{\mathbb{R}^4} \frac{i d^4 q}{(2 \pi)^4}\frac{( 2 \pi i ) ^ { 2 }}{4\omega_1\omega_2} \left[\delta\!\left(E -\omega_1-\omega_2\right) \delta\!\left(q^0-E/2+\omega_2\right)-\delta\!\left(E+\omega_1+\omega_2\right) \delta\!\left(q^0-E/2-\omega_2\right)\right] \notag\\
			= & -2 i \rho(E^2)\left[\theta\left(E-m_1-m_2\right)-\theta\left(-E-m_1-m_2\right)\right] \notag\\
			= & -2 i \rho(s)\,\theta\left(s-s_{+}\right).\notag
		\end{align}
	This result is completely consistent with the discontinuity formula derived in Eq.~\eqref{eq:disc-G1}.
    \end{widetext}

	\section{Complete analytic continuation of the Green's function matrix}
	\label{appx:2PGfunc-ac}

	The ``Cut-2 terms'' in Eq.~\eqref{eq:disc-cgen-gm-cut-1} are given by:
	\begin{align}
		\text{``Cut-2 terms''}=i\sum_{b=1}^{n_c}\theta_b'(s)\sum_{1\leq c\leq a}^{p(c)\leq b}\varrho_c(s),\notag
	\end{align}
	where $\theta_b^{\prime}(s) \equiv \theta_{[s_b', s_{b+1}']}(s)$,
	% $\theta_b^{\prime}(s) \equiv \theta\left(s-s_{b+1}^{\prime}\right) \theta\left(s_b^{\prime}-s\right)$, 
	$s_a^{\prime}$ $(a=1, \cdots, n_c)$ are the pseudo-thresholds arranged in descending order, $p(c)$ denotes the order of the pseudo-threshold of channel $c$, and we set $s_{n_c+1}^{\prime} $ to $-\infty$. 

	We have discussed the analytic continuation of $\cgen_{1 a} \gm(s)$ along Cut-1 in the main text, as shown in Eq.~\eqref{eq:cgen-cgen-gm}. Besides Cut-1, $\cgen_{1 a} \gm(s)$ has another cut, Cut-2, which does not exist on the physical sheet but exists on all other sheets. Thus, one needs to introduce new continuation kernels $\conk_{2 a}$ $(a=1, \cdots, n_c)$, which satisfy the following equations:
	\begin{align}
		&\conk_{2a}\gm(s)=0,\notag\\
		&\conk_{2b}\left[\cgen_{1a}\gm(s)\right]=i\sum_{1\leq c\leq a}^{p(c)\leq b}\varrho_c(s),\notag
	\end{align}
	and the continuation generators $\cgen_{2a}=1-\conk_{2a}$:
	\begin{align}
		&\cgen_{2a}\gm(s)=\gm(s),\label{eq:cgen-gm-cut-2}\\
		&\cgen_{2b}\left[\cgen_{1a}\gm(s)\right]=\gm(s)-i\sum_{1\leq c\leq a}^{p(c)\leq b}\varrho_c(s)+i\sum_{1\leq c\leq a}^{p(c)> b}\varrho_c(s).\notag
	\end{align}
	According to Eq.~\eqref{eq:cgen-gm}, one can obtain:
	\begin{align}
		\cgen_{1a}\left[\cgen_{2b}\gm(s)\right]=~&\cgen_{1a}\gm(s)=\gm(s)+i\sum_{b=1}^a\varrho_b(s)\notag\\
		\neq~&\cgen_{2b}\left[\cgen_{1a}\gm(s)\right].\notag
	\end{align}
	This result indicates that the actions of the continuation generators $\cgen_{1a}$ and $\cgen_{2b}$ on $\gm(s)$ do not commute. 
	Furthermore, the analytic continuation of $\cgen_{2b}\left[\cgen_{1a}\gm(s)\right]$ across Cut-2 can be evaluated to yield:
	\begin{align}
		\cgen_{2c}\left\{\cgen_{2b}\left[\cgen_{1a}\gm(s)\right]\right\}=~&\gm(s)+i\sum_{1\leq d\leq a}^{p(d)\leq\min\{b,c\}}\varrho_d(s)~-\notag\\
		&i\sum_{1\leq d\leq a}^{\min\{b,c\}<p(d)\leq\max\{b,c\}}\varrho_d(s)~+\notag\\
		&i\sum_{1\leq d\leq a}^{p(d)>\max\{b,c\}}\varrho_d(s).\notag
	\end{align}
	From this equation, we can derive the following relations:
	\begin{align}
		&\cgen_{2c}\left\{\cgen_{2b}\left[\cgen_{1a}\gm(s)\right]\right\}= \cgen_{2b}\left\{\cgen_{2c}\left[\cgen_{1a}\gm(s)\right]\right\},\notag\\
		&\cgen_{2b}\left\{\cgen_{2b}\left[\cgen_{1a}\gm(s)\right]\right\}= \cgen_{1a}\gm(s),\notag
	\end{align}
	which imply the equivalence relations $\cgen_{2a}\cgen_{2b}\sim\cgen_{2b}\cgen_{2a}$ and $\cgen_{2a}^2\sim1$.

	To clarify the structural information of the Riemann surface $\mathrm{RS}\{\gm(s)\}$, we define a new set of continuation generators $\cgen_{2a}'~(a=1,\cdots,n_c)$:
	\begin{equation}
		\cgen_{2a}'\equiv\cgen_{2[p(a)-1]}\cgen_{2p(a)},\notag
	\end{equation}
	where we stipulate that $\cgen_{20}=1$. According to Eq.~\eqref{eq:disc-rho}, one can obtain
	\begin{align}
		&\cgen_{2a}'\varrho_a(s)=-\varrho_a(s),\notag\\
		&\cgen_{2a}'\varrho_b(s)=\varrho_b(s)~(a\neq b).
		\label{eq:cgenp-varrho-1-and-2}
	\end{align}
	If we replace $\cgen_{2 a}^{\prime}$ with $\cgen_{1 a}^{\prime}$ from Eq.~\eqref{eq:def-cgenp-1} in the above equations, they still hold. 

	Furthermore, one can define the raising operator $\ppm_a$ and the lowering operator $\ppm_{-a}~(a=1,\cdots,n_c)$:
	\begin{align}
		\ppm_a\equiv\cgen_{1a}'\cgen_{2a}', \quad \ppm_{-a}\equiv\cgen_{2a}'\cgen_{1a}'.\notag
	\end{align}
	Combining Eqs.~(\ref{eq:cgenp-gm},\ref{eq:cgen-gm-cut-2},\ref{eq:cgenp-varrho-1-and-2}), one can obtain
	\begin{align}
		&\ppm_{\pm a}^{k}\gm(s)=\gm(s)\pm k \varrho_a(s),\notag\\
		&\ppm_{\pm a}^{k}\ppm_{\pm b}^{k'}\gm(s)\hspace{-.5mm}=\hspace{-.5mm}\ppm_{\pm b}^{k'}\ppm_{\pm a}^{k}\gm(s)\hspace{-.5mm}=\hspace{-.5mm}\gm(s)\pm k \varrho_a(s)\pm k'\varrho_b(s),\notag
	\end{align}
	where $k,k'\in\mathbb{Z}$. These equations imply that the structure of the Riemann surface $\mathrm{RS}\{\gm(s)\}$ is:
	\begin{align}
		\mathrm{RS}\{\gm(s)\}=~&\mathbb{C}\times\big\{\ppm_{\pm1},\cdots,\ppm_{\pm n_c}\big|\ppm_a\ppm_{-a}\sim1,\notag\\
		&~~\quad\quad\ppm_a\ppm_b\sim\ppm_{b}\ppm_{a}(\text{for any }a,b)\big\}\notag\\
		\cong~&\mathbb{C}\times\mathbb{Z}^{n_c}.\notag
	\end{align} 

	In summary, $\mathrm{RS}\{\gm(s)\}$ consists of countably infinitely many Riemann sheets. The corresponding Green's function on each Riemann sheet is given by:
	\begin{equation}
		\gm^{(\bm{k})}(s)\equiv\gm(s)+i\sum_{a=1}^{n_c}k_a\varrho_a(s),\notag
	\end{equation}
	where $\bm{k}=(k_1,k_2,\cdots,k_{n_c})\in\mathbb{Z}^{n_c}$.



