%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Explanations and comments}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{enumerate}[label=\arabic*)]
	\setlength\itemsep{0.5em}
\item Arena \label{arena}

\begin{itemize}
	\setlength\itemsep{0.25em}
   \item The arena of the \CM\ system is [here] just the {\scshape Euclid}ean plane $\R\times\R\cong\R^2$ with real coordinates $(p,q)$ in the sense of {\scshape Cartesius/Descartes}, for momentum and position.
    \item The arena of the corresponding \QM\ system is a {\scshape Hilbert} space $\H$ over the (algebraic field of) complex numbers $\C$ of [here] countably \emph {infinite} dimension. This means that $\H$ is a linear space of vectors $\psi,\varphi,\eta,\dots$ with a scalar product $\langle\psi|\varphi\rangle$ and norm $\|\psi\|\ceq\langle\psi|\psi\rangle^{1/2}$, where $\langle\psi|\varphi\rangle$ is assumed to be antilinear in the left argument. Moreover, there is a countable set of pairwise orthogonal unit vectors (orthonormal basis $\eqc$ ONB) such that every $\psi\in\H$ can be written as a linear combination of these unit vectors which converges (in norm). Finally, every {\scshape Cauchy} sequence in $\H$ is convergent. To summarize, $\H$ is the reasonable extension to infinite dimension of the $n$-dimensional (complex) ``{\scshape Euclid}ean'' space $\C^n$ with \emph{finite} $n\in\{1,2,3,\dots\}$. Although all {\scshape Hilbert} spaces of the same dimension are isometrically isomorphic, it is convenient throughout this Section 2 to follow {\scshape Schrödinger} \cite{Sc1926a} and to think of $\H=\LL^2(\R)$. This is the linear space of all functions $\psi:\R\rightarrow\C, q\mapsto \psi(q)$ being square-integrable with respect to the {\scshape Lebesgue} measure, that is, $\int_\R \dd q \,\big|\psi(q)\big|^2<\infty$, where two such functions are identified with each other if they take different values only on a set of zero {\scshape Lebesgue} measure. The scalar product of $\LL^2(\R)$ is given by $\langle\psi|\varphi\rangle=\int_{\R}\!\dd q\, \psi(q)^*\varphi(q)$. Nevertheless, it is appropriate to remark that all the structural elements in the right column of the above table, which do not refer to $P$ and $Q$ of a \emph {mechanical} system in the strict sense, retain their significance for other quantum systems with infinite-dimensional or finite-dimensional $\H$. In the latter case, like for (pure) spin systems, one may think of $\H=\C^n$ with a suitable finite $n\in\{1,2,3,\dots\}$.
\end{itemize}

\item Canonical Elements \label{kanonische_variablen}

\begin{itemize}
	\setlength\itemsep{0.25em}

  \item For the \CM\ see Explanation~\ref{arena}.
  \item For the \QM\ (in the {\scshape Schrödinger} realization) the \emph{position operator} $Q$ is defined as the basic \emph{multiplication} operator by $(Q\psi)(q)\ceq q\psi(q)$ for all $\psi\in \dom(Q)\ceq\{\eta\in\LL^2(\R) : \|Q\eta\|<\infty\}$, the \emph{domain} of $Q$. It's obvious that $\langle\varphi|Q\psi\rangle=\langle Q\varphi|\psi\rangle$ for all $\varphi, \psi \in \dom(Q)$ (with the finiteness following from the {\scshape Cauchy--Schwarz} inequality $|\langle\varphi|Q\psi\rangle|\leq\|\varphi\|\|Q\psi\|<\infty$). Since $\dom(Q)$ is dense in $\LL^2(\R)$, it is not hard to show that the (unique) adjoint operator $Q^{*}$ has the same domain. Hence $Q$ is \emph{self-adjoint} on $\dom(Q)$ which is written as $Q^{*}=Q$, see \cite{BEH2008,T2014}.\\ The definition of the \emph{momentum operator} $P$ is somewhat more involved. Informally it is the basic \emph{differential} operator ``$-\ii\hbar\frac{\dd}{\dd q}$'', where  $2\pi \hbar\approx 6.63\times10^{-34}$ {\scshape Joule}-seconds is the fundamental {\scshape Planck} constant. Its precise domain turns out to be 
\[\dom(P)\ceq\big\{\eta\in \LL^2(\R): \eta\; \text{is absolutely continuous with derivative}\ \eta'\in \LL^2(\R)\big\}\,.\]
Here a function $\eta: \R\rightarrow\C, q\mapsto\eta(q)$ is \emph{absolutely continuous}, if its (existing) derivative $\eta'$ satisfies the fundamental theorem of calculus
in the {\scshape Lebesgue} sense
\[\int_{q_1}^{q_2}\dd{q}\eta'(q)=\eta(q_2)-\eta(q_1)\quad\text{for all}\;\; q_1, q_2\in\R\;\;\text{with}\;\; q_1\leq q_2\,.\]   
For $\psi\in\dom(P)$ it can be shown that $\psi(q)\to 0$ as $q\to\pm \infty$\,. 
\end{itemize}
\newpage
\item Scalar Product (for {\scshape Liouville} space) \label{skalarprodukt}

\begin{itemize}

\item
In the \CM\ case, $\langle  a,b \rangle$ is a (positive definite) scalar product in the strict sense only for $a, b\in \LL^2(\R\times\R)$. For other functions on $\R\times\R$  it is merely a convenient notation for the underlying integral if it exists. Simple example: $\langle |a|,1 \rangle <\infty$ and $|b(p,q)|\leq \gamma$ for {\scshape Lebesgue}-almost all $(p,q)\in \R\times\R$ with some constant $\gamma < \infty$.
\item 
Similar remarks apply to the \QM\ case. Here  $\tr(A^*B)$ makes sense as a scalar pro\-duct if $A$ and $B$ are {\scshape Hilbert--Schmidt} operators. But the \emph{trace} also exists, for example, if $A$ is even of \emph{trace class}, $\tr(A^*A)^{1/2}<\infty$, and $B$ is \emph{bounded} in the sense that (at least) its uniform norm $\|B\|\ceq \sup\{\|B\eta\| : \eta\in \H\,, \|\eta\|=1\}$ is finite.
\end{itemize}

\item {\scshape Lie} Product \label{lie-produkt}

\begin{itemize}
		\setlength\itemsep{0.25em}
	\item is, by definition, bilinear, anticommutative, and obeys the {\scshape Jacobi}  identity  
	\[ \big[A,[B,C]\big]+\big[B,[C,A]\big]+\big[C,[A,B]\big]=\mathbb{0}\,.\]
	\item is, in addition, compatible with the ``ordinary'' product by the {\scshape Leibniz} rule
\[ [AB,C]=A[B,C]+[A,C]B\,.\]

\end{itemize}
[similar in the \CM]

\item Canonical Relation\label{cr}

	\begin{itemize}
	\setlength\itemsep{0.25em}
	\item is obvious in the \CM.
	\item is in the \QM\ known as the {\scshape Heisenberg}--{\scshape Born}--{\scshape 	Jordan} \emph{commutation relation}. It follows \emph{informally} by ignoring domain 	questions and using the product rule of calculus. One rigorous approach is via 			the ``unitary form'' of the relation \cite{Wey1927}.
	\end{itemize}

\item Observables \label{observablen}

	\begin{itemize}
	\setlength\itemsep{0.25em}
	\item include the ``observable'' or measurable quantities in the sense of (experimental) physics. But is there an operational instruction to measure, for example, $PQ^2P=QP^2Q$ in the laboratory? I don't know.
	\item may be interpreted in the \CM\ directly as real-valued \emph{random variables} in the sense of the \emph{classical probability theory} ($\eqc$ \CPT) \cite{Bau1996}.
	\item manifest themselves in the \QM\ \emph{physically} in that only the (real) \emph{spectral values} of the self-adjoint operator are postulated as possible outcomes of measurements in the laboratory and thereby become (\emph{quantum}) random variables, but in a more fundamental and intrinsic sense than in the \CM. I will try to explain this in the following.
	\end{itemize}

\item Events \label{ereignisse}

	\begin{itemize}
	\setlength\itemsep{0.25em}
	\item are \{0,1\}-(spectral) valued (or {\scshape Bernoulli}) observables. They correspond to simple \textsf{no-yes}-alternatives and form a \emph{lattice} (or algebra endowed with a complementation operation), classically even a {\scshape Boole}an one. See Section~4.
	\item are often induced by an observable and {\scshape Borel} sets $I \subseteq \R$ in the following sense:

\medskip
\begin{tabular}{llcl}
&${\cal E}=\chi_{a^{-1}(I)}$&$=$&indicator function of the pre-image of $I$ under $a$\\
resp.&$E=\chi_I(A)$&$=$&spectral projection of $A$ corresponding to $I$\,.
\end{tabular}

\medskip
These are interpreted as follows:

\begin{enumerate}[label=\roman*)]
\item Mathematically: 
%
``$a$ resp. $A$ has a (spectral) value in $I$ or not ( \textsf{yes} or \textsf{no}).''
\item Physically:
%
``{}An ideal single measurement of $a$ resp. $A$ in the laboratory gives a result in $I$ or not.''{}
\end{enumerate}

\item  may be combined to a \emph{joint} event, if there are two of them, by the well-known formula  $\chi_{{\cal E} \cap {\cal F}}=\chi_{\cal E}\chi_{\cal F}$ in the \CM\ and \CPT. It generalizes in the \QM\ to $E\wedge F\ceq\lim_{n\to\infty} E(FE)^n$, because in general $EF\neq FE$, see Section 4.
Example:  For $E=\chi_I(P)$ and $F=\chi_J(Q)$ on $\H=\LL^2(\R)$ with non-empty and bounded  $I,J\subset \R$ one finds the \emph{impossible} event $E\wedge F=\mathbb{0}$ (equivalently $E\H \cap F\H =\{0\}$), as a consequence of the ``delocalization property'' of the {\scshape Fourier--Plancherel} transformation, see Sections~2.3 and 4 as well as pp.104--109 in \cite{BGL1995}. In other words, the two events are \emph{disjoint} (or \emph{mutually exclusive}).
\item have a natural generalization to observables taking (spectral) values in the unit interval  ${[0,1]}$. They are only of interest in the \QM, where they obey the operator inequali\-ties $\mathbb{0}\leq E \leq \uu$. Therefore they are a kind of fuzzy or unsharp events, sometimes called \emph{effects}. More importantly, they are basic for the effect-valued or, less precise,  \emph{positive-operator-valued} (POV) measures on $\R$ and the related \emph{unsharp} observables \cite{BGL1995,BZ2006,Au2007,NC2010,BLPY2016,Hay2017}. These are of interest in modern measurement theory and quantum information theory, but they are not considered in this text.    
\end{itemize}

\item States \label{zustaende}

\begin{itemize}
	\setlength\itemsep{0.25em}
\item The term \emph{state} includes the one needed for \emph{statistical} mechanics and for a \emph{composite} system (in general), when restricting/reducing its state to one of its subsystems, see Section 3.
A \QM\ state is a positive operator of trace class and therefore only has a discrete spectrum.

Example: {\scshape Boltzmann}--{\scshape Gibbs} state
 \[ W = \frac{\textrm{e}^{-\beta H}}{\tr \textrm{e}^{-\beta H}}\]
of a \QM\ system with {\scshape Hamilton}ian $H$ (= energy observable) in thermodynamic equlibrium at absolute temperature  $1/(\beta k_B) > 0$\,, where the {\scshape Boltzmann} constant $k_B>0$ fixes the {\scshape Kelvin} scale and $H$ only has a discrete spectrum such that the trace in the denominator, the canonical \emph{partition function}, is finite. Example:  $\H=\LL^2(\R)$ and $H=P^2/(2m)+\gamma\,Q^2$ with $\gamma >0$, defining the quantal \emph{harmonic oscillator}.
\smallskip
\item \emph{Pure} \QM\ states are one-dimensional projections:
\[W =|\psi_0\rangle\langle\psi_0| \ceq \text{projection on the span of}\; \psi_0 \in \H\,\,\text{with}\,\, \langle\psi_0|\psi_0\rangle=1\] \[\psi_0 = \text{\emph{state vector}}= \text{ ``{}normalized wave function''{}}\,.\] 
Whereas a \emph{classical} pure state is fully determined by only two real numbers $(p_0,q_0)$, a \emph{quantal} pure state needs an infinite sequence of complex numbers for its characterization (given an ONB in $\H=\LL^2(\R)$).

\item \emph{Mixed} (or \emph{impure}) \QM\ states are non-trivial convex combinations of pure ones according to their \emph{spectral resolution} (or \emph{decomposition})
\[ W = \sum_n \rho_n  \,|\psi_n\rangle\langle\psi_n| \]	
\[\rho_n \geq 0,\quad \sum_n \rho_n = 1,\quad \psi_n\in\H,\quad\langle\psi_n| \psi_m\rangle = \delta_{n,m}\,, \quad \sum_n |\psi_n\rangle\langle\psi_n| = \uu\,.\]
\end{itemize}
\newpage
\item Entropy of a State (following {\scshape Boltzmann}, {\scshape Gibbs}, {\scshape von Neumann}, and {\scshape Shannon} ) \label{entropie}

\begin{itemize}
	\setlength\itemsep{0.25em}

\item It may be understood purely information-theoretically in the sense of {\scshape C.E. Shannon} and quantifies, how much \emph{information} the state lacks from the maximum possible one, that is, how impure it is. Only for pure states the entropy is minimal. The larger it is, the more coarse-grained is the information encoded in the state.

\item In the \CM\ there exists, in principle, only subjective ignorance (or ``uncertainty''), whereas in the \QM\ there may be additional objective \emph{indeterminacy}, even for pure states.\footnote{For a \QM\ state its spectral resolution yields for the entropy \[- \langle W,\ln W \rangle=-\tr W\ln W =-\sum_n \rho_n\ln \rho_n \qquad (\textrm{with the agreement}\quad 0\ln 0\ceq0).\]} See Explanation~\ref{varianz}.

\item The entropy of the {\scshape Boltzmann}--{\scshape Gibbs} state of Explanation~\ref{zustaende} equals the \emph{thermal} entropy (in the case of a single particle), when multiplied by $k_B$.

\item Range of the entropy:
\begin{align*}
\text{\CM: } &&- \infty &\leq - \langle w,\ln w\rangle \leq  \ln \Big( \int_\Gamma \frac{\dd p\, \dd q}{2 \pi \hbar} \Big)\quad
\big[=\infty\quad \text{for\,\, $\Gamma=\R\times\R$\big]}\\[0.5em]
\text{\QM: } && 0 &\leq - \ln \langle W,W\rangle\leq -\langle W, \ln W\rangle\\&&&\leq \ln\big(\dim \H \big)\quad\big[= \infty\quad\text{for\,\, $\H= \LL^2(\R)\big]$}
\end{align*}
[The lower bound in the \QM\ case is the second-order quantum {\scshape R\'enyi} entropy.]
\end{itemize} 

\item Eigenstate of an Observable

\begin{enumerate}[label = \roman*)]
	\setlength\itemsep{0.25em}
\item  For the \CM\ one has:
\begin{itemize}

\item An eigenstate is concentrated on the level line corresponding to one of the possible values the function $a$ can take. Therefore one has $aw = \alpha w$ similarly to the \QM.
\item Common eigenstates of two observables exist, only if these have level lines which cross each other.
\item Every pure state is a common eigenstate of \emph{all} observables (if defined on the
whole phase space).

\end{itemize}
\item  For the \QM\ one has: 
\begin{itemize}

\item The operator $A$ has eigenstates, only if $A$ has \emph{eigenvectors} $\psi\in\H$. Upon normalization they determine the pure eigenstates of $A$ according to: $W=|\psi\rangle\langle\psi|$, $\langle\psi|\psi\rangle=1$, $A\psi=\alpha\psi$\,.

\item Mixed eigenstates of $A$ exist, only if the multiplicity of the corresponding eigenvalue is at least $2$; namely as an arbitrary convex combination of pure eigenstates of this eigenvalue.

\item Common eigenstates of two observables exist in general only if these \emph{commute}.

\end{itemize}
\end{enumerate}

\item Expectation Value (mean or average value) of an Observable in a State\label{erwartungswert} 

\begin{itemize} 
	\setlength\itemsep{0.25em}

\item is an additive, homogeneous, positive, and normalized functional on the star-algebra of (bounded) operators [resp. functions in the \CM\ and \CPT]:

\[\langle A + B\rangle=\langle A\rangle + \langle B\rangle\,, \qquad \langle\lambda A\rangle=\lambda\langle A\rangle\,,\qquad\,\lambda\in\R\,,\]
\[\langle A^* A\rangle\geq 0\,,\qquad \langle \uu\rangle=1\,.\]

\item is in the \CM\ case, $ \langle  a \rangle = \langle w,a\rangle$, independent of the {\scshape Planck} constant $2\pi \hbar$ by the normalization $\langle w, 1 \rangle  = 1$ (unless $a$ depends on it). 

\item is a ``weighted mean'' of the (spectral) values of an observable in repeated
measurements. The probability for the occurrence of a particular outcome equals the expectation value of the corresponding event, see the Explanations~\ref{observablen}, \ref{ereignisse}, \ref{verteilung}, and \ref{wsk}.

\item may be written in two simple alternative forms
\[\boxedeqn{\braket{A} = \tr(WA) =\sum_n \rho_n\,\langle\psi_n| A\, \psi_n\rangle  =   \sum_j \alpha_j \tr(WE_j)\,,}\]
if the \QM\ observable $A$, like $W$, has a purely \emph{discrete} spectral resolution
according to $A = \sum_j \alpha_j E_j $ with $\alpha_j \in \R$, $\alpha_i \neq \alpha_j$ if $i \neq j$, $E_i^* E_j = \delta_{ij} E_j$, and $\sum_j E_j = \uu$, where the trace $\tr E_j$ is the dimension of the $j$-th eigenspace, that is, the multiplicity of the eigenvalue $\alpha_j$. Each of the two forms has an obvious probabilistic interpretation.
\end{itemize}

\item \emph{Probability distribution} \label{verteilung} of an observable in a state

If the spectrum, $\spec A \subseteq\R$, of $A=A^*$ also, or even only, has a continuous part, such as the position operator $Q$, then the last sum has to be replaced by the integral $\int_\R\mu_A(\textrm{d}\alpha)\,\alpha$\,. Here the {\scshape Borel} probability measure $\mu_A$ on the real line $\R$ is defined by
\[\mu_A(I)\ceq \braket{\chi_I(A)}=\tr\big(W\chi_I(A)\big)\,,\quad I\subseteq\R\,.\]
According to {\scshape Born} and {\scshape von Neumann} it is the probability \emph{distribution} of $A$ in the state $W$, in close analogy to the \CM\ and \CPT. 
(See the Explanations~\ref{observablen}, \ref{ereignisse}, and \ref{wsk})

\item \emph{Variance} \label{varianz} of an observable in a state

is the mean-square deviation from, or quadratic \emph{fluctuation} around, the mean of an observable (in repeated measurements). It is the most often used quantification for the ``width'' of the density of its probability distribution:

\[\boxedeqn{\sigma_A^2 \ceq \big\langle\big( A- \langle A\rangle\uu\big)^2\big\rangle} = \langle A^2\rangle -\langle A\rangle^2= \int_\R\mu_A(\textrm{d}\alpha)\,\big(\alpha-\langle A\rangle\big)^2\,.\]
\paragraph{Facts:}
\parbox[t]{0.85\textwidth}{\begin{enumerate}[label = \roman*)]
	\setlength\itemsep{0.5em}
\item $\sigma_{\lambda A}^2=\lambda^2\sigma_A^2\,,\qquad\sigma^2_{A+\lambda\uu}=\sigma^2_A\,,\quad \lambda\in\R\,.$
\item \boxedtext{$\sigma_A^2 \geq 0$} \label{var1}    
\item \boxedtext{$\sigma_A^2 = 0 \; \Longleftrightarrow\;\mu_A\;$ is a {\scshape Dirac} measure $\;\Longleftrightarrow\; W$ is an eigenstate of $A$}\label{var2}
\end{enumerate}}

\medskip
[similar in the \CM\ and \CPT;\, \CM\ observables as random variables]

\begin{proof}
\begin{enumerate}[label = \roman*)]
	\setlength\itemsep{0.5em}
\item obvious by definition.
\item by the operator inequality $\big( A - \langle A\rangle\uu \big)^2\geq \mathbb{0} $\,.
\item The first equivalence is standard by the {\scshape Chebyshev} inequality \cite{Bau1996}.\\ The equivalence\newline ``$\sigma_A^2=0\;\Longleftrightarrow\; W$ is an eigenstate of $A$''\; can be shown as follows:
\medskip
\begin{enumerate}
\item[``{}$\Leftarrow$''{}:] The assumption $AW = \alpha W$ with  $\alpha \in \R$ implies $A^2\,W = \alpha^2\,W$\;. The claim follows by taking traces.
\item[``{}$\Rightarrow$''{}:] For $C\ceq\big(A - \langle A\rangle\uu\big)W^{1/2}\quad$ one has $\quad C^*C = W^{1/2} \big(A - \langle A\rangle\uu \big)^2 W^{1/2}$ 
\newline and therefore $\tr C^*C=\sigma_A^2$. The assumption\, $\sigma_A^2 = 0$\, hence implies

$C=\mathbb{0} \quad \Rightarrow \quad \big(A- \langle A\rangle\uu \big) W = \mathbb{0} \quad \Rightarrow \quad AW = \alpha W\quad\text{with}\quad\alpha \ceq \langle A\rangle.$\qed
\end{enumerate}
\end{enumerate}

\end{proof}

Conclusions of iii) with additions:
\smallskip
\begin{itemize}
	\setlength\itemsep{0.25em}

\item Only if the system of the \CM\  resp. \QM\ is (prepared) in an eigenstate of an observable, then its renewed measurement will definitely give the same outcome, that is, with probability $1$ (\emph{absence of fluctuations} in the sense of $\sigma_a^2= 0$ resp. $\sigma_A^2= 0$).

\item For an individual \QM\ system (with $\dim \H \geq 2$) it is at most acceptable in eigenstates of $A$ to imagine that the system ``possesses'' an eigenvalue of $A$ as an intrinsic \emph{property}. In all other states the ``value'' of $A$ is \emph{objectively indeterminate}, because the outcomes of repeated measurements at the same, always equally prepared, \QM\ system objectively fluctuate with a statistics obeying  $\sigma_A^2> 0$\,, see Explanation \ref{wsk}.

\item For any \QM\ system (with $\dim \H \geq 2$) there exists no state, not even a pure one, being an eigenstate of \emph{all} observables.\footnote{If $\dim \H = \infty$, there exist operators with continuous spectrum like the position operator $Q$. To include such cases this statement reads more precisely: There is no \emph{sequence} $(W_n)$ of states such that $\lim_{n \rightarrow \infty}  \sigma_{A}^2( W_n) = 0$ for all $A = A^*$. See Explanations~\ref{verteilung}, \ref{uu}, and \ref{wsk}.} Example: For an orthonormal pair $\psi, \varphi\in\H$ is $W\ceq|\psi\rangle\langle\psi|$ an eigenstate of 
$|\varphi\rangle\langle\varphi|\,,$ but not of $A\ceq |\eta\rangle\langle\eta|$ with the
``superposition'' $\eta\ceq (\varphi+\psi)/\sqrt{2}$\,, since $\sigma_A^2=1/4\,.$
[Non-existence of \emph{universally fluctuation-free states}, see Explanation~\ref{uu}]

\item If the \QM\ system is in a general state $W$, the outcome value of an ideal  measurement of a (discrete) observable $A$, only \emph{arises} in the moment of measurement, namely \emph{by chance} with the probability $\langle W, E\rangle$. Here $E$ is the eigenprojection of $A$ corresponding to the outcome. According to a rule of {\scshape Lüders} \cite{Lü1951}, $W$ then changes to the state $W_E\ceq EWE/\langle W, E\rangle$. Such a non-linear and non-invertible change of state is called a \emph{state collapse}. It is usually undisputed that it occurs in the experimental praxis, at least approximately and, in fact, regardless of the level of knowledge of the persons involved. However, whether it can be explained in a purely quantum-theoretical way is still controversial today, despite the ideas of {\scshape Zeh} \cite{Zeh1970} and subsequent authors to understand it as a consequence of the \emph{entanglement}\footnote{see Section~3.} with the noisy environment (from the measuring apparatus etc.) and the resulting irreversible ``loss of coherence'' in the macroscopic limit. See also Section~5.
Apart from this, the state  $W_E$ is (for $\dim\H\geq 3$) the only(!) one which provides for the occurrence of any event $F$ with $F=FE$ ($\Leftrightarrow F\H\subseteq E\H$) in a subsequent measurement the (conditional) probability $\langle W_E,F\rangle$, in particular\footnote{confer the above \emph{absence of fluctuations} and the Explanations~\ref{verteilung} and \ref{wsk}.} $\langle W_E, E\rangle =1$. This claim is shown in \cite{BC1981,Hug1989} to be a consequence of {\scshape Gleason}'s theorem\footnote{see Section~4.}. 
\end{itemize}

\item \emph{Covariance} of two observables in a state\label{kovarianz}

 quantifies the correlation of their (symmetrized) fluctuations
\begin{eqnarray*}
&\boxedeqn{c_{A,B} \ceq \frac{1}{2} \Big\langle\big(A-\langle A\rangle\uu\big)\big( B-\langle B\rangle\uu \big)+\big(B-\langle B\rangle\uu\big)\big(A-\langle A\rangle\uu\big)\Big\rangle} \\&\displaystyle= \frac{1}{2} \langle AB + BA\rangle - \langle A\rangle \langle B\rangle\,.
\end{eqnarray*}  
Correlations play a major role in all of science and technology. But in quantum physics they are of fundamental importance. See, for example, Section 6.

\paragraph{Facts:}
\parbox[t]{0.85\textwidth}{
\begin{enumerate}[label=\roman*)]
	\setlength\itemsep{0.5em}
\item $\displaystyle c_{A,A}=\sigma_A^2\,,\quad\, c_{A,B}=c_{B,A}\,,\quad\, c_{\lambda A,B}=\lambda\, c_{A,B}\,,\quad\, c_{A+\lambda\uu,B}=c_{A,B}\;;\quad \lambda\in\R$.
\label{var}
\item \boxedtext{$\displaystyle\sigma_A^2 + \sigma_B^2 = \sigma_{A+B}^2 - 2 c_{A,B}$} \label{add}
\end{enumerate}}
\paragraph{\phantom{Facts:}}
\parbox[t]{0.85\textwidth}{
\begin{enumerate}[label=\roman*)]
\setcounter{enumii}{2}
	\setlength\itemsep{0.5em}
\item \boxedtext{$\displaystyle\sigma_A^2 \sigma_B^2 \geq  c_{A, B}^2 + \frac{\hbar^2}{4} \braket{[A, B]}^2$} \,\,\emph{Indeterminacy inequality} ($\eqc$\,\ini)
\label{ur}
\end{enumerate}}

\medskip
[similar in the \CM\ and \CPT, but without the commutator term]

\begin{proof}%\allowdisplaybreaks
 \ref{var} obvious by definition.
   %\begin{enumerate}[label=\alph*)]
 For \ref{add} and \ref{ur} consider at first the case $\langle A\rangle = 0$ and $\langle B \rangle = 0$. The expectation value of $A^2 + B^2 = (A+B)^2 - AB - BA$ then gives \ref{add}\,. And the {\scshape Cauchy}--{\scshape Schwarz} inequalitiy for the (positive semi-definite) scalar product $(X,Y)\mapsto\langle X^* Y\rangle=\tr(WX^*Y)$ then yields \ref{ur} according to
       \begin{align*}
        \langle A^2\rangle \langle B^2\rangle &\geq \big| \langle AB\rangle\big|^2 
	= \big(\re \langle AB\rangle \big)^2 + \big( \im \langle AB\rangle\big)^2\\
        &= \Big\langle\frac{1}{2} \big(AB+BA\big)\Big\rangle^2 + \Big\langle\frac{1}{2 \ii} 
        \big(AB-BA\big)\Big\rangle^2 =\; c_{A,B}^2 + \frac{\hbar^2}{4} \big\langle[A,B]\big\rangle^2.
       \end{align*}
If $\langle A\rangle \neq 0$ and/or $\langle B\rangle \neq 0$, then replace $A$ with $A- \langle A\rangle\uu$ and/or $B$ with $B- \langle B\rangle\uu$, which does not change the commutator.
\qed
%\end{enumerate}
\end{proof}

\item Explanations and comments on the indeterminacy inequality (\ini)\label{uu}

\begin{itemize}
	\setlength\itemsep{0.25em}

\item The \ini\ refers to the statistics of outcomes of measurements and is, in this general form, due to {\scshape Robertson} \cite{Rob1929} and {\scshape Schrödinger} \cite{Sc1930,Sc2008}. It has nothing to do with possible perturbations of the \QM\ system or with imperfections of single measurements. Instead it tells the physicists that the structure of the \QM\ does not allow for states violating it. In other words: violations of the \ini\ are not observable within the {\scshape Hilbert}-space quantum formalism. Let's recall {\scshape Einstein}: ``Erst die Theorie entscheidet darüber, was man beobachten kann.''\footnote{In a conversation with {\scshape Heisenberg} in April 1926, quoted after the latter's autobiography \cite{Hei1969}. In English: ``It is the theory which decides what we can observe'', see p. 63 in \cite{Hei1971} and also \cite{Hol2000,Kl2019}. One should note that {\scshape Einstein} used the term ``theory'' in the hypothetico-deductive sense \cite{E1919}. Thereby he anticipated {\scshape K. Popper}'s main idea on the progress of natural science (``trial and error'').}

\item For $\big\langle[A,B]\big\rangle= 0$ the \ini\ reduces to a standard inequality in the \CPT\ and \CM.

\item The \ini\ is often weakened by omitting $c_{A,B}^2$\,, by which one (carelessly) also loses the classical inequality.

\item Its best known example on $\H=\LL^2(\R)$ dates back to {\scshape Heisenberg} \cite{Hei1927} as an approximate measurement-uncertainty equality and as a precise variance \ini\ to {\scshape Kennard} \cite{Ke1927} barely four months later:
\[\sigma_P^2 \sigma_Q^2 \geq c_{P,Q}^2 + \frac{\hbar^2}{4} \geq \frac{\hbar^2}{4} \quad (\text{\emph{independent} of the state}\,\, W).\]
It implies that there exists \emph{no} state with $\sigma_P^2 \sigma_Q^2 < \hbar^2/4$, although the momentum variance $\sigma_P^2>0$ and the position variance $\sigma_Q^2>0$  may be \emph{individually} arbitrarily small (for states with a small enough width of their probability density in momentum resp. position space). For rigorous {\scshape Heisenberg}-type error-disturbance relations see \cite{BLW2014} and also \cite{WF2019}.

\item In the above indeterminacy inequality for $P$ and $Q$ equality holds, for example, for the pure state 
$|\psi\rangle\langle\psi|$ defined by the complex-valued square-integrable function

\[\psi(q)\ceq (2\pi \alpha^2)^{-1/4}\textrm{e}^{-q^2/(4\alpha^2)}\textrm{e}^{\ii\gamma q^2/\hbar}\quad\quad\quad (q,\gamma \in\R,\;\alpha^2>0\,)\,.\]

This state has the covariance  $c_{P,Q}=2\gamma \alpha^2$ and a positive {\scshape Wigner} density, see Remark iv) in Section 2.5 \,.

\item The analytical power of the ({\scshape Heisenberg}--){\scshape Kennard} inequality must not be overestimated. For example, lower bounds on the ground-state energy of a standard {\scshape Hamilton}ian are better derived by {\scshape Sobolev} inequalities and related ones \cite{Fa1978}.
\end{itemize}

\item \emph{Correlation coefficient} \label{korr} (as ``de-dimensionalized'' covariance)

\[\boxedeqn{ \kappa_{A,B} \ceq \frac{c_{A,B}}{\sigma_A \sigma_B}}\qquad (\text{if}\quad\sigma_A \sigma_B > 0)\,.\]

with the `` standard deviations'': $\quad \sigma_A \ceq \sqrt{\sigma_A^2} \geq 0$ \quad and \quad $\sigma_B\ceq\sqrt{\sigma_B^2}\geq 0$\,.

\paragraph{Facts:}
\parbox[t]{0.85\textwidth}{
\begin{enumerate}[label = \roman*), ref=\roman*)]
		\setlength\itemsep{0.5em}
\item\label{kor_def_i} Symmetry: $\quad\kappa_{A,B} = \kappa_{B,A}$

\item\label{kor_def_ii} Invariance under rescaling and translation:

$A\mapsto \lambda A\,,\quad\lambda>0\,; \quad A\mapsto A+\xi\uu,\quad\xi\in\R$\,;\quad
similar for $B$

\item\label{kor_def_iii} Indeterminacy inequality: $\quad\displaystyle\kappa_{A,B}^2 \leq 1- \frac{\hbar^2}{4}\big\langle[A/\sigma_A,B/\sigma_B]\big\rangle^2 \leq 1$

\item \label{kor_def_iv} States for the two extreme values:

\boxedtext{$\kappa_{A,B} = \pm 1 \quad \Longleftrightarrow \quad$\parbox[t]{0.55\textwidth}{There exists $\lambda > 0$, such that $W$ is an eigenstate of $A \mp \lambda B$}}\\

Interpretation of \ref{kor_def_iv}: 

In the state $W$ the observables $A$ and $B$ are \emph{perfectly} $\begin{cases}\text{correlated.}\\\text{anticorrelated.}\end{cases}$ 

In this state one obviously has by iii): \; $\big\langle[A,B]\big\rangle = 0\,.$
\end{enumerate} }

\medskip
[similar in the \CM\ and \CPT\, but without the commutator term]

\begin{proof} 
\ref{kor_def_i} and \ref{kor_def_ii} are obvious by definition.\\ 
\ref{kor_def_iii} is only a reformulation of the \ini\ from Explanation \ref{kovarianz}. \\ 
It remains to show \ref{kor_def_iv}. This can be done ``quite classically'' as follows:

 ``$\Leftarrow$'':\, 
\begin{minipage}[t]{0.885\textwidth} Fact~\ref{var2} for the variance, Facts ~\ref{kor_def_i} and \ref{kor_def_ii} for the covariance, and the inequality of the arithmetic and geometric means yield
%\begin{align*}
\[0 = \sigma_{A \mp \lambda B}^2 = \sigma_A^2 + \lambda^2 \sigma_B^2 \mp 2 \lambda c_{A,B} \geq 2 \sqrt{\sigma_A^2 \lambda^2 \sigma_B^2} \mp 2 \lambda c_{A,B} = 2\lambda \left( \sigma_A \sigma_B  \mp c_{A,B} \right),\]
%\end{align*}
hence $\sigma_A \sigma_B \leq \pm c_{A,B}$. On the other hand, iii) obviously implies $|c_{A,B}|\leq \sigma_A \sigma_B\,.$ Thus $c_{A,B} = \pm  \sigma_A \sigma_B,\, \text{hence}\,\, \kappa_{A,B} = \pm  1\,.$
\end{minipage}

\medskip
``$\Rightarrow$'':\,
\begin{minipage}[t]{0.885\textwidth} With $\displaystyle \lambda \ceq \sigma_A/\sigma_B >0$ one has
   \[ 0 = \left(\sigma_A - \lambda \sigma_B\right)^2 = \sigma_A^2 + \lambda^2  \sigma_B^2 - 2 \lambda \sigma_A \sigma_B = \sigma_{A \mp \lambda B}^2\;.\]
Here the last equality is a consequence of $\sigma_A \sigma_B =\pm c_{A,B}$ (due to the assumption $\kappa_{A,B} = \pm 1$) in combination with the Facts~\ref{kor_def_i} and \ref{kor_def_ii} for the covariance. Fact~\ref{var2} for the variance now shows that the underlying state $W$ is an eigenstate of $A \mp \lambda B$ (with eigenvalue $\braket{A \mp \lambda B}$).
\qed
\end{minipage}
\end{proof}

%\newpage
\item  Probability for the Occurrence of an Event in a State \label{wsk}

\begin{itemize}
	\setlength\itemsep{0.25em}
\item Each state induces a \emph{probability measure} on the lattice/algebra of events. In the case of \CM\ this leads to a {\scshape Kolmogorov} probability space in the sense of \CPT. This is not  true in the case of \QM, because the corresponding lattice is not of {\scshape Boole}an type, which in turn is the reason for the \QM\ particularities like interference, violations of {\scshape Bell}-type inequalities, and the like, see Explanation~\ref{ereignisse} and Sections~4 and 6.

\item Typical \QM\ example (see Explanations~\ref{ereignisse} and \ref{verteilung}): 

Let $E= \chi_I(Q)$ be the spectral projection of the position operator $Q$ corresponding to the {\scshape Borel} set $I \subseteq \R$.
%
Then the probability of finding the particle in $I$ may be written as: 
\[ \big\langle E \big\rangle = \tr\big(W \chi_I(Q)\big) = \int_I \dd q \,\langle q| W |q\rangle\,.\]
Here $\langle q|W|q'\rangle$, with $q, q' \in \R$, denotes the 
\emph{integral kernel} or the ``position representation'' of $W$.
Therefore the ``diagonal'' $\langle q| W|q\rangle\geq 0$ as a function of $q\in \R$ is a probability density of the measure $\mu_Q$ in the sense of $\mu_Q(dq)=dq\langle q|W|q\rangle$. Especially for a pure $W=|\psi\rangle\langle\psi|$ with $\psi\in \LL^2(\R)$ and $\langle\psi|\psi\rangle = 1$ one gets the ``usual'' absolute square of {\scshape Schrödinger}'s wave function:  $\langle q|W|q\rangle = |\psi(q)|^2$.
\medskip
\item Interpretation of \emph{all} probabilities as \emph{predictions of relative frequencies} in frequently repeated measurements at a single (always equally prepared) system or in a simultaneous measurement at a (thought of) large number of dynamically independent equal copies of the system (= \emph{statistical ensemble}).
\end{itemize}

\item Time-Evolution of a State \label{zeitentwicklung}

\begin{itemize}
	\setlength\itemsep{0.25em}

\item is purely deterministic (for a \emph{closed} or isolated system as considered here) and is generated by the time-independent energy observable called {\scshape Hamilton}ian (= {\scshape Hamilton} function $h$ resp. {\scshape Hamilton} operator $H$) according to a canonical resp. unitary transformation and enables (in principle) the prediction of a future
expectation value for times $t>0$ given the present one (at $t=0$), for example, the position of a particle in \emph{motion}.

\item does not change the entropy, in particular pure resp. mixed states remain pure resp. mixed.

\item is equivalent to the well-known differential equations of {\scshape Hamilton} resp. {\scshape Schrö\-ding\-er} (for pure states).

\item can be ``transferred'' from the state to the observables according to the transformation
\[a_t\ceq\text{e}^{t[h,\boldsymbol{\cdot}]}\,a \quad\quad\text{resp.}\quad\quad A_t\ceq\text{e}^{\ii tH/\hbar}\,A\,\text{e}^{-\ii tH/\hbar}\,.\]
The time-dependence of expectation values therefore takes two alternative forms
\[\langle a\rangle_t\ceq\langle w_t, a\rangle=\langle w_0, a_t\rangle\quad\quad\text{resp.}\quad\quad\langle A\rangle_t\ceq\langle W_t, A\rangle=\langle W_0, A_t\rangle\,, \]
what is called the ``transition from the {\scshape Schrödinger} to the {\scshape Heisenberg} picture‘‘. Only in the latter picture one can define and study multi-time correlation functions like $c_{a_t, b_{t'}}$ resp. $c_{A_t, B_{t'}}$ for $t\not=t'$\;.
\medskip
\item is for a \emph{free} particle, classical and quantal, particularly simple in the \newline {\scshape Heisenberg} picture, because \;$H=P^2/(2m)$\; generates the equations of motion
\[ P_t=P\quad\quad\text{and}\quad\quad Q_t=Q+\frac{t}{m}P\,.\]
For example, they give for the time-dependencies of the position variance and the momentum-position covariance for an arbitrary initial state $W_0$ with $\langle P^2\rangle <\infty$ and $\langle Q^2\rangle <\infty$ the equations:

\[\sigma^2_{Q_t}-\sigma^2_Q=\frac{2t}{m}c_{P,Q}+\frac{t^2}{m^2}\sigma^2_P\quad\quad\text{and}\quad\quad c_{P_t,Q_t}= c_{P,Q}+ \frac{t}{m}\sigma^2_P\,.\]

They are contained already in \cite{Sc1930,Sc2008}, although {\scshape Schrödinger} did not write down the second one, but see also \cite{Le1986}. In the case $c_{P,Q}<0$, that is, for anticorrelated  $P$ and $Q$ in the initial state, as in the example of Explanation~\ref{uu} for $\gamma<0$, their right-hand sides remain negative only for short enough (positive) times; more precisely for $t\in {]0, 2t_c[}$\; resp.\; $t\in [{0, t_c}[$ with $t_c\ceq m|c_{P,Q}|/ \sigma^2_P\leq m\sigma_Q/ \sigma_P$. 
These time-dependencies also hold classically for an initial state $w_0$ with $ \sigma_p \sigma_q \in ]{0,\infty}[ $. They can visualize the quantal time-dependencies by a swarm of dynamically independent classical particles.

\end{itemize}
\medskip
\emph{Time-independent} or \emph{stationary} states (in the {\scshape Schrödinger} picture)
\begin{itemize}
\item are characterized by a vanishing {\scshape Lie} product with the {\scshape Hamilton}ian: 
\[[w_0, h] = 0 \quad\quad\text{resp.}\quad\quad  [W_0, H] = \mathbb{0}\,.\]
Example: {\scshape Boltzmann--Gibbs} state from Explanation~\ref{zustaende}
\item include in the \QM\ all energy eigenstates, but not so in the \CM.
\item are in the \CM\ mixed for cases of physical interest.
\end{itemize}

\medskip
\item Invariance Group \label{invarianzgruppe}

Leaves expectation values \emph{numerically invariant}, but {\scshape Lie} products and equations of motion ($\ceq$ differential equations for the time-evolution of states, observables, and expectation values) are in general only \emph{forminvariant}.

\end{enumerate}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Entropic indeterminacy inequality for momentum and position}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

This subsection is a kind of addendum to Explanation \ref{uu} in Section 2.2.
The variance of a probability density provides just one way to quantifiy its width.
Another quantifier is its entropy. So it might not come as a surprise that the famous
({\scshape Heisenberg}--){\scshape Kennard} indeterminacy inequality $\displaystyle\hbar/2\leq\sigma_P \sigma_Q$  has an entropic analog. It was conjectured by {\scshape Hirschman} in 1957
and proved by {\scshape  Beckner} and {\scshape Białynicki--Birula-Mycielski} in 1975.



\paragraph{Assumption and notations:}

\begin{itemize}
  \item  State vector corresponding to a pure state (position representation)
\[\psi \in \LL^2(\R)\,,\,\,\langle\psi|\psi\rangle=\int_\R \dd q \,\big|\psi(q)\big|^2 = 1\quad\big(|\psi(q)|^2 = \langle q|W|q\rangle\,,\quad W\ceq\big|{\psi}\rangle\langle\psi\big|\big).\]

\item Transformed state vector by {\scshape Fourier--Plancherel} (``momentum representation'')
    \[\widehat{\psi} (p) \ceq \int_\R \frac{\dd q}{\sqrt{2\pi\hbar}}\,\psi(q)\,\textrm{e}^{-\ii pq/\hbar}, \quad \int_\R \dd p \,\big| \widehat{\psi}(p) \big|^2 = 1\,.\]

\item  \emph{Pseudo-classical} state assigned to $W$
     \[\boxedeqn{w(p,q) \ceq 2\pi \hbar \,\big|\widehat{\psi}(p)\big|^2 \,\big|\psi (q) \big|^2}\,\]
     \[w \geq 0\,,\quad\langle w, 1\rangle = \int_{\R\times\R} \frac{\dd p\,\dd q}{2\pi\hbar}\, w(p,q) = 1\,.\]
 \end{itemize}

\paragraph{Assertion} (\emph{entropic} \ini\ for momentum and position):

\medskip
 The classical entropy of $w$ has the state independent lower bound
  $\displaystyle\ln \frac{\textrm{e}}{2} $, that is
\[\boxedeqn{ \ln \frac{\textrm{e}}{2}\leq - \langle w, \ln w\rangle}\,.\]

\paragraph{Interpretation:}~

\medskip
Although the entropies of the (quantal) probability densities on the momentum and position space may be individually arbitrarily small and even negative, their sum does not fall below $\ln (\textrm{e}/2)= 1 - \ln 2\ > 0.3068$.

\begin{proof} (following \cite{Hi1957,Bec1975,B--BM1975})

The function $f:{[2,\infty[}\rightarrow\R$, defined by the difference

\[f(\sv)\ceq \left(\frac{\su}{2\pi \hbar} \right)^{1/(2\su)}\big\|\psi\big\|_\su-\left(\frac{\sv}{2 \pi \hbar}\right)^{1/(2\sv)} \big\| \widehat{\psi}\big\|_\sv\quad \quad \big(\,\sv \geq 2\,,\quad \su\ceq \sv/(\sv-1)\in {]1,2]}\big)\;\]

in terms of the usual {\scshape Lebesgue} norm $\|\varphi\|_r \ceq (\int_\R \dd x \, |\varphi(x)|^r)^{1/r} $\, with\, $r\in [1,\infty[$\,, fulfills $f(2)=0$ by the well-known  {\scshape Parseval--\scshape Plancherel} equality, observed already above for $\langle w, 1\rangle = 1$. Less well known is the sharp {\scshape Hausdorff}--{\scshape Young} inequality $f(\sv)\geq 0$ for all $\sv\geq 2$, see \cite {LL2001}. The combination of both implies $f'(2+0)\geq 0$  for the (right-sided) derivate of $f$ at $2$. This last inequality turns out to be equivalent to the assertion when using the formula

\[r^2\frac{\dd}{\dd{r}}\big\|\varphi\big\|_r=  \big\|\varphi\big\|_r^{1-r}\int_\R \dd x |\varphi(x)|^r\ln\big(|\varphi(x)|^r/ ||\varphi ||_r^{r}\big)\,\]

with $r=2$ for $\varphi=\psi$ as well as for $ \varphi=\widehat{\psi}$ and observing again
$||\psi||_2=||\widehat{\psi}||_2=1$.
\qed
\end{proof}

\paragraph{Remarks:}

\begin{itemize}%[label = \roman*)]
\setlength\itemsep{0.25em}
\item The assertion is extended from pure to all states $W\,(\geq W^2\,)$ by using the extended definition $w(p,q)\ceq2\pi \hbar \langle p|W|p\rangle\langle q|W|q\rangle\geq 0$ for the pseudo-classical state assigned to $W$. The claim then follows from the spectral resolution\footnote{see Explanation \ref{zustaende}.} of $W$, the convexity of the function $x \mapsto x \ln x$ (for $x> 0$), the {\scshape Jensen} inequality, and the result for pure $W$.
\smallskip 
\item The \emph{entropic} \ini\ implies the (weakened) \emph{variance} \ini\ of Explanation \ref{uu}:
\[\frac{\hbar}{2}\leq\sigma_P \sigma_Q\,.\]

\begin{proof} of the last statement:
\begin{enumerate}[label = \alph*), ref = \alph*)]
	\item\label{bem_a} In a first step the elementary inequality $\ln x\leq x-1$ yields
	\begin{align*}
	-\big\langle w, \ln w\big\rangle = - \big\langle w,\ln \widetilde{w}\big\rangle + \Big\langle w,\ln\frac{\widetilde w}{w}\Big\rangle\leq -\big\langle w, \ln \widetilde{w}\big\rangle
	\end{align*}
	for any probability density (or classical state) $\widetilde{w}$ on the phase space $\R \times \R$\,.

	\item\label{bem_b} The second step consists in choosing in \ref{bem_a} the {\scshape Gauß} density 
	\begin{align*}
	\widetilde{w}(p,q)= \frac{\hbar}{\sigma_P \sigma_Q} \exp\bigg\{-\frac{(p - \braket{P})^2}{2\sigma_P^2}-\frac{(q - \braket{Q})^2}{2\sigma_Q^2}\bigg\} 
	\end{align*} 
	characterized by the means and variances of $P$ and $Q$ and by a zero covariance with respect to $W$.
	The entropic \ini, combined with a), then yields the claim as follows

	\begin{align*}
	\quad\ln\frac{\textrm{e}}{2}&\leq-\langle w,\ln w\rangle \leq -\langle w,\ln\widetilde{w}\rangle\\
	&=- \Big\langle w, \ln \left(\frac{\hbar}{\sigma_P\sigma_Q}\right) - \frac{1}{2\sigma_P^2} \big(p - \langle P\rangle \big)^2 -\frac{1}{2\sigma_Q^2} \big( q - \langle Q\rangle\big)^2\Big\rangle \\
	&= - \ln \left(\frac{\hbar}{\sigma_P \sigma_Q}\right) + \frac{1}{2} + \frac{1}{2} =\ln \left( \frac{\textrm{e}}{\hbar} \sigma_P \sigma_Q \right)\,.
	\end{align*}
\end{enumerate} 
\qed
\end{proof}
\end{itemize} 
\paragraph{Conclusion:}~

\medskip
\boxedtext{\parbox{0.98\textwidth}{If the \emph{entropic} indeterminacy inequality (\ini) is strict, then the assigned (non-{\scshape Gauss}ian) pseudo-classical state provides a sharpening of the most famous \emph{variance} \ini. Equality in the latter implies that in the former.}}

