\medskip
\item Simplifications for \emph{compatible} events, that is, for pairwise \emph{commuting} projections ($EF=FE$ etc.):
\[E \wedge F = EF, \quad E\vee F = E+F - EF\,.\]
These imply the {\scshape Boole}an distributive laws:
  \begin{align*}
   E \wedge (F \vee G) &= (E \wedge F) \vee (E \wedge G)\\
   E \vee (F \wedge G) &= (E \vee F) \wedge (E \vee G)\,.
  \end{align*}

\item Each subset of pairwise commuting projections in $\mathcal{P}(\H)$ with $\uu$ and $\mathbb{0}$ is isomorphic to the {\scshape Boole}an lattice of subsets of some basic set with the set-theoretic operations complement, intersection, and union.
\end{itemize}

\begin{center}
 \boxedtext{
 \begin{minipage}{\textwidth-11pt}
\begin{theorem*} 

\medskip
If $W$ is a state on $\H$, then the mapping $\mu : {\mathcal P}(\H)\to\R$, defined by
$E \mapsto \mu(E) \ceq \tr(WE)$, is a \emph{probability measure} on $\mathcal{P}(\H)$ in 
the sense that it has the following three properties:
\begin{enumerate}[label=\alph*)]
 \item\label{alpha} $\displaystyle 0 \leq \mu(E) \leq 1$
 \item\label{beta} $\displaystyle \mu(\mathbb{0})=0,\; \mu(\uu)=1$
 \item\label{gamma} $\displaystyle \mu\Big(\bigvee_n E_n \Big) = \sum_n\mu(E_n)$ for any sequence $(E_n)$ of pairwise \emph{disjoint}\\ and pairwise \emph{commuting} projections.
\end{enumerate} 
\end{theorem*}
 \end{minipage}}
\end{center}

\paragraph{Explanation:}

\medskip
 If $EF=FE$, then the following equivalences hold:
 \[
   E\,\, \text{and}\,\,  F\,\, \text{are \emph{disjoint}} : \Leftrightarrow\ E\wedge F = \mathbb{0} \,  \Leftrightarrow\, E \vee F = E+F\,\Leftrightarrow\, EF=\mathbb{0} 
 \,.\]
 Accordingly, the property \ref{gamma} in the theorem can be rewritten as
 \begin{enumerate}
\item[c')] $\displaystyle \mu\Big(\sum_n E_n\Big) = \sum_n \mu(E_n)$ for any sequence $(E_n)$ of pairwise \emph{orthogonal} projections, that is, $E_n E_m= \delta_{mn} E_n\,.$ 
\end{enumerate}
Therefore the proof of the theorem is obvious if $\H$ is finite-dimensional. For $\dim\H=\infty$ see Theorem A11 in \cite{BC1981}. The following \emph{reverse statement} is deeper and its proof more arduous \cite{Gl1957}. A simplified proof is given in \cite{CKM1985}, see also \cite{Hug1989}.

\begin{center}
 \boxedtext{
 \begin{minipage}{\textwidth-11pt}
\begin{theorem*}({\scshape Gleason} 1957)

\medskip
If $\dim \H \geq 3$, then there exists for each probability measure $\mu$ on $\mathcal{P}(\H)$ a unique state $W$ on $\H$ such that $\mu(E) = \tr(WE)$ for all $E \in \mathcal{P}(\H)$.{}
\end{theorem*}
 \end{minipage}}
\end{center}

\paragraph{Remarks:}

 \begin{itemize}
  \item Each ONB in $\H$ provides an example of a sequence of pairwise orthogonal (one-dimensional) projections.

  \item The \emph{quantum} probability theory (QPT) with the lattice of projections (resp. corresponding subspaces) is more general than the classical one (\CPT) of {\scshape Kolmogorov} 1933, but reduces to \CPT\ for any ({\scshape Boole}an) \emph{sublattice} of $\mathcal{P}(\H)$ containing only pairwise \emph{commuting} projections including $\mathbb{0}$ and $\uu$ \cite{Heg1985,Stre2000,Ac2010}.

\smallskip

Analogy:\\
QPT extends \CPT\ similarly as the non-{\scshape Euclid}ean geometry extends the {\scshape Euclid}ean one \cite{Stre2007,Ac2010}. The outcomes of experiments decide which theory is better suited to model aspects of Nature.

\item For $\dim \H = 2$ there are more general probability measures $\mathcal{P}(\H)$! 

This can be seen as follows:

\bigskip
\begin{enumerate}[label=\alph*)]

\item Explicit description of all elements of $\mathcal{P}(\C^2)$:

\medskip
A \QM\ system with the two-dimensional {\scshape Hilbert} space $\H\cong\C^2$ is the simplest. It can be viewed as a single spin with (intrinsic) main quantum number $\nicefrac{1}{2}$. The corresponding vector operator $\vv{S} \ceq (S^{x}, S^{y}, S^{z})$ is represented in the eigenbase of $S^{z}$, up to factor $\hbar/2$, by the triple of ({\scshape Dirac}--){\scshape Pauli} matrices according to:
 \[S^{x}\,\widehat{=}\begin{pmatrix} 0 &1\\ 1 &0  \end{pmatrix},\,\; S^{y}\,\widehat{=}\begin{pmatrix} 0 &-\ii\\ \ii &0 \end{pmatrix},\,\; S^{z}\,\widehat{=} \begin{pmatrix} 1 &0\\ 0 &-1 \end{pmatrix}
 \,.\]

They are self-adjoint, their squares are equal to the ${2\times 2}$ unit matrix representing the unit operator $\uu$, and they imply the identities
 $S^{x}S^{y}=\ii S^{z}$, $S^{y}S^{z}=\ii S^{x}$ and $S^{z}S^{x}=\ii S^{y}$\,.

The lattice $\mathcal{P}(\C^2)$ consists of the following projections:\\

\arrayrulecolor{red}
\begin{tabular}{p{0.28\textwidth}|p{0.36\textwidth}|}\cline{2-2}&\\
one 0-dimensional & $\mathbb{0}$ \\&\\
one 2-dimensional & $\uu$ \\&\\
a 2-parameter \newline family of 1-dimensional &  $\displaystyle E\ceq \frac{1}{2} (\uu + \vv{e} \boldsymbol{\cdot} \vv{S})$,\newline $\vv{e} \in\R^3$ with $|\vv{e}| = 1$ \medskip\\\cline{2-2}
\end{tabular}
\arrayrulecolor{black}

\begin{tabular}{lp{0.68\textwidth}}
Implication: &$(\vv{e}\boldsymbol{\cdot} \vv{S})E=E$\medskip\\
Interpretation:& $E$ is a pure eigenstate of the spin component\newline
$\vv{e}\boldsymbol{\cdot}\vv{S}\ceq e^{x}S^{x} + e^{y}S^{y} + e^{z}S^{z}$ in $\vv{e}$ direction with eigenvalue $1$.
\end{tabular}

\bigskip
\item Explicit description of all probability measures on $\mathcal{P}(\C^2)$:

\medskip
\[\boxedeqn{\mu(0) \ceq 0,\;\, \mu(\uu) \ceq 1,\;\, \mu(E) \ceq \frac{1}{2} \left(1 + m(\vv{e})\right)}\]
Here $m$ is an arbitrary mapping of the 2-sphere $\mathbb S^2$ to the interval ${[-1,1]}$ with $m(-\vv{e}) = - m(\vv{e})$ (to guarantee $\mu(E) + \mu(E^\bot) = 1$).
\newline Simplest example:\; $m(\vv{e})=0$ for all unit vectors $\vv{e}$.

\bigskip
A comparison with the three formulas $\,\tr(W\mathbb{0})=0$, $\,\tr(W\uu)=1\,$, and\\ $\,\tr(WE)=1+\frac{1}{2}\vv{e}\boldsymbol{\cdot} \tr(W\vv{S})\,$ now yields the 


\medskip
\textbf{Equivalence}:
\newline
\medskip
\boxedtext{
\begin{tabular}{p{0.27\textwidth}p{0.05\textwidth}p{0.46\textwidth}}
$\mu$ is induced by a state $W$ on $\C^2$ &$\Longleftrightarrow$ &There is $\vv{p} \in \R^3$ with $|\vv{p}~| \leq 1$, such that \newline $m (\vv{e}) =\vv{p}\boldsymbol{\cdot} \vv{e}$ for all $\vv{e}\in\R^3$ with $|\vv{e}| = 1$
\end{tabular}}

\begin{proof} Put $\vv{p} = \tr(W \vv{S})$ and conversely $W = \frac{1}{2}(\uu   + \vv{p} \boldsymbol{\cdot} \vv{S})$\,.\qed\end{proof}

The above claimed existence of probability measures \emph{not} arising from a state $W$ on $\C^2$, is now easy to see.


\smallskip
Here are two examples (with $\vv{\lambda}\in\R^3$, $\vv{\lambda}\neq\vv{0}$):
\begin{enumerate}[label=\roman*)]
 \item $\displaystyle m(\vv{e}) = \sin(\vv{\lambda}\boldsymbol{\cdot} \vv{e}),\qquad \sin(\xi)\ceq\frac{1}{2\ii}\big(\textrm{e}^{\ii\xi}-\textrm{e}^{-\ii\xi}\big)\quad$ for $\quad\xi\in\R$
\medskip
 \item $\displaystyle m(\vv{e}) = \sgn(\vv{\lambda}\boldsymbol{\cdot} \vv{e}),\qquad \sgn(\xi) \ceq\begin{cases} 1 \: &\text{for}\quad \xi \geq 0\\ -1 \: &\text{für}\quad \xi < 0 
\end{cases}$
\end{enumerate}
The resulting measures $\mu$ do not seem to have any physical relevance, but some of their ``relatives'' play a role in classical models with hidden variables for \QM\ systems with $\dim {\cal H}=2$ (see Section 5.1).
\end{enumerate}
\end{itemize}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{On the Realistic Interpretability of Quantum Mechanics}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Edward {\scshape Nelson} (1932--2014)\;\; (in \cite[p. 230]{Fa2006}):\\

``\emph{The problem of finding a realistic interpretation of quantum mechanics is, in my view, as unresolved as it was in the 1920s}.'' 

\paragraph{Findings}\,

\medskip
The {\scshape Hilbert}-space formalism of \QM\ with its pragmatic and minimal(istic) \emph{statistical interpretation} -- as summarized above -- has evolved over the decades to the most successful theory of physics.

\paragraph{Discomfort of classical realists}

(like {\scshape Planck}, {\scshape Einstein}, {\scshape deBroglie}, {\scshape Schrödinger}, D. {\scshape Bohm}, {\scshape Bell}, \dots) 

\medskip
Even in pure states, ``most'' observables do not have a specific value, but are \emph{objectively indeterminate}. Values only arise as factual outcomes of measurements with an \emph{intrinsic} probability $\langle W, E\rangle$, as briefly described in Explanation\,\ref{varianz} of Section\,2.2 about the ``state collapse''. This contrasts with a sentence by {\scshape Einstein} to {\scshape Born} in December 1926, often shortened but pithily quoted as ``Gott würfelt nicht.''\footnote{In English: ``God does not play dice.''} Even to this day, no proposal at understanding the quantal indeterminacy or accepting it as a feature of (a veiled?) reality has found general agreement. This is, of course, related to the infamous \emph{measurement problem}. For some discussions of the latter see \cite{Zeh1970,Mit1998,Ho2001,Zeh2007,BLPY2016,Hay2017}.
\bigskip

\paragraph{Hope for a way out by cryptodeterminism} (Models with hidden variables (\HV))

\medskip
The indeterminacy $\sigma_A^2 > 0$ in non-eigenstates of an observable $A$ may be explained by ``embedding'' the \QM\ into a more fundamental probabilistic theory, which is \emph{realistically} (or ``classically'') interpretable in the following sense:
\begin{enumerate}[label = \roman*)]

\item Each observable $A$ of an \emph{individual} \QM\ system has in each (pure) state $W$ an \emph{objectively definite} (eigen)value, pre-existing before any measurement.

 \item The \QM\ probabilities only express that the distribution of these values is in general not concentrated at a single point, unknown, and empirically in-accessable, that is,  \emph{hidden}.  

\end{enumerate}

\medskip
In short: \hfill\boxedtext{\emph{Subjective ignorance} instead of \emph{objective indeterminacy}}\hfill\,

\smallskip
[somewhat similar to \emph{statistical} \CM].

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Basic idea behind most models with hidden variables}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{itemize}
 \item Starting point:
  \QM\ system with {\scshape Hilbert} space $\H$, observables $A: \H \rightarrow \H$, and a state $W: \H \rightarrow \H$ mostly assumed to be pure.
  \item Classical \emph{probability space} \cite{Bau1996}:
 $\big(\Omega, \mathcal{A}(\Omega),\P\big)$, that is, a triple consisting of the set $\Omega$ of the \emph{hidden variables} $\omega$, a sigma algebra $\mathcal{A}(\Omega)$ of subsets of $\Omega$, and a probability measure $\P$ on $\Omega$, more precisely, on $\mathcal{A}(\Omega)$.
\item Desired identity:
 \[\boxedeqn{\int_\Omega \P(\dd\omega)\, a_W(\omega) = \tr(WA)}\]
 for a suitable  \emph{value-function}  $a_W :\Omega\rightarrow \R$ assigned to the pair $(A,W)$. In \CPT\ such a function is usually called a random variable.
\end{itemize}

\paragraph{Remarks:}

 \begin{itemize}
 \item The \emph {hidden variables} $\omega\in\Omega$ discriminate between the individual systems (realizations).
\item The probability measure $\P$ also may depend on $W$, or $W$ may only be ``transferred‘‘ from $a_W$ to $\P$. The {\scshape Weyl}--{\scshape Wigner} mapping of Section 2.5 provides something similar to the latter case with the phase space $\Gamma$ playing the role of $\Omega$, the {\scshape Wigner} density $w$ that of $\P_W$, and the symbol $a$ that of $a_W$. However, one problem with this \HV\ model is that $w$
is in general not positive everywhere. Another one is that the symbol of $A^2$ in general does not equal the square of the symbol of $A$ etc.

\end{itemize}  

\emph{Interpretation:} 

\medskip
While the description by a (pure) \QM\ state $W(=W^2)$ may not provide a ``complete picture'' of the physical reality on its own, the pair $(W, \omega)$, the so-called \emph{microstate}, does it in the sense of the \emph{assignment}:
\[ \big(A, (W, \omega) \big) \mapsto a_W(\omega) = \text{value of the observable $A$ in the microstate $(W,\omega)$}\,.\]

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\paragraph{Model with hidden variables in the case of a two-dimensional {\scshape Hilbert} space:}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{itemize}
 \item {\scshape Hilbert} space $\H = \C^2$ associated to a single spin $\nicefrac{1}{2}$ as in Section\,4.{}
 \item Useful relation for the product of two general spin-operator components:
  \[\boxedeqn{
 \big(\vv{a}\cdot\vv{S}\big)\big(\vv{b}\cdot\vv{S}\big)=\vv{a}\cdot\vv{b}\uu+\ii\big(\vv{a}\times\vv{b}\big)\cdot\vv{S}
 }\]
 for \emph{any} vectors $\vv{a},\vv{b}\in\R^{3}$ in terms of its dot product and cross product.

  \item Each \QM\ observable $A$ on $\C^2$ is a linear combination:
   \[\boxedeqn{
    A = a_0 \uu + \vv{a}\boldsymbol{\cdot} \vv{S}}
   \]
   with $a_0 \ceq \frac{1}{2} \tr A \in\R$ and  $\vv{a} \ceq \frac{1}{2} \tr(A \vv{S})\in\R^3$.
\smallskip
\item Equivalence: % (if $\vv{a}\neq\vv{0}\neq\vv{b}$):
\[\boxedeqn{
 AB = BA \; \Leftrightarrow \; \vv{a}\text{ and }\vv{b}\,\text{are parallel or anti-parallel (that is, \emph{collinear}}  }\,, \]
by the commutation relation $AB-BA=2 \ii\big(\vv{a}\times\vv{b}\big)\cdot\vv{S}$ from the above ``useful relation''.


 \item Each \QM\ state $W$ on $\C^2$ can be written as (see also Section~4):
  \[\boxedeqn{W = \frac{1}{2} ( \uu + \vv{p}\boldsymbol{\cdot} \vv{S})}\,.  \]
Here the vector $\vv{p} \ceq \tr(W\vv{S})\in\R^3$ is called the \emph{polarization} of $W$ and obeys $|\vv{p}\,|\leq 1$. The pure states (or \emph{qubits} of quantum information theory) are exactly the \emph{totally} polarized ones: 
  \[\boxedeqn{ W = W^2  \; \Leftrightarrow \; |\vv{p}\,| = 1 }\,. \]

Conclusion:

\smallskip
\boxedtext{\parbox{0.93\textwidth}{Each state $W$ corresponds exactly to one point of the closed unit ball in $\R^3$ (called {\scshape Bloch} ball in this setting). The pure states correspond to the points on its surface ${\mathbb S}^2$.}}
\medskip
\item Expectation values are given by: 
  \[\boxedeqn{
   \tr(WA) = a_0 + \vv{p}\boldsymbol{\cdot}\vv{a}}\,.
  \]
\end{itemize}

With the choices\footnote{and the definition $\sgn(0)\ceq 1.$}
\begin{center}\renewcommand{\arraystretch}{1.5}
 \boxedtext{\begin{tabular}{l}
$\Omega={\mathbb S}^2$ = unit sphere in $\R^3$\\
${\cal A}(\Omega)={\cal B}(\mathbb{S}^2)\ceq$ sigma algebra of the {\scshape Borel} subsets of ${\mathbb S}^2$\\
 $\P =$ uniform distribution on $\Omega$\\
  $\displaystyle a_W (\vv{\omega}) \ceq a_0 + |\vv{a}|
  \sgn\left((\vv{p} + \vv{\omega})\boldsymbol{\cdot} \vv{a} \right),\qquad \vv{\omega}\in{\mathbb S}^2$
 \end{tabular}}
\end{center}

one now gets indeed, by explicit integration in spherical coordinates, the desired formula

\[
	\int_\Omega \P(\dd \vv{\omega})\, a_W(\vv{\omega})
	= \frac{1}{4\pi}\int_{\R^3}\!\dd^3\!\omega \,\,\delta\big(|\vv{\omega}| - 1\big)\,a_W(\vv{\omega}) = a_0+\vv{p}\boldsymbol{\cdot}\vv{a}=\tr(WA)\,.{}
\]
\textbf{Facts} on the above assignment\, $A\mapsto a_W$\; (for fixed $W$, equivalently, fixed $\vv{p}$)\,:\\
\begin{itemize}
 \item the value $a_W(\vv{\omega})$ of $a_W$ coincides with one of the two eigenvalues $a_0 \pm|\vv{a}|$ of the observable $A\;\leftrightarrow\; (a_0, \vv{a})$. This is called \emph{spectral consistency}. In particular,
\[e_W(\vv{\omega})=\frac{1}{2}\Big(1+\sgn\big((\vv{p}+\vv{\omega})\boldsymbol\cdot\vv{e}\big)\Big)\] 
is (for $\vv{p}=\vv0$) one of the (eigen)values of a 1-dimensional projection $E$ of the example~ii) in Section~4 for a probability measure on ${\cal P}(\C^2)$, which does not arise from a \QM\ state. 
 \item the (eigen)value $c_W(\vv{\omega})$ of the sum $C\ceq A + B$ is \emph{additively consistent} in the sense that $c_W(\vv{\omega}) = a_W(\vv{\omega}) + b_W(\vv{\omega})$ if \boxedtext{$AB=BA$}\,. 

\item the (eigen)value $d_W(\vv{\omega})$ of the product $D\ceq AB$ is \emph{multiplicatively consistent} in the sense that $d_W(\vv{\omega}) = a_W(\vv{\omega}) b_W(\vv{\omega})$ if  \boxedtext{$AB=BA$}\,. In particular, the microstate $(W,\vv{\omega})$ is universally fluctuation-free because $d_W(\vv{\omega}) = \big(a_W(\vv{\omega})\big)^2$ for $A=B$.

\item the assignment is \emph{injective} (or one-to-one) in the sense that $a_W(\vv{\omega})= b_W(\vv{\omega})$ for all $ \vv{\omega}$ implies $A=B$\;.
\end{itemize}\medskip

Remarks:
\begin{itemize}
\item Such \HV~models for $\dim \H = 2$ go back to a publication of {\scshape J.S. Bell}  in 1966 (submitted in 1964), see the first paper re-printed in \cite{Bel2004}.
\item For $\dim \H \geq 3$ such \HV~models do not exist (for \emph{all} observables), because then there ermerges a conflict between the above consistencies and the injectivity.This will be explained in the next subsection.
\end{itemize}

