\section{Correlation Inequalities of {\scshape Bell} and Others}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\paragraph{Warning:}\,

\medskip
In this last section the commutator of $X$ and $Y$ is defined by $[X,Y]\ceq XY-YX$, that is, without the factor $\ii/\hbar$.

\medskip
\boxedtext{\begin{minipage}{\textwidth-11pt}
\begin{theorem*} ({\scshape Bell} 1964, {\scshape Clauser}--{\scshape Horne}--{\scshape Shimony}--{\scshape Holt} 1969; {\scshape Tsirelson} 1980)

\medskip
Let $A, B, C, D$ be four self-adjoint operators on an at least 4-dimensional {\scshape Hilbert} space $\H$ with the properties $A^2=B^2=C^2=D^2= \uu$ and $[A, C]=[A,D]=[B,C]=[B,D]=\mathbb{0}$.
%
 Moreover, consider the operator $K:= A (C+D)+ B(C-D)$ \,and\,the expectation functional  $\langle\boldsymbol{\cdot} \rangle \ceq \tr(W \boldsymbol{\cdot})$ induced by a state\, $W$\, on $\H$.\medskip

Then one has:
\begin{enumerate}[label=\roman*)]
  \item\label{satz_i} $K=K^*$\; and\; $K^2 = 4\,\uu - [A, B][C,D]$

  \item\label{satz_ii} $|\langle K\rangle| \leq 2 \sqrt{2}$\qquad ({\scshape Tsirelson} inequality)

  \item\label{satz_iii} If $\langle [A, B][C, D]\rangle\geq 0$\,, then \,$|\langle K\rangle| \leq 2$\qquad ({\scshape B--CHSH} inequality)\,.
 \end{enumerate}
 \end{theorem*} 
\end{minipage}}

\begin{proof}
\begin{enumerate}[label=\roman*)] \item By $(X+Y)^*=X^*+Y^*$\,and 
 $(XY)^*=Y^*X^* $\, resp.\, by explicit squaring.
\item The positivity of the variance combined with the subadditivity (= triangle inequality) and submultiplicativity (= multiplicative inequality) of the operator norm, see Explanation~\ref{skalarprodukt} in Section 2.2, gives as claimed

 % \begin{align*}
  \[\big|\langle K\rangle\big|^2= \langle K\rangle^2 \leq\langle K^2\rangle \leq\big\|K^2\big\| \overset{\ref{satz_i}}  {\leq} \big\|4\,\uu\big\| + \big\|[A, B][C, D]\big\|
  \leq 4 + (1+1)(1+1) = 4 \cdot 2\,.\]
 %\end{align*}
\item $\big|\langle K\rangle\big|^2 = \langle K\rangle^2\leq \langle K^2\rangle\overset{\ref{satz_i}}=4-\langle [A, B][C, D]\rangle\leq 4 $\,.\qed
\end{enumerate}
\end{proof}

\paragraph{Remarks:}

%\medskip
\begin{itemize}
\item  For this elegant and simple proof see \cite{T/C1980,La1987,Stre2007}. One should  note the generality of the result. Neither ``stochastic independence'' nor ``locality'' is assumed, whatever the latter may mean. The interpretation of the theorem is as simple as its proof. It merely says that non-commutativity can make a difference in obtaining upper bounds on quantal expectation values. In the present case the two (anti-self-adjoint) commutators $[A, B]$ and $[C, D]$ commute with each other, so that they have a joint eigenbasis in $\H$. Nevertheless, in general it is not obvious, how to measure observables like $K$ or $K^2$ in realizable experiments \cite{Per2002,LeB2006}. 

\item To call $|\langle K\rangle| \leq 2$  the ``{\scshape B--CHSH} inequality'' is justified, because it also holds, when $A, B, C, D$ are interpreted as (commuting) \emph{classical} random variables taking values $\pm 1$ and the angular brackets $\braket{\boldsymbol{\cdot}}$ as the expectation with respect to an (unknown) arbitrary joint probability measure/distribution for these values, as in the \HV\ model of {\scshape B--CHSH}\; ($K^2 = 4 $\; implies\; $K=\pm 2$\; for all $2^4 = 16$ realizations), see the second paper re-printed in \cite{Bel2004} and \cite{CHSH1969}.

\end{itemize}

\subsection*{Application: Spin correlations in the singlet state}
\begin{itemize}
\item QM system: Again composed of two spins with $\H = \H_1 \otimes \H_2$,\, $\H_1 = \H_2 \cong\C^2$

\item Two arbitrary spin components on $\H_1$ resp. $\H_2$ as observables on $\H$ in terms of four \emph{unit} vectors $\vv{a}, \vv{b}, \vv{c}, \vv{d} \in \R^3$\,:

\[\boxedeqn{
   A\ceq\vv{a}\boldsymbol{\cdot} \vv{S} \otimes \uu,\; B\ceq\vv{b}\boldsymbol{\cdot}\vv{ S} \otimes \uu, \; C\ceq\uu \otimes \vv{c}\boldsymbol{\cdot}\vv{S},\;  D\ceq\uu \otimes \vv{d}\boldsymbol{\cdot}\vv{S}\,.}\]
Obviously, they satisfy the assumptions of the above theorem.

 \item \emph{Singlet state} (in manifestly spin-rotation-invariant form, confer Section 3.2):
  \[\boxedeqn{
   W^-=\frac{1}{4} \left(\uu \otimes \uu - \left(\vv{S} \otimes \uu \right)\boldsymbol{\cdot} \left(\uu \otimes \vv{S} \right) \right)}\;\, \widehat{=}\,|\Phi^-\rangle\langle\Phi^-|
  \]
fulfills
\[(W^-)^2=W^- \quad \text{and}\quad (\vv{S}\otimes \uu + \uu \otimes \vv{S})^2 W^- =\mathbb{0}\,.\]
It is therefore a pure eigenstate of the squared total-spin vector with eigenvalue
$0=4\cdot 0(0+1)$, which justifies its name. Moreover, it is the (unique) ground state of the 
{\scshape Hamilton}ian\; $H\ceq\sv\, (\vv{S} \otimes \uu)\boldsymbol{\cdot} (\uu \otimes \vv{S})$ coupling the two spins anti-ferromagnetically: $HW^- =-3\sv W^-,\; \sv> 0$.

\item Combining the four observablen $A, B, C, D$, as defined above, to $K$ as in the theorem and computing the expectation value in the singlet state $W^-$ gives explicitly:
  \begin{align*}
 \braket{K} &= \braket{AC} + \braket{AD} + \braket{BC} - \braket{BD}\\
  &= \kappa_{A, C} + \kappa_{A, D} + \kappa_{B, C} - \kappa_{B, D}\\ 
  &=-\vv{a}\boldsymbol{\cdot} \vv{c} - \vv{a}\boldsymbol{\cdot} \vv{d} - \vv{b}   			\boldsymbol{\cdot} \vv{c} + \vv{b}\boldsymbol{\cdot} \vv{d}\,.
 \end{align*}

 \item If, for example, all four unit vectors  $\vv{a}, \vv{b}, \vv{c}, \vv{d}$ are \emph{coplanar} and aligned as in the following figure, then one finds $\braket{K} = - 2\sqrt{2}$, hence equality in the {\scshape Tsirelson} inequality~\ref{satz_ii} and therefore a
\boxedtext{Maximum violation of the {\scshape B--CHSH} inequality!}
