\paragraph{(ii) $\boldsymbol{N=2}$.} For $1 < \alpha \leq 2$ the solutions of eq.\eqref{fde.rule.1}  
are 
\begin{equation}
\label{phi.zero.alpha.2}
\phi^{\scriptstyle 2}_{0,\alpha}(\omega t) = \sum_{m=0}^\infty (-1)^m C_{0,m}^{\scriptstyle 2}(\alpha) (\omega t)^{2m} ,
\end{equation}
with 
\begin{equation}
\label{C.0.m.aux}
C_{0,m}^{\scriptstyle 2}(\alpha) = \frac{\llbracket (3-\alpha)/2;1/2\rrbracket_m}{\llbracket 
3/2;1/2\rrbracket_m} = \frac{G[(3-\alpha)/2+m;1/2]G(3/2;1/2)}{G[(3-\alpha)/2;1/2]G(3/2+m;1/2)} , 
\end{equation}
and 
\begin{equation}
\label{phi.one.alpha.2}
\phi^{\scriptstyle 2}_{1,\alpha}(\omega t) = \sum_{m=0}^\infty (-1)^m C_{1,m}^{\scriptstyle 2}(\alpha) (\omega t)^{2m+1} ,
\end{equation}
with 
\begin{equation}
\label{C.0.m.aux.1}
C_{1,m}^{\scriptstyle 2}(\alpha) = \frac{\llbracket 2-\alpha/2;1/2\rrbracket_m}{\llbracket 
2;1/2\rrbracket_m} = \frac{G(2-\alpha/2+m;1/2)G(2;1/2)}{G(2-\alpha/2;1/2)G(2+m;1/2)} , 
\end{equation}
where $G(-;-)$ is the double gamma function. 
We have in Figure~\ref{fig.2} the
plots of $\phi_{0,\alpha}^{\scriptstyle 2}(t)$   
and in Figure~\ref{fig.3} the
plots of $\phi_{1,\alpha}^{\scriptstyle 2}(t)$ for $\alpha = \{2,1.9,1.8\}$. 
When $\alpha = 2$ we have, using eq.\eqref{ap.B.general.G.tau} in eq.\eqref{C.0.m.aux} 
and in  eq.\eqref{C.0.m.aux.1} that 
\begin{equation}
C_{0,m}^2(2) = \frac{G(1/2+m;1/2) G(3/2;1/2)}{G(1/2;1/2)G(3/2+m;1/2)} = \frac{1}{\Gamma(2m+1)}
\end{equation}
and 
 \begin{equation}
C_{1,m}^2(2) =  \frac{G(1+m;1/2) G(2;1/2)}{G(1;1/2)G(2+m;1/2)} = \frac{1}{\Gamma(2m+2)} ,
\end{equation}
and therefore 
\begin{equation}
\phi_{0,2}^2(\omega t) = \cos{\omega t} , \qquad \phi_{1,2}^2(\omega t) = \sin{\omega t} . 
\end{equation}


