It is also interesting to note that using eq.\eqref{modular.2} with $p = \tau = 1$ and $q = 2$ 
we can rewrite $C_{j,m}^2(\alpha)$ for $j = 0,1$ as 
\begin{equation}
C_{j,m}^2(\alpha) = \frac{1}{2^{\alpha m}} \frac{\llbracket (3-\alpha+j)/2\rrbracket_m \llbracket (4-\alpha+j)/2\rrbracket_m}{\llbracket (3+j)/2\rrbracket_m \llbracket (4+j)/2\rrbracket_m} . 
\end{equation} 


\subsection{FDE using rule II}


The fractional version of eq.\eqref{DE.int.order.nu} using the rule in eq.\eqref{subs.2} is  
\begin{equation}
\label{fde.rule.2}
\left(t^{\alpha^\prime - 1} {\sideset{_{}^{}}{_{{t}}^{\alpha^\prime}}{\operatorname{\mathcal{D}}}}\right)^N f = -\omega^N f , 
\end{equation}
where  $0 < \alpha^\prime \leq 1$ for $N = 1,2,\ldots$. In this case we have 
to use eq.\eqref{analytic.2} recursively, that is, 
\begin{equation}
\left(t^{\alpha^\prime - 1} {\sideset{_{}^{}}{_{{t}}^{\alpha^\prime}}{\operatorname{\mathcal{D}}}}\right)^N f = \sum_{k=0}^\infty f_{k+N} \left[\prod_{i=1}^N \frac{\Gamma(k+i+1)}{\Gamma(k+i+1-\alpha)}\right] t^k ,
\end{equation}
which in eq.\eqref{fde.rule.2} shows that we must have 
\begin{equation}
f_{k+N} = -\omega^N \prod_{i=1}^k \frac{\Gamma(k+i+1-\alpha^\prime)}{\Gamma(k+i+1)} f_k , \quad k=0,1,2,\ldots 
\end{equation}
From this recurrence relation we obtain 
\begin{equation}
f_{mN+j}  = \left(-\omega^N\right)^m \prod_{r=1}^{mN}\frac{\Gamma(r+j+1-\alpha^\prime)}{\Gamma(r+j+1)} f_j ,
\end{equation}
with $j = 0,1,\ldots,N-1$ and $ m=1,2,\ldots$. 


Defining $K^{\scriptscriptstyle N}_{j,m}(\alpha^\prime)$ as 
\begin{equation}
K^{\scriptscriptstyle N}_{j,m}(\alpha^\prime) = \begin{cases} 1 , \quad & m = 0 , \\[1ex]
\displaystyle \prod_{r=1}^{mN}  \frac{\Gamma(r+j+1-\alpha^\prime)}{\Gamma(r+j+1)} , \quad & m = 1,2,\ldots 
\end{cases}
\end{equation}
and the constants $\kappa_j$ as 
\begin{equation}
f_j = (\omega)^j \kappa_j ,
\end{equation}
we can write $f(t)$ as 
\begin{equation}
f(t) = \sum_{j=0}^{N-1} \kappa_j \psi_{j,\alpha^\prime}^{\scriptscriptstyle N}(\omega t) ,
\end{equation}
where 
\begin{equation}
\psi_{j,\alpha^\prime}^{\scriptscriptstyle N}(\omega t) = \sum_{m=0}^\infty (-1)^m K^{\scriptscriptstyle N}_{j,m}(\alpha^\prime) (\omega t)^{m N + j} , \quad j = 0,1,\ldots,N-1.  
\end{equation}

Like in the previous case, we can also use the double gamma function to 
write a convenient expression for the coefficients $K^{\scriptscriptstyle N}_{j,m}(\alpha^\prime)$, 
but in this case the parameter $\tau$ is $\tau = 1$, that is, we have the
Barnes $G$-function $G(z)$. We have 
\begin{equation}
K^{\scriptscriptstyle N}_{j,m}(\alpha^\prime) = 
\frac{\llbracket j + 2-\alpha^\prime\rrbracket_{mN}}{\llbracket j+2\rrbracket_{mN}} ,
\end{equation}
and then 
\begin{equation}
\label{def_psi_j}
\psi_{j,\alpha^\prime}^{\scriptscriptstyle N}(\omega t) = \sum_{m=0}^\infty (-1)^m \frac{\llbracket j + 2-\alpha^\prime\rrbracket_{mN}}{\llbracket j+2\rrbracket_{mN}} (\omega t)^{m N + j} , \quad j = 0,1,\ldots,N-1.
\end{equation}

Like the case of eq.\eqref{def_phi_j}, the convergence of eq.\eqref{def_psi_j}
 for all values of $\omega t$ also follows using 
Gautschi's inequality. 

