\subsubsection{Examples} 



\paragraph{(i) $\boldsymbol{N=2}$.} From eq.\eqref{def_psi_j} we have 
\begin{equation}
\label{psi.0.alphaprime}
\begin{aligned}
\psi_{0,\alpha^\prime}^2(\omega t) & = \sum_{m=0}^\infty \frac{\llbracket 2-\alpha^\prime\rrbracket_{2m}}{\llbracket 2 \rrbracket_{2m}} (-1)^m (\omega t)^{2m}   \\[1ex]
& = \frac{G(2)}{G(2-\alpha^\prime)} 
\sum_{m=0}^\infty \frac{G(2-\alpha^\prime+2m)}{G(2+2m)} (-1)^m (\omega t)^{2m}
\end{aligned}
\end{equation}
and 
\begin{equation}
\label{psi.1.alphaprime}
\begin{aligned}
\psi_{1,\alpha^\prime}^2(\omega t) & = \sum_{m=0}^\infty \frac{\llbracket 3-\alpha^\prime\rrbracket_{2m}}{\llbracket 3 \rrbracket_{2m}} (-1)^m (\omega t)^{2m+1} \\[1ex]
&  = \frac{G(3)}{G(3-\alpha^\prime)} 
\sum_{m=0}^\infty \frac{G(3-\alpha^\prime+2m)}{G(3+2m)} (-1)^m (\omega t)^{2m+1} .
\end{aligned}
\end{equation}
Using eq.\eqref{functional.barnes.G} it is not difficult to see that, for $\alpha^\prime \to 1$, 
we have, as expected, 
\begin{equation}
\psi_{0,1}^2(\omega t) = \cos{\omega t} , \qquad 
\psi_{1,1}^2(\omega t) = \sin{\omega t} .
\end{equation}
We have in Figure~\ref{fig.5} the
plots of $\psi_{0,\alpha^\prime}^{\scriptstyle 2}(t)$   
and in Figure~\ref{fig.6} the
plots of $\psi_{1,\alpha^\prime}^{\scriptstyle 2}(t)$ for $\alpha^\prime = \{1,0.95,0.9\}$. 




\section{Comparison between solutions of FDEs} 



In this section we will compare the solutions of the equations with the 
dimensional regularized Caputo derivative obtained in the previous section with 
the solutions of the equation involving the regular Caputo derivative. 
For convenience we will choose $\omega = 1$. 


\paragraph{(i) $\boldsymbol{N=1}$.} Let us consider the ODE 
\begin{equation}
\label{decay.order.1}
\frac{dy}{dt} +  y = 0 . 
\end{equation}
The corresponding FDE obtained using the regular Caputo derivative is 
\begin{equation}
\label{fde.ex.caputo.1}
{\sideset{_{}^{}}{_{{t}}^{\alpha}}{\operatorname{\mathcal{D}}}} y + y = 0 , \qquad 0 < \alpha \leq 1 ,
\end{equation}
whose solution is 
\begin{equation}
\label{sol.fde.ex.caputo.1}
y = y(0) \operatorname{E}_\alpha\left(- t^\alpha\right) ,
\end{equation}
where $\operatorname{E}_\alpha(\cdot)$ is the Mittag-Leffler function. The FDE obtained using
rule I or II is 
\begin{equation}
\label{fde.rule.1.bis}
t^{\alpha - 1} {\sideset{_{}^{}}{_{{t}}^{\alpha}}{\operatorname{\mathcal{D}}}}  y + y = 0 ,  \qquad 0 < \alpha \leq 1 ,
\end{equation}
whose solution is given by $\phi_{0,\alpha}^{\scriptstyle 1}( t)$ as in eq.\eqref{phi.zero.alpha}. 

In Figure~\ref{fig.7} we compare the solutions with $y(0) = 1$ of eq.\eqref{decay.order.1} and its fractional version in eq.\eqref{fde.ex.caputo.1} and
eq.\eqref{fde.rule.1.bis}. We choose for comparison $\alpha = 0.8$ and for simplicity we use $\kappa = 1$. So we   
have in Figure~\ref{fig.7} the plots of $\exp{(-t)}$, $\operatorname{E}_{0.8}{(-t^{0.8})}$ and 
$\phi_{0,0.8}^{\scriptstyle 1}(t)$. 
\begin{figure}[hbt]
\begin{center}
\includegraphics[width=12cm]{graficos_4_3.pdf}
\end{center}
\caption{Plots of the solution of eq.\eqref{decay.order.1}, that is, $\exp{(-t)}$, and its fractional version in eq.\eqref{fde.ex.caputo.1} and
eq.\eqref{fde.rule.1.bis} (with $\kappa = 1$)  for $\alpha = 0.8$, that is, $\operatorname{E}_{0.8}{(-t^{0.8})}$ and 
$\phi_{0,0.8}^{\scriptscriptstyle 1}(t)$, respectively. \label{fig.7}}
\end{figure}

We can see that for values of $t$ such that $0 < t < 0.84$ (value obtained numerically using Mathematica), 
function $\operatorname{E}_{0.8}{(-t^{0.8})}$ decays faster than $\exp(-t)$, but for $t > 0.84$ this behaviour changes, 
and for $t \to \infty$ the function has a behaviour \cite{Mainardi}
$\operatorname{E}_{0.8}(-t^{0.8}) \sim t^{-0.8}/\Gamma(0.2)$.
The function $\phi_{0,0.8}^{\scriptscriptstyle 1}(t)$, on the other hand, has a decay that is always slower than $\exp(-t)$ for $t > 0$.
At the point $t = 2.01$ (value obtained numerically using Mathematica), the solution $\operatorname{E}_{0.8}(-t^{0.8})$ begins to 
show values greater than those of $\phi_{0,0.8}^{\scriptscriptstyle 1}(t)$, and after that these graphs never cross again. 
For $t\to \infty$ the we have $\phi_{0,0.8}^{\scriptscriptstyle 1}(t)  \sim t^{-1}/\Gamma(0.2)$ \cite{Simon}.

\paragraph{(ii) $\boldsymbol{N=2}$.} Let us consider the ODE  
\begin{equation}
\label{ode.two}
\frac{d^2 y}{dt^2} +  t = 0. 
\end{equation}
The corresponding FDE version obtained using the regular Caputo derivative is 
\begin{equation}
\label{fde.ex.caputo.2}
{\sideset{_{}^{}}{_{{t}}^{\alpha}}{\operatorname{\mathcal{D}}}} y +  y = 0 , \qquad 1 < \alpha \leq 2 ,
\end{equation}
whose solution is 
\begin{equation}
\label{sol.fde.ex.caputo.2}
y = y(0) \operatorname{E}_{\alpha,1}\left(- t^\alpha\right) + 
y^\prime(0) \, t \operatorname{E}_{\alpha,2}\left(- t^\alpha\right)  ,
\end{equation}
where $\operatorname{E}_{\alpha,\beta}(\cdot)$ is the two-parameter Mittag-Leffler function, 
\begin{equation}
\operatorname{E}_{\alpha,\beta}(z) = \sum_{n=0}^\infty \frac{z^n}{\Gamma(n\alpha + \beta)} ,
\end{equation}
and such that $\operatorname{E}_\alpha(\cdot) = \operatorname{E}_{\alpha,1}(\cdot)$ .
The FDE obtained using
rule I is 
 \begin{equation}
\label{fde.rule.10}
t^{\alpha - 2} {\sideset{_{}^{}}{_{{t}}^{\alpha}}{\operatorname{\mathcal{D}}}} y +  y  = 0 , 
\qquad 1 < \alpha \leq 2 , 
\end{equation}
whose solution is a linear combination $\phi^{\scriptstyle 2}_{0,\alpha}( t)$ 
and $\phi^{\scriptstyle 2}_{1,\alpha}(t)$ given by eq.\eqref{phi.zero.alpha.2} and
eq.\eqref{phi.one.alpha.2}, respectively. 
 On the other hand, the FDE obtained using rule II is
  \begin{equation}
\label{fde.rule.11}
\left(t^{\alpha^\prime - 1} {\sideset{_{}^{}}{_{{t}}^{\alpha^\prime}}{\operatorname{\mathcal{D}}}}\right)^2 y +  y  = 0 , 
\qquad 0 < \alpha^\prime \leq 1 , 
\end{equation}
whose solution is a linear combination $\psi^{\scriptstyle 2}_{0,\alpha^\prime}( t)$ 
and $\psi^{\scriptstyle 2}_{1,\alpha^\prime}(t)$ given by eq.\eqref{psi.0.alphaprime} and
eq.\eqref{psi.1.alphaprime}, respectively. 

Let us consider in separate the solutions for the initial conditions 
(i) $y(0) = 1$ and $ y^\prime(0) = 0$, and (ii) $y(0) = 0$ and $ y^\prime(0) = 1$. 
For (i) $y(0) = 1$ and $ y^\prime(0) = 0$, the solutions of 
eq.\eqref{ode.two}, eq.\eqref{fde.ex.caputo.2}, eq.\eqref{fde.rule.10} and 
eq.\eqref{fde.rule.11} are, respectively, $\cos{t}$, $\operatorname{E}_{1.9}\left(-t^{1.9}\right)$, 
$\phi_{0,1.9}^2(t)$ and $\psi_{0,0.95}^2(t)$, whose plots are in Figure~\ref{fig.8}. 


\begin{figure}[hbt]
