\section{The Barnes $\boldsymbol{G}$ and double gamma functions}
\label{appendix.A}

Around the turn of the 20th century, E. W. Barnes and others 
studied how to generalize the properties of the gamma function \cite{Barnes1,Barnes2,Barnes3,others}. 
Examples of functions defined in this context are the Barnes $G$-function $G(z)$ and 
its generalization $G(z,\tau)$, the so-called double gamma function, with 
$G(z,1) = G(z)$. Firstly let us 
define the function $G(z)$. 
The \textit{Barnes $G$-function} $G(z)$ was introduced in \cite{Barnes1} as a generalization 
of the gamma function $\Gamma(z)$. To see this, we begin by recalling the Weierstrass definition of the 
gamma function:  
\begin{equation}
\label{weierstrass.gamma}
\frac{1}{\Gamma(z)}  = z e^{\gamma z} \prod_{k=1}^\infty \left(1 + \frac{z}{k}\right) e^{-\frac{z}{k}} ,
\end{equation}
where $\gamma$ is the Euler-Mascheroni constant. This representation 
clearly shows that $1/\Gamma(z)$ is an entire function in the complex plane 
and that has simple zeros at $z = -k$ ($k=0,1,2,\ldots)$. 
Barnes defined the $G$-function as 
\begin{equation}
\label{weierstrass.G}
G(1+z)=(2\pi)^{z/2} \exp\left(- \frac{z+z^2(1+\gamma)}{2} \right) \, \prod_{k=1}^\infty \left\{ \left(1+\frac{z}{k}\right)^k \exp\left(\frac{z^2}{2k}-z\right) \right\} .
\end{equation}
Similar to $1/\Gamma(z)$, the function $G(z)$ is an entire function in the complex plane. 
However, the zeros of $G(z)$ at $z = -k$ have order  
$k+1$ at $z = -k$ ($k = 0,1,2,\ldots$). 

Equivalent definitions are 
\begin{equation}
\begin{split}
\label{ap.B.def.G.1}
G(z+1) = & (2\pi)^{z/2} \exp\left[\left(\gamma-1/2\right)z - \frac{z^2}{2}\left(
\frac{\pi^2}{6}+1+\gamma\right)\right] z \Gamma(z) \\
& \cdot \prod_{m,n\in \mathbb{N}_\ast^2} \left[ 
\left(1+\frac{z}{m+n}\right) \exp\left(-\frac{z}{m+n}+\frac{z^2}{2(m+n)^2}\right)\right] , 
\end{split}
\end{equation}
and 
\begin{equation}
\label{ap.B.def.G.2}
G(z+1)=(2\pi)^{z/2} \exp\left(- \frac{z+z^2(1+\gamma)}{2} \right) \, \prod_{k=1}^\infty \left\{
\frac{\Gamma(k)}{\Gamma(k+z)} \exp\left[z \psi(k) + \frac{z^2}{2}\psi^\prime(k)\right]\right\}
\end{equation}
where $\psi(\cdot)$ is the digamma function and $\mathbb{N}_\ast = \mathbb{N}\setminus\{0\}$. 

From these definitions we obtain the
functional relation 
\begin{equation}
\label{functional.barnes.G}
G(z+1) = \Gamma(z) G(z) . 
\end{equation}
Additionally, the definition implies that  
\begin{equation}
G(1) = 1. 
\end{equation}
As a result, we have 
\begin{equation}
G(n+2) = 0! \, 1! \, 2! \cdots n! \quad (n=0,1,2,\ldots) .
\end{equation}



 Denoted by $G(z; \tau)$, the \textit{double gamma function}  is a 
generalization of the $G$-function. 
It is defined as \cite{Kusnetsov}
\begin{equation}
\label{ap.B.G.tau.1}
\begin{split}
G(z;\tau) = & \frac{z}{\tau} \exp\left[a(\tau)\frac{z}{\tau} + b(\tau)\frac{z^2}{2\tau}\right] \\
& \cdot \prod_{m,n\in \mathbb{N}_\ast^2} \left[ 
\left(1+\frac{z}{m\tau+n}\right) \exp\left(-\frac{z}{m\tau+n}+\frac{z^2}{2(m\tau+n)^2}\right)\right] , 
\end{split}
\end{equation}
where $a(\tau)$ and $b(\tau)$ are given by 
\begin{equation}
\begin{split}
& a(\tau) = \gamma \tau + \frac{\tau}{2}\log{(2\pi \tau)} + \frac{1}{2}\log\tau - \tau C(\tau) , \\
& b(\tau) = - \frac{\pi^2 \tau^2}{6} - \tau \log\tau - \tau^2 D(\tau) , 
\end{split}
\end{equation}
with 
\begin{equation}
\begin{split}
& C(\tau) = \lim_{m\to \infty} \left[\sum_{k=1}^{m-1}\psi(k\tau) + \frac{1}{2}\psi(m\tau) - \frac{1}{\tau} 
\log\left(\frac{\Gamma(m\tau)}{\sqrt{2\pi}}\right) \right] , \\
& D(\tau) = \lim_{m\to \infty} \left[\sum_{k=1}^{m-1}\psi^\prime(k\tau) + \frac{1}{2}\psi^\prime(m\tau) - \frac{1}{\tau}\psi(m\tau) \right] . 
\end{split}
\end{equation}
Another definition of double gamma function is 
\begin{equation}
\label{ap.B.G.tau.2}
G(z;\tau) = \frac{1}{\tau\Gamma(z)} \exp\left[\tilde{a}(\tau)\frac{z}{\tau} + \tilde{b}(\tau) 
\frac{z^2}{2\tau^2}\right] \prod_{m=1}^\infty \frac{\Gamma(m\tau)}{\Gamma(z+m\tau)} 
\exp\left[z\psi(m\tau)+ \frac{z^2}{2}\psi^\prime(m\tau) \right] ,
\end{equation}
where 
\begin{equation}
\tilde{a}(\tau) = a(\tau) - \gamma\tau , \qquad \tilde{b}(\tau) = b(\tau) + \frac{\pi^2 \tau^2}{6} .
\end{equation}
Barnes $G$-function $G(z)$ is a particular case of the double 
gamma function $G(z;\tau)$ for $\tau = 1$. Note that $C(1) = 1/2$ and $D(1) = 1+ \gamma$, as shown 
in \cite{Barnes1}. 

The double gamma function is defined in such a way that 
\begin{equation}
\label{ap.B.G.tau.(1)}
G(1;\tau) = 1 . 
\end{equation}
It satisfies the functional relations 
\begin{equation}
\label{ap.B.general.G.tau}
G(z+1;\tau) = \Gamma(z/\tau) G(z;\tau) 
\end{equation} 
and 
\begin{equation}
\label{ap.B.general.G.tau.2}
G(z+\tau;\tau) = (2\pi)^{\frac{\tau-1}{2}} \tau^{-z+\frac{1}{2}} \Gamma(z) G(z;\tau) ,
\end{equation}
which generalize eq.\eqref{functional.barnes.G}. A straightforward consequence of these properties is 
\begin{equation}
\label{ap.B.G.tau.cons}
G(1+\tau;\tau) = G(\tau;\tau) = (2\pi)^{(\tau-1)/2} \tau^{-1/2} . 
\end{equation}
Moreover, using eq.\eqref{ap.B.general.G.tau}  and eq.\eqref{ap.B.general.G.tau.2}  recursively, we obtain
\begin{equation}
\label{ap.B.general.G.tau.n}
G(z+k;\tau) = G(z;\tau) \prod_{j=0}^{k-1} \Gamma[(z+j)/\tau]   
\end{equation}
and 
\begin{equation}
\label{ap.B.general.G.tau.2.n}
G(z+k\tau;\tau) = (2\pi)^{k(\tau-1)/2} \tau^{k(-z+(1-\tau(k-1))/2)} \left[\prod_{j=0}^{k-1} \Gamma(z+j\tau)\right] G(z;\tau)   , 
\end{equation}
respectively. 
Another interesting relations are  
\begin{equation}
\label{modular.transf}
G(z;\tau) = (2\pi)^{z(1-1/\tau)/2} 
\tau^{[(z-z^2)/(2\tau) +z/2 -1]} G(z/\tau;1/\tau) . 
\end{equation}
and, for $p, q \in \mathbb{N}$, 
\begin{equation}
\label{modular.2}
G(z;p\tau/q) = q^{\frac{1}{2p\tau}(z-1)(qz-p\tau)} (2\pi)^{-(q-1)(z-1)/2} 
\prod_{i=0}^{p-1} \prod_{j=0}^{q-1} \frac{G[(z+i)/p + j \tau/q;\tau]}{G(1+i)/p+j\tau/q;\tau]}  .
\end{equation}





An integral representation for $G(z;\tau)$ was provided in \cite{lawrie}, namely 
\begin{equation}
\label{double.gamma.int.rep}
\begin{aligned}
\ln G(z;\tau) & = \int_0^1 \bigg[ \frac{r^{z-1}}{(r-1)(r^\tau-1)} - 
\frac{z^2}{2\tau} r^{\tau-1} - z r^{\tau-1}\left(\frac{2-r^\tau}{r^\tau-1}-\frac{1}{2\tau}\right) \\
& -r^{\tau-1} + \frac{1}{r-1} - \frac{r^{\tau-1}}{(r-1)(r^\tau-1)}\bigg] \frac{dr}{\ln{r}} . 
\end{aligned}
\end{equation}
It is convergent for $\operatorname{Re}z > 0$ and $\delta > 0$.  


Finally, let us recall that the Pochhammer symbol is defined as $(a)_n = a(a+1)\cdots (a+n-1)$ 
with $(a)_0 = 1$, or 
\begin{equation}
\label{ap.B.pochhammer}
(a)_n = \frac{\Gamma(a+n)}{\Gamma(a)} . 
\end{equation}
Since the double gamma function generalizes the gamma function, it is natural to generalize the 
definition of the Pochhammer symbol using $G(z;\tau)$ \cite{Simon}. So we define 
\begin{equation}
\label{ap.B.G.pochhammer}
\llbracket  a;\tau \rrbracket_n = \frac{G(a+n;\tau)}{G(a;\tau)} . 
\end{equation} 
From eq.\eqref{ap.B.general.G.tau.n} it follows that the usual Pochhammer symbol can be written in terms of the $G$-Pochhammer symbol 
as 
\begin{equation}
\label{ap.B.poch.G.poch.gen.2}
(a)_n = \tau^n \frac{\llbracket a+\tau;\tau\rrbracket_{n}}{\llbracket a;\tau\rrbracket_{n}} . 
\end{equation}



\section{The Kilbas-Saigo function}

Let $\alpha,m > 0$ and $l > -1/\alpha$. The Kilbas-Saigo function $E_{\alpha,m,l}(z)$ is defined by the series \cite{Meccanica} 
\begin{equation}
\label{KS.function.def}
E_{\alpha,m,l}(z) = \sum_{k=0}^\infty c_k z^k   
\end{equation}
with  
\begin{equation}
\label{def.ck}
c_0 = 1 , \qquad c_k = \prod_{j=0}^{k-1} \frac{\Gamma[\alpha(jm+l)+1]}{\Gamma[\alpha(jm+l+1)+1]} , \quad 
(k=1,2,\ldots) . 
\end{equation}

Let $\llbracket a;\tau\rrbracket_k$ be the $G$-Pochhammer symbol defined in eq.\eqref{ap.B.G.pochhammer}. 
Using eq.\eqref{ap.B.general.G.tau.n} it follows that the Kilbas-Saigo function $E_{\alpha,m,l}(z)$ can be written as 
\begin{equation}
\label{KS.G}
E_{\alpha,m,l}(z) = \sum_{k=0}^\infty \frac{\llbracket (\alpha l+1)/(\alpha m);1/(\alpha m)\rrbracket_k}{\llbracket (\alpha (l+1)+1)/(\alpha m);1/(\alpha m)\rrbracket_k} z^k .
\end{equation}




