% path integral of electron propagator
\section{Path integral representation of polaron propagator}
In this section, we fill in the gaps in the derivation of the path integral representation of electron propagator. We consider a chain of $N$ sites subject to periodic boundary condition. The Hamiltonian reads:
\begin{align}
H = \underbrace{-\sum_i (c^\dagger_i c^{\phantom\dagger}_{i+1}+ c^\dagger_{i+1} c^{\phantom\dagger}_i)}_{K} + \underbrace{\sum_q \omega_q b^\dagger_q b^{\phantom\dagger}_q -  \lambda f_q n_q (b_q + b^\dagger_{-q})}_{V}.
\label{eq:Hamil}
\end{align}
The first term $K$ is the electron kinetic energy. $c^\dagger_i$ ($c_i$) creates (annihilates) a spinless electron on site $i$. We set the electron hopping amplitude to 1 by rescaling the unit of energy. The second term $V$ describes the phonons and their coupling to electron. $b^\dagger_q$ ($b_q$) creates (annihilates) a phonon with wave vector $q$. $n_q = \frac{1}{\sqrt{N}}\sum_k c^\dagger_{k+q} c^{\phantom\dagger}_k$ is the Fourier transform of electron density operator. $\omega_q$ is the phonon dispersion relation. $f_q = f^\ast_{-q}$ is a form factor. $\lambda>0$ is the electron-phonon coupling constant. 

We are interested in the zero temperature electron propagator in the momentum space:
\begin{align}
iG^R(k,t) = \theta(t) \langle 0| c^{\phantom\dagger}_k (t) c^\dagger_k (0) |0\rangle =  \langle 0| c^{\phantom\dagger}_k e^{-iHt} c^\dagger_k |0\rangle.
\end{align}
$|0\rangle$ refers to the ground state of Eq.~\eqref{eq:Hamil} in the zero-electron sector. As $c^\dagger_k$ creates an electron, the ensuing time evolution occurs in the one-electron sector. 

To derive the path integral representation, we use the second order Suzuki-Trotter decomposition, $e^{-i\epsilon H} =  e^{-i\frac{\epsilon}{2}V} e^{-i\epsilon K} e^{-i\frac{\epsilon}{2} V} + O(\epsilon^3)$. Substituting it into the expression for $G^R$, we obtain:
\begin{align}
iG^R(k,t) = \theta(t) \sum_{r} e^{ikr} \langle 0| c^{\phantom\dagger}_r  \underbrace{e^{-i\frac{\epsilon}{2}V}e^{-i\epsilon K} e^{-i\epsilon V}\cdots e^{-i\epsilon V} e^{-i\epsilon K} e^{-i\frac{\epsilon}{2} V}}_\textrm{M hopping terms} c^\dagger_0 |0\rangle.
\end{align}
We insert the resolution of identity by electron position eigenstates and use the fact that $V$ commutes with the electron position operator:
\begin{align}
iG^R(k,t) = \theta(t) \sum_{\{x\}}  e^{ikr} \langle x_{M}|e^{-i\epsilon K}|x_{M-1}\rangle \cdots \langle x_{1} |e^{-i\epsilon K}|x_{0}\rangle 
 \langle \phi| e^{-i\frac{\epsilon}{2}V(x_{M})}e^{-iV(x_{M-1})} \cdots e^{-i\epsilon V(x_1)} e^{-i\frac{\epsilon}{2}V(x_0)}|\phi\rangle.
\end{align}
The summation is over all electron paths $x_0,x_1,\cdots x_{M}$ , with the boundary condition $x_0 = 0$ and $x_{M} = r$. $V(x)$ refers to the phonon Hamiltonian when the electron is at position $x$:
\begin{align}
V(x) = \sum_q (\omega_q b^\dagger_q b^{\phantom\dagger}_q - \frac{\lambda f_q e^{iqx}}{\sqrt{N}} b_q - \frac{\lambda f^\ast_{q} e^{-iqx}}{\sqrt{N}} b^\dagger_{q}).
\label{eq:V_x}
\end{align}
Here, we have used $n_q |x\rangle = \frac{1}{\sqrt{N}}e^{iqx}|x\rangle$. $|\phi\rangle$ is the phonon vacuum.

In the next step, we perform a change of variable from electron position $x_n$ to electron displacement $s_n = x_n-x_{n-1}$:
\begin{align}
iG^R(k,t) = \theta(t) \sum_{\{s\}} (\prod^M_{j=1}e^{iks_j}) A_0(\{s\}) I(\{s\}).
\end{align}
Here, $\{s\} = \{s_M,\cdots s_2,s_1\}$. $A_0$ is the quantum amplitude for a free particle:
\begin{align}
A_0(\{s\}) =  \prod^M_{j=1}f(s_j), \quad
f(s) = \langle x+s|e^{-i\epsilon K} |x\rangle = 
\left\{\begin{array}{cc}
 1-\epsilon^2 & (s=0) \\
  i\epsilon  & (s = \pm 1) \\
-\epsilon^2/2 & (s = \pm 2) 
\end{array}\right. .
\end{align}
Here, we have truncated the range of $s$ to $|s|\le 2$. This truncation introduces an error of order $\epsilon^3$, which is comparable to that of the Trotter error. The phonon influence functional $I$ is given by:
\begin{align}
I(\{s\}) = \langle \phi| e^{-i\frac{\epsilon}{2}V(x_{M})} e^{-i\epsilon V(x_{M-1})} \cdots e^{-i\epsilon V(x_1)} e^{-i\frac{\epsilon}{2}V(x_0)}|\phi\rangle.
\end{align}
The right hand side depends on $\{s\}$ implicitly through the relation $x_{j} = x_{j-1} + s_j$, with the initial condition $x_0 = 0$.

We wish to make the dependence of $I$ on $\{s\}$ explicit. To this end, we use the translation operator $T(x)$ on phonon states $T(-x) b_q T(x) = e^{-iqx} b_q$. It follows that $T(x) V(0) T(-x) = V(x)$.
$I$ now depends on $\{s\}$ explicitly:
\begin{align}
I(\{s\}) &= \langle \phi| e^{-i\frac{\epsilon}{2}V(0)} T(-s_M) e^{-i\epsilon V(0)} \cdots T(-s_2)e^{-i\epsilon V(0)} T(-s_1) e^{-i\frac{\epsilon}{2}V(0)}|\phi\rangle
\nonumber\\
& = \langle \phi| U(s_M) \cdots U(s_2)U(s_1)|\phi\rangle.
\end{align}
Here, we have defined the unitary operator:
\begin{align}
U(s) = e^{-i\frac{\epsilon}{2}V(0)}T(-s)e^{-i\frac{\epsilon}{2}V(0)}.
\end{align}

% MPS formula of B tensor
\section{Exponentiation of influence functional \label{sec:exp}}

$I(\{s\})$ already has a matrix product structure; it can be viewed as a diagonal matrix product operator whose virtual  space is the phonon Hilbert space. In this section, we show that $I(\{s\})$ can be exponentiated as:
\begin{align}
I(\{s\}) = e^{\lambda^2 S(\{s\})},
\end{align}
where $S(\{s\})$ has a matrix product form whose bond dimension is $N+2$. 

We view $I(\{s\})$ as a sequence of controlled unitary evolution of the phonon states, starting from the phonon vacuum $|\phi\rangle$. We note that $U(s)$ maps phonon coherent state to coherent state, and, furthermore, that the initial state is a coherent state. Therefore, the phonons stay in the coherent state manifold. We may parametrize the phonon state as:
\begin{align}
e^{\lambda^2 S_j }|\lambda z_j \rangle = U(s_j)\cdots U(s_2)U(s_1)|\phi\rangle.
\end{align}
Here, $S_j$ is a complex number; $z_j$ is a $N$-dimensional complex vector that parametrize the coherent state, whose entry runs over all phonon wave vectors. In particular, $z_q$ corresponds to the phonon mode with wave vector $q$. The scaling factor $\lambda^2$ ($\lambda$) in front of $S_j$ ($z_j$) is for later convenience.

We now derive a recursion relation for the parameters $S_j$ and $z_j$. We first consider the action of $\exp(-i\frac{\epsilon}{2}V(0))$ on phonon coherent state:
\begin{align}
e^{-i \frac{\epsilon}{2}V(0)}|\lambda z\rangle &= \prod^{\otimes}_{q} \exp (-i \frac{\omega_q \epsilon}{2} b^\dagger_q b^{\phantom\dagger}_q + i\frac{\lambda f_q \epsilon}{2\sqrt{N}} b_q + i\frac{\lambda f^\ast_{q} \epsilon}{2\sqrt{N}} b^\dagger_q ) |\lambda z_q\rangle.
\end{align} 
We untangle the operator exponential by the following identity:
\begin{align}
e^{-Ab^\dagger b + B b + C b^\dagger} = e^{\frac{BC}{A}-\frac{BC}{A^2}(1-e^{-A})} e^{-Ab^\dagger b}e^{C\frac{e^{A}-1}{A}b^\dagger} e^{B\frac{1-e^{-A}}{A}b}.
\end{align}
Setting 
\begin{align}
A = \frac{i\omega_q\epsilon}{2};
\quad
B = i\frac{\lambda f_q \epsilon}{2\sqrt{N}};
\quad
C = i\frac{\lambda f^\ast_q\epsilon}{2\sqrt{N}},
\end{align}
we obtain:
\begin{align}
\exp (-i \frac{\omega_q \epsilon}{2} b^\dagger_q b^{\phantom\dagger}_q + i\frac{\lambda f_q \epsilon}{2\sqrt{N}} b_q + i\frac{\lambda f^\ast_{q} \epsilon}{2\sqrt{N}} b^\dagger_q ) = \exp[ i\frac{\lambda^2|f_q|^2}{2N\omega_q}\epsilon - \frac{\lambda^2|f_q|^2}{N\omega^2_q}(1-e^{-i\frac{\omega_q\epsilon}{2}})]
\nonumber\\
\exp(-i\frac{\omega_q\epsilon}{2} b^\dagger_q b^{\phantom\dagger}_q) 
\exp[\frac{\lambda f^\ast_q}{\sqrt{N}\omega_q}(e^{i\frac{\omega_q\epsilon}{2}}-1)b^\dagger_q] 
\exp[\frac{\lambda f_q}{\sqrt{N}\omega_q}(1-e^{-i\frac{\omega_q\epsilon}{2}})b_q].
\end{align}
Computing its action on coherent state is now straightforward:
\begin{align}
\exp (-i \frac{\omega_q \epsilon}{2} b^\dagger_q b^{\phantom\dagger}_q + i\frac{\lambda f_q \epsilon}{2\sqrt{N}} b_q + i\frac{\lambda f^\ast_{q} \epsilon}{2\sqrt{N}} b^\dagger_q )  |\lambda z_q\rangle
=  \exp[ i\frac{\lambda^2|f_q|^2}{2N\omega_q}\epsilon - \frac{\lambda^2|f_q|^2}{N\omega^2_q}(1-e^{-i\frac{\omega_q\epsilon}{2}}) + \frac{\lambda^2 f_q}{\sqrt{N}\omega_q}(1-e^{-i\frac{\omega_q\epsilon}{2}})z_q]
\nonumber\\
|\lambda e^{-i\frac{\omega_q\epsilon}{2}}z_q+\frac{\lambda f^\ast_q}{\sqrt{N}\omega_q}(1-e^{-i\frac{\omega_q\epsilon}{2}})\rangle.
\end{align}

Collecting the results for different $q$, we obtain:
\begin{align}
e^{-i\frac{\epsilon}{2}V(0)} e^{\lambda^2 S} |\lambda z \rangle = e^{\lambda^2 (S+ c + \beta^\dagger z)} | \lambda (\mathcal{V} z + \alpha) \rangle,
\end{align}
Here, $\mathcal{V}$ is a diagonal matrix whose diagonal entry reads:
\begin{subequations}
\begin{align}
\mathcal{V}_{qq} = \exp(-i\frac{\omega_{q}\epsilon}{2}).
\end{align}
$\alpha$ and $\beta$ are complex $N$-dimensional vectors:
\begin{align}
\alpha_q = \frac{f^\ast_q}{\sqrt{N}\omega_q}(1-e^{-i\frac{\omega_q \epsilon}{2}});
\quad
\beta_q = \frac{f^\ast_q}{\sqrt{N}\omega_q}(1-e^{i\frac{\omega_q \epsilon}{2}}) = -(\mathcal{V}^{\dagger}\alpha)_q;
\end{align}
$c$ is a complex number:
\begin{align}
c = \frac{1}{N}\sum_q \frac{|f_q|^2}{\omega_q}(i\frac{\epsilon}{2} - \frac{1-e^{-i\frac{\omega_q\epsilon}{2}}}{\omega_q}).
\end{align}
\end{subequations}

We recognize that the action of $\exp(-i\frac{\epsilon}{2}V(0))$ on phonon coherent state in fact induces an affine transformation:
\begin{align}
S \overset{e^{-i\frac{\epsilon}{2} V(0)}}{\longrightarrow} S + c + \beta^\dagger z,\quad z \overset{e^{-i\frac{\epsilon}{2} V(0)}}{\longrightarrow} \mathcal{V} z + \alpha.
\end{align}
We recast the above in matrix form:
\begin{align}
\begin{pmatrix}
S \\
z \\
1
\end{pmatrix} \overset{e^{-i\frac{\epsilon}{2} V(0)}}{\longrightarrow} \begin{pmatrix}
1 & \beta^\dagger & c \\
0 & \mathcal{V} & \alpha \\
0 & 0 & 1
\end{pmatrix} \begin{pmatrix}
S \\
z \\
1
\end{pmatrix}.
\end{align}

Likewise, the lattice translation operator $T(x)$ maps coherent state to coherent state. To prove this, we use:
\begin{align}
T(x)^{-1} b_q T(x) = e^{-iqx} b_q.
\end{align}
It follows that:
\begin{align}
b_q(T(x)|z_q\rangle) = e^{-iqx}z_q T(x)|z_q\rangle,
\end{align}
which implies
\begin{align}
T(x)|z_q\rangle = |e^{-iqx}z_q\rangle.
\end{align}
Collecting the results for different $q$, we find:
\begin{align}
T(-s) e^{\lambda^2 S}|\lambda z\rangle = e^{\lambda^2 S} |\lambda \mathcal{T}(-s) z \rangle,
\end{align}
where $\mathcal{T}(x)$ is a diagonal unitary matrix whose diagonal entries are given by:
\begin{align}
\mathcal{T}(x)_{qq} = e^{-iqx}.
\end{align}
The induced linear transformation on $S$ and $z$ can be written in matrix form:
\begin{align}
\begin{pmatrix}
S \\
z \\
1
\end{pmatrix} \overset{T(-s)}{\longrightarrow} \begin{pmatrix}
1 & 0 & 0 \\
0 & \mathcal{T}(-s) & 0 \\
0 & 0 & 1
\end{pmatrix} \begin{pmatrix}
S \\
z \\
1
\end{pmatrix}.
\end{align}

Combining the above results, we arrive at the following recursion relation for $S_j$ and $z_j$:
\begin{align}
\begin{pmatrix}
S_{j} \\
z_{j} \\
1
\end{pmatrix} = \begin{pmatrix}
1 & \beta^\dagger & c \\
0 & \mathcal{V} & \alpha \\
0 & 0 & 1
\end{pmatrix}
 \begin{pmatrix}
1 & 0 & 0 \\
0 & \mathcal{T}(-s_{j}) & 0 \\
0 & 0 & 1
\end{pmatrix}
\begin{pmatrix}
1 & \beta^\dagger & c \\
0 & \mathcal{V} & \alpha \\
0 & 0 & 1
\end{pmatrix}
\begin{pmatrix}
S_{j-1} \\
z_{j-1} \\
1
\end{pmatrix} \equiv B(s_j) \begin{pmatrix}
S_{j-1} \\
z_{j-1} \\
1
\end{pmatrix}.
\end{align}
Here, $B(s_j)$ is a $N+2$ dimensional square matrix. The initial condition is $z_0 = 0$ and $S_0 = 0$.

We now compute $I(\{s\})$ using the recursion relation. By definition:
\begin{align}
I(\{s\}) = e^{\lambda^2 S_M }\langle 0|\lambda z_M\rangle = e^{\lambda^2 S_M}.
\end{align}
$S_M$ can be found by using the iteration relation:
\begin{align}
S_M = \psi_L B(s_M) \cdots B(s_2)B(s_1)\psi_R;\quad 
\psi_L =  \begin{pmatrix}
1 & 0 & 0
\end{pmatrix};\quad
\psi_R = \begin{pmatrix}
0 \\
0 \\
1
\end{pmatrix}.
\end{align}
We see that $S_M$ is expressed in matrix product form; the bond dimension is $N+2$. Note all the entries in $B$ are independent of $\lambda$ thanks to the scaling factor introduced in the definition of $z$ and $S$.

% Holstein
\section{Spectral function of one-dimensional Holstein model}

\begin{figure}
\includegraphics[width = 0.7\columnwidth]{time_domain_holstein.png}
\caption{Top rows: the real (a$\sim$c) and imaginary (d$\sim$f) part of the electron propagator of the one dimensional Holstein model at three representative wave vectors. The parameters are: $\omega_q = \omega_0 = 1$, $\lambda = \sqrt{2}$, and $f_q = 1$. Bottom row: the corresponding spectral function ($g\sim$i). Data for different system sizes $N$ and bond dimensions $\chi$ are shown.}
\label{fig:time_domain_holstein}
\end{figure}

Fig.~\ref{fig:time_domain_holstein} shows the data for the electron propagator $G^R(k,t)$ in the time domain at three representative wave vectors. Note these wave vectors are identical to what are shown in Figure 2c$\sim$e in the main text. Both the real (panels a$\sim$c) and the imaginary parts (panels d$\sim$f) are shown. We find that $G^R(k,t)$ at $k\approx 0$ reaches convergence already at low bond dimension $\chi = 80$ and small system size $N=8$. By contrast, $G^R(k,t)$ at $k\approx \pi/2$ and $k\approx \pi$ exhibit slower rate of convergence. 

An interesting feature of the time domain data is that the data at different times exhibit a relatively uniform rate of convergence with respect to $\chi$. We do observe a moderate difference, though. $G^R(k,t)$ at early time and some late time intervals reaches convergence relatively early (at $\chi = 80$), whereas, for some specific intervals, there is a discernible difference between data at $\chi = 120$ and $\chi = 160$, indicating that the data at these times have not yet reached full convergence but are fairly close to it. 

The nearly uniform convergence for different times is due to the fact that the physical time corresponds to the length direction of the MPS. It proves advantageous for computing spectral functions (panel g$\sim$i). We find that the spectral functions in fact converge much faster than the time domain data. This behavior is expected: the spectral function at low frequencies are insensitive to small, local changes in the time domain data.

\begin{figure}
\includegraphics[width = 0.7\columnwidth]{holstein_1d.png}
\caption{Spectral function of one dimension Holstein model. We set $\omega_q = \omega_0$ and $f_q = 1$. The system size $N = 16$. Maximal bond dimension $\chi = 120$.}
\label{fig:holstein_1d}
\end{figure}

Fig.~\ref{fig:holstein_1d} shows the spectral function of the one-dimensional Holstein model for a few representative parameter sets. We set $\omega_q = \omega_0$ and $f_q = 1$. The system size $N = 16$. The maximal bond dimension $\chi = 120$. The top row (panel a$\sim$c) show the result for $\lambda = 1$ with increasingly softer phonon frequency. The bottom row (panel d$\sim$f) is similar but with stronger coupling constant $\lambda = \sqrt{2}$. The overall trend is that increasing $\lambda$ and/or decreasing $\omega_0$ introduce more satellite peaks, reflecting the fact that the combination $\lambda^2/\omega_0$ controls the effective coupling strength. Interestingly, we find that, for $\omega_0 = 2$, we observe shadow bands with relative small spectral weight between the main bands. We have verified that these are not artifacts. The microscopic origin of these shadow bands are not entirely clear at the moment. 

% dispersive phonons
\section{Spectral function for dispersive model}

\begin{figure}
\includegraphics[width = 0.8\columnwidth]{spectra_dispersive.png}
\caption{Spectral function of one dimension model with dispersive phonons. We set $\omega_q = 1 + 2 t_{ph}\cos q$, $f_q = 1$, and $\lambda = (4-16t^2_{ph})^{1/4}$. The system size $N = 16$. The maximal bond dimension $\chi = 120$. The top row is reproduced from a previous variational calculation~\cite{Bonca2021}, where the bottom row is from this work.}
\label{fig:spectra_dispersive}
\end{figure}

Fig.~\ref{fig:spectra_dispersive} shows the spectral function for a one-dimensional model with dispersive phonons. Following Ref.~\onlinecite{Bonca2021}, we set $\omega_q = 1+2t_{ph}\cos q$, $f_q = 1$, and $\lambda = (4-16t^2_{ph})^{1/4}$. We use a system of $N = 16$ sites. The maximal bond dimension $\chi = 120$. We find that our results agree well with that of Ref.~\onlinecite{Bonca2021}, which uses a variational construction of low-energy eigenstates. Compared with dispersionless phonons ($t_{ph} = 0$), the satellite peaks for the case of dispersive phonons ($t_{ph}=\pm 0.2$) show narrower spacing in energy. This feature reflects the fact that the phonon frequency minimum $\omega_{min} = 1-2|t_{ph}| = 0.6$ is smaller than the dispersionless case. For $t_{ph}=-0.2$ ($t_{ph} = 0.2$), the lowest polaron band bends upward (downward) near the Brillouin zone boundary, mirroring the phonon dispersion.

\begin{figure}
\includegraphics[width = 0.7\columnwidth]{benchmark_dispersive.png}
\caption{Constant $k$-cuts of the spectral function $A(k,\omega)$ for three representative wave vectors $k=0$, $\pi/2$, and $\pi$. The parameter choice is the same as Fig.~\ref{fig:spectra_dispersive}. Both the results from this work (red) and Ref.~\onlinecite{Bonca2021} are shown.}
\label{fig:benchmark_dispersive}
\end{figure}

We carry out a quantitative comparison of our results with that of Ref.~\onlinecite{Bonca2021} in Fig.~\ref{fig:benchmark_dispersive}. We find good agreement between the two methods. We note that the spectral peaks from Ref.~\onlinecite{Bonca2021} have smaller peak width than ours. This difference is due to the different energy resolution. In the former method, a spectral broadening factor is used, whereas, in the latter, the energy resolution is controlled by the maximal time of evolution.

We therefore compare the partially integrated spectral function $\int^\omega_{-\infty} A(k,\omega')d\omega'$. This object is less sensitive to the energy resolution. The steps of the partially integrated spectral function correspond to peaks in $A(k,\omega)$. Fig.~\ref{fig:int_spectra} shows the comparison of the partially integrate spectral function, which shows quantitative agreement between the two methods.

\begin{figure}
\includegraphics[width = 0.7\columnwidth]{int_spectra.png}
\caption{Same as Fig.~\ref{fig:benchmark_dispersive} but for the partially integrated spectral function.}
\label{fig:int_spectra}
\end{figure}

% diffusion
\section{Path integral representation of electron desnsity}

We consider a nonequilibrium diffusion problem. We place an electron at the origin of an initially empty lattice, $|\psi\rangle = c^\dagger_0|0\rangle$. We monitor the ensuing evolution of the electron density:
\begin{align}
\rho(x,t) = \langle 0|c^{\phantom\dagger}_0 e^{iHt} c^\dagger_x c^{\phantom\dagger}_x e^{-iHt} c^{\dagger}_0|0\rangle,
\end{align}
where $H$ is the Hamiltonian Eq.~\eqref{eq:Hamil}. In this section, we derive a path integral representation for $\rho(x,t)$.

First, we trotterize the time evolution and insert the resolution of identity by electron position eigenstates:
\begin{align}
\rho(x,t) = \sum_{\{x^-\}}\sum_{\{x^+\}} \langle x^-_0|e^{i\epsilon K}|x^-_1\rangle\langle x^-_1|e^{i\epsilon K}|x^-_2\rangle \cdots \langle x^-_{M-1}|e^{i\epsilon K}|x^-_M\rangle  
\langle x^+_M|e^{-i\epsilon K}|x^+_{M-1}\rangle \cdots \langle x^+_2|e^{-i\epsilon K}|x^+_1\rangle \langle x^+_1|e^{-i\epsilon K}|x^+_0 \rangle
\nonumber \\
\times
\langle \phi | e^{i\frac{\epsilon}{2}V(x^-_0)} e^{i\epsilon V(x^-_1)} \cdots e^{i\epsilon V(x^-_{M-1})} e^{i\frac{\epsilon}{2}V(x^-_M)}  e^{-i\frac{\epsilon}{2}V(x^+_M)} e^{-i\epsilon V(x^+_{M-1})} \cdots e^{-i\epsilon V(x^+_1)} e^{-i\frac{\epsilon}{2}V(x^+_0)}|\phi \rangle.
\end{align}
Here, $\{x^+\}$ and $\{x^-\}$ label the electron position on the forward and backward branch of the Keldysh contour. We impose the boundary condition $x^\pm_0 = 0$ and $x^\pm_M = x$.  $V(x)$ is the same as Eq.~\eqref{eq:V_x}.

Second, we perform a change of variables from the electron position to the displacements, $s^\pm_j = x^\pm_j - x^\pm_{j-1}$. Using these, we find:
\begin{align}
\rho(x,t) = \sum_{\{s^-\}}\sum_{\{s^+\}} \Delta_x (\{s^-\}) \Delta_x(\{s^+\}) A^\ast_0(\{s^-\} )A_0(\{s^+\}) I(\{s^-\},\{s^+\}).
\end{align}
The functional $\Delta_x$ ensures that the electron reaches $x$ at time $t$:
\begin{align}
\Delta_x(\{s^\pm\}) = \delta(x-\sum^M_{j=1}s^\pm_j).
\end{align}
$A_0$ is the amplitude of a free particle defined in Sec.~\ref{sec:exp}. The amplitude on the forward and backward branches are complex conjugates. $I$ is the phonon influence functional:
\begin{align}
I(\{s^-\},\{s^+\}) = \langle \phi | U^\dagger(s^-_1)U^\dagger (s^-_2)\cdots U^\dagger (s^-_M)U(s^+_M) \cdots  U(s^+_2) U(s^+_1) |\phi \rangle
\nonumber\\
= \langle \phi | U^{-1}(s^-_1)U^{-1} (s^-_2)\cdots U^{-1} (s^-_M)U(s^+_M) \cdots  U(s^+_2) U(s^+_1) |\phi \rangle.
\end{align}
Here, we have used the same trick as the main text, namely using the translation operator to make the dependence on $s$ explicit. $U(s) = e^{-i\frac{\epsilon}{2}V(0)}T(-s)e^{-i\frac{\epsilon}{2}V(0)}$ is the same as before. The second line follows from the unitarity of $U(s)$.

Third, we exponentiate the influence functional. For the time evolution on the forward branch, we use the recursion relation from Sec.~\ref{sec:exp}:
\begin{subequations}
\begin{align}
\begin{pmatrix}
S_{j} \\
z_{j} \\
1
\end{pmatrix} = B(s^+_j) \begin{pmatrix}
S_{j-1} \\
z_{j-1} \\
1
\end{pmatrix}.
\end{align}
For the time evolution on the backward branch, we exploit the fact that $U^{-1}(s^-)$ is the inverse of $U(s)$:
\begin{align}
\begin{pmatrix}
S_{j} \\
z_{j} \\
1
\end{pmatrix} = B^{-1} (s^{-}_j) \begin{pmatrix}
S_{j-1} \\
z_{j-1} \\
1
\end{pmatrix}.
\end{align}
\end{subequations}
The exponentiated form of the influence functional thus reads:
\begin{align}
I(\{s^-\},\{s^+\}) = e^{\lambda^2 S(\{s^-\},\{s^+\})},
\end{align}
with 
\begin{align}
S(\{s^-\},\{s^+\}) = \psi_L B^{-1}(s^-_1)B^{-1}(s^-_2)\cdots B^{-1}(s^-_M) B(s^+_M) \cdots B(s^+_2) B(s^+_1) \psi_R.
\end{align}
The boundary vectors $\psi_L = (1,0,0)$ and $\psi_R = (0,0,1)^T$. 

We therefore obtain the flow equation for the quantum amplitude $A(\{s^-\},\{s^+\}) \equiv I(\{s^-\},\{s^+\}) A_0(\{s^-\},\{s^+\})$:
\begin{align}
\frac{dA(\{s^-\},\{s^+\})}{d\lambda^2} = S(\{s^-\},\{s^+\}) A(\{s^-\},\{s^+\}).
\end{align}
The initial condition is:
\begin{align}
A(\{s^-\},\{s^+\}) = A^\ast_0(\{s^-\}) A_0(\{s^+\}).
\end{align}
Solving the flow equation effects the compression of $A$.

In the final step, we need to contract $A$ with $\Delta$. It is then necessary to recast $\Delta$ in MPS form. Here, we use the translation matrix $T(x)$:
\begin{align}
T(x)|y\rangle = |x+y\rangle,
\end{align}
where $|x\rangle$ is the electro position eigenstate. It is then easy to see:
\begin{align}
\Delta_x(\{s^+\}) = \langle x|T(s^+_M) \cdots T(s^+_2)T(s^+_1)|0\rangle.
\end{align}
The above is an MPS with bond dimension $N$. The MPS expression for $\Delta_x(\{s^-\})$ can be found in the same vein.

