	&d\widetilde{D}^{\pm}_t = \mathbf{1}_{\{ \widetilde{D}^{\pm}_t>0, \widetilde{U}^{\pm}_t>0 \}}\big((r-\mu+\frac{1}{2}V_t) dt - \sqrt{V_t} dB_t \big)  + dL_t^0(\widetilde{D}^\pm),\\
	&d\widetilde{U}^\pm_t = \mathbf{1}_{\{ \widetilde{D}^{\pm}_t>0, \widetilde{U}^{\pm}_t>0 \}}\big((\mu-r-\frac{1}{2}V_t)dt + \sqrt{V_t} dB_t \big)  + d L_t^0(\widetilde{U}^\pm),\\
	&dV_t=\kappa(\theta-V_t)dt+\sigma\sqrt{V_t}dW_t,\\
	&\int_{0}^{t} 1_{\{\widetilde{D}^{\pm}_s = 0\}} ds  =  \xi L_t^0(\widetilde{D}^{\pm}),\\
	&\int_{0}^{t} 1_{\{\widetilde{U}^\pm_s = 0\}} ds  =  \eta L_t^0(\widetilde{U}^\pm).
	\end{cases}	
	\end{align}

Since the Feller condition $2\kappa\theta>\sigma^2$ is satisfied, $V_t>0$. We set $P_t^{\pm}=\frac{\widetilde{U}^\pm_t}{V_t+1}$ and $Q_t^\pm=\frac{\widetilde{D}^{\pm}_t}{V_t+1}$. So
\begin{align}
