\end{align}
Let $\widetilde{P}_t^\pm=\ln (P^\pm_t+1)$, $\widetilde{Q}_t^\pm=\ln (Q^\pm_t+1)$, and $\widetilde{V}_t=\ln (V_t+1)$. Define $f(x)=e^x-1$. Then we have
\begin{align}
    V_t=f(\widetilde{V}_t)>0, \ P^\pm_t=f(\widetilde{P}^{\pm}_t)\ge 0, \ Q^\pm_t=f(\widetilde{Q}^{\pm}_t)\ge 0.
\end{align}

