    &\quad\quad \quad \ -\Big(\frac{\sqrt{f(\widetilde{V}_t)}}{(f(\widetilde{Q}_t^\pm)+1)(f(\widetilde{V}_t)+1)}+\frac{\sigma f(\widetilde{Q}_t^\pm)\sqrt{f(\widetilde{V}_t)}\rho}{(f(\widetilde{Q}_t^\pm)+1)(f(\widetilde{V}_t)+1)}\Big)dB_t\bigg)\\
    &\quad\quad \quad \ + \mathbf{1}_{\{\boldsymbol{X}_t\in \partial \mathbb{S}\}}\mathbf{1}_{\{\widetilde{Q}_t^\pm=0\}}\frac{1}{(f(\widetilde{V}_t)+1)\xi}dt,\\
    &d\widetilde{P}_t^\pm= \mathbf{1}_{\{\boldsymbol{X}_t\in \mathbb{S}\}}\bigg(\Big(\frac{-\kappa(\theta-f(\widetilde{V_t}))f(\widetilde{P}^{\pm}_t)+\mu-r-\frac{1}{2}f(\widetilde{V}_t)}{(f(\widetilde{V_t})+1)(f(\widetilde{P}^{\pm}_t)+1)}+\frac{\sigma^2f(\widetilde{V}_t)f(\widetilde{P}^{\pm}_t)-\sigma\rho f(\widetilde{V}_t)}{(f(\widetilde{V}_t)+1)^2(f(\widetilde{P}^{\pm}_t)+1)}\\
    &\quad\quad \quad \  +\frac{-\sigma^2f(\widetilde{P}^{\pm}_t)^2f(\widetilde{V}_t)-f(\widetilde{V}_t)+2\rho\sigma f(\widetilde{P}^{\pm}_t)f(\widetilde{V}_t)}{(f(\widetilde{P}^{\pm}_t)+1)^2(f(\widetilde{V}_t)+1)^2}\Big)dt-\frac{\sigma f(\widetilde{P}^{\pm}_t)\sqrt{f(\widetilde{V}_t)}\sqrt{1-\rho^2}}{(f(\widetilde{P}^{\pm}_t)+1)(f(\widetilde{V}_t)+1)}d\bar{B}_t\\
    &\quad\quad \quad \  +\Big(\frac{\sqrt{f(\widetilde{V}_t)}}{(f(\widetilde{P}^{\pm}_t)+1)(f(\widetilde{V}_t)+1)}-\frac{\sigma f(\widetilde{P}^{\pm}_t)\sqrt{f(\widetilde{V}_t)}\rho}{(f(\widetilde{P}^{\pm}_t)+1)(f(\widetilde{V}_t)+1)}\Big)dB_t\bigg)\\
    &\quad\quad \quad \ +\mathbf{1}_{\{\boldsymbol{X}_t\in \partial \mathbb{S}\}}\mathbf{1}_{\{\widetilde{P}^{\pm}_t=0\}} \frac{1}{(f(\widetilde{V}_t)+1)\eta}dt,\\
	&d\widetilde{V}_t=\mathbf{1}_{\{\boldsymbol{X}_t\in \mathbb{S}\}}\bigg(\Big(\frac{\kappa(\theta-f(\widetilde{V_t}))}{f(\widetilde{V_t})+1}-\frac{\sigma^2f(\widetilde{V_t})}{(f(\widetilde{V_t})+1)^2}  \Big)dt+\frac{\sigma\rho\sqrt{f(\widetilde{V_t})}}{f(\widetilde{V_t})+1}dB_t+\frac{\sigma\sqrt{1-\rho^2}\sqrt{f(\widetilde{V_t})}}{f(\widetilde{V_t})+1}d\bar{B}_t\bigg)\\
    &\quad\quad \ \ +\mathbf{1}_{\{\boldsymbol{X}_t\in \partial \mathbb{S}\}}\bigg(\Big(\frac{\kappa(\theta-f(\widetilde{V_t}))}{f(\widetilde{V_t})+1}-\frac{\sigma^2f(\widetilde{V_t})}{(f(\widetilde{V_t})+1)^2}  \Big)dt+\frac{\sigma\rho\sqrt{f(\widetilde{V_t})}}{f(\widetilde{V_t})+1}dB_t+\frac{\sigma\sqrt{1-\rho^2}\sqrt{f(\widetilde{V_t})}}{f(\widetilde{V_t})+1}d\bar{B}_t\bigg),\\
