The SDE \eqref{eq:final-sticky-process-SDE} can be formulated as
\begin{align}\label{eq:multidimensional-SDE-formulation}
	d \boldsymbol{X}_t= & \boldsymbol{\mu}\left(\boldsymbol{X}_t\right) \mathbf{1}\left(\boldsymbol{X}_t \in \mathbb{S}\right) d t+\boldsymbol{\Sigma}\left(\boldsymbol{X}_t\right) \mathbf{1}\left(\boldsymbol{X}_t \in \mathbb{S}\right) d \mathbf{B}_{1, t} \\ & +\hat{\boldsymbol{\beta}}\left(\boldsymbol{X}_t\right) \mathbf{1}\left(\boldsymbol{X}_t \in \partial \mathbb{S}\right) d t+\hat{\boldsymbol{\Gamma}}\left(\boldsymbol{X}_t\right) \mathbf{1}\left(\boldsymbol{X}_t \in \partial \mathbb{S}\right) d \boldsymbol{B}_{2, t} 
\end{align}
with the following sojourn condition
\begin{align}
    \mathbf{1}_{\{\boldsymbol{X}_t\in \partial \mathbb{S}\}}dt=\rho (\boldsymbol{X}_t)dL_t,
\end{align}
where $L$ is the local time process of $\boldsymbol{X}$ on the boundary. In \eqref{eq:multidimensional-SDE-formulation}, 
\begin{align}
\boldsymbol{\mu}\left(\boldsymbol{X}_t\right)=\left[\begin{array}{c}\frac{r-\mu-\frac{1}{2}f(\widetilde{V}_t)-f(\widetilde{Q}^{\pm}_t)\kappa(\theta-f(\widetilde{V}_t))}{(f(\widetilde{Q}_t^\pm)+1)(f(\widetilde{V}_t)+1)}+\frac{\sigma\rho f(\widetilde{V}_t)+\sigma^2 f(\widetilde{Q}_t^\pm)f(\widetilde{V}_t)}{(f(\widetilde{Q}_t^\pm)+1)(f(\widetilde{V}_t)+1)^2}- \frac{\sigma^2f(\widetilde{Q}_t^\pm)^2f(\widetilde{V}_t)+f(\widetilde{V}_t)+2\sigma\rho f(\widetilde{Q}_t^\pm)f(\widetilde{V}_t)}{(f(\widetilde{Q}_t^\pm)+1)^2(f(\widetilde{V}_t)+1)^2} \\ \frac{-\kappa(\theta-f(\widetilde{V_t}))f(\widetilde{P}^{\pm}_t)+\mu-r-\frac{1}{2}f(\widetilde{V}_t)}{(f(\widetilde{V_t})+1)(f(\widetilde{P}^{\pm}_t)+1)}+\frac{\sigma^2f(\widetilde{V}_t)f(\widetilde{P}^{\pm}_t)-\sigma\rho f(\widetilde{V}_t)}{(f(\widetilde{V}_t)+1)^2(f(\widetilde{P}^{\pm}_t)+1)} +\frac{-\sigma^2f(\widetilde{P}^{\pm}_t)^2f(\widetilde{V}_t)-f(\widetilde{V}_t)+2\rho\sigma f(\widetilde{P}^{\pm}_t)f(\widetilde{V}_t)}{(f(\widetilde{P}^{\pm}_t)+1)^2(f(\widetilde{V}_t)+1)^2} \\ \frac{\kappa(\theta-f(\widetilde{V_t}))}{f(\widetilde{V_t})+1}-\frac{\sigma^2f(\widetilde{V_t})}{(f(\widetilde{V_t})+1)^2}  \end{array}\right],
\end{align}
\begin{align}
\boldsymbol{\Sigma}\left(\boldsymbol{X}_t\right)=\left[\begin{array}{ccc}-\frac{\sigma f(\widetilde{Q}_t^\pm)\sqrt{f(\widetilde{V}_t)}\sqrt{1-\rho^2}}{(f(\widetilde{Q}_t^\pm)+1)(f(\widetilde{V}_t)+1)} & -\Big(\frac{\sqrt{f(\widetilde{V}_t)}}{(f(\widetilde{Q}_t^\pm)+1)(f(\widetilde{V}_t)+1)}+\frac{\sigma f(\widetilde{Q}_t^\pm)\sqrt{f(\widetilde{V}_t)}\rho}{(f(\widetilde{Q}_t^\pm)+1)(f(\widetilde{V}_t)+1)}\Big) & 0 \\ -\frac{\sigma f(\widetilde{P}^{\pm}_t)\sqrt{f(\widetilde{V}_t)}\sqrt{1-\rho^2}}{(f(\widetilde{P}^{\pm}_t)+1)(f(\widetilde{V}_t)+1)} & +\Big(\frac{\sqrt{f(\widetilde{V}_t)}}{(f(\widetilde{P}^{\pm}_t)+1)(f(\widetilde{V}_t)+1)}-\frac{\sigma f(\widetilde{P}^{\pm}_t)\sqrt{f(\widetilde{V}_t)}\rho}{(f(\widetilde{P}^{\pm}_t)+1)(f(\widetilde{V}_t)+1)}\Big) & 0 \\ \frac{\sigma\sqrt{1-\rho^2}\sqrt{f(\widetilde{V_t})}}{f(\widetilde{V_t})+1} & \frac{\sigma\rho\sqrt{f(\widetilde{V_t})}}{f(\widetilde{V_t})+1} & 0 \end{array}\right],
\end{align}
\begin{align}
\hat{\boldsymbol{\beta}}\left(\boldsymbol{X}_t\right)=\left[\begin{array}{c}
     \mathbf{1}_{\{\widetilde{Q}_t^\pm=0\}}\frac{1}{(f(\widetilde{V}_t)+1)\xi}\\
     \mathbf{1}_{\{\widetilde{P}^{\pm}_t=0\}} \frac{1}{(f(\widetilde{V}_t)+1)\eta}\\
     \frac{\kappa(\theta-f(\widetilde{V_t}))}{f(\widetilde{V_t})+1}-\frac{\sigma^2f(\widetilde{V_t})}{(f(\widetilde{V_t})+1)^2} 
\end{array}\right],
\end{align}
\begin{align}
    \hat{\boldsymbol{\Gamma}}\left(\boldsymbol{X}_t\right)=\left[\begin{array}{ccc} 0 & 0& 0\\
    0 & 0& 0 \\
    \frac{\sigma\sqrt{1-\rho^2}\sqrt{f(\widetilde{V_t})}}{f(\widetilde{V_t})+1} & \frac{\sigma\rho\sqrt{f(\widetilde{V_t})}}{f(\widetilde{V_t})+1} & 0
    \end{array}\right].
\end{align}

Let $\boldsymbol{n}(\boldsymbol{x})$ be the unit normal vector at the boundary point $\boldsymbol{x}$ pointing inwards, which is given by $\boldsymbol{n}(\boldsymbol{x})=\nabla \Phi(\boldsymbol{x})/|\nabla \Phi(\boldsymbol{x})|$. Since $\boldsymbol{\mu}(\boldsymbol{x})$ and $\boldsymbol{\Sigma}(\boldsymbol{x})$ are continuous and bounded; $\hat{\boldsymbol{\beta}}(\boldsymbol{x})\rho(\boldsymbol{x})$ and $\hat{\boldsymbol{\Gamma}}(\boldsymbol{x})\sqrt{\rho(\boldsymbol{x})}$ are continuous and bounded on $\partial\mathbb{S}$; and there exists some constant $C>0$ such that $(\hat{\boldsymbol{\beta}}(\boldsymbol{x})\rho(\boldsymbol{x}))^\top\boldsymbol{n}(\boldsymbol{x})+\rho(\boldsymbol{x})>C$, then there exists at least one solution to SDE system \eqref{eq:final-sticky-process-SDE} as implied by Theorems I.14 in \cite{graham1988martingale}. Consequently the solution to SDE system \eqref{eq:sticky-process-SDE} can be obtained by 
\begin{align}
\begin{cases}
    &D_t^\pm=\exp(-\exp(\widetilde{V}_t)(\exp(\widetilde{Q}_t^\pm)-1)),\\
    &U_t^\pm=\exp(\exp(\widetilde{V}_t)(\exp(\widetilde{P}_t^\pm)-1)), \\
    &V_t=\exp(\widetilde{V}_t)-1.
    \end{cases}
\end{align}
So the Theorem \ref{thm:existence-weak-sol-SDE} is proved.

\end{proof}

