\begin{align}  d\left(e^{-r t} P(t, x, y, z, v;\Phi)\right)   =& -r e^{-r t} P(t, x, y, z, v;\Phi) d t+e^{-r t} d P(t, x, y, z, v;\Phi) \\ = & e^{-r t}\left[-r P d t+P_x d S_t^{ \pm}+P_y d \bar{S}_t^{ \pm}+P_z d \underline{S}_t^{ \pm}+P_t d t+P_v d V_t\right. \\  &\left.+ \frac{1}{2} P_{x x} d\left\langle S^{ \pm}, S^{ \pm}\right \rangle_t+\frac{1}{2} P_{v v} d\left\langle V, V\right \rangle_t+ P_{x v} d\left\langle S^{ \pm}, V\right \rangle_t \right] \\  = & e^{-r t}\left[-r P d t+P_x\left(r x d t+\sqrt{v} x 1_{\{x \neq\{y, z\}\}} d B_t\right)\right. \\ & +P_y\left(r y d t+y d L_t^{1}\left(D^{ \pm}\right)\right)+P_z\left(r z d t-z d L_t^{1}\left(U^{ \pm}\right)\right) \\ & +P_t d t+P_v\left[k_v(\theta-v) d t+\sigma \sqrt{v} d W_t\right] \\ & +\frac{1}{2} P_{x x} v x^2 1_{\{x \neq\{y, z\}\}} d t+\frac{1}{2} P_{v v} \sigma^2 v d t +P_{x v} \sigma v x \rho 1_{\{x \neq\{y, z\}\}} d t \\ = & e^{-r t}\left\{\left[-r P+r x P_x+r y P_y+r z P_z+P_t+k_v(\theta-v) P_v+\frac{1}{2} P_{x x} v x^2\right.\right. \\ & \left.+\frac{1}{2} \sigma^2 v P_{v v}+\sigma v x \rho P_{x v}\right] d t \\ & +\left(P_y y d L_t^{1}\left(D^{ \pm}\right)-\frac{1}{2} P_{x x} v x^2 1_{\{x=y\}} d t-\sigma v x \rho P_{x v} 1_{\{x=y\}} d t\right) \\ & +\left(-P_z z d L_t^{1}\left(U^{ \pm}\right)-\frac{1}{2} P_{x x} v x^2 1\{x=z\} d t -\sigma v x \rho P_{x v} 1_{\{x=z\}} d t\right) \\ & \left.+P_x \sqrt{v} x 1_{\{x \neq\{y, z\}\}} d B_t+P_v \sigma \sqrt{v} d W_t\right\} \\  = & e^{-r t}\left\{\left[-r p+r x P_x+r y P_y+r z P_z+P_t+k_v(\theta-v) P_v+\frac{1}{2} P_{x x} v x^2\right.\right. \\ & \left.+\frac{1}{2} \sigma^2 v P_{v v}+\sigma v x \rho P_{x v}\right] d t \\ & +\left(P_y y d L_t^{1}\left(D^{ \pm}\right)-\frac{1}{2} P_{x x} v y^2 k_s d L_t^{1}\left(D^{ \pm}\right)-\sigma v y \rho P_{x v} k_s d L_t^{1}\left(D^{ \pm}\right)\right) \\ & +\left(-P_z z d L_t^{1}\left(U^{ \pm}\right)-\frac{1}{2} P_{x x} v z^2 \eta d L_t^{1}\left(U^{ \pm}\right)-\sigma v z \rho P_{x v} \eta d L_t^{1}\left(U^{ \pm}\right)\right) \\ & \left.+P_x \sqrt{v} x 1_{\{x \neq\{y, z\}\}} d B_t+P_v \sigma \sqrt{v} d W_t\right\} \\ & \end{align}

For the function $P(t,x,y,z,v;\Phi)\in \mathbf{C}^2$, $e^{-rt}P(t,x,y,z,v;\Phi)$ is a local martingale. Then, for $0\leq t<T$, $0\leq z<x<y$, $P(t,x,y,z,v;\Phi)$ satisfies the PDE
