\section{Calibration Algorithm}
\label{app-cali}
\begin{algorithm}[H]
  \caption{Deep Levenberg–Marquardt Calibration Algorithm}
  \begin{algorithmic}[1]
      \State Initialize values for parameter set $\phi$, and the Levenberg–Marquardt parameters $\lambda$, $\lambda_{down}$ and $\lambda_{up}$. Obtain the scaling factor $l_d$, underlying asset prices, strike prices and maturities. 
      \State Evaluate the root mean square error, $r\gets \sqrt{\frac{\sum_{i=1}^{N_d}(P^{\theta}_i-P^{MKT}_i)^2}{N_d}}$, and the Jacobian, $J\gets \frac{\partial P^{\theta}}{\partial \phi}$, at the initial parameter guess.

      \State $t$ $\gets$ 1, $rmse\gets 0$, $iter\gets 0$
      \While{$t\le 10000$}
        \State $g\gets J^\intercal J+\lambda I$, $\triangledown C\gets J^\intercal r$
        \State $\phi_{new}\gets \phi-g^{-1}\triangledown C$
        \State Check if the parameters in $\phi_{new}$ are within an appropriate range
        \State Evaluate root mean square error $r_{new}$ with $\phi_{new}$
        \If{$r_{new}<r$}
        \State $\phi\gets \phi_{new}$, $r\gets r_{new}$, $\lambda\gets \lambda/\lambda_{down}$, $iter\gets 0$
        \If{$|r_{new}-rmse|<10^{-10}$}
        \State \textbf{break}
        \EndIf
        \Else
        \State $\lambda=\lambda\times \lambda_{up}$
        \State $iter=iter+1$
        \If{$iter>20$}
        \State \textbf{break}
        \EndIf
      \EndIf
      \State $rmse\gets r$
      \State $t\gets t+1$
      \EndWhile


  \end{algorithmic}
\end{algorithm}


\section{Sticky Drawdown Stochastic Volatility model and Sticky Drawup Stochastic Volatility model}
\label{app-SVSDSVSU}

The SVSD model follows the SDE:
\[
\left\{\begin{array}{l}d D_t^{ \pm}=1_{\left\{D_t^{ \pm} \neq 1 \right\}} \sqrt{V_t} D_t^{ \pm} d B_t-D_t^{ \pm} d L_t^1\left(D^{ \pm}\right), \\ d V_t=\kappa\left(\theta-V_t\right) d t+\sigma \sqrt{V_t} d W_t, \\ \int_0^t 1_{\left\{D_s^{ \pm}=1\right\}} d s=\xi L_t^1\left(D^{ \pm}\right).\end{array}\right.
\]

$$
\begin{aligned}
& \left\{\begin{array}{l}
d S_t^{ \pm}=r S_t^{ \pm} d t+\sqrt{V_t} S_t^{ \pm} \mathbf{1}_{\left\{S_t^{ \pm} \neq\bar{S}_t^{ \pm} \right\}} d B_t, \\
d V_t=\kappa\left(\theta-V_t\right) d t+\sigma \sqrt{V_t} d W_t \\
\int_0^t 1_{\left\{S_t^{ \pm}=\bar{S}_t^{ \pm}\right\}} d s=\xi L_t^1\left(D^{ \pm}\right) \\
d \bar{S}_t^{ \pm}=r \bar{S}_t^{ \pm} d t+\bar{S}_t^{ \pm} d L_t^1\left(D^{ \pm}\right) .
\end{array}\right. \\
&
\end{aligned}
$$
By Feynman-Kac Theorem, we have the pricing PDE:
\begin{align}
	\begin{array}{l}
	\frac{1}{2} v x^2 P_{x x}+\rho \sigma v x P_{x v}+\frac{1}{2} \sigma^2 v P_{v v}+r x P_x \\
	+\kappa(\theta-v) P_v+r y P_y+P_t=r P,
	\end{array}
\end{align}
where $0\le t<T$ and $0<x<y$. The boundary is at $x = y$:
\begin{align}
	\begin{array}{l}
	P_y(t,y,y,v;\Phi)=\left[\frac{1}{2} v y P_{x x}(t,y,y,v;\Phi)+\rho \sigma v P_{x v}(t,y,y,v;\Phi)\right] \xi. 
	\end{array}
\end{align}
The terminal condition is
\begin{align}
	P(T, x, y, v;\Phi) = (x-K)^+, 
\end{align}
where $0< x\le y$.


The SVSU model is defined by:
\[
\left\{\begin{array}{l} d U_t^{ \pm}=1_{\left\{U_t^{ \pm} \neq 1\right\}} \sqrt{V_t} U_t^{ \pm} d B_t+U_t^{ \pm} d L_t^1\left(U^{ \pm}\right), \\ d V_t=\kappa\left(\theta-V_t\right) d t+\sigma \sqrt{V_t} d W_t, \\   \int_0^t 1_{\left\{U_s^{ \pm}=1\right\}} d s=\eta L_t^1\left(U^{ \pm}\right) .\end{array}\right.
\]
$$
\begin{aligned}
& \left\{\begin{array}{l}
d S_t^{ \pm}=r S_t^{ \pm} d t+\sqrt{V_t} S_t^{ \pm} \mathbf{1}_{\left\{S_t^{ \pm} \neq\underline{S}_t^{ \pm}\right\}} d B_t, \\
d V_t=\kappa\left(\theta-V_t\right) d t+\sigma \sqrt{V_t} d W_t \\
\int_0^t \mathbf{1}_{\left\{S_t^{ \pm}=\underline{S}_t^{ \pm}\right\}} d s=\eta L_t^1\left(U^{ \pm}\right) \\
d \underline{S}_t^{ \pm}=r \underline{S}_t^{ \pm} d t-\underline{S}_t^{ \pm} d L_t^1\left(U^{ \pm}\right) .
\end{array}\right. \\
&
\end{aligned}
$$
By Feynman-Kac Theorem, we have the pricing PDE: 
\begin{align}
	\begin{array}{l}
	\frac{1}{2} v x^2 P_{x x}+\rho \sigma v x P_{x v}+\frac{1}{2} \sigma^2 v P_{v v}+r x P_x \\
	+\kappa(\theta-v) P_v+r z P_z+P_t=r P,
	\end{array}
\end{align}
where $0\le t<T$ and $0< z<x$. The boundary is at $x=z$:
\begin{align}
	\begin{array}{l}
	P_z(t,z,z,v;\Phi)=-\left[\frac{1}{2} v z P_{x x}(t,z,z,v;\Phi)+\rho \sigma v P_{x v}(t,z,z,v;\Phi)\right] \eta.
	\end{array}
\end{align}
The terminal condition is
\begin{align}
	P(T, x, z, v;\Phi) = (x-K)^+,
\end{align}
where $0< z\le x$.




