\begin{definition}[N-dimensional Vector of Reals]\label{def:Nd_Vector}
An $N$-dimensional vector of reals, denoted $\RVector(n)$ in our Lean formalization, is a function from $\Fin(n)$ to $\R$, where $\Fin(n)$ represents the finite set $\{0, 1, \dots, n-1\}$. This corresponds to the standard $\R^n$ but uses a function representation that facilitates formal reasoning in Lean.
\end{definition}
\begin{example}
If $n=3$, a vector $x \in \RVector(3)$ could be $x = (x_0, x_1, x_2)$, where $x(0)=x_0, x(1)=x_1, x(2)=x_2$. For instance, $v = (1.0, 2.5, -0.5)$ is in $\RVector(3)$.
\end{example}

\begin{definition}[Vector Relations]\label{def:vector relations}
Let $x, y \in \RVector(n)$.
\begin{itemize}
    \item \textbf{Componentwise less than ($<$)}: $x < y \iff \forall i \in \Fin(n), x(i) < y(i)$.
    \item \textbf{Componentwise less than or equal ($\leq$)}: $x \leq y \iff \forall i \in \Fin(n), x(i) \leq y(i)$.
    \item \textbf{Componentwise strictly greater than ($\allGt$)}: $\allGt(x, y) \iff \forall i \in \Fin(n), x(i) > y(i)$. (This is equivalent to $y < x$).
\end{itemize}
\end{definition}
\begin{example}
Let $x=(1,2), y=(3,4), z=(1,5) \in \RVector(2)$.
Then $x < y$ since $1<3$ and $2<4$.
However, $x \not< z$ because $x(0) \not< z(0)$ (i.e., $1 \not< 1$). But $x \leq z$ holds.
$\allGt(y,x)$ is true since $y(0)>x(0)$ and $y(1)>x(1)$.
\end{example}

\begin{definition}[N-dimensional Rectangles]\label{def:N-dimensional Rectangles}
Let $a, b \in \RVector(n)$.
\begin{itemize}
    \item \textbf{Closed N-dimensional Rectangle ($\Iccn$)}:
    $\Iccn(a,b) := \{x \in \RVector(n) \mid a \leq x \land x \leq b \}$.
    This means for all $i \in \Fin(n)$, $a(i) \leq x(i) \leq b(i)$. This represents the hyperrectangle $[a_0, b_0] \times \dots \times [a_{n-1}, b_{n-1}]$.
    \item \textbf{Open N-dimensional Rectangle ($\Ioon$)}:
    $\Ioon(a,b) := \{x \in \RVector(n) \mid a < x \land x < b \}$.
    This means for all $i \in \Fin(n)$, $a(i) < x(i) < b(i)$. This represents the hyperrectangle $(a_0, b_0) \times \dots \times (a_{n-1}, b_{n-1})$.
\end{itemize}
\end{definition}
\begin{example}
If $n=2$, $a=(0,0)$, $b=(1,2)$.
$\Iccn(a,b) = \{ (x_0, x_1) \mid 0 \leq x_0 \leq 1 \land 0 \leq x_1 \leq 2 \}$.
$\Ioon(a,b) = \{ (x_0, x_1) \mid 0 < x_0 < 1 \land 0 < x_1 < 2 \}$.
The point $(0.5, 1.5)$ is in $\Ioon(a,b)$ and $\Iccn(a,b)$. The point $(1,1)$ is in $\Iccn(a,b)$ but not $\Ioon(a,b)$.
\end{example}

\begin{definition}[Special Vector Constructions]\label{def:Special Vector Constructions}
Let $x_0, b, x \in \RVector(n)$, $s \subseteq \Fin(n)$ be a finite set of indices (formalized as \lean{Finset (Fin n)} in Lean), $j \in \Fin(n)$, and $\text{val} \in \R$.
\begin{itemize}
    \item \textbf{Mixed Vector ($\mixedVec$)}: $\mixedVec(x_0, b, s)$ is a vector where components at indices in $s$ are taken from $x_0$, and components at indices not in $s$ are taken from $b$.
    \[ (\mixedVec(x_0, b, s))(i) = \begin{cases} x_0(i) & \text{if } i \in s \\ b(i) & \text{if } i \notin s \end{cases} \]
    This construction is fundamental for defining the $N$-dimensional survival probability using the principle of inclusion-exclusion, as it allows us to specify points at the "corners" of orthants.
    \item \textbf{Replace Component ($\text{replace}$)}: $\text{replace}(x, j, \text{val})$ is a vector identical to $x$ except that its $j$-th component is replaced by $\text{val}$.
    \[ (\text{replace}(x, j, \text{val}))(i) = \begin{cases} \text{val} & \text{if } i = j \\ x(i) & \text{if } i \neq j \end{cases} \]
    This is a standard utility in vector manipulations.
    \item \textbf{Midpoint Vector ($\text{midpoint}$)}: $(\text{midpoint}(x,y))(i) = (x(i) + y(i))/2$ for all $i \in \Fin(n)$. This is a non-computable definition in Lean due to real division not being computable, but it serves as a useful theoretical construct for our proofs.
\end{itemize}
\end{definition}
\begin{example}[Mixed Vector]
Let $n=3$, $x_0 = (1,2,3)$, $b=(10,11,12)$. Let $s = \{0, 2\} \subseteq \Fin(3)$.
Then $\mixedVec(x_0, b, s)$ will take $x_0(0)$ and $x_0(2)$ and $b(1)$:
$(\mixedVec(x_0, b, s))(0) = x_0(0) = 1$
$(\mixedVec(x_0, b, s))(1) = b(1) = 11$
$(\mixedVec(x_0, b, s))(2) = x_0(2) = 3$
So, $\mixedVec(x_0, b, s) = (1, 11, 3)$.
\end{example}

\begin{definition}[Indicator Function for Upper-Right Orthant]\label{def:indicatorURO_ND}
The function $\indicatorURO : \RVector(n) \to \RVector(n) \to \R$ is defined as:
\[ \indicatorURO(x_0, x) := \begin{cases} 1 & \text{if } \allGt(x, x_0) \\ 0 & \text{otherwise} \end{cases} \]
This function is pivotal: it identifies whether a point $x$ strictly "dominates" a threshold point $x_0$ in all dimensions. The utility function $u(x) = \indicatorURO(x_0, x)$ represents a preference for outcomes that exceed threshold $x_0$ in every dimension, reflecting an economically meaningful preference structure.
\end{definition}
\begin{example}
Let $n=2$, $x_0 = (1,1)$.
If $x=(2,3)$, then $\allGt(x,x_0)$ is true (since $2>1$ and $3>1$), so $\indicatorURO(x_0, x) = 1$.
If $x=(0,4)$, then $\allGt(x,x_0)$ is false (since $0 \not> 1$), so $\indicatorURO(x_0, x) = 0$.
If $x=(2,1)$, then $\allGt(x,x_0)$ is false (since $1 \not> 1$), so $\indicatorURO(x_0, x) = 0$.
\end{example}

\begin{definition}[$N$-dimensional Survival Probability]\label{def:survivalProbN_ND}
The survival probability, denoted $\survivalProbN(\text{Dist}, x_0, b)$, for a joint distribution function $\text{Dist}: \RVector(n) \to \R$ (where $\text{Dist}(x) = P(X_0 \leq x_0, \dots, X_{n-1} \leq x_{n-1})$), threshold vector $x_0 \in \RVector(n)$, and upper bound vector $b \in \RVector(n)$, is defined as:

\[ \survivalProbN(\text{Dist}, x_0, b) := 1 - \sum_{s \in \mathcal{P}(\Fin(n)) \setminus \{\emptyset\}} (-1)^{|s|+1} \cdot \text{Dist}(\mixedVec(x_0, b, s)), \]
where $\mathcal{P}(\Fin(n))$ is the power set of indices $\Fin(n)$, and $\mixedVec(x_0, b, s)$ constructs a vector whose components at indices in $s$ are taken from $x_0$ and components at indices not in $s$ are taken from $b$.

This formula computes the probability that all components of a random vector $X$ exceed their respective thresholds in $x_0$:

\[ P(X > x_0) = P(X_0 > x_0(0), \dots, X_{n-1} > x_0(n-1)). \]

Using the principle of inclusion-exclusion, this can be equivalently expressed as:

\[ \survivalProbN(\text{Dist}, x_0, b) := \sum_{s \subseteq \Fin(n)} (-1)^{|s|} \cdot \text{Dist}(\mixedVec(x_0, b, s)). \]
\end{definition}
\begin{remark}[Formalization Note on $\survivalProbN$]
The definition of $\survivalProbN$ uses \lean{Finset.powerset} and \lean{Finset.sum} from Lean. The vector $b$ plays the role of the "upper anchor" for the probability calculation. For a standard CDF $F$ in two dimensions, with $b=(b_0,b_1)$ where $b_i$ represent upper bounds of the support:

Our $\mixedVec(x_0, b, s)$ constructs the arguments for $F$. For $s=\{0\}$, $\mixedVec(x_0,b,\{0\})=(x_{0,0}, b_1)$. For $s=\{1\}$, $\mixedVec(x_0,b,\{1\})=(b_0, x_{0,1})$. For $s=\{0,1\}$, $\mixedVec(x_0,b,\{0,1\})=(x_{0,0},x_{0,1})$.

The sum is:
$(-1)^{1+1} F(x_{0,0}, b_1) + (-1)^{1+1} F(b_0, x_{0,1}) + (-1)^{2+1} F(x_{0,0}, x_{0,1})$.
So $\survivalProbN = 1 - (F(x_{0,0},b_1) + F(b_0,x_{0,1}) - F(x_{0,0},x_{0,1}))$. This is indeed the standard formula for $P(X_0 > x_{0,0}, X_1 > x_{0,1})$.
This combinatorial definition is highly amenable to formal proof, as it relies on set theory and algebraic manipulation rather than analytic limits or measure theory for its basic properties.
\end{remark}

\begin{definition}[$N$-dimensional Riemann-Stieltjes Integral for Orthant Indicators]\label{def:riemannStieltjesND_ND}
The specialized Riemann-Stieltjes integral $\riemannStieltjesND(u, \text{Dist}, a, b, x_0, h_{x_0}, h_u)$ is defined for a function $u: \RVector(n) \to \R$, a distribution $\text{Dist}$, vectors $a, b, x_0 \in \RVector(n)$, a proof $h_{x_0}$ that $x_0 \in \Iccn(a,b)$, and a proof $h_u$ that $u(x) = \indicatorURO(x_0, x)$ for all $x \in \Ioon(a,b)$.
It evaluates to:
\[ \begin{cases} \survivalProbN(\text{Dist}, x_0, b) & \text{if } \exists x_0' \in \Iccn(a,b) \text{ s.t. } \forall x \in \Ioon(a,b), u(x) = \indicatorURO(x_0',x) \\ 0 & \text{otherwise} \end{cases} \]
The condition uses \Lean{Classical.propDecidable}. The definition in Lean directly uses $x_0$ from the arguments if the condition (checked via $h_u$ and $h_{x_0}$) holds.
\end{definition}

\begin{remark}[Verification Perspective]
Similar to the 1D case, this definition is tailored. The hypotheses $h_{x_0}$ and $h_u$ ensure that the function $u$ indeed corresponds to an orthant indicator defined by $x_0$ within the relevant domain. The definition takes advantage of the uniqueness of such $x_0$ (established in Lemma \ref{lem:uniqueness_ND}) to avoid unnecessary non-constructive operations when the threshold parameter $x_0$ is already known. This design enhances both the logical clarity and the tractability of subsequent proofs.
\end{remark}

\section{Key Theorems for $N$-Dimensional Geometric FSD}\label{sec:theorems_nd}
\subsection{Main Results}
The geometric framework allows for clear and formally verifiable statements about $N$-dimensional FSD, building upon the definitions above.

\begin{lemma}(Subset Relation between Rectangles)\label{lem:Ioo_subset_Icc_self_n}
For any $a, b \in \RVector(n)$, $\Ioon(a,b) \subseteq \Iccn(a,b)$.
\end{lemma}
\begin{proof}
Formal proof sketch provided in Appendix \ref{proof:lem:Ioo_subset_Icc_self_n}. This follows directly from $x < y \implies x \leq y$ applied componentwise.
\end{proof}
\begin{remark}[Formalization Note]
This is a foundational geometric property, easily proven in Lean by applying the definition of subset and vector relations. It's used frequently to ensure that points in an open rectangle are also contained in the corresponding closed rectangle, facilitating necessary type coercions in our proofs.
\end{remark}

\begin{lemma}[Uniqueness of Indicator Function Parameter ($N$D)]\label{lem:uniqueness_ND}
Let $a, b, x_1, x_2 \in \RVector(n)$ such that $\forall i, a(i) < b(i)$ (ensuring $\Ioon(a,b)$ is non-empty and $n$-dimensional).
Let $x_1 \in \Ioon(a,b)$ and $x_2 \in \Ioon(a,b)$. If for all $x \in \Ioon(a,b)$,
 $$ \indicatorURO(x_1, x) = \indicatorURO(x_2, x),$$
then $x_1 = x_2$.
\end{lemma}
\begin{proof}
Formal proof sketch provided in Appendix \ref{proof:lem:uniqueness_nd}. The proof is by contradiction. If $x_1 \neq x_2$, then they must differ in at least one component, say $x_1(j) \neq x_2(j)$. Assuming without loss of generality that $x_1(j) < x_2(j)$, we construct a point $z \in \Ioon(a,b)$ such that $x_1(j) < z(j) < x_2(j)$ and $z(i) > \max(x_1(i), x_2(i))$ for all $i \neq j$. This point $z$ satisfies $\allGt(z, x_1)$ but not $\allGt(z, x_2)$, so $\indicatorURO(x_1, z) = 1$ but $\indicatorURO(x_2, z) = 0$, contradicting the assumption that these functions are equal on $\Ioon(a,b)$.
\end{proof}
\begin{remark}[Verification Perspective]
This lemma is critical. It guarantees that if an orthant indicator utility function $u(x) = \indicatorURO(x_0,x)$ is specified over the domain $\Ioon(a,b)$, the parameter vector $x_0$ is unique. This justifies our use of classical reasoning in Definition \ref{def:riemannStieltjesND_ND}, ensuring that regardless of which $x_0'$ is chosen by \lean{Classical.choose}, the integral value $\survivalProbN(\text{Dist}, x_0', b)$ will be the same for any valid $x_0'$. In practice, our formalization avoids invoking \lean{Classical.choose} when $x_0$ is explicitly provided.
\end{remark}

\begin{lemma}[Integral for Indicator Function ($N$D)]\label{lem:integral_for_indicator_ND}
Let $a, b \in \RVector(n)$ with $\forall i, a(i) < b(i)$.
Let $u: \RVector(n) \to \R$, $\text{Dist}: \RVector(n) \to \R$, and $x_0 \in \RVector(n)$.
Assume $x_0 \in \Ioon(a,b)$ (hypothesis $h_{x_0{_mem}}$) and $\forall x \in \Iccn(a,b), u(x) = \indicatorURO(x_0, x)$ (hypothesis $h_{u{_def}}$).
Then, with $h_{x_0}' : x_0 \in \Iccn(a,b)$ (derived from $h_{x_0{_mem}}$ using Lemma \ref{lem:Ioo_subset_Icc_self_n}) and $h_u' : \forall x \in \Ioon(a,b), u(x) = \indicatorURO(x_0, x)$ (derived from $h_{u{_def}}$),
$$\riemannStieltjesND(u, \text{Dist}, a, b, x_0, h_{x_0}', h_u') = \survivalProbN(\text{Dist}, x_0, b).$$
\end{lemma}
\begin{proof}
Formal proof sketch provided in Appendix \ref{proof:lem:integral_for_indicator_nd}. The proof directly applies Definition \ref{def:riemannStieltjesND_ND}. The hypotheses $h_{x_0{_mem}}$ and $h_{u{_def}}$ establish that $u$ is indeed an orthant indicator function defined by $x_0$. The definition of $\riemannStieltjesND$ then evaluates to $\survivalProbN(\text{Dist}, x_0, b)$ as required.
\end{proof}
\begin{remark}[Purpose]
This lemma is the cornerstone connecting the specialized integral definition to the geometric/combinatorial survival probability. It formally verifies that, for the specific class of orthant indicator utility functions, our specialized Riemann-Stieltjes integral correctly computes the survival probability. This establishes a bridge between the expected utility framework and the geometric interpretation of FSD through survival probabilities.
\end{remark}

\begin{theorem}[FSD Equivalence for Indicator Functions ($N$D)]\label{thm:fsd_equivalence_ND}
Let $F, G: \RVector(n) \to \R$ be joint distribution functions. Let $a,b \in \RVector(n)$ with $\forall i, a(i) < b(i)$.
Then, the condition
$$(\forall x_0 \in \Ioon(a,b), \survivalProbN(F, x_0, b) \geq \survivalProbN(G, x_0, b))$$
is equivalent to
$$(\forall (x_0 \in \Ioon(a,b)) (h_{x_0{_mem}} : x_0 \in \Ioon(a,b)),$$
$$  \riemannStieltjesND(\indicatorURO(x_0), F, a, b, x_0, h_{x_0}', h_u')$$
$$  \geq \riemannStieltjesND(\indicatorURO(x_0), G, a, b, x_0, h_{x_0}', h_u'),$$
where $h_{x_0}'$ is $x_0 \in \Iccn(a,b)$  and $h_u'$ is $\forall x \in \Ioon(a,b), u(x) = \indicatorURO(x_0, x)$ indicate the necessary proof arguments $h_{x_0}'$ and $h_u'$ as in Lemma \ref{lem:integral_for_indicator_ND}.
\end{theorem}
\begin{proof}
Formal proof sketch provided in Appendix \ref{proof:thm:fsd_equivalence_nd}.
The proof follows directly from Lemma \ref{lem:integral_for_indicator_ND}.
($\Rightarrow$): Assume $\forall x_0 \in \Ioon(a,b), \survivalProbN(F, x_0, b) \geq \survivalProbN(G, x_0, b)$. For any $x_0 \in \Ioon(a,b)$, let $u_{x_0}(x) = \indicatorURO(x_0, x)$. By Lemma \ref{lem:integral_for_indicator_ND}, the specialized Riemann-Stieltjes integrals with respect to $F$ and $G$ are precisely $\survivalProbN(F, x_0, b)$ and $\survivalProbN(G, x_0, b)$. The inequality between the survival probabilities directly translates to the inequality between the integrals.

($\Leftarrow$): Assume the integral inequality for all $x_0 \in \Ioon(a,b)$ and their corresponding indicator functions. By Lemma \ref{lem:integral_for_indicator_ND}, this translates directly to $\survivalProbN(F, x_0, b) \geq \survivalProbN(G, x_0, b)$ for all $x_0 \in \Ioon(a,b)$, completing the proof.
\end{proof}

\begin{remark}[Central Result for Geometric FSD]
This theorem is the central result for our geometric formalization of $N$-dimensional FSD for orthant indicator functions. It formally establishes that dominance in terms of higher expected utility for orthant indicator utility functions is equivalent to higher survival probabilities in all upper-right orthants. This provides a clear geometric interpretation of FSD in $N$ dimensions: one distribution dominates another if and only if it has a higher probability of exceeding any given threshold vector in all dimensions simultaneously.
\end{remark}

\subsection{Extension to General Non-Decreasing Utility Functions}\label{subsec:extension_general}
The formal verification presented thus far specifically addresses orthant indicator functions of the form $\indicatorURO(x_0, x)$. However, in Sections 6 and 9, we make broader claims that the results extend to "all investors with non-decreasing utility functions" and "all policy evaluators with non-decreasing utility functions." This extension, while not formally verified in our Lean implementation, rests on well-established mathematical principles in stochastic dominance theory \cite{Levy2015}\cite{ShakedShanthikumar2007}.

\begin{proposition}[Extension to Non-Decreasing Utility Functions]\label{prop:extension}
If $F$ and $G$ are two joint distribution functions such that $\survivalProbN(F, x_0, b) \geq \survivalProbN(G, x_0, b)$ for all $x_0 \in \Ioon(a,b)$, then $E_F[u(X)] \geq E_G[u(X)]$ for all non-decreasing utility functions $u: \RVector(n) \to \R$.
\end{proposition}

The mathematical foundations for this extension include:

\begin{enumerate}[leftmargin=1.5em, itemsep=0.5em]
    \item \textbf{Approximation Theory:} Any non-decreasing utility function can be approximated arbitrarily closely by a positive linear combination of upper-right orthant indicator functions. This is analogous to how step functions can approximate continuous functions in one dimension.

    \item \textbf{Linearity of Expectation:} If $$E_F[\indicatorURO(x_0,X)] \geq E_G[\indicatorURO(x_0,X)]$$ for all $x_0$, then by linearity of the expectation operator, this inequality also holds for any positive linear combination of these indicator functions.

    \item \textbf{Limit Arguments:} Taking limits (under appropriate regularity conditions), the dominance relation extends to all non-decreasing utility functions that can be approximated by such combinations.
\end{enumerate}

In formal mathematics terms, the orthant indicator functions form a "generating class" for the space of non-decreasing utility functions, in the sense that their linear spans and limits can represent any such function \cite{RussellSeo1989}.

\begin{remark}[Formalization Scope]
While formalizing the full extension to all non-decreasing utility functions would be a valuable contribution, it would require significant additional machinery in Lean, including:
\begin{itemize}
    \item Development of measure-theoretic function approximation theorems
    \item Formalization of convergence theorems for expectations
    \item Construction of limit operations for utility function sequences
\end{itemize}
These extensions remain as promising directions for future formal verification work, building upon the geometric foundation established in this paper.
\end{remark}

For the economic applications discussed in subsequent sections, the indicator function characterization provides a clear, testable condition through survival probability comparisons. The extension to all non-decreasing utility functions then follows as a "free theorem" from standard stochastic dominance theory, making the geometric approach both theoretically complete and practically applicable.



\section{Economic Applications: A Geometric Perspective}\label{sec:economic_applications}
The geometric framework for $N$-dimensional FSD, formalized and verified in Lean 4, offers a robust and notably tractable foundation for analyzing a range of multi-dimensional economic decision problems. In this section, we explore concrete applications across several domains and highlight how the formalization enhances these analyses.

\subsection{Portfolio Selection}
In contemporary finance, portfolio selection extends beyond the classic mean-variance analysis of Markowitz \cite{Markowitz1952}. Investors often evaluate portfolios based on multiple criteria, such as expected returns across different economic scenarios, risk measures across various time horizons, or environmental, social, and governance (ESG) metrics alongside financial performance.
Let a portfolio $P$'s outcome be represented by an $N$-dimensional random vector $X_P = (X_1, X_2, \dots, X_N)$, where each $X_i$ is a desirable attribute.

A portfolio $A$ exhibits first-order stochastic dominance over portfolio $B$ under our geometric framework if, for any target outcome vector $x_0 = (x_{0,1}, \dots, x_{0,N})$, the probability that portfolio $A$ exceeds all targets simultaneously is at least as high as the probability for portfolio $B$:
$P(X_A > x_0) \geq P(X_B > x_0)$.

\begin{example}[Multi-Attribute Portfolio Choice]
Consider two portfolios with bivariate distributions of (return, downside protection). Portfolio $A$ has a higher probability than portfolio $B$ of simultaneously achieving any given threshold combination of return and downside protection. By our geometric FSD framework, portfolio $A$ dominates portfolio $B$, making it preferable for all investors with non-decreasing utility functions over both attributes.
\end{example}



\textbf{Benefits and Enhanced Applications from Geometric Formalization:}
\begin{itemize}
    \item \textbf{Rigor for Complex Criteria:} The geometric framework provides a formal, verifiable basis for portfolio selection involving multiple, possibly correlated criteria without requiring explicit utility functions. This is particularly valuable for institutional investors who must justify decisions across multiple objectives.
    \item \textbf{Verifiable Robo-Advising:} Automated investment advisors can implement FSD checks on portfolios with formal guarantees, enhancing trust in recommendation algorithms.
    \item \textbf{Executable FSD Checkers for Empirical Distributions:} The constructive nature of the geometric proofs, especially for distributions represented as step-functions (empirical CDFs from historical data), enables the development of verified algorithms that can directly check for FSD between portfolios.
        \begin{itemize}
            \item \textbf{Application Example (Portfolio Screening):} A financial institution can use Lean to develop a verified program that decides whether an empirical CDF of returns from a candidate portfolio is dominated by an existing portfolio. The formal guarantees ensure that the screening process correctly implements FSD checks.
        \end{itemize}
    \item \textbf{Automated Verification for Parametric Models with Satisfiability Modulo Theories (SMT) Solvers:} If portfolio returns are modeled by parametric distributions, FSD conditions might translate into algebraic inequalities that can be verified through SMT solvers integrated with Lean.
        \begin{itemize}
            \item \textbf{Application Example:} A firm designs a structured product whose multi-attribute payoff depends on parameters $\alpha, \beta$. They can formally verify in Lean (potentially with SMT solver support) that for certain parameter ranges, the product's payoff distribution dominates a benchmark, providing formal guarantees to clients.
        \end{itemize}
    \item \textbf{Scalability for High-Dimensional Attributes:} The geometric approach, relying on combinatorics (inclusion-exclusion) rather than complex multi-dimensional integration theory (Fubini/Tonelli theorems), scales more effectively to higher dimensions in formal verification contexts.
\end{itemize}
This approach complements works like \cite{DentchevaRuszczynski2006} on stochastic dominance constraints in portfolio optimization, by providing a framework for formally verifying the underlying dominance relations.

\subsection{Risk Management}
Financial institutions manage multifaceted risks, represented as vectors $X = (X_1, \dots, X_N)$ of desirable outcomes (e.g., $X_1$=capital adequacy, $X_2$=liquidity ratio). Strategy $S_A$ FSDs $S_B$ if for all threshold vectors $x_0$, $P(X_{S_A} > x_0) \geq P(X_{S_B} > x_0)$.

\begin{example}[Comparing Hedging Strategies]
A bank compares two hedging strategies for managing interest rate and credit risks. Strategy $A$ stochastically dominates strategy $B$ in our geometric framework, meaning that for any target threshold combinations of interest rate protection and credit risk mitigation, strategy $A$ has a higher probability of simultaneously exceeding both thresholds. This provides a clear justification for preferring strategy $A$ without requiring specific utility functions over these risk dimensions.
\end{example}

\textbf{Benefits and Enhanced Applications from Geometric Formalization:}
\begin{itemize}
    \item \textbf{Unambiguous Model Comparison:} The geometric FSD condition provides clear, interpretable criteria for comparing risk management models across multiple risk dimensions.
    \item \textbf{Regulatory Confidence and Certified Compliance:} Regulators might demand formal proof that a new financial product or risk management strategy FSDs a baseline scenario across multiple risk dimensions.
        \begin{itemize}
            \item \textbf{Application Example:} A bank develops a new internal model for assessing operational risk across $N$ categories. To gain regulatory approval, they provide a Lean-verified proof that their model's risk distribution FSDs the standardized approach across all relevant risk dimensions, demonstrating superior risk management with mathematical certainty.
        \end{itemize}
    \item \textbf{FSD Constraints in Optimization Solvers:} Risk management often involves optimizing resource allocation (e.g., capital, hedging instruments) subject to risk constraints. FSD conditions on multivariate outcomes can be incorporated as verified constraints in optimization problems.
        \begin{itemize}
            \item \textbf{Application Example:} An insurer wants to design a reinsurance program by choosing among various contracts. The goal is to minimize reinsurance cost while ensuring that the post-reinsurance risk profile FSDs a regulatory benchmark across multiple risk categories. The geometric formulation enables more direct incorporation of these constraints in the optimization model.
        \end{itemize}
    \item \textbf{Certified Monte Carlo for Stress Testing:} When evaluating risk under stress scenarios using Monte Carlo simulations, the geometric FSD framework aligns directly with counting simulated outcomes in specific orthants, making verification more tractable.
        \begin{itemize}
            \item \textbf{Application Example:} A bank performs $M$ Monte Carlo simulations for two different investment portfolios under a stress scenario, yielding $M$ vectors of $N$ P\&L figures for each portfolio. A Lean-verified checker can confirm whether one portfolio stochastically dominates the other by directly implementing the geometric survival probability comparisons.
        \end{itemize}
\end{itemize}

\subsection{Welfare Analysis and Policy Evaluation}
Societal well-being or policy impact is often multi-dimensional ($W = (W_1, \dots, W_N)$). Policy $A$ FSDs policy $B$ if $\survivalProbN(F_A, w_0, b) \geq \survivalProbN(F_B, w_0, b)$ for any target welfare vector $w_0$, meaning $A$ has a higher probability than $B$ of simultaneously achieving all welfare thresholds.

\begin{example}[Evaluating Social Programs]
Two healthcare reforms are being compared based on their impacts on three dimensions: access to care, quality of care, and cost reduction. Reform $A$ FSDs reform $B$ in our geometric framework if the probability of simultaneously achieving any given threshold combination across all three dimensions is higher under reform $A$ than reform $B$. This provides a robust basis for policy selection without requiring explicit trade-offs between these objectives.
\end{example}

\textbf{Benefits and Enhanced Applications from Geometric Formalization:}
\begin{itemize}
    \item \textbf{Transparent Policy Choice:} The geometric condition $P(W > w_0)$ is visual and directly interpretable to policymakers as the probability of exceeding all welfare targets simultaneously.
    \item \textbf{Robustness to Utility Specification:} The FSD criterion is valid for all policy evaluators with non-decreasing utility functions over the welfare dimensions, avoiding contentious assumptions about specific social welfare functions.
    \item \textbf{Rigorous Impact Assessment for Interacting Policies:} Our framework accommodates joint distributions where welfare dimensions may be correlated, capturing interaction effects between policy components that might be missed in dimension-by-dimension analyses.
    \item \textbf{Pedagogical Clarity:} The geometric approach, linking FSD to probabilities of exceeding targets in hyperrectangles, is more accessible to students and policymakers who may know calculus but not measure theory, broadening the potential audience for formal methods in policy analysis.
    \item \textbf{Verified Simulation of Policy Impacts:} Similar to stress testing, if the impact of social policies is estimated via agent-based models or microsimulations yielding multi-dimensional outcome distributions, FSD can be assessed directly from these simulated datasets with formal guarantees.
\end{itemize}

\subsection{New Application Area: Formal Guarantees in Data Privacy}
The concept of "dominance" can be extended to information leakage in data privacy mechanisms, such as those aiming for differential privacy \cite{Dwork2006}. Consider $N$ different types of sensitive information. Let $X_i$ represent the information leakage (a value to be minimized) for type $i$ under privacy mechanism $M_A$, and $Y_i$ the leakage under mechanism $M_B$. If for all threshold vectors $x_0$, $P(X < x_0) \ge P(Y < x_0)$, then mechanism $A$ provides superior privacy protection across all dimensions.
Alternatively, if $X_i$ represents the utility preserved for attribute $i$ under privacy mechanism $M_A$, and $Y_i$ under $M_B$, then $M_A$ FSDs $M_B$ if $P(X > x_0) \ge P(Y > x_0)$ for all utility thresholds $x_0$, indicating better utility preservation.

\textbf{Benefits of Geometric Formalization:}
\begin{itemize}
    \item \textbf{Precise Multi-Attribute Privacy Guarantees:} The $N$-dimensional geometric framework can precisely define and verify privacy guarantees across multiple types of data or queries simultaneously, advancing beyond single-metric privacy analyses.
    \item \textbf{Reduced Technical Overhead for Verification:} Proving such multi-dimensional privacy properties without heavy measure-theoretic machinery makes formal verification more accessible to privacy researchers, potentially accelerating the development and verification of privacy-preserving algorithms.
\end{itemize}

\subsection{New Application Area: Certified Libraries and Embedded Systems}
The reduced dependency on heavy measure theory libraries makes the geometric FSD formalization suitable for inclusion in certified numerical libraries or systems where code size and auditability are crucial.

\textbf{Benefits of Geometric Formalization:}
\begin{itemize}
        \item \textbf{Lightweight Certified Components:} A verified FSD checker based on geometric principles can be a small, self-contained module. This is advantageous for embedded systems in finance (e.g., trading devices) and safety-critical applications where code verification is essential.
    \item \textbf{Foundation for Verified Complex Systems:} Verified FSD can be a building block in larger verified systems. For example, a formally verified dynamic programming solver could use this framework to ensure that decisions satisfy stochastic dominance requirements without requiring the full machinery of measure theory.
\end{itemize}
\section{Comparison with Analytical and Other Formal Approaches}\label{sec:comparison_approaches}
The traditional mathematical treatment of stochastic dominance, particularly in multiple dimensions, is deeply rooted in measure theory and the calculus of multi-dimensional integration \cite{Levy2015}. While these analytical approaches provide theoretical rigor, they introduce significant formalization challenges in interactive theorem proving environments.

Our geometric approach, as presented in this paper, offers a distinct and, for the specific goal of verifying FSD and enabling its direct applications, a more tractable alternative for formalization within Lean 4 and similar systems. The key differences and advantages include:

\begin{itemize}[leftmargin=1.5em, itemsep=0.5em]
    \item \textbf{Simplified Mathematical Primitives:} Instead of confronting general integrals and arbitrary measurable sets from the outset, our framework focuses on geometrically intuitive objects: upper-right orthants, hyperrectangles, and inclusion-exclusion calculations on discrete sets. This significantly reduces the theoretical prerequisites for formalization while maintaining the essential mathematical properties needed for economic applications.

    \item \textbf{Lower Technical Overhead in Formalization:} A direct consequence is a significant reduction in the formalization overhead.
        \begin{itemize}
            \item There is no direct need to define or manipulate $\sigma$-algebras, prove measurability for numerous functions and sets, or reason about almost-everywhere equalities for the core FSD theorems.
            \item Such self-contained formalizations tend to compile faster and place less strain on Lean's kernel. They are also often easier to maintain and adapt across future versions of Mathlib's evolving integration and measure theory libraries.
        \end{itemize}

    \item \textbf{Enhanced Automation and SMT-Friendliness:} Proofs within the geometric framework frequently reduce to verifying systems of linear (or sometimes bilinear) real arithmetic inequalities.
        \begin{itemize}
            \item Lean's built-in tactics like `linarith`, `polyrith`, `ring`, and `positivity` are highly effective for such goals.
            \item Furthermore, these types of arithmetic problems are often well-suited for external SMT solvers \cite{deMoura2008}, which can be integrated with Lean through frameworks like `smt\_tactic`.
            \item This contrasts sharply with measure-theoretic proofs, where automation often struggles with goals like "show this set is measurable" or "show this function is integrable," which require extensive manual guidance and domain-specific expertise.
        \end{itemize}

    \item \textbf{More Direct Path to $N$-Dimensional Scalability:} The traditional route to multivariate FSD requires formalizing product $\sigma$-algebras and Fubini's or Tonelli's theorems to handle multiple integrals. Our combinatorial approach using inclusion-exclusion principles scales to $N$ dimensions with comparatively less formalization overhead, making it practical to handle higher-dimensional problems.

    \item \textbf{Potential for Constructive Proofs and Code Extraction:} Because geometric proofs often rely on explicit inequalities and constructions on rectangles or intervals, the conclusions can frequently be stated in more computationally tractable ways.
        \begin{itemize}
            \item This opens the possibility of extracting executable code directly from the verified theorems (e.g., a program that decides FSD for distributions represented by step-functions or empirical CDFs).
            \item In contrast, some measure-theoretic results might be non-constructive or rely on classical axioms in ways that make direct code extraction more challenging or less meaningful.
        \end{itemize}

     \item \textbf{Lean-Specific Implementation Insights:} Working in Lean 4 specifically, We've found that:
        \begin{itemize}
            \item The \lean{Finset} operations used for survival probability calculations align well with Lean's computation capabilities and tactic-based automation
            \item The \lean{Classical.propDecidable} and \lean{Classical.choose} constructs provide a pragmatic way to handle the existence requirements while maintaining logical consistency
            \item Lean's dependent type system allows us to express the complex geometric conditions with precise types that carry proof information (like our \lean{riemannStieltjesND} function that takes proof arguments)
        \end{itemize}  

\end{itemize}



Compared to other formal verification efforts in economics or finance that might aim to formalize stochastic dominance by directly translating the standard analytical definitions (relying heavily on Mathlib's integration theory), our geometric approach offers a more modular and focused pathway. It establishes the essential properties of FSD needed for economic applications without requiring the formalization of the full measure-theoretic foundations. This strategic choice enhances tractability while maintaining mathematical rigor for the specific goal of enabling formal analysis of multi-dimensional economic decision problems.

\section{Conclusion}\label{sec:conclusion}
This paper has introduced and demonstrated a novel geometric pathway to the formalization and verification of $N$-dimensional first-order stochastic dominance using the Lean 4 theorem prover. By strategically reformulating the traditional analytical characterizations of FSD into a geometric framework based on survival probabilities in upper-right orthants, we have achieved a significantly more tractable formalization while maintaining the essential mathematical properties needed for economic analysis.

The central message of this work, substantiated by our formal developments in Lean 4, is that \textbf{geometric methods can provide a significantly more tractable path to formalizing complex probabilistic concepts in economics}, particularly those involving multi-dimensional risk and welfare comparisons. This approach reduces the formalization overhead without compromising mathematical rigor, bridging the gap between theoretical economic concepts and formal verification technologies.

The benefits of this geometric approach, particularly from the perspective of formal verification and practical application, are manifold:
\begin{itemize}[leftmargin=1.5em, itemsep=0.5em]
    \item \textbf{Enhanced Formal Tractability and Maintainability:} The geometric definitions simplify the translation of mathematical concepts into Lean 4 and streamline the proof development process. They also reduce dependencies on evolving libraries for advanced measure theory, enhancing long-term maintainability.
     \item \textbf{Clarity, Intuition, and Pedagogical Transparency:} Geometric conditions, such as comparing probabilities of exceeding targets in specific orthants ($P(X > x_0)$), often provide a more intuitive and accessible framework for practitioners than traditional analytical formulations involving multiple integrals or complex measure-theoretic constructs.
    \item \textbf{Foundation for Verifiable Economic Models and Certified Tools:} This work provides formally verified building blocks for constructing more complex economic models and decision-support tools with mathematical guarantees. The reduced formalization overhead makes it practical to incorporate these verified components into larger systems.
    \item \textbf{Improved Automation in Proofs:} The reduction of many proof goals to real arithmetic makes them amenable to powerful automated tactics in Lean (`linarith`, `polyrith`, `ring`, `positivity`) and integration with external SMT solvers, increasing the efficiency of formal verification efforts.
\end{itemize}

Future research can extend this geometric framework in several promising directions. This includes formalizing higher-order stochastic dominance using related geometric ideas (e.g., based on integrals of survival functions), developing verified algorithms for checking stochastic dominance between empirical distributions, and extending the approach to more specialized forms of stochastic dominance relevant to specific economic applications. The combinatorial structure of our definitions also suggests potential connections to algorithmic game theory and computational economics that warrant further exploration.

By demonstrating the feasibility and advantages of a geometric approach to a cornerstone concept in decision theory, this work aims to encourage further exploration of how strategic mathematical reformulations can enhance the tractability of formal verification in economics. The resulting formally verified theorems provide a foundation for more reliable and transparent economic analysis in high-stakes domains where rigorous guarantees are increasingly essential.

