\appendix 
\section{Regularity of Lie derivatives of Hilbert transform analogues}
The main goal of this appendix is to establish the following result.

\begin{theorem}\label{thm: decay of Hilbert transform on SL2(R)}
  Let $1 < p < \infty$ and let $m \in L_\infty(SL_2(\mathbb{Z}))$ be the symbol defined in \eqref{eqn: Hilbert transform on PSL_2(Z)}. Let $\widetilde{m} \in L_\infty(SL_2(\mathbb{R}))$ denote the transferred multiplier associated to $m$ via \eqref{eqn: formula of tilde m}. Then $\widetilde{m}$ is bi-$K$-invariant and satisfies the pointwise estimate
  \[
     \norm{g}^{\abs{\gamma}}\abs{\dd_g^\gamma \widetilde{m}(g)}\leq C,\quad \text{for all multi-indices }  \abs{\gamma}\leq 1,
  \]
  where $\norm{g} =\sup_{v\in \mathbb{R}^2}\frac{\norm{gv}_2}{\norm{v}_2}$ is the operator norm of $g \in SL_2(\mathbb{R})$.

  Moreover, $T_{\widetilde{m}}$ is a completely bounded Fourier multiplier on $L_p(\mathcal{L}(SL_2(\mathbb{R})))$.
\end{theorem}

We begin by establishing some notational conventions and preliminary computations. The proof of Theorem~\ref{thm: decay of Hilbert transform on SL2(R)} is presented in Section~\ref{Sec: Proof of the main theorem}, where it relies on Lemma~\ref{Lem: dereasing ratio of derivative of m hat}. In Remark~\ref{Rmk: non-existence of second order}, we show that the H\"ormander--Mikhlin condition fails to hold for $\widetilde{m}$ when $\abs{\gamma} = 2$.

Let
\[
X_1 = \begin{pmatrix}
1 & 0 \\
0 & -1
\end{pmatrix}, \quad 
X_2 = \begin{pmatrix}
0 & 1 \\
0 & 0
\end{pmatrix}, \quad 
X_3 = \begin{pmatrix}
0 & 1 \\
-1 & 0
\end{pmatrix}
\]
be a basis for the Lie algebra $\mathfrak{sl}_2(\mathbb{R})$. The corresponding Lie derivatives of functions on $SL_2(\mathbb{R})$ are defined by
\[
\partial_{X_j} m(g) = \eval{\dv{t}}_{t=0} m\big(g \exp(tX_j)\big),
\]
and, in general, these derivatives do not commute when $j \neq k$. Given an ordered multi-index $\gamma = (j_1, j_2, \dots, j_k)$ with $1 \leq j_i \leq 3$ and $\abs{\gamma}= k \geq 0$, the associated Lie differential operator is defined by
\[
\dd_g^\gamma m(g) = \partial_{X_{j_1}} \partial_{X_{j_2}} \cdots \partial_{X_{j_k}} m(g) = \left( \prod_{1 \leq k \leq |\gamma|}^{\rightarrow} \partial_{X_{j_k}} \right) m(g).
\]

Assume that $m \in L_\infty(SL_2(\mathbb{Z}))$ satisfies $m(\gamma) = m(-\gamma)$ for all $\gamma \in SL_2(\mathbb{Z})$. Let $SL_2(\mathbb{R}) = KAK$ denote the Cartan decomposition of the group. By Proposition~\ref{Prop: widetilde m is bi-K-invariant}, the first-order Lie derivatives of the function $\widetilde{m}$ satisfy
\[
\begin{split}
\partial_{X_j} \widetilde{m}(k'a k) &= \eval{\dv{t}}_{t=0}\widetilde{m}\big(k' a k \exp(t X_j)\big) =\eval{\dv{t}}_{t=0} \widetilde{m}\big(a k \exp(t X_j) k^{-1}\big) \\
&= \eval{\dv{t}}_{t=0} \widetilde{m}\big(a \exp(t (\ad_k X_j))\big) = \partial_{\ad_k X_j} \widetilde{m}(a),
\end{split}
\]
for all $k, k' \in K$ and $a \in A$ with $1 \leq j \leq 3$.
Let
\[
k = \begin{pmatrix}
\cos\theta & -\sin\theta \\
\sin\theta & \cos\theta
\end{pmatrix}.
\]
We compute the adjoint actions:
\begin{align*}
\ad_k X_1 &= kX_1k^{-1} = 
\begin{pmatrix}
\cos(2\theta) & \sin(2\theta) \\
\sin(2\theta) & -\cos(2\theta)
\end{pmatrix}
= \cos(2\theta) X_1 + 2\sin(2\theta) X_2 - \sin(2\theta) X_3, \\
\ad_k X_2 &= kX_2k^{-1} =
\begin{pmatrix}
-\sin\theta \cos\theta & \cos^2\theta \\
-\sin^2\theta & \sin\theta \cos\theta
\end{pmatrix}
= -\sin\theta \cos\theta X_1 + \cos(2\theta) X_2 + \sin^2\theta X_3, \\
\ad_k X_3 &= kX_3k^{-1} = 
\begin{pmatrix}
0 & 1 \\
-1 & 0
\end{pmatrix}
= X_3.
\end{align*}
Therefore, for any $a \in A$ and $k,k' \in K$, we have the following estimate:
\begin{equation}\label{Eqn: estimation of Lie derivation of m tilde}
\left| \partial_{X_j} \widetilde{m}(k' a k) \right| = \left| \partial_{\ad_k X_j} \widetilde{m}(a) \right| \leq \sum_{j=1}^3 \left| \partial_{X_j} \widetilde{m}(a) \right|.
\end{equation}

Now, let $g \in AN$ be written as
\[
g = \begin{pmatrix}
\sqrt{g_y} & \dfrac{g_x}{\sqrt{g_y}} \\
0 & \dfrac{1}{\sqrt{g_y}}
\end{pmatrix},
\]
and denote by $\widehat{m}(g_x, g_y)$ the function $\widetilde{\widetilde{m}}(g)$ defined in \eqref{eqn: formula of tilde tilde m for SL2(R)} when restricted to $AN$.
The Lie derivatives of $\widetilde{\widetilde{m}}$ are given by
\begin{equation}\label{Eqns: Lie derivations of tildetilde m}
\left\{
\begin{aligned}
   \partial_{X_1} \widetilde{\widetilde{m}}(g) &=\eval{\dv{t}}_{t=0} \widehat{m}(g_x, e^{2t}g_y) = \eval{2e^{2t}g_y \pdv{g_y} \widehat{m}(g_x, e^{2t}g_y)}_{t=0} = 2g_y \pdv{g_y} \widehat{m}(g_x, g_y), \\
  \partial_{X_2} \widetilde{\widetilde{m}}(g) &=\eval{\dv{t}}_{t=0} \widehat{m}(g_x + t g_y, g_y) = \eval{ g_y \pdv{g_x} \widehat{m}(g_x + t g_y, g_y)}_{t=0} = g_y \pdv{g_x} \widehat{m}(g_x, g_y), \\
  \partial_{X_3} \widetilde{\widetilde{m}}(g) &=\eval{\dv{t}}_{t=0} \widehat{m}(g_x, g_y) = 0.
\end{aligned}
\right.
\end{equation}
By the mean value theorem, we have
\begin{equation}\label{Eqn: formula of Lie derivation of m tilde}
\begin{split}
  \partial_{X_j} \widetilde{m}(a) &=\eval{\dv{t}}_{t=0} \frac{1}{\pi} \int_{K_+} \widetilde{\widetilde{m}}(k_0 a \exp(t X_j)) \, \dd\nu(k_0) \\
  &= \frac{1}{\pi} \lim_{\delta \to 0} \int_{K_+} \eval{\dv{t}}_{t=\delta} \widetilde{\widetilde{m}}(k_0 a \exp(t X_j)) \, \dd\nu(k_0).
\end{split}
\end{equation}
Assuming that $\left| \dv{t} \widetilde{\widetilde{m}}(k_0 a \exp(t X_j)) \right|$ is integrable over $K_+$ for $t$ in a neighborhood of $0$, the dominated convergence theorem yields
\begin{equation}\label{Eqn: final formula of Lie derivation of m tilde}
  \partial_{X_j} \widetilde{m}(a) = \frac{1}{\pi} \int_{K_+} \partial_{X_j} \widetilde{\widetilde{m}}(k_0 a) \, \dd\nu(k_0).
\end{equation}

To analyze the decay of $\partial_{X_j} \widetilde{m}$, by \eqref{Eqn: estimation of Lie derivation of m tilde}, it suffices to evaluate the integrals in \eqref{Eqn: final formula of Lie derivation of m tilde}.
The decay of $\partial_{X_j} \widetilde{m}$ on the subgroup $A$ is governed by the expression $\widehat{m}(g_x, g_y)$, derived using Equations~\eqref{Eqns: Lie derivations of tildetilde m} and~\eqref{Eqn: final formula of Lie derivation of m tilde}, where $g = P_{AN}(k a)$ for some $k \in K$ and $a \in A$. The following lemma establishes the necessary decay properties for the function $\widetilde{\widetilde{m}}(g)$ defined in~\eqref{eqn: formula of tilde tilde m for SL2(R)}. The proof of this lemma constitutes the main technical work of the next subsection.

\begin{lemma}\label{Lem: dereasing ratio of derivative of m hat}
Let
\[
g = \begin{pmatrix}
  \sqrt{g_y} & \dfrac{g_x}{\sqrt{g_y}} \\
  0 & \dfrac{1}{\sqrt{g_y}}
\end{pmatrix} \in AN,
\]
and denote $\widetilde{\widetilde{m}}(g)$ in~\eqref{Eqn: explicit formula of tildetilde m for Hilbert transform} by $\widehat{m}(g_x, g_y)$. Then the following estimates hold:
\[
0<\pdv{g_x}\widehat{m}(g_x,g_y)\leq
\begin{cases}
C_1 \log\left( \dfrac{1}{|g_x|} \right) + C_2 \log\left( \dfrac{1}{g_y} \right) + C_3, & \text{if } 0 < g_y \leq \dfrac{1}{2}, \\
C_1 \log\left( \dfrac{1}{|g_x|} \right), & \text{if } g_y > \dfrac{2}{\sqrt{3}},
\end{cases}
\]
and
\[
0 \leq \pdv{g_y}\widehat{m}(g_x,g_y) \leq
\begin{cases}
6, & \text{if } 0 < g_y \leq \dfrac{1}{2}, \\
0, & \text{if } g_y > \dfrac{2}{\sqrt{3}}.
\end{cases}
\]
\end{lemma}
