\begin{align*}
E_{y,upper}(x,g_x,g_y)&=\frac{\sqrt{g_x^2 - x (x + 2) g_y^2} - (x + 1) g_x}{g_x^2 + g_y^2},\\
 E_{y,lower}(x,g_x,g_y)&=-\frac{\sqrt{g_x^2 - x (x + 2) g_y^2} + (x + 1) g_x}{g_x^2 + g_y^2}.
\end{align*}
Also, we denote the function of the right (left) part of the ellipse by
\begin{align*}
E_{x,right}(y, g_x, g_y) &= -y g_x + \sqrt{1 - y^2 g_y^2} - 1, \\
E_{x,left}(y, g_x, g_y) &= -y g_x - \sqrt{1 - y^2 g_y^2} - 1. \\
\end{align*}
Finally, for easy to compute, denote  
\begin{align*}
L_y(x, g_x, g_y) &= -\frac{1 + 2 x}{2 g_x},\\
L_x(y, g_x, g_y) &= -y g_x - \frac{1}{2}.
\end{align*}
\par 

These functions help delineate the integration domain for $\widehat{m}(g_x,g_y)$ when calculating the integral over $A(g_x, g_y) \cap \mathcal{F}$. Solving these equations provides the necessary boundaries to evaluate the integral explicitly. We list the values of $g_x$ at the boundary conditions for $g_y<\frac{1}{2}$ in Figure \ref{fig: change of A cap F by g_x for small gy}:
\begin{enumerate}
\item $g_x=b_2(g_y)=\frac{-1+\sqrt{4-3g_y^2}}{\sqrt{3}}$: The unique $g_x$ such that the point $(-\frac{1}{2},\frac{\sqrt{3}}{2})$ lies on the right part of the ellipse $E$.
\item $g_x=b_3(g_y)=0$: The unique $g_x$ such that the line $L$ is perpendicular to the $x$-axis.
\item $g_x=b_4(g_y)=-1+\sqrt{1-g_y^2}$: The unique $g_x$ such that the point $(0,1)$ lies on the right part of the ellipse $E$.
\item $g_x=b_5(g_y)=-\frac{\sqrt{5}g_y}{2}$: The unique $g_x$ such that the right part of the ellipse $E$ tangent to the straight line $x=\frac{1}{2}$.
\item $g_x=b_6(g_y)=-\frac{2g_y}{\sqrt{3}}$: The unique $g_x$ such that the line $L$, the right part of the ellipse $E$ and the straight line $x=\frac{1}{2}$ meet at one point. 
\item $g_x=b_7(g_y)=-\frac{3-\sqrt{4-3g_y^2}}{\sqrt{3}}$: The unique $g_x$ such that the point $(\frac{1}{2},\frac{\sqrt{3}}{2})$ lies on the right part of the ellipse $E$.
\end{enumerate}
And we list the explicit values of $g_x$ at these boundary conditions for $g_y>\frac{2}{\sqrt{3}}$ in Figure \ref{fig: change of A cap F by g_x for large gy}.
\begin{enumerate}
\item $g_x=b_8(g_y)=-\frac{2}{\sqrt{3}}$: The unique $g_x$ such that the point $(\frac{1}{2},\frac{\sqrt{3}}{2})$ lies on the line $L$.
\item $g_x=b_9(g_y)=0$: The unique $g_x$ such that the line $L$ is perpendicular to the $x$-axis.
\end{enumerate}
We compute $\widehat{m}(g_x,g_y)$ for $g_y<\frac{1}{2}$ in Case 1 to Case 7, $\widehat{m}(g_x,g_y)$ for $g_y>\frac{2}{\sqrt{3}}$ in Case 8.\par 
\noindent\textbf{Case 1: $g_x \in (b_2(g_y), \infty)$}

In this case, the overlap region is depicted in Figure \ref{fig:case1}.

\begin{figure}[h]
\centering
\includegraphics[scale=0.3]{Case_1.eps}
\caption{Case 1}\label{fig:case1}
\end{figure}

We have $\widehat{m}(g_x, g_y) = 1$ is a constant function. So $\pdv{g_y}\widehat{m}(g_x, g_y) = \pdv{g_x}\widehat{m}(g_x, g_y)=0$.\par

\noindent\textbf{Case 2: $g_x \in (b_3(g_y), b_2(g_y))$}

In this case, the overlap region is depicted in Figure \ref{fig:case2}.
\begin{figure}[h]
\centering
\includegraphics[scale=0.3]{Case_2.eps}
\caption{Case 2}\label{fig:case2}
\end{figure}

Denote the $x$-coordinate of the intersection point of the ellipse $E$ and the circle $x^2+y^2=1$ by  $A_x(g_x, g_y)$. Since \(E_{y,upper}(x, g_x, g_y)\) is concave with respect to $x$, we have
\[
E_{y,upper}(x, g_x, g_y) \leq \left( \eval{\pdv{x} E_{y,upper}(x, g_x, g_y)}_{x=0} \right) x = -\frac{x}{g_x}.
\]
So the solution of the equation \(-\frac{x}{g_x} = \sqrt{1 - x^2}\) gives an upper bound of \(A_x(g_x, g_y)\),
\[
A_x(g_x, g_y) \leq -\frac{g_x}{\sqrt{1 + g_x^2}} \leq -\frac{g_x}{\sqrt{1 + \frac{1}{3}}} = -\frac{\sqrt{3}g_x}{2}.
\]
The second inequality is due to $g_x^2 \leq \frac{1}{3}$ for $g_x\in (0,b_2(g_y))$.\par
For $g_x\in (b_3(g_y),b_2(g_y))$, we have
\[
\begin{split}
\widehat{m}(g_x, g_y) &= 1 - \frac{3}{\pi} \int_{-\frac{1}{2}}^{A_x(g_x, g_y)} \int_{\sqrt{1 - x^2}}^{E_{y,upper}(x, g_x, g_y)} \frac{1}{y^2} \dd y \dd x \\
&= 1 + \frac{3}{\pi} \int_{-\frac{1}{2}}^{A_x(g_x, g_y)}  \frac{1}{E_{y,upper}(x, g_x, g_y)} - \frac{1}{\sqrt{1 - x^2}} \dd x \\
&= 1 + \frac{3}{\pi} \int_{-\frac{1}{2}}^{A_x(g_x, g_y)} F_2(x, g_x, g_y) \dd x.
\end{split}
\]

It is easy to compute that $\int \pdv{g_x}F_2(x,g_x,g_y)\dd x=\pdv{g_x}\int F_2(x,g_x,g_y)\dd x+C$ and $\int \pdv{g_y}F_{2}(x,g_x,g_y)\dd x=\pdv{g_y}\int F_2(x,g_x,g_y)\dd x+C$. Since $F_2(A_x(g_x,g_y),g_x,g_y)=0$, we have 
\[
\pdv{g_x}\widehat{m}(g_x, g_y)=\frac{3}{\pi}\int_{-\frac{1}{2}}^{A_x(g_x,g_y)}\pdv{g_x}F_2(x,g_x,g_y)\dd x,
\]
\[
\pdv{g_y}\widehat{m}(g_x, g_y)=\frac{3}{\pi}\int_{-\frac{1}{2}}^{A_x(g_x,g_y)}\pdv{g_y}F_{2}(x,g_x,g_y)\dd x.
\]\par

In the region of integration in this case, we have \(x \in (-\frac{1}{2}, 0 )\) and \(g_x > 0\). Therefore, \(\pdv{g_x}F_2(x, g_x, g_y)\) can be estimated by
\[
0 < \pdv{g_x}F_2(x, g_x, g_y) = -\frac{ \frac{g_x}{\sqrt{g_x^2 - g_y^2 x (x + 2)}} + x + 1 }{ x (x + 2) } \leq -\frac{ 1 + x + 1 }{ x (x + 2) } = -\frac{1}{x}.
\]
So we have 
\begin{equation}\label{ineq: estimation of m hat 2 by gx}
0<\pdv{g_x}\widehat{m}(g_x, g_y)\leq \frac{3}{\pi}\int_{-\frac{1}{2}}^{ \frac{-\sqrt{3}g_x}{2} } -\frac{1}{x}\dd x= -\frac{3\log(3)}{2\pi}+\frac{3}{\pi}\log(\frac{1}{g_x}).
\end{equation}
Now we estimate $\pdv{g_y}\widehat{m}(g_x, g_y)$. This estimation will occur many times in subsequent cases. The main estimation we use is that 
\begin{equation}\label{ineq: estimation of m hat 2 by gy}
\begin{split}
0<\pdv{g_y}\widehat{m}(g_x, g_y)=&\frac{3}{\pi}\int_{x_l}^{x_u}\pdv{g_y}F_{2}(x, g_x, g_y)\dd x = \frac{3}{\pi}\int_{x_l}^{x_u}\frac{1}{\sqrt{(\frac{g_x}{g_y} )^2 - x(x+2)}}\dd x \\
= &\frac{3}{\pi}\left( \eval{ -\tan^{-1}\left( \frac{\sqrt{(\frac{g_x}{g_y})^2 - 2x - x^2}}{1+x} \right) }_{x_l}^{x_u} \right) \leq 3,
\end{split}
\end{equation}
for any $x_l, x_u$ in the domain of the integrand of the above integration.


\noindent\textbf{Case 3: $g_x\in (b_4(g_y),b_3(g_y))$}\par

In this case, the overlap region is depicted in Figure \ref{fig:case3}.
\begin{figure}[h]
\includegraphics[scale=0.3]{Case_3.eps}
\centering
\caption{Case 3}\label{fig:case3}
\end{figure}\par 
Let $B_x(g_x,g_y)$ be the $x$-coordinate of the intersection point of the ellipse $E$ and the line $L$, i.e.,
\[
L_y(B_x(g_x,g_y),g_x,g_y)=E_{y,upper}(B_x(g_x,g_y),g_x,g_y).
\]
This yields
\[
B_x(g_x,g_y)=-\frac{\sqrt{3} g_x+g_y}{2 g_y}>-\frac{1}{2}.
\]
For $g_x\in (b_4(g_y),b_3(g_y))$, we have
\[
\begin{split}
\widehat{m}(g_x,g_y)=&\frac{3}{\pi}\int_{B_x(g_x,g_y)}^{\frac{1}{2}}\int_{\sqrt{1-x^2}}^{L_y(x,g_x,g_y)}\frac{1}{y^2}\dd y\dd x-\frac{3}{\pi}\int_{B_x(g_x,g_y)}^{A_x(g_x,g_y)}\int_{\sqrt{1-x^2}}^{E_{y,upper}(x,g_x,g_y)}\frac{1}{y^2}\dd y\dd x\\
=&-\frac{3}{\pi}\int_{B_x(g_x,g_y)}^{\frac{1}{2}}\frac{1}{L_y(x,g_x,g_y)}-\frac{1}{\sqrt{1-x^2}}\dd x+\frac{3}{\pi}\int_{B_x(g_x,g_y)}^{A_x(g_x,g_y)}\frac{1}{E_{y,upper}(x,g_x,g_y)}-\frac{1}{\sqrt{1-x^2}}\dd x\\
=&\frac{3}{\pi}\int_{B_x(g_x,g_y)}^{\frac{1}{2}}F_{3,1}(x,g_x,g_y)\dd x+\frac{3}{\pi}\int_{B_x(g_x,g_y)}^{A_x(g_x,g_y)}F_{2}(x,g_x,g_y)\dd x\\
=& \widehat{m}_{3,1}(g_x,g_y)+\widehat{m}_{3,2}(g_x,g_y).
\end{split}
\]\par
It is easy to compute that $\int \pdv{g_x}F_{3,1}(x,g_x,g_y)\dd x=\pdv{g_x}\int F_{3,1}(x,g_x,g_y)\dd x+C$ and $\int \pdv{g_y}F_{3,1}(x,g_x,g_y)\dd x=\pdv{g_y}\int F_{3,1}(x,g_x,g_y)\dd x+C=C$. Since 
\[
F_{3,1}(B_x(g_x,g_y),g_x,g_y)+F_{2}(B_x(g_x,g_y),g_x,g_y)=0,
\]
we have
\[
\begin{split}
\pdv{g_x}\widehat{m}(g_x, g_y)=&\frac{3}{\pi}\int_{B_x(g_x,g_y)}^{\frac{1}{2}}\pdv{g_x}F_{3,1}(x,g_x,g_y)\dd x+\frac{3}{\pi}\int_{B_x(g_x,g_y)}^{A_x(g_x,g_y)}\pdv{g_x}F_{2}(x,g_x,g_y)\dd x\\
=&\frac{3}{\pi}\int_{B_x(g_x,g_y)}^{\frac{1}{2}}\frac{2}{1+2x}\dd x+\frac{3}{\pi}\int_{B_x(g_x,g_y)}^{A_x(g_x,g_y)}\pdv{g_x}F_{2}(x,g_x,g_y)\dd x,\\
\end{split}
\]
\[
\pdv{g_y}\widehat{m}(g_x, g_y)=\frac{3}{\pi}\int_{B_x(g_x,g_y)}^{A_x(g_x,g_y)}\pdv{g_y}F_{2}(x,g_x,g_y)\dd x.\\
\]\par
We have
\begin{equation}
0<\int_{B_x(g_x,g_y)}^{\frac{1}{2}}\frac{2}{1+2x}\dd x\leq\log(-\frac{2g_y}{\sqrt{3}g_x})\leq \log(-\frac{1}{\sqrt{3}g_x}).
\end{equation}

Let $b(g_x,g_y)=\frac{g_y^2}{g_x^2}$. We have
\[
b(g_x,g_y)\geq \frac{g_y^2}{b_4(g_y)^2}= \frac{g_y^2}{(1-\sqrt{1-g_y^2})^2}\geq 7+4\sqrt{3}.
\]
So 
\[
\pdv{g_x}F_{2}(x,g_x,g_y)=\frac{-\frac{1}{\sqrt{1-(\frac{g_y}{g_x})^2 x (x+2)}}+x+1}{-x(x+2)}=\frac{-\frac{1}{\sqrt{1-b(g_x,g_y) x (x+2)}}+x+1}{-x(x+2)}>0.
\]

We have
\[
\begin{split}
0<\int_{B_x(g_x,g_y)}^{A_x(g_x,g_y)}\pdv{g_x}F_{2}(x,g_x,g_y)\dd x\leq &\int_{-\frac{1}{2}}^{0}\frac{-\frac{1}{\sqrt{1-b(g_x,g_y) x (x+2)}}+x+1}{-x (x+2)}\dd x\\
=&(\log(\frac{1+b(g_x,g_y)}{2})-\log(\frac{2}{3}(\sqrt{4+3b(g_x,g_y)}-1)))\\
\leq &\log(b(g_x,g_y))= 2\log(-\frac{g_y}{g_x})\leq 2\log(-\frac{1}{2g_x}).
\end{split}
\]
Therefore, we have 
\begin{equation}\label{ineq: estimation of m hat 3 by gx}
0<\pdv{g_x}\widehat{m}(g_x, g_y)\leq \frac{9}{\pi}\log \left(-\frac{1}{g_x}\right)-\frac{3\log (3)}{2\pi}-\frac{3}{\pi}\log (4).
\end{equation}
Also, by estimation \eqref{ineq: estimation of m hat 2 by gy}, we have \par 
\begin{equation}\label{ineq: estimation of m hat 3 by gy}
0<\pdv{g_y}\widehat{m}(g_x, g_y)=\frac{3}{\pi}\int_{B_x(g_x,g_y)}^{A_x(g_x,g_y)}\pdv{g_y}F_{2}(x,g_x,g_y)\dd x\leq 3.
\end{equation}

\noindent\textbf{Case 4: $g_x\in (b_5(g_y),b_4(g_y))$}\par
In this case, the overlap region is depicted in Figure \ref{fig:case4}.\par
\begin{figure}[h]
\includegraphics[scale=0.3]{Case_4.eps}
\centering
\caption{Case 4}\label{fig:case4}
\end{figure}
Let $A_y(g_x, g_y)$ be the $y$-coordinate of the intersection point of the ellipse $E$ and the circle $x^2+y^2=1$, $B_y(g_x,g_y)$ be the $y$-coordinate of the intersection point of the ellipse $E$ and the line $L$, i.e.,
\[
L_x(B_y(g_x,g_y),g_x,g_y)=E_{x,right}(B_y(g_x,g_y),g_x,g_y),
\]
and $C_y(g_x,g_y)$ be the $y$-coordinate of the intersection point of the line $L$ and line $x=\frac{1}{2}$, i.e.,
\[
L_x(C_y(g_x,g_y),g_x,g_y)=\frac{1}{2}.
\]
These yield 
\[
A_y(g_x,g_y)\geq \frac{\sqrt{3}}{2},\quad B_y(g_x,g_y)=\frac{\sqrt{3}}{2g_y}>\frac{\sqrt{3}}{2},\quad C_y(g_x,g_y)=-\frac{1}{g_x}>\frac{\sqrt{3}}{2}.
\]
For $g_x\in (b_5(g_y),b_4(g_y))$, 
\[
\begin{split}
\widehat{m}(g_x,g_y)=&\frac{3}{\pi}\int_{\frac{\sqrt{3}}{2}}^{A_y(g_x,g_y)}\int_{\sqrt{1-y^2}}^{\frac{1}{2}}\frac{1}{y^2}\dd x\dd y+\frac{3}{\pi}\int_{A_y(g_x,g_y)}^{B_y(g_x,g_y)}\int_{E_{x,right}(y,g_x,g_y)}^{\frac{1}{2}}\frac{1}{y^2}\dd x\dd y\\
&~~+\frac{3}{\pi}\int_{B_y(g_x,g_y)}^{C_y(g_x,g_y)}\int_{L_x(y,g_x,g_y)}^{\frac{1}{2}}\frac{1}{y^2}\dd x\dd y\\
=&\frac{3}{\pi}\int_{\frac{\sqrt{3}}{2}}^{A_y(g_x,g_y)}\frac{\frac{1}{2}-\sqrt{1-y^2}}{y^2}\dd y+\frac{3}{\pi}\int_{A_y(g_x,g_y)}^{B_y(g_x,g_y)}\frac{\frac{1}{2}-E_{x,right}(y,g_x,g_y)}{y^2}\dd y\\
&~~+\frac{3}{\pi}\int_{B_y(g_x,g_y)}^{C_y(g_x,g_y)}\frac{\frac{1}{2}-L_x(y,g_x,g_y)}{y^2}\dd y\\
=&\frac{3}{\pi}\int_{\frac{\sqrt{3}}{2}}^{A_y(g_x,g_y)}F_{4,1}(y,g_x,g_y)\dd y+\frac{3}{\pi}\int_{A_y(g_x,g_y)}^{B_y(g_x,g_y)}F_{4,2}(y,g_x,g_y)\dd y\\
&~~+\frac{3}{\pi}\int_{B_y(g_x,g_y)}^{C_y(g_x,g_y)}F_{4,3}(y,g_x,g_y)\dd y.\\
\end{split}
\]

It is easy to compute that
\[
\begin{cases}
\int \pdv{g_x}F_{4,1}(x,g_x,g_y)\dd x=\pdv{g_x}\int F_{4,1}(x,g_x,g_y)\dd x+C=C,\\
\int \pdv{g_y}F_{4,1}(x,g_x,g_y)\dd x=\pdv{g_y}\int F_{4,1}(x,g_x,g_y)\dd x+C=C,\\
\int \pdv{g_x}F_{4,2}(x,g_x,g_y)\dd x=\pdv{g_x}\int F_{4,2}(x,g_x,g_y)\dd x+C=\log(x)+C,\\
\int \pdv{g_y}F_{4,2}(x,g_x,g_y)\dd x=\pdv{g_y}\int F_{4,2}(x,g_x,g_y)\dd x+C=\tan ^{-1}\left(\frac{g_y x}{\sqrt{1-g_y^2 x^2}}\right)+C,\\
\int \pdv{g_x}F_{4,3}(x,g_x,g_y)\dd x=\pdv{g_x}\int F_{4,3}(x,g_x,g_y)\dd x+C=\log(x)+C,\\
\int \pdv{g_y}F_{4,3}(x,g_x,g_y)\dd x=\pdv{g_y}\int F_{4,3}(x,g_x,g_y)\dd x+C=C.
\end{cases}
\]
Since
\[
\begin{cases}
F_{4,1}(A_y(g_x,g_y),g_x,g_y)=F_{4,2}(A_y(g_x,g_y),g_x,g_y),\\
F_{4,2}(B_y(g_x,g_y),g_x,g_y)=F_{4,3}(B_y(g_x,g_y),g_x,g_y),\\
F_{4,3}(C_y(g_x,g_y),g_x,g_y)=0,
\end{cases}
\]
we have
\[
\begin{split}
\pdv{g_x}\widehat{m}(g_x, g_y)=&\frac{3}{\pi}\int_{A_y(g_x,g_y)}^{B_y(g_x,g_y)}\pdv{g_x}F_{4,2}(y,g_x,g_y)\dd y+\frac{3}{\pi}\int_{B_y(g_x,g_y)}^{C_y(g_x,g_y)}\pdv{g_x}F_{4,3}(y,g_x,g_y)\dd y\\
=&\frac{3}{\pi}\int_{A_y(g_x,g_y)}^{C_y(g_x,g_y)}\frac{1}{y}\dd y,
\end{split}
\]
\[
\pdv{g_y}\widehat{m}(g_x, g_y)=\frac{3}{\pi}\int_{A_y(g_x,g_y)}^{B_y(g_x,g_y)}\pdv{g_y}F_{4,2}(y,g_x,g_y)\dd y.
\]
\par
We have 
\begin{equation}\label{ineq: estimation of m hat 4 by gx}
0<\pdv{g_x}\widehat{m}(g_x, g_y)= \frac{3}{\pi}\int_{A_y(g_x,g_y)}^{C_y(g_x,g_y)}\frac{1}{y}\dd y    \leq\frac{3}{\pi}\int_{\frac{\sqrt{3}}{2}}^{C_y(g_x,g_y)}\frac{1}{y}\dd y=\frac{3}{\pi}\log(-\frac{2}{\sqrt{3}g_x}).
\end{equation}
And similar to the estimation in inequality \eqref{ineq: estimation of m hat 2 by gy}, we have
\begin{equation}\label{ineq: estimation of m hat 4 by gy}
0<\pdv{g_y}\widehat{m}(g_x, g_y)=\frac{3}{\pi}\int_{A_y(g_x,g_y)}^{B_y(g_x,g_y)}\pdv{g_y}F_{4,2}(x,g_x,g_y)\dd y=\frac{3}{\pi}\eval{\tan ^{-1}\left(\frac{g_y x}{\sqrt{1-g_y^2 x^2}}\right)}_{A_y(g_x,g_y)}^{B_y(g_x,g_y)}\leq 3.
\end{equation}


\noindent\textbf{Case 5: $g_x\in (b_6(g_y),b_5(g_y))$}\par
In this case, the overlap region is depicted in Figure \ref{fig:case5}.
\begin{figure}[h]
\includegraphics[scale=0.3]{Case_5.eps}
\includegraphics[scale=0.3]{Case_5_zoomed.eps}
\centering
\caption{Case 5}\label{fig:case5}
\end{figure}\par

Since the ellipse $E$ is convex, we have 
\[
E_{y,lower}(x,g_x,g_y)\leq \frac{B_y(g_x,g_y)}{L_x(B_y(g_x,g_y),g_x,g_y)}x=-\frac{\sqrt{3}}{\sqrt{3}g_x+g_y}x.
\]
Therefore, the solution of the equation $-\frac{\sqrt{3}}{\sqrt{3}g_x+g_y}x=\sqrt{1-x^2}$ gives a lower bound of $A_x(g_x,g_y)$,
\[
A_x(g_x,g_y)\geq  \frac{1}{\sqrt{\frac{3}{(\sqrt{3}g_x+g_y)^2}+1}}.
\]
Since $\sqrt{3}g_x+g_y\in (-2g_y+g_y,-\frac{\sqrt{15}}{2}g_y+g_y)$, we have 
\[
\frac{ (\sqrt{3}g_x+g_y)^2}{3}\geq \frac{(1-\frac{\sqrt{15}}{2})^2}{3}g_y^2>\frac{1}{4}g_y^2,
\]
and hence
\[
A_x(g_x,g_y)\geq \frac{1}{\sqrt{\frac{4}{g_y^2}+1}}\geq \frac{g_y}{4}.
\]\par
The lower bound of $B_x(g_x,g_y)$ can be estimated by
\[
\begin{split}
B_x(g_x,g_y)=&-\frac{\sqrt{3}g_x+g_y}{2g_y}\geq \frac{1}{4}(\sqrt{15}-2).
\end{split}
\]

For $g_x\in (b_6(g_y),b_5(g_y))$, $\widehat{m}$ is
\[
\begin{split}
\widehat{m}(g_x,g_y)=&\frac{3}{\pi}\int_{A_x(g_x,g_y)}^{\frac{1}{2}}\int_{\sqrt{1-x^2}}^{E_{y,lower}(x,g_x,g_y)}\frac{1}{y^2}\dd y\dd x+\frac{3}{\pi}\int_{B_x(g_x,g_y)}^{\frac{1}{2}}\int_{E_{y,upper}(x,g_x,g_y)}^{L_y(y,g_x,g_y)}\frac{1}{y^2}\dd y\dd x\\
=&-\frac{3}{\pi}\int_{A_x(g_x,g_y)}^{\frac{1}{2}}\frac{1}{E_{y,lower}(x,g_x,g_y)}-\frac{1}{\sqrt{1-x^2}}\dd x-\frac{3}{\pi}\int_{B_x(g_x,g_y)}^{\frac{1}{2}}\frac{1}{L_y(x,g_x,g_y)}-\frac{1}{E_{y,upper}(x,g_x,g_y)}\dd x\\
=&\frac{3}{\pi}\int_{A_x(g_x,g_y)}^{\frac{1}{2}}F_{5,1}(x,g_x,g_y)\dd x+\frac{3}{\pi}\int_{B_x(g_x,g_y)}^{\frac{1}{2}}F_{5,2}(x,g_x,g_y)\dd x.
\end{split}
\]

It is easy to compute that
\[
\begin{cases}
\int \pdv{g_x}F_{5,1}(x,g_x,g_y)\dd x=\pdv{g_x}\int F_{5,1}(x,g_x,g_y)\dd x+C,\\
\int \pdv{g_y}F_{5,1}(x,g_x,g_y)\dd x=\pdv{g_y}\int F_{5,1}(x,g_x,g_y)\dd x+C,\\
\int \pdv{g_x}F_{5,2}(x,g_x,g_y)\dd x=\pdv{g_x}\int F_{5,2}(x,g_x,g_y)\dd x+C,\\
\int \pdv{g_y}F_{5,2}(x,g_x,g_y)\dd x=\pdv{g_y}\int F_{5,2}(x,g_x,g_y)\dd x+C.\\
\end{cases}
\]

Since
\[
F_{5,1}(A_x(g_x,g_y))=0,\quad F_{5,2}(B_x(g_x,g_y))=0,
\]
we have
\[
\pdv{g_x}\widehat{m}(g_x, g_y)=\frac{3}{\pi}\int_{A_x(g_x,g_y)}^{\frac{1}{2}}\pdv{g_x}F_{5,1}(x,g_x,g_y)\dd x+\frac{3}{\pi}\int_{B_x(g_x,g_y)}^{\frac{1}{2}}\pdv{g_x}F_{5,2}(x,g_x,g_y)\dd x,\\
\]
\[
\pdv{g_y}\widehat{m}(g_x, g_y)=\frac{3}{\pi}\int_{A_x(g_x,g_y)}^{\frac{1}{2}}\pdv{g_y}F_{5,1}(x,g_x,g_y)\dd x+\frac{3}{\pi}\int_{B_x(g_x,g_y)}^{\frac{1}{2}}\pdv{g_y}F_{5,2}(x,g_x,g_y)\dd x.\\
\]
We have 
\[
\pdv{g_x}F_{5,1}(x,g_x, g_y)=\frac{-\frac{g_x}{\sqrt{g_x^2-g_y^2 x (x+2)}}+x+1}{x (x+2)}=\frac{\frac{1}{\sqrt{1-b(g_x,g_y) x (x+2)}}+x+1}{x (x+2)}>0.
\]
Since $b(g_x,g_y)=\frac{g_y^2}{g_x^2}\in (\frac{3}{4},\frac{4}{5})\subset (0,\frac{4}{5})$, we have $ 1+x-\sqrt{1-bx(x+2)}>0$ and hence
\[
\begin{split}
\int_{A_x(g_x,g_y)}^{\frac{1}{2}}\pdv{g_x}F_{5,1}(x,g_x,g_y)\dd x\leq&\int_{A_x(g_x,g_y)}^{\frac{1}{2}}\frac{\frac{1}{\sqrt{1-b(g_x,g_y) x (x+2)}}+x+1}{x (x+2)}\dd x\\
=&\eval{\log(1+x-\sqrt{1-b(g_x,g_y)x(x+2)})}_{A_x(g_x,g_y)}^{\frac{1}{2}}.
\end{split}
\]\par
Let $f(b,x)=1+x-\sqrt{1-bx(x+2)}$. For $b>0$ and $x\in (0,\frac{1}{2})$, we have 
\[
{\pdv{f}{b}}(b,x)=\frac{x (x+2)}{2 \sqrt{1-b x (x+2)}}>0,\quad {\pdv{f}{x}}(b,x)=\frac{b(x+1)}{\sqrt{1-b x (x+2)}}+1>0.
\]
So we have
\[
\begin{split}
\eval{\log(f(b(g_x,g_y),x))}_{A_x(g_x,g_y)}^{\frac{1}{2}}\leq &\log(f(\frac{4}{5},\frac{1}{2}))-\log(f(\frac{3}{4},\frac{g_y}{4}))\\
=&\log (12)-\log \left(2 g_y-\sqrt{64-3 g_y (g_y+8)}+8\right)\\
=&\left(\log \left(\frac{24}{7}\right)+\log (\frac{1}{g_y})\right)-\frac{3 g_y}{32}+O\left(g_y^2\right).
\end{split}
\]
Therefore,
\[
\begin{split}
\pdv{g_x}F_{5,2}(x,g_x,g_y)=&\frac{2}{1+2x}-\frac{1+x-\frac{1}{\sqrt{1-b(g_x,g_y) x (x+2)}}}{x (x+2)}\\
\geq& \frac{2}{1+2x}-\frac{1+x-1}{x (x+2)}>0.
\end{split}
\]
Thus, we have 
\[
\begin{split}
0<\int_{B_x(g_x,g_y)}^{\frac{1}{2}}\pdv{g_x}F_{5,2}(x,g_x,g_y)\dd x=& \int_{B_x(g_x,g_y)}^{\frac{1}{2}}\frac{2}{1+2x}-\frac{1+x-\frac{1}{\sqrt{1-b(r,\theta) x (x+2)}}}{x (x+2)}\dd x\\
=&\eval{\left[ \log(f(b(r,\theta),x))+\log(\frac{1+2x}{x(x+2)}) \right]}_{B_x(g_x,g_y)}^{\frac{1}{2}}\\
\leq&\log(f(\frac{4}{5},\frac{1}{2}))-\log(f(\frac{3}{4},\frac{1}{4} \left(\sqrt{15}-2\right)))\\
=&\log \left(\frac{12}{2 \sqrt{15}-\sqrt{55-12 \sqrt{15}}+4}\right).
\end{split}
\]
The last inequality holds since $\log(\frac{1+2x}{x(x+2)})$ decreases in $(0,\frac{1}{2})$. Therefore, 
\begin{equation}\label{ineq: estimation of m hat 5 by gx}
0<\pdv{g_x}\widehat{m}(g_x,g_y)\leq \frac{3}{\pi}\log \left(\frac{288}{7(2 \sqrt{15}-\sqrt{55-12 \sqrt{15}}+4)}\right)+\frac{3}{\pi}\log(\frac{1}{g_y})-\frac{9g_y}{32\pi}+O(g_y^2)
\end{equation}
Also, 
\[
\pdv{g_y}F_{5,2}(x,g_x,g_y)=\pdv{g_y}F_{5,1}(x,g_x,g_y)=\frac{1}{\sqrt{(\frac{g_x}{g_y})^2-x(x+2)}}=\pdv{g_y}F_{2}(x,g_x,g_y).
\]
Therefore, using estimation \eqref{ineq: estimation of m hat 2 by gy}, we have 
\[
0<\int_{A_x(g_x,g_y)}^{\frac{1}{2}} \pdv{g_y}F_{5,1}(x,g_x,g_y)\dd x\leq \pi,
\]
and
\[
0<\int_{B_x(g_x,g_y)}^{\frac{1}{2}} \pdv{g_y}F_{5,2}(x,g_x,g_y)\dd x\leq \pi.
\]
Therefore, we have
\begin{equation}\label{ineq: estimation of m hat 5 by gy}
0<\pdv{g_y}\widehat{m}(g_x, g_y)\leq 6.
\end{equation}

\noindent\textbf{Case 6: $g_x\in (b_7(g_y),b_6(g_y))$}\par
In this case the overlap region is depicted in Figure \ref{fig:case6}.
\begin{figure}[h]
\includegraphics[scale=0.3]{Case_6.eps}
\centering
\caption{Case 6}\label{fig:case6}
\end{figure}\par 
For $g_x\in (b_7(g_y),b_6(g_y))$, 
\[
\begin{split}
\widehat{m}(g_x,g_y)=\frac{3}{\pi}\int_{A_x(g_x,g_y)}^{\frac{1}{2}}F_{5,1}(x,g_x,g_y)\dd x.
\end{split}
\]
We have 
\[
\pdv{g_x}\widehat{m}(g_x, g_y)=\int_{A_x(g_x,g_y)}^{\frac{1}{2}}\pdv{g_x}F_{5,1}(x,g_x,g_y)\dd x,
\]
\[
\pdv{g_y}\widehat{m}(g_x, g_y)=\int_{A_x(g_x,g_y)}^{\frac{1}{2}}\pdv{g_y}F_{5,1}(x,g_x,g_y)\dd x.
\]

Since $g_x\in (b_7(g_y),b_6(g_y))\subset  (b_7(g_y),b_5(g_y))$, from Case 5, we know $A_x(g_x,g_y)>  \frac{g_y}{4}$ and $b(g_x,g_y)=\frac{g_y^2}{g_x^2}\in (0,\frac{4}{5})$. Therefore, we have  
\begin{equation}\label{ineq: estimation of m hat 6 by gx}
\begin{split}
0<\pdv{g_x}\widehat{m}(g_x,g_y)\leq &\frac{3}{\pi} \int_{A_x(g_x,g_y)}^{\frac{1}{2}}\pdv{g_x}F_{5,1}(x,g_x,g_y)\dd x\\
\leq &\frac{3}{\pi}(\log(f(\frac{4}{5},\frac{1}{2}))-\log(f(0,\frac{g_y}{4})))=\frac{3}{\pi}\log (6)+\frac{3}{\pi}\log (\frac{1}{g_y}).
\end{split}
\end{equation}

Also, like in Case 5, we have
\begin{equation}\label{ineq: estimation of m hat 6 by gy}
0<\pdv{g_y}\widehat{m}(g_x, g_y)=\frac{3}{\pi}\int_{B_x(g_x,g_y)}^{\frac{1}{2}} \pdv{g_y}F_{5,1}(x,g_x,g_y)\dd x\leq 3.
\end{equation}


\noindent\textbf{Case 7: $g_x\in (-\infty,b_7(g_y))$}\par
In this case the overlap region is depicted in Figure \ref{fig:case7}.
\begin{figure}[h]
\includegraphics[scale=0.3]{Case_7.eps}
\centering
\caption{Case 7}\label{fig:case7}
\end{figure}\par
We have $\widehat{m}(g_x,g_y)=0$ and thus $\pdv{g_x}\widehat{m}(g_x, g_y)=\pdv{g_y}\widehat{m}(g_x, g_y)=0$.\par

\noindent\textbf{Case 8: $g_x\in (-\frac{2}{\sqrt{3}},0)$}\par
In this case the overlap region is depicted in Figure \ref{fig:case8}.
\begin{figure}[h]
\includegraphics[scale=0.3]{Case_8.eps}
\centering
\caption{Case 8}\label{fig:case8}
\end{figure}
\par 



Let $D_x(g_x,g_y)$ be the $x$-coordinate of the intersection point of the line $L$ and the circle $x^2+y^2=1$, i.e., 
\[
L_y(D_x(g_x,g_y),g_x,g_y)=\sqrt{1-D_x(g_x,g_y)^2}.
\]
This yields
\[
D_x(g_x,g_y)=-\frac{g_x \sqrt{4 g_x^2+3}+1}{2 g_x^2+2}.
\]
For $g_x\in (-\frac{2}{\sqrt{3}},0)$,
\[
\begin{split}
\widehat{m}(g_x,g_y)=&\frac{3}{\pi}\int_{D_x(g_x,g_y)}^{\frac{1}{2}}\int_{\sqrt{1-x^2}}^{L_y(x,g_x,g_y)}\frac{1}{y^2}\dd y\dd x=-\frac{3}{\pi}\int_{D_x(g_x,g_y)}^{\frac{1}{2}}\frac{1}{L_y(x,g_x,g_y)}-\frac{1}{\sqrt{1-x^2}}\dd x\\
=&\frac{3}{\pi}\int_{D_x(g_x,g_y)}^{\frac{1}{2}}F_8(x,g_x,g_y)\dd x.
\end{split}
\]


Since $F_8(D_x(g_x,g_y),g_x,g_y)=0$, we have
\[
\pdv{g_x}\widehat{m}(g_x, g_y)=\pdv{g_x}\int_{D_x(g_x,g_y)}^{\frac{1}{2}}F_8(x,g_x,g_y)\dd x=\eval{\log(1+2x)}_{D_x(g_x,g_y)}^{\frac{1}{2}}=\log \left(\frac{2 \left(g_x^2+1\right)}{g_x \left(g_x-\sqrt{4 g_x^2+3}\right)}\right),
\]
\[
\pdv{g_y}\widehat{m}(g_x, g_y)=\pdv{g_y}\int_{D_x(g_x,g_y)}^{\frac{1}{2}}F_8(x,g_x,g_y)\dd x=0.
\]
For $g_x\in (-\frac{2}{\sqrt{3}},0)$, we have $-\frac{2}{\sqrt{3}}<\frac{2 \left(g_x^2+1\right)}{g_x-\sqrt{4 g_x^2+3}}<-1$. So we have
\begin{equation}\label{ineq: estimation of m hat 8 by gx}
\pdv{g_x}\widehat{m}(g_x, g_y)\leq\log(-\frac{2}{\sqrt{3}g_x}).
\end{equation}
Combining all estimations of $\pdv{g_x}\widehat{m}(g_x, g_y)$ and $\pdv{g_x}\widehat{m}(g_x, g_y)$ in Case 1 to Case 8, the proof of Lemma \ref{Lem: dereasing ratio of derivative of m hat} is finished.
\refstepcounter{subsection}
\subsection*{\thesubsection\quad Proof of Theorem \ref{thm: decay of Hilbert transform on SL2(R)}}
\phantomsection
\label{Sec: Proof of the main theorem}

First we prove the integrability of $\dv{t}\widetilde{\widetilde{m}}(k_0a\exp(tX_j))$, i.e., the integrability of $2e^{2t}g_y\pdv{g_y}\widehat{m}(g_x,e^{2t}g_y)$ and $g_y\pdv{g_x}\widehat{m}(g_x+tg_y,g_y)$ for small $t$. Since $g_y(r,\theta)\leq \max(\frac{1}{r^2},r^2)$, by Lemma \ref{Lem: dereasing ratio of derivative of m hat}, we only need to prove the integrability of $\log(\frac{1}{\abs{g_x(r,\theta)+t g_y(r,\theta)}})$ and $\log(\frac{1}{\abs{g_x(r,\theta)}})$.\par
We have 
\[
\abs{g_x(r,\theta)+tg_y(r,\theta)}=\frac{\abs{\left(r^4-1\right) \sin \theta \cos\theta+r^2 t}}{r^4 \sin ^2\theta+\cos ^2\theta}\geq \frac{1-r^4}{2}\abs*{\sin (2\theta)-\frac{2r^2 t}{1-r^4}}
\]
for $r$ close to $0$. Let $\sin(2\omega)=\frac{2r^2 t}{1-r^4}$, we have 
\[
\begin{split}
&\int_{-\frac{\pi}{2}}^{\frac{\pi}{2}}\log(\frac{1}{\abs{g_x(r,\theta)+t g_y(r,\theta)}})\dd\theta\\
\leq& \pi\log(\frac{2}{1-r^4})-\int_{-\frac{\pi}{2}}^{\frac{\pi}{2}}\log(\abs{\sin(2\theta)-\sin(2\omega)})\dd\theta\\
=&\pi\log(\frac{2}{1-r^4})-\log(2)-\int_{-\frac{\pi}{2}}^{\frac{\pi}{2}}\log(\abs{\cos(\theta+\omega)})\dd\theta-\int_{-\frac{\pi}{2}}^{\frac{\pi}{2}}\log(\abs{\sin(\theta-\omega)})\dd\theta\\
=&\pi\log(\frac{2}{1-r^4})-\log(2)-\int_{-\frac{\pi}{2}}^{\frac{\pi}{2}}\log(\abs{\cos\theta})\dd\theta-\int_{-\frac{\pi}{2}}^{\frac{\pi}{2}}\log(\abs{\sin\theta})\dd\theta\\
=&\pi\log(\frac{2}{1-r^4})-\log(2)+2\pi\log(2).\\
\end{split} 
\]
Let $t=0$, we have $\omega=0$ and hence
\[
\int_{-\frac{\pi}{2}}^{\frac{\pi}{2}}\log(\frac{1}{\abs{g_x(r,\theta)}})\dd\theta\leq\pi\log(\frac{2}{1-r^4})-\log(2)+2\pi\log(2).
\]
Therefore, by dominated convergence theorem, we have 
\begin{equation}
\begin{cases}
\partial_{X_1} \widetilde{m}(a)=\frac{1}{\pi}\int_{-\frac{\pi}{2}}^{\frac{\pi}{2}} 2g_y(r,\theta)\pdv{g_y}\widehat{m}(g_x(r,\theta),g_y(r,\theta))\dd \theta,\\
\partial_{X_2} \widetilde{m}(a)=\frac{1}{\pi}\int_{-\frac{\pi}{2}}^{\frac{\pi}{2}} g_y(r,\theta)\pdv{g_x}\widehat{m}(g_x(r,\theta),g_y(r,\theta))\dd \theta.
\end{cases}
\end{equation}
The ratio $\frac{g_x(r,\theta)}{g_y(r,\theta)}=\frac{(r^4-1)\cos\theta\sin\theta}{r^2}$ indicates that as $\theta$ varies from $-\frac{\pi}{2}$ to $\frac{\pi}{2}$, the ellipse $E$ and line $L$ first rotate counter-clockwise, then clockwise, and finally counter-clockwise again when $r$ is close to $0$. The transformation $(r,\theta) \mapsto (g_x(r,\theta),g_y(r,\theta))$ is invertible for $\theta \in \left(-\frac{\pi}{4}, \frac{\pi}{4}\right)$. Figure \ref{fig: rotate of theta} illustrates these changes as $\theta$ increases.
\begin{figure}[h]
\centering
\includegraphics[scale=0.4]{rotate_1.eps}
\includegraphics[scale=0.4]{rotate_2.eps}
\includegraphics[scale=0.4]{rotate_3.eps}
\includegraphics[scale=0.4]{rotate_4.eps}
\includegraphics[scale=0.4]{rotate_5.eps}
\caption{The illustration of $A(g_x(r,\theta),g_y(r,\theta))\cap \mathcal{F}$ as $\theta$ increases.}\label{fig: rotate of theta}
\end{figure}\par


Solving the boundaries $g_x(r,\theta)=b_2(g_y(r,\theta))$, $g_x(r,\theta)=b_7(g_y(r,\theta))$ and $g_x(r,\theta)=b_8(g_y(r,\theta))$ for $r$ close to $0$, we obtain the corresponding boundaries 
\[
\begin{cases}
\theta_2(r)=-\frac{\pi}{6},\\
\theta_7(r)=\cos^{-1}\left(\sqrt{\frac{16r^4-3\sqrt{9r^8-66r^4+9}-12}{28(r^4-1)}}\right),\\
\theta_8(r)=\tan^{-1}\left(\frac{4\sqrt{3}}{-3r^4+\sqrt{9r^8-66r^4+9}+3}\right),
\end{cases}
\]
and 
\[
\theta_7(0)=\frac{\pi}{6}, \quad \theta_8(0)=\frac{\pi}{2}.
\]

For $\theta\in (-\frac{\pi}{4},\frac{\pi}{4})$ and $r$ close to $0$, we have estimations:
\[
\abs{g_x(r,\theta)}=\frac{\abs{(r^4-1)\cos\theta \sin\theta}}{\cos^2\theta +r^4\sin^2\theta}\in (\frac{\abs{\sin(2\theta)}}{4},\abs{\sin(2\theta)}),
\]
\[
g_y(r,\theta)=\frac{r^2}{\cos^2\theta+r^4\sin^2\theta}\in (r^2,2r^2).
\]

For $\theta\in (\theta_8(r),\frac{\pi}{2})$ and $r$ close to $0$, we have 
\[
\begin{split}
g_x(r,\theta)=&\frac{\left(r^4-1\right) \sin\theta \cos\theta}{r^4 \sin ^2\theta+\cos ^2\theta}=\frac{\left(r^4-1\right)}{r^4 \tan\theta+\cot\theta}\in\left( -\frac{1}{r^4\tan\theta},-\frac{1}{4r^4\tan\theta} \right),
\end{split}
\]
by the estimation $r^4\tan\theta \geq r^4 \tan(\theta_8(r))\to \frac{\sqrt{3}}{2}$ as $r\to 0$. And
\[
g_y(r,\theta)=\frac{r^2}{\cos^2\theta+r^4\sin^2\theta}\in \left( \frac{1}{2r^2},\frac{2}{r^2} \right),
\]
by estimations $\sin\theta\geq \sin(\theta_8(r))\to 1$ as $r\to 0$ and $\cos^2\theta\leq \cos^2(\theta_8(r))=O(r^8)$.\par
By the above estimations of $g_x(r,\theta)$ and $g_y(r,\theta)$ and Lemma \ref{Lem: dereasing ratio of derivative of m hat}, we have 
\[
\begin{split}
&\int_{-\frac{\pi}{2}}^{\frac{\pi}{2}}g_y(r,\theta)\pdv{g_x}\widehat{m}(g_x(r,\theta),g_y(r,\theta))\dd\theta\\
=&\int_{-\frac{\pi}{2}}^{\theta_7(r)}g_y(r,\theta)\pdv{g_x}\widehat{m}(g_x(r,\theta),g_y(r,\theta))\dd\theta+\int_{\theta_8(r)}^{\frac{\pi}{2}}g_y(r,\theta)\pdv{g_x}\widehat{m}(g_x(r,\theta),g_y(r,\theta))\dd\theta\\
\lesssim & r^2\left( \int_{-\frac{\pi}{2}}^{\theta_7(r)}\log(\frac{1}{\sin(2\theta)})+\log(\frac{1}{r^2})\dd\theta \right)+\frac{1}{r^2}\left(  \int_{\theta_8(r)}^{\frac{\pi}{2}}\log(4r^4\tan\theta)\dd\theta \right)\\
\lesssim & r^2\log(\frac{1}{r^2})=O(r)
\end{split}
\]
and 
\[
\int_{-\frac{\pi}{2}}^{\frac{\pi}{2}}g_y(r,\theta)\pdv{g_y}\widehat{m}(g_x(r,\theta),g_y(r,\theta))\dd\theta=\int_{-\frac{\pi}{2}}^{\theta_7(r)}g_y(r,\theta)\pdv{g_x}\widehat{m}(g_x(r,\theta),g_y(r,\theta))\dd\theta\leq 12\pi r^2.
\]
Let $f_j(r)=\partial_{X_j}\widetilde{m}(a)$. Since $\partial_{X_j}\widetilde{m}(a)$ is left-$K$-invariant, we have $f_j(r)=f_j(\frac{1}{r})$.
By $\norm{kak'}=\norm{a}=\max(r,\frac{1}{r})$, we have 
\[
\limsup_{\norm{kak'}\to \infty}\norm{kak'}\abs{ \partial_{X_j} \widetilde{m}(kak')}\leq \limsup_{\norm{a}\to \infty}\norm{a}(\abs{\partial_{X_1} \widetilde{m}(a)}+\abs{\partial_{X_2} \widetilde{m}(a)})=\limsup_{r\to 0^+}\frac{1}{r}(\abs{f_1(r)}+\abs{f_2(r)}).
\]
Therefore, Theorem \ref{thm: decay of Hilbert transform on SL2(R)} is proved since $f_i(r)=O(r)$ as $r\to 0^+$.


\begin{remark}
By a more careful analysis, $ \int_{-\frac{\pi}{2}}^{\frac{\pi}{2}}g_y(r,\theta)\pdv{g_x}\widehat{m}(g_x(r,\theta),g_y(r,\theta))\dd\theta$ is also in the order of $O(r^2)$.
\end{remark}

\begin{remark}\label{Rmk: non-existence of second order}
Take $X_i=X_j=X_2$. By mean value theorem we have 
\[
\begin{split}
  \partial_{X_2}\partial_{X_2} \widetilde{m}(a)=&\eval{\dv{t}}_{t=0}\partial_{X_2} \widetilde{m}(a\exp(tX_2))\\
  =&\eval{\dv{t}}_{t=0}\eval{\dv{l}}_{l=0}\widetilde{m}(a\exp(tX_2)\exp(lX_2))\\
  =&\frac{1}{\nu(K_+)}\lim_{\delta\to 0}\lim_{\varepsilon\to 0}\int_{K_+}\eval{\dv{t}}_{t=\delta}\eval{\dv{l}}_{l=\varepsilon}\widetilde{\widetilde{m}}(k_0a\exp(tX_2)\exp(lX_2))\dd\nu(k_0)\\
  =&\frac{1}{\pi}\lim_{\delta\to 0}\lim_{\varepsilon\to 0}\int_{-\frac{\pi}{2}}^{\frac{\pi}{2}}g_y(r,\theta)^2\pdv[2]{g_x}\widehat{m}(g_x(r,\theta)+(\delta+\varepsilon)g_y(r,\theta),g_y(r,\theta))\dd\theta.\\
\end{split}
\]
We will show that there is an interval $I\subset (-\frac{\pi}{2},\frac{\pi}{2})$ such that
\[
g_y(r,\theta)^2\pdv[2]{g_x}\widehat{m}(g_x(r,\theta)+(\delta+\varepsilon)g_y(r,\theta),g_y(r,\theta))>0,
\]
and 
\[
\int_I g_y(r,\theta)^2\pdv[2]{g_x}\widehat{m}(g_x(r,\theta),g_y(r,\theta))=\infty.
\]
Therefore, by Fatou's lemma we have 
\[
\lim_{\delta\to 0}\lim_{\varepsilon\to 0}\int_{I}g_y(r,\theta)^2\pdv[2]{g_x}\widehat{m}(g_x(r,\theta)+(\delta+\varepsilon)g_y(r,\theta),g_y(r,\theta))\dd\theta   \geq \int_I g_y(r,\theta)^2\pdv[2]{g_x}\widehat{m}(g_x(r,\theta),g_y(r,\theta))=\infty.
\]
So $\partial_{X_2}\partial_{X_2} \widetilde{m}(a)$ is infinity or does not exist.

We have 
\[
\begin{split}
\pdv[2]{g_x}\widehat{m}(g_x, g_y)=&-\frac{2}{1+2D_x(g_x,g_y)}D_x^{(1,0)}(g_x,g_y)=\frac{\frac{g_x}{\sqrt{4 g_x^2+3}}-1}{g_x^3+g_x}.
\end{split}
\]
For $g_x(r,\theta)\in (-\frac{2}{\sqrt{3}},0)$, we have $4 \left(\sqrt{3}-2\right)\leq\frac{\frac{g_x}{\sqrt{4 g_x^2+3}}-1}{g_x^2+1}\leq -\frac{3}{5}$. So 
\[
\begin{split}
-\frac{3}{5g_x}\leq \pdv[2]{g_x}\widehat{m}(g_x, g_y)\leq \frac{4 \left(\sqrt{3}-2\right)}{g_x}.
\end{split}
\]

Therefore, we have 
\[
\begin{split}
\int_{\theta_8(r)}^{\frac{\pi}{2}}g_y(r,\theta)^2 \pdv[2]{g_x}\widehat{m}(g_x(r,\theta),g_y(r,\theta))\dd \theta\geq &\frac{3}{5}\int_{\theta_8(r)}^{\frac{\pi}{2}}\frac{r^4\tan\theta}{4r^4}\dd\theta\\
=&\infty.
\end{split}
\]
\end{remark}

