\title{RALLY: Role-Adaptive LLM-Driven Yoked Navigation for Agentic UAV Swarms}

\author{Ziyao Wang, Rongpeng Li, Sizhao Li, Yuming Xiang, Haiping Wang, Zhifeng Zhao, and Honggang Zhang
