% Both policies execute low-level controllers toward selected goals $g_i^t$.
For agent $i$, the action-value function at time $t$ is: 
\begin{equation}
\label{def:value_functions}
\begin{aligned}
Q_i(\bm{o}_i^t, \bm{a}_i^t) & = \mathbb{E}\left[\sum_{t'=t}^{\infty} \gamma^{t'-t}\,R(\bm{s}^{t'},\bm{a}^{t'}) \;\middle|\; \bm{o}_i^t,\bm{a}_i^t \right] \\& = \mathbb{E}\left[\sum_{t'=t}^{\infty} \gamma^{t'-t}\,R(\bm{s}^{t'},\bm{a}^{t'}) \;\middle|\; \bm{o}_i^t,k_i^t,g_i^t \right].
\end{aligned}
\end{equation}
For global state $\bm{s}^t$ and all agents' goal decisions $\bm{g}^t:=(g_1^t,\cdots,g_N^t)$, the global value function $Q_\text{tot}$ is defined by a mixing network $f$, which will be detailed in \ref{sec_rmix}:
\begin{equation}
    % Q_{\text{tot}}(s^t,g_1,\dots,g_N) = f(Q_1, Q_2, \dots, Q_N;\;s^t\bigr),
     Q_{\text{tot}}(\bm{s}^t,\bm{a}) = f(Q_1, Q_2, \dots, Q_N;\;\bm{s}^t,\bm{a}^t\bigr).
\end{equation}
% where $f$ is a monotonic mixing network parameterized by a hypernetwork, satisfying
\end{definition}
\begin{assumption}[Monotonic Value Factorization]
    \label{as:monotonic}
    Under a monotonic value factorization \cite{QMIX}, 
    every weight in $f$ is constrained to be non-negative, which guarantees the monotonicity property:  
\begin{equation} 
\label{def:monotonic}
\frac{\partial Q_{\text{tot}}(\bm{s}^t, \bm{g})}{\partial Q_i} \geq 0, \quad \forall i.
\end{equation} 
% and the expected return for policy $\bm{\pi}$ is:
% \begin{equation}
%     J(\bm{\pi}) = \mathbb{E}\left[\sum_{t=0}^\infty \gamma^t\,R(s^t,a^t)\right],
% \end{equation}
% where $a^t$ depends on the selected goals $g_i^t$.
\end{assumption}
\begin{theorem}[Two-Stage Superiority]
    \label{thm:superiority}
Under Assmption \ref{as:monotonic}, the two-stage policy achieves strictly higher expected return:
\begin{equation}
    J(\bm{\pi}^{\text{two}}) > J(\bm{\pi}^{\text{one}}),
\end{equation}
provided there exists at least one reachable context where $\text{LLM}_{\text{cons}}$ improves upon $\widetilde{\text{LLM}}_\text{HC}$.
\end{theorem}
\begin{proof}[Proof]
For any $(\bm{o}_i^t, k_i^t)$, the two-stage consensus step selects:
\begin{equation}
g_i^*=\underset{g \in\mathcal{T}}{\operatorname{argmax}}\ Q_{i}\left(\bm{o}_{i}^{t}, k_{i}^{t}, g_i^t\right),
\end{equation}
by construction of $\text{LLM}_{\text{cons}}$. 
In contrast, the one-stage policy outputs $\tilde g_i = \widetilde{\text{LLM}}_\text{HC}(\bm{o}_i^t,k_i^t)$ without refinement. By optimality of $g_i^*$:
\begin{equation} 
Q_i(\bm{o}_i^t, k_i^t, g_i^*) \geq Q_i(\bm{o}_i^t, k_i^t, \tilde{g}_i), \end{equation}
with strict inequality when consensus improves the goal. 
Under Assmption \ref{as:monotonic}, 
increasing any individual agent' value $Q_i$ cannot decrease the total value,
% for any state $s^t$ and goal vector \bm{g}, we have 
% % enhancing any agent's $Q_i$ preserves or increases the joint value: 
