\subsection{Credit-Assignment Mechanism Based on Role-value Mixing Network}
\label{sec_rmix}
\begin{figure}[!t]
\centering
\includegraphics[width=1.0\columnwidth]{figs/RMIX.pdf}
\caption{The training of the RMIX-based role selection mechanism. Each UAV employs a fully distributed role selection policy, using local observation $o_i^t$ to selects role $k_i^t$, and computes corresponding $Q_i(\bm{o}_i^{t},k_i^t)$. These $Q_i$ are aggregated into the global action-value $\bm{Q}_\text{tot}$ via the RMIX network and stored in a prior offline experience replay buffer. Function evaluation cost is computed using the buffer data, followed by gradient backpropagation to update both the RMIX network and role selection policies.}
\label{RMIX}
\end{figure}
\begin{algorithm}[!ht]
\caption{Credit-Assignment Enhanced Intention Generation Strategy (RMIX)}
\label{alg:RMIX}
\begin{algorithmic}[1]
\REQUIRE Role candidate set $\mathcal{K} = \{\texttt{Commander}, \texttt{Coordinator}, \texttt{Executor}\}$, \\
\hspace{1.8em} RMIX parameters $\theta$, target network $\bar{\theta}$, \\
\hspace{1.8em} Discount factor $\gamma_{\text{rmix}}$, learning rate $\alpha$, batch size $b$, \\
\hspace{1.8em} Experience replay buffer $\mathcal{B}_R$.

\vspace{0.5em}
\STATE \textbf{Step 1: Offline Experience Collection via LLM}
\FOR{episode = 1 to $N_{\text{pre}}$}
    \STATE Initialize environment, observe $\{\bm{o}_i^t\}_{i=1}^n$;
    \FOR{each agent $i$}
        \STATE $k_{i_\text{GPT}} \leftarrow \bm{\pi}_{\text{GPT}}(\bm{o}_i^t)$; \hfill$\triangleright$ GPT assigns role
    \ENDFOR
    \STATE Execute actions, receive reward $R$, state $\bm{s}$;
    \STATE Store $\langle \bm{s}, \{\bm{o}_i, k_{i_\text{GPT}}\}, R \rangle$ into buffer $\mathcal{B}_R$;
\ENDFOR

\vspace{0.5em}
\STATE \textbf{Step 2: Online Cooperative RMIX Training}
\FOR{episode = 1 to $N_{\text{epoch}}$}
    \STATE Reset environment, observe $\{\bm{o}_i^0\}_{i=1}^N$;
    \FOR{$t = 0$ to $T - 1$}
        \FOR{each agent $i$}
            \STATE $Q_i(\bm{o}_i^t, k) \leftarrow \text{MLP}_\theta(\bm{o}_i^t)$;
            \STATE $k_i^t \leftarrow \arg\max_{k \in \mathcal{K}} Q_i(\bm{o}_i^t, k)$;
        \ENDFOR
        \STATE Execute roles $\{k_i^t\}$, receive $R^t$, $\bm{s}^{t+1}$, $\{\bm{o}_i^{t+1}\}$;
        \STATE Store $\langle \bm{s}^t, \{\bm{o}_i^t, k_i^t\}, R^t, \bm{s}^{t+1} \rangle$ into $\mathcal{B}_R$;

        \IF{$|\mathcal{B}_R| \geq b$}
            \STATE Sample batch $\{(\bm{s}^j, \{\bm{o}_i^j, k_i^j\}, R^j, \bm{s}^{j+1})\}_{j=1}^b$;
            % \STATE Compute targets: $y^j = R^j + \gamma_{\text{rmix}} \max_{\bm{k}'} \bar{Q}(\bm{s}^{j+1}, \bm{k}'; \bar{\theta})$
            \STATE Compute target values as follows:\\
            \(\vtop{\hbox{%
              $\displaystyle
                \begin{aligned}
                  y^j
                    &= R^j 
                     + \gamma_{\text{rmix}}\;\max_{\bm{k}'}\bar{Q}\bigl(\bm{s}^{j+1}, \bm{k}'; \bar{\theta}\bigr);
                \end{aligned}$
            }}\)

            \STATE Compute RMIX outputs $Q_{\text{tot}}$ according to Eq. \eqref{eq:rmix};
            % \STATE Compute RMIX outputs:
            % \STATE \quad $\bm{Q}^j \leftarrow [Q_1^j, \dots, Q_n^j]$
            % \STATE \quad $Q'_{\text{tot}} \leftarrow \text{ReLU}(|\bm{W}_1| \cdot \bm{Q}^j + \bm{b}_1)$ \hfill \\$\triangleright$ Monotonic mixing
            % \STATE \quad $Q_{\text{tot}} \leftarrow \text{ReLU}(\bm{W}_2 \cdot Q'_{\text{tot}} + \bm{b}_2)$

            \STATE Update: $\theta \leftarrow \theta - \alpha \nabla_\theta \sum_j (y^j - Q_{\text{tot}}^j)^2$;
            \STATE Periodically update target: $\bar{\theta} \leftarrow \tau \theta + (1 - \tau)\bar{\theta}$.
        \ENDIF
    \ENDFOR
\ENDFOR
\RETURN Trained RMIX network $\text{RL}_\text{HI}$ for decentralized role selection
\end{algorithmic}
\end{algorithm}
The underlying distributed nature of the DS-CEFC task makes a direct fine-tuning of LLM incompetent for reasonable multi-agent collaboration. 
%As noted earlier, LLM-driven agents struggle to make reasonable role selections in a decentralized setting and to drive neighborhood consensus. Moreover, the DS-CEFC task lacks a clear global optimum to serve as training labels, making it difficult to improve LLM cooperation through mere fine-tuning. 
As illustrated in Fig. \ref{RMIX}, each distributed agent $i$ feeds its current local observation $\bm{o}_i^t$, and computes the obtainable optimal role satisfying:
% acquired via communication and perception, into the role selection policy network $\pi_\text{HI}$. This network, implemented as a multilayer perceptron (MLP), outputs a $|\mathcal{K}|$-dimensional action-value vector $[Q(\bm{o}_i^{t},k_1^t),\ldots,Q(\bm{o}_i^{t},k_{|\mathcal{K}|}^t)]$. Agent $i$ then selects the role that maximizes$Q_{i}$:
\begin{equation}
k_i^t=\underset{k_{i}^{t} \in\mathcal{K}}{\operatorname{argmax}}\ Q_{i}\left(\bm{o}_{i}^{t}, k_{i}^{t} | \hat{g}_i^t\right).
\end{equation}
% \begin{equation}
% k_i^t=\underset{k_{i}^{t} \in\mathcal{K}}{\operatorname{argmax}}\ Q_{i}\left(\bm{o}_{i}^{t}, k_{i}^{t} \right).
% \end{equation}
%As shown, the optimal role choice at each time relies on the accuracy of the action-value function $Q(\bm{o}_i^{t},k_{i}^t)$ in estimating cumulative reward. However, 
By Eq. \eqref{def:value_functions}, in dynamic multi-agent adversarial tasks, instantaneous reward $R$ cannot directly reflect the contribution from the choice of role $k_{i}^{t}$. To address this issue, we propose an RMIX-assisted credit-assignment mechanism to evaluate each agent's role choices. % and training under the CTDE paradigm of MARL. 
Notably, considering the significant inference latency of LLM, which results in higher costs for acquiring training samples, we introduce a semi-offline learning approach to improve sample efficiency.
Similar to Curriculum Learning (CL)\cite{Wang2020ACS}, we first exploit the zero-shot capability of LLM (e.g., GPT-4o\cite{Hurst2024GPT4oSC}) via API to obtain its role assignment strategy $\bm{\pi}_{\text{GPT}}$. 
By interacting with the environment under local observation $\bm{o}_i^t$, the mid-layer policy $\bm{\pi}_{M}$ and the physical flight controller $\bm{\pi}_{L}$, we record GPT's preliminary role suggestions ${k}_{i_\text{GPT}}$ and store the related transition quadruple $\langle {\bm o}_{i},{k}_{i_\text{GPT}},\bm{s}',R\rangle$ into a replay buffer $\mathcal{B}_R$, where $\bm{s}'$ denotes the transitioned state. This offline data collection runs in parallel with LLM consensus reasoning, enabling RMIX to assist the LLM in understanding role assignments and reducing the cold-start overhead from ineffective exploration.

Inspired by \cite{QMIX}, RMIX aggregates individual role-value estimates $Q_i(\bm{o}_i^{t},k_i^t)$ into a global value $Q_\text{tot}$ via a two-layer Multi-Layer Perceptron (MLP). 
Let $\bm{Q}^t=[Q_1(\bm{o}_1^{t},k_1^t),\ldots,Q_N(\bm{o}_N^{t},k_{N}^t)]$.
A small hypernetwork conditioned on the global state $\bm{s}^t$ produces nonnegative weights, by enforcing:
\begin{equation}
Q_\text{tot}^{t}=\text{ReLU}\left(\bm{W}_{2}^\top\big(\text{ReLU}(\bm{W}_{1} \bm{Q}^t+\bm{b}_{1})\big)+{b}_{2}\right),
\label{eq:rmix}
\end{equation}
where the two nonnegative weight vectors $\bm{W}_{1} \in \mathbb{R}^{E \times N}$ and $\bm{W}_{2}\in \mathbb{R}^{E \times 1}$, while  biases $\bm{b}_{1} \in \mathbb{R}^{{E}\times{1}}$ and $b_{2} \in \mathbb{R}$, with $E$ denoting the hidden layer dimension of RMIX. $\text{ReLU}(\cdot)$ indicates the ReLU nonlinear activation function. Eq. \eqref{eq:rmix} ensures the monotonic mapping between $Q_\text{tot}^t$ and $\bm{Q}^t$, thus satisfying the Assumption \ref{as:monotonic}.

% Enforcing
% \begin{equation}
% h^t=\text{ReLU}\left(\bm{W}_{1} \bm{Q}^t+\bm{b}_{1}\right).
% \end{equation}
% A second nonnegative weight vector $\bm{W}_{2}\in \mathbb{R}^{E}$ and $\bm{b}_{2}$ yield the final global value
% \begin{equation}
% Q_{tot}^{t}=\text{ReLU}\left(\bm{W}_{2}h^{t}+\bm{b}_{2}\right)
% \end{equation}
% The $\text{ReLU}(\cdot)$ nonlinear activation function is to facilitating RMIX in capturing the nonlinear correlation between $\bm{Q}(\bm{o}_{t},k^t)$ and the global value function $Q_{tot}$. 
% Since the state information $s^t$ is mixed into $Q_{tot}^{t}$ through the super-network, it can fully utilize the state information to improve the system performance; if it is directly used as an input to the RMIX, $s^t$ will be mapped into a non-negative space due to the monotonic constraint, resulting in information loss. 


Subsequently, we proceed to the standard CTDE online training. RMIX jointly learns from both offline and newly collected online samples to continuously explore and refine cooperative behaviors among agents. 
Generally, RMIX can be solved by a classical Stochastic Gradient Descent (SGD) approach with the cost function of RMIX being formulated as:
\begin{equation}
L(\theta)=\sum_{i=1}^{|\mathcal{B}_R|}\left[\left( y_{i}^\text{tot}-Q_\text{tot}(\bm{s}^t,k^t; \theta,\hat{g}^t)\right)^{2}\right], %chktex 3
\end{equation}
where $\theta$ denotes the concatenation of $\bm{W}_{1}$, $\bm{W}_{2}$, $\bm{b}_{1}$ and $b_{2}$ while $|\mathcal{B}_R|$ denotes the number of samples sampled from the empirical memory $\mathcal{B}_R$. As an approximate estimation of the cumulative returns under the global state $\bm{s}^t$, $y^\text{tot}$ is given as:
\begin{equation}
y^\text{tot}=R^t+\gamma_\text{rmix} \max _{k^{\prime}} \bar{Q}\left(\bm{s}^{\prime},k^{\prime} ; \bar{\theta},\hat{g}^t\right),
\end{equation}
where for the transitioned state $\bm{s}^{\prime}$ and the taken action $k^{\prime}$, $\bar{Q}\left(\bm{s}^{\prime},k^{\prime}; \bar{\theta}\right)$ denotes the target network parameterized by $\bar{\theta}$ and $\gamma_\text{rmix}$ is the discount factor.

