\subsection{Context-Based LLM Fine-Tuning}
\begin{algorithm}[!t]
\caption{Context Transfer Enhanced Lightweight Large Model Consensus Inference Algorithm}
\label{alg:Lightweight}
\begin{algorithmic}[1]
\REQUIRE Task prompt $\text{X}_\text{task}$, prompt generator $\text{Y}(\bm{o}_i)$, \\
\hspace{0.2em} GPT‑4o API, target set $\mathcal{G}_a$, rewards $R$, \\
\hspace{0.2em} thresholds $\{\tau_r,L_{\min},L_{\max}\}$, weights $\{w_{1,g},\cdots, w_{4,g}\}$, \\
\hspace{0.2em} minimum samples $M$, batch size $B$, LoRA params $\psi$.

\STATE $\mathcal{B}_\text{LLM}\gets\emptyset$
\WHILE{$|\mathcal{B}_\text{LLM}|<M$}
  \STATE Observe $(\bm{o}_i)$;
  \STATE $(g_i^*,\mathscr{I}_i^*)\gets\text{GPT4o}(\text{X}_\text{task},\,\text{Y}(\bm{o}_i))$\;cf.\ Eq.~\eqref{human-mark};
  \STATE Append $(\bm{o}_i,k_i,g_i^*,\mathcal{I}_i^*,R)$ to $\mathcal{B}_\text{LLM}$;
\ENDWHILE

\STATE $\mathcal{B}_\text{fil}\!\gets\!\{x\in\mathcal{B}_\text{LLM}\mid \text{Check}(x)\ge1\}$\;cf.\ Eq.~\eqref{QualityEvaluation};

\FOR{epoch=1 \TO $N_{\mathrm{epoch}}$}
  \STATE Sample batch $\mathcal{B}\subset\mathcal{B}_\text{fil}$ of size $B$;
  \STATE Compute loss via Eq.~\eqref{LoraLoss};
  \STATE Update $\psi\gets\psi - \eta\nabla_\psi$;
\ENDFOR

\RETURN Fine‐tuned LLM$_\psi$
\end{algorithmic}
\end{algorithm}

