\section{Design of Reward Function}
In the DS-CEFC task, the reward function$R_t$ consists of the following five items:
\begin{itemize}{}{}
\item\textit{Formation reward:} without loss of generality, assume that the current cluster $\mathcal{N}$ forms $\chi_t$ detachments, denote the number of UAVs in each detachment $\mathcal{N}_k$ as$n_k$, $k\in \{1,\ldots, \chi_t\}$, and the number of UAVs in each detachment satisfies the constraint ${n}_{1}+\cdots+{n}_{\chi_t}=N$. Define $\mathcal{F}_{n_k}$ to denote the desired formation of the detachment $\mathcal{N}_k$, and the relative position of UAVs as $\bm{P}_k^t=\{\bm{p}_j^t-\bar{\bm{p}}^t|\forall j \in \mathcal{N}_k\}$, where $\bar{\bm{p}}^t$ denotes the center of $\mathcal{N}_k$. The formation reward is defined as the sum of the Hausdorff distances of each detachment from its expected formation:
\begin{equation}
R_{f}^{t} = -\sum_{k=1}^{\chi^{t}} d_{HD}(\mathcal{F}_{n_k}, \bm{P}^{t}_{k}) - \omega_l R_{f}^{t-1},
\end{equation}
where $R_{f}^{0}=0$, $\omega_l$ is the formation trend coefficient.

\item\textit{Goal Navigation Reward:} the Euclidean distance between the UAVs and each current goal point, weighted by urgency$\kappa_{\mathcal{T}}^{t}$, is weighted to sum the results as the goal navigation reward:
\begin{equation}
\label{eq:nareward}
    R_{n}^{t}=-\sum_{i\in \mathcal{N}} \sum_{\mathcal{T} \in \mathcal{T}}\kappa_{\mathcal{T}}^{t}\|\bm{p}_{i,\mathcal{T}}^{t}\|,
\end{equation}.
where $\bm{p}_{i,\mathcal{T}}^{t}$ denotes the distance of the UAV $i$ relative to the target area $\mathcal{T}$, and the urgency $\kappa_{\mathcal{T}}^{t}$ will be decreasing as the cluster of UAVs stays in the target area $\mathcal{T}$.
\begin{equation}
\label{decrease}
    \kappa^{t+1}_{\mathcal{T}} = \max \left ( \kappa^{t}_{\mathcal{T}} - \omega_d \sum_{k^*} \text{TC}_{k^*,\mathcal{T}}^{t}, 0 \right ),
\end{equation}
where $\kappa^{0}_{\mathcal{T}}=1$, $\omega_d$ is the decay factor and $\text{TC}_{k^*\to \mathcal{T}}^{t}$ is the task completion reward, as defined below.

\item\textit{Mission Completion Reward:}Whenever a subcluster$\mathcal{N}_k$ arrives within the target area and successfully maintains formation, it will be considered to be completing a downstream mission and will receive a Mission Completion Reward. 
\begin{equation} 
    \text{TC}_{k^*\to \mathcal{T}}^{t} =
    \begin{cases}
    n_{k^*} ,& \|\bar{\bm{p}}^{t}_{k^*,\mathcal{T}}\|<\delta_{task},d_{HD}(\mathcal{F}_{n_k}, \bm{P}^{t}_{k})<\delta_{err},\\
    0,&\text{otherwise}, 
    \end{cases}
\end{equation}
where $\delta_{task}$ is the radius of the target area and $\delta_{err}$ is the maximum tolerable formation error. 
The overall task completion reward is defined as a weighted summation of that reward and the target urgency$\kappa_{\mathcal{T}}^{t}$, the
\begin{equation}
\label{eq:taskreward}
    R_{tc}^{t} = \sum_{\mathcal{T} \in \mathcal{T}} \kappa_{\mathcal{T}}^{t} \sum_{k^*} \text{TR}_{k^*,\mathcal{T}}^{t},
\end{equation}

\item Penalty for being interfered: this paper defines a penalty given when an intelligent body is interfered by an adversary (the distance is less than a threshold), which makes the intelligent body consciously stay away from the adversary.
\begin{equation}
    R_{e}^t=-k_e\sum\nolimits_{i \in \mathcal{N}} (\| \bm{p}_i^t-\bm{p}_e^t \|<\delta _{safe}),
\end{equation}.
where $k_e$ is the avoidance reward coefficient and $\delta_{safe}$ is the jammed warning distance.

\item\textit{Collision Penalty:} in order to avoid collision of an intelligent body with an obstacle, let $\text{CR}_{i,j}^{t}$ denote the degree of danger of the intelligent body $i$ with respect to $j$, which is defined as a segmented function related to the smallest measurement of the distance sensor $\upsilon_{i,m}^{t}=\min (\upsilon_{i1}^{t},\ldots,\upsilon_{iM}^{t})$, the
\begin{equation} 
    \text{CR}_{i,j}^{t} =
    \begin{cases}
    \omega_{cr_1} (\delta _{s}-\upsilon_{i,m}^{t}) + C_1, & \upsilon_{i,m}^{t}<\delta _{s},\\
    \omega_{cr_2} (\delta_{a,c}-\upsilon_{i,m}^{t}) + C_2, & \delta _{s} < \upsilon_{i,m }^{t}<\delta_{a,c},\\
    0, & \upsilon_{i,m}^{t}>\delta _{a},
    \end{cases} \\
\end{equation}
where $\delta_{\text{s}}$ is the minimum safe distance, $\delta_{\text{a,c}}$ is the collision warning distance, and $\omega_{cr_1}$, $\omega_{cr_2}$, $C_1$, $C_2$  are non-negative constants. Let the set of obstacles be defined as $\mathcal{I}$ and the cluster collision penalty can be expressed as
\begin{equation}
    R_{c}^{t}=-\sum_{i\in \mathcal{N}}\sum_{j \ne i, j\in \mathcal{I}} \text{CR}_{i,j}^{t},
\end{equation}.

\end{itemize}

To summarize, the task completion of the DS-CEFC task at the $t$ moment is defined as
\begin{equation}
\label{eq:totalreward}
    R^{t} = \omega_f R_{f}^{t} + \omega_n R_{n}^{t} + \omega_t R_{tc}^{t} + \omega_e R_{e}^{t} + \omega_c R_{c}^{t},
\end{equation}
where$[\omega_{f}$, $ \omega_{n}$, $ \omega_{t}$, $\omega_{e}$, $\omega_{c}]$,undefined are the weights of the subitems.

