            \label{Example: Tensor weights 4-point correlation function}
            The 4-points correlation function of tensor weights last hidden layer condition is
\begin{eqnarray}
	\left<\right.\hat{f}^{*}({\bf x}_{1})\hat{f}^{*}({\bf x}_{2})\hat{f}({\bf x}_{3})\hat{f}({\bf x}_{4})\left.\right>\equiv\frac{1}{d}\ {\rm tr}\left({1 \over n_{\rm nets}}\sum_{\alpha=1}^{n_{\rm nets}}f_{\alpha}^{*}({\bf x}_1)f_{\alpha}^{*}({\bf x}_2)f_{\alpha}({\bf x}_3)f_{\alpha}({\bf x}_4)\right),
\end{eqnarray}
which can be expanded as
\begin{eqnarray}
    &&\left<\right.\hat{f}^{*}({\bf x}_{1})\hat{f}^{*}({\bf x}_{2})\hat{f}({\bf x}_{3})\hat{f}({\bf x}_{4})\left.\right>\\
	&=&\left<\sigma\left({\bf x}_{1}W_{\rm in,h}+{\bf b}_{\rm h}\right)^{*}W_{\rm h,out}^{*}\sigma\left({\bf x}_{2}W_{\rm in,h}+{\bf b}_{\rm h}\right)^{*}W_{\rm h,out}^{*}\sigma\left({\bf x}_{3}W_{\rm in,h}+{\bf b}_{\rm h}\right)W_{\rm h,out}\sigma\left({\bf x}_{4}W_{\rm in,h}+{\bf b}_{\rm h}\right)W_{\rm h,out}\right>\nonumber,
\end{eqnarray}
considering that the dimension of the output function $f$ is $d_{\rm out}=1$ and the relation that
\begin{eqnarray}
	\frac{1}{d}\left<W_{i}^{*}W_{j}^{*}W_{k}W_{l}\right>{\rm tr}[\gamma_{i}\gamma_{j}\gamma_{k}\gamma_{l}]&=&\frac{4\sigma_{\rm w}^{4}}{H^{2}}(2\delta_{ij}\delta_{ik}\delta_{il}-\delta_{ik}\delta_{jl}+\delta_{il}\delta_{jk}),
\end{eqnarray}
the 4-points correlation function can be calculated as
\begin{eqnarray}\label{4-points-correlation-matrix}
	&&\left<\right.\hat{f}^{*}({\bf x}_{1})\hat{f}({\bf x}_{2})\hat{f}^{*}({\bf x}_{3})\hat{f}({\bf x}_{4})\left.\right>\nonumber\\
	&=&\frac{4\sigma_{\rm w}^{4}}{H^{2}}\left<\sigma\left({\bf x}_{4}W_{\rm in,h}+{\bf b}_{\rm h}\right)\sigma\left(W_{\rm in,h}^{\dag}{\bf x}_{1}^{\dag}+{\bf b}_{\rm h}^{\dag}\right)\sigma\left({\bf x}_{3}W_{\rm in,h}+{\bf b}_{\rm h}\right)\sigma\left(W_{\rm in,h}^{\dag}{\bf x}_{2}^{\dag}+{\bf b}_{\rm h}^{\dag}\right)\right>\nonumber\\
	&&-\frac{4\sigma_{\rm w}^{4}}{H^{2}}\left<\sigma\left({\bf x}_{3}W_{\rm in,h}+{\bf b}_{\rm h}\right)\sigma\left(W_{\rm in,h}^{\dag}{\bf x}_{1}^{\dag}+{\bf b}_{\rm h}^{\dag}\right)\sigma\left({\bf x}_{4}W_{\rm in,h}+{\bf b}_{\rm h}\right)\sigma\left(W_{\rm in,h}^{\dag}{\bf x}_{2}^{\dag}+{\bf b}_{\rm h}^{\dag}\right)\right>\nonumber\\
	&&+\frac{8\sigma_{\rm w}^{4}}{H^{2}}\sum_{j=1}^{H}\left<\exp\left\{\sum_{i=1}^{d_{\rm in}}[x_{1}^{(i)*}w_{ij}^{*}+x_{2}^{(i)*}w_{ij}^{*}+x_{3}^{(i)}w_{ij}+x_{4}^{(i)}w_{ij}]+2b_{j}+2b_{j}^{*}\right\}\right>.
\end{eqnarray}
According to the matrix multiplication relation that
\begin{eqnarray}
	&&\exp({\bf x}_{4}W_{\rm in,h}+{\bf b}_{\rm h})\exp(W_{\rm in,h}^{\dag}{\bf x}_{1}^{\dag}+{\bf b}_{\rm h}^{\dag})\exp({\bf x}_{3}W_{\rm in,h}+{\bf b}_{\rm h})\exp(W_{\rm in,h}^{\dag}{\bf x}_{2}^{\dag}+{\bf b}_{\rm h}^{\dag})\nonumber\\
	&=&\sum_{j=1}^{H}\exp\left\{\sum_{i=1}^{d_{\rm in}}[x_{4}^{(i)}w_{ij}+x_{1}^{(i)*}w_{ij}^{*}]+b_{j}+b_{j}^{*}\right\}\sum_{j'=1}^{H}\exp\left\{\sum_{i'=1}^{d_{\rm in}}[x_{3}^{(i')}w_{i'j'}+x_{2}^{(i')*}w_{i'j'}^{*}]+b_{j'}+b_{j'}^{*}\right\}
\end{eqnarray}
the mathematical expectation of the above equation gives
\begin{eqnarray}\label{14-23-connection}
	&&\left<\right.\exp({\bf x}_{4}W_{\rm in,h}+{\bf b}_{\rm h})\exp(W_{\rm in,h}^{\dag}{\bf x}_{1}^{\dag}+{\bf b}_{\rm h}^{\dag})\exp({\bf x}_{3}W_{\rm in,h}+{\bf b}_{\rm h})\exp(W_{\rm in,h}^{\dag}{\bf x}_{2}^{\dag}+{\bf b}_{\rm h}^{\dag})\left.\right>\nonumber\\
	&=&H(H-1)\exp\left\{\frac{2\sigma_{\rm w}^{2}}{d_{\rm in}}({\bf x}_{1}\cdot{\bf x}_{4}+{\bf x}_{2}\cdot{\bf x}_{3})+4\sigma_{\rm b}^{2}\right\}+H\times\exp\left\{\frac{2\sigma_{\rm w}^{2}}{d_{\rm in}}({\bf x}_{1}+{\bf x}_{2})\cdot({\bf x}_{3}+{\bf x}_{4})+8\sigma_{\rm b}^{2}\right\},
\end{eqnarray}
considering ${\bf x}_{i}$ ($i=1,2,3,4$) being real valued vectors, with the first term coming from the $j\neq j'$ case, and the second term coming from the $j=j'$ case.

As for the third term in equation (\ref{4-points-correlation-matrix}), the mathematical expectation gives the value of the second term in equation (\ref{14-23-connection}), thus, in the large $H$ limit, this term vanishes, and the 4-points correlation function gives
\begin{eqnarray}
	\lim_{H\rightarrow\infty}\left<\right.\hat{f}^{*}({\bf x}_{1})\hat{f}^{*}({\bf x}_{2})\hat{f}({\bf x}_{3})\hat{f}({\bf x}_{4})\left.\right>&=&G_{\rm NN}^{(2)}({\bf x}_{1},{\bf x}_{4})G_{\rm NN}^{(2)}({\bf x}_{2},{\bf x}_{3})-G_{\rm NN}^{(2)}({\bf x}_{1},{\bf x}_{3})G_{\rm NN}^{(2)}({\bf x}_{2},{\bf x}_{4}).
\end{eqnarray}
\end{widetext}
























