\title{Polarized Deep Inelastic Scattering as $x \to 1$ using Soft Collinear Effective Theory}

\author[a]{Jaipratap Singh Grewal \orcidlink{https://orcid.org/0000-0003-1256-2281},}
\author[a]{Aneesh V. Manohar \orcidlink{https://orcid.org/0009-0004-5497-8554},}
\author[b]{Jyotirmoy Roy \orcidlink{https://orcid.org/0000-0002-4574-5386}}
\affiliation[a]{Physics Department 0319, University of California San Diego, 9500 Gilman Drive, La Jolla, CA 92093-0319, USA}
