\begin{align}
    W_{\mu\nu}(P,S,q) &= \frac{1}{4\pi} \int d^4z \, e^{iq \cdot z} \braket{ P,S|[j_\mu(z),j_\nu(0)]|P,S } \nn
    &= -F_1 \left(g_{\mu\nu} - \frac{q_\mu q_\nu}{q^2} \right) + \frac{F_2}{P \cdot q}\left(P_\mu - \frac{(P \cdot q)\, q_\mu}{q^2} \right)\left(P_\nu - \frac{(P \cdot q)\, q_\nu}{q^2} \right) \nn
    & + \frac{ig_1}{P \cdot q}\epsilon_{\mu\nu\lambda\sigma} q^\lambda S^\sigma  + \frac{ig_2}{(P \cdot q)^2} \epsilon_{\mu\nu\lambda\sigma} q^\lambda (P \cdot q \, S^\sigma - S \cdot q \, P^\sigma) \, ,
    \label{2.2}
\end{align}
where $j$ is the electromagnetic current, and the structure functions $F_1$, $F_2$, $g_1$ and $g_2$ are dimensionless functions of $x$ and $Q^2$. The decomposition Eq.~\eqref{2.2} is valid for spin-1/2 targets, and assumes $P$ and $T$ symmetry.  We will use uppercase letters $S^\mu,\, P^\mu$ for hadronic (proton) quantities, and lower case letters $s^\mu,\, p^\mu$ for partonic quantities. $S^\mu$ is the spin of the proton, and is normalized to $S^2 = -M_p^2$. The $Q^2$ dependence of  structure functions for large $Q^2$, which is logarithmic, is computable in perturbative QCD.  Using lightcone coordinates in the Breit frame, we can write
\begin{align}
W^{\mu \nu} &=  - F_1 g^\perp_{\mu \nu} +\frac{F_L}{8x} 
\left(  \nb + n  \right)^\mu\left(  \nb + n \right)^\nu - i g_1 \epsilon_\perp^{\mu \nu} \frac{n \cdot S}{n \cdot P}   \nn 
&  + i \frac{g_1+g_2}{Q}x \left[ - (n + \nb)^\mu \epsilon_\perp^{\nu \sigma} + (n + \nb)^\nu \epsilon_\perp^{\mu \sigma} \right] S_\sigma  \,.
\label{2.20}
\end{align}
The DIS literature usually uses $F_2$ and $F_L=F_2-2xF_1$ as the two independent unpolarized structure functions. In SCET, Eq.~\eqref{2.20} shows that it is better to use $F_1$ and $F_L$. $F_1$ and $g_1$ contribute to $W^{\mu \nu}$ with $\mu,\nu$ both $\perp$ indices, $F_L$ with both $\parallel$ indices, and $g_1+g_2$ with one $\perp$ and one $\parallel$ index. We will see the benefit of using $F_1$ instead of $F_2$ in Section~\ref{sec:coeff}.


The spin-averaged DIS cross section is
\begin{align}
    \frac{d^2\sigma}{\rd x\, \rd y}     &=  \frac{4 \pi \alpha^2} {x y Q^2}\left[xy^2F_1 + \left(1-y-\frac{x^2 y^2 M_p^2}{Q^2} \right) F_2 \right]\,.
    \label{2.3}
\end{align}
The cross section asymmetry for a target polarized parallel to the beam direction is
%
\begin{align}
    \frac{d^2 \Delta \sigma}{\rd x\, \rd y}
    &=  \frac{8 \pi \alpha^2} {x y Q^2} \left[ x y (y-2)  g_1 +  \frac{ 2 M_p^2 x^3 y^2}{Q^2} (y g_1 + 2 g_2)  \right]\,,
    \label{2.4}
\end{align}
and for a target polarized transverse to the beam direction is
\begin{align}
    \frac{d^2\Delta \sigma}{\rd x\, \rd y\, \rd \phi}
    &=  \frac{8 \pi \alpha^2} {x y Q^2} \left[ -\frac{\sqrt{2} M_p x^2 y \sqrt{1-y}  }{Q} (y g_1 + 2 g_2)  \right] \cos \phi \,,
    \label{2.5}
\end{align}
where $\phi$ is the azimuthal angle between the scattered electron and the transverse polarization direction. Polarized cross section measurements for the proton require both a polarized target and polarized beam, and are done by flipping either the lepton or target polarization. $g_1$ can be measured using a longitudinally polarized target, and the cross section asymmetry is leading order in $M_p^2/Q^2$. The contribution of $g_2$ to the cross section for longitudinal polarization is suppressed by $M_p^2/Q^2$. The transverse asymmetry is order $M_p/Q$, and both $g_1$ and $g_2$ contribute at this order. In QCD, structure functions have a twist expansion in powers of $M_p^2/Q^2$. $F_1$, $F_2$ and $g_1$ get contributions at leading twist, with higher twist corrections suppressed by powers of $M_p^2/Q^2$. The QCD contribution to $g_2$ starts at twist-three, so we need subleading operators of order $\lambda$ in the SCET analysis. $g_2$ is a dimensionless function of $x$ and is order unity. Its contribution to the cross section is order $M_p/Q$.



\subsection{OPE} \label{sec:ope}

The QCD analysis of DIS uses an OPE at the scale $Q$ to match the time-ordered product of two electromagnetic currents
\begin{align}
    t^{\mu\nu}  &= i \int d^4z \, e^{iq \cdot z} \, T \left( j^\mu(z) j^\nu(0) \right) \,,
    \label{2.7}
\end{align}
onto local operators. The hadronic matrix element of the time-ordered product is
\begin{align}
T_{\mu\nu}(P,S,q) &=i \int d^4z \, e^{iq \cdot z} \braket{ P,S| T \left( j^\mu(z) j^\nu(0) \right) |P,S } \nn
    &= -\widetilde F_1 \left(g_{\mu\nu} - \frac{q_\mu q_\nu}{q^2} \right) + \frac{\widetilde F_2}{P \cdot q}\left(P_\mu - \frac{(P \cdot q)\, q_\mu}{q^2} \right)\left(P_\nu - \frac{(P \cdot q)\, q_\nu}{q^2} \right) \nn
    & + \frac{i \widetilde g_1}{P \cdot q}\epsilon_{\mu\nu\lambda\sigma} q^\lambda S^\sigma  + \frac{i \widetilde g_2}{(P \cdot q)^2} \epsilon_{\mu\nu\lambda\sigma} q^\lambda (P \cdot q \, S^\sigma - S \cdot q \, P^\sigma) \, .
    \label{2.60}
\end{align}
with a tensor decomposition analogous to $W_{\mu \nu}$. The structure functions $\widetilde{\mathcal{F}}$ with $\mathcal{F}=F_1,\ F_2,\ g_1,\ g_2$ have branch cuts in the physical region $-1 \le x \le 1$ with discontinuity $\text{Disc} \, \widetilde{\mathcal{F}} = 4 \pi i\, \mathcal{F}$, which relates the structure functions in $T_{\mu \nu}$ to those in $W_{\mu \nu}$.


The OPE gives an expansion of $t_{\mu \nu}$ in powers of $\omega=1/x$ around $\omega=0$. The coefficients of powers of $\omega$ can be related to moments of the structure functions, which are discontinuities across the cut, using Cauchy's theorem.
%
The OPE for the polarized structure function $g_1$ at leading twist (twist-two) gives the moment sum rule\footnote{The OPE quark coefficients for the moments of $F_1$, $F_2$, $F_L$ and $g_1$ will be denoted by $C_{1q,N}$, $C_{2q,N}$, $C_{Lq,N}=C_{2q,N}-C_{1q,N}$ and $C_{\Delta q,N}$, and similarly for the gluon coefficients.}
\begin{align}
2 M_{N} [g_1] &= \sum_{i=q,g} C_{\Delta  i,N}(Q,\mu) A_{i,N}(\mu), \qquad (N\ \text{odd})
\label{2.8}
\end{align}
where the sum on $i$ is over quark and gluon contributions.  The quark coefficient $ C_{\Delta  q,N}=1$ at tree-level and the gluon coefficient $ C_{\Delta  g,N}$ starts at $O(\alpha_s)$. The axial matrix elements $A_{q,N}(\mu)$ are defined via the proton matrix element of twist-two quark operators renormalized at scale $\mu$,
%
\begin{align}
O_{A,q,N} &= \frac12 \overline \psi \slashed{n} \gamma_5 \left( i n \cdot D \right)^{N-1}  \psi\,, \nn
\braket{P,S | O_{A,q,N} | P,S} &= A_{q,N}(\mu)\, (n \cdot S)\, (n \cdot P)^{N-1} \,.
\label{2.10}
\end{align}
%
The operator in Eq.~\eqref{2.10} is normalized so that the tree-level matrix element in a free-quark state has $A_{q,N}=1$.

The renormalization group (RG) improved expressions for $g_1$ are given by evaluating $ C_{\Delta i,N}(Q,\mu)$ at $\mu \sim Q$, where $\log Q^2/\mu^2$ is not large, and using the RG to evolve it to a fixed scale $\mu_0$ of order a hadronic scale, where the matrix elements are evaluated.

The tower of twist-two operators can be inverted in moment space to obtain bilocal PDF operators~\cite{Manohar:1990jx,Manohar:1990kr}
%
\begin{align}
O_{\Delta q}(r^+) &= \frac{1}{4\pi} \int \rd \xi \ e^{-i \xi r^+} \ \overline \psi(n \xi) \slashed{n} \gamma_5 \psi(0)\,, \nn
O_{ \Delta \overline q}(r^+) &= \frac{1}{4\pi} \int \rd \xi \ e^{-i \xi r^+} \ \overline \psi(0) \slashed{n} \gamma_5 \psi(n \xi) \,,
\label{2.14}
\end{align}
whose proton matrix elements define the polarized quark and antiquark PDFs $f_{\Delta q}(x)$ and  $f_{\Delta \overline q}(x)$,
\begin{align}
\braket{P,S | O_{\Delta q}(x P^+) | P,S} &= f_{\Delta q}(x)\,, \nn
\braket{P,S | O_{\Delta \overline q}(x P^+) | P,S} &= f_{\Delta \overline q}(x) \,,
\label{2.15}
\end{align}
which satisfy $f_{\Delta q}(-x) = f_{\Delta \overline q}(x)$.
The axial matrix elements are moments of the polarized PDF
\begin{align}
    M_N[ f_{\Delta q}(x) + f_{\Delta\overline{q}}(x)] &= A_{q,N}(\mu), \qquad (N \text{ odd})
    \label{2.16}
\end{align}
The OPE Eq.~\eqref{2.7} involves the product of two electromagnetic currents, so the PDF combinations which enter the DIS cross section are charge-conjugation even, and are the sum of quark and antiquark contributions.

The tree-level OPE for the antisymmetric part of $t^{\mu \nu}$ is~(see~\cite{Manohar:1992tz} for a review)
\begin{align}
t^{[\mu\nu]}=\sum_{n=1,3,5}^\infty 2\  \frac{2^{n} q_{\mu_2}
\ldots q_{\mu_n} }{ (-q^2)^{n}}
\ i\epsilon^{\mu\nu \alpha\mu_{1}}\,q_\alpha \  \frac12 \overline \psi \gamma^{\mu_1} \gamma_5 \left( i D^{\mu_2} \right)  \cdots \left( i D^{\mu_n} \right)  \psi \,.
\label{2.17}
\end{align}
The hadronic matrix element of the quark operator in Eq.~\eqref{2.17} only has $+$ components, so the operator that contributes to $t^{[\mu \nu]}$ is
%
\begin{align}
O_q^\sigma &=  \frac12 \overline \psi \gamma^{\sigma} \gamma_5 \left( i n \cdot D \right) ^{N-1}  \psi = O_{2,q}^\sigma + \frac{N-1}{N} O_{3,q}^\sigma \, ,
\label{2.70}
\end{align}
which has twist-two and twist-three pieces. The twist-two piece is
\begin{align}
O_{2,q}^\sigma &=  \frac1{2N} \overline \psi \gamma^{\sigma} \gamma_5 \left( i n \cdot D \right) ^{N-1}  \psi 
+ \sum_{r+s=N-2}  \frac1{2N} \overline \psi  \slashed{n} \gamma_5 \left( i n \cdot D \right)^r (i n \cdot D)^\sigma (i n \cdot D)^s \psi 
\label{2.71}
\end{align}
and is completely symmetric in the Lorentz index $\sigma$ and the $N-1$ indices contracted with $n^\mu$. Its hadronic matrix element is
%
\begin{align}
\braket{P,S | O_{2,q}^\sigma  | P, S} & = A_{q,N} \left[ \frac{1}{N} S^\sigma (n \cdot P)^{N-1} + \frac{N-1}{N} (n \cdot S) P^\sigma (n \cdot P)^{N-2} \right] \,,
\label{2.73}
\end{align}
and is completely symmetric in $S$ and $P$.
The matrix element $A_{q,N}$ is the same as for the twist-two operator for $g_1$ defined in Eq.~\eqref{2.10}, since $n_\sigma O_{2,q}^\sigma =  O_{A,q,N}$.
%
The twist-three piece is
%
\begin{align}
O_{3,q,N}^\sigma 
&=\frac12 \overline \psi \gamma^{\sigma } \gamma_5 \left( i n \cdot D \right)^{N-1}  \psi 
- \frac{1}{N-1} \sum_{r+s=N-2} \frac12 \overline \psi \slashed{n} \gamma_5 \left( i n \cdot D \right)^r  (i D^\sigma)  \left( i n \cdot D \right)^s \psi \,.
\label{2.39}
\end{align}

The contribution of the twist-two operator $O_{A,q,N}$ to $T_{\mu \nu}$ (including the matching coefficient  $ C_{\Delta q,N}$ which is unity at tree-level) is
\begin{align}
T_{\mu \nu} &= \braket{P,S | t_{\mu \nu} | P,S} \nn
& =
\sum_{n=1,3,5}^\infty  2\ C_{\Delta q,N} A_{q,N}  \frac{2^{n}}{(-q^2)^{n}} i\epsilon^{\mu\nu \alpha \sigma}\,q_\alpha \left[ \frac{1}{N}S^{\sigma} (q \cdot P)^{N-1} +  \frac{N-1}{N} P^\sigma (q \cdot S) (q \cdot P)^{N-2} \right] \nn
&= 
\sum_{n=1,3,5}^\infty  2\  C_{\Delta q,N} A_{q,N}\ \omega^n i\epsilon^{\mu\nu \alpha \sigma}\,q_\alpha \left[ \frac{S^\sigma}{(q \cdot P)} - \frac{N-1}{N}  \frac{  \big(S^\sigma (q \cdot P) - P^\sigma (q \cdot S) \big) }{(q \cdot P)^{2}} \right] \,.
\label{2.40}
\end{align}
Comparing with Eq.~\eqref{2.2}, the first term leads to the quark term for $g_1$ discussed earlier in Eq.~\eqref{2.8}, and the second term is the Wilczek-Wandzura contribution to $g_2$
\begin{align}
2 M_{N} [g_2^\text{WW} ] &= - \frac{N-1}{N} C_{  \Delta i,N}(Q,\mu) A_{i,N}(\mu) = - \frac{N-1}{N}\  2 M_{N} [g_1]\,. \qquad (N\ \text{odd})
\label{2.37}
\end{align}
In $x$-space,
\begin{align}
g^{\text{WW}}_2(x) &= -g_1(x) + \int_x^1 \frac{\rd y}{y} g_1(y) \,.
\label{2.25}
\end{align}
The total expression for $g_2$ is
\begin{align}
g_2(x) &= g^{\text{WW}}_2(x) + \overline g_2 (x) \,,
\label{2.26}
\end{align}
where $\overline g_2$ is the contribution from the twist-three operators $O_{3,q}$ in Eq.~\eqref{2.70}. Both $g^{\text{WW}}_2(x) $ and $ \overline g_2 (x)$ are dimensionless functions of the same order in power counting, so $ \overline g_2 (x)$  is not formally suppressed relative to $g^{\text{WW}}_2(x) $.

The proton matrix element of the twist-three operators $O_{3,q,N}^\sigma$ defines the matrix elements $B_{q,N}$,
\begin{align}
\braket{P,S| O_{3,q,N}^\sigma |P,S} &= B_{q,N}(\mu) \left[  S^\sigma (n \cdot P)^{N-1} - P^\sigma (n \cdot S) (n \cdot P)^{N-2}  \right],
\label{2.21}
\end{align}
%
and contributes to $\overline g_2$ but not $g_1$. Its contributions to the moments of $\overline g_2$ are given by
%
\begin{align}
2M_{N} [\overline g_2] &=  B_{q,N} (\mu) \,, \qquad N \text{ odd} \,,
\label{2.23}
\end{align}
since the matching coefficient is unity at tree-level.
%
Note that there are no twist-three operators for $N=1$, and the first moment of the Wilczek-Wandzura contribution Eq.~\eqref{2.8} vanishes,
which leads to the Burkhardt-Cottingham sum rule~\cite{Burkhardt:1970ti} $M_1[g_2]=0$. The matrix elements $B_{q,N}$ and $A_{q,N}$ are order unity, so the twist-three contribution $\overline g_2$ is the same order as the twist-two contribution $g^{\text{WW}}_2$ and cannot be neglected.

It was pointed out by Shuryak and Vainshtein~\cite{Shuryak:1981pi} that the above twist-three analysis~\cite{Kodaira:1978sh,Kodaira:1979ib,Kodaira:1979pa} is incorrect, because the twist-three quark operator $O_{3,q,N}$ can be eliminated using the equations of motion in favor of three-parton quark-gluon operators Eq.~\eqref{2.30} which start at order $g$. The moments of $\overline{g}_2$ cannot be written as in Eq.~\eqref{2.23} with matrix elements $B_{q,N}$ of quark-only twist-three operators. 

% A basis for the quark-gluon twist-three 
The correct analysis requires the operators~\cite{Kodaira:1994ge}
\begin{align}
V_{r,s}^\sigma &= i g  \overline \psi   (i n \cdot D)^{r-1} G^{\sigma \alpha} n_\alpha (i n \cdot D)^{s-1} \slashed{n} \gamma_5   \psi \,, \nn
U_{r,s}^\sigma &= g  \overline \psi   (i n \cdot D)^{r-1}  \widetilde G^{\sigma \alpha} n_\alpha (i n \cdot D)^{s-1}    \slashed{n}  \psi \,,
\label{2.30}
\end{align}
where for the $N^\text{th}$ moment,  $N=r+s+1$ and $1 \le r,s \le N-2$, $\widetilde G_{\alpha \beta} = \frac12 \epsilon_{\alpha \beta \lambda \sigma}G^{\lambda \sigma}$.\footnote{
We have contracted the symmetrized $\mu$-indices in the definition~\cite{Kodaira:1994ge} with $n$, and used $g \to -g$ because our sign convention for the covariant derivative is the opposite of~\cite{Kodaira:1994ge}.}
Some properties of the quark-gluon operators, and the equation-of-motion identity are given in Appendix~\ref{app:ops} and Appendix~\ref{app:eom}. The equation-of-motion gives the linear combination Eq.~\eqref{a2.34} for tree-level matching. However, at one-loop, the coefficients of the individual $V_{r,s}^\sigma $ and $U_{r,s}^\sigma $ can be different, so the matching is not given by a single overall coefficient $B_{q,N}$. We compute the one-loop matching in Section~\ref{sec:matchingJ}.

The charge-conjugation even combinations of $V_{r,s}^\sigma$ and $U_{r,s}^\sigma$ that enter DIS are
\begin{align}
& V_{r,s}^\sigma - V_{s,r}^\sigma\,, &  & \text{and} & U_{r,s}^\sigma + U_{s,r}^\sigma\,.
\label{2.33}
\end{align}
There are $N-2$ charge-conjugation even twist-three operators, and the number of operators grows with the moment. The anomalous dimension is a $(N-2) \times (N-2)$ matrix. The anomalous dimension of the non-singlet twist-three operators was computed in moment space in Refs.~\cite{Bukhvostov:1983eob,Ratcliffe:1985mp,Ji:1990br}, and in $x$ space in Refs.~\cite{Ratcliffe:1985mp,Balitsky:1987bk,Ali:1991em,Geyer:1996isa}.

Similar to the twist-two case, one can combine the twist-three operators into trilocal PDF operators~\cite{Balitsky:1987bk,Geyer:1996isa}
%
\begin{align}
F_\pm(r_1^+,r_2^+) &=  \frac{1}{(2\pi)^2}\int \rd \xi_1\ \int \rd \xi_2\ e^{-i \xi_2 r_2^+}\ e^{i \xi_1 r_1^+} \overline \psi (n \xi_2) \left[ \pm i g G_{n \sigma} (0) \slashed{n}\gamma_5+ g \widetilde G_{n \sigma}(0) 
\slashed{n} \right] \psi(n \xi_1)
\label{2.35}
\end{align}
whose double-moments give $U^\sigma_{r,s}\pm V^\sigma_{r,s}$, and whose proton matrix elements give a PDF
\begin{align}
\braket{P,S | F(x_1 P^+ ,x_2 P^+) | P,S} &= f(x_1,x_2) \,,
\label{2.36}
\end{align}
which is a function of two variables.

The analysis of $g_2$ is much more complicated than the other structure functions because of the trilocal PDF operator. The anomalous dimension kernel of this operator also depends on two variables~\cite{Balitsky:1987bk,Ali:1991em,Geyer:1996isa}, whereas the structure function $g_2(x)$ itself depends only on a single variable. Equivalently, the $N^{\text{th}}$ moment of $g_2$ is a single number, whereas it gets contributions from $N-2$ operators. Thus a measurement of $g_2(x,Q_1^2)$ at a single scale $Q_1$ is not sufficient to determine $g_2(x,Q_2^2)$ at a different scale $Q_2$.


In the $x \to 1$ limit, the QCD evolution of the twist-three PDF distribution simplifies to an evolution with single variable kernels~\cite{Ali:1991em,Geyer:1996isa}. We will see that SCET explains why this occurs, and also greatly simplifies the QCD analysis.

\section{ \texorpdfstring{Unpolarized DIS as $ x \to 1$: $F_1$ and $F_L$}{Unpolarized DIS as x goes to 1: F1 and F2}}\label{sec:unpolarized}

The SCET analysis of unpolarized DIS as $x \to 1$ at leading order in $\lambda$ is given in Ref.~\cite{Manohar:2003vb}. We briefly summarize the results here. 
The SCET operators are constructed out of gauge-invariant objects\footnote{Our sign convention for the covariant derivative is the opposite of Ref.~\cite{Luke:2022ops}.}
\begin{align}
    \label{building_blocks}
    \chi_{n} (x) &= W^\dagger_{n}(x) \psi_{n} (x) \,,  \nn
   \mathcal{B}_n^{\mu_1 \cdots \mu_N}(x) &=  {W}_n^\dagger(x)\, i D_n^{\mu_1}\cdots i D_n^{\mu_N} {W}_n(x) \,.
\end{align}
%
The collinear Wilson lines, needed to preserve gauge invariance, are defined as
%\footnote{The difference between incoming and outgoing collinear Wilson lines is in the sign of the $i0^+$ terms in the Feynman rules, but this does not affect the final result after zero-bin/overlap subtraction.}
\begin{align} 
\label{Wline_defns}
{W}_n(x) &= \mathcal{P} \exp \left( -ig \int_{-\infty}^{0} \!\! \rd s \ \bar n\cdot A^a_{n}(x+\nb s) T^a  \right) \,.
\end{align}
Note that the subscript on a Wilson line corresponds to the sector with which it interacts rather than its direction along the lightcone. $W_n$ contains $n$-collinear fields,  but is in the $\nb$ direction. $\chi_n$ is the gauge invariant quark field satisfying $\slashed{n} \chi_n=0$, and $\mathcal{B}_n^{\mu_1 \cdots \mu_N}(x)$ is a gauge invariant version of the gauge field and its derivatives. We will need $\mathcal{B}_n^{\mu}(x) \sim -g A^\mu_n(x) + \ldots$ with a single Lorentz index. The definitions of $\nb$-collinear fields are given by $n \leftrightarrow \nb$.

With our choice of kinematics, the incoming partons are in the $\nb$ direction and the outgoing partons are in the $n$ direction.
At the scale $Q$, the electromagnetic current $j_\text{QCD}^\nu=\overline\psi \gamma^\nu \psi $ in QCD is matched onto the SCET current at leading power, %
\begin{align}
  j_\text{QCD}^\nu &=  C_J(\mu)\ j^\nu_{\text{SCET}}(x) + O(\lambda)\,, & j^\nu_{\text{SCET}}(x) & = \overline \chi_n(x) \gamma^\nu_\perp \chi_{\nb}(x) \,.
\label{3.18}
\end{align}
The Lorentz index for the leading order SCET current is a $\perp$ index. In SCET, 
\begin{align}
    W^{\mu\nu}(P,S,q) &= \frac{1}{4\pi} \int d^4z \, e^{iq \cdot z} 
    \braket{P,S| j^{\dagger \mu}_{\text{SCET}}(x)  j^\nu_{\text{SCET}}(0) |P,S}
     \label{3.41}
\end{align}
gives the quark contribution to $W^{\mu \nu}$, and the antiquark contribution is given by adding the charge-conjugate contribution. The second term in the commutator in Eq.~\eqref{2.2} does not contribute. The antiquark contribution must be added explicitly, since there is no crossing symmetry in SCET. The current Eq.~\eqref{3.18} describes an incoming quark in the $\nb$ direction and an outgoing quark in the $n$ direction. The charge-conjugate operator has an incoming antiquark in the $\nb$ direction and an outgoing antiquark in the $n$ direction, and lives in a different SCET sector.

%
The one-loop matching coefficient is~\cite{Manohar:2003vb}
\begin{align}
C_J(\mu)&= 1 + \frac{\alpha_s}{4 \pi} \left[ -\lQ^2 + 3\lQ  + \frac{\pi^2}{6} - 8 \right] \,.
\label{3.3}
\end{align}
%
The operator SCET current is evolved to $M_J$ using the SCET anomalous dimension~\cite{Manohar:2003vb}
\begin{align}
\mu \frac{\rd}{\rd \mu} j^\nu_{\text{SCET}} &= \gamma_J \, j^\nu_{\text{SCET}}\,,  &  \gamma_J =\frac{\alpha_s}{4\pi} C_F \left(-4 \lQ + 6 \right)\,.
\label{3.2}
\end{align}
The anomalous dimension contains a logarithm $\lQ$, and the RGE sums the Sudakov double logarithms.

At the scale $M_J$, the time-ordered product of two SCET currents is matched using an OPE (see Fig.~\ref{fig:ope}) onto the quark PDF operator
% - BEGIN FIGURE
\begin{figure}
\centering
\includegraphics[width=10cm]{figs/fig2}
\caption{\label{fig:ope} Time ordered product of two currents at tree-level matching onto the (a) quark PDF and (b) antiquark PDF operators.}
\end{figure}
% - END FIGURE
\begin{align}
O_q(r^+) &= \frac{1}{4\pi} \int \rd \xi \,  e^{- i \xi r^+} \overline \chi_{\nb} (n \xi) \, \slashed{n} \, \chi_{\nb}(0) \,,
\label{3.20}
\end{align}
and the antiquark PDF operator $O_{\overline q}(r^+)= - O_q(-r^+)$ given by charge conjugation. The antiquark contributions in the OPE are related to the quark contributions by reversing the direction of the fermion arrow in the diagram as shown in Fig.~\ref{fig:ope}.
 In Eq.~\eqref{3.20} the Wilson lines in $\chi_{\nb}(0)$ and $\overline \chi_{\nb}(n\xi)$ can be combined into a single Wilson line from $0$ to $n\xi$,
\begin{align}
O_q(r^+) &= \frac{1}{4\pi} \int \rd \xi \,  e^{- i \xi r^+} \overline \psi_{\overline n} (n \xi) W(n\xi,0) \ \slashed{n} \ \psi_{\overline n}(0) \,.
\label{3.4}
\end{align}
%
 The matrix elements of the PDF operators give the quark and antiquark PDFs,
%
\begin{align}
\braket{P | O_q(x P^+) | P} &=  f_q(x,\mu) &
\braket{P | O_{\overline q} (x P^+) | P} &=  f_{\overline q}(x,\mu) \,,
\label{3.13}
\end{align}
with $f_q(-x) = - f_{\overline q}(x)$.\footnote{The physical region is $0 \le x \le 1$. The moment sum rules integrate over all $x$, and the negative $x$ part of the $x$ integral is the antiquark contribution, e.g.\ in Eq.~\eqref{2.16}. The $g_1$ moment sum rules for odd $N$ give the matrix elements of the sum of quark and antiquark distributions, which is charge-conjugation even. There are no $g_1$ moment sum rules for even $N$, as those would have generated charge-conjugation odd matrix elements. See~\cite{Jaffe:1983hp} for a detailed discussion on the allowed $x$ range for PDFs.}
%
\begin{figure}
    \centering
    \includegraphics[width=\linewidth]{figs/fig3.pdf}
    \caption{SCET loop graphs that generate the 1-loop matching onto the quark PDF. The gluon from the current vertex arises from the $W_n$ Wilson line. The graphs that match onto the antiquark PDF are the same but with arrows reversed. The quark and gluon are in the $n$-sector (jet sector), which is integrated out.  External particles (quarks and/or gluons) couple to the vertices and are in the $\nb$-sector, and not shown. The overlap/zero-bin prescription~\cite{Manohar:2006nz, Goerke:2017ioi} ensures that only the $n$-sector contributes to the matching.}
    \label{fig:g1_soft_matching}
\end{figure}
%
%
The factorization formula for the matching at the jet scale is
\begin{align} 
W^{\mu\nu} &= \frac{1}{4\pi} \int \rd x \ e^{i q \cdot x} \ j_\text{SCET}^{\dagger \mu(x)}\ j_\text{SCET}^\nu(0)  =  \frac12 (-g_\perp^{\mu \nu}) \int \frac{\rd r^+}{r^+} \mathcal{M}\left({-q^+}/{r^+} \right) \left[O_q(r^+) + O_{\overline q}(r^+) \right] \,,
\label{3.5}
\end{align}
%
and the matching coefficient to one-loop on integrating out the $n$-collinear jet, generated by the graphs in Fig.~\ref{fig:g1_soft_matching}, is~\cite{Manohar:2003vb} 
\begin{align}
\mathcal{M}(z) &= \delta(1-z) +  \frac{\alpha_s}{4 \pi} \left \{ 4  {\left[ \frac{\ln(1-z)}{(1-z)} \right]_+ }  + \left[ 4  \lQ
 -3 \right] { \frac{1}{(1-z)_+} }  + 
 \left[  2 \lQ^2
-3 \lQ  -\pi^2  + 7  \right] \delta(1-z) \right\} \,.
\label{3.6}
\end{align}
%



%
Comparing with Eq.~\eqref{2.20}, we see that Eq.~\eqref{3.5} implies $F_L$ vanishes at leading power so that $C_{Lq,N} =\mathcal{O}(1/N)$,
and Eq.~\eqref{3.6} is the one-loop matching contribution to the quark coefficient $C_{1q}$ for $F_1$.

Below $M_J$ there is only one SCET sector, so the theory is the same as QCD, since there is nothing to expand in. The PDF operator Eq.~\eqref{3.4} is the same as the QCD PDF operator, and the Wilson line $W(n\xi,0)$ is the QCD Wilson line along the $n$ direction from $0$ to $n\xi$. The SCET calculation is identical to the QCD calculation and gives the entire kernel, including the complete $x$-dependence. The anomalous dimension below $M_J$ of the PDF operator is the usual DGLAP anomalous dimension,
%
\begin{align}
\mu \frac{\rd}{\rd \mu} O_q(r^+) &=  \int \frac{\rd s^+}{s^+} P_{qq}\left(  {r^+}/{s^+}\right) O_q(s^+) \,, \nn
P_{qq}(z) &= \frac{\alpha_s}{4\pi} \,  4C_F \left[  \frac{2}{(1-z)}_{\!+} -z-1  + \frac32\, \delta(1-z)  \right] \,.
\label{3.8}
\end{align}

The analysis in Ref.~\cite{Manohar:2003vb} was done in both $x$-space and moment space. The scale separation between $Q$ and $M_J$ is cleaner in moment space, where the $N{}^{\rm th}$ moment picks out the scale $Q^2/\overline{N}$, $\overline{N} = N e^{\gamma_E}$. This can be seen from the expression for the one-loop matching $\mathcal{M}$ in moment space
\begin{align}
M_N[ \mathcal{M}] &=1 +  \frac{\alpha_s}{4 \pi } \left\{ 4 \sum_{j=1}^{N-1} \frac {H_j }{ j} + \left(3 - 4  \lQ \right) H_{N-1}  +  2 \lQ^2  - 3  \lQ  - \pi^2 + 7 \right\} \,, \nn
&\to 1+  \frac {\alpha_s }{4 \pi }C_F \left[2  \ln^2 \frac{Q^2  }{ \overline{N} \mu^2}  - 3   \ln \frac {Q^2  }{ \overline{N} \mu^2}  - \frac {2 \pi^2 }{ 3} + 7 \right] \,,\qquad \text{as}\ N \to \infty \,.
\label{3.10}
\end{align}
Neglecting $1-x$ terms is more precise in moment space --- the expansion neglects terms which vanish as $N \to \infty$, since $1-x \sim 1/N$. The moments of $\delta(1-x)$ are $M_N[\delta(1-x)]=1$, whereas $M_N[1]=1/N$, so constant terms in $x$ space are subleading as $x \to 1$. The terms which survive as $N \to \infty$ are singular as $x \to 1$. The matching condition has no large logarithms if $\mu \sim Q/\sqrt{\overline{N}}$, which is the jet scale in moment space.

The moments of the DGLAP kernel Eq.~\eqref{3.8} are
\begin{align}
M_N \left[ P_{qq} \right] &=\frac {\alpha_s(\mu)  }{ 4 \pi}\, 2 C_F \left[ -4H_N + \frac {2 }{ N(N+1)} + 3 \right]  \nn
& \to \frac{\alpha_s(\mu)  }{ 4 \pi}\, 2 C_F \left[ -4 \ln \overline{N} + 3  \right]   \qquad \text{as}\ N \to \infty \,.
\label{3.11}
\end{align}

\section{ \texorpdfstring{Polarized DIS as $ x \to 1$: $g_1$}{Polarized DIS as x goes to 1: g1} }\label{sec:g1}

The analysis for the polarized structure function $g_1$ is almost identical to the unpolarized case. The matching from QCD to SCET at $Q$ and the SCET RGE from $Q$ to $M_J$ are unchanged. The new feature is that we must include spin-dependent terms in the OPE Eq.~\eqref{3.5} at $M_J$. These terms contribute to the antisymmetric part of $W_{\mu \nu}$. The OPE produces the structure
%
\begin{align}
-g_\perp^{\mu \nu} O_q(r^+) - i \epsilon_\perp^{\mu \nu} O_{\Delta q}(r^+) \,,
\label{3.40}
\end{align}
using the identity 
\begin{align}
    \gamma^\mu \gamma^\alpha \gamma^\nu = g^{\mu\alpha}\gamma^\nu + g^{\nu\alpha}\gamma^\mu - g^{\mu\nu}\gamma^\alpha -i\epsilon^{\mu\alpha\nu\lambda}\gamma_\lambda\gamma_5 \,,
\label{3.21}
\end{align}
%
where
\begin{align}
O_{\Delta q}(r^+) &= \frac{1}{4\pi} \int \rd \xi e^{- i \xi r^+} \overline \psi (n \xi) W(n\xi,0) \ \slashed{n} \, \gamma_5 \ \psi(0) \,,
\label{3.15}
\end{align}
is the polarized PDF operator~\cite{Manohar:1990kr,Manohar:1990jx} whose matrix elements give the polarized PDF $f_{\Delta q}(x,\mu)$
\begin{align}
\braket{P | O_{\Delta q}(x P^+) | P} &=  f_{\Delta q}(x,\mu) \,.
\label{3.25}
\end{align}
The polarized antiquark operator $O_{\Delta \overline q}(r^+) = O_{\Delta q}(-r^+) $ is given by charge conjugation, which also gives $f_{\Delta q}(-x) = f_{\Delta\overline q}(x)$.

The structure function contributions can be read off from Eq.~\eqref{2.20}.
The unpolarized contribution $-g_\perp^{\mu \nu}$ in Eq.~\eqref{3.40} gives the structure function $F_1$. The matching coefficient for $g_1$ is the same as Eq.~\eqref{3.6} for $F_1$, since they occur in the combination Eq.~\eqref{3.40}. 


The operator $O_{\Delta q}$ involves $\gamma_5$, so there are subtleties related to the definition of $\gamma_5$. These are discussed in Appendix~\ref{app:BMHV} as they don't play a role as $x \to 1$. The one-loop anomalous dimension of $O_{\Delta q}$ is the same as for the unpolarized PDF $O_{q}$, Eq.~\eqref{3.8}. The entire analysis of $g_1$ at leading power (up to terms which vanish as $N \to \infty$) is identical to $F_1$, for which the results are given in~\cite{Manohar:2003vb}.
%
Using the solutions to the RG equations 
\begin{align} \label{3.22}
    \Gamma_J(\mu_h,\mu_l) &= \int_{\mu_l}^{\mu_h} \frac{{\rm{d}}\mu}{\mu} \, \gamma_J(\mu) \,, \nn
    \Gamma_{qq,N}(\mu_h,\mu_l) &=  \int_{\mu_l}^{\mu_h} \frac{{\rm{d}}\mu}{\mu} \, M_N[P_{qq}(\mu)] \,,
\end{align}
where $M_N[P_{qq}(\mu)]$ is given in Eq.~\eqref{3.11},
the complete resummed factorization formula for $g_1$ in moment space is
\begin{align} \label{3.23}
   2 M_N(g_1) = \left( C_J(Q) \right)^2 \, e^{2\,\Gamma_J(Q,\mu_J)} \, M_N\left[\mathcal{M}\left(\mu_J\right)\right] \,  e^{\Gamma_{qq,N}(\mu_J,\mu_0)} \, A_{q,N}(\mu_0) \,,
\end{align}
where the jet scale is $\mu_J = Q/\sqrt{\Nb}$ and moments of the PDF are evaluated at a reference momentum $\mu_0$ below the jet scale. This formula includes all  $\alpha_s$ terms, and sums  the double-log series $[\alpha_s \ln^2 (1-x) ]^n$ as well as the leading-log series $[\alpha_s \ln M_J/\lqcd]^n$.


\section{ \texorpdfstring{Polarized DIS  as $ x \to 1$: $g_2$ Operators}{Polarized DIS as x goes to 1: g2 Operators} }\label{sec:g2}

The SCET analysis of $g_2$ is much simpler than the QCD analysis. It naturally  gives the twist-3 quark-gluon operators at order $\lambda$, and the twist-three PDF as a bilocal operator.

SCET cleanly extracts the twist-3 part $\overline{g}_2$. From Eq.~\eqref{2.20}, $g_2$ can be obtained from the $W_{\mu \nu}$ tensor structure
\begin{align}
W^{\mu \nu} &=    i \frac{g_1+g_2}{Q}x \left[ - (n + \overline n)^\mu \epsilon_\perp^{\nu \sigma} + (n + \overline n)^\nu \epsilon_\perp^{\mu \sigma} \right]S_\sigma \,,
\label{4.38}
\end{align}
and
\begin{align}
g_1+g_2 &= g_1 + g^{\text{WW}}_2 + \overline g_2 =  \int_x^1 \frac{\rd y}{y} g_1(y) + \overline g_2 \to \overline g_2 \,, \qquad
\text{as} \  x \to 1
\label{4.39}
\end{align}
using Eq.~\eqref{2.25}. The twist three part $\overline g_2$ is given directly from the tensor structure in Eq.~\eqref{4.38}, which has one $\parallel$ ($n$ or $\nb$)  index and one $\perp$ index.

The SCET analysis of $g_2$ requires both the leading order and  order $\lambda$ terms in the matching of $j^\nu_{\text{QCD}}$. The order $\lambda$ contribution to $W^{\mu \nu}$ is given by the interference term between the leading order and order $\lambda$ contributions. The expansion of the QCD current to order $\lambda$ was computed in~\cite{Freedman:2011kj,Goerke:2017ioi,Inglis-Whalen:2021bea,Luke:2022ops} and matches onto $q \overline q g$ SCET operators. SCET directly gives operators containing gluons without using the equations of motion. There are four kinematic sectors which are shown in Fig.~\ref{fig:1B}: \\
\textbf{topology A:} incoming $\nb$-collinear quark and outgoing $n$-collinear quark and gluon,\\
\textbf{topology B:} incoming $\nb$-collinear quark and gluon and an outgoing $n$-collinear quark,\\
\textbf{topology C:}  incoming $\nb$-collinear quark and antiquark and outgoing $\nb$-collinear gluon,\\
\textbf{topology D:}  incoming $\nb$-collinear gluon and outgoing $n$-collinear quark and antiquark. There are also the hermitian conjugate amplitudes, which exchange incoming and outgoing particles. 


Using the notation employed in \cite{Luke:2022ops}, the QCD current is given by
%
\begin{align} \label{4.3}
    j^\nu_{\text{QCD}}(x) &= C_J(\mu)\ j^\nu_{\text{SCET}}(x) + \frac{1}{Q} \sum_{i\in\{A,B,C,D\}}\int_0^1 {\rm{d}} u \, C^{(1i)}(u,\mu)O^{(1i)}(x,u,\mu) + \text{h.c.} +  O\left( \lambda^2  \right),
\end{align} 
where the superscript factor of $1$ denotes order $\lambda^1$ in the power counting. The tree-level matching is from Fig.~\ref{fig:subleading}. 
%
