\section{Set-indexed partial comonotonicity}\label{sec:set}
The first of the two formulations of partial comonotonicity comes as a generalization of $p$-concentration. 
\begin{definition}
    Given $K\subseteq[0,1]$, we say a random vector $\mathbf{X}$ is \textit{$K$-concentrated} when $\mathbf{X}$ is $p$-concentrated for each $p\in K$.
\end{definition}

 Because any random vector $\mathbf X$ is trivially $1$-concentrated and $0$-concentrated, we sometimes omit $0$ and/or $1$ from the set $K$. In this paper, the word dependence structure will refer to either $K$-concentration for some $K\subset[0,1]$, or having a particular copula (\cite{N06}). 

\begin{example} \label{ex:1} By choosing the set $K$, we can recover many well-studied dependence structures. 
\begin{enumerate}[(a)]
     \item For $p\in (0,1)$, $\{p\}$-concentration is precisely $p$-concentration. This is the most distinguishing property used to characterize $\ES_p$ in \cite{WZ21}. 
     \item With $K_c = [0,1]$,  $K_c$-concentration is equivalent to  comonotonicity (Fact \ref{fact:pcon}, item (\ref{lem:com})). This justifies the term partial comonotonicity since $K$ is always a subset of $[0,1]$. 

    \item For $p\in (0,1)$, let $K_p = [p,1]$. For $\mathbf X$ to be $K_p$-comonotonic,
    there exists a common $p$-tail event of $\mathbf X$
such that the conditional distribution of $\mathbf X$ on this event is comonotonic. This was called upper comonotonicity in \cite{C09}.
\end{enumerate}    
\end{example}




The next proposition shows that it suffices to consider concentration indexed by closed subsets of $[0,1]$.
\begin{proposition}
    For $K\subseteq [0,1]$
    with its closure denoted by $\mathsf{cl}(K)$, $K$-concentration is equivalent to $\mathsf{cl}(K)$-concentration. 
\end{proposition}
\begin{proof}
     If $p_n \downarrow p$ with each $p_n \in K$, let $A = \bigcup_{n \in \mathbb N} A_{p_n}$, where $A_{p_n}$ is a common $p_n$-tail event of $\mathbf X$ for each $n$. Since $\P$ satisfies $\sigma$-additivity, we have $\P(A) = 1-p$. If $\omega \in A$, then $\omega \in A_{p_n}$ for some $n$. Since $A^c \subseteq A_{p_n}^c$, for any $\omega^\prime \in A^c$ we have $\mathbf X(\omega) \geq \mathbf X(\omega^\prime)$, and hence $A$ is a $p$-tail event for $\mathbf X$.  Similarly, if $p_n \uparrow p$ with each $p_n \in K$, by continuity from above, $\mathbf X$ is  $p$-concentrated. 
\end{proof}



We denote by $\mathcal S$ the set of all closed subsets of $[0,1]$. The following proposition proposes a structured approach to selecting the common $p$-tail events for different levels $ p \in K$.
\begin{proposition}
    Let $K\in \mathcal S$ and suppose a random vector $\mathbf X$ is $K$-concentrated. Then there exists a collection sets $\{A_p\}_{p\in K}$ such that 
    \begin{enumerate}[(a)]
        \item for each $p\in K$, $A_p$ is a common $p$-tail event for $\mathbf X$;
        \item \label{cond:2} for $p,q \in K$ with $p > q$, we have $A_p \subseteq A_q$. 
    \end{enumerate}
\end{proposition}
\begin{proof}
    Let $S = X_1 + \dots + X_n$. By Lemma A.32 of \cite{FS16}, there exists a uniform $[0,1]$ random variable $U$ such that $Q_S(U)=S$ almost surely. For each $p\in K$, let $A_p = \{U > p\}$. Clearly, each $A_p$ is a $p$-tail event for $S$ and the collection satisfies condition (\ref{cond:2}). By item (\ref{lem:sum}) of Fact \ref{fact:pcon}, each $A_p$ is also a common $p$-tail event for $\mathbf X$.
\end{proof}

    We call $\{A_p\}_{p\in K}$ satisfying (i) and (ii) above a nested collection of common tail events. 










 We are ready to develop results regarding the additivity of quantile functions. We start by introducing the notion of partial comonotonic additivity.
\begin{definition}
    Let $K\in \mathcal S$. A riskmetric $\rho$ is \textit{$K$-additive} if for all $K$-concentrated random vectors $\mathbf X = (X_1, \dots, X_d) $, we have 
    $$\rho\left(\sum_{i=1}^d X_i\right) = \sum_{i=1}^d \rho( X_i).$$
\end{definition}



\begin{theorem} \label{thm:quant}
    Let $p\in (0,1]$ and $K$ be a closed subset of $[0,1]$. The following are equivalent:
    \begin{enumerate}[(a)]
        \item $\mathrm{VaR}_p$ is $K$-additive.
        \item There exists a strictly increasing sequence $p_n \uparrow p$ with each $p_n \in K$.

    \hspace*{-2.7em} Similarly, for $p\in [0,1)$, the following are equivalent:

        \item $\mathrm{VaR}^+_p$ is $K$-additive.
        \item There exists a strictly decreasing sequence $p_n \downarrow p$ with each $p_n \in K$.
    \end{enumerate}
\end{theorem}
\begin{proof}
    Let $p_n \uparrow p$ and $\mathbf X = (X_1, \dots, X_d)$ be $p_n$-concentrated for each $n\in \mathbb N$.  By (\ref{lem:ineq}) from Fact \ref{fact:pcon}, for each $n\in \mathbb N$ we have the inequalities
    \begin{align*} \sum_{i=1}^d \VaR_{p_{n}} (X_i) \leq \sum_{i=1}^d \VaR^+_{p_{n}} (X_i) &\leq \VaR^+_{p_{n}} \left(\sum_{i=1}^d X_i\right)\\
    &\leq \VaR_{p_{n+1}} \left(\sum_{i=1}^d X_i\right ) \leq \sum_{i=1}^d \VaR_{p_{n+1}}(X_i).
    \end{align*}
As $n\to \infty$, by the left-continuity of the left quantile function, the first and last terms converge to $\sum_{i=1}^d {\VaR_p(X_i)}$,  and therefore the last two terms are equal in the limit.\\
Similarly for $p_n \downarrow p$, we have
    \begin{align*} \sum_{i=1}^d \VaR^+_{p_{n}} (X_i) \geq \sum_{i=1}^d \VaR_{p_{n}} (X_i) &\geq \VaR_{p_{n}} \left (\sum_{i=1}^d X_i\right )\\
    &\geq \VaR^+_{p_{n+1}} \left (\sum_{i=1}^d X_i\right ) \geq \sum_{i=1}^d \VaR^+_{p_{n+1}}(X_i).
    \end{align*}
    As $n\to \infty$, by the right-continuity of the right quantile function, the first and last terms converge to $\sum_{i=1}^d {\VaR^+_p(X_i)}$ and the last two terms are equal in the limit.\\
    For the converse directions, see the proof of Theorem \ref{thm:KCA}.
\end{proof}


The following proposition enables us to focus on the special case $d=2$ for many of the proofs that follow.



\begin{proposition}
\label{prop:incr-trans}
Fix $d\in \mathbb N$, $K\in \mathcal S$ and $\mathbf X\in \mathcal X^d$. We have that 
    $\mathbf X  $ is $K$-concentrated if and only if for any $k\in\mathbb N$ and any (componentwise) increasing function $\mathbf f = (f_1, \dots, f_k) : \R^d \mapsto \R^k$, $\mathbf f (\mathbf X)$ is $K$-concentrated.
\end{proposition}
\begin{proof}
    Take $p \in K$ and let $A_p$ be a common $p$-tail event for $\mathbf X$. For a.s. all $\omega \in A_p$ and  $\omega^\prime \in A_p^c$, we have $\mathbf X(\omega) \geq \mathbf X(\omega^\prime)$. Since $\mathbf f$ is increasing, $[\mathbf f(\mathbf X)](\omega) \geq [\mathbf f(\mathbf X)](\omega^\prime)$ so that $A_p$ is a common $p$-tail event for $\mathbf f(\mathbf X)$, and hence $\mathbf f(\mathbf x)$ is $p$-concentrated. 
\end{proof}

The invariance property under increasing transforms in Proposition \ref{prop:incr-trans}  is also satisfied by the popular dependence concept of positive association, introduced by \cite{EPW67}, who showed that 
if $\mathbf X$ is positively associated, then so is $\mathbf f(\mathbf X)$ for any increasing function $\mathbf f $. Proposition \ref{prop:incr-trans} generalizes
the fact that comonotonicity satisfies this invariance,  
 shown by \cite{LLW23}.

\begin{remark}
    Suppose $\rho$ is additive for $2$-dimensional $K$-concentrated vectors. That is, $\rho(X+Y) = \rho(X)+\rho(Y)$ for any $K$-concentrated random vector $(X,Y)$. Since addition is a pointwise increasing function, for  a $K$-concentrated random vector $(X_1, X_2, X_3)$, $(X_1, X_2+X_3)$ and $(X_2, X_3)$ are both $K$-concentrated. So that
\begin{align*}
    \rho(X_1+X_2+X_3) = \rho(X_1+(X_2+X_3)) &= \rho(X_1)+\rho(X_2+X_3) \\ &= \rho(X_1)+\rho(X_2)+\rho(X_3).
\end{align*}
This shows that considering the case $d=2$ does not lose generality. 
\end{remark} 

We are ready to develop criteria for $K$-additivity for general distortion riskmetrics. 

For any  $K\in \mathcal S$, we decompose $  K^c$ as a disjoint union of open intervals $\{B_i\}_{i \in \mathbb N}$.
For a subset $B$ of $[0,1]$, let $1-B=\{1-x:x\in B\}$.

\begin{theorem}\label{thm:KCA} 
   For   $K\in \mathcal S$ and $h\in \mathcal{H}^{\rm bv}$,  a distortion riskmetric $I_h$ is $K$-additive if and only if
   $h$ is linear on each $\mathsf{cl}(1-B_i$).
\end{theorem}  

\begin{proof}
    Given $h$ with bounded variation, decompose $h = h_l+h_r+h_c$ where $h_l$ (resp. $h_r$) is constant except for jumps that are left- (resp. right-) continuous,  and $h_c$ is continuous. Let $\hat h, \hat h_c, \hat h_l, \hat h_r$ be corresponding conjugate functions. The functional $I_{h_l}$ is a countable weighted sum of left quantiles, and similarly, $I_{h_r}$ is a countable weighted sum of right quantiles. Note that $h$ being continuous on $\mathsf{cl} (1-B_i)$ is equivalent to $\hat h$ being continuous on $\mathsf{cl}(B_i)$. 



By Fact \ref{fact:choquet} (\ref{choquet:rquantile}) and (\ref{choquet:lquantile}),  we have
\begin{align*}
    I_h &= I_{h_c}+I_{h_l}+I_{h_r}\\
    &=\int_0^1 Q^-_{(~\cdot~)}(p) \d \hat h_c (p) +\int_0^1 Q^-_{(~\cdot~)} (p)\d \hat h_l (p)+\int_0^1 Q^+_{(~\cdot~)} (p)\d \hat h_r (p).
\end{align*}
Suppose $(X,Y)$ is $K$-concentrated. Let $\{A_p\}_{p\in K}$ be a nested family of common tails, we have 
\begin{align*}
I_{h_c}(X+Y) &= \int_0^1 Q^-_{X+Y}(p) \d \hat h_c(p)\\
&= \sum_{i=1}^\infty \int_{K_i} Q^-_{X+Y}(p) \d \hat h_c(p) + \sum_{i=1}^\infty \int_{B_i} Q^-_{X+Y}(p) \d \hat h_c(p).
\end{align*}
Let $m_i$ be the slope of $\hat h_c$ on $B_i=(a_i,b_i)$, and let $\Omega_i = A_{a_i} \setminus A_{b_i}$, we have:
\begin{align*}
     \int_{B_i} Q^-_{X+Y}(p) \d \hat h_c(p) 
    &= m_i \E[(X+Y) \mathds{1}_{\Omega_i}]\\ 
    &= m_i \E[X \mathds{1}_{\Omega_i}] +m_i \E[Y \mathds{1}_{\Omega_i}]\\
    &= \int_{B_i} Q^-_{X}(p) \d \hat h(p) +\int_{B_i} Q^-_{Y}(p) \d \hat h(p).
\end{align*} 
 For an interior point $p$ of $K$, Theorem \ref{thm:quant} implies that $Q^-_{X+Y}(p) = Q^-_X(p)+Q^-_Y(p)$. Combining the above arguments,  $I_{h_c}$ is $K$-additive.

Next suppose for some $p\in [0,1]$, $\VaR_p^-$ is not $K$-additive. By Theorem \ref{thm:quant}, $p \in (a_i, b_i]$ for some $B_i = (a_i, b_i)$. Since $\hat h$ is continuous on $[a_i,b_i]$, $\hat h_l$ is continuous at $p$ and $I_{h_l}$ does not have a mass on $\VaR_p^-$, this shows that $I_{h_l}$ is $K$-additive. A similar argument shows that $I_{h_r}$ is also $K$-additive.




For the only if direction, we construct counterexamples taking $\Omega = [0,1]$.

Case 1: If $\hat h$ is not linear on some $B_i = (a,b)$. Pick $X,Y$ such that $X=Y = 0$ on $[0,a]$ and $X = Y = 3$ on $[b,1]$. Since $I_h$ is not a multiple of the expectation on $(a,b)$, we can pick $X, Y$ to have range $[1,2]$ on $(a,b)$ so that $I_h$ restricted to $B_i$ is not additive. This can be done because $K$-concentration puts no restriction on the dependence structure of ($X|_{(a,b)}, Y|_{(a,b)})$.  Since $X=Y$ outside $(a,b)$, $I_h$ is additive when restricted to $(a,b)^c$. Overall, $I_h$ is not additive for $(X,Y)$. 

Case 2: Suppoes for some $B_i = [a_i, b_i]$,  $\hat h$ is not right continuous at $a$. Then $I_h$ puts a mass on $Q^-_a$ and for some $\epsilon \in (0,a)$,  $(a-\epsilon, a) \cap K = \emptyset$. A counterexample is illustrated by Figure \ref{fig:example}. Let $U$ be a uniform $[0,1]$ random variable, $X = f(U)$ and $Y=g(U)$ with $f,g$ being the two functions in the illustration. 

Case 3: A similar counterexample can be constructed where additivity fails due to a mass on some $Q^+_{b_i}$.  
\end{proof}


