\section{Function-indexed partial comonotonicity}\label{sec:func}


For random variables $X,Y,Z$, if $(X,Z)$ and $(Y,Z)$ are comonotonic, it is in general not true that $(X,Y)$ is also comonotonic. That is, the property of having perfect comovement is not transitive.  However, depending on $Z$, the property is partially transitive. 


In this section, we define and investigate partial comonotonicity indexed by functions, and establish an equivalence to set-indexed comonotonicity.  Let $\mathcal G$ be the collection of left-continuous increasing functions from $[0,1]$ to $\R$. 
\begin{definition}
Let $g \in \mathcal G$. A random vector $(X_1, \dots, X_d)$ is \textit{$g$-comonotonic} if there exists a random variable $Z$ such that
\begin{enumerate}[(a)]
    \item the left quantile function $Q^-_Z$ is equal to $g$, and
    \item $(X_i,Z)$ is comonotonic for all $i=1, \dots, d$.
\end{enumerate}
\end{definition}

\begin{definition}
    Given $g \in \mathcal G$, a riskmetric $\rho$ is
 \textit{$g$-additive} if for all random vector $(X_1, \dots, X_d)$ satisfying $g$-comonotonicity, we have $\rho(X_1 + \cdots +X_d) = \rho(X_1)+ \cdots + \rho(X_d)$.

\end{definition}




%\begin{definition}\label{f-o}
For $f,g \in \mathcal G$, we write $ f \precsim g $ when
    there exists an increasing function $h$ such that $f = h \circ g$.
%\end{definition}


\begin{proposition}\label{prop:order}
    If $f \precsim g$, then $g$-comonotonicity implies $f$-comonotonicity, and in turn, $f$-additivity implies $g$-additivity.
\end{proposition}
\begin{proof}
    Let $h$ be such that $f = h \circ g$, and $Z$ be as in the definition of $g$-comonotonicity. Then $h(Z)$ satisfies the definition of $f$-comonotonicity. The other claim follows trivially.
\end{proof}

\begin{remark} \label{rmk:eq}
    The symmetric part of the pre-order $\precsim $ defines an equivalence relation $\cong$. For $f,g \in \mathcal G$, the following are equivalent:
    \begin{enumerate}[(a)]
        \item $f$-comonotonicity is equivalent to $g$-comonotonicity;
        \item $f \cong g$;
        \item for all $0\leq a<b\leq 1$, $f(a)=f(b)$ if and only if $g(a)=g(b)$.
    \end{enumerate} 
\end{remark}

 To establish a connection between the two notions of partial comonotonicity, we first define two functions.

Define the map $\mathcal I : \mathcal G \mapsto \mathcal S$ as follows.
Given $g \in \mathcal G$, define an equivalence relation $\sim$ on $[0,1]$ by $a\sim b$ if and only if $g$ is constant on $[\min(a,b),\max(a,b)]$. Each equivalence class is an interval. Let $\{D_\lambda\}_{\lambda \in \Lambda}$ be the set of equivalence classes. Replace each $D_\lambda$ by its interior, and there are only countably many non-empty sets remaining, denoted by $(B_i)_{i=1}^\infty$. Take $B = \bigcup_{i=1}^\infty B_i$ and $\mathcal I(g)$ to be $B^c$. 

We next define the map $\mathcal V: \mathcal S \mapsto \mathcal G$. Given $K\in \mathcal S$, let $K_i=[c_i, d_i]$ be the disjoint closed partition of $K$ and $B_i = (a_i, b_i)$ be the disjoint open partition of $K^c$. If $p\in (a_i, b_i)$ for some $i$, take $g(p) = a_i$. If $p \in [c_i, d_i]$ for some $i$, take $g(p) = p$. Modify any discontinuities of $g$ such that $g$ is left-continuous. Define $\mathcal V(K) = g$. It is straightforward to check that $g$ is increasing. 

Intuitively, $\mathcal I(g)$ is the set on which $g$ is strictly increasing, and $\mathcal V(K)$ is a function with slope $1$ on $K$, slope $0$ on $K^c$. 
\begin{proposition}\label{prop:adj} The maps $\mathcal V$ and $\mathcal I$ have the following properties:
    \begin{enumerate}[(a)]
        \item $\mathcal V (\mathcal I(g)) \cong g$ for all $g \in \mathcal G$; 
        \item $\mathcal I (\mathcal V(K)) = K$ for all $K\in \mathcal S$.
        \item $g_1 \precsim g_2 \implies \mathcal I(g_1) \subseteq \mathcal I(g_2)$ for all $g_1, g_2 \in \mathcal G$;
        \item $K_1 \subseteq K_2 \implies \mathcal V(K_1) \precsim \mathcal V(K_2)$ for all $K_1, K_2 \in \mathcal S$. 
    \end{enumerate}
\end{proposition}
\begin{proof}
The proofs are straightforward by the constructions of $\mathcal I$ and $\mathcal V$. 
    \begin{enumerate}[(a)]
        \item Let $f = \mathcal V (\mathcal I(g))$. Take $0\leq a < b \leq 1$, we show that $f(a)=f(b)$ if and only if $g(a)=g(b)$. If $g(a)=g(b)$, then $(a,b) \subseteq B_i = (a_i, b_i)$ for some $i$. By construction $f(a)=a_i = f(b)$. If $g(a)\neq g(b)$, let $B_i=(a_i,b_i)$ be the equivalence class such that $[a_i, b_i)$ contains $a$. Then $f(a) = a_i < b_i \leq f(b)$.
        \item Let $L = \mathcal I (\mathcal V(K))$. Let $(a,b)$ be a maximal open interval contained in $K^c$ and $g=\mathcal V(K)$, we have $g \equiv a$ on $[a,b)$, and $g(x) \neq a$ for any $x \notin [a,b)$. Hence by construction, $(a,b) \cap L = \emptyset$ and $a,b \in L$, so that $(a,b)$ is also a maximal open interval contained in $L^c$.
        \item When $g_1 \precsim g_2$, for any $a,b\in [0,1]$ we have $g_2(a)=g_2(b)\implies g_1(a) = g_1(b)$. If $(a,b)$ is one of the $B_i$ in the construction of $\mathcal I(g_2)$, then some $(a^\prime, b^\prime)$ with $a^\prime \leq a$ and $b \leq b^\prime$ is one of the $B_i$ in the construction of $\mathcal I(g_1)$, so that $\mathcal I(g_2)^c \subseteq \mathcal I(g_1)^c$.
        \item Let $g_1 = \mathcal V(K_1)$ and $g_2 = \mathcal V(K_2)$. Suppose for some $a,b \in [0,1]$ we have $g_2(a)=g_2(b)$, we show that $g_1(a) = g_1(b)$. By the definition of $\mathcal V$, $(a,b) \subseteq K_2^c$. Hence $(a,b) \subseteq K_1^c$ and $g_1(a) = g_1(b)$.
        \qedhere
    \end{enumerate}
\end{proof}
The following theorem establishes the equivalence between the two notions of partial comonotonicity.
\begin{theorem} For $K\in \mathcal S$ and $g \in \mathcal G$, we have the following equivalences:
    \begin{enumerate}[(a)]
        \item \label{item:KtoVK}$K$-concentration is equivalent to  $\mathcal V(K)$-comonotonicity;
        \item \label{item:gtoIg}$g$-comonotonicity is equivalent to $\mathcal I(g)$-concentration.
    \end{enumerate}
\end{theorem}
\begin{proof}
(\ref{item:KtoVK}) $\Rightarrow$: Let $g = \mathcal V(K)$ and suppose $\mathbf X$ is $K$-concentratated. Let $\{A_p\}_{p\in K}$ be a nested collection of common tail events, that is, $p > q \implies A_p \subseteq A_q$. Let $K_i = [c_i, d_i]$ be the closed partition of $K$ and $B_i = (a_i, b_i)$ be the open partition of $K^c$. For $\omega \in \Omega$ let $p = \sup \{q: q\in K, \omega \in A_q\}$.  Define $Z(\omega)$ according to the following rules. 
\begin{enumerate}[(i)]
    \item If $\omega \notin A_p$, take $Z(\omega) = p$. 
    \item If $\omega \in A_p$ and there exists a strictly decreasing sequence $p_n \downarrow p$ with $p_n \in K$ for each $n$, also take $Z(\omega) = p$. 
    \item Otherwise, let $r = \inf \{ q: q> p, q\in K\}$ and take $Z(\omega) = (r+p)/2$.
\end{enumerate}
We first show that each $X_i$ is comonotonic with $Z$. Fix $i$, and take $\omega_1, \omega_2 \in \Omega$. Without loss of generality, assume $p_1 = Z(\omega_1) < Z(\omega_2)= p_2$. 
If $p_1$ arises from case (i), pick $p = p_1$. If $p_1$ arises from case (ii), pick $p$ with $p_1 < p < p_2$. If $p_1$ arises from case (iii), pick $p = r$. In all cases, $\omega_2 \in A_p$ but $\omega_1 \notin A_p$ and hence $X_i(\omega_2) \geq X_i(\omega_1)$. 

(\ref{item:KtoVK})$\Leftarrow$: Let $\mathcal V(K) = g$. Suppose $\mathbf X$ is $g$-comonotonic. Let $Z$ be the random variable comonotonic with each $X_i$ with $Q_Z=g$. For each $p\in K$, define $A_p = \{\omega: Z(\omega) > p\}$. By the construction of $\mathcal V(K)$, $\P(A_p) = 1-p$ and for any $\omega \in A_p, \omega^\prime \in A_p^c$, $Z(\omega) > Z(\omega^\prime)$. Comonotonicity then requires $X_i(\omega) \geq X_i(\omega^\prime)$ for each $i$, so that $\mathcal X$ is $p$-concentrated for each $p\in K$.

(\ref{item:gtoIg}): Combining (\ref{item:KtoVK}), Remark \ref{rmk:eq} and Proposition \ref{prop:adj}, we have the following equivalences:
\begin{center}
    $g$-comonotonicity $\Leftrightarrow \mathcal V(\mathcal I(g))$-comonotonicity $\Leftrightarrow \mathcal I(g)$-comonotonicity.\qedhere
\end{center}
\end{proof}
\begin{remark}
    Let $K\in \mathcal S$. Using the terminology of copulas, $K$-concentration represents a collection of copulas $\mathcal C_K$, in the sense that a random vector $\mathbf X$ is $K$-concentrated if and only if the copula of $\mathbf X$ is a member of $\mathcal C_K$. The best tool to describe $\mathcal C_K$ is ordinal sums from \citet[Section 3.2.2]{N06}. Let the open intervals $\{B_i:=(a_i,b_i)\}$ be a disjoint partition of $K^c$ and closed intervals $\mathcal K=\{K_i := (c_i, d_i)\}$ be a disjoint partition of $K$. Replace each $B_i$ by its closure $[a_i,b_i]$. 
    Let $\{J_i\}$ be the collection of non-degenerate closed intervals among all $\overline{B_i}$ and $K_i$. Any collection of copulas $\{C_i\}$ with the same index of $\{J_i\}$ defines a copula through the ordinal sum. Such an ordinal sum copula is a member of $\mathcal C_K$ if the following holds:
    \begin{align*}
        &\mbox{each $C_i$ is the comonotonic copula when   $J_i \in \mathcal K$.} 
    \end{align*}
Conversely, all members of $\mathcal C_K$ is of this form. Figure \ref{fig:ordinal} illustrates this idea. Take $K = [0,1/3]\cup [2/3,1]$. Put any copula inside the middle box, the resulting ordinal sum copula is in $\mathcal C_K$.
