\section{Scattering wave functions in both configuration space and momentum space}
The $s$-wave radial wave functions for the $NN$ scattering are
derived from the $t$-matrices in momentum space. The single (S=0) and triplet (S=1)
wave functions with the initial momentum $p$ are
\begin{align}
 \psi_{\ell=0}^S (r;p) =& \sqrt{\frac{2}{\pi}}\left\{ j_0(pr) +\int_0^\infty p_3^2 dp_3 \sum_{\ell'=0,2}
 (\delta_{S0}\delta_{\ell'0}+\delta_{S1}) \right. \notag \\
 & \left. \times \frac{j_{\ell'}(p_3 r)t_{\ell,\ell'}^S(p_3,p)}
{\frac{\hbar^2}{2\mu}p^2-\frac{\hbar^2}{2\mu}{p_3^2}+i\epsilon}\right\},
\end{align} 
where $\mu=\mu_{NN}=m_N/2$ is a reduced mass, $j_\ell$ stands for a spherical Bessel function,
and the factor $\sqrt{\frac{2}{\pi}}$ corresponds to the natural normalization of the plane wave.
The numerical integration of $p_3$ with the pole at $p_3=p$ is carried out by the subtraction method.
The wave function for the $\ell'=0$ part is expressed as follows,
employing the relation $\frac{1}{p^2-p_3^2+i\epsilon}=P\frac{1}{p^2-p_3^2}-i\frac{\pi}{2p}\delta(p_3-p)$.
\begin{align}
 & \psi_{\ell=0,(\ell'=0)}^S (r;p) = \sqrt{\frac{2}{\pi}}
 \left\{ (1-i\frac{\pi \mu p}{\hbar^2} t_{0,0}^S(p,p))j_0(pr) \right. \notag\\
  & \hspace{3em}+\left. \frac{2\mu}{\hbar^2} P\int_0^\infty p_3^2 dp_3
 \frac{ j_{0}(p_3r)t_{0,0}^S(p_3,p)}{p^2-{p_3^2}}
 \right\}.
\label{eq:a1}
\end{align}
The standard prescription for the numerical treatment of the principal-value integration is
\begin{align}
 & P\int_0^\infty p_3^2 dp_3 \frac{ j_{0}(p_3 r)t_{0,0}^S(p_3,p)}{p^2-{p_3^2}} \notag\\
 =& \int_0^\infty p_3^2 dp_3 \frac{ j_{0}(p_3r)(t_{0,0}^S(p_3,p)-t_{0,0}^S(p,p))}{p^2-{p_3^2}} \notag\\
 & + t_{0,0}^S(p,p)P\int_0^\infty p_3^2 dp_3 \frac{ j_{0}(p_3 r)}{p^2-{p_3^2}} \notag\\
 =& \int_0^\infty p_3^2 dp_3 \frac{ j_{0}(p_3 r)(t_{0,0}^S(p_3,p)-t_{0,0}^S(p,p))}{p^2-{p_3^2}} \notag\\
 & -\frac{\pi}{2}\frac{1}{r} \cos(pr)t_{0,0}^S(p,p)
\end{align}
Because the phase shift $\delta_{\ell=0}^S$ is defined as
\begin{equation}
 e^{2i\delta_{\ell=0}^S} =1-2\pi i \frac{\mu}{\hbar^2}p t_{0,0}^S(p,p),
\end{equation}
Eq. (\ref{eq:a1}) can be reduced to
\begin{align}
 & \psi_{\ell=0}^S (r) = \sqrt{\frac{2}{\pi}}\left\{ \frac{1}{pr}e^{i\delta_{\ell=0}^S}
 \sin(pr+\delta_{\ell=0}^S) \right. \notag \\
 & \left. +\frac{2\mu}{\hbar^2} \int_0^\infty p_3^2 dp_3
 \frac{ j_{0}(p_3 r)(t_{0,0}^S(p_3,p)-t_{0,0}^S(p,p))}{p^2-{p_3^2}} \right\}.
\end{align} 
The principal value integration in the $\ell'=2$ part requires the utilization of the formula
\begin{align}
  t_{0,2}^S(p,p)P\int_0^\infty p_3^2 dp_3 \frac{ j_{2}(p_3 r)}{p^2-{p_3^2}} \notag \\
 =t_{0,2}^S(p,p)\frac{\pi p}{2}
 \left\{ \frac{3}{(pr)^3} + n_2(pr)\right\},
\end{align}
where $n_2$ is a spherical Bessel function of the second kind.

The corresponding wave function in momentum space is expressed as follows:
\begin{align}
  \tilde{\psi}_{\ell=0}^S (p_3;p) =& \frac{\delta(p_3-p)}{p_3p}e^{i\delta_{\ell=0}^S}
 \cos(\delta_{\ell=0}^S)+\frac{2}{\pi p} e^{i\delta_{\ell=0}^S}P\frac{1}{p_3^2-p^2} \notag \\
 & +\frac{2\mu}{\hbar^2} \frac{(t_{0,0}(p_3,p)-t_{0,0}(p,p))}{p^2-{p_3^2}},
\end{align}
This is a generalized function. The $\delta$-function and the principal values are taken care of
in the integration in Eq. (\ref{eq:g3}). It is noted that $\tilde{\psi}_{\ell=0}^S (p)$ is reduced
to the free solution of $\frac{1}{p_3 p}\delta(p_3-p)$ in the case of $V_{np}=0$.

