We start with well-posedness and basis properties of the solution to \eqref{eq-main}.
Here, we consider solutions in the classical sense. Particularly, a $\F_t$-adapted stochastic process $(u(t,x),v(t,x))$ is a solution to \eqref{eq-main} if almost surely, $u(t,x),v(t,x)$ are differentiable in $t$, twice differentiable in $x$ and satisfy \eqref{eq-main}.

\begin{thm}\label{thm-pre}
	Let $E$ be an open bounded connected subset of
	$\RR^n$, $n\geq1$. 
	Assume that $\partial E \in H^{2+l}$ for some $l$ satisfying $0 < l < 1$. 
	Let $u_0$, $v_0$ be non-negative valued functions in $H^{2+l}(\bar E)$ with vanishing normal derivatives on $\partial E$. 
	Then, we have the following claims.
	\begin{itemize} 
\item[{\rm (i)}] Equation \eqref{eq-main} with initial condition $(u_0,v_0)$ and boundary conditions \eqref{e3} has a
	unique solution $(u(t,x)$, $v(t,x))$.
	Moreover, $u(t,\cdot)\in H^{2+l}(\bar E)$, $v(t,\cdot)\in H^{2+l}(\bar E)$ for all $t>0$ a.s.
\item[{\rm(ii)}] $u(t,x)\geq 0$, $v(t,x)\geq 0$ for all $(x, t)\in \bar E\times [0,\infty)$ a.s.
\item[{\rm (iii)}] If $u_0$, $v_0$ are not identically zero, then both $u(t,\cdot)$, $v(t,\cdot)$ are strictly positive for all $t >0$ a.s.
\item[{\rm (iv)}]
The solution is bounded almost surely. More precisely, with probability 1
\begin{equation}
	0\leq u(t,x)\leq M_1,\;0\leq v(t,x)\leq M_2,\;\forall (t,x)\in (0,\infty)\times \bar E,
\end{equation}
where
$$M_1>\max\Big\{\max_{i\in\{+,-\}}\frac{a(i)}{b(i)},\sup_{x\in\bar E}u_0(x)\Big\},$$
and
$$ M_2>\max\Big\{\max_{i\in\{+,-\}}\frac{a(i)}{c(i)},\max_{i\in\{+,-\}}\frac{M_1e(i)-d(i)}{f(i)},\sup_{x\in\bar E}v_0(x)\Big\}.$$

	\end{itemize}
\end{thm}

\begin{proof}
The proof of this theorem for deterministic systems \eqref{e6+} and \eqref{e6-} can be found in \cite{leung1978limiting}.
	It is noted that \eqref{eq-main} is switching system that switch (randomly based on the changes of $\xi(t)$) between two deterministic systems \eqref{e6+} and \eqref{e6-}, and $M_1$, $M_2$ are independent of $\xi(t)$. Therefore, the proof this theorem can follow \cite{leung1978limiting}.
\end{proof}

One of our main motivations comes from ecology, where ecologists seek to determine whether a particular ecological population is at risk of extinction or can persist over time since understanding these dynamics is crucial for conservation efforts and managing biodiversity. To address this, we introduce the following concepts.
\begin{defn}
	We say a specie with density $z(t,x)$ is extinct in strong sense if 
	$$\lim_{t\to\infty} \sup_Ez(t,x)=0 \text{ a.s.}$$
\end{defn}

\begin{defn}
	We say a specie with density $z(t,x)$ is persistent in average sense if 
	\begin{equation*}
		\liminf_{T\to\infty}\frac 1T\int_0^T \frac 1{|E|}\int_E z(t,x)dxdt>\delta>0,
	\end{equation*}
	for some $\delta$, which is independent of initial condition.
\end{defn}


We also want to study further the limit set behavior of systems.
Adapting the definition introduced in \cite{du2011dynamics}, we define $\omega$-limit set as follows.
\begin{defn}
	The $\omega$-limit set of the trajectory starting from an initial value $(u_0, v_0)$ is
	$$
	\Omega(u_0,v_0,\omega) =\displaystyle\bigcap\limits_{T>0}\bar{
		\bigcup\limits_{t>T}
		%\bigcup\limits_{x\in E}
		(u(t,\cdot,\omega), v(t,\cdot,\omega))},
	$$	
	with the closure being obtained under supremum norm in $C(\bar E)$,
%		and the spatial $\omega$-limit set of the trajectory in $x$ starting from an initial value $(u_0, v_0)$ is
%	$$
%	\Omega^x(u_0,v_0,\omega) =\displaystyle\bigcap\limits_{T>0}\bar{
%		\bigcup\limits_{t>T}
%		%\bigcup\limits_{x\in E}
%		(u(t,x,\omega), v(t,x,\omega))},
%	$$
	where $(u(t,\cdot,\omega), v(t,\cdot,\omega))$ is solution to \eqref{eq-main} with initial condition $(u_0,v_0)$.

\end{defn}  



This definition generalizes the concept in \cite{du2011dynamics} to functional space. As remarked in \cite{du2011dynamics}, this type of $\omega$-limit set is different from the one in \cite{crauel1994attractors} but it is closest to that of an $\omega$-limit set for a deterministic dynamical system. In the case where $\Omega(u_0, v_0,\omega)$ is a.s constant, it is similar to the concept
of weak attractor and attractor given in \cite{mao2001attraction}. Although, in general, the $\omega$-limit set in this sense
does not have the invariant property, this concept is appropriate for our purpose of describing the
pathwise asymptotic behavior of the solution with a given initial value.

\section{Asymptotic Behavior}\label{sec:class}
This section investigates the long-term behavior of the system \eqref{eq-main}, with a particular focus on classifying conditions for extinction and persistence. To this end, we introduce a threshold parameter 
$\lambda$, whose sign is shown to determine these asymptotic properties. In Section \ref{sec:kpp}, we first study a random Fisher–KPP equation in detail. This equation not only plays a key role in the definition of 
$\lambda$ but is also of independent interest. Section \ref{subsec-class} then formally defines the threshold $\lambda$ and establishes that its sign characterizes extinction and persistence. Finally, Section \ref{sec-omega} describes the 
$\omega$-limit set of solutions to \eqref{eq-main}.
\subsection{Random Fisher-KPP equation}\label{sec:kpp}
To analyze the long-term behavior of the reaction-diffusion predator-prey system with random switching \eqref{eq-main}, it is essential to first examine the related boundary problem (i.e., the related system when $v(t,x)=0$). Specifically, this involves studying the random  Fisher-KPP equation. Consequently, this section is dedicated to investigating the random Fisher-KPP equation.
% which is also of independent interest.

The deterministic Fisher-KPP equation (see e.g., \cite{fisher1937wave,kolmogorov1937etude}) is given by
\begin{equation}\label{e0}
\begin{cases}
\dfrac{\partial\tilde{u}(t,x)}{\partial t}=\alpha_1\Delta \tilde{u}(t,x) + \tilde{u}(t,x)(a- b\tilde{u}(t,x)),\\[1ex]
\tilde{u}(0,x)=u_0(x)\geq 0, x\in E,
\end{cases}
\end{equation}
with the boundary condition 
\begin{equation}\label{bc}\frac{\partial \tilde{u}}{\partial n}=0 \text{ on } [0,\infty)\times \partial E.
\end{equation}
 It is well-known that if $u_0\geq 0$ then \eqref{e0} has a unique solution $\tilde{u}(t,x)$ bounded by $\max\set{\frac ab, \sup_{\bar E} u_0(x)}$ on  $(0,\infty)\times \bar E$ and $\lim_{t\to\infty} U(t,x)=\frac ab$ uniformly on $\bar E$. 
%Let  $\xi_t, t\geq 0$ be a Markov process with valued in the set $S=\{+,-\}$. 

