\begin{equation}\label{e1}
\begin{cases}
\dfrac{\partial \tilde{u}(t,x)}{\partial t}=\alpha_1(\xi(t))\Delta \tilde{u}(t,x) + \tilde{u}(t,x)(a(\xi(t))- b(\xi(t))\tilde{u}(t,x)),\\[1ex]
\tilde{u}(0,x)=u_0(x)\geq 0, x\in E,
\end{cases}
\end{equation}
with the boundary condition \eqref{bc}.
It is easy to see that \eqref{e1} has a unique solution $\tilde{u}(t,x)$ bounded by $\max\set{\max_{i\in\{+,-\}}\frac {a(i)}{b(i)}, \sup_{\bar E} u_0(x)}$ on  $(0,\infty)\times\bar E$.

