In this section, we will go further to investigate the $\omega$-limit set of the solution.
We start with the following lemma regarding the behavior of deterministic system \eqref{eq-pde}.
\begin{lem}\label{lem-com}  
	Consider the deterministic system \eqref{eq-pde}.
	Let $K$ is a compact in $C(\bar E)$ such that $z\in K$ implies $z\geq \delta$ for some $\delta>0$.	
	%\begin{itemize}
	%\item if $\dfrac ab>\dfrac de$ then \eqref{e1} has a unique  equilibrium point $$(u^*,v^*)=\Big(\frac {af+cd}{bf+ce},\frac {ae-bd}{bf+ec}\Big)$$ which attracts (in $C^0(\bar E)$) every  positive solution;
	%\item 
	\begin{itemize}
		\item[]{\rm (i)} If $\frac ab>\frac de$ then, \eqref{e1} has a unique  equilibrium point 
		$$(u^*,v^*)=\Big(\frac {af+cd}{bf+ce},\frac {ae-bd}{bf+ec}\Big),$$
		%which attracts all positive solution.
		and
		 $\lim_{t\to\infty} (u(t,x),v(t,x))=(u^*,v^*)$ uniformly on $E$ and  on $K$. Further, for any $\eps>0$,  there is a $T=T(\eps)$ such that 
		$
		(u(t,\cdot),v(t,\cdot))\in U_\eps(u^*,v^*)$ for all $t\geq T$, 
		provided $u(0,x),v(0,x)\in  K,$
		where $U_\eps(u^*,v^*)$ is $\eps$-neighbor of constant functions $(u^*,v^*)$ in $C(\bar E)$.

		\item[]{\rm (ii)} If $\sup_Ev(t,x)\to 0$ then $u(t,x)\to\frac{a}{b}$ uniformly in $E$.

		\item[]{\rm (iii)} 
		If $\frac ab<\frac de$ then $\lim_{t\to\infty} (u(t,x),v(t,x))=\Big(\frac ab,0\Big)$ uniformly on $E$ and this convergence is uniform in initial condition $u_0\in K$, and $v_0\geq 0\in H^{2+l}(\bar E)$.
	\end{itemize} 
\end{lem}
\begin{proof}
We first prove (i). For each $\bar u,\bar v\in K$, 
	by \cite{leung1978limiting}, the solution $ (u(t,x),v(t,x))$ with the initial condition $ (u(0,x),v(0,x))=(\bar u,\bar v)$ satisfies 
	$$
	\lim_{t\to\infty} (u(t,x),v(t,x))\to (u^*,v^*)\text{ uniformly in }E,
	$$
	there is $t_{\bar u,\bar v}>0$ such that $(u(t,\cdot),v(t,\cdot))\in U_{\eps/2}(u^*,v^*)$ for any $t\geq t_{\bar u,\bar v}$.
	Therefore, there is a $\delta_{\bar u,\bar v}>0$ such that
	for any initial data $(u'_0,v'_0)\in U_{\delta_{\bar u,\bar v}}((\bar u,\bar v)$ we have  
	$(u(t,\cdot),v(t,\cdot))\in U_{\eps}(u^*,v^*)$ for all $t\geq t_{\bar u,\bar v}$.
	Let consider the open covering $\{U_{\delta_{\bar u,\bar v}}((\bar u,\bar v): \bar u,\bar v\in K\}$. Since $K$ is compact, there is a finite covering 
	$\{U_{\delta_{\bar u_i,\bar v_i}(\bar u_i,\bar v_i)}: i=1,2,...,N\}$ of $K$. Put $ T=\max_{i=1,\dots,N}t_{\bar u_i,\bar v_i}$ we have the proof.

Next, we prove (ii).
Let $\eps>0$ be arbitrary. There is $t_1$ such that $t>t_1$ then $v(t,x)<\frac{\eps}c.$ By comparison argument then $u_\eps(t,x)\leq u(t,x)\leq \tilde{u}(t,x)$ where $\tilde{u}$ is solution to the deterministic Fisher-KPP equation \eqref{e0} and $u_\eps$ is solution 
\begin{equation*}%\label{e0-eps}
	\begin{cases}
		\dfrac{\partial u_\eps(t,x)}{\partial t}=\alpha_1\Delta u_\eps(t,x) + u_\eps(t,x)(a-\eps- bu_\eps(t,x)),\;t\geq t_1,\\
		u_\eps(t_1,x)=u(t_1,x).
	\end{cases}
\end{equation*}
Therefore, we can obtain $u(t,x)\to \frac{a}{b}$ uniformly in $E$.

The part (iii) following the fact that $v(t,x)\to 0$ whenever $ae<bd$, which can be proved similarly as done in Theorem \ref{thm-ext}.
\end{proof}
