\section{Residues}

Let $A$ be a local artinian ring with maximal ideal $\mm$ and residue field $k$, $\pi : C \to S = \Spec(A)$ a flat family of curves with reduced fiber, and $p$ a point in the fiber $C_0 = C \times_{\Spec(A)} \Spec(A/\mm)$. Given a minimal prime ideal $q_0 \subset \hat\O_{C_0,p}$, let $q \subset \hat\O_{C,p}$ be the preimage of $q_0$ under the map $\hat\O_{C,p} \to \hat\O_{C_0,p}$.

\begin{proposition}\label{local_ring}
    If $q_0$ is a minimal prime ideal of $\hat\O_{C_0,p}$, then there is an isomorphism $(\hat\O_{C_0,p})_{q_0} \simeq k(\!(x)\!)$. 
\end{proposition}

\begin{proof}
    Denote $\hat\O_{C_0,p}$ and $\O_{C_0,p}$ by $\hat{R}$ and $R$, respectively, throughout.

    Let $\{q_1,...,q_n\}$ be the minimal prime ideals of $\hat{R}$. If we denote by $R'$ the integral closure of $R$ in $Q(R)$ (its total ring of fractions), then the number of maximal ideals of $R'$ is $n$ (\cite{stacks-project} Tags 0C37 and 0C2E). Denote these by $\{m_1,...,m_n\}$. Let $\hat{R'}$ be the completion of $R'$ at the ideal $I = m_1\cdots m_n$, which is equivalent to completing $R'$ at the maximal ideal $m$ of $R$. Since $R'$ is semi-local, we have an isomorphism (\cite{Matsumura} Thm. 8.15)
    \[
    \hat{R'} \simeq \hat{R'}_{m_1} \times \cdots \times \hat{R'}_{m_n},
    \]
    where $\hat{R'}_{m_i}$ is the completion of the local ring $R'_{m_i}$ at its maximal ideal. 

    Now since $R'$ is finite over $R$, we also have an isomorphism
    \[
    \hat{R'} \simeq \hat{R} \otimes_R R'.
    \]
    $R$ is a localization of a finitely generated algebra over a field, so it is an excellent ring. In particular, it is a G-ring, so it has normal formal fibers, and from (\cite{egaiv} Prop. 6.14.4) we know that $\hat{R} \otimes_R R'$ is the integral closure of $\hat{R}$ in $Q(\hat{R})$. Thus, we can write
    \[
    \hat{R'} \simeq \hat{R}_1 \times \cdots \times \hat{R}_n,
    \]
    where $\hat{R}_i$ is the integral closure of $\hat{R}/q_i$ in $Q(\hat{R}/q_i) \simeq \hat{R}_{q_i}$ (\cite{stacks-project} Tag 030C). Therefore, up to reordering, we can assume $\hat{R}_i \simeq \hat{R'}_{m_i}$. In particular, $\hat{R}_i$ is a regular, complete, local noetherian ring of dimension one over $k$, so by the Cohen Structure Theorem (\cite{stacks-project} Tag 0C0S) $\hat{R}_i \simeq k[\![x]\!]$. Thus $\hat{R}_{q_i} \simeq Q(\hat{R}/q_i) \simeq k(\!(x)\!)$ for each $i$. 
\end{proof}

\begin{proposition}\label{stalk}
    If $q \subset \hat\O_{C,p}$ is the preimage of a minimal prime ideal $q_0 \subset \hat\O_{C_0,p}$, then $(\hat\O_{C})_q$ is isomorphic to $A(\!(x)\!)$.
\end{proposition}

\begin{proof}
    From Prop. \ref{local_ring}, we know that $(\hat\O_{C_0,p})_{q_0} \simeq k(\!(x)\!)$. For ease of notation, we denote $\hat\O_{C_0,p}$ and $\hat\O_{C,p}$ by $\hat\O_{C_0}$ and $\hat\O_{C}$, respectively, throughout.

    We now have two compatible infinitesimal deformations of $(\hat\O_{C_0})_{q_0}$ fitting in the following diagram

\begin{center}
    \begin{tikzcd}
{k(\!(x)\!) = (\hat\O_{C_0})_{q_0}} & {(\hat\O_{C})_{q}} \arrow[l] \\
A(\!(x)\!) \arrow[u]         & A \arrow[u] \arrow[l]         
\end{tikzcd}
\end{center}
We also have a compatible map $A(\!(x)\!) \to (\hat\O_{C})_q$ constructed as follows. The map $\hat{\O}_C \to \hat{\O}_{C_0}$ is surjective, so $(\hat{\O}_C)_q \to (\hat{\O}_{C_0})_{q_0} \simeq k(\!(x)\!)$ is also surjective. Let $y \in (\hat{\O}_C)_q$ be a preimage of $x$ under this map, which will be a unit since this is a local homomorphism. We then define $A(\!(x)\!) \to (\hat{\O}_C)_q$ by sending $x$ to $y$. 

We now show that the map just constructed $A(\!(x)\!) \to (\hat{\O}_C)_q$ is an isomorphism. Since $A$ is an order $N$ extension of $k$, $A(\!(x)\!)$ and $(\hat\O_{C})_q$ are both order $N$ extensions of $k(\!(x)\!)$. We show the desired isomorphism via induction on the order of extension $n$ by factoring these extensions into extensions of lower orders. We set $B_n$ and $D_n$ to be the order $n$ extensions of $k(\!(x)\!)$ coming from $A(\!(x)\!)$ and $(\hat\O_{C})_q$, respectively, $A_n$ to be the corresponding extension of $k$, and assume we have a map $B_n \to D_n$ over $A_n$ as constructed in the previous paragraph.

For the case $n = 1$, we have $B_1 = D_1 = k(\!(x)\!)$. Now assume the statement holds for $n-1$. We note that if $I$ is the kernel of $A_n \to A_{n-1}$, then by flatness of the deformations over $A_n$ and the base case, we know that the kernel of $B_n \to B_{n-1}$, denoted $J$, is $J = I \otimes_{A_n} B_n = I \otimes_{A_1} B_1$. Similarly, the kernel of $D_n \to D_{n-1}$ is $I \otimes_{A_1} D_1 \simeq I \otimes_{A_1} B_1 = J$. We then have the following diagram of exact sequences

\begin{center}
    \begin{tikzcd}
0 \arrow[r] & J \arrow[r]           & B_n \arrow[r]           & B_{n-1} \arrow[r]           & 0 \\
0 \arrow[r] & J \arrow[r] \arrow[u] & D_n \arrow[r] \arrow[u] & D_{n-1} \arrow[r] \arrow[u] & 0
\end{tikzcd}
\end{center}
The left vertical map is an isomorphism, as discussed above, and the right vertical map is an isomorphism via the induction hypothesis. Therefore, the middle map is also an isomorphism, which concludes the induction.

Hence we conclude that $(\hat\O_{C})_q \simeq A(\!(x)\!)$.
\end{proof}

Now let $p \in C$ be a point, $q \subset \hat\O_{C,p}$ a prime as above (corresponding to a branch, $X$, at the point $p$ in the fiber $C_0$), and $\phi \in \omega_C(U)$ for some open set $U$ containing $p$. 

\begin{lemma}\label{differential}
    $(\hat\omega_{C,p})_q$ is isomorphic to $A(\!(x)\!)\,dx$.
\end{lemma}

\begin{proof}
    Since $\omega_C$ is a line bundle on $C$, the stalk at $p$ will be one-dimensional over the stalk of $\O_C$. The localization of the completion will still be one-dimensional over the localization of the completion of the stalk of $\O_C$, which we know is isomorphic to $A(\!(x)\!)$ by Lemma \ref{stalk}. Therefore, we need only show that $dx$ is a basis element.

    Let $\tilde{C_0}$ be the normalization of $C_0$, let $\tilde{X}$ be the component of $\tilde{C_0}$ corresponding to the branch $X$ of $C_0$, and let $\tilde{p} \in \tilde{X}$ be the point mapping to $p \in C_0$. Let $\tilde{X}'$ be a deformation of $\tilde{X}$ over $A$. If we let $C^{\circ} \subset C$ be the open subset where we have removed $p$ and all components other than $X$, then we see that $C^{\circ}$ is the same as $\tilde{X}' \setminus \{\tilde{p}\}$. Thus we deduce that $(\O_{C,p})_q$ is isomorphic to $(\O_{\tilde{X}',\tilde{p}})_q$. Now since $\tilde{X}'$ is a smooth curve, we know that $\omega_{\tilde{X}',\tilde{p}}$ is one dimensional over $\O_{\tilde{X}',\tilde{p}}$ and generated by $d$ of a uniformizer of $\O_{\tilde{X}',\tilde{p}}$. This is still true after localization and completion. Now we have a map $(\hat\omega_{\tilde{X}',\tilde{p}})_q \to (\hat\omega_{C,p})_q$, and the generator of the former will map to $dx$, from which we conclude that $dx$ is a basis element. 
\end{proof}

Now from Lemma \ref{differential}, such a differential $\phi$ will have $(\phi_p)|_X \in A(\!(x)\!) \, dx$. Let us define a map $A(\!(x)\!) \, dx \to A$ by sending $\sum a_ix^i \mapsto a_{-1}$. 

\begin{definition}\label{residue}
    The \textbf{residue of $\phi$ at $p$ along the branch $X$} is the image of $(\phi_p)|_X$ under the map $A(\!(x)\!) \, dx \to A$. We denote this by $\res_{p,X}(\phi)$. 

    This induces a map $\pi_*\omega_C \to \O_S$, which we call the \textbf{residue map}.
\end{definition}

We must now show that this is well-defined, i.e., that the residue of an element of $A(\!(x)\!)\, dx$ is invariant under any continuous automorphism of $A(\!(x)\!)$. This follows from \cite{LaurentHoms} Corollary 5.4. This statement is more powerful than needed, as it deals with Laurent series in $n$ variables. In order to keep this self-contained, we provide a proof in Appendix \ref{inv} of the case $n = 1$ that we are considering.

\subsection{Facts about Residues}

\begin{remark}
    We note that, by definition, if we have an expansion
\begin{align}\label{res_coordinates}
    (\phi_p)|_X = \sum a_ix^i \, dx \in A(\!(x)\!) \, dx,
\end{align}
then the residue is just the term $a_{-1}$ in \eqref{res_coordinates}. We will use this fact heavily throughout.
\end{remark}

\begin{remark}
    When $p$ is a smooth point, there is only a single branch and we recover the usual definition of residue on a smooth curve over a local artinian ring (see, e.g., Chapter VII of \cite{hartRD}).
\end{remark}

As mentioned in the Introduction, one may think of this residue over a local artinian ring as an algebraic analogue of integration around a vanishing cycle in the complex analytic setting. The following lemma lends credence to that idea.

\begin{lemma}\label{invert}
    If $p \in C$ is a node with branches $X$ and $Y$, then 
    \[
    \res_{p,X}(\phi) = - \res_{p,Y}(\phi).
    \]
\end{lemma}

\begin{proof}
    Assume we have local coordinates $x$ and $y$ for $X$ and $Y$, respectively, such that $xy = t$ for some $t \in \mm$. We first write out
    \[
    \phi_p|_X = \left(\sum_{j=N}^{\infty} a_jx^j\right)dx,
    \]
    so $\res_{p,X}(\phi) = a_{-1}$. We now split into the cases $t = 0$ and $t \neq 0$.

    First assume $xy = t$, where $t \neq 0$. When we restrict to the complement of $X$, $y$ will be invertible and we can write $x = ty^{-1}$, and $dx = -t\frac{dy}{y^2}$. The $-1$ term for the residue in this expansion on $Y$ will come from $a_{-1}x^{-1} = a_{-1}(ty^{-1})^{-1}$, due to the $1/y^2$ in the $dx$ conversion. Multiplying $-t\frac{dy}{y^2}$ by this term shows 
    \[
    \res_{p,Y}(\phi) = -a_{-1} = -\res_{p,X}(\phi).
    \]

    Now assume $t = 0$. Over $\Spec(k)$, we have that 
    \[
    \omega_{C/k} \subset \omega_{X \setminus p / k} \times \omega_{Y \setminus p / k} \simeq \Omega_{X \setminus p / k} \times \Omega_{Y \setminus p / k}
    \]
    and we can identify this with the multiples of $\left(\frac{dx}{x},-\frac{dy}{y}\right)$ (see, e.g., Rosenlicht duality in Altman--Kleinman \cite{altman-kleinman} Prop. VIII.1.16). Over an artinian base $S$ we still have
    \[
    \omega_{C/S} \subset \omega_{X \setminus p / S} \times \omega_{Y \setminus p / S} \simeq \Omega_{X \setminus p / S} \times \Omega_{Y \setminus p / S}
    \]
    and it will still be generated by one element. Using Nakayama's Lemma, one shows that $\left(\frac{dx}{x},-\frac{dy}{y}\right)$ still generates, since it generates over $k$. Thus, since every element of $\omega_{C/S}$ is a multiple of $\left(\frac{dx}{x},-\frac{dy}{y}\right)$ and no element of $\O_C$ will have different constant value on $X$ and $Y$ (as they agree at the node), we see that the residues of $\phi$ along $X$ and $Y$ still differ by a sign.
\end{proof}

\begin{lemma}\label{res_thm}
    If $C \to S$ is smooth, then 
    \[
    \sum_{p \in C} \res_{p,C}(\phi) = 0.
    \]
\end{lemma}

\begin{proof}
    See Theorem 1.5 and the remark following it in Chapter VII of \cite{hartRD}.
\end{proof}

\section{The Contraction}

\subsection{Construction}

Let $\pi : C \to S$ be a family of centrally aligned curves with $n$ rational curves emerging from the aligned circle. We will construct a contraction $\tau : C \to \widebar{C}$ that is an isomorphism outside of the aligned circle of $C$ and such that the interior of the aligned circle is contracted to a Gorenstein genus 1 singularity with $n$ branches in $\widebar{C}$. 

We first construct the contraction when $S$ is the spectrum of a local artinian ring $A$ with maximal ideal $\mm$ and residue field $k$. Set $C_0$ to be the scheme $C \times_S \Spec(A/\mm)$. Assume that the central alignment on $C_0$ splits it into $m$ layers $L_0,...,L_m$, where $L_0$ is the core, $L_i$ is the subcurve consisting of the union of the rational curves at level $i$, and $L_m$ is the union of the rational curves on the edge of the aligned circle. Since $C_0$ is centrally aligned, a smoothing parameter at any node connecting layer $L_i$ to $L_{i-1}$ will be the same, say equal to $t_i \in \mm$. We denote by $t$ the product of these smoothing parameters, $t = t_1 \cdots t_m$. See Figure \ref{fig:layers1}.

