Now given a function $f \in H^0(V,\O_C)$, we can compute $\res^m_{p_i,R_i}(f\phi|_V) \in \O_S(-\delta)$, where $\delta$ is the value of $\lambda$ on the layer, $L_m$. Define the map $\res^m : H^0(V,\O_C) \to \O_S(-\delta)$ by 
\[
\res^m(f\phi) = \sum_{p_i} \res^m_{p_i,R_i}(f\phi|_V).
\]

\begin{proposition}
    The map $\res^m$ is an $A$-derivation. 
\end{proposition}

\begin{proof}
    The $A$-linearity is clear from definition, so we need only show the Leibniz rule holds. We can reduce to showing this is true when taking the residue at a single $p_i$, since summing over all $p_i$ will still preserve the Leibniz rule. Thus we must show that given $f,g \in H^0(V,\O_C)$, $\res^m_{p_i,R_i}(fg\phi|_V) = f(p_i)\res^m_{p_i,R_i}(g\phi|_V) + g(p_i)\res^m_{p_i,R_i}(f\phi|_V)$. 

    Letting $x$ be a local coordinate for $R_i$ at $p_i$, we can write 
    \begin{align*}
        f_{p_i} &= c_0 + c_1x + \cdots \\
        g_{p_i} &= d_0 + d_1x + \cdots \\
        (\phi_{p_i})|_{R_i} &= [t](\gamma_{-2}x^{-2} + \gamma_0 + \gamma_1x + \cdots).
    \end{align*}
    Note that there is no $x_i^{-1}$ term as the total residue of $\phi|_{R_i}$ must be 0. A computation then yields
    \begin{align*}
        \res^m_{p_i,R_i}(fg\phi|_V) &= [t](c_0d_1 + d_0c_1) \\
        &= f(p_i)\res^m_{p_i,R_i}(g\phi|_V) + g(p_i)\res^m_{p_i,R_i}(f\phi|_V),
    \end{align*}
    as desired.
\end{proof}

\begin{lemma}\label{splitting}
    The image of the map $\res^m : \O_C(V) \to \O_S(-\delta)$ is generated by $\mathrm{Ann}_A(t)$ and we have a splitting $[t]\mathrm{Ann}_A(t) \to \O_C(V)$.
\end{lemma}

\begin{proof}
    First, note that $\O_S(-\delta) \simeq [t]A$. Now, the only condition on the map $\O_C(V) \to \O_S(-\delta)$ is that the composition $\O_C(V) \to \O_S(-\delta) \to \O_S$ must be 0. Let $f \in \O_C(V)$ and assume we have local expansions at each $p_i$
    \[
    f_{p_i} = c_0^i + c_1^ix_i + \cdots
    \]
    and 
    \[
    \phi_{p_i} = [t](\gamma_{-2}^ix_i^{-2} + \gamma_0^i + \cdots).
    \]
    Putting these together, we have
    \[
    \res^m(f\phi) = [t]\sum_{i=1}^n \gamma_{-2}^ic_1^i \in \O_S(-\delta).
    \]
    After mapping to $\O_S$, we get the following condition
    \[
    t\sum_{i=1}^n \gamma_{-2}^ic_1^i = 0 \in \O_S.
    \]
    Therefore, we see that the only condition on $f$ is that $\sum_{i=1}^n \gamma_{-2}^ic_1^i \in \mathrm{Ann}_A(t)$, so the image of the map lies in $[t]\mathrm{Ann}_A(t)$.

    To show that the image is all of $[t]\mathrm{Ann}_A(t)$, we define a splitting $[t]\mathrm{Ann}_A(t) \to \O_C(V)$. Let $c \in \mathrm{Ann}_A(t)$. We then define a function $f \in \O_C(V)$ by $f_{p_1} = (c/\gamma_{-2}^1)x_1$ and $f_{p_i} = 0$ for $i \neq 1$, which one can check is a splitting.
\end{proof}

We then define $f$ to be in $\O_{\widebar{C}}(U)$ if it satisfies
\begin{equation}\label{res_cond}
    \res^m(f\phi) = \sum_{p_i} \res^m_{p_i,R_i}(f\phi|_V) = 0 \in \O_S(-\delta).
\end{equation}
Note that $\O_{\widebar{C}}(U)$ is a ring, since it is the kernel of a derivation.

\begin{definition}\label{contraction_def}
    Let $\pi : C \to S$ be a family of centrally aligned genus one curves with $S$ the spectrum of a local artinian ring, $A$. The contraction $\widebar{\pi} : \widebar{C} \to S$ is defined to be the ringed space $\widebar{C} = (C',\O_{\widebar{C}})$ with the map $\tau : C \to \widebar{C}$ topologically being the contraction and on sheaves being the map $\O_{\widebar{C}} \hookrightarrow \tau'_*\O_C = \tau_*\O_C$. 
\end{definition}

\begin{remark}
    We could carry out this construction at any layer $L_i$ by using $\res^i$ instead of $\res^m$. Thus we have a contraction for each layer $L_i$, but we will only be concerned with the contraction at $L_m$.
\end{remark}

