We now collect some facts about $\widebar{C}$ and residues. 

First, let $B = A/\mm^i$ be a quotient of $A$ by a power of its maximal ideal and set $T = \Spec(B)$ and $C_T = C \times_S T$. For any value of $\lambda$, say $u$, we have an isomorphism $\O_T(-u) \simeq \O_S(-u) \otimes_A B$. Indeed, given a map of log schemes $f : T \to S$, we have a natural isomorphism $\O_T(-u) \simeq F^*\O_S(-u) = \O_S(-u) \otimes_A B$.

Next, let $F : C_T \to C$ be the natural map. Since $F^*\omega_C \simeq \omega_{C_T}$ (see \cite{stacks-project} Tag 0E6R) and $F^*\O_C(-\lambda) \simeq \O_{C_T}(-\lambda)$, we see that $F^*\omega_C(-\lambda) \simeq \omega_{C_T}(-\lambda)$. We have a natural map (using the $R^0$ case of base change) 
\[
H^0(C,\omega_C(-\lambda)) \otimes_A B \to H^0(C_T,\omega_{C_T}(-\lambda)).
\]
Then identifying $H^0(C,\omega_C(-\lambda)) \otimes_A B \simeq H^0(C,\omega_C(-\lambda))/\mm^iH^0(C,\omega_C(-\lambda))$, we see that we have a surjective map $H^0(C,\omega_C(-\lambda)) \to H^0(C_T,\omega_{C_T}(-\lambda))$. Now if $\phi$ is a generator of $H^0(C,\omega_C(-\lambda))$ and $\psi$ is a generator of $H^0(C_T,\omega_{C_T}(-\lambda))$, then the image of $\phi$ under the above map will differ from $\psi$ by a multiple of a unit, so their residues will only differ by a multiple of a unit.

\begin{lemma}\label{res_lift}
    Let $P_j \in R_j$ be a node connecting $L_i$ to $L_{i-1}$ in $C_0$ and let $\lambda$ have the value $u$ at layer $L_i$. Let $B = A/\mm^l$ be a quotient of $A$ by a power of its maximal ideal, $T = \Spec(B)$, and $C_T = C \times_S T$. If $g \in \O_C(V)$ is a lift of $f \in \O_{C_T}(V)$ and $\phi \in H^0(C,\omega_C(-\lambda))$ is a lift of $\psi \in H^0(C_T,\omega_{C_T}(-\lambda))$, then $\res^i_{P_j,R_j}(g\phi|_V)$ maps to $\res^i_{P_j,R_j}(f\psi|_V)$ under the map $\O_S(-u) \to \O_T(-u)$. 
\end{lemma}

\begin{proof}
    Let $n$ be the smallest integer such that $\mm^n = 0$. We show the lemma is true for $l = n-1$. This implies the general result, since one can simply apply the lemma repeatedly to get to any $l$.

    This is a computation in local coordinates. Let $x$ be a local coordinate for $R_j$. Let $T = t_1 \cdots t_i$. First, we write
    \[
    (\psi)_{P_j}|_{R_j} = [T](\gamma_{-2}x^{-2} + \gamma_0 + \cdots)\,dx
    \]
    \[
    (f)_{P_j} = c + c_1x + \cdots
    \]
    from which we compute
    \[
    \res^i_{P_j,R_j}(f\psi|_V) = [T]\gamma_{-2}c_1.
    \]
    Now since $g$ and $\phi$ are lifts of $f$ and $\psi$, respectively, we can write
    \[
    (\phi)_{P_j}|_{R_j} = [T](\gamma_{-2}+v_{-2})x^{-2} + (\gamma_0 + v_0) + \cdots]\,dx
    \]
    \[
    (g)_{P_j} = c + c_1x + \cdots + u(d + d_1x + \cdots)
    \]
    where $u,v_i \in \mm^{n+2}$. From this we compute
    \[
    \res^i_{P_j,R_j}(g\phi|_V) = [T](\gamma_{-2}c_1 + ud_1\gamma_{-2} + v_{-2}c_1), 
    \]
    so we see that
    \[
    \res^i_{P_j,R_j}(f\psi|_V) = \res^i_{P_j,R_j}(g\phi|_V) \pmod{\mm^{n+1}}
    \]
    as desired.
\end{proof}

Next, let $S = \Spec(R)$, where $R$ is a local noetherian ring with maximal ideal $\mm$. Let $S_n = \Spec(R/\mm^{n+1})$ and $C_n = C \times_S S_n$. Since $R/\mm^{n+1}$ is a local artinian ring, we have the following diagram of cartesian squares
\begin{center}
    \begin{tikzcd}
C_0 \arrow[r] \arrow[d] & C_1 \arrow[r] \arrow[d] & C_2 \arrow[d] \arrow[r] & \cdots \\
S_0 \arrow[r]           & S_1 \arrow[r]           & S_2 \arrow[r]           & \cdots
\end{tikzcd}
\end{center}
and a contraction for each $i$, $\tau_i : C_i \to \widebar{C_i}$, defined using a differential $\phi_i \in H^0(C_i,\omega_{C_i}(-\lambda))$.

Based on the conclusion of the paragraph before Lemma \ref{res_lift}, we will assume that $\phi_{n+1}$ is a lift of $\phi_n$, since any lift of $\phi_n$ will only differ from $\phi_{n+1}$ by a unit multiple, and we are only concerned with the residue being zero or not. 

\begin{lemma}\label{node_pass}
    Let $q_1,...,q_l$ be the nodes connecting layer $L_0$ to layer $L_1$ and let $f_n \in \O_{C_n}(V)$. Then 
    \[
    \sum_{p_i} \res_{p_i,R_i}(f_n\phi_n|_V) = -\sum_{q_i} \res_{q_i,L_0}(f_n\phi_n|_V).
    \]
\end{lemma}

\begin{proof}
    Combining Lemmas \ref{invert} and \ref{res_thm}, we see that if $P_1,...,P_k$ are the nodes connecting layer $L_{m-1}$ to $L_{m-2}$, say node $P_j$ is on the curve $Y_j$ in $L_{m-1}$, then 
    \[
    \sum_{p_i} \res_{p_i,R_i}(f_n\phi_n|_V) = -\sum_{p_i} \res_{p_i,Y_i}(f_n\phi_n|_V) =  \sum_{P_j} \res_{P_j,Y_j}(f_n\phi_n|_V).
    \]
    We can then repeat this for the nodes connecting $L_{m-2}$ to $L_{m-3}$, and so forth, until we hit the core $L_0$, where the corresponding equation becomes
    \[
    \sum_{p_i} \res_{p_i,R_i}(f_n\phi_n|_V) = -\sum_{q_i} \res_{q_i,L_0}(f_n\phi_n|_V),
    \]
    as desired.
\end{proof}

Before moving on to the main theorem, we provide an example to illustrate the idea of part of the proof and motivate the statement (and, hopefully, the definition of $\widebar{C}$). 

\begin{example}
    Let $C$ and $A$ be the same as in Example \ref{tacnode}. Let $U$ be a neighborhood of the contracted subcurve, and let $q$ be the node connecting $X$ and $T$. We will examine the condition a function $f \in \O_{C_0}(U)$ must satisfy if it lifts to a function $\tilde{f} \in \O_C(U)$. 

    Assume we have such a lift $\tilde{f}$. At the outer nodes $p_1$ and $p_2$, let us write
    \[
    f_{p_i} = c + c_1^ix_i + \cdots.
    \]
    The stalks of $\tilde{f}$ must be lifts of these, so we can write
    \[
    \tilde{f}_{p_i} = (c + du + eu^2) + (c_1^i + d_1^iu + e_1^iu^2)x_i + \cdots,
    \]
    for some $d,e,d_j^i,e_j^i \in k$. Also, for $\phi \in H^0(C_0,\omega_{C_0}(-\lambda))$ and a lift $\tilde{\phi} \in H^0(C,\omega_C(-\lambda))$, we can write
    \begin{align*}
        \phi_{p_i}|_{R_i} &= [u^2](\gamma_{-2}^ix_i^{-2} + \cdots)\,dx_i \\
        \tilde{\phi}_{p_i}|_{R_i} &= [u^2][(\gamma_{-2}^i + \alpha^iu + \beta^iu^2)x_i^{-2} + \cdots]\,dx_i
    \end{align*}
    for some $\alpha^i,\beta^i \in k$. In order for $\tilde{f}$ to be a lift of $f$, the lifts of the stalks must be compatible with the lifts of $f$ on any component of $C_0$ with the nodes removed. Lifting to the rational components is always possible, so the only condition can come from lifting to $X \setminus \{q\}$. 

    Computing and summing the residues of $\tilde{f}\tilde{\phi}$ in $\O(-\delta)$ at $p_1$ and $p_2$, we get 
    \[
    [u^2][(\gamma_{-2}^1 + \alpha^1u + \beta^1u^2)(c_1^1 + d_1^1u + e_1^1u^2) + (\gamma_{-2}^2 + \alpha^2u + \beta^2u^2)(c_1^2 + d_1^2u + e_1^2u^2)].
    \]
    From Lemma \ref{node_pass}, the total residue on $X$ is the negative of the image of this sum under the map to $\O$, and since $X$ is a genus one curve, a compatible lift of $f$ to $\O_C(X \setminus \{q\})$ exists if and only if this residue is 0 (this is the Mittag-Leffler problem). Expanding the products in the sum, we get
    \[
    [u^2][(\gamma_{-2}^1c_1^1 + \gamma_{-2}^2c_1^2) + au + bu^2],
    \]
    where $a$ and $b$ are sums containing the other coefficients. Now since $u^3 = 0$ in $A$, the image of this in $\O$ will just be
    \[
    [u^2](\gamma_{-2}^1c_1^1 + \gamma_{-2}^2c_1^2).
    \]
    Thus for $f$ to lift, it must satisfy
    \[
    u^2(\gamma_{-2}^1c_1^1 + \gamma_{-2}^2c_1^2) = 0,
    \]
    which is equivalent to 
    \[
    \gamma_{-2}^1c_1^1 + \gamma_{-2}^2c_1^2 = 0,
    \]
    since if $\gamma_{-2}^1c_1^1 + \gamma_{-2}^2c_1^2 \neq 0$, then it will not in the annihilator of $u^2$. Now we see that this is exactly the condition for $f$ to descend to $\widebar{C_0}$. 
\end{example}

\begin{theorem}\label{main}
    Let $R$ be a local noetherian ring complete with respect to its maximal ideal $\mm$, $S = \Spec(R)$, and $S_n = \Spec(R/\mm^{n+1})$. Let $C \to S$ be a family of centrally aligned genus one curves and set $C_n = C \times_S S_n$. Assume $\O_C(-\lambda) \to \O_C$ is injective.

    Let $U \subset \widebar{C_n}$ be an open subset, $V = \tau_n^{-1}(U)$, and $f_n \in \O_{C_n}(V)$. The following are equivalent:
    \begin{enumerate}
        \item $f_n$ is in the image of $\O_{C_m}(V) \to \O_{C_n}(V)$ for all $m \geq n$;
        \item there exist compatible lifts $f_m \in \O_{C_m}(V)$ of $f_n$ for all $m \geq n$;
        \item $f_n$ is in $\O_{\widebar{C_n}}(U)$;
        \item $f_n$ satisfies the residue condition: $\sum_{p_i} \res^m_{p_i,R_i}(f_n\phi_n|_V) = 0 \in \O_{S_n}(-\delta)$.
    \end{enumerate}
\end{theorem}

\begin{proof}
    We clearly have (ii) implies (i), and (iii) and (iv) are equivalent by definition of $\widebar{C_n}$. We will first show (i) implies (iv), then finish by showing (iv) implies (ii).

    We begin with (i) implies (iv). If $\tau_n(E) \not\in U$, then $\O_{\widebar{C_n}}(U) = \O_{C_n}(V)$, so (i) clearly implies (iv) in this case. 

    Now assume $\tau_n(E) \in U$. Let
    \[
    \sum_{p_i}\res^m_{p_i,R_i}(f_n\phi_n|_V) = [t]a
    \]
    for some $a \in R/\mm^{n+1}$.
    Let $N \geq n$ be the smallest integer such that $ta \in \mm^N$, but $ta \not\in \mm^{N+1}$. Note that we could have $N=n$. From Lemma \ref{res_lift}, we know that 
    \[
    \sum_{p_i} \res^m_{p_i,R_i}(f_N\phi_N|_V) = [t]\Tilde{a} + [t]G,
    \]
    where $G \in \mm^N$ and $\Tilde{a}$ is a lift of $a$ to $R/\mm^{N+1}$. Then we have
    \[
    \sum_{p_i} \res_{p_i,R_i}(f_N\phi_N|_V) = t\Tilde{a} \in R/\mm^{N+1},
    \]
    since $tG \in \mm^{N+1}$. Now applying Lemma \ref{node_pass} with $q_i$ as in said lemma, we have
    \[
    \sum_{q_i} \res_{q_i,L_0}(f_N\phi_N|_V) = -t\Tilde{a},
    \]
    and since this is the total residue of $f_N\phi_N$ on $L_0$, we must have $t\Tilde{a} = 0$, from which we deduce that $\Tilde{a} = 0$, since if $\tilde{a} \neq 0$, then $\Tilde{a} \not\in \text{Ann}(t)$. Restricting back to $S_n$, we conclude that $a = 0 \in R/\mm^{n+1}$, so $ta = 0$, as desired.

    We now address (iv) implies (ii). Let $J = \ker(R/\mm^{n+2} \to R/\mm^{n+1})$. Since $C_{n+1}$ is an infinitesimal deformation of $C_n$, we have a short exact sequence
    \[
    0 \to \O_{C_{n+1}} \otimes J \to \O_{C_{n+1}} \to \O_{C_n} \to 0.
    \]
    By flatness of the maps $C_k \to S_k$, we see that $\O_{C_{n+1}} \otimes J = \O_{C_0} \otimes J$. Now this sequence induces a long exact sequence in cohomology, and we see that the obstruction to lifting $f_n$ to a function $f_{n+1}$ is found in $H^1(C_0,\O_{C_0} \otimes J)$. When $\tau_n(E) \not\in U$, $V$ is a collection of rational curves, so $H^1(V,\O_{C_0} \otimes J|_V) = 0$ and we always have a lift. We can then repeat this on $C_{n+1}$ to find a compatible lift to $C_{n+2}$, then repeat to get a lift to any $C_m$ for $m \geq n$. 

    Now we examine the case when $\tau_n(E) \in U$. We will approach this by showing that if $f_n$ satisfies (iv), then we can find a lift $f_{n+1}$ that also satisfies (iv). We can then inductively lift $f_{n+1}$ to $f_{n+2}$ also satisfying (iv), and so forth to any order. 

    We first make a reduction to the problem. If we let $X$ be a component of $C_{n+1}$ with nodes $r_1,...,r_k$, then we claim that finding a lift of $f_n$ to $X$ is equivalent to finding compatible lifts of $f_n|_{X\setminus\{r_1,...,r_k\}}$ and $(f_n)_{r_i} \in (\O_{C_n})_{r_i}$. This follows from Zariski gluing, since viewing $(f_n)_{r_i}$ as a function in a suitably small neighborhood $W_i$ of $r_i$, we see that $X\setminus\{r_1,...,r_k\}$ and $W_1,...,W_k$ form a cover of $X$. Now we can always find lifts to $X \setminus \{r_1,...,r_k\}$, since $X \setminus \{r_1,...,r_k\}$ is affine, and $(\O_{C_{n+1}})_{r_i} \to (\O_{C_{n}})_{r_i}$ is surjective, so we can also find a lift to $(\O_{C_{n+1}})_{r_i}$. However, these lifts must be compatible, and the lift to $(\O_{C_{n+1}})_{r_i}$ can potentially force the lift to $X \setminus \{r_1,...,r_k\}$ to have a zero or pole at $r_i$. Thus we see that finding a lift is equivalent to finding a rational function on $X$ with prescribed zeroes or poles at the nodes. As we saw above, this can always be done when the component is rational. Furthermore, since $C_{n+1}$ has genus one, the dual graph of $C_{n+1}$ minus the vertices corresponding to the core forms a tree. Thus if we think of finding a lift as first lifting to layer $L_m$, then layer $L_{m-1}$, and so forth, we see that the only obstruction to lifting arises from lifting to $L_0$. This is the obstruction in $H^1$ previously discussed.

    Let us now compute this obstruction and show that we can always find a lift when $f_n \in \O_{\widebar{C_n}}(U)$. In a similar fashion to the proof of Lemma \ref{res_lift}, we compute in local coordinates. At each $p_i$, with $x_i$ the local coordinate for $R_i$, we write (with $\gamma^i_{-2}$ a unit)
     \[
    (\phi_n)_{p_i}|_{R_i} = [t](\gamma_{-2}^{i}x_{i}^{-2} + \gamma_0^i + \cdots)\,dx_i
    \]
    \[
    (f_n)_{p_i} = c^i + c_1^ix_i + \cdots
    \]
    from which we compute
    \[
    \res^m_{p_i,R_i}(f_n\phi_n|_V) = [t]\gamma_{-2}^ic_1^i.
    \]
    Again as in Lemma \ref{res_lift}, since $f_{n+1}$ and $\phi_{n+1}$ are lifts of $f_n$ and $\phi_n$, respectively, we can write
    \[
    (\phi_{n+1})_{p_i}|_{R_i} = [t][(\gamma_{-2}^i+v_{-2}^i)x_i^{-2} + (\gamma_0^i + v_0^i) + \cdots]\,dx_i
    \]
    \[
    (f_{n+1})_{p_i} = c^i + c_1^ix_i + \cdots + u^i(d^i + d_1^ix_i + \cdots)
    \]
    where $u^i,v_j^i \in \mm^{n+1}$. From this we compute
    \begin{align*}
        \res^m_{p_i,R_i}(f_{n+1}\phi_{n+1}|_V) &= [t](\gamma_{-2}^ic_1^i + u^id_1^i\gamma_{-2}^i + v_{-2}^ic_1^i) \\
        &= [t]\gamma_{-2}^ic_1^i + t(u^id_1^i\gamma_{-2}^i + v_{-2}^ic_1^i).
    \end{align*}
    Now using Lemma \ref{node_pass}, we can compute
    \[
    \sum_{q_i} \res_{q_i,L_0}(f_{n+1}\phi_{n+1}|_V) = -t\sum_{p_i} \gamma_{-2}^ic_1^i,
    \]
    where the other terms in the residue vanish since $tu^i,tv_{-2}^i \in \mm^{n+2}$. We then have principal parts on $L_0$ and want to know if these principal parts come from a rational function -- this is the Mittag-Leffler problem. Thus to find our rational function on $L_0$ we only need $t\sum_{p_i} \gamma_{-2}^ic_1^i = 0 \in \O_{S_{n+1}}$, which is satisfied by assumption. Therefore, we can find a lift $f_{n+1}$. Furthermore, we can choose $u^i,d_1^i$ to satisfy $u^id_1^i\gamma_{-2}^i + v_{-2}^ic_1^i = 0$ for each $i$, e.g., by choosing $u^i = v_{-2}^i$ and setting $d_1^i = c_1^i(\gamma_{-2}^i)^{-1}$, so we can choose the lift $f_{n+1}$ to satisfy (iv). Hence we can find compatible lifts of $f_n$ to $f_m$ for any $m \geq n$.
\end{proof}

\subsection{Properties of the Contraction}

\begin{proposition}
    Let $B = A/\mm^i$ be a quotient of $A$ by a power of its maximal ideal, $T = \Spec(B)$, and $C_{T} = C \times_S T$. Then $\widebar{C}_{T} \simeq \widebar{C} \times_S T$, i.e., the following diagram is cartesian
    \begin{center}
        \begin{tikzcd}
\widebar{C}_{T} \arrow[d] \arrow[r] & \widebar{C} \arrow[d] \\
T \arrow[r]                         & S                    
\end{tikzcd}
    \end{center}
\end{proposition}

\begin{proof}
    First, we reduce to the case $B = A/I$, where $I \simeq k$. To do this, we first note that if $B = A/\mm^i$ and if $\mm^{n+1} = 0$ and $\mm^n \neq 0$, then we can write $B$ as a successive quotient of $A$, first quotienting by $\mm^n$, then $\mm^{n-1}$, and so on until reaching $\mm^i$. Thus, we can work with $A/\mm^n$. Now writing $\mm^n = (a_1,...,a_j)$, we can write $A/\mm^n$ as a successive quotient by $(a_1)$, then $(a_2)$, and so on until $(a_j)$. Since $\mm^{n+1} = 0$, we see that each $(a_i) \simeq k$, so we have the desired reduction to $B = A/I$ with $I \simeq k$. Assume $I = (a)$ for some $a \in A$.

    The underlying topological spaces of $\widebar{C}_{T}$ and $\widebar{C} \times_S T$ are the same, equal to $C'$, so we need only show that $\O_{\widebar{C}_{T}} = \O_{\widebar{C}} \otimes_{\O_S} \O_T$ as sheaves on $C'$. Away from the contracted point $P = \tau(E)$, this clearly holds, so we need only show that if $U \subset C'$ is an open set containing $P$, then $\O_{\widebar{C}_{T}}(U) = (\O_{\widebar{C}} \otimes_{\O_S} \O_T)(U)$. For this, it suffices to show $\O_{\widebar{C}_{T}}(U) = \O_{\widebar{C}}(U) \otimes_{A} B$. Set $V = (\tau')^{-1}(U)$.

    Using Lemma \ref{splitting}, we have the following commutative diagram with split exact rows:

    \begin{center}
        \begin{tikzcd}
0 \arrow[r] & \O_{\bar{C}}(U) \arrow[r] \arrow[d]           & \O_C(V) \arrow[r] \arrow[d]                              & {[t]}\mathrm{Ann}_A(t) \arrow[r] \arrow[d]                      & 0 \\
0 \arrow[r] & \O_{\bar{C}}(U) \otimes B \arrow[r] \arrow[d] & \O_C(V) \otimes B \arrow[r] \arrow[d] \arrow[ld, dashed] & {[t]}\mathrm{Ann}_A(t) \otimes B \arrow[r] \arrow[d, "0"] & 0 \\
0 \arrow[r] & \O_{\bar{C}_T}(U) \arrow[r]                 & \O_{C_T}(V) \arrow[r]                                    & {[t]}\mathrm{Ann}_B(t) \arrow[r]                                & 0
\end{tikzcd}
    \end{center}
    Our goal is to show that the bottom left vertical map $\O_{\bar{C}}(U) \otimes B \to \O_{\bar{C}_T}(U)$ is an isomorphism. 

    First, we note that we have a map $\O_C(V) \otimes B \to \O_{\bar{C}_T}(U)$ (dashed in the diagram). To see this, note that $\O_C(V) \to \O_C(V) \otimes B$ is surjective. Let $f \in \O_C(V) \otimes B$ and, by abuse of notation, we also denote the preimage in $\O_C(V)$ by $f$. If $f_T$ is the image of $f$ in $\O_{C_T}(V)$, then we see that $f_T$ maps to zero in $[t]\mathrm{Ann}_B(t)$, so $f_T$ is actually in $\O_{\bar{C}_T}(U)$, i.e., the map $\O_C(V) \otimes B \to \O_{C_T}(V)$ factors through $\O_{\bar{C}_T}(U)$. By Theorem \ref{main}, any element of $\O_{\bar{C}_T}(U)$ has a lift to $\O_C(V)$, so this map is surjective. Since the maps between rows are maps of split exact sequences, we can see that the map $\O_{\bar{C}}(U) \otimes B \to \O_{\bar{C}_T}(U)$ must also be surjective.

    We now show that $\O_{\bar{C}}(U) \otimes B \to \O_{\bar{C}_T}(U)$ is injective to complete the proof. If we let 
    \begin{align*}
        K_1 &= \ker(\O_{\bar{C}}(U) \otimes B \to \O_{\bar{C}_T}(U)) \\
        K_2 &= \ker(\O_C(V) \otimes B \to \O_{C_T}(V))
    \end{align*}
    then from the Snake Lemma we have the following exact sequence
    \[
    0 \to K_1 \to K_2 \to t\mathrm{Ann}_A(t) \otimes B \to 0
    \]
    Therefore, if we can show that $K_2 \to [t]\mathrm{Ann}_A(t) \otimes B$ is injective, then $K_1 = 0$ and we are done. 

    Let $f \in K_2$ such that $f$ maps to zero in $[t]\mathrm{Ann}_A(t) \otimes B$. Denoting a preimage of $f$ in $\O_C(V)$ by $\tilde{f}$, we see that $\tilde{f} \in \ker(\O_C(V) \to \O_{C_T}(V))$ and $\tilde{f}$ maps to zero in $[t]\mathrm{Ann}_A(t)$. Thus $\tilde{f} \in (I\O_C)(V)$. We will show that we have actually have $\tilde{f} \in I\O_C(V)$, so $f = 0 \in \O_C(V) \otimes B$. Since $I = (a) \simeq k$, we have $I\O_C \simeq \O_{C_0}$, so $\tilde{f}$ corresponds to a function $g \in \O_{C_0}(V)$. This function $g$ will have residue zero, since $\tilde{f}$ did, so by Theorem \ref{main}, $g$ lifts to a function $\tilde{g} \in \O_C(V)$. Now applying the multiplication by $a$ map to $\O_C(V)$, we have $\tilde{f} = a\tilde{g}$. Thus $\tilde{f} \in I\O_C(V)$, and we are done.
\end{proof}

\begin{lemma}\label{finite}
    The map $C' \to \widebar{C}$ is finite.
\end{lemma}

\begin{proof}
    We need only show that if $U \subset C'$ is an open subset containing $P = \tau(E)$, then $\O_{C'}(U)$ is a finitely generated module over $\O_{\widebar{C}}(U)$. 

    Let $M$ be the image of $\res^m : \O_{C'}(U) \to \O_S(-\delta)$. Then we have an exact sequence of $\O_{\widebar{C}}(U)$-modules
    \[
    0 \to \O_{\widebar{C}}(U) \to \O_{C'}(U) \to M \to 0.
    \]
    Now since $\O_S(-\delta)$ is a noetherian $A$-module, $M$ is finitely generated as an $A$-module. Thus, since $A \subset \O_{\widebar{C}}(U)$, $M$ is also finitely generated as an $\O_{\widebar{C}}(U)$-module. Therefore, both $\O_{\widebar{C}}(U)$ and $M$ are finitely generated as $\O_{\widebar{C}}(U)$-modules, so we see that the same is true for $\O_{C'}(U)$. 
\end{proof}

\begin{proposition}
    The ringed space $\widebar{C}$ is a scheme.
\end{proposition}

\begin{proof}
    First, since $\tau : C \to \widebar{C}$ is an isomorphism outside of $E$, we need only show that $\tau(E) = P$ has an affine open neighborhood. We reduce to showing this when $S = \Spec(k)$, since if $U$ is an affine neighborhood of $P$ over $\Spec(k)$, then a deformation of this neighborhood over a local artinian ring will still be affine.

    Let $U$ be an affine open neighborhood of $P$ in $C'$, e.g., by removing a smooth point from each component. We claim that $(U,\O_{\widebar{C}}|_U)$ is an affine scheme, and thus an affine neighborhood of $P$ in $\widebar{C}$. For this to be true, we first show that $U$ is homeomorphic to $\Spec\,\O_{\widebar{C}}(U)$. Since $C'$ and $\widebar{C}$ have the same topological space, we see that this is equivalent to showing that $\Spec\,\O_{C'}(U) \to \Spec\,\O_{\widebar{C}}(U)$ is a homeomorphism. To show this, let $V = U \setminus P$, so $(V, \O_{C'}|_V)$ and $(V, \O_{\widebar{C}}|_V)$ are both affine, equal to $\Spec\,\O_{C'}(V)$ and $\Spec\,\O_{\widebar{C}}(V)$, respectively. We then have the following commutative diagram
    \begin{center}
        \begin{tikzcd}
{\Spec\,\O_{\widebar{C}}(U)} & {\Spec\,\O_{\widebar{C}}(V)} \arrow[l] \\
{\Spec\,\O_{C'}(U)} \arrow[u] & {\Spec\,\O_{C'}(V)} \arrow[u] \arrow[l]
\end{tikzcd}
    \end{center}
    The left vertical map is finite by Lemma \ref{finite}, so in particular it is closed. The right vertical map is a bijection, and since the left vertical map is just adding one point to each space, it must also be a bijection. Thus we have a closed bijection, which is a homeomorphism.

    Lastly, to check that $(U,\O_{\bar{C}}|_U)$ is isomorphic to $\Spec\,\O_{\bar{C}}(U)$ we must check that the maps on stalks are isomorphisms. The only place this can fail is at the point $P$. One can check that this is an isomorphism by considering the exact sequence of sheaves
    \[
    0 \to \O_{\bar{C}} \to \O_{C'} \to M \to 0
    \]
    and noting that localization commutes with taking kernels, as localization is exact.
\end{proof}

\begin{proposition}\label{flat}
    The map $\widebar{\pi} : \widebar{C} \to S$ is flat.
\end{proposition}

\begin{proof}
    First, since $\pi : C \to S$ is flat and $\tau : C \to \widebar{C}$ is an isomorphism outside of the contracted subcurve, we see that we need only check flatness at the contracted point, i.e., if $P = \tau(E)$, we must show that $A \to \O_{\widebar{C},P}$ is flat. Using the local criterion for flatness over a local artinian ring, see \cite{stacks-project} Tag 051K, we must show that 
    \begin{enumerate}
        \item $\O_{\widebar{C},P}/\mm\O_{\widebar{C},P}$ is flat over $A/\mm$;
        \item $\text{Tor}_1^A(k, \O_{\widebar{C},P}) = 0$.
    \end{enumerate}
    The first condition is trivially satisfied, since $A/\mm \simeq k$ is a field. We now proceed with the proof of (ii). 

    Let us first introduce some notation. Since $A$ is a local artinian ring, its maximal ideal $\mm$ is nilpotent, say $\mm^{n+1} = 0$ for some $n \geq 0$. We write $A_i = A/\mm^{i+1}$ and $C_i = C \times_S \Spec(A_i)$ for $0 \leq i \leq n$, so $A_n = A$ and $C_n = C$. We proceed by induction on $i$. For $i = 0$, $A_0 = k$ is a field, so $\Tor_1^{A_0}(k,\O_{\widebar{C_0},P}) = 0$. Now assume that $\Tor_1^{A_i}(k,\O_{\widebar{C_i},P}) = 0$. We will show that $\Tor_1^{A_{i+1}}(k,\O_{\widebar{C_{i+1}},P}) = 0$. 

    We will make use of the spectral sequence (\cite{stacks-project} Tag 068F)
    \[
    \Tor_n^{A_i}(k,\Tor_m^{A_{i+1}}(A_i,\O_{\widebar{C_{i+1}},P})) \implies \Tor_{n+m}^{A_{i+1}}(k,\O_{\widebar{C_{i+1}},P}).
    \]
    We will show $\Tor_1^{A_i}(k,\Tor_0^{A_{i+1}}(A_i,\O_{\widebar{C_{i+1}},P})) = 0$ and $\Tor_0^{A_i}(k,\Tor_1^{A_{i+1}}(A_i,\O_{\widebar{C_{i+1}},P})) = 0$, which together imply that $\Tor_1^{A_{i+1}}(k,\O_{\widebar{C_{i+1}},P}) = 0$, as desired. First, using the induction hypothesis and the definition of $\Tor_0$, we have
    \[
    \Tor_1^{A_i}(k,\Tor_0^{A_{i+1}}(A_i,\O_{\widebar{C_{i+1}},P})) = \Tor_1^{A_i}(k,\O_{\widebar{C_i},P}) = 0.
    \]
    Next, let us denote $J = \ker(A_{i+1} \to A_i)$, so we have an exact sequence 
    \[
    0 \to J \otimes \O_{C_{i+1}} \to \O_{C_{i+1}} \to \O_{C_i} \to 0,
    \]
    since $C_{i+1}$ is an infinitesimal deformation of $C_i$. Pushing forward along the topological contraction $\tau'$, we get
    \[
    0 \to J \otimes \tau'_*\O_{C_{i+1}} \to \tau'_*\O_{C_{i+1}} \to \tau'_*\O_{C_i}.
    \]
    From Theorem \ref{main}, we see that this sequence gives rise to
    \[
    0 \to J \otimes \O_{\widebar{C_{i+1}}} \to \O_{\widebar{C_{i+1}}} \to \O_{\widebar{C_{i}}} \to 0.
    \]
    Taking stalks at $P$, we have the exact sequence of $A_{i+1}$-modules
    \begin{align}\label{O-seq}
    0 \to J \otimes \O_{\widebar{C_{i+1}},P} \to \O_{\widebar{C_{i+1}},P} \to \O_{\widebar{C_{i}},P} \to 0.
    \end{align}
    We note that this is the exact sequence that arises from tensoring
    \begin{align}\label{A-seq}
        0 \to J \to A_{i+1} \to A_i \to 0
    \end{align}
    with $\O_{\widebar{C_{i+1}},P}$. Now since \eqref{O-seq} and \eqref{A-seq} are exact, the long exact sequence from $\Tor_m^{A_{i+1}}(-,\O_{\widebar{C_{i+1}},P})$ applied to \eqref{A-seq} tells us that $\Tor_1^{A_{i+1}}(A_i,\O_{\widebar{C_{i+1}},P}) = 0$. This then implies that
    \[
    \Tor_0^{A_i}(k,\Tor_1^{A_{i+1}}(A_i,\O_{\widebar{C_{i+1}},P})) = \Tor_0^{A_i}(k,0) = 0,
    \]
    which concludes the proof.
\end{proof}

\begin{proposition}
    The map $\widebar{\pi} : \widebar{C} \to S$ is proper.
\end{proposition}

\begin{proof}
    Since $\pi$ is proper and $\tau$ is surjective, it suffices to show that $\widebar{\pi}$ is separated and locally of finite type (see \cite{stacks-project} Tag 03GN). First, since $C' \to \widebar{C}$ is finite and $C' \to S$ is locally of finite type, $\widebar{\pi} : \widebar{C} \to S$ is locally of finite type (see \cite{atiyahmacdonald} Prop. 7.8). Next, for separatedness we reduce to the case where $S = \Spec(k)$, since we can check separatedness on the reduction of a scheme. 

    Now we note that the map $\tau : C \to \widebar{C}$ can be factored as $C \to C' \to \widebar{C}$. The map $C \to C'$ is proper, as both $C$ and $C'$ are proper over $S$ (\cite{stacks-project} Tag 01W6), and $C' \to \widebar{C}$ is finite, so also proper. Therefore, $\tau : C \to \widebar{C}$ is proper. In particular, $\tau$ is surjective and universally closed, so $\widebar{\pi} : \widebar{C} \to S$ is separated by \cite{stacks-project} Tag 09MQ (statement (4)).
\end{proof}

\begin{proposition}\label{sing}
    The curve $\widebar{C_0}$ has a Gorenstein genus one singularity with $n$ branches at the point $\tau(E)$. 
\end{proposition}

\begin{proof}
    Let $P = \tau'(E) \in C'$. Since $C'$ consists of $n$ rational curves meeting transversally at the point $P$, we see that $\hat\O_{C',P} \simeq k[[x_1]] \times_k \cdots \times_k k[[x_n]]$ for some parameters $x_1,...,x_n$. 

    Let $f$ be a function on $C_0$ that descends to $\widebar{C_0}$, which we can view as an element of $\hat\O_{\widebar{C_0},P}$. This function must necessarily be constant on the interior of the aligned circle, since $E$ is proper and reduced. Thus, choosing local coordinates $x_i$, $y_i$ at each $p_i$ such that $x_i$ is the coordinate for $R_i$, we may write $f_{p_i} = c + c_1^ix_i + \cdots \in \hat\O_{C_0,p_i}$. 

    Now $\phi|_{R_i} \in H^0(R_i, \omega_{R_i}(2p_i) \otimes \pi^*\O_k(-\delta))$, so we can express $\phi_{p_i}|_{R_i}$ in these coordinates as 
    \[
    \phi_{p_i}|_{R_i} = [t](\gamma_{-2}^ix_i^{-2} + \gamma_0^i + \gamma_1^ix_i + \cdots)\,dx_i.
    \] 
    Note that there is no $x_i^{-1}$ term as the total residue of $\phi|_{R_i}$ must be 0, and $\gamma_{-2}^i \neq 0$, since $\phi|_{R_i}$ has a pole of order two at $p_i$. Therefore, the residue condition \eqref{res_cond} tells us that 
    \begin{align}\label{zero-sum}
         \sum_{p_i} \gamma_{-2}^ic_1^i = 0.
    \end{align}

   Now we send such an $f$ to $\hat\O_{C',P}$ via the inclusion $\hat\O_{\widebar{C_0},P} \to \hat\O_{C',P}$ by sending $f$ to $(f_{p_1},...,f_{p_n}) \in k[[x_1]] \times_k \cdots \times_k k[[x_n]]$. As we have just seen, $f$ descending to a function on $\widebar{C_0}$ is equivalent to \eqref{zero-sum} being satisfied. This condition cuts out the subring of $k[[x_1]] \times_k \cdots \times_k k[[x_n]]$ defining a Gorenstein genus one singularity with $n$ branches (see the appendix of \cite{smyth_mstable}), which proves the statement.
\end{proof}

